window.STEPS=Object.assign(window.STEPS||{},{"ns-030b64d4c740":{"길":"무게중심은 좌표의 평균, 이등분선은 대변을 두 변의 비로 내분한다","단계":[{"제목":"무게중심 G 와 15(a+b) 구하기","힌트":"세 꼭짓점의 $x$좌표의 평균과 $y$좌표의 평균은?","식":["$a=\\dfrac{2-2+8}{3}=\\dfrac{8}{3},\\ b=\\dfrac{3-1-3}{3}=-\\dfrac{1}{3}$","$15(a+b)=15\\times\\dfrac{7}{3}=35$"],"설명":"삼각형의 무게중심은 세 꼭짓점의 $x$좌표끼리, $y$좌표끼리 평균을 낸 점이다.","확인":"35","스킬":"S7"},{"제목":"두 변 AB, AC 의 길이의 비 구하기","힌트":"두 점 사이의 거리 공식으로 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AC}}$ 를 구하면?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{4^{2}+4^{2}}=4\\sqrt{2}$","$\\overline{\\mathrm{AC}}=\\sqrt{6^{2}+6^{2}}=6\\sqrt{2}$","$\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=2:3$"],"설명":"$\\mathrm{A}(2,\\ 3)$ 에서 $\\mathrm{B}$ 까지는 가로, 세로로 각각 $4$, $\\mathrm{C}$ 까지는 각각 $6$ 만큼 떨어져 있어 길이의 비가 간단히 나온다.","확인":null,"스킬":"S7"},{"제목":"이등분선이 BC 를 나누는 비 정하기","고비":true,"힌트":"$\\angle\\mathrm{A}$ 의 이등분선은 대변 $\\overline{\\mathrm{BC}}$ 를 어떤 비로 나눌까?","식":["$\\overline{\\mathrm{BD}}:\\overline{\\mathrm{DC}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=2:3$","$\\mathrm{D}$ 는 $\\overline{\\mathrm{BC}}$ 를 $2:3$ 으로 내분하는 점"],"설명":"각의 이등분선의 정리에 따라 $\\overline{\\mathrm{BD}}:\\overline{\\mathrm{DC}}$ 는 두 변의 길이의 비 $\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}$ 와 같다. 비를 잘못 뒤집지 않도록 $\\mathrm{B}$ 쪽이 $2$ 임에 주의한다.","확인":null,"스킬":"S7"},{"제목":"D 의 좌표와 15(c+d) 구하기","힌트":"$\\mathrm{B}$ 에서 $2$, $\\mathrm{C}$ 에서 $3$ 의 비로 내분하는 점의 좌표는?","식":["$c=\\dfrac{2\\times8+3\\times(-2)}{5}=2$","$d=\\dfrac{2\\times(-3)+3\\times(-1)}{5}=-\\dfrac{9}{5}$","$15(c+d)=15\\times\\dfrac{1}{5}=3$"],"설명":"$\\mathrm{B}$ 쪽 길이가 $2$ 이므로 $\\mathrm{C}$ 의 좌표에 $2$, $\\mathrm{B}$ 의 좌표에 $3$ 을 곱한다.","확인":null,"스킬":"S7"}]},"ns-07708d407a8c":{"길":"내분점의 y좌표와 외분점의 x좌표를 각각 0 으로 놓아 a, b 를 정한다","단계":[{"제목":"내분점 조건으로 b 구하기","힌트":"$x$축 위의 점은 $y$좌표가 얼마일까?","식":["$\\dfrac{3\\times b+1\\times5}{3+1}=0$","$b=-\\dfrac{5}{3}$"],"설명":"선분 $\\mathrm{AB}$ 를 $3:1$ 로 내분하는 점의 $y$좌표가 $0$ 이어야 한다.","확인":"-5/3","스킬":"S4"},{"제목":"외분점 조건으로 a 구하기","고비":true,"힌트":"선분 $\\mathrm{BA}$ 를 외분하므로 $\\mathrm{A}$ 의 좌표에는 어느 수를 곱할까?","식":["$\\dfrac{5\\times1-2\\times a}{5-2}=0$","$a=\\dfrac{5}{2}$"],"설명":"$\\mathrm{B}$ 에서 $\\mathrm{A}$ 쪽으로 보는 외분점이므로 $\\mathrm{A}$ 의 좌표에 $5$, $\\mathrm{B}$ 의 좌표에 $2$ 를 곱하고 뺀다. 이 점이 $y$축 위이므로 $x$좌표가 $0$ 이다.","확인":"5/2","스킬":"S4"},{"제목":"a + b 구하기","힌트":"구한 $a$, $b$ 를 더하면?","식":["$a+b=\\dfrac{5}{2}-\\dfrac{5}{3}=\\dfrac{5}{6}$"],"설명":"분모를 $6$ 으로 통분해 계산한다.","확인":"5/6","스킬":"S4"}]},"ns-09d68b1f5254":{"길":"이등분선 정리와 빗변 중점의 성질로 k 의 방정식을 세운다","단계":[{"제목":"이등분선 정리로 BD 나타내기","힌트":"$\\angle\\mathrm{A}$ 의 이등분선은 $\\overline{\\mathrm{BC}}$ 를 어떤 비로 나눌까?","식":["$\\overline{\\mathrm{BC}}=a$ 로 두면 $\\overline{\\mathrm{AB}}=6,\\ \\overline{\\mathrm{AC}}=k$","$\\overline{\\mathrm{BD}}:\\overline{\\mathrm{DC}}=6:k$","$\\overline{\\mathrm{BD}}=\\dfrac{6a}{k+6}$"],"설명":"각의 이등분선의 정리에 따라 $\\overline{\\mathrm{BD}}:\\overline{\\mathrm{DC}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}$ 이다. $\\overline{\\mathrm{BC}}$ 전체를 $6:k$ 로 나누므로 $\\overline{\\mathrm{BD}}$ 는 전체의 $\\frac{6}{k+6}$ 이다.","확인":null,"스킬":"S7"},{"제목":"AM, MD 를 a 로 나타내기","힌트":"직각삼각형에서 빗변의 중점 $\\mathrm{M}$ 은 세 꼭짓점과 어떤 관계일까?","식":["$\\overline{\\mathrm{AM}}=\\overline{\\mathrm{BM}}=\\dfrac{a}{2}$","$\\overline{\\mathrm{MD}}=\\left|\\dfrac{6a}{k+6}-\\dfrac{a}{2}\\right|$"],"설명":"$\\angle\\mathrm{A}=90^{\\circ}$ 이므로 빗변 $\\overline{\\mathrm{BC}}$ 의 중점 $\\mathrm{M}$ 은 외심이고 $\\overline{\\mathrm{AM}}=\\overline{\\mathrm{BM}}$ 이다. $\\overline{\\mathrm{MD}}$ 는 $\\overline{\\mathrm{BM}}$ 과 $\\overline{\\mathrm{BD}}$ 의 차이며, 등식에서는 제곱하므로 순서는 상관없다.","확인":null,"스킬":"S7"},{"제목":"등식에 대입해 k 의 방정식 만들기","고비":true,"힌트":"$\\overline{\\mathrm{AB}}^{2}+\\overline{\\mathrm{AC}}^{2}$ 은 피타고라스 정리로 $a$ 에 대한 어떤 식일까?","식":["$\\overline{\\mathrm{AB}}^{2}+\\overline{\\mathrm{AC}}^{2}=a^{2}$","$a^{2}=\\dfrac{a^{2}}{2}+8\\left(\\dfrac{6a}{k+6}-\\dfrac{a}{2}\\right)^{2}=\\dfrac{a^{2}}{2}+\\dfrac{2a^{2}(k-6)^{2}}{(k+6)^{2}}$","$(k+6)^{2}=4(k-6)^{2}$"],"설명":"$2\\overline{\\mathrm{AM}}^{2}=\\frac{a^{2}}{2}$ 이고 괄호 안을 통분하면 $\\frac{6-k}{2(k+6)}a$ 이다. 양변을 $a^{2}$ 으로 나누면 $a$ 가 사라지고 $k$ 만 남는다.","확인":null,"스킬":"S1"},{"제목":"k 값의 합 구하기","힌트":"$(k+6)^{2}=4(k-6)^{2}$ 을 정리하면 어떤 이차방정식일까?","식":["$k^{2}-20k+36=0$","$k=2,\\ 18$","$k$ 값의 합 $=20$"],"설명":"전개해 정리하면 $k^{2}-20k+36=0$ 이다. 두 근이 모두 양수이므로 문제의 조건에 맞고, 근과 계수의 관계로 합은 $20$ 이다.","확인":"20","스킬":"S7"}]},"ns-0a35355da137":{"길":"P(0, t) 로 두고 거리의 제곱합을 t 의 이차식으로 정리한다","단계":[{"제목":"P(0, t) 로 두고 거리의 제곱 구하기","힌트":"$y$축 위의 점은 $x$좌표가 얼마일까?","식":["$\\overline{\\mathrm{AP}}^{2}=1^{2}+(t-2)^{2}=t^{2}-4t+5$","$\\overline{\\mathrm{BP}}^{2}=3^{2}+(t-4)^{2}=t^{2}-8t+25$"],"설명":"$\\mathrm{P}(0,\\ t)$ 로 두면 $x$좌표의 차는 각각 $1$, $3$ 이고 $y$좌표의 차는 $t-2$, $t-4$ 이다.","확인":null,"스킬":"A6"},{"제목":"합을 t 의 이차식으로 정리하기","힌트":"두 식을 더해 $t$ 의 차수별로 모으면?","식":["$\\overline{\\mathrm{AP}}^{2}+\\overline{\\mathrm{BP}}^{2}=2t^{2}-12t+30$"],"설명":"$t^{2}$ 항은 $2t^{2}$, $t$ 항은 $-12t$, 상수항은 $30$ 이다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식으로 최솟값 구하기","고비":true,"힌트":"$2t^{2}-12t+30$ 을 $2(t-\\square)^{2}+\\triangle$ 꼴로 바꾸면?","식":["$2t^{2}-12t+30=2(t-3)^{2}+12$","$t=3$ 일 때 최솟값 $12$"],"설명":"$2(t^{2}-6t)+30$ 에서 $t^{2}-6t$ 를 $(t-3)^{2}-9$ 로 고치면 상수항이 $12$ 가 된다. 제곱 항이 $0$ 일 때 최소이다.","확인":"12","스킬":"A6"}]},"ns-0b0a58aa1610":{"길":"거리 공식에 넣어 k² 을 구하고 양수 조건으로 k 를 정한다","단계":[{"제목":"거리 공식으로 k² 구하기","힌트":"두 점 사이의 거리를 $x$좌표의 차와 $y$좌표의 차로 나타내면?","식":["$\\sqrt{(3+1)^{2}+(2k-k)^{2}}=5$","$16+k^{2}=25$","$k^{2}=9$"],"설명":"$x$좌표의 차는 $3-(-1)=4$, $y$좌표의 차는 $2k-k=k$ 이다. 양변을 제곱해 근호를 없앤다.","확인":"9","스킬":"S3"},{"제목":"양수 조건으로 k 정하기","고비":true,"힌트":"$k^{2}=9$ 인 $k$ 중 문제의 조건에 맞는 값은?","식":["$k=\\pm3$","$k>0$ 이므로 $k=3$"],"설명":"$k^{2}=9$ 의 해는 $\\pm3$ 이고, 양수라는 조건이 음수 해를 걸러 낸다.","확인":"3","스킬":"S3"}]},"ns-0f8ab1ad51ae":{"길":"세 지점에서 같은 거리는 외심이므로 수직이등분선 두 개로 잡는다","단계":[{"제목":"좌표를 정하고 외심 조건 세우기","힌트":"$\\mathrm{A}$ 를 원점으로 하면 $\\mathrm{B}$, $\\mathrm{C}$ 의 좌표는?","식":["$\\mathrm{A}(0,\\ 0),\\ \\mathrm{B}(-4,\\ 0),\\ \\mathrm{C}(2,\\ 2)$","세 점에서 같은 거리인 점 $=$ $\\triangle\\mathrm{ABC}$ 의 외심"],"설명":"서쪽은 $x$ 가 음수 방향, 북쪽은 $y$ 가 양수 방향이다. 세 꼭짓점에서 같은 거리에 있는 점은 외심이다.","확인":null,"스킬":"S4"},{"제목":"두 변의 수직이등분선 구하기","고비":true,"힌트":"$\\overline{\\mathrm{AC}}$ 의 중점과 기울기로 수직이등분선을 쓰면?","식":["$\\overline{\\mathrm{AB}}$ 의 수직이등분선: $x=-2$","$\\overline{\\mathrm{AC}}$ 의 수직이등분선: $y-1=-(x-1)$, 즉 $y=-x+2$"],"설명":"$\\overline{\\mathrm{AB}}$ 는 $x$축 위에 있으므로 수직이등분선은 중점 $(-2,\\ 0)$ 을 지나는 $x=-2$ 이다. $\\overline{\\mathrm{AC}}$ 의 중점은 $(1,\\ 1)$ 이고 기울기가 $1$ 이므로 수직인 직선의 기울기는 $-1$ 이다.","확인":null,"스킬":"S7"},{"제목":"외심에서 A 까지의 거리 구하기","힌트":"두 직선의 교점을 구하고 $\\mathrm{A}$ 까지의 거리를 재면?","식":["$x=-2$ 를 $y=-x+2$ 에 대입하면 $y=4$","외심 $(-2,\\ 4)$","$\\sqrt{(-2)^{2}+4^{2}}=\\sqrt{20}=2\\sqrt{5}$"],"설명":"외심은 두 수직이등분선의 교점이다. 단위는 $\\mathrm{km}$ 이다.","확인":null,"스킬":"S4"}]},"ns-16539f6a02ee":{"길":"x 와 y 를 따로 완전제곱식으로 만들어 최소가 되는 점을 찾는다","단계":[{"제목":"거리의 제곱합을 정리하기","힌트":"세 점까지 거리의 제곱을 쓰고 $x$ 끼리, $y$ 끼리 모으면?","식":["$(x-1)^{2}+(y-2)^{2}+(x-3)^{2}+y^{2}+(x-5)^{2}+(y-4)^{2}$","$=3x^{2}-18x+3y^{2}-12y+55$"],"설명":"$x$ 항은 $(x-1)^{2}$, $(x-3)^{2}$, $(x-5)^{2}$ 에서, $y$ 항은 $(y-2)^{2}$, $y^{2}$, $(y-4)^{2}$ 에서 나온다.","확인":null,"스킬":"A6"},{"제목":"x, y 를 각각 완전제곱식으로 바꾸기","고비":true,"힌트":"$3x^{2}-18x$ 와 $3y^{2}-12y$ 를 각각 제곱식 꼴로 바꾸면?","식":["$3x^{2}-18x=3(x-3)^{2}-27$","$3y^{2}-12y=3(y-2)^{2}-12$","$\\overline{\\mathrm{PA}}^{2}+\\overline{\\mathrm{PB}}^{2}+\\overline{\\mathrm{PC}}^{2}=3(x-3)^{2}+3(y-2)^{2}+16$"],"설명":"계수 $3$ 으로 묶은 뒤 일차항 계수의 절반을 제곱해 더하고 뺀다. 상수항은 $55-27-12=16$ 이다.","확인":null,"스킬":"A6"},{"제목":"최소가 되는 x, y 와 α + β 구하기","힌트":"제곱 항이 모두 $0$ 이 될 때 $x$, $y$ 는?","식":["$x=\\alpha=3,\\ y=\\beta=2$","$\\alpha+\\beta=5$"],"설명":"제곱 항은 $0$ 이상이므로 두 제곱 항이 모두 $0$ 일 때 합이 최소이다.","확인":"5","스킬":"S7"}]},"ns-1775536ae472":{"길":"대각선의 교점이 중점이므로 삼각형의 중선정리를 쓴다","단계":[{"제목":"대각선의 교점을 중점으로 보기","힌트":"평행사변형의 두 대각선은 서로를 어떻게 나눌까?","식":["교점 $\\mathrm{M}$ 은 $\\overline{\\mathrm{AC}}$, $\\overline{\\mathrm{BD}}$ 의 중점","$\\overline{\\mathrm{AM}}=\\dfrac{1}{2}\\overline{\\mathrm{AC}}=4,\\ \\overline{\\mathrm{BD}}=2\\overline{\\mathrm{BM}}$"],"설명":"평행사변형의 두 대각선은 서로를 이등분한다. 따라서 $\\overline{\\mathrm{BM}}$ 은 $\\triangle\\mathrm{ABC}$ 에서 $\\overline{\\mathrm{AC}}$ 의 중점으로 가는 중선이다.","확인":null,"스킬":"S4"},{"제목":"중선정리로 BM² 구하기","고비":true,"힌트":"$\\triangle\\mathrm{ABC}$ 에서 중선 $\\overline{\\mathrm{BM}}$ 에 중선정리를 쓰면?","식":["$\\overline{\\mathrm{AB}}^{2}+\\overline{\\mathrm{BC}}^{2}=2\\left(\\overline{\\mathrm{BM}}^{2}+\\overline{\\mathrm{AM}}^{2}\\right)$","$4^{2}+6^{2}=2\\left(\\overline{\\mathrm{BM}}^{2}+4^{2}\\right)$","$\\overline{\\mathrm{BM}}^{2}=10$"],"설명":"중선정리는 두 변의 제곱의 합이 중선의 제곱과 밑변 절반의 제곱의 합의 $2$ 배라는 내용이다. 양변을 $2$ 로 나누면 $\\overline{\\mathrm{BM}}^{2}+16=26$ 이다.","확인":"10","스킬":"S4"},{"제목":"BD 의 길이 구하기","힌트":"$\\overline{\\mathrm{BD}}$ 는 $\\overline{\\mathrm{BM}}$ 의 몇 배일까?","식":["$\\overline{\\mathrm{BM}}=\\sqrt{10}$","$\\overline{\\mathrm{BD}}=2\\overline{\\mathrm{BM}}=2\\sqrt{10}$"],"설명":"$\\mathrm{M}$ 이 $\\overline{\\mathrm{BD}}$ 의 중점이므로 $\\overline{\\mathrm{BD}}$ 는 $\\overline{\\mathrm{BM}}$ 의 $2$ 배이다.","확인":null,"스킬":"S4"}]},"ns-20349a1c3a8d":{"길":"B, C, A 의 좌표를 차례로 잡고 이등분선 정리로 D 를 내분점으로 구한다","단계":[{"제목":"OG 로 B, C 의 좌표 구하기","힌트":"$\\mathrm{G}(3,\\ 4)$ 에서 원점까지의 거리 $\\overline{\\mathrm{OG}}$ 는?","식":["$\\overline{\\mathrm{OG}}=\\sqrt{3^{2}+4^{2}}=5$","$\\overline{\\mathrm{OB}}=2\\overline{\\mathrm{OG}}=10$","$\\mathrm{B}(-10,\\ 0),\\ \\mathrm{C}(10,\\ 0)$"],"설명":"$\\mathrm{B}$ 는 $x$축의 음의 부분에 있고, $\\mathrm{O}$ 가 $\\overline{\\mathrm{BC}}$ 의 중점이므로 $\\mathrm{C}$ 는 $\\mathrm{B}$ 와 원점에 대칭인 점이다.","확인":"10","스킬":"S4"},{"제목":"무게중심 조건으로 A 의 좌표와 OA 구하기","힌트":"$\\mathrm{A}(p,\\ q)$ 로 두고 무게중심의 좌표가 세 꼭짓점 좌표의 평균임을 쓰면?","식":["$\\dfrac{-10+10+p}{3}=3,\\ \\dfrac{0+0+q}{3}=4$","$\\mathrm{A}(9,\\ 12)$","$\\overline{\\mathrm{OA}}=\\sqrt{9^{2}+12^{2}}=15$"],"설명":"$x$좌표의 평균이 $3$, $y$좌표의 평균이 $4$ 이므로 $p=9$, $q=12$ 이다. 제1사분면 조건과도 맞는다.","확인":"15","스킬":"S7"},{"제목":"이등분선 정리로 내분하는 비 정하기","고비":true,"힌트":"$\\overline{\\mathrm{OD}}$ 가 $\\angle\\mathrm{AOC}$ 를 이등분하면 $\\overline{\\mathrm{AC}}$ 는 어떤 비로 나뉠까?","식":["$\\overline{\\mathrm{AD}}:\\overline{\\mathrm{DC}}=\\overline{\\mathrm{OA}}:\\overline{\\mathrm{OC}}=15:10=3:2$","$\\mathrm{D}$ 는 $\\overline{\\mathrm{AC}}$ 를 $3:2$ 로 내분하는 점"],"설명":"$\\angle\\mathrm{AOD}=\\angle\\mathrm{COD}$ 이므로 $\\triangle\\mathrm{OAC}$ 에서 각의 이등분선의 정리를 쓴다. 대변이 두 변의 길이의 비로 나뉜다.","확인":null,"스킬":"S7"},{"제목":"D 의 좌표와 2a + b 구하기","힌트":"$\\mathrm{A}$ 에서 $\\mathrm{C}$ 쪽으로 $3:2$ 로 내분하는 점의 좌표는?","식":["$\\mathrm{D}\\left(\\dfrac{2\\times9+3\\times10}{5},\\ \\dfrac{2\\times12+3\\times0}{5}\\right)=\\left(\\dfrac{48}{5},\\ \\dfrac{24}{5}\\right)$","$2a+b=\\dfrac{96}{5}+\\dfrac{24}{5}=24$"],"설명":"$\\mathrm{A}$ 쪽 비가 $3$ 이므로 $\\mathrm{C}$ 의 좌표에 $3$, $\\mathrm{A}$ 의 좌표에 $2$ 를 곱해 더하고 $5$ 로 나눈다.","확인":"24","스킬":"S4"}]},"ns-39684cc33938":{"길":"내분점과 외분점의 식을 같게 놓고 보기마다 값을 확인하거나 반례를 찾는다","단계":[{"제목":"내분점과 외분점의 식 세우기","힌트":"$\\mathrm{P}$ 가 $\\overline{\\mathrm{AC}}$ 의 내분점이면서 $\\overline{\\mathrm{BC}}$ 의 외분점일 때 $p$ 를 두 가지로 쓰면?","식":["$p=\\dfrac{na+mc}{m+n}$","$p=\\dfrac{mc-nb}{m-n}$"],"설명":"수직선 위에서 $m:n$ 으로 내분하는 점은 $\\frac{na+mc}{m+n}$, 외분하는 점은 $\\frac{mc-nb}{m-n}$ 이다. 같은 점 $\\mathrm{P}$ 이므로 두 식이 같다.","확인":null,"스킬":"S4"},{"제목":"p 를 a, b 로 정리하기 (ㄱ 확인)","고비":true,"힌트":"두 식에서 $mc$ 를 각각 $p$ 로 나타내 같다고 놓으면?","식":["$mc=(m+n)p-na=(m-n)p+nb$","$2np=n(a+b)$","$p=\\dfrac{a+b}{2}$"],"설명":"$mc$ 를 두 식에서 따로 구해 같게 놓으면 $m$ 이 사라지고 $p$ 만 남는다. $n>0$ 이므로 양변을 $n$ 으로 나눌 수 있어 ㄱ 은 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 의 p 와 c 확인하기","힌트":"$a=1,\\ b=7$ 일 때 $p$ 의 값과, $m=3,\\ n=2$ 일 때 $c$ 를 구하면?","식":["$p=\\dfrac{1+7}{2}=4$","$\\dfrac{2\\times1+3c}{5}=4$","$c=6$"],"설명":"ㄱ 에서 $p=\\frac{a+b}{2}$ 이므로 $p=4$ 이고, 이를 내분점 식에 넣어 $c$ 를 구하면 ㄴ 이 주장하는 값과 같아 ㄴ 은 참이다.","확인":"4","스킬":"S4"},{"제목":"ㄷ 의 반례 찾고 답 고르기","힌트":"$m<n$ 인 값을 하나 잡아 $a<p<c<b$ 가 항상 성립하는지 확인하면?","식":["$a=1,\\ b=7,\\ m=2,\\ n=3$ 이면 $p=4$","$\\dfrac{3\\times1+2c}{5}=4\\ \\to\\ c=\\dfrac{17}{2}>b$","ㄷ 은 거짓, 옳은 것은 ㄱ, ㄴ"],"설명":"$c=\\frac{17}{2}$ 는 $b=7$ 보다 커서 $c<b$ 가 깨진다. 반례가 하나 있으므로 ㄷ 은 거짓이고 옳은 것은 ㄱ, ㄴ 이다.","확인":null,"스킬":"C3"}]},"ns-3b808f1517a6":{"길":"닮음비로 BP 의 길이를 BC 의 배수로 나타내 P 의 좌표를 구한다","단계":[{"제목":"AB, AC 의 길이로 BD 구하기","힌트":"두 점 사이의 거리 공식으로 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AC}}$ 를 구하면?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{5^{2}+12^{2}}=13$","$\\overline{\\mathrm{AC}}=\\sqrt{4^{2}+3^{2}}=5$","$\\overline{\\mathrm{BD}}=13-5=8$"],"설명":"$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{AC}}=5$ 이고 $\\mathrm{D}$ 는 $\\overline{\\mathrm{AB}}$ 위의 점이므로 $\\overline{\\mathrm{BD}}=\\overline{\\mathrm{AB}}-\\overline{\\mathrm{AD}}$ 이다.","확인":"8","스킬":"S1"},{"제목":"평행선으로 BC : BP 구하기","고비":true,"힌트":"$\\overline{\\mathrm{DC}}\\parallel\\overline{\\mathrm{AP}}$ 이면 $\\triangle\\mathrm{BDC}$ 와 닮은 삼각형은?","식":["$\\triangle\\mathrm{BDC}\\sim\\triangle\\mathrm{BAP}$","$\\overline{\\mathrm{BD}}:\\overline{\\mathrm{BA}}=\\overline{\\mathrm{BC}}:\\overline{\\mathrm{BP}}=8:13$"],"설명":"평행선 때문에 두 삼각형은 닮음이고, $\\mathrm{B}$ 에서 잰 대응하는 변의 비가 같다. $\\overline{\\mathrm{BP}}$ 는 $\\overline{\\mathrm{BC}}$ 보다 길어 $\\mathrm{P}$ 가 연장선 위에 있다.","확인":null,"스킬":"S1"},{"제목":"P 의 좌표 구하기","힌트":"$\\mathrm{B}$ 에서 $\\mathrm{C}$ 까지의 이동량의 $\\dfrac{13}{8}$ 배만큼 가면?","식":["$\\mathrm{B}$ 에서 $\\mathrm{C}$ 까지: $x$ 로 $9$, $y$ 로 $9$ 이동","$\\mathrm{P}=\\left(4+\\dfrac{13}{8}\\times9,\\ 0+\\dfrac{13}{8}\\times9\\right)=\\left(\\dfrac{149}{8},\\ \\dfrac{117}{8}\\right)$"],"설명":"$\\overline{\\mathrm{BP}}=\\frac{13}{8}\\overline{\\mathrm{BC}}$ 이고 $\\mathrm{P}$ 는 $\\mathrm{B}$ 에서 $\\mathrm{C}$ 방향의 연장선 위에 있으므로 이동량도 $\\frac{13}{8}$ 배이다.","확인":null,"스킬":"S1"}]},"ns-46010d104e07":{"길":"무게중심은 좌표의 평균, 두 점의 기울기로 직선을 쓰고 y절편을 읽는다","단계":[{"제목":"두 삼각형의 무게중심 구하기","힌트":"그림에서 꼭짓점의 좌표를 읽고 각각 평균을 내면?","식":["$\\triangle\\mathrm{ABC}$: $\\left(\\dfrac{-5-1-3}{3},\\ \\dfrac{-5-5-2}{3}\\right)=(-3,\\ -4)$","$\\triangle\\mathrm{DEF}$: $\\left(\\dfrac{2+6+4}{3},\\ \\dfrac{2+3+7}{3}\\right)=(4,\\ 4)$"],"설명":"무게중심은 세 꼭짓점의 $x$좌표끼리, $y$좌표끼리 평균을 낸 점이다. 그림의 좌표는 $\\mathrm{A}(-5,\\ -5)$, $\\mathrm{B}(-1,\\ -5)$, $\\mathrm{C}(-3,\\ -2)$, $\\mathrm{D}(2,\\ 2)$, $\\mathrm{E}(6,\\ 3)$, $\\mathrm{F}(4,\\ 7)$ 이다.","확인":null,"스킬":"S7"},{"제목":"두 무게중심을 지나는 직선의 기울기 구하기","힌트":"$(-3,\\ -4)$ 와 $(4,\\ 4)$ 사이에서 $y$ 의 증가량과 $x$ 의 증가량은?","식":["$\\dfrac{4-(-4)}{4-(-3)}=\\dfrac{8}{7}$"],"설명":"기울기는 $y$ 의 증가량을 $x$ 의 증가량으로 나눈 값이다.","확인":"8/7","스킬":"S7"},{"제목":"직선의 식과 y절편 구하기","고비":true,"힌트":"점 $(4,\\ 4)$ 를 지나고 기울기가 $\\dfrac{8}{7}$ 인 직선에서 $x=0$ 일 때 $y$ 는?","식":["$y-4=\\dfrac{8}{7}(x-4)$","$y=\\dfrac{8}{7}x-\\dfrac{4}{7}$","$y$절편 $=-\\dfrac{4}{7}$"],"설명":"$4-\\frac{32}{7}=-\\frac{4}{7}$ 이다. $x=0$ 을 대입한 $y$ 값이 $y$절편이다.","확인":"-4/7","스킬":"S7"}]},"ns-4d3b8dec97fc":{"길":"CG 가 AB 의 중점 M 까지 거리의 절반임을 보고 수직이등분선 위의 C 를 찾는다","단계":[{"제목":"CG 를 CM 으로 나타내기","고비":true,"힌트":"$\\triangle\\mathrm{CPQ}$ 는 $\\triangle\\mathrm{CAB}$ 와 어떤 관계이고 닮음비는?","식":["$\\triangle\\mathrm{CPQ}\\sim\\triangle\\mathrm{CAB}$ (닮음비 $3:4$)","$\\overline{\\mathrm{CG}}=\\dfrac{2}{3}\\times\\dfrac{3}{4}\\overline{\\mathrm{CM}}=\\dfrac{1}{2}\\overline{\\mathrm{CM}}$","$\\overline{\\mathrm{CM}}=2\\sqrt{10}$"],"설명":"$\\overline{\\mathrm{CP}}:\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CQ}}:\\overline{\\mathrm{CB}}=3:4$ 이므로 두 삼각형은 닮음이다. $\\mathrm{M}$ 이 $\\overline{\\mathrm{AB}}$ 의 중점이면 $\\overline{\\mathrm{CM}}$ 은 $\\triangle\\mathrm{CAB}$ 의 중선이고, 무게중심 $\\mathrm{G}$ 는 $\\triangle\\mathrm{CPQ}$ 의 중선을 $2:1$ 로 나눈다.","확인":null,"스킬":"S1"},{"제목":"M 의 좌표와 C 가 놓인 직선 구하기","힌트":"$\\overline{\\mathrm{AC}}=\\overline{\\mathrm{BC}}$ 이면 $\\mathrm{C}$ 는 $\\overline{\\mathrm{AB}}$ 의 어떤 직선 위에 있을까?","식":["$\\mathrm{M}(6,\\ 2)$","$\\overline{\\mathrm{AB}}$ 의 기울기 $-\\dfrac{1}{3}$ 이므로 수직이등분선은 $y-2=3(x-6)$"],"설명":"두 점에서 같은 거리에 있는 점은 수직이등분선 위에 있다. $\\overline{\\mathrm{AB}}$ 의 기울기의 역수에 음의 부호를 붙인 $3$ 이 수직이등분선의 기울기이다.","확인":null,"스킬":"S7"},{"제목":"C 의 좌표 후보 구하기","힌트":"수직이등분선 위의 점을 $t$ 로 나타내고 $\\overline{\\mathrm{CM}}=2\\sqrt{10}$ 을 쓰면?","식":["$\\mathrm{C}(6+t,\\ 2+3t)$","$\\overline{\\mathrm{CM}}^{2}=t^{2}+(3t)^{2}=10t^{2}=40$","$t=\\pm2$"],"설명":"$\\mathrm{M}$ 에서 $x$ 로 $t$ 만큼 가면 직선을 따라 $y$ 는 $3t$ 만큼 변한다. 거리의 제곱이 $40$ 이다.","확인":null,"스킬":"S7"},{"제목":"제1사분면 조건으로 a + b 구하기","힌트":"$t=2$, $t=-2$ 일 때 $\\mathrm{C}$ 의 좌표 중 제1사분면의 점은?","식":["$t=2$: $\\mathrm{C}(8,\\ 8)$","$t=-2$: $\\mathrm{C}(4,\\ -4)$ 는 제4사분면이므로 제외","$a+b=16$"],"설명":"문제에서 $\\mathrm{C}$ 는 제1사분면 위의 점이므로 $y$좌표가 음수인 후보는 버린다.","확인":"16","스킬":"S7"}]},"ns-4d56c8eb37ef":{"길":"무게중심이 중선을 2:1 로 나누므로 높이를 먼저 구하고 변과 넓이를 구한다","단계":[{"제목":"정삼각형의 높이 구하기","고비":true,"힌트":"무게중심은 중선을 꼭짓점 쪽부터 어떤 비로 나눌까?","식":["$\\overline{\\mathrm{OA}}=\\sqrt{4^{2}+3^{2}}=5$","높이 $=\\dfrac{3}{2}\\times\\overline{\\mathrm{OA}}=\\dfrac{15}{2}$"],"설명":"꼭짓점에서 무게중심까지가 중선의 $\\frac{2}{3}$ 이므로 중선 전체는 $\\overline{\\mathrm{OA}}$ 의 $\\frac{3}{2}$ 배이다. 정삼각형은 중선이 높이이다.","확인":"15/2","스킬":"S7"},{"제목":"한 변의 길이 구하기","힌트":"정삼각형의 높이는 한 변의 길이 $a$ 의 몇 배일까?","식":["$\\dfrac{\\sqrt{3}}{2}a=\\dfrac{15}{2}$","$a=5\\sqrt{3}$"],"설명":"정삼각형의 높이는 한 변의 길이의 $\\frac{\\sqrt{3}}{2}$ 배이다. 양변에 $2$ 를 곱한 뒤 $\\sqrt{3}$ 으로 나눈다.","확인":null,"스킬":"S7"},{"제목":"정삼각형의 넓이 구하기","힌트":"밑변이 $5\\sqrt{3}$, 높이가 $\\dfrac{15}{2}$ 인 삼각형의 넓이는?","식":["$\\dfrac{1}{2}\\times5\\sqrt{3}\\times\\dfrac{15}{2}=\\dfrac{75\\sqrt{3}}{4}$"],"설명":"넓이는 밑변과 높이의 곱의 절반이다.","확인":null,"스킬":"S7"}]},"ns-4efbf38079ff":{"길":"내분점과 외분점을 구하고 원점이 낀 삼각형의 넓이 공식을 쓴다","단계":[{"제목":"1 : 2 내분점 구하기","힌트":"선분 $\\mathrm{AB}$ 를 $1:2$ 로 내분하는 점의 좌표는?","식":["$\\left(\\dfrac{1\\times4+2\\times(-1)}{3},\\ \\dfrac{1\\times0+2\\times3}{3}\\right)=\\left(\\dfrac{2}{3},\\ 2\\right)$"],"설명":"내분점은 $\\mathrm{B}$ 의 좌표에 $1$, $\\mathrm{A}$ 의 좌표에 $2$ 를 곱해 더하고 $3$ 으로 나눈다.","확인":null,"스킬":"G10"},{"제목":"1 : 2 외분점 구하기","고비":true,"힌트":"외분점은 분모가 $m-n$ 이다. 이 값은 얼마일까?","식":["$\\left(\\dfrac{1\\times4-2\\times(-1)}{1-2},\\ \\dfrac{1\\times0-2\\times3}{1-2}\\right)=(-6,\\ 6)$"],"설명":"$m=1,\\ n=2$ 이므로 분모가 $-1$ 이다. 분자의 부호와 분모의 부호를 함께 처리한다.","확인":null,"스킬":"G10"},{"제목":"원점이 낀 삼각형의 넓이 구하기","힌트":"원점과 두 점 $(x_{1},\\ y_{1})$, $(x_{2},\\ y_{2})$ 로 이루어진 삼각형의 넓이 공식은?","식":["$S=\\dfrac{1}{2}\\left|\\dfrac{2}{3}\\times6-(-6)\\times2\\right|$","$S=\\dfrac{1}{2}(4+12)=8$"],"설명":"원점과 두 점이 이루는 삼각형의 넓이는 $\\frac{1}{2}|x_{1}y_{2}-x_{2}y_{1}|$ 이다. 내분점이 $(x_{1},\\ y_{1})$, 외분점이 $(x_{2},\\ y_{2})$ 이다.","확인":"8","스킬":"G10"}]},"ns-6afc233a7ee8":{"길":"m>n, m<n 으로 나누어 외분점의 부호 조건에서 m/n 의 범위를 구한다","단계":[{"제목":"외분점의 좌표 세우기","힌트":"$\\mathrm{A}(1,\\ -5)$, $\\mathrm{B}(4,\\ -1)$ 을 $m:n$ 으로 외분하는 점의 좌표는?","식":["$\\mathrm{P}\\left(\\dfrac{4m-n}{m-n},\\ \\dfrac{-m+5n}{m-n}\\right)$"],"설명":"$\\mathrm{B}$ 의 좌표에 $m$, $\\mathrm{A}$ 의 좌표에 $n$ 을 곱해 빼고 $m-n$ 으로 나눈다.","확인":null,"스킬":"C2"},{"제목":"m > n 일 때의 조건 구하기","고비":true,"힌트":"분모가 양수이면 두 분자는 어떤 부호여야 할까?","식":["$4m-n>0\\ \\to\\ \\dfrac{m}{n}>\\dfrac{1}{4}$","$-m+5n>0\\ \\to\\ \\dfrac{m}{n}<5$","$m>n$ 이므로 $1<\\dfrac{m}{n}<5$"],"설명":"제1사분면은 $x$좌표와 $y$좌표가 모두 양수인 영역이다. 분모 $m-n$ 이 양수이므로 두 분자가 모두 양수여야 한다.","확인":null,"스킬":"C2"},{"제목":"m < n 일 때의 조건 구하기","힌트":"분모가 음수이면 두 분자는 어떤 부호여야 할까?","식":["$4m-n<0\\ \\to\\ \\dfrac{m}{n}<\\dfrac{1}{4}$","$-m+5n<0\\ \\to\\ \\dfrac{m}{n}>5$","두 조건을 동시에 만족하는 $\\dfrac{m}{n}$ 은 없다"],"설명":"분모가 음수이므로 두 분자가 모두 음수여야 한다. $\\frac{m}{n}$ 이 $\\frac{1}{4}$ 보다 작으면서 $5$ 보다 클 수는 없다.","확인":null,"스킬":"C2"},{"제목":"b − a 의 최댓값 구하기","힌트":"제1사분면이 되는 $\\dfrac{m}{n}$ 의 범위의 폭은?","식":["$1<\\dfrac{m}{n}<5$","$b-a\\le5-1=4$"],"설명":"$a<\\frac{m}{n}<b$ 가 이 범위 안에 들어갈 때 $b-a$ 가 가장 크려면 $a=1,\\ b=5$ 이다.","확인":"4","스킬":"C2"}]},"ns-789db9376841":{"길":"내분점 좌표를 t로 쓰고 제4사분면의 부호 조건을 건다","단계":[{"제목":"내분점의 좌표를 t의 식으로 표현","힌트":"$t:(1-t)$로 내분하는 점의 $x$좌표와 $y$좌표는 각각 어떤 식인가?","식":["$\\left(\\frac{5t+3(1-t)}{t+(1-t)},\\ \\frac{t+(-5)(1-t)}{t+(1-t)}\\right)$","$(2t+3,\\ 6t-5)$"],"설명":"점 $\\mathrm{A}$에는 $(1-t)$를, 점 $\\mathrm{B}$에는 $t$를 곱해 더하고 비의 합 $t+(1-t)=1$로 나눈다. 따라서 내분점은 $(2t+3,\\ 6t-5)$이다.","확인":null,"스킬":"C7"},{"제목":"제4사분면 조건에서 나오는 상한","힌트":"$y$좌표가 음수이려면 $t$는 어떤 값보다 작아야 하는가?","식":["$2t+3>0 \\Rightarrow t>-\\frac{3}{2}$","$6t-5<0 \\Rightarrow t<\\frac{5}{6}$"],"설명":"제4사분면의 점은 $x$좌표가 양수, $y$좌표가 음수이다. 두 부등식을 각각 풀면 $t>-\\frac{3}{2}$, $t<\\frac{5}{6}$이다.","확인":"5/6","스킬":"C7","고비":true},{"제목":"주어진 범위와의 공통 범위","힌트":"$-\\frac{3}{2}<t<\\frac{5}{6}$과 $0<t<1$이 겹치는 구간은 어디인가?","식":["$0<t<\\frac{5}{6}$"],"설명":"$t$는 $0<t<1$이어야 하므로 하한은 $-\\frac{3}{2}$ 대신 $0$이 된다. 상한 $\\frac{5}{6}$은 $1$보다 작으므로 그대로이다.","확인":null,"스킬":"C7"}]},"ns-7b2c14a7f036":{"길":"R의 좌표를 p, q로 쓰고 q가 실수로 존재할 조건을 판별식으로 건다","단계":[{"제목":"점 P, Q의 좌표와 길이 조건","힌트":"$\\mathrm{P}(p,\\ p)$, $\\mathrm{Q}(q,\\ -q)$로 놓으면 $\\overline{\\mathrm{PQ}}^{\\,2}=6$은 어떤 식이 되는가?","식":["$\\mathrm{P}(p,\\ p),\\ \\mathrm{Q}(q,\\ -q)$","$(q-p)^2+(-q-p)^2=6$","$p^2+q^2=3$"],"설명":"$\\mathrm{P}$는 직선 $y=x$ 위의 점, $\\mathrm{Q}$는 직선 $y=-x$ 위의 점이므로 위와 같이 놓는다. 두 점 사이의 거리 공식으로 $2p^2+2q^2=6$이 되어 $p^2+q^2=3$이다.","확인":"3","스킬":"S4"},{"제목":"R의 좌표로 p를 없애 q의 이차식 만들기","힌트":"$a=\\frac{2p+q}{3}$에서 $p$를 $a,\\ q$로 나타내 $p^2+q^2=3$에 넣으면 어떤 식이 되는가?","식":["$\\mathrm{R}\\left(\\frac{2p+q}{3},\\ \\frac{2p-q}{3}\\right),\\ p=\\frac{3a-q}{2}$","$\\left(\\frac{3a-q}{2}\\right)^2+q^2=3$","$5q^2-6aq+9a^2-12=0$"],"설명":"$\\mathrm{R}$은 $\\overline{\\mathrm{PQ}}$를 $1:2$로 내분하는 점이므로 $x$좌표는 $\\frac{2p+q}{3}$이다. 이를 $a$로 놓아 $p$를 $a$와 $q$로 나타내고 $p^2+q^2=3$에 대입한 뒤 양변에 $4$를 곱해 정리한다.","확인":null,"스킬":"A10"},{"제목":"q가 실수로 존재할 조건","힌트":"$q$가 실수이려면 판별식 $D\\ge 0$이어야 한다. 이를 정리하면 $a^2$의 상한은 얼마인가?","식":["$\\frac{D}{4}=(-3a)^2-5(9a^2-12)\\ge 0$","$-36a^2+60\\ge 0 \\Rightarrow a^2\\le\\frac{5}{3}$"],"설명":"점 $\\mathrm{R}$이 존재하려면 $q$가 실수여야 하므로 판별식 $D\\ge 0$이다. 계산하면 $60-36a^2\\ge 0$이고 $a^2\\le\\frac{5}{3}$이다.","확인":"5/3","스킬":"G2","고비":true},{"제목":"a의 최댓값 판단","힌트":"$a^2\\le\\frac{5}{3}$에서 $a$의 범위와 최댓값은 얼마인가?","식":["$-\\frac{\\sqrt{15}}{3}\\le a\\le\\frac{\\sqrt{15}}{3}$","$a$의 최댓값 $=\\frac{\\sqrt{15}}{3}$"],"설명":"$a^2\\le\\frac{5}{3}$에서 $|a|\\le\\sqrt{\\frac{5}{3}}=\\frac{\\sqrt{15}}{3}$이다. 따라서 $a$의 최댓값은 $\\frac{\\sqrt{15}}{3}$이다.","확인":null,"스킬":"G2"}]},"ns-7f8260cd0d88":{"길":"내분점 좌표를 t로 쓰고 두 좌표를 모두 양수로 둔다","단계":[{"제목":"내분점의 좌표를 t의 식으로 표현","힌트":"$t:(1-t)$로 내분하는 점의 $x$좌표와 $y$좌표는 각각 어떤 식인가?","식":["$\\left(\\frac{3t+(-2)(1-t)}{t+(1-t)},\\ \\frac{-2t+5(1-t)}{t+(1-t)}\\right)$","$(5t-2,\\ 5-7t)$"],"설명":"점 $A$에는 $(1-t)$를, 점 $B$에는 $t$를 곱해 더하고 비의 합 $t+(1-t)=1$로 나눈다. 따라서 내분점은 $(5t-2,\\ 5-7t)$이다.","확인":null,"스킬":"C7"},{"제목":"제1사분면 조건에서 나오는 상한","힌트":"$y$좌표가 양수이려면 $t$는 어떤 값보다 작아야 하는가?","식":["$5t-2>0 \\Rightarrow t>\\frac{2}{5}$","$5-7t>0 \\Rightarrow t<\\frac{5}{7}$"],"설명":"제1사분면의 점은 $x$좌표와 $y$좌표가 모두 양수이다. 두 부등식을 각각 풀면 $t>\\frac{2}{5}$, $t<\\frac{5}{7}$이다.","확인":"5/7","스킬":"C7","고비":true},{"제목":"두 부등식의 공통 범위","힌트":"$t>\\frac{2}{5}$와 $t<\\frac{5}{7}$을 동시에 만족하는 범위는 어디인가?","식":["$\\frac{2}{5}<t<\\frac{5}{7}$"],"설명":"이 구간은 $0<t<1$ 안에 들어 있으므로 조건 $0<t<1$도 만족한다.","확인":null,"스킬":"C7"}]},"ns-80536d94d115":{"길":"세 중점으로 꼭짓점 B를 잡고 수직·거리 조건을 연립한다","단계":[{"제목":"세 중점으로 꼭짓점 B 구하기","힌트":"$\\mathrm{P},\\ \\mathrm{Q},\\ \\mathrm{R}$를 꼭짓점의 좌표로 쓰고 $\\mathrm{P}+\\mathrm{Q}-\\mathrm{R}$를 계산하면 무엇이 남는가?","식":["$\\mathrm{P}+\\mathrm{Q}-\\mathrm{R}=\\frac{\\mathrm{A}+\\mathrm{B}}{2}+\\frac{\\mathrm{B}+\\mathrm{C}}{2}-\\frac{\\mathrm{C}+\\mathrm{A}}{2}=\\mathrm{B}$","$\\mathrm{B}=(2+4-a,\\ 1-1-b)=(6-a,\\ -b)$"],"설명":"세 중점을 $\\mathrm{P}=\\frac{\\mathrm{A}+\\mathrm{B}}{2}$ 등으로 쓰고 좌표끼리 $\\mathrm{P}+\\mathrm{Q}-\\mathrm{R}$를 계산하면 $\\mathrm{B}$만 남는다. 따라서 $\\mathrm{B}(6-a,\\ -b)$이다.","확인":null,"스킬":"S4"},{"제목":"수직 조건으로 a, b의 관계 구하기","힌트":"직선 $\\mathrm{PQ}$의 기울기는 얼마이고, 수직인 직선 $\\mathrm{BR}$의 기울기는 얼마인가?","식":["$m_{\\mathrm{PQ}}=\\frac{-1-1}{4-2}=-1$","$m_{\\mathrm{BR}}=\\frac{b-(-b)}{a-(6-a)}=\\frac{b}{a-3}=1$","$b=a-3$"],"설명":"직선 $\\mathrm{PQ}$의 기울기가 $-1$이므로 수직인 직선 $\\mathrm{BR}$의 기울기는 $1$이다. $\\mathrm{B}(6-a,\\ -b)$, $\\mathrm{R}(a,\\ b)$를 지나는 직선의 기울기를 $1$로 놓으면 $b=a-3$이다.","확인":null,"스킬":"G9"},{"제목":"무게중심 G와 직선 PQ의 방정식","힌트":"$\\mathrm{G}$의 좌표와 직선 $\\mathrm{PQ}$의 방정식은 각각 무엇인가?","식":["$\\mathrm{G}=\\left(\\frac{2+4+a}{3},\\ \\frac{1-1+b}{3}\\right)=\\left(\\frac{a+6}{3},\\ \\frac{b}{3}\\right)$","$\\mathrm{PQ}:\\ y-1=-(x-2) \\Rightarrow x+y-3=0$"],"설명":"$\\mathrm{P}+\\mathrm{Q}+\\mathrm{R}=\\mathrm{A}+\\mathrm{B}+\\mathrm{C}$이므로 $\\triangle\\mathrm{ABC}$의 무게중심은 $\\mathrm{P},\\ \\mathrm{Q},\\ \\mathrm{R}$의 좌표 평균이다. 직선 $\\mathrm{PQ}$는 기울기가 $-1$이고 $\\mathrm{P}(2,\\ 1)$을 지난다.","확인":null,"스킬":"S7"},{"제목":"거리 조건으로 a 정하기","힌트":"점 $\\mathrm{G}$와 직선 $x+y-3=0$ 사이의 거리를 $2\\sqrt{2}$로 놓고 $b=a-3$을 넣으면 $a$는 얼마인가?","식":["$\\frac{|2a-6|}{3\\sqrt{2}}=2\\sqrt{2}$","$|2a-6|=12 \\Rightarrow a=9,\\ -3$","$a=9$"],"설명":"$\\frac{a+6}{3}+\\frac{b}{3}-3=\\frac{2a-6}{3}$이므로 거리는 $\\frac{|2a-6|}{3\\sqrt{2}}$이다. $a=-3$이면 $b=-6$이어서 $\\mathrm{G}(1,\\ -2)$가 제4사분면에 놓이므로, $\\mathrm{G}$가 제1사분면에 있는 $a=9$만 가능하다.","확인":"9","스킬":"C2","고비":true},{"제목":"2a+b의 값 계산","힌트":"$a=9$와 $b=a-3$을 이용해 $2a+b$를 구하면 얼마인가?","식":["$b=9-3=6$","$2a+b=18+6=24$"],"설명":"$b=a-3=6$이므로 $2a+b=24$이다. 이 값은 선지 ⑤와 같다.","확인":"24","스킬":"S4"}]},"ns-9436b288f593":{"길":"밑변의 비로 넓이를 s, k로 나타내 비례식을 세운다","단계":[{"제목":"점 M의 좌표와 직선 AM의 방정식","힌트":"$\\overline{\\mathrm{OB}}$를 $2:1$로 내분하는 점 $\\mathrm{M}$의 $x$좌표는 얼마인가?","식":["$\\mathrm{M}\\left(\\frac{2\\cdot 6+1\\cdot 0}{3},\\ 0\\right)=(4,\\ 0)$","$\\mathrm{AM}:\\ y=-6x+24$"],"설명":"$\\mathrm{M}$은 $x$축 위에 있고 $x$좌표는 $\\frac{12}{3}=4$이다. $\\mathrm{A}(3,\\ 6)$, $\\mathrm{M}(4,\\ 0)$을 지나는 직선의 기울기는 $-6$이므로 $y=-6x+24$이다.","확인":"4","스킬":"S4"},{"제목":"밑변의 비로 세 넓이를 s, k로 표현","힌트":"$\\triangle\\mathrm{OPM}:\\triangle\\mathrm{BPM}$은 어떤 비와 같고, $\\triangle\\mathrm{PBA}$는 넓이 조건으로 어떻게 나타나는가?","식":["$\\triangle\\mathrm{OPM}=4s,\\ \\triangle\\mathrm{BPM}=2s \\Rightarrow \\triangle\\mathrm{PBO}=6s$","$\\overline{\\mathrm{PN}}:\\overline{\\mathrm{PB}}=k:1 \\Rightarrow \\triangle\\mathrm{PNO}=6ks$","$6ks+2s=2\\triangle\\mathrm{PBA} \\Rightarrow \\triangle\\mathrm{PBA}=(3k+1)s$"],"설명":"높이가 같은 두 삼각형의 넓이비는 밑변의 비와 같다. $\\triangle\\mathrm{BPM}=2s$로 두면 $\\overline{\\mathrm{OM}}:\\overline{\\mathrm{MB}}=2:1$에서 $\\triangle\\mathrm{OPM}=4s$이다. $\\triangle\\mathrm{PNO}$와 $\\triangle\\mathrm{PBO}$는 꼭짓점 $\\mathrm{O}$가 같고 밑변이 직선 $\\mathrm{NB}$ 위에 있어 넓이비가 $k:1$이다. 넓이 조건 $\\triangle\\mathrm{PNO}+\\triangle\\mathrm{PMB}=2\\triangle\\mathrm{PBA}$에서 $\\triangle\\mathrm{PBA}$가 정해진다.","확인":null,"스킬":"S8"},{"제목":"나머지 세 삼각형의 넓이 구하기","힌트":"$\\triangle\\mathrm{ANP}$의 넓이는 어떻게 나타나고, $\\triangle\\mathrm{OAM}$과 $\\triangle\\mathrm{BAM}$은 각각 어떤 삼각형들로 나뉘는가?","식":["$\\triangle\\mathrm{ANP}=k\\cdot\\triangle\\mathrm{PBA}=(3k^2+k)s$","$\\triangle\\mathrm{OAM}=\\triangle\\mathrm{OPM}+\\triangle\\mathrm{PNO}+\\triangle\\mathrm{ANP}=(3k^2+7k+4)s$","$\\triangle\\mathrm{BAM}=\\triangle\\mathrm{PBA}+\\triangle\\mathrm{BPM}=(3k+3)s$"],"설명":"$\\triangle\\mathrm{ANP}$와 $\\triangle\\mathrm{APB}$는 꼭짓점 $\\mathrm{A}$가 같고 밑변이 $\\overline{\\mathrm{PN}},\\ \\overline{\\mathrm{PB}}$이므로 넓이비가 $k:1$이다. 점 $\\mathrm{P}$가 변 $\\mathrm{AM}$ 위에 있으므로 $\\triangle\\mathrm{OAM}$은 $\\triangle\\mathrm{OPM}$과 $\\triangle\\mathrm{OPA}$로, $\\triangle\\mathrm{BAM}$은 $\\triangle\\mathrm{BPA}$와 $\\triangle\\mathrm{BPM}$으로 나뉜다.","확인":null,"스킬":"S8"},{"제목":"넓이비 2:1로 k 구하기","힌트":"$\\triangle\\mathrm{OAM}:\\triangle\\mathrm{BAM}$은 밑변의 비 $\\overline{\\mathrm{OM}}:\\overline{\\mathrm{MB}}$와 같다. $k$에 대한 방정식은 무엇인가?","식":["$(3k^2+7k+4)s:(3k+3)s=2:1$","$3k^2+k-2=0 \\Rightarrow (3k-2)(k+1)=0$","$k=\\frac{2}{3}$"],"설명":"$3k^2+7k+4=2(3k+3)$을 정리하면 $3k^2+k-2=0$이다. $k$는 길이의 비이므로 양수여서 $k=\\frac{2}{3}$이다.","확인":"2/3","스킬":"S8","고비":true},{"제목":"점 P의 좌표 구하기","힌트":"$\\mathrm{N}(a,\\ 2a)$로 놓으면 $\\mathrm{P}$는 $\\overline{\\mathrm{NB}}$를 어떤 비로 내분하고, $\\mathrm{P}$가 직선 $\\mathrm{AM}$ 위에 있다는 조건으로 $a$는 얼마인가?","식":["$\\mathrm{N}(a,\\ 2a),\\ \\mathrm{P}\\left(\\frac{3a+12}{5},\\ \\frac{6a}{5}\\right)$","$\\frac{6a}{5}=-6\\cdot\\frac{3a+12}{5}+24 \\Rightarrow a=2$","$\\mathrm{P}\\left(\\frac{18}{5},\\ \\frac{12}{5}\\right)$"],"설명":"$\\mathrm{N}$은 직선 $\\mathrm{OA}:\\ y=2x$ 위의 점이다. $\\overline{\\mathrm{PN}}:\\overline{\\mathrm{PB}}=\\frac{2}{3}:1=2:3$이므로 $\\mathrm{P}=\\frac{3\\mathrm{N}+2\\mathrm{B}}{5}$이다. 이 점을 직선 $y=-6x+24$에 대입해 $a$를 구한다.","확인":"2","스킬":"S4"},{"제목":"x좌표와 y좌표의 합","힌트":"$\\mathrm{P}\\left(\\frac{18}{5},\\ \\frac{12}{5}\\right)$에서 두 좌표의 합은 얼마인가?","식":["$\\frac{18}{5}+\\frac{12}{5}=6$"],"설명":"합은 $\\frac{30}{5}=6$이고 선지 ①과 같다.","확인":"6","스킬":"S4"}]},"ns-94e2019204be":{"길":"수직이등분선과 닮음비로 CD의 길이를 잡고 거리 공식을 쓴다","단계":[{"제목":"점 C가 놓이는 직선","힌트":"$\\overline{\\mathrm{AC}}=\\overline{\\mathrm{BC}}$이면 $\\mathrm{C}$는 $\\overline{\\mathrm{AB}}$의 수직이등분선 위에 있다. 이 직선의 기울기는 얼마인가?","식":["$\\overline{\\mathrm{AB}}$의 중점 $(10,\\ 2)$, $\\overline{\\mathrm{AB}}$의 기울기 $-\\frac{1}{5}$","$y-2=5(x-10)$","$b=5a-48$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$이므로 수직이등분선의 기울기는 $5$이다. 이 직선이 중점 $(10,\\ 2)$를 지나므로 $b=5a-48$이다.","확인":"5","스킬":"S4"},{"제목":"중점과 평행선으로 보조선 긋기","힌트":"$\\mathrm{E}$는 $\\overline{\\mathrm{CQ}}$의 어떤 점인가? $\\mathrm{E}$에서 $\\overline{\\mathrm{PQ}}$에 평행한 직선이 $\\overline{\\mathrm{CD}}$와 만나는 점 $\\mathrm{H}$는 $\\overline{\\mathrm{CD}}$의 어떤 점인가?","식":["$\\overline{\\mathrm{CE}}=\\overline{\\mathrm{EQ}}$","$\\overline{\\mathrm{CH}}=\\overline{\\mathrm{DH}}$"],"설명":"$\\overline{\\mathrm{BC}}$를 $5$등분한 한 칸을 $1$로 보면 $\\overline{\\mathrm{BQ}}=1,\\ \\overline{\\mathrm{BE}}=3$이므로 $\\overline{\\mathrm{CQ}}=4,\\ \\overline{\\mathrm{CE}}=2$이고 $\\mathrm{E}$는 $\\overline{\\mathrm{CQ}}$의 중점이다. $\\triangle\\mathrm{CQD}$에서 $\\mathrm{E}$가 중점이고 $\\overline{\\mathrm{EH}}\\parallel\\overline{\\mathrm{QD}}$이므로 중점 연결정리에 의해 $\\mathrm{H}$는 $\\overline{\\mathrm{CD}}$의 중점이다.","확인":null,"스킬":"S2","고비":true},{"제목":"닮음으로 CD의 길이 구하기","힌트":"$\\triangle\\mathrm{FHE}$와 $\\triangle\\mathrm{FDP}$의 닮음비로 $\\overline{\\mathrm{FH}}$를 구하면 $\\overline{\\mathrm{CD}}$는 얼마인가?","식":["$\\overline{\\mathrm{EH}}=\\frac{1}{2}\\overline{\\mathrm{QD}}=\\frac{1}{2}\\overline{\\mathrm{PD}} \\Rightarrow \\triangle\\mathrm{FHE}\\sim\\triangle\\mathrm{FDP}\\ (1:2)$","$\\overline{\\mathrm{FH}}=\\frac{1}{2}\\overline{\\mathrm{DF}}=\\frac{2}{5}\\sqrt{26}$","$\\overline{\\mathrm{DH}}=\\frac{6}{5}\\sqrt{26}=\\overline{\\mathrm{CH}} \\Rightarrow \\overline{\\mathrm{CD}}=\\frac{12}{5}\\sqrt{26}$"],"설명":"$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CB}}$이므로 $\\overline{\\mathrm{CP}}=\\overline{\\mathrm{CQ}}$이고, 꼭지각의 이등분선 $\\overline{\\mathrm{CD}}$는 밑변 $\\overline{\\mathrm{PQ}}$를 이등분하여 $\\overline{\\mathrm{PD}}=\\overline{\\mathrm{QD}}$이다. $\\overline{\\mathrm{EH}}=\\frac{1}{2}\\overline{\\mathrm{QD}}$이므로 닮음비는 $1:2$이고 $\\overline{\\mathrm{FH}}=\\frac{1}{2}\\overline{\\mathrm{DF}}$이다. $\\mathrm{H}$가 $\\overline{\\mathrm{CD}}$의 중점이므로 $\\overline{\\mathrm{CD}}=2\\overline{\\mathrm{DH}}$이다.","확인":null,"스킬":"S1"},{"제목":"닮음비로 CI의 길이 구하기","힌트":"직선 $\\mathrm{CD}$가 $\\overline{\\mathrm{AB}}$와 만나는 점을 $\\mathrm{I}$라 할 때, $\\triangle\\mathrm{ABC}$와 $\\triangle\\mathrm{PQC}$의 닮음비로 $\\overline{\\mathrm{CI}}$는 얼마인가?","식":["$\\triangle\\mathrm{ABC}\\sim\\triangle\\mathrm{PQC}\\ (5:4) \\Rightarrow \\overline{\\mathrm{CI}}:\\overline{\\mathrm{CD}}=5:4$","$\\overline{\\mathrm{CI}}=\\frac{5}{4}\\cdot\\frac{12}{5}\\sqrt{26}=3\\sqrt{26}$"],"설명":"$\\overline{\\mathrm{CP}}:\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CQ}}:\\overline{\\mathrm{CB}}=4:5$이므로 $\\overline{\\mathrm{PQ}}\\parallel\\overline{\\mathrm{AB}}$이고 두 삼각형은 닮음이다. 대응하는 선분 $\\overline{\\mathrm{CD}},\\ \\overline{\\mathrm{CI}}$의 비도 $4:5$이다. 이등변삼각형 꼭지각의 이등분선은 밑변에 수직이므로 $\\overline{\\mathrm{CI}}$는 점 $\\mathrm{C}$에서 직선 $\\mathrm{AB}$까지의 거리이다.","확인":null,"스킬":"S1"},{"제목":"점과 직선 사이의 거리 식 세우기","힌트":"직선 $\\mathrm{AB}$의 방정식을 쓰고 $\\mathrm{C}(a,\\ b)$에서 직선까지의 거리를 $3\\sqrt{26}$으로 놓으면 $|a+5b-20|$은 얼마인가?","식":["$\\mathrm{AB}:\\ \\frac{x}{20}+\\frac{y}{4}=1 \\Rightarrow x+5y-20=0$","$\\frac{|a+5b-20|}{\\sqrt{26}}=3\\sqrt{26}$","$|a+5b-20|=78$"],"설명":"점과 직선 사이의 거리 공식을 쓴다. 양변에 $\\sqrt{26}$을 곱하면 $3\\cdot 26=78$이다.","확인":"78","스킬":"S4"},{"제목":"연립으로 a, b 정하기","힌트":"$b=5a-48$을 $|a+5b-20|=78$에 넣으면 $a$의 후보는 무엇이고, 제1사분면 조건에 맞는 $a$는 얼마인가?","식":["$|26a-260|=78 \\Rightarrow |a-10|=3 \\Rightarrow a=13,\\ 7$","$(a,\\ b)=(13,\\ 17),\\ (7,\\ -13)$","$(a,\\ b)=(13,\\ 17)$"],"설명":"$a+5b-20=a+5(5a-48)-20=26a-260$이므로 $|a-10|=3$이다. 점 $\\mathrm{C}$가 제1사분면에 있어 $b>0$이어야 하므로 $b=-13$인 $a=7$은 제외하고 $a=13,\\ b=17$이다.","확인":"13","스킬":"A10"},{"제목":"a+b의 값 계산","힌트":"$a=13,\\ b=17$일 때 $a+b$는 얼마인가?","식":["$a+b=13+17=30$"],"설명":"$a+b=30$이고 선지 ②와 같다.","확인":"30","스킬":"S4"}]},"ns-9caf15cc1d93":{"길":"삼등분점을 내분점으로 좌표화해 기울기와 k를 구한다","단계":[{"제목":"삼등분점 B, C의 좌표","힌트":"$\\mathrm{B}$는 $\\overline{\\mathrm{AD}}$를 $1:2$로, $\\mathrm{C}$는 $2:1$로 내분하는 점이다. 두 점의 좌표는 각각 무엇인가?","식":["$\\mathrm{B}\\left(\\frac{1\\cdot 5+2\\cdot 0}{3},\\ \\frac{1\\cdot 0+2\\cdot 4}{3}\\right)=\\left(\\frac{5}{3},\\ \\frac{8}{3}\\right)$","$\\mathrm{C}\\left(\\frac{2\\cdot 5+1\\cdot 0}{3},\\ \\frac{2\\cdot 0+1\\cdot 4}{3}\\right)=\\left(\\frac{10}{3},\\ \\frac{4}{3}\\right)$"],"설명":"$\\overline{\\mathrm{AD}}$를 삼등분하는 점 중 $\\mathrm{A}$에 가까운 점은 $1:2$ 내분점, 먼 점은 $2:1$ 내분점이다. 내분점 공식에 $\\mathrm{A}(0,\\ 4)$, $\\mathrm{D}(5,\\ 0)$을 대입한다.","확인":null,"스킬":"S4","고비":true},{"제목":"원점을 지나는 두 직선의 기울기","힌트":"직선 $y=mx$가 $\\mathrm{B}$를 지난다. $m$은 얼마인가?","식":["$m=\\frac{8/3}{5/3}=\\frac{8}{5}$","$n=\\frac{4/3}{10/3}=\\frac{2}{5}$"],"설명":"원점과 한 점을 지나는 직선의 기울기는 (점의 $y$좌표) ÷ (점의 $x$좌표)이다. $m>n$이므로 $\\mathrm{B}$를 지나는 직선의 기울기가 $m$이다.","확인":"8/5","스킬":"G9"},{"제목":"k의 값 구하기","힌트":"$m^2+n^2$과 $mn$을 구해 $k=\\frac{m^2+n^2}{mn}$에 넣으면 $k$는 얼마인가?","식":["$m^2+n^2=\\frac{64}{25}+\\frac{4}{25}=\\frac{68}{25},\\ mn=\\frac{16}{25}$","$k=\\frac{68}{16}=\\frac{17}{4}$"],"설명":"$m^2+n^2=kmn$에서 $k=\\frac{m^2+n^2}{mn}$이다. 분모가 같은 두 분수의 비이므로 분자끼리 나눈다.","확인":"17/4","스킬":"S4"},{"제목":"서로소 조건으로 p+q 구하기","힌트":"$\\frac{q}{p}=\\frac{17}{4}$에서 $p,\\ q$가 서로소인 양수이면 $p+q$는 얼마인가?","식":["$p=4,\\ q=17$","$p+q=21$"],"설명":"$17$과 $4$는 서로소이므로 $\\frac{17}{4}$는 기약분수이고 $p=4$, $q=17$이다. 따라서 $p+q=21$이고 선지 ①과 같다.","확인":"21","스킬":"N2"}]},"ns-9fc66389c66e":{"길":"각의 이등분선의 비로 P를 잡고 직선 BP로 Q를 구해 넓이를 계산한다","단계":[{"제목":"세 변의 길이와 이등분선의 비","힌트":"$\\overline{\\mathrm{AB}}$의 길이는 얼마이고, $\\angle\\mathrm{B}$의 이등분선은 $\\overline{\\mathrm{OA}}$를 어떤 비로 나누는가?","식":["$\\overline{\\mathrm{OB}}=3,\\ \\overline{\\mathrm{OA}}=4,\\ \\overline{\\mathrm{AB}}=5$","$\\overline{\\mathrm{OP}}:\\overline{\\mathrm{PA}}=\\overline{\\mathrm{BO}}:\\overline{\\mathrm{BA}}=3:5$"],"설명":"$\\overline{\\mathrm{OA}}=\\sqrt{8+8}=4$, $\\overline{\\mathrm{OB}}=\\sqrt{\\frac{9}{2}+\\frac{9}{2}}=3$, $\\overline{\\mathrm{AB}}=\\sqrt{\\left(\\frac{7\\sqrt{2}}{2}\\right)^2+\\left(\\frac{\\sqrt{2}}{2}\\right)^2}=5$이다. 각의 이등분선은 대변을 이웃한 두 변의 비로 나누므로 $\\mathrm{P}$는 $\\overline{\\mathrm{OA}}$를 $3:5$로 내분한다.","확인":"5","스킬":"S7"},{"제목":"점 P의 좌표","힌트":"$\\mathrm{P}$는 $\\overline{\\mathrm{OA}}$를 $3:5$로 내분하는 점이다. 좌표는 무엇인가?","식":["$\\mathrm{P}\\left(\\frac{5\\cdot 0+3\\cdot 2\\sqrt{2}}{8},\\ \\frac{5\\cdot 0+3\\cdot 2\\sqrt{2}}{8}\\right)$","$\\mathrm{P}\\left(\\frac{3\\sqrt{2}}{4},\\ \\frac{3\\sqrt{2}}{4}\\right)$"],"설명":"$\\mathrm{O}$가 원점이므로 $\\mathrm{P}$의 좌표는 $\\mathrm{A}$의 좌표에 $\\frac{3}{8}$을 곱한 값이다.","확인":null,"스킬":"S4"},{"제목":"직선 BP와 점 Q의 좌표","힌트":"직선 $\\mathrm{BP}$의 방정식을 구하면 $x$절편은 얼마인가? 그림에서 $\\mathrm{Q}$는 $x$축 위에 있다.","식":["$m_{\\mathrm{BP}}=\\frac{\\frac{3\\sqrt{2}}{4}-\\frac{3\\sqrt{2}}{2}}{\\frac{3\\sqrt{2}}{4}+\\frac{3\\sqrt{2}}{2}}=-\\frac{1}{3}$","$\\mathrm{BP}:\\ y=-\\frac{1}{3}x+\\sqrt{2}$","$y=0 \\Rightarrow x=3\\sqrt{2},\\ \\mathrm{Q}(3\\sqrt{2},\\ 0)$"],"설명":"$\\mathrm{Q}$는 $\\overline{\\mathrm{BP}}$의 연장선 위의 점이고 그림에서 $x$축 위에 있으므로 직선 $\\mathrm{BP}$의 $x$절편이다. $\\mathrm{B}\\left(-\\frac{3\\sqrt{2}}{2},\\ \\frac{3\\sqrt{2}}{2}\\right)$를 지나므로 $y$절편은 $\\sqrt{2}$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"점 Q에서 직선 AP까지의 거리","힌트":"직선 $\\mathrm{AP}$는 $y=x$이다. 점 $\\mathrm{Q}$에서 이 직선까지의 거리는 얼마인가?","식":["$\\mathrm{AP}:\\ x-y=0$","$d=\\frac{|3\\sqrt{2}-0|}{\\sqrt{2}}=3$","$\\overline{\\mathrm{AP}}=\\overline{\\mathrm{OA}}-\\overline{\\mathrm{OP}}=4-\\frac{3}{2}=\\frac{5}{2}$"],"설명":"$\\mathrm{A}$와 $\\mathrm{P}$는 모두 직선 $y=x$ 위의 점이므로 직선 $\\mathrm{AP}$는 $y=x$이다. 점과 직선 사이의 거리 공식을 쓴다. $\\overline{\\mathrm{OP}}=\\frac{3}{8}\\cdot 4=\\frac{3}{2}$이다.","확인":"3","스킬":"S4"},{"제목":"삼각형 APQ의 넓이","힌트":"밑변을 $\\overline{\\mathrm{AP}}$, 높이를 점 $\\mathrm{Q}$에서 직선 $\\mathrm{AP}$까지의 거리로 보면 넓이는 얼마인가?","식":["$\\triangle\\mathrm{APQ}=\\frac{1}{2}\\cdot\\frac{5}{2}\\cdot 3=\\frac{15}{4}$"],"설명":"밑변 $\\overline{\\mathrm{AP}}=\\frac{5}{2}$, 높이 $3$인 삼각형의 넓이이다.","확인":"15/4","스킬":"S8"}]},"ns-a18d32ca7c7c":{"길":"F가 무게중심임을 알아내고 각의 이등분선의 비로 두 넓이를 같은 기준에 잇는다","단계":[{"제목":"이등변삼각형에서 길이와 좌표 잡기","힌트":"$\\overline{\\mathrm{BA}}=\\overline{\\mathrm{BC}}$이면 $\\overline{\\mathrm{BE}}$는 $\\overline{\\mathrm{AC}}$를 수직이등분한다. $\\overline{\\mathrm{BE}}$의 길이는 얼마인가?","식":["$\\overline{\\mathrm{AE}}=\\overline{\\mathrm{CE}}=\\sqrt{7},\\ \\overline{\\mathrm{BE}}=\\sqrt{8-7}=1$","$\\mathrm{E}(0,\\ 0),\\ \\mathrm{A}(-\\sqrt{7},\\ 0),\\ \\mathrm{C}(\\sqrt{7},\\ 0),\\ \\mathrm{B}(0,\\ 1)$","$\\mathrm{D}\\left(-\\frac{\\sqrt{7}}{2},\\ \\frac{1}{2}\\right)$"],"설명":"이등변삼각형의 꼭지각의 이등분선은 밑변을 수직이등분한다. $\\mathrm{E}$를 원점, $\\overline{\\mathrm{AC}}$를 $x$축, $\\overline{\\mathrm{BE}}$를 $y$축에 놓으면 좌표가 위와 같고 $\\mathrm{D}$는 $\\overline{\\mathrm{AB}}$의 중점이다.","확인":"1","스킬":"S4"},{"제목":"F는 무게중심, 선분 길이","힌트":"$\\overline{\\mathrm{CD}}$와 $\\overline{\\mathrm{BE}}$는 중선이다. $\\overline{\\mathrm{CF}}$의 길이는 얼마인가?","식":["$\\overline{\\mathrm{BF}}=\\frac{2}{3},\\ \\overline{\\mathrm{FE}}=\\frac{1}{3}$","$\\overline{\\mathrm{CD}}=\\sqrt{\\left(\\frac{3\\sqrt{7}}{2}\\right)^2+\\left(\\frac{1}{2}\\right)^2}=4$","$\\overline{\\mathrm{CF}}=\\frac{8}{3},\\ \\overline{\\mathrm{FD}}=\\frac{4}{3}$"],"설명":"$\\overline{\\mathrm{CD}}$와 $\\overline{\\mathrm{BE}}$는 각각 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AC}}$의 중점을 지나는 중선이므로 $\\mathrm{F}$는 무게중심이고 중선을 $2:1$로 나눈다. $\\overline{\\mathrm{BE}}=1$에서 $\\overline{\\mathrm{BF}}=\\frac{2}{3}$, $\\overline{\\mathrm{FE}}=\\frac{1}{3}$이다. $\\overline{\\mathrm{CD}}$는 두 점 사이의 거리로 구한다.","확인":"8/3","스킬":"S7"},{"제목":"이등분선의 비로 두 삼각형 표현","힌트":"$\\angle\\mathrm{BFD}$와 $\\angle\\mathrm{CFE}$는 맞꼭지각이다. 직선 $\\mathrm{GH}$가 $\\triangle\\mathrm{FDB}$와 $\\triangle\\mathrm{FEC}$를 나누는 비는 각각 얼마인가?","식":["$\\overline{\\mathrm{DG}}:\\overline{\\mathrm{GB}}=\\overline{\\mathrm{FD}}:\\overline{\\mathrm{FB}}=2:1 \\Rightarrow S_2=\\frac{2}{3}\\triangle\\mathrm{FDB}$","$\\overline{\\mathrm{EH}}:\\overline{\\mathrm{HC}}=\\overline{\\mathrm{FE}}:\\overline{\\mathrm{FC}}=1:8 \\Rightarrow S_1=\\frac{1}{9}\\triangle\\mathrm{FEC}$"],"설명":"$\\angle\\mathrm{BFD}$와 $\\angle\\mathrm{CFE}$는 맞꼭지각이므로 직선 $\\mathrm{GH}$는 두 각을 모두 이등분한다. $\\triangle\\mathrm{FDB}$에서 이등분선은 $\\overline{\\mathrm{DB}}$를 $\\overline{\\mathrm{FD}}:\\overline{\\mathrm{FB}}=\\frac{4}{3}:\\frac{2}{3}=2:1$로 나누고, $\\triangle\\mathrm{FEC}$에서는 $\\overline{\\mathrm{EC}}$를 $\\overline{\\mathrm{FE}}:\\overline{\\mathrm{FC}}=\\frac{1}{3}:\\frac{8}{3}=1:8$로 나눈다. 꼭짓점 $\\mathrm{F}$가 같고 밑변이 한 직선 위에 있어 넓이비는 밑변의 비와 같다.","확인":null,"스킬":"S8","고비":true},{"제목":"무게중심의 넓이 성질로 비 구하기","힌트":"$\\triangle\\mathrm{FDB}$와 $\\triangle\\mathrm{FEC}$의 넓이는 어떤 관계이고, $\\frac{S_2}{S_1}$은 얼마인가?","식":["$\\triangle\\mathrm{FDB}=\\triangle\\mathrm{FEC}=\\frac{1}{6}\\triangle\\mathrm{ABC}$","$\\frac{S_2}{S_1}=\\frac{\\frac{2}{3}}{\\frac{1}{9}}=6$"],"설명":"무게중심과 중선으로 나뉜 여섯 삼각형의 넓이는 모두 같다. 따라서 $\\triangle\\mathrm{FDB}=\\triangle\\mathrm{FEC}$이고, $S_2:S_1=\\frac{2}{3}:\\frac{1}{9}=6:1$이다. 이 값은 선지 ③과 같다.","확인":"6","스킬":"S8"}]},"ns-b9803ef0d9e4":{"길":"두 점을 문자로 놓고 무게중심 식 두 개를 연립한다","단계":[{"제목":"무게중심 조건을 식으로 옮기기","힌트":"$\\mathrm{A}\\left(a,\\ \\frac{a}{2}\\right)$, $\\mathrm{B}(b,\\ 3b)$로 놓고 $\\triangle\\mathrm{OAB}$의 무게중심 좌표를 쓰면 어떤 식이 되는가?","식":["$\\left(\\frac{0+a+b}{3},\\ \\frac{0+\\frac{a}{2}+3b}{3}\\right)=\\left(2,\\ \\frac{8}{3}\\right)$","$a+b=6,\\ a+6b=16$"],"설명":"$\\mathrm{A}$는 직선 $y=\\frac{1}{2}x$ 위, $\\mathrm{B}$는 직선 $y=3x$ 위의 점이다. $y$좌표 식은 $\\frac{a}{6}+b=\\frac{8}{3}$이고 양변에 $6$을 곱하면 $a+6b=16$이다.","확인":null,"스킬":"S7","고비":true},{"제목":"연립방정식으로 a, b 구하기","힌트":"$a+b=6$, $a+6b=16$을 연립해 $a$를 구하면 얼마인가?","식":["$5b=10 \\Rightarrow b=2$","$a=6-2=4$"],"설명":"두 식을 변끼리 빼면 $5b=10$이므로 $b=2$이고 $a=4$이다. 따라서 $\\mathrm{A}(4,\\ 2)$, $\\mathrm{B}(2,\\ 6)$이다.","확인":"4","스킬":"A10"},{"제목":"선분 AB의 길이","힌트":"$\\mathrm{A}(4,\\ 2)$, $\\mathrm{B}(2,\\ 6)$ 사이의 거리는 얼마인가?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(2-4)^2+(6-2)^2}=\\sqrt{20}=2\\sqrt{5}$"],"설명":"두 점 사이의 거리 공식을 쓴다. $\\sqrt{20}=2\\sqrt{5}$이다.","확인":null,"스킬":"S4"}]},"ns-bebb9191213f":{"길":"평행선이 만드는 닮음비로 P가 AB를 외분하는 비를 구한다","단계":[{"제목":"삼각형 변의 길이 구하기","힌트":"$\\overline{\\mathrm{CA}},\\ \\overline{\\mathrm{BC}}$의 길이를 구하고, $\\overline{\\mathrm{CD}}=\\overline{\\mathrm{CA}}$를 이용하면 $\\overline{\\mathrm{BD}}$는 얼마인가?","식":["$\\overline{\\mathrm{CA}}=\\sqrt{4^2+3^2}=5$","$\\overline{\\mathrm{BC}}=\\sqrt{15^2+8^2}=17$","$\\overline{\\mathrm{BD}}=\\overline{\\mathrm{BC}}-\\overline{\\mathrm{CD}}=17-5=12$"],"설명":"$\\mathrm{D}$는 선분 $\\mathrm{BC}$ 위의 점이고 $\\overline{\\mathrm{CD}}=\\overline{\\mathrm{CA}}=5$이다. 두 점 사이의 거리 공식으로 $\\overline{\\mathrm{CA}},\\ \\overline{\\mathrm{BC}}$를 구한다.","확인":"12","스킬":"S3"},{"제목":"닮음비로 P의 위치 찾기","힌트":"$\\overline{\\mathrm{DA}}\\parallel\\overline{\\mathrm{CP}}$일 때 $\\triangle\\mathrm{BDA}$와 $\\triangle\\mathrm{BCP}$의 닮음비로 $\\overline{\\mathrm{PA}}:\\overline{\\mathrm{PB}}$는 얼마인가?","식":["$\\triangle\\mathrm{BDA}\\sim\\triangle\\mathrm{BCP}\\ (12:17)$","$\\overline{\\mathrm{BA}}:\\overline{\\mathrm{BP}}=12:17 \\Rightarrow \\overline{\\mathrm{PA}}:\\overline{\\mathrm{PB}}=5:17$"],"설명":"평행선이므로 두 삼각형은 닮음이고 $\\overline{\\mathrm{BD}}:\\overline{\\mathrm{BC}}=\\overline{\\mathrm{BA}}:\\overline{\\mathrm{BP}}=12:17$이다. $\\mathrm{P}$는 $\\mathrm{B}$에서 $\\mathrm{A}$를 지나 더 나간 점이므로 $\\overline{\\mathrm{PA}}=\\overline{\\mathrm{BP}}-\\overline{\\mathrm{BA}}$이고 $\\overline{\\mathrm{PA}}:\\overline{\\mathrm{PB}}=5:17$이다. 곧 $\\mathrm{P}$는 $\\overline{\\mathrm{AB}}$를 $5:17$로 외분하는 점이다.","확인":null,"스킬":"S1","고비":true},{"제목":"외분점 공식으로 P의 좌표","힌트":"$\\mathrm{P}$의 $x$좌표 $a$는 얼마인가?","식":["$a=\\frac{5\\cdot(-11)-17\\cdot 0}{5-17}=\\frac{55}{12}$","$b=\\frac{5\\cdot(-8)-17\\cdot 3}{5-17}=\\frac{91}{12}$"],"설명":"외분점 공식 $\\left(\\frac{mx_2-nx_1}{m-n},\\ \\frac{my_2-ny_1}{m-n}\\right)$에 $\\mathrm{A}(0,\\ 3)$, $\\mathrm{B}(-11,\\ -8)$, $m:n=5:17$을 대입한다.","확인":"55/12","스킬":"S4"},{"제목":"b-a의 값 계산","힌트":"$a=\\frac{55}{12}$, $b=\\frac{91}{12}$일 때 $b-a$는 얼마인가?","식":["$b-a=\\frac{91}{12}-\\frac{55}{12}=\\frac{36}{12}=3$"],"설명":"분모가 같으므로 분자끼리 빼면 $\\frac{36}{12}=3$이고 선지 ③과 같다.","확인":"3","스킬":"S4"}]},"ns-c33a923b6cfb":{"길":"P가 무게중심임을 알아내고 이등분선의 비로 두 넓이를 같은 삼각형에 잇는다","단계":[{"제목":"점 A의 좌표와 변의 길이","힌트":"$\\mathrm{B}(0,\\ 0)$, $\\mathrm{C}(2,\\ 0)$, $\\mathrm{D}(1,\\ 0)$으로 놓고 $\\overline{\\mathrm{AB}}=2\\sqrt{3}$, $\\overline{\\mathrm{AD}}=\\sqrt{7}$을 쓰면 $\\mathrm{A}$의 $x$좌표는 얼마인가?","식":["$\\mathrm{B}(0,\\ 0),\\ \\mathrm{C}(2,\\ 0),\\ \\mathrm{D}(1,\\ 0),\\ \\mathrm{A}(x,\\ y)$","$x^2+y^2=12,\\ (x-1)^2+y^2=7$","$x=3,\\ y=\\sqrt{3}\\ (y>0)$"],"설명":"두 식을 변끼리 빼면 $2x-1=5$이므로 $x=3$이고 $y^2=3$이다. 그림에서 $\\mathrm{A}$는 $x$축 위쪽에 있으므로 $\\mathrm{A}(3,\\ \\sqrt{3})$이고, $\\overline{\\mathrm{CA}}=\\sqrt{1+3}=2=\\overline{\\mathrm{CB}}$이다.","확인":"3","스킬":"S4"},{"제목":"이등변삼각형에서 점 P의 정체","힌트":"$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CB}}$이면 꼭지각 $\\mathrm{C}$의 이등분선 $\\overline{\\mathrm{CE}}$는 $\\overline{\\mathrm{AB}}$를 어떻게 나누는가? $\\overline{\\mathrm{CE}}$의 길이는 얼마인가?","식":["$\\mathrm{E}\\left(\\frac{3}{2},\\ \\frac{\\sqrt{3}}{2}\\right),\\ \\mathrm{P}\\left(\\frac{5}{3},\\ \\frac{\\sqrt{3}}{3}\\right)$","$\\overline{\\mathrm{PA}}=\\frac{2}{3}\\overline{\\mathrm{AD}}=\\frac{2\\sqrt{7}}{3},\\ \\overline{\\mathrm{PD}}=\\frac{\\sqrt{7}}{3}$","$\\overline{\\mathrm{CE}}=1,\\ \\overline{\\mathrm{PC}}=\\frac{2}{3},\\ \\overline{\\mathrm{PE}}=\\frac{1}{3}$"],"설명":"이등변삼각형의 꼭지각의 이등분선은 밑변을 이등분하므로 $\\mathrm{E}$는 $\\overline{\\mathrm{AB}}$의 중점이다. 따라서 $\\overline{\\mathrm{CE}}$와 $\\overline{\\mathrm{AD}}$는 중선이고 교점 $\\mathrm{P}$는 무게중심이어서 중선을 $2:1$로 나눈다. $\\overline{\\mathrm{CE}}=\\sqrt{\\left(\\frac{1}{2}\\right)^2+\\left(\\frac{\\sqrt{3}}{2}\\right)^2}=1$이다.","확인":"1","스킬":"S7"},{"제목":"이등분선으로 R, Q의 위치 정하기","힌트":"$\\overline{\\mathrm{PR}}$은 $\\angle\\mathrm{APE}$의 이등분선이다. $\\overline{\\mathrm{AR}}:\\overline{\\mathrm{RE}}$는 얼마이고, 연장선 $\\overline{\\mathrm{PQ}}$가 가르는 $\\overline{\\mathrm{DQ}}:\\overline{\\mathrm{QC}}$는 얼마인가?","식":["$\\overline{\\mathrm{AR}}:\\overline{\\mathrm{RE}}=\\overline{\\mathrm{PA}}:\\overline{\\mathrm{PE}}=2\\sqrt{7}:1$","$\\overline{\\mathrm{DQ}}:\\overline{\\mathrm{QC}}=\\overline{\\mathrm{PD}}:\\overline{\\mathrm{PC}}=\\sqrt{7}:2$"],"설명":"$\\triangle\\mathrm{APE}$에서 각의 이등분선은 대변 $\\overline{\\mathrm{AE}}$를 $\\overline{\\mathrm{PA}}:\\overline{\\mathrm{PE}}=\\frac{2\\sqrt{7}}{3}:\\frac{1}{3}$로 나눈다. $\\mathrm{A},\\ \\mathrm{P},\\ \\mathrm{D}$와 $\\mathrm{E},\\ \\mathrm{P},\\ \\mathrm{C}$가 각각 한 직선 위에 있으므로 $\\angle\\mathrm{APE}$와 $\\angle\\mathrm{DPC}$는 맞꼭지각이고, 직선 $\\mathrm{RQ}$는 두 각을 모두 이등분한다. $\\triangle\\mathrm{DPC}$에서 이등분선은 $\\overline{\\mathrm{DC}}$를 $\\overline{\\mathrm{PD}}:\\overline{\\mathrm{PC}}=\\frac{\\sqrt{7}}{3}:\\frac{2}{3}$로 나눈다.","확인":null,"스킬":"S10","고비":true},{"제목":"넓이를 두 삼각형의 일부로 나타내기","힌트":"$S_1$은 $\\triangle\\mathrm{PAE}$의, $S_2$는 $\\triangle\\mathrm{PDC}$의 각각 몇 분의 몇이고, 두 삼각형의 넓이는 어떤 관계인가?","식":["$S_1=\\frac{\\overline{\\mathrm{AR}}}{\\overline{\\mathrm{AE}}}\\triangle\\mathrm{PAE}=\\frac{2\\sqrt{7}}{2\\sqrt{7}+1}\\triangle\\mathrm{PAE}$","$S_2=\\frac{\\overline{\\mathrm{DQ}}}{\\overline{\\mathrm{DC}}}\\triangle\\mathrm{PDC}=\\frac{\\sqrt{7}}{\\sqrt{7}+2}\\triangle\\mathrm{PDC}$","$\\triangle\\mathrm{PAE}=\\triangle\\mathrm{PDC}=\\frac{1}{6}\\triangle\\mathrm{ABC}$"],"설명":"꼭짓점 $\\mathrm{P}$가 같고 밑변이 한 직선 위에 있으면 넓이비는 밑변의 비이다. $\\mathrm{P}$가 무게중심이므로 중선으로 나뉜 여섯 삼각형의 넓이는 모두 같다.","확인":null,"스킬":"S8"},{"제목":"넓이의 비를 유리화해 a 구하기","힌트":"$\\frac{S_2}{S_1}$을 $a+b\\sqrt{7}$ 꼴로 나타내면 $a$는 얼마인가?","식":["$\\frac{S_2}{S_1}=\\frac{\\sqrt{7}}{\\sqrt{7}+2}\\cdot\\frac{2\\sqrt{7}+1}{2\\sqrt{7}}=\\frac{2\\sqrt{7}+1}{2(\\sqrt{7}+2)}$","$=\\frac{(2\\sqrt{7}+1)(\\sqrt{7}-2)}{2\\cdot 3}=\\frac{12-3\\sqrt{7}}{6}=2-\\frac{\\sqrt{7}}{2}$"],"설명":"$\\triangle\\mathrm{PAE}=\\triangle\\mathrm{PDC}$이므로 두 비의 비만 남는다. 분모의 $\\sqrt{7}+2$에 $\\sqrt{7}-2$를 곱해 유리화하면 $(\\sqrt{7}+2)(\\sqrt{7}-2)=3$이다. 따라서 $a=2,\\ b=-\\frac{1}{2}$이다.","확인":"2","스킬":"A5"},{"제목":"ab의 값 계산","힌트":"$a=2,\\ b=-\\frac{1}{2}$일 때 $ab$는 얼마인가?","식":["$ab=2\\cdot\\left(-\\frac{1}{2}\\right)=-1$"],"설명":"$ab=-1$이고 선지 ②와 같다.","확인":"-1","스킬":"A5"}]},"ns-c8e912523383":{"길":"B를 원점에 두고 OA=OC인 O를 두 식으로 찾은 뒤 원 내부 조건으로 거른다","단계":[{"제목":"점 B를 원점에 둔 좌표 설정","힌트":"$\\mathrm{B}$를 원점에 두면 $\\mathrm{A},\\ \\mathrm{C}$의 좌표는 무엇이고, $\\mathrm{O}(x,\\ y)$는 어떤 조건을 만족하는가?","식":["$\\mathrm{B}(0,\\ 0),\\ \\mathrm{A}(0,\\ 4),\\ \\mathrm{C}(2,\\ 0),\\ \\mathrm{O}(x,\\ y)$","$\\overline{\\mathrm{OA}}^{\\,2}=x^2+(y-4)^2=10$","$\\overline{\\mathrm{OC}}^{\\,2}=(x-2)^2+y^2=10$"],"설명":"$\\angle\\mathrm{ABC}=90^{\\circ}$이므로 $\\overline{\\mathrm{BA}}$를 $y$축, $\\overline{\\mathrm{BC}}$를 $x$축에 놓을 수 있다. $\\mathrm{A},\\ \\mathrm{C}$가 원 위의 점이므로 $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OC}}=\\sqrt{10}$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"두 식을 빼서 x와 y의 관계 구하기","힌트":"두 식을 변끼리 빼면 $x$를 $y$로 나타낸 식은 무엇인가?","식":["$-8y+16=-4x+4$","$x=2y-3$"],"설명":"두 식을 전개하면 $x^2+y^2-8y+16=10$, $x^2+y^2-4x+4=10$이다. 변끼리 빼면 $x^2+y^2$이 사라져 일차식이 남는다.","확인":null,"스킬":"A10"},{"제목":"y의 값 구하기","힌트":"$x=2y-3$을 $(x-2)^2+y^2=10$에 넣으면 $y$의 두 값 중 작은 값은 얼마인가?","식":["$(2y-5)^2+y^2=10$","$y^2-4y+3=0 \\Rightarrow y=1,\\ 3$","$\\mathrm{O}(-1,\\ 1)$ 또는 $\\mathrm{O}(3,\\ 3)$"],"설명":"$(2y-5)^2+y^2=10$을 정리하면 $5y^2-20y+15=0$이고 $5$로 나누면 $y^2-4y+3=0$이다. $y=1$이면 $x=-1$, $y=3$이면 $x=3$이다.","확인":"1","스킬":"A10"},{"제목":"원 내부 조건으로 O 정하기","힌트":"$\\mathrm{B}$는 원 내부의 점이므로 $\\overline{\\mathrm{OB}}$는 반지름 $\\sqrt{10}$보다 짧아야 한다. 두 후보 중 알맞은 $\\overline{\\mathrm{OB}}$는 얼마인가?","식":["$\\mathrm{O}(-1,\\ 1) \\Rightarrow \\overline{\\mathrm{OB}}=\\sqrt{2}<\\sqrt{10}$","$\\mathrm{O}(3,\\ 3) \\Rightarrow \\overline{\\mathrm{OB}}=3\\sqrt{2}>\\sqrt{10}$","$\\overline{\\mathrm{OB}}=\\sqrt{2}$"],"설명":"$\\mathrm{O}(3,\\ 3)$이면 $\\overline{\\mathrm{OB}}=3\\sqrt{2}=\\sqrt{18}>\\sqrt{10}$이어서 $\\mathrm{B}$가 원 밖에 놓인다. 따라서 $\\mathrm{O}(-1,\\ 1)$이고 $\\overline{\\mathrm{OB}}=\\sqrt{2}$이며 선지 ①과 같다.","확인":null,"스킬":"C2"}]},"ns-cd5cf80798a0":{"길":"중선정리로 PB²을 세우고 직사각형 성질로 PB²을 바꿔 계수를 비교한다","단계":[{"제목":"중선정리로 식 세우기","힌트":"$\\triangle\\mathrm{PBC}$에서 $\\mathrm{M}$은 $\\overline{\\mathrm{BC}}$의 중점이다. $2\\overline{\\mathrm{CM}}^{\\,2}$를 $\\overline{\\mathrm{PB}},\\ \\overline{\\mathrm{PC}},\\ \\overline{\\mathrm{PM}}$으로 나타내면 어떤 식이 되는가?","식":["$\\overline{\\mathrm{PB}}^{\\,2}+\\overline{\\mathrm{PC}}^{\\,2}=2\\left(\\overline{\\mathrm{PM}}^{\\,2}+\\overline{\\mathrm{CM}}^{\\,2}\\right)$","$2\\overline{\\mathrm{CM}}^{\\,2}=\\overline{\\mathrm{PB}}^{\\,2}+\\overline{\\mathrm{PC}}^{\\,2}-2\\overline{\\mathrm{PM}}^{\\,2}$"],"설명":"중선정리는 삼각형의 두 변의 제곱의 합이 중선의 제곱과 밑변의 절반의 제곱의 합의 $2$배라는 성질이다. 이 식을 $2\\overline{\\mathrm{CM}}^{\\,2}$에 대해 정리한다.","확인":null,"스킬":"S3"},{"제목":"직사각형 성질로 PB² 바꾸기","힌트":"직사각형 내부의 점 $\\mathrm{P}$에 대하여 $\\overline{\\mathrm{PA}}^{\\,2}+\\overline{\\mathrm{PC}}^{\\,2}$은 어떤 합과 같은가?","식":["$\\overline{\\mathrm{PA}}^{\\,2}+\\overline{\\mathrm{PC}}^{\\,2}=\\overline{\\mathrm{PB}}^{\\,2}+\\overline{\\mathrm{PD}}^{\\,2}$","$\\overline{\\mathrm{PB}}^{\\,2}=\\overline{\\mathrm{PA}}^{\\,2}+\\overline{\\mathrm{PC}}^{\\,2}-\\overline{\\mathrm{PD}}^{\\,2}$"],"설명":"점 $\\mathrm{P}$에서 각 변에 수선을 내려 피타고라스의 정리를 쓰면, 마주 보는 꼭짓점까지 거리의 제곱의 합 $\\overline{\\mathrm{PA}}^{\\,2}+\\overline{\\mathrm{PC}}^{\\,2}$과 $\\overline{\\mathrm{PB}}^{\\,2}+\\overline{\\mathrm{PD}}^{\\,2}$이 같다.","확인":null,"스킬":"S3","고비":true},{"제목":"대입해 계수 비교하기","힌트":"$\\overline{\\mathrm{PB}}^{\\,2}$을 대입해 정리하면 $\\overline{\\mathrm{PD}}^{\\,2}$의 계수 $c$는 얼마인가?","식":["$2\\overline{\\mathrm{CM}}^{\\,2}=\\overline{\\mathrm{PA}}^{\\,2}+2\\overline{\\mathrm{PC}}^{\\,2}-\\overline{\\mathrm{PD}}^{\\,2}-2\\overline{\\mathrm{PM}}^{\\,2}$","$a=1,\\ b=2,\\ c=-1,\\ d=-2$"],"설명":"$\\overline{\\mathrm{PC}}^{\\,2}$은 두 식에서 한 번씩 나와 계수가 $1+1=2$가 되고, $\\overline{\\mathrm{PD}}^{\\,2}$에는 $-$가 붙는다. 임의의 점 $\\mathrm{P}$에 대해 성립하는 식이므로 계수를 그대로 비교한다.","확인":"-1","스킬":"A3"},{"제목":"a+b+c+d의 값 계산","힌트":"$a=1,\\ b=2,\\ c=-1,\\ d=-2$이면 합은 얼마인가?","식":["$a+b+c+d=1+2-1-2=0$"],"설명":"합은 $0$이고 선지 ③과 같다.","확인":"0","스킬":"A3"}]},"ns-cebc05dda1e0":{"길":"두 내분점이 축 위에 있을 조건에서 m, n을 지워 a, b의 관계만 남긴다","단계":[{"제목":"두 내분점의 좌표 구하기","힌트":"$\\overline{\\mathrm{AB}}$와 $\\overline{\\mathrm{AC}}$를 $m:n$으로 내분하는 점의 좌표는 각각 무엇인가?","식":["$\\overline{\\mathrm{AB}}:\\ \\left(\\frac{-m+na}{m+n},\\ \\frac{m+nb}{m+n}\\right)$","$\\overline{\\mathrm{AC}}:\\ \\left(\\frac{2m+na}{m+n},\\ \\frac{-2m+nb}{m+n}\\right)$"],"설명":"$\\mathrm{A}$에서 $\\mathrm{B}$ 쪽으로 $m:n$으로 내분하므로 $\\mathrm{A}$의 좌표에는 $n$을, $\\mathrm{B}$의 좌표에는 $m$을 곱해 더하고 $m+n$으로 나눈다. $\\overline{\\mathrm{AC}}$도 같은 방법이다.","확인":null,"스킬":"C7"},{"제목":"축 위에 있을 조건","힌트":"$y$축 위의 점은 $x$좌표가, $x$축 위의 점은 $y$좌표가 $0$이다. 각각 어떤 식이 되는가?","식":["$-m+na=0 \\Rightarrow na=m$","$-2m+nb=0 \\Rightarrow nb=2m$"],"설명":"$\\overline{\\mathrm{AB}}$의 내분점이 $y$축 위에 있으므로 $x$좌표가 $0$이고, $\\overline{\\mathrm{AC}}$의 내분점이 $x$축 위에 있으므로 $y$좌표가 $0$이다. 분모 $m+n$은 $0$이 아니므로 분자만 $0$으로 둔다.","확인":null,"스킬":"C7","고비":true},{"제목":"m, n을 없애 a, b의 관계 구하기","힌트":"$na=m$과 $nb=2m$에서 $m,\\ n$을 없애면 $b$는 $a$로 어떻게 나타나는가?","식":["$nb=2m=2na$","$b=2a$"],"설명":"$nb=2m$에 $m=na$를 대입하면 $nb=2na$이고 $n>0$이므로 $b=2a$이다. 거꾸로 $b=2a$이면 $n=1,\\ m=a$로 두 조건을 모두 만족하므로 $b=2a$가 필요충분조건이다.","확인":null,"스킬":"A10"},{"제목":"10 이하의 자연수 순서쌍 세기","힌트":"$b=2a$를 만족하는 $10$ 이하의 자연수 순서쌍 $(a,\\ b)$는 몇 개인가?","식":["$(1,\\ 2),\\ (2,\\ 4),\\ (3,\\ 6),\\ (4,\\ 8),\\ (5,\\ 10)$"],"설명":"$b=2a\\le 10$에서 $a\\le 5$이므로 $a=1,\\ 2,\\ 3,\\ 4,\\ 5$이다. 순서쌍마다 삼각형이 하나씩 정해지므로 개수는 순서쌍의 개수와 같다.","확인":"5","스킬":"P4"}]},"ns-d5d13a602ef6":{"길":"OB와 DB를 피타고라스로 구해 OP, OQ를 바로 잡는다","단계":[{"제목":"OP의 길이와 OP²","힌트":"$\\overline{\\mathrm{OP}}=\\overline{\\mathrm{OB}}$이다. $\\overline{\\mathrm{OP}}^{\\,2}$은 얼마인가?","식":["$\\overline{\\mathrm{OB}}=\\sqrt{4^2+4^2}=4\\sqrt{2}$","$\\overline{\\mathrm{OP}}^{\\,2}=32$"],"설명":"$\\mathrm{P}$는 $\\mathrm{O}$를 중심으로 하고 $\\overline{\\mathrm{OB}}$를 반지름으로 하는 원 위의 점이므로 $\\overline{\\mathrm{OP}}=\\overline{\\mathrm{OB}}$이다. $\\overline{\\mathrm{OB}}$는 정사각형의 대각선이다.","확인":"32","스킬":"S3"},{"제목":"OD, DB를 구해 OQ 구하기","힌트":"$\\overline{\\mathrm{OD}}$와 $\\overline{\\mathrm{DB}}$를 구하면 $\\overline{\\mathrm{OQ}}$는 얼마인가?","식":["$\\overline{\\mathrm{OD}}=\\frac{1}{4}\\overline{\\mathrm{OA}}=1,\\ \\overline{\\mathrm{DA}}=3$","$\\overline{\\mathrm{DB}}=\\sqrt{3^2+4^2}=5$","$\\overline{\\mathrm{OQ}}=\\overline{\\mathrm{OD}}+\\overline{\\mathrm{DQ}}=1+5=6$"],"설명":"$\\mathrm{D}$는 $\\overline{\\mathrm{OA}}$를 $1:3$으로 내분하므로 $\\overline{\\mathrm{OD}}=1$이다. $\\mathrm{Q}$는 $\\mathrm{D}$를 중심으로 반지름 $\\overline{\\mathrm{DB}}$인 원이 반직선 $\\mathrm{OA}$와 만나는 점이다. 반직선 $\\mathrm{OA}$ 위의 점은 $\\mathrm{D}$의 오른쪽에 있으므로 $\\overline{\\mathrm{DQ}}=\\overline{\\mathrm{DB}}=5$이다.","확인":"6","스킬":"S3","고비":true},{"제목":"OP²+OQ²의 값","힌트":"$\\overline{\\mathrm{OP}}^{\\,2}=32$, $\\overline{\\mathrm{OQ}}=6$일 때 $\\overline{\\mathrm{OP}}^{\\,2}+\\overline{\\mathrm{OQ}}^{\\,2}$은 얼마인가?","식":["$\\overline{\\mathrm{OP}}^{\\,2}+\\overline{\\mathrm{OQ}}^{\\,2}=32+36=68$"],"설명":"$\\overline{\\mathrm{OQ}}^{\\,2}=6^2=36$이므로 합은 $32+36=68$이다.","확인":"68","스킬":"S3"}]},"ns-de4e01663c54":{"길":"각의 이등분선의 비로 D를, 평균으로 G를 잡고 외분점 공식을 쓴다","단계":[{"제목":"변의 길이와 BD:CD","힌트":"$\\overline{\\mathrm{AB}}$의 길이는 얼마이고, $\\angle\\mathrm{A}$의 이등분선은 $\\overline{\\mathrm{BC}}$를 어떤 비로 나누는가?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(2+4)^2+(5+3)^2}=10$","$\\overline{\\mathrm{AC}}=\\sqrt{(5-2)^2+(1-5)^2}=5$","$\\overline{\\mathrm{BD}}:\\overline{\\mathrm{CD}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=2:1$"],"설명":"각의 이등분선은 대변을 이웃한 두 변의 비로 나눈다. 따라서 $\\overline{\\mathrm{BD}}:\\overline{\\mathrm{CD}}$는 $\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}$와 같다.","확인":"10","스킬":"S7","고비":true},{"제목":"점 D의 좌표","힌트":"$\\mathrm{D}$는 $\\overline{\\mathrm{BC}}$를 $2:1$로 내분하는 점이다. $y$좌표는 얼마인가?","식":["$\\mathrm{D}\\left(\\frac{2\\cdot 5+1\\cdot(-4)}{3},\\ \\frac{2\\cdot 1+1\\cdot(-3)}{3}\\right)$","$\\mathrm{D}\\left(2,\\ -\\frac{1}{3}\\right)$"],"설명":"$\\overline{\\mathrm{BD}}:\\overline{\\mathrm{CD}}=2:1$이므로 $\\mathrm{B}$의 좌표에는 $1$을, $\\mathrm{C}$의 좌표에는 $2$를 곱해 더하고 $3$으로 나눈다.","확인":"-1/3","스킬":"S4"},{"제목":"무게중심 G의 좌표","힌트":"세 꼭짓점의 좌표의 평균으로 $\\mathrm{G}$를 구하면 어떤 점인가?","식":["$\\mathrm{G}\\left(\\frac{2-4+5}{3},\\ \\frac{5-3+1}{3}\\right)=(1,\\ 1)$"],"설명":"삼각형의 무게중심의 좌표는 세 꼭짓점의 좌표의 평균이다.","확인":null,"스킬":"S7"},{"제목":"외분점 Q의 좌표","힌트":"$\\overline{\\mathrm{DG}}$를 $2:1$로 외분하는 점 $\\mathrm{Q}$의 $x$좌표와 $y$좌표는 각각 얼마인가?","식":["$\\mathrm{Q}\\left(\\frac{2\\cdot 1-1\\cdot 2}{2-1},\\ \\frac{2\\cdot 1-1\\cdot\\left(-\\frac{1}{3}\\right)}{2-1}\\right)$","$\\mathrm{Q}\\left(0,\\ \\frac{7}{3}\\right)$"],"설명":"선분 $\\mathrm{DG}$를 $m:n$으로 외분하는 점은 $\\left(\\frac{mx_2-nx_1}{m-n},\\ \\frac{my_2-ny_1}{m-n}\\right)$이다. 여기서 $\\mathrm{D}$를 $(x_1,\\ y_1)$, $\\mathrm{G}$를 $(x_2,\\ y_2)$로 두고 $m:n=2:1$을 대입한다.","확인":null,"스킬":"S4"}]},"ns-dfe17789cb73":{"길":"외분점 네 개를 좌표로 쓰고 a-c, b-d를 한 덩어리로 두어 일차항을 지운다","단계":[{"제목":"외분점 네 개의 좌표","힌트":"선분 $\\mathrm{XY}$를 $4:1$로 외분하는 점의 좌표는 어떤 식이고, $\\mathrm{P},\\ \\mathrm{Q},\\ \\mathrm{R},\\ \\mathrm{S}$는 각각 무엇인가?","식":["$\\mathrm{P}\\left(\\frac{4a}{3},\\ \\frac{4b}{3}\\right),\\ \\mathrm{Q}\\left(\\frac{8-a}{3},\\ \\frac{20-b}{3}\\right)$","$\\mathrm{R}\\left(\\frac{4c-2}{3},\\ \\frac{4d-5}{3}\\right),\\ \\mathrm{S}\\left(-\\frac{c}{3},\\ -\\frac{d}{3}\\right)$"],"설명":"선분 $\\mathrm{XY}$를 $4:1$로 외분하는 점은 $\\frac{4\\mathrm{Y}-\\mathrm{X}}{4-1}$이다. $\\mathrm{O}(0,\\ 0)$, $\\mathrm{A}(a,\\ b)$, $\\mathrm{B}(2,\\ 5)$, $\\mathrm{C}(c,\\ d)$를 선분의 순서대로 넣는다.","확인":null,"스킬":"S4"},{"제목":"a-c, b-d를 한 덩어리로 두기","힌트":"$u=a-c$, $v=b-d$로 놓으면 $\\overline{\\mathrm{PR}}^{\\,2}$과 $\\overline{\\mathrm{QS}}^{\\,2}$는 $u,\\ v$로 어떻게 나타나는가?","식":["$u^2+v^2=\\overline{\\mathrm{AC}}^{\\,2}=25$","$\\overline{\\mathrm{PR}}^{\\,2}=\\frac{(4u+2)^2+(4v+5)^2}{9}$","$\\overline{\\mathrm{QS}}^{\\,2}=\\frac{(u-8)^2+(v-20)^2}{9}$"],"설명":"$\\overline{\\mathrm{PR}}$의 $x$성분은 $\\frac{4c-2}{3}-\\frac{4a}{3}=-\\frac{4u+2}{3}$, $y$성분은 $-\\frac{4v+5}{3}$이다. $\\overline{\\mathrm{QS}}$의 $x$성분은 $-\\frac{c}{3}-\\frac{8-a}{3}=\\frac{u-8}{3}$, $y$성분은 $\\frac{v-20}{3}$이다. 제곱하면 부호는 사라진다.","확인":null,"스킬":"A1"},{"제목":"전개해 일차항 지우기","힌트":"두 식의 분자를 전개해 더하면 $u,\\ v$의 일차항은 어떻게 되고, 상수항의 합은 얼마인가?","식":["$(4u+2)^2+(u-8)^2=17u^2+68$","$(4v+5)^2+(v-20)^2=17v^2+425$","$\\overline{\\mathrm{PR}}^{\\,2}+\\overline{\\mathrm{QS}}^{\\,2}=\\frac{17(u^2+v^2)+493}{9}$"],"설명":"$16u$와 $-16u$, $40v$와 $-40v$가 서로 지워져 $u,\\ v$의 일차항이 사라진다. 상수항은 $68+425=493$이다.","확인":"493","스킬":"A1","고비":true},{"제목":"조건 (나)를 대입해 값 구하기","힌트":"$u^2+v^2=25$를 대입하면 $\\overline{\\mathrm{PR}}^{\\,2}+\\overline{\\mathrm{QS}}^{\\,2}$은 얼마인가?","식":["$\\frac{17\\cdot 25+493}{9}=\\frac{918}{9}=102$"],"설명":"$17\\cdot 25=425$이고 $425+493=918$이다. $\\frac{918}{9}=102$이며 선지 ②와 같다.","확인":"102","스킬":"A1"}]},"ns-e163f9ea882d":{"길":"A를 원점에 두고 세 거리식을 서로 빼서 x, y를 변의 길이 a로 나타낸다","단계":[{"제목":"좌표 설정과 세 거리식","힌트":"정사각형의 한 변을 $a$로 놓고 $\\mathrm{A}$를 원점에 두면 $\\overline{\\mathrm{AP}},\\ \\overline{\\mathrm{BP}},\\ \\overline{\\mathrm{CP}}$의 조건은 각각 어떤 식이 되는가?","식":["$\\overline{\\mathrm{AP}}^{\\,2}=x^2+y^2=25$","$\\overline{\\mathrm{BP}}^{\\,2}=(x-a)^2+y^2=9$","$\\overline{\\mathrm{CP}}^{\\,2}=(x-a)^2+(y-a)^2=49$"],"설명":"$\\mathrm{A}(0,\\ 0)$, $\\mathrm{B}(a,\\ 0)$, $\\mathrm{C}(a,\\ a)$, $\\mathrm{D}(0,\\ a)$로 놓고 $\\mathrm{P}(x,\\ y)$라 한다. 두 점 사이의 거리의 제곱을 좌표로 쓴다.","확인":null,"스킬":"S4"},{"제목":"식을 빼서 x, y를 a로 나타내기","힌트":"첫째 식에서 둘째 식을, 둘째 식에서 셋째 식을 빼면 $x$와 $y$는 $a$로 어떻게 나타나는가?","식":["$2ax-a^2=16 \\Rightarrow x=\\frac{a^2+16}{2a}$","$2ay-a^2=-40 \\Rightarrow y=\\frac{a^2-40}{2a}$"],"설명":"첫째 식에서 둘째 식을 빼면 $x^2-(x-a)^2=2ax-a^2=25-9$이다. 둘째 식에서 셋째 식을 빼면 $y^2-(y-a)^2=2ay-a^2=9-49$이다.","확인":null,"스킬":"A10"},{"제목":"a²에 대한 방정식 풀기","힌트":"$x,\\ y$를 $x^2+y^2=25$에 넣어 정리하면 $a^2$의 두 값 중 큰 값은 얼마인가?","식":["$\\frac{(a^2+16)^2+(a^2-40)^2}{4a^2}=25$","$a^4-74a^2+928=0$","$(a^2-58)(a^2-16)=0$"],"설명":"양변에 $4a^2$을 곱해 전개하면 $2a^4-48a^2+1856=100a^2$이고 $2$로 나누면 $a^4-74a^2+928=0$이다. $a^2$을 한 문자로 보고 인수분해한다.","확인":"58","스킬":"A1","고비":true},{"제목":"조건에 맞는 a 고르기","힌트":"$a^2=16$이면 점 $\\mathrm{P}$의 좌표는 어디이고, 문제의 조건에 맞는가?","식":["$a^2=16 \\Rightarrow \\mathrm{P}(4,\\ -3)$","$a^2=58$","$a=\\sqrt{58}$"],"설명":"$a^2=16$이면 $a=4$이고 $x=\\frac{32}{8}=4$, $y=\\frac{-24}{8}=-3$이다. $\\mathrm{P}$가 직선 $\\mathrm{BC}$ 위에 놓이고 $y<0$이어서 정사각형 내부의 점이 아니므로 제외한다. 따라서 $a^2=58$이다.","확인":null,"스킬":"C2"}]},"ns-edf0d9a991f6":{"길":"두 변의 길이를 제곱 꼴로 좌표에 옮겨 전개하고 더한다","단계":[{"제목":"두 변의 길이를 제곱 꼴로 쓰기","힌트":"$\\mathrm{A}(a,\\ b)$와 $\\mathrm{B}(-c,\\ 0)$, $\\mathrm{C}(c,\\ 0)$ 사이 거리의 제곱은 각각 어떤 식인가?","식":["$\\overline{\\mathrm{AB}}^{\\,2}=(a+c)^2+b^2$","$\\overline{\\mathrm{AC}}^{\\,2}=(a-c)^2+b^2$"],"설명":"두 점 사이의 거리 공식에서 제곱근을 씌우지 않고 제곱 그대로 쓴다. $\\mathrm{B}$의 $x$좌표가 $-c$이므로 $a-(-c)=a+c$이다.","확인":null,"스킬":"S4","고비":true},{"제목":"전개해 더하기","힌트":"두 식을 전개해 더하면 $ac$가 들어 있는 항은 어떻게 되는가?","식":["$(a^2+2ac+c^2+b^2)+(a^2-2ac+c^2+b^2)$","$=2a^2+2b^2+2c^2=2(a^2+b^2+c^2)$"],"설명":"$2ac$와 $-2ac$가 서로 지워진다. 따라서 (가)는 $2(a^2+b^2+c^2)$이고 선지 ④와 같다.","확인":null,"스킬":"S4"}]},"ns-f46f517e0259":{"길":"높이가 같은 두 삼각형의 넓이비를 선분의 비로 바꿔 P를 내분점으로 잡는다","단계":[{"제목":"넓이비를 선분의 비로 바꾸기","힌트":"$\\triangle\\mathrm{OAP}$와 $\\triangle\\mathrm{OBP}$는 꼭짓점 $\\mathrm{O}$가 같고 밑변이 선분 $\\mathrm{AB}$ 위에 있다. 넓이비는 어떤 선분의 비와 같은가?","식":["$\\triangle\\mathrm{OAP}:\\triangle\\mathrm{OBP}=\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PB}}=3:1$"],"설명":"높이가 같은 두 삼각형의 넓이비는 밑변의 비와 같다. 따라서 $\\mathrm{P}$는 $\\overline{\\mathrm{AB}}$를 $3:1$로 내분하는 점이다.","확인":null,"스킬":"S8","고비":true},{"제목":"점 P의 좌표","힌트":"$\\mathrm{P}$는 $\\overline{\\mathrm{AB}}$를 $3:1$로 내분하는 점이다. $y$좌표는 얼마인가?","식":["$\\mathrm{P}\\left(\\frac{3\\cdot 0+1\\cdot 4}{4},\\ \\frac{3\\cdot 3+1\\cdot 0}{4}\\right)=\\left(1,\\ \\frac{9}{4}\\right)$"],"설명":"$\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PB}}=3:1$이므로 $\\mathrm{A}$의 좌표에는 $1$을, $\\mathrm{B}$의 좌표에는 $3$을 곱해 더하고 $4$로 나눈다.","확인":"9/4","스킬":"S4"},{"제목":"직선에 대입해 a 구하기","힌트":"직선 $ax-4y+6=0$이 $\\mathrm{P}\\left(1,\\ \\frac{9}{4}\\right)$를 지난다. $a$는 얼마인가?","식":["$a-4\\cdot\\frac{9}{4}+6=0$","$a=3$"],"설명":"점 $\\mathrm{P}$가 직선 위에 있으므로 좌표를 방정식에 대입하면 등식이 성립한다. $a-9+6=0$에서 $a=3$이고 선지 ③과 같다.","확인":"3","스킬":"G1"}]},"ns-fc0473556a6a":{"길":"무게중심 G가 같음을 이용해 G와 Y 사이 거리로 정삼각형 XYZ의 높이를 얻는다","단계":[{"제목":"정삼각형 BEC의 무게중심 Y","힌트":"$\\overline{\\mathrm{BC}}=2$인 정삼각형 $\\mathrm{BEC}$에서 꼭짓점 $\\mathrm{E}$와 무게중심 $\\mathrm{Y}$의 좌표는 각각 무엇인가?","식":["$\\mathrm{E}(0,\\ -\\sqrt{3})$","$\\mathrm{Y}\\left(0,\\ -\\frac{\\sqrt{3}}{3}\\right)$"],"설명":"한 변이 $2$인 정삼각형의 높이는 $\\sqrt{3}$이다. 삼각형 $\\mathrm{ABC}$가 $x$축 위쪽에 있으므로 외부에 그린 정삼각형은 아래쪽에 놓인다. 무게중심은 $\\overline{\\mathrm{BC}}$의 중점 $(0,\\ 0)$에서 높이의 $\\frac{1}{3}$만큼 떨어진 점이다.","확인":null,"스킬":"S7"},{"제목":"두 삼각형의 무게중심은 일치","힌트":"나폴레옹 삼각형 $\\mathrm{XYZ}$의 무게중심은 삼각형 $\\mathrm{ABC}$의 무게중심과 같다. 이 점 $\\mathrm{G}$의 좌표는 무엇인가?","식":["$\\mathrm{G}\\left(\\frac{1-1+1}{3},\\ \\frac{2\\sqrt{3}+0+0}{3}\\right)=\\left(\\frac{1}{3},\\ \\frac{2\\sqrt{3}}{3}\\right)$"],"설명":"나폴레옹 삼각형의 무게중심이 원래 삼각형의 무게중심과 일치한다는 성질을 쓴다. $\\mathrm{G}$는 $\\triangle\\mathrm{ABC}$의 세 꼭짓점 좌표의 평균이다.","확인":null,"스킬":"S7","고비":true},{"제목":"선분 GY의 길이","힌트":"$\\mathrm{G}\\left(\\frac{1}{3},\\ \\frac{2\\sqrt{3}}{3}\\right)$와 $\\mathrm{Y}\\left(0,\\ -\\frac{\\sqrt{3}}{3}\\right)$ 사이 거리의 제곱은 얼마인가?","식":["$\\overline{\\mathrm{GY}}^{\\,2}=\\left(\\frac{1}{3}\\right)^2+\\left(\\frac{2\\sqrt{3}}{3}+\\frac{\\sqrt{3}}{3}\\right)^2=\\frac{1}{9}+3=\\frac{28}{9}$","$\\overline{\\mathrm{GY}}=\\frac{2\\sqrt{7}}{3}$"],"설명":"$x$좌표의 차는 $\\frac{1}{3}$, $y$좌표의 차는 $\\frac{2\\sqrt{3}}{3}-\\left(-\\frac{\\sqrt{3}}{3}\\right)=\\sqrt{3}$이다.","확인":"28/9","스킬":"S4"},{"제목":"정삼각형 XYZ의 높이","힌트":"$\\mathrm{G}$는 정삼각형 $\\mathrm{XYZ}$의 무게중심이다. 꼭짓점 $\\mathrm{Y}$에서 맞은편 변까지의 높이는 $\\overline{\\mathrm{GY}}$의 몇 배인가?","식":["$h=\\frac{3}{2}\\overline{\\mathrm{GY}}=\\frac{3}{2}\\cdot\\frac{2\\sqrt{7}}{3}=\\sqrt{7}$"],"설명":"무게중심은 중선(정삼각형에서는 높이)을 $2:1$로 나누므로 꼭짓점에서 무게중심까지의 거리 $\\overline{\\mathrm{GY}}$는 높이의 $\\frac{2}{3}$이다.","확인":null,"스킬":"S7"},{"제목":"한 변의 길이 a와 a²","힌트":"높이가 $\\sqrt{7}$인 정삼각형의 한 변의 길이 $a$에 대하여 $a^2$은 얼마인가?","식":["$\\frac{\\sqrt{3}}{2}a=\\sqrt{7} \\Rightarrow a=\\frac{2\\sqrt{7}}{\\sqrt{3}}$","$a^2=\\frac{28}{3}$"],"설명":"한 변이 $a$인 정삼각형의 높이는 $\\frac{\\sqrt{3}}{2}a$이다. $a=\\frac{2\\sqrt{7}}{\\sqrt{3}}$의 양변을 제곱하면 $a^2=\\frac{4\\cdot 7}{3}=\\frac{28}{3}$이고 선지 ④와 같다.","확인":"28/3","스킬":"S3"}]},"ns-fc3d5429279e":{"길":"정의대로 두 가지 거리 식에 좌표를 넣어 각각 계산해 더한다","단계":[{"제목":"좌표평면에서의 거리 계산","힌트":"첫 번째 거리 식에 $\\mathrm{A}(2,\\ 6)$, $\\mathrm{B}(5,\\ 2)$를 넣으면 $d_{U}(\\mathrm{A},\\ \\mathrm{B})$는 얼마인가?","식":["$d_{U}(\\mathrm{A},\\ \\mathrm{B})=\\sqrt{(5-2)^2+(2-6)^2}=\\sqrt{9+16}=5$"],"설명":"좌표평면에서 쓰는 보통의 두 점 사이의 거리 공식이다.","확인":"5","스킬":"C6"},{"제목":"택시 거리 계산","힌트":"$d_{T}$는 $x$축 방향 이동 거리와 $y$축 방향 이동 거리의 합이다. $d_{T}(\\mathrm{A},\\ \\mathrm{B})$는 얼마인가?","식":["$d_{T}(\\mathrm{A},\\ \\mathrm{B})=|5-2|+|2-6|=3+4=7$"],"설명":"절댓값으로 $x$좌표의 차와 $y$좌표의 차의 크기를 각각 구해 더한다.","확인":"7","스킬":"C6","고비":true},{"제목":"두 거리의 합","힌트":"$d_{U}=5$, $d_{T}=7$일 때 두 거리의 합은 얼마인가?","식":["$d_{U}(\\mathrm{A},\\ \\mathrm{B})+d_{T}(\\mathrm{A},\\ \\mathrm{B})=5+7=12$"],"설명":"합은 $12$이고 선지 ④와 같다.","확인":"12","스킬":"C6"}]},"ns-fca92d16eca3":{"길":"넓이 3등분점은 무게중심이므로 PM을 구하고 중선정리로 BM을 얻는다","단계":[{"제목":"넓이 3등분과 점 P의 정체","힌트":"세 삼각형 $\\triangle\\mathrm{PAB},\\ \\triangle\\mathrm{PBC},\\ \\triangle\\mathrm{PCA}$의 넓이가 같으면 $\\mathrm{P}$는 무엇인가? $\\overline{\\mathrm{AP}}$의 연장선이 $\\overline{\\mathrm{BC}}$와 만나는 점을 $\\mathrm{M}$이라 할 때 $\\overline{\\mathrm{PM}}$은 얼마인가?","식":["$\\overline{\\mathrm{BM}}=\\overline{\\mathrm{MC}}$","$\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PM}}=2:1 \\Rightarrow \\overline{\\mathrm{PM}}=\\frac{6}{2}=3$"],"설명":"삼각형 내부의 점 $\\mathrm{P}$가 넓이를 $3$등분하면 $\\mathrm{P}$는 무게중심이다. 무게중심은 중선을 꼭짓점 쪽에서 $2:1$로 나누므로 $\\overline{\\mathrm{AM}}$은 중선이고 $\\mathrm{M}$은 $\\overline{\\mathrm{BC}}$의 중점이다.","확인":"3","스킬":"S7","고비":true},{"제목":"중선정리로 BM 구하기","힌트":"$\\triangle\\mathrm{BPC}$에서 $\\overline{\\mathrm{PM}}$은 중선이다. $\\overline{\\mathrm{PB}}^{\\,2}+\\overline{\\mathrm{PC}}^{\\,2}=2\\left(\\overline{\\mathrm{PM}}^{\\,2}+\\overline{\\mathrm{BM}}^{\\,2}\\right)$에 값을 넣으면 $\\overline{\\mathrm{BM}}^{\\,2}$은 얼마인가?","식":["$25+49=2\\left(9+\\overline{\\mathrm{BM}}^{\\,2}\\right)$","$\\overline{\\mathrm{BM}}^{\\,2}=28$"],"설명":"$\\overline{\\mathrm{PB}}=5$, $\\overline{\\mathrm{PC}}=7$, $\\overline{\\mathrm{PM}}=3$을 넣으면 $74=18+2\\overline{\\mathrm{BM}}^{\\,2}$이다. 따라서 $\\overline{\\mathrm{BM}}^{\\,2}=28$이다.","확인":"28","스킬":"S3"},{"제목":"BC의 길이","힌트":"$\\overline{\\mathrm{BM}}^{\\,2}=28$이고 $\\mathrm{M}$이 $\\overline{\\mathrm{BC}}$의 중점이면 $\\overline{\\mathrm{BC}}$는 얼마인가?","식":["$\\overline{\\mathrm{BM}}=\\sqrt{28}=2\\sqrt{7}$","$\\overline{\\mathrm{BC}}=2\\overline{\\mathrm{BM}}=4\\sqrt{7}$"],"설명":"$\\mathrm{M}$이 $\\overline{\\mathrm{BC}}$의 중점이므로 $\\overline{\\mathrm{BC}}$는 $\\overline{\\mathrm{BM}}$의 $2$배이다. 이 값은 선지 ③과 같다.","확인":null,"스킬":"S3"}]},"ns-015887dfe9b1":{"길":"평행인 경우와 세 직선이 한 점에서 만나는 경우로 나누어 a 를 모두 찾는다","단계":[{"제목":"평행으로 삼각형이 안 생기는 경우 찾기","힌트":"두 직선이 평행하면 삼각형이 생기지 않는다. 세 쌍 중 평행이 가능한 쌍과 그때의 $a$ 는?","식":["$l\\parallel m$ 이면 $\\frac{1}{a}=\\frac{-a}{1}$ 에서 $a^{2}=-1$ 이라 불가능","$l\\parallel n$ 이면 $\\frac{a}{a}=\\frac{1}{-2}$ 가 성립하지 않아 불가능","$m\\parallel n$ 이면 $\\frac{a}{1}=\\frac{-2}{-a}$ 에서 $a^{2}=2$, $a=\\pm\\sqrt{2}$"],"설명":"두 직선 $a_1x+b_1y+c_1=0$, $a_2x+b_2y+c_2=0$ 이 평행하려면 $\\frac{a_1}{a_2}=\\frac{b_1}{b_2}\\ne\\frac{c_1}{c_2}$ 이어야 한다. $l$ 과 $m$ 은 서로 수직이고, $l$ 과 $n$ 은 $a\\ne0$ 이면 기울기가 $-a$, $\\frac{a}{2}$ 로 달라 평행할 수 없다. $m$ 과 $n$ 만 $a^{2}=2$ 일 때 평행하다.","확인":null,"스킬":"C2"},{"제목":"세 직선이 한 점에서 만나는 경우의 교점 구하기","힌트":"세 직선이 한 점에서 만나도 삼각형이 생기지 않는다. $l$ 과 $n$ 의 교점의 좌표는?","식":["$l:\\ ax+y=a+2$, $n:\\ ax-2y=4a-2$ 를 변끼리 빼면 $3y=4-3a$","$y=-a+\\frac{4}{3},\\ x=2+\\frac{2}{3a}$"],"설명":"두 식을 변끼리 빼면 $x$ 항이 사라져 $y$ 가 먼저 나온다. 이 $y$ 를 $l$ 에 넣으면 $ax=2a+\\frac{2}{3}$ 이고 $a\\ne0$ 이므로 $x$ 도 구해진다.","확인":null,"스킬":"G3"},{"제목":"교점이 m 위에 있을 조건 풀기","고비":true,"힌트":"교점이 $m$ 위에도 있으려면 $m$ 의 식에 대입한 값이 $0$ 이어야 한다. 이때 $a$ 는?","식":["$2+\\frac{2}{3a}-a\\left(-a+\\frac{4}{3}\\right)+2a-1=0$","$a^{3}+\\frac{2}{3}a^{2}+a+\\frac{2}{3}=0$","$\\left(a+\\frac{2}{3}\\right)\\left(a^{2}+1\\right)=0$ 이므로 $a=-\\frac{2}{3}$"],"설명":"정리한 식의 양변에 $a$ 를 곱하면 삼차식이 되고, $a^{2}\\left(a+\\frac{2}{3}\\right)+\\left(a+\\frac{2}{3}\\right)$ 로 묶을 수 있다. $a^{2}+1$ 은 $0$ 이 될 수 없어 실수 $a$ 는 $-\\frac{2}{3}$ 하나뿐이다.","확인":"-2/3","스킬":"G3"},{"제목":"가능한 a 의 값을 모아 곱하기","힌트":"삼각형이 안 생기는 $a$ 가 $\\sqrt{2}$, $-\\sqrt{2}$, $-\\frac{2}{3}$ 일 때 이 값들의 곱은?","식":["$\\sqrt{2}\\times\\left(-\\sqrt{2}\\right)\\times\\left(-\\frac{2}{3}\\right)=\\frac{4}{3}$"],"설명":"평행인 경우에서 $a=\\pm\\sqrt{2}$, 한 점에서 만나는 경우에서 $a=-\\frac{2}{3}$ 가 나와 값은 모두 세 개이다. 앞의 두 값의 곱이 $-2$ 이므로 여기에 $-\\frac{2}{3}$ 를 곱한다.","확인":"4/3","스킬":"C2"}]},"ns-01de17952eeb":{"길":"세 점을 t 로 적고 두 기울기가 같다는 식으로 t 를 구해 직선을 얻는다","단계":[{"제목":"t 초 후 세 점의 좌표 나타내기","힌트":"$t$ 초 후 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 의 좌표는? ($\\mathrm{C}$ 는 $y=x-1$ 위에서 속력 $\\sqrt{2}$ 로 움직인다.)","식":["$\\mathrm{A}(3t,\\ 0),\\ \\mathrm{B}(0,\\ 2t)$","$\\mathrm{C}(1+t,\\ t)$"],"설명":"$\\mathrm{A}$ 는 $x$축 위에서 $3t$, $\\mathrm{B}$ 는 $y$축 위에서 $2t$ 만큼 간다. $\\mathrm{C}$ 는 기울기가 $1$ 인 직선 위를 움직여 $x$, $y$ 가 같은 양씩 늘어난다. $x$, $y$ 가 각각 $1$ 늘면 이동 거리가 $\\sqrt{2}$ 이므로 속력 $\\sqrt{2}$ 에서는 $1$ 초에 각각 $1$ 씩 늘어난다. 그래서 $(1,\\ 0)$ 에서 $x$, $y$ 가 각각 $t$ 만큼 늘어난다.","확인":null,"스킬":"C7"},{"제목":"두 직선의 기울기 구하기","고비":true,"힌트":"세 점이 한 직선 위에 있으려면 어느 두 점을 골라도 기울기가 같아야 한다. 직선 $\\mathrm{AB}$ 와 직선 $\\mathrm{BC}$ 의 기울기는?","식":["직선 $\\mathrm{AB}$ 의 기울기 $\\frac{2t-0}{0-3t}=-\\frac{2}{3}$","직선 $\\mathrm{BC}$ 의 기울기 $\\frac{t-2t}{(1+t)-0}=-\\frac{t}{t+1}$"],"설명":"점 $\\mathrm{B}$ 를 공통으로 하는 두 직선의 기울기를 각각 구한다. 세 점이 한 직선 위에 있으면 이 두 기울기가 같아야 한다.","확인":null,"스킬":"G9"},{"제목":"기울기가 같다는 식으로 t 구하기","힌트":"두 기울기를 같다고 놓고 $t$ 를 구하면?","식":["$-\\frac{t}{t+1}=-\\frac{2}{3}$","$3t=2(t+1)$","$t=2$"],"설명":"$t>0$ 이므로 $t+1\\ne0$ 이다. 양변에 $3(t+1)$ 을 곱해 정리하면 $t$ 가 나온다.","확인":"2","스킬":"C7"},{"제목":"세 점을 지나는 직선의 방정식 구하기","힌트":"$t=2$ 일 때 $\\mathrm{A}$, $\\mathrm{B}$ 는 각각 어느 축 위의 어떤 점이고, 이 직선을 $ax+by+c=0$ 꼴로 쓰면?","식":["$\\mathrm{A}(6,\\ 0),\\ \\mathrm{B}(0,\\ 4)$","$\\frac{x}{6}+\\frac{y}{4}=1$","$2x+3y-12=0$"],"설명":"$t=2$ 를 넣으면 $\\mathrm{A}$ 는 $x$절편, $\\mathrm{B}$ 는 $y$절편이 되어 절편 꼴로 쓸 수 있다. 양변에 $12$ 를 곱해 정리하면 $a=2$, $b=3$, $c=-12$ 이다.","확인":null,"스킬":"G9"},{"제목":"3a+2b+c 의 값 계산하기","힌트":"$a=2,\\ b=3,\\ c=-12$ 를 $3a+2b+c$ 에 넣으면?","식":["$3\\times2+2\\times3+(-12)=0$"],"설명":"구한 $a$, $b$, $c$ 를 식에 그대로 넣어 계산한다. 앞의 두 항의 합이 $12$ 라서 $c$ 와 합하면 $0$ 이 된다.","확인":"0","스킬":"C7"}]},"ns-01dfd52be3e3":{"길":"ㄱㄴㄷ 을 수직·평행 조건과 지나는 점으로 하나씩 따져 옳은 것을 고른다","단계":[{"제목":"ㄱ 판정: 수직이 되는 k 의 값 구하기","힌트":"수직 조건 $a_1a_2+b_1b_2=0$ 에 두 직선의 계수를 넣으면 $k$ 는?","식":["$k\\times1+1\\times k=0$","$k=0$"],"설명":"$l$ 의 $x$, $y$ 의 계수는 $(k,\\ 1)$, $m$ 의 계수는 $(1,\\ k)$ 이다. 수직 조건에 넣으면 $2k=0$ 으로 $k$ 가 하나로 정해져 ㄱ 은 옳다.","확인":"0","스킬":"G9"},{"제목":"ㄴ 판정: 평행이 되는 k 의 값 가려내기","고비":true,"힌트":"평행 조건 $\\frac{k}{1}=\\frac{1}{k}$ 으로 나온 $k$ 를 각각 대입했을 때, 두 직선이 일치하지 않는 값은?","식":["$k^{2}=1$ 이므로 $k=\\pm1$","$k=1$ 이면 $l,\\ m$ 이 모두 $x+y+2=0$ 으로 일치","평행한 경우는 $k=-1$ 하나뿐이므로 ㄴ 은 거짓"],"설명":"평행은 만나지 않는 경우라서 두 직선이 겹치는 경우는 제외한다. $k=-1$ 이면 $l:\\ y=x$, $m:\\ y=x+2$ 로 평행하다. 그래서 평행이 되는 $k$ 는 한 개이다.","확인":"-1","스킬":"C3"},{"제목":"ㄷ 판정: 두 직선이 항상 지나는 점 찾기","힌트":"$l$, $m$ 을 각각 $k$ 에 대한 식으로 정리하면 $k$ 의 값에 관계없이 지나는 점은?","식":["$l:\\ k(x+1)+(y+1)=0$ 이므로 $(-1,\\ -1)$ 을 지남","$m:\\ (x+2)+ky=0$ 이므로 $(-2,\\ 0)$ 을 지남"],"설명":"$k$ 의 값에 관계없이 성립하려면 $k$ 의 계수와 나머지 부분이 각각 $0$ 이어야 한다. $l$ 은 $x+1=0$, $y+1=0$ 에서, $m$ 은 $x+2=0$, $y=0$ 에서 점이 정해진다.","확인":null,"스킬":"G3"},{"제목":"ㄷ 판정과 옳은 보기 고르기","힌트":"두 점 $(-1,\\ -1)$, $(-2,\\ 0)$ 을 지나는 직선의 방정식은?","식":["기울기 $\\frac{0-(-1)}{-2-(-1)}=-1$","$y=-(x+2)$, 즉 $x+y+2=0$","ㄷ 이 옳으므로 옳은 것은 ㄱ, ㄷ"],"설명":"구한 직선이 보기 ㄷ 의 $x+y+2=0$ 과 같으므로 ㄷ 은 옳다. ㄱ 과 ㄷ 이 옳고 ㄴ 은 거짓이다.","확인":null,"스킬":"C3"}]},"ns-038793553035":{"길":"OB, AC 는 점과 직선 사이 거리로, BC 는 직각삼각형으로 구해 사다리꼴 넓이를 쓴다","단계":[{"제목":"OB, AC 의 길이를 점과 직선 사이 거리로 구하기","힌트":"직선 $2x-y+b=0$ 에서 원점과 점 $\\mathrm{A}(5,\\ 0)$ 까지의 거리는?","식":["$\\overline{\\mathrm{OB}}=\\frac{|b|}{\\sqrt{5}}=\\frac{b}{\\sqrt{5}}$","$\\overline{\\mathrm{AC}}=\\frac{|10+b|}{\\sqrt{5}}=\\frac{10+b}{\\sqrt{5}}$"],"설명":"$\\mathrm{B}$, $\\mathrm{C}$ 는 수선의 발이므로 $\\overline{\\mathrm{OB}}$, $\\overline{\\mathrm{AC}}$ 는 각각 점 $\\mathrm{O}$, $\\mathrm{A}$ 와 직선 $2x-y+b=0$ 사이의 거리이다. $b>0$ 이라 절댓값 안이 모두 양수이다.","확인":null,"스킬":"S4"},{"제목":"BC 의 길이 구하기","고비":true,"힌트":"$\\mathrm{O}$ 에서 $\\overline{\\mathrm{AC}}$ 에 내린 수선의 발을 $\\mathrm{H}$ 라 하면 $\\overline{\\mathrm{BC}}=\\overline{\\mathrm{OH}}$ 이다. 직각삼각형 $\\mathrm{AOH}$ 에서 $\\overline{\\mathrm{OH}}$ 는?","식":["$\\overline{\\mathrm{BC}}=\\overline{\\mathrm{OH}}$","직선이 $x$축과 이루는 각 $\\theta$ 에서 $\\tan\\theta=2$ 이므로 $\\cos\\theta=\\frac{1}{\\sqrt{5}}$","$\\overline{\\mathrm{OH}}=5\\cos\\theta=\\sqrt{5}$"],"설명":"사각형 $\\mathrm{OHCB}$ 는 세 각이 직각이라 직사각형이고 $\\overline{\\mathrm{BC}}=\\overline{\\mathrm{OH}}$ 이다. $\\overline{\\mathrm{OH}}$ 는 직선과 평행하므로 $\\angle\\mathrm{AOH}=\\theta$ 이다. $\\tan\\theta=2$ 에서 빗변이 $\\sqrt{5}$ 인 직각삼각형으로 $\\cos\\theta$ 를 얻고 $\\overline{\\mathrm{OA}}=5$ 에 곱한다.","확인":null,"스킬":"S4"},{"제목":"사다리꼴의 넓이를 b 로 나타내기","힌트":"$\\overline{\\mathrm{OB}}\\parallel\\overline{\\mathrm{AC}}$ 이고 높이가 $\\overline{\\mathrm{BC}}$ 일 때 사각형 $\\mathrm{OACB}$ 의 넓이는?","식":["$\\square\\mathrm{OACB}=\\frac{1}{2}\\left(\\frac{b}{\\sqrt{5}}+\\frac{10+b}{\\sqrt{5}}\\right)\\times\\sqrt{5}$","$=b+5$"],"설명":"$\\overline{\\mathrm{OB}}$ 와 $\\overline{\\mathrm{AC}}$ 는 모두 직선에 수직이라 서로 평행하다. 사각형 $\\mathrm{OACB}$ 는 평행한 두 변이 $\\overline{\\mathrm{OB}}$, $\\overline{\\mathrm{AC}}$ 이고 높이가 $\\overline{\\mathrm{BC}}$ 인 사다리꼴이다.","확인":null,"스킬":"S4"},{"제목":"넓이 조건으로 b 구하기","힌트":"사각형 $\\mathrm{OACB}$ 의 넓이가 $13$ 일 때 $b$ 는?","식":["$b+5=13$","$b=8$"],"설명":"넓이를 $13$ 과 같다고 놓고 $b$ 를 구한다. $b=8$ 은 $y$절편이 양수라는 조건에 맞다.","확인":"8","스킬":"S4"}]},"ns-03f5a281af55":{"길":"AB 의 중점을 지나고 AB 에 수직인 직선을 세워 상수항 -17 에 맞춘다","단계":[{"제목":"선분 AB 의 중점과 기울기 구하기","힌트":"$\\mathrm{A}(1,\\ 3)$, $\\mathrm{B}(6,\\ -12)$ 일 때 $\\overline{\\mathrm{AB}}$ 의 기울기는? (중점도 함께 구한다.)","식":["중점 $\\left(\\frac{1+6}{2},\\ \\frac{3+(-12)}{2}\\right)=\\left(\\frac{7}{2},\\ -\\frac{9}{2}\\right)$","기울기 $\\frac{-12-3}{6-1}=-3$"],"설명":"수직이등분선은 $\\overline{\\mathrm{AB}}$ 의 중점을 지나고 $\\overline{\\mathrm{AB}}$ 와 수직이다. 그래서 중점과 $\\overline{\\mathrm{AB}}$ 의 기울기가 먼저 필요하다.","확인":"-3","스킬":"G9"},{"제목":"수직이등분선의 방정식 세우기","고비":true,"힌트":"기울기가 $-3$ 인 직선에 수직인 직선의 기울기를 쓰고, 중점을 지나는 직선의 방정식을 $ax+by-17=0$ 꼴로 맞추면?","식":["수직인 직선의 기울기 $\\frac{1}{3}$","$y+\\frac{9}{2}=\\frac{1}{3}\\left(x-\\frac{7}{2}\\right)$","$x-3y-17=0$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다. 위 식에 $6$ 을 곱하면 $2x-6y-34=0$ 이고 양변을 $2$ 로 나눈다. 상수항이 $-17$ 이므로 $ax+by-17=0$ 과 바로 비교해 $a=1$, $b=-3$ 이다.","확인":null,"스킬":"G9"},{"제목":"a-b 의 값 계산하기","힌트":"$a=1,\\ b=-3$ 일 때 $a-b$ 는?","식":["$a-b=1-(-3)=4$"],"설명":"음수를 빼면 부호가 바뀌어 더하는 계산이 된다.","확인":"4","스킬":"G9"}]},"ns-04f69fe1d25e":{"길":"꼭짓점 O 를 지나는 이등분선은 대변 AB 의 중점을 지난다는 점으로 기울기를 구한다","단계":[{"제목":"넓이를 이등분하는 직선이 지나는 점 찾기","고비":true,"힌트":"꼭짓점 $\\mathrm{O}$ 를 지나 삼각형의 넓이를 이등분하는 직선은 대변 $\\mathrm{AB}$ 의 어느 점을 지나는가?","식":["$\\mathrm{AB}$ 의 중점 $\\mathrm{M}\\left(\\frac{7+3}{2},\\ \\frac{1+3}{2}\\right)=(5,\\ 2)$"],"설명":"$\\overline{\\mathrm{AM}}=\\overline{\\mathrm{MB}}$ 이면 $\\triangle\\mathrm{OAM}$ 과 $\\triangle\\mathrm{OMB}$ 는 밑변과 높이가 같아 넓이가 같다. 그래서 $\\mathrm{O}$ 에서 $\\overline{\\mathrm{AB}}$ 의 중점으로 그은 직선이 넓이를 이등분한다.","확인":null,"스킬":"G10"},{"제목":"직선 l 의 기울기 구하기","힌트":"원점과 $(5,\\ 2)$ 를 지나는 직선의 기울기는?","식":["$\\frac{2-0}{5-0}=\\frac{2}{5}$"],"설명":"직선 $l$ 은 원점과 $\\mathrm{M}$ 을 지난다. $y$ 좌표의 차를 $x$ 좌표의 차로 나누면 기울기이다.","확인":"2/5","스킬":"G9"}]},"ns-052810e1c1c4":{"길":"두 절편이 주어지면 절편 꼴로 쓰고 일반형으로 정리한다","단계":[{"제목":"절편 꼴로 직선의 식 쓰기","고비":true,"힌트":"$x$절편이 $3$, $y$절편이 $2$ 일 때 절편 꼴 $\\frac{x}{p}+\\frac{y}{q}=1$ 의 $p$, $q$ 는?","식":["$\\frac{x}{3}+\\frac{y}{2}=1$"],"설명":"$x$절편이 $p$, $y$절편이 $q$ 인 직선은 $\\frac{x}{p}+\\frac{y}{q}=1$ 이다. 이 식은 두 점 $(3,\\ 0)$, $(0,\\ 2)$ 를 모두 지난다.","확인":null,"스킬":"G9"},{"제목":"일반형으로 정리하기","힌트":"양변에 $6$ 을 곱하고 우변을 $0$ 으로 옮기면?","식":["$2x+3y=6$","$2x+3y-6=0$"],"설명":"분모 $3$, $2$ 의 최소공배수 $6$ 을 곱하면 분수가 사라진다. 이 식은 선지 ①과 같다.","확인":null,"스킬":"G9"}]},"ns-090816d9acf4":{"길":"넓이를 구한 뒤 x=t 로 잘린 삼각형의 넓이를 t 로 쓰고 반과 같게 놓는다","단계":[{"제목":"삼각형 ABC 의 넓이 구하기","힌트":"세 변의 길이를 구해 $\\triangle\\mathrm{ABC}$ 가 어떤 삼각형인지 살피면 넓이는?","식":["$\\overline{\\mathrm{AB}}=2\\sqrt{5},\\ \\overline{\\mathrm{BC}}=\\sqrt{5},\\ \\overline{\\mathrm{AC}}=5$","$\\overline{\\mathrm{AB}}^{2}+\\overline{\\mathrm{BC}}^{2}=\\overline{\\mathrm{AC}}^{2}$ 이므로 $\\angle\\mathrm{B}=90^{\\circ}$","$\\triangle\\mathrm{ABC}=\\frac{1}{2}\\times2\\sqrt{5}\\times\\sqrt{5}=5$"],"설명":"피타고라스 정리의 역으로 $\\overline{\\mathrm{AC}}$ 가 빗변인 직각삼각형임을 알 수 있다. 직각을 낀 두 변이 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{BC}}$ 이므로 넓이가 바로 나온다.","확인":"5","스킬":"G10"},{"제목":"직선 AC, AB 의 방정식 구하기","힌트":"두 점의 좌표로 직선 $\\mathrm{AC}$, $\\mathrm{AB}$ 의 방정식을 세우면?","식":["$\\mathrm{AC}:\\ y=\\frac{5-1}{4-1}(x-1)+1=\\frac{4}{3}x-\\frac{1}{3}$","$\\mathrm{AB}:\\ y=\\frac{3-1}{5-1}(x-1)+1=\\frac{1}{2}x+\\frac{1}{2}$"],"설명":"$y$축에 평행한 직선 $x=t$ 가 두 직선과 만나는 점의 $y$ 좌표를 구하려고 두 직선의 식을 먼저 세운다.","확인":null,"스킬":"G9"},{"제목":"x=t 로 잘린 삼각형의 넓이를 t 로 나타내기","고비":true,"힌트":"$x=t\\ (1<t<4)$ 가 직선 $\\mathrm{AC}$, $\\mathrm{AB}$ 와 만나는 점을 $\\mathrm{P}$, $\\mathrm{Q}$ 라 할 때 $\\triangle\\mathrm{APQ}$ 의 넓이는?","식":["$\\mathrm{P}\\left(t,\\ \\frac{4}{3}t-\\frac{1}{3}\\right),\\ \\mathrm{Q}\\left(t,\\ \\frac{1}{2}t+\\frac{1}{2}\\right)$","$\\triangle\\mathrm{APQ}=\\frac{1}{2}\\times(t-1)\\times\\frac{5}{6}(t-1)=\\frac{5}{12}(t-1)^{2}$"],"설명":"$\\overline{\\mathrm{PQ}}$ 는 $y$축에 평행하므로 밑변으로 보고, 높이는 $\\mathrm{A}$ 의 $x$ 좌표 $1$ 과 $t$ 의 차인 $t-1$ 이다. $\\overline{\\mathrm{PQ}}=\\left(\\frac{4}{3}t-\\frac{1}{3}\\right)-\\left(\\frac{1}{2}t+\\frac{1}{2}\\right)=\\frac{5}{6}(t-1)$ 이다. $t$ 가 $4$ 보다 작아야 직선이 $\\overline{\\mathrm{AC}}$ 와 만난다.","확인":null,"스킬":"G10"},{"제목":"넓이를 이등분하는 직선 구하기","힌트":"$\\triangle\\mathrm{APQ}$ 의 넓이가 $\\triangle\\mathrm{ABC}$ 의 넓이의 반일 때 직선의 방정식은?","식":["$\\frac{5}{12}(t-1)^{2}=\\frac{1}{2}\\times5$","$(t-1)^{2}=6,\\ t=1+\\sqrt{6}$","직선 $x=1+\\sqrt{6}$"],"설명":"$1<t<4$ 에서 $t-1>0$ 이므로 $t-1=\\sqrt{6}$ 이다. $1+\\sqrt{6}$ 은 약 $3.4$ 로 범위 안에 있다.","확인":null,"스킬":"G10"}]},"ns-0a415420e972":{"길":"평행 두 가지와 세 직선이 한 점에서 만나는 경우로 나누어 a 를 모두 더한다","단계":[{"제목":"앞의 두 직선의 교점 구하기","힌트":"$2x-y+1=0$ 과 $3x+y-6=0$ 의 교점은?","식":["두 식을 더하면 $5x-5=0$, $x=1$","$y=2\\times1+1=3$, 교점 $(1,\\ 3)$"],"설명":"$y$ 항의 계수가 $-1$, $1$ 이라 두 식을 더하면 $y$ 가 사라진다. 구한 $x$ 를 첫 식에 넣어 $y$ 를 구한다.","확인":null,"스킬":"G1"},{"제목":"평행해서 삼각형이 안 생기는 a 구하기","힌트":"세 번째 직선의 기울기가 앞의 두 직선의 기울기 $2$, $-3$ 과 각각 같아지는 $a$ 는?","식":["세 번째 직선의 기울기 $-\\frac{1}{a}\\ (a\\ne0)$","$-\\frac{1}{a}=2$ 에서 $a=-\\frac{1}{2}$","$-\\frac{1}{a}=-3$ 에서 $a=\\frac{1}{3}$"],"설명":"$2x-y+1=0$ 의 기울기는 $2$, $3x+y-6=0$ 의 기울기는 $-3$ 이다. $a=0$ 이면 세 번째 직선이 $y$축에 평행해 어느 쪽과도 평행하지 않으므로 $a\\ne0$ 에서 따진다.","확인":null,"스킬":"C2"},{"제목":"교점을 지나서 삼각형이 안 생기는 a 구하기","고비":true,"힌트":"세 직선이 한 점에서 만나도 삼각형이 생기지 않는다. 교점 $(1,\\ 3)$ 이 세 번째 직선 위에 있게 하는 $a$ 는?","식":["$1+a\\times3+3a+1=0$","$6a+2=0$, $a=-\\frac{1}{3}$"],"설명":"교점이 세 번째 직선 위에 있으면 세 직선이 한 점에서 만난다. $x=1$, $y=3$ 을 세 번째 직선의 식에 넣는다.","확인":"-1/3","스킬":"G3"},{"제목":"구한 a 의 값 모두 더하기","힌트":"삼각형이 안 생기는 $a$ 가 $-\\frac{1}{2}$, $\\frac{1}{3}$, $-\\frac{1}{3}$ 일 때 합은?","식":["$-\\frac{1}{2}+\\frac{1}{3}+\\left(-\\frac{1}{3}\\right)=-\\frac{1}{2}$"],"설명":"뒤의 두 값은 부호만 달라 합이 $0$ 이 되므로 $-\\frac{1}{2}$ 만 남는다.","확인":"-1/2","스킬":"C2"}]},"ns-0a6a306c79fc":{"길":"앞의 두 직선이 수직이 아니므로 세 번째 직선이 둘 중 하나와 수직인 a 를 구한다","단계":[{"제목":"앞의 두 직선이 수직인지 확인하기","고비":true,"힌트":"수직 조건 $a_1a_2+b_1b_2=0$ 에 $x-3y+11=0$, $x+2y-14=0$ 의 계수를 넣으면 값은?","식":["$1\\times1+(-3)\\times2=-5\\ne0$","두 직선은 수직이 아니다"],"설명":"직각삼각형이 되려면 세 직선 중 두 직선이 수직이어야 한다. 앞의 두 직선이 수직이 아니므로 세 번째 직선이 둘 중 하나와 수직이어야 한다.","확인":"-5","스킬":"G9"},{"제목":"세 번째 직선이 수직이 되는 a 구하기","힌트":"$ax-y-7=0$ 이 $x-3y+11=0$, $x+2y-14=0$ 과 각각 수직일 조건에서 $a$ 는?","식":["$x-3y+11=0$ 과 수직: $1\\times a+(-3)\\times(-1)=0$, $a=-3$","$x+2y-14=0$ 과 수직: $1\\times a+2\\times(-1)=0$, $a=2$"],"설명":"수직 조건에 계수를 넣어 두 경우의 $a$ 를 따로 구한다. 두 경우 모두 세 직선이 한 점에서 만나지 않아 삼각형을 이룬다.","확인":null,"스킬":"G9"},{"제목":"a 의 값의 합 구하기","힌트":"$a=-3$, $a=2$ 일 때 두 값의 합은?","식":["$-3+2=-1$"],"설명":"구한 두 값을 더한다.","확인":"-1","스킬":"G9"}]},"ns-0a7385d052ab":{"길":"식을 원점 중심의 원의 반지름 꼴로 보고 꺾인 그래프에 접하는 경우의 r 를 b 로 쓴다","단계":[{"제목":"식을 원의 반지름 꼴로 바꾸기","힌트":"$a-b=x$, $|a+3|+b^{2}=y$ 로 놓으면 주어진 식은 어떤 도형의 반지름의 제곱이 되는가?","식":["$a-b=x,\\ |a+3|+b^{2}=y$","$x^{2}+y^{2}=r^{2}$ 은 중심이 원점인 원"],"설명":"주어진 식은 $x^{2}+y^{2}$ 이다. $(x,\\ y)$ 가 움직이는 도형에 닿는 가장 작은 원의 $r^{2}$ 이 구하는 최솟값이다.","확인":null,"스킬":"S4"},{"제목":"y 를 x 의 식으로 나타내기","힌트":"$a=x+b$ 를 $y=|a+3|+b^{2}$ 에 넣으면 $y$ 는 $x$ 의 어떤 식인가?","식":["$a=x+b$ 이므로 $y=|x+b+3|+b^{2}$","꺾인점 $(-b-3,\\ b^{2})$"],"설명":"$b$ 를 고정하면 $(x,\\ y)$ 는 이 꺾인 그래프 위를 움직인다. 꺾인점은 $x+b+3=0$ 에서 생겨 좌표가 $(-b-3,\\ b^{2})$ 이고, $b$ 가 변하면 이 점은 $y=(x+3)^{2}$ 위를 따라 움직인다.","확인":null,"스킬":"G5"},{"제목":"접할 때의 반지름을 b 로 나타내기","고비":true,"힌트":"원 $x^{2}+y^{2}=r^{2}$ 이 그래프의 오른쪽 직선 $y=x+b^{2}+b+3$ 에 접할 때 $r$ 을 $b$ 로 나타내면?","식":["$y=x+b^{2}+b+3$ 은 $x-y+b^{2}+b+3=0$","$r=\\frac{|b^{2}+b+3|}{\\sqrt{2}}$"],"설명":"그림에서 원이 처음 닿는 곳은 꺾인 그래프의 오른쪽 직선 부분이다. 원이 직선에 접하면 중심 $(0,\\ 0)$ 에서 직선까지의 거리가 반지름과 같다.","확인":null,"스킬":"S4"},{"제목":"b²+b+3 의 최솟값 구하기","힌트":"$b^{2}+b+3$ 을 완전제곱 꼴로 고치면 최솟값은?","식":["$b^{2}+b+3=\\left(b+\\frac{1}{2}\\right)^{2}+\\frac{11}{4}$","$b^{2}+b+3\\ge\\frac{11}{4}$"],"설명":"$b$ 는 임의의 실수이므로 제곱 부분이 $0$ 일 때 가장 작다. $b=-\\frac{1}{2}$ 에서 $b^{2}+b+3$ 이 가장 작아 $r$ 도 가장 작다.","확인":"11/4","스킬":"A6"},{"제목":"r² 의 최솟값 구하기","힌트":"$r\\ge\\frac{11}{4\\sqrt{2}}$ 일 때 $r^{2}$ 의 최솟값은?","식":["$r^{2}\\ge\\frac{\\left(\\frac{11}{4}\\right)^{2}}{2}$","$r^{2}\\ge\\frac{121}{32}$"],"설명":"$r=\\frac{b^{2}+b+3}{\\sqrt{2}}$ 이고 $b^{2}+b+3>0$ 이다. 양변을 제곱하면 분모는 $2$, 분자는 $\\left(\\frac{11}{4}\\right)^{2}$ 이 된다.","확인":"121/32","스킬":"A6"},{"제목":"m+n 의 값 구하기","힌트":"최솟값 $\\frac{n}{m}=\\frac{121}{32}$ 이고 $m$, $n$ 이 서로소일 때 $m+n$ 은?","식":["$121=11^{2},\\ 32=2^{5}$ 는 서로소이므로 $m=32,\\ n=121$","$m+n=153$"],"설명":"$121$ 과 $32$ 는 공통 소인수가 없어 이미 기약분수이다. 분모가 $m$, 분자가 $n$ 이다.","확인":"153","스킬":"A6"}]},"ns-0abaa3bd8217":{"길":"k 로 묶어 정점을 찾고 ㉠~㉣ 을 하나씩 따져 옳은 것을 고른다","단계":[{"제목":"㉠ 판정: 항상 지나는 점 찾기","힌트":"식을 $k$ 로 묶으면 $2x-y-2=0$ 과 $x+y-4=0$ 이 모두 성립하는 점은?","식":["두 식을 더하면 $3x-6=0$, $x=2$","$y=2$ 이므로 $k$ 의 값에 관계없이 $(2,\\ 2)$ 를 지남"],"설명":"$k$ 의 값에 관계없이 성립하려면 $k$ 의 계수 $x+y-4$ 와 나머지 $2x-y-2$ 가 모두 $0$ 이어야 한다. 두 직선의 교점이 그 점이므로 ㉠ 은 옳다.","확인":null,"스킬":"G3"},{"제목":"㉡ 판정: k 에 값을 넣어 직선 만들기","힌트":"직선 $2x-y=2$ 가 되려면 $k$ 는 어떤 값이어야 하는가?","식":["$k=0$ 이면 $2x-y-2=0$, 즉 $2x-y=2$","㉡ 은 옳다"],"설명":"$k$ 에 $0$ 을 넣으면 $k$ 가 붙은 항이 사라져 $2x-y-2=0$ 만 남는다.","확인":"0","스킬":"G3"},{"제목":"㉢ 판정: 나타낼 수 없는 직선 찾기","고비":true,"힌트":"점 $(2,\\ 2)$ 를 지나는 직선 $x+y-4=0$ 을 이 꼴로 나타낼 수 있는가?","식":["식을 정리하면 $(2+k)x+(k-1)y-2-4k=0$","$x+y-4=0$ 이 되려면 $2+k=k-1$ 이어야 하는데 불가능","㉢ 은 거짓"],"설명":"$x+y-4=0$ 은 $x$, $y$ 의 계수가 같아야 하는데 이 식에서는 $x$ 의 계수가 $y$ 의 계수보다 항상 $3$ 크다. 점 $(2,\\ 2)$ 를 지나는 직선이어도 나타낼 수 없는 직선이 있다.","확인":null,"스킬":"C3"},{"제목":"㉣ 판정과 옳은 보기 고르기","힌트":"직선 $x+y=0$ 과 평행해지는 $k$ 가 있는가?","식":["평행 조건 $(2+k)\\times1-1\\times(k-1)=0$ 인데 좌변은 항상 $3$","항상 평행하지 않아 한 점에서 만나므로 ㉣ 은 옳다","옳은 것은 ㉠, ㉡, ㉣"],"설명":"두 직선이 평행하지도 겹치지도 않으면 한 점에서 만난다. ㉠, ㉡, ㉣ 이 옳고 ㉢ 은 거짓이다.","확인":null,"스킬":"C3"}]},"ns-0ae4b9d2fa8d":{"길":"AD 의 중점 M 으로 중선정리를 써서 MP 가 최소인 수선의 발을 찾는다","단계":[{"제목":"꼭짓점 D, C 의 좌표 구하기","힌트":"$\\overline{\\mathrm{AB}}$ 에 수직이고 길이가 같은 선분을 그으면 $\\mathrm{D}$, $\\mathrm{C}$ 의 좌표는?","식":["$\\mathrm{A}(0,\\ 2)$ 에서 $x$ 로 $2$, $y$ 로 $1$ 이동하면 $\\mathrm{D}(2,\\ 3)$","$\\mathrm{B}(1,\\ 0)$ 에서 같이 이동하면 $\\mathrm{C}(3,\\ 1)$"],"설명":"$\\overline{\\mathrm{AB}}$ 는 $x$ 로 $1$, $y$ 로 $-2$ 만큼 가는 선분이다. 이 선분에 수직이고 길이가 같은 선분은 $x$ 로 $2$, $y$ 로 $1$ 만큼 가는 선분이다. 반대 방향이면 $\\mathrm{D}$ 가 제$1$사분면 밖이므로 그림처럼 오른쪽 위로 간다.","확인":null,"스킬":"S4"},{"제목":"직선 l 의 방정식 구하기","힌트":"$\\overline{\\mathrm{DC}}$ 의 중점과 $\\mathrm{B}$ 를 지나는 직선의 방정식은?","식":["$\\overline{\\mathrm{DC}}$ 의 중점 $\\left(\\frac{5}{2},\\ 2\\right)$","기울기 $\\frac{2-0}{\\frac{5}{2}-1}=\\frac{4}{3}$","$l:\\ 4x-3y-4=0$"],"설명":"$\\mathrm{B}(1,\\ 0)$ 과 중점을 이어 기울기를 구하고 점 $\\mathrm{B}$ 를 지나는 식을 세운다. $y=\\frac{4}{3}(x-1)$ 의 양변에 $3$ 을 곱해 정리한다.","확인":null,"스킬":"G9"},{"제목":"중선정리로 AP²+DP² 를 MP 로 나타내기","고비":true,"힌트":"$\\overline{\\mathrm{AD}}$ 의 중점을 $\\mathrm{M}$ 이라 할 때 $\\overline{\\mathrm{AP}}^{2}+\\overline{\\mathrm{DP}}^{2}$ 을 $\\overline{\\mathrm{MP}}$ 로 나타내면?","식":["$\\mathrm{M}\\left(1,\\ \\frac{5}{2}\\right),\\ \\overline{\\mathrm{AM}}^{2}=\\frac{5}{4}$","$\\overline{\\mathrm{AP}}^{2}+\\overline{\\mathrm{DP}}^{2}=2\\left(\\overline{\\mathrm{AM}}^{2}+\\overline{\\mathrm{MP}}^{2}\\right)=2\\left(\\frac{5}{4}+\\overline{\\mathrm{MP}}^{2}\\right)$"],"설명":"중선정리는 삼각형 $\\mathrm{PAD}$ 에서 $\\overline{\\mathrm{PA}}^{2}+\\overline{\\mathrm{PD}}^{2}=2\\left(\\overline{\\mathrm{AM}}^{2}+\\overline{\\mathrm{PM}}^{2}\\right)$ 이 성립한다는 것이다. $\\overline{\\mathrm{AD}}=\\sqrt{5}$ 이므로 $\\overline{\\mathrm{AM}}^{2}=\\frac{5}{4}$ 이다. 그래서 $\\overline{\\mathrm{MP}}$ 가 최소일 때 구하는 값이 최소이다.","확인":null,"스킬":"S4"},{"제목":"MP 가 최소일 때 MP² 구하기","힌트":"$\\mathrm{P}$ 가 직선 $l$ 위를 움직일 때 $\\overline{\\mathrm{MP}}$ 가 최소가 되는 경우의 $\\overline{\\mathrm{MP}}^{2}$ 은?","식":["$\\mathrm{P}$ 가 $\\mathrm{M}$ 에서 $l$ 에 내린 수선의 발일 때 최소","$\\overline{\\mathrm{MP}}^{2}=\\frac{\\left(4\\times1-3\\times\\frac{5}{2}-4\\right)^{2}}{4^{2}+3^{2}}=\\frac{9}{4}$"],"설명":"점과 직선 사이의 거리가 최단 거리이다. 거리 공식에 $\\mathrm{M}\\left(1,\\ \\frac{5}{2}\\right)$ 을 넣으면 분자 안이 $-\\frac{15}{2}$ 이고, 제곱한 $\\frac{225}{4}$ 를 분모 $25$ 로 나누면 $\\frac{9}{4}$ 이다.","확인":"9/4","스킬":"A6"},{"제목":"구하는 최솟값 계산하기","힌트":"$\\overline{\\mathrm{MP}}^{2}=\\frac{9}{4}$ 를 $2\\left(\\frac{5}{4}+\\overline{\\mathrm{MP}}^{2}\\right)$ 에 넣으면?","식":["$2\\left(\\frac{5}{4}+\\frac{9}{4}\\right)=2\\times\\frac{7}{2}=7$"],"설명":"괄호 안의 분수를 먼저 더하면 $\\frac{14}{4}=\\frac{7}{2}$ 이다. 여기에 $2$ 를 곱한다.","확인":"7","스킬":"A6"}]},"ns-0b625dde9f04":{"길":"지름의 원주각이 직각임을 써서 두 직선의 기울기의 곱을 -1 로 놓는다","단계":[{"제목":"AP, BP 의 기울기의 곱 알아내기","고비":true,"힌트":"선분 $\\mathrm{AB}$ 는 원의 지름이다. 원 위의 점 $\\mathrm{P}$ 에서 두 직선 $\\mathrm{AP}$, $\\mathrm{BP}$ 의 기울기의 곱은?","식":["$\\overline{\\mathrm{AB}}$ 는 원 $x^{2}+y^{2}=16$ 의 지름이므로 $\\angle\\mathrm{APB}=90^{\\circ}$","직선 $\\mathrm{AP}$ 의 기울기 $\\times$ 직선 $\\mathrm{BP}$ 의 기울기 $=-1$"],"설명":"지름에 대한 원주각은 $90^{\\circ}$ 이다. 수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":"-1","스킬":"S5"},{"제목":"두 직선의 기울기를 OQ, OR 로 나타내기","힌트":"직선 $\\mathrm{AP}$ 는 $\\mathrm{A}(-4,\\ 0)$ 과 $\\mathrm{Q}$ 를, 직선 $\\mathrm{BP}$ 는 $\\mathrm{B}(4,\\ 0)$ 과 $\\mathrm{R}$ 을 지난다. 두 기울기는?","식":["직선 $\\mathrm{AP}$ 의 기울기 $\\frac{\\overline{\\mathrm{OQ}}-0}{0-(-4)}=\\frac{\\overline{\\mathrm{OQ}}}{4}$","직선 $\\mathrm{BP}$ 의 기울기 $\\frac{\\overline{\\mathrm{OR}}-0}{0-4}=-\\frac{\\overline{\\mathrm{OR}}}{4}$"],"설명":"그림에서 $\\mathrm{Q}$, $\\mathrm{R}$ 은 $y$축의 양의 부분에 있어 $y$ 좌표가 각각 $\\overline{\\mathrm{OQ}}$, $\\overline{\\mathrm{OR}}$ 이다. 두 점을 지나는 직선의 기울기를 좌표의 차로 구한다.","확인":null,"스킬":"G9"},{"제목":"기울기의 곱으로 OQ·OR 구하기","힌트":"두 기울기의 곱이 $-1$ 일 때 $\\overline{\\mathrm{OQ}}\\cdot\\overline{\\mathrm{OR}}$ 의 값은?","식":["$\\frac{\\overline{\\mathrm{OQ}}}{4}\\times\\left(-\\frac{\\overline{\\mathrm{OR}}}{4}\\right)=-1$","$\\overline{\\mathrm{OQ}}\\cdot\\overline{\\mathrm{OR}}=16$"],"설명":"양변의 부호를 맞추면 $\\frac{\\overline{\\mathrm{OQ}}\\cdot\\overline{\\mathrm{OR}}}{16}=1$ 이다. 점 $\\mathrm{P}$ 의 위치에 관계없이 같은 값이 나온다.","확인":"16","스킬":"G9"}]},"ns-0ccd6e58ca8e":{"길":"직선을 일반형으로 고쳐 점과 직선 사이의 거리 공식에 넣는다","단계":[{"제목":"직선을 일반형으로 바꾸기","고비":true,"힌트":"직선 $y=x-1$ 을 $ax+by+c=0$ 꼴로 쓰면?","식":["$y=x-1$ 에서 $x-y-1=0$"],"설명":"거리 공식은 $ax+by+c=0$ 꼴에서 쓴다. 우변의 항을 모두 좌변으로 옮긴다.","확인":null,"스킬":"S4"},{"제목":"점과 직선 사이의 거리 구하기","힌트":"점 $(1,\\ 2)$ 와 직선 $x-y-1=0$ 사이의 거리는?","식":["$\\frac{|1\\times1+(-1)\\times2-1|}{\\sqrt{1^{2}+(-1)^{2}}}=\\frac{2}{\\sqrt{2}}$","$=\\sqrt{2}$"],"설명":"분자는 점의 좌표를 직선의 식에 넣은 값의 절댓값이고, 분모는 $x$, $y$ 의 계수의 제곱의 합의 제곱근이다. $\\frac{2}{\\sqrt{2}}$ 는 분모를 유리화하면 $\\sqrt{2}$ 이다.","확인":null,"스킬":"S4"}]},"ns-0cffc314256d":{"길":"수직 조건으로 k 를 구하고 정점 A 와 두 x절편으로 삼각형 넓이를 계산한다","단계":[{"제목":"두 직선을 x, y 에 대해 정리하기","힌트":"$l$, $m$ 을 $x$, $y$ 의 계수와 상수항으로 나누어 쓰면?","식":["$l:\\ (k+1)x+(2k-1)y-k+2=0$","$m:\\ (k+1)x+(2-k)y+2k-1=0$"],"설명":"괄호를 풀어 $x$ 항, $y$ 항, 상수항끼리 모은다. $m$ 은 $x+2y-1$ 의 계수가 $1$, $x-y+2$ 의 계수가 $k$ 이다.","확인":null,"스킬":"G3"},{"제목":"수직 조건으로 k 구하기","고비":true,"힌트":"두 직선의 기울기의 곱이 $-1$ 이라는 식에서 $k$ 는? ($k>1$)","식":["$-\\frac{k+1}{2k-1}\\times\\left(-\\frac{k+1}{2-k}\\right)=-1$","$k^{2}+2k+1=2k^{2}-5k+2$, 즉 $k^{2}-7k+1=0$","$k>1$ 이므로 $k=\\frac{7+3\\sqrt{5}}{2}$"],"설명":"직선 $ax+by+c=0$ 의 기울기는 $-\\frac{a}{b}$ 이다. 분모를 없애 정리하면 이차방정식이 되고, 근의 공식으로 푼 두 근 $\\frac{7\\pm3\\sqrt{5}}{2}$ 중 $k>1$ 인 것을 택한다.","확인":null,"스킬":"G9"},{"제목":"두 직선의 교점 A 구하기","힌트":"두 식을 변끼리 빼서 $y$ 를 먼저 구하면 교점 $\\mathrm{A}$ 의 좌표는?","식":["$l-m:\\ (3k-3)y+(3-3k)=0$ 이므로 $y=1$","$x=-1$, $\\mathrm{A}(-1,\\ 1)$"],"설명":"$k>1$ 이라 $3k-3\\ne0$ 이어서 $y=1$ 이 나온다. 이 $y$ 를 $l$ 의 식에 넣으면 $(k+1)x=-k-1$ 이므로 $x=-1$ 이다.","확인":null,"스킬":"G3"},{"제목":"x축과 만나는 점 B, C 구하기","힌트":"$l$, $m$ 에 $y=0$ 을 넣으면 $\\mathrm{B}$, $\\mathrm{C}$ 의 $x$ 좌표는?","식":["$l:\\ (k+1)x-k+2=0$ 에서 $\\mathrm{B}\\left(\\frac{k-2}{k+1},\\ 0\\right)$","$m:\\ (k+1)x+2k-1=0$ 에서 $\\mathrm{C}\\left(\\frac{1-2k}{k+1},\\ 0\\right)$"],"설명":"$x$축과 만나는 점은 $y=0$ 일 때의 점이다. 각 식에서 $x$ 를 구한다.","확인":null,"스킬":"G3"},{"제목":"삼각형 ABC 의 넓이 구하기","힌트":"밑변을 $\\overline{\\mathrm{BC}}$, 높이를 $\\mathrm{A}$ 의 $y$ 좌표로 보고 $k$ 를 넣으면 넓이는?","식":["$\\overline{\\mathrm{BC}}=\\left|\\frac{3-3k}{k+1}\\right|,\\ \\triangle\\mathrm{ABC}=\\frac{1}{2}\\times\\left|\\frac{3-3k}{k+1}\\right|\\times1$","$k=\\frac{7+3\\sqrt{5}}{2}$ 를 넣으면 $\\frac{3}{2}\\times\\frac{5+3\\sqrt{5}}{9+3\\sqrt{5}}$","$=\\frac{3}{2}\\times\\frac{\\sqrt{5}}{3}=\\frac{\\sqrt{5}}{2}$"],"설명":"$\\overline{\\mathrm{BC}}$ 는 $x$ 좌표의 차이고 $\\mathrm{A}$ 의 $y$ 좌표가 $1$ 이라 높이가 $1$ 이다. $\\frac{5+3\\sqrt{5}}{9+3\\sqrt{5}}$ 의 분모를 유리화하면 $\\frac{12\\sqrt{5}}{36}=\\frac{\\sqrt{5}}{3}$ 이다.","확인":null,"스킬":"G10"}]},"ns-0da7e8f6cc62":{"길":"점과 직선 사이의 거리 공식에 넣고 절댓값을 풀어 양수 a 를 고른다","단계":[{"제목":"거리 공식으로 식 세우기","힌트":"점 $(4,\\ a)$ 와 직선 $x+2y-10=0$ 사이의 거리를 공식에 넣고, 분모를 없애면 절댓값 안의 식은 얼마와 같은가?","식":["$\\frac{|4+2a-10|}{\\sqrt{1^{2}+2^{2}}}=4\\sqrt{5}$","$|2a-6|=4\\sqrt{5}\\times\\sqrt{5}=20$"],"설명":"분모가 $\\sqrt{5}$ 이므로 양변에 $\\sqrt{5}$ 를 곱하면 우변이 $4\\sqrt{5}\\times\\sqrt{5}=20$ 이 된다.","확인":"20","스킬":"S4"},{"제목":"절댓값을 풀어 양수 a 고르기","고비":true,"힌트":"$|2a-6|=20$ 의 두 해 중 $a>0$ 인 것은?","식":["$2a-6=20$ 또는 $2a-6=-20$","$a=13$ 또는 $a=-7$","$a>0$ 이므로 $a=13$"],"설명":"절댓값이 $20$ 이면 안의 식은 $20$ 또는 $-20$ 이다. 양수라는 조건으로 한 값만 남긴다.","확인":"13","스킬":"S4"}]},"ns-0fc77c501c6a":{"길":"각의 내부에서 거리의 합이 일정한 직선을 구하고 원점에서 그 직선까지의 거리를 본다","단계":[{"제목":"P 에서 두 직선까지의 거리 나타내기","힌트":"$\\mathrm{P}(x,\\ y)$ 에서 직선 $\\mathrm{OA}$ 와 직선 $\\mathrm{OB}$ 까지의 거리는?","식":["직선 $\\mathrm{OA}$ 는 $y=0$ 이므로 거리 $y$","직선 $\\mathrm{OB}$ 는 $\\sqrt{3}x-y=0$ 이므로 거리 $\\frac{|\\sqrt{3}x-y|}{2}$"],"설명":"$\\mathrm{OA}$ 는 $x$축이라 거리는 $y$ 좌표이다. $\\mathrm{OB}$ 는 원점과 $(1,\\ \\sqrt{3})$ 을 지나므로 기울기가 $\\sqrt{3}$ 이고, 분모는 $\\sqrt{(\\sqrt{3})^{2}+(-1)^{2}}=2$ 이다.","확인":null,"스킬":"S4"},{"제목":"각의 내부 조건으로 거리의 합을 직선의 식으로 쓰기","고비":true,"힌트":"$\\mathrm{P}$ 가 $\\angle\\mathrm{AOB}$ 의 내부에 있을 때 $\\sqrt{3}x-y$ 의 부호를 알면 거리의 합이 $2$ 라는 식은?","식":["내부이면 $y>0$ 이고 $\\mathrm{OB}$ 의 아래쪽이라 $\\sqrt{3}x-y>0$","$y+\\frac{\\sqrt{3}x-y}{2}=2$","$\\sqrt{3}x+y=4$"],"설명":"$\\mathrm{OB}$ 아래쪽의 점은 $y<\\sqrt{3}x$ 라 절댓값 안이 양수이다. 부호가 정해지므로 절댓값을 그대로 벗길 수 있고, $2$ 를 곱해 정리하면 직선의 식이 나온다.","확인":null,"스킬":"C2"},{"제목":"원점에서 직선까지의 최단 거리 구하기","힌트":"$\\mathrm{P}$ 가 직선 $\\sqrt{3}x+y-4=0$ 위를 움직일 때 $\\overline{\\mathrm{OP}}$ 의 최솟값은?","식":["원점과 직선 사이의 거리 $\\frac{|-4|}{\\sqrt{(\\sqrt{3})^{2}+1^{2}}}=2$","수선의 발 $(\\sqrt{3},\\ 1)$ 은 $0<y<\\sqrt{3}x$ 를 만족하므로 각의 내부에 있다"],"설명":"점 $\\mathrm{P}$ 가 직선 위에 있으므로 $\\overline{\\mathrm{OP}}$ 는 원점에서 직선까지의 거리일 때 가장 짧다. 수선의 발이 각의 내부에 있으므로 이 거리 $2$ 에 실제로 도달한다.","확인":"2","스킬":"S4"}]},"ns-10e8b4a08b54":{"길":"영역을 그리고 분수식을 (-4, 2) 와 잇는 직선의 기울기로 읽어 꼭짓점에서 비교한다","단계":[{"제목":"부등식이 나타내는 영역의 꼭짓점 구하기","힌트":"$|x-2|\\le4$, $|y-2|\\le4$ 로 정사각형을 잡고 두 직선 $y=x+3$, $y=x-3$ 사이를 고르면 영역의 꼭짓점은?","식":["$-2\\le x\\le6,\\ -2\\le y\\le6$ 이고 $x-3\\le y\\le x+3$","꼭짓점 $(-2,\\ -2),\\ (-2,\\ 1),\\ (3,\\ 6),\\ (6,\\ 6),\\ (6,\\ 3),\\ (1,\\ -2)$"],"설명":"$y=x+3$ 이 $x=-2$, $y=6$ 과 만나는 점이 $(-2,\\ 1)$, $(3,\\ 6)$ 이고, $y=x-3$ 이 $x=6$, $y=-2$ 와 만나는 점이 $(6,\\ 3)$, $(1,\\ -2)$ 이다. 정사각형의 꼭짓점 중 $(-2,\\ -2)$, $(6,\\ 6)$ 은 두 직선 사이에 있어 그대로 남는다.","확인":null,"스킬":"G6"},{"제목":"분수식을 직선의 기울기로 읽기","고비":true,"힌트":"$\\frac{y-2}{x+4}$ 는 점 $(x,\\ y)$ 와 어떤 점을 이은 직선의 기울기인가?","식":["$\\frac{y-2}{x+4}=\\frac{y-2}{x-(-4)}$","점 $(x,\\ y)$ 와 점 $(-4,\\ 2)$ 를 이은 직선의 기울기"],"설명":"두 점 $(x_1,\\ y_1)$, $(x_2,\\ y_2)$ 를 지나는 직선의 기울기는 $\\frac{y_2-y_1}{x_2-x_1}$ 이다. 영역에서 $x\\ge-2$ 이므로 $x+4>0$ 이고 기울기가 항상 정해진다. 볼록한 영역에서 기울기의 최대·최소는 꼭짓점에서 생긴다.","확인":null,"스킬":"G9"},{"제목":"기울기의 최댓값 구하기","힌트":"$(-4,\\ 2)$ 와 각 꼭짓점을 이은 기울기 중 가장 큰 값은?","식":["$(3,\\ 6)$ 에서 $\\frac{6-2}{3+4}=\\frac{4}{7}$","$(6,\\ 6)$ 에서 $\\frac{2}{5}$, $(6,\\ 3)$ 에서 $\\frac{1}{10}$ 이므로 최댓값은 $\\frac{4}{7}$"],"설명":"음수인 기울기는 제외하고 양수인 세 꼭짓점의 기울기를 비교한다. $\\frac{4}{7}$ 가 가장 크다.","확인":"4/7","스킬":"G9"},{"제목":"기울기의 최솟값 구하기","힌트":"$(-4,\\ 2)$ 와 각 꼭짓점을 이은 기울기 중 가장 작은 값은?","식":["$(-2,\\ -2)$ 에서 $\\frac{-2-2}{-2+4}=-2$","$(-2,\\ 1)$ 에서 $-\\frac{1}{2}$, $(1,\\ -2)$ 에서 $-\\frac{4}{5}$ 이므로 최솟값은 $-2$"],"설명":"음수인 세 꼭짓점의 기울기를 비교한다. $(-2,\\ -2)$ 에서 직선이 가장 가파르게 내려간다.","확인":"-2","스킬":"G9"},{"제목":"최댓값과 최솟값의 합 구하기","힌트":"최댓값 $\\frac{4}{7}$ 와 최솟값 $-2$ 의 합은?","식":["$\\frac{4}{7}+(-2)=-\\frac{10}{7}$"],"설명":"$-2$ 를 분모가 $7$ 인 분수 $-\\frac{14}{7}$ 로 고쳐 더한다.","확인":"-10/7","스킬":"G9"}]},"ns-16501a578ce9":{"길":"영역의 꼭짓점을 구하고 y/x 를 원점과 잇는 직선의 기울기로 읽는다","단계":[{"제목":"영역의 꼭짓점 구하기","힌트":"$x\\ge1$, $y\\ge2$, $y\\le-2x+10$ 이 나타내는 삼각형의 꼭짓점은?","식":["$x=1$ 과 $y=2$ 에서 $(1,\\ 2)$","$x=1$ 과 $y=-2x+10$ 에서 $(1,\\ 8)$","$y=2$ 와 $y=-2x+10$ 에서 $(4,\\ 2)$"],"설명":"세 경계선 중 두 개씩 연립해 교점을 구한다. 세 교점이 모두 영역의 경계 위에 있어 삼각형의 꼭짓점이 된다.","확인":null,"스킬":"G6"},{"제목":"y/x 를 원점을 지나는 직선의 기울기로 읽기","고비":true,"힌트":"$\\frac{y}{x}=k$ 로 놓으면 $y=kx$ 는 어떤 직선이고, $k$ 가 최대·최소일 때 직선은 어느 꼭짓점을 지나는가?","식":["$\\frac{y}{x}=k$ 이면 $y=kx$, 원점을 지나는 기울기 $k$ 인 직선","$k$ 는 $(1,\\ 8)$ 을 지날 때 최대, $(4,\\ 2)$ 를 지날 때 최소"],"설명":"원점을 지나는 직선이 삼각형 영역과 만나면서 기울기가 가장 클 때는 가장 위쪽의 $(1,\\ 8)$ 을, 가장 작을 때는 가장 아래쪽의 $(4,\\ 2)$ 를 지난다. $(1,\\ 2)$ 에서의 기울기 $2$ 는 이 둘 사이의 값이다.","확인":null,"스킬":"G9"},{"제목":"최댓값과 최솟값의 합 구하기","힌트":"두 꼭짓점의 $\\frac{y}{x}$ 를 구해 더하면?","식":["최댓값 $\\frac{8}{1}=8$, 최솟값 $\\frac{2}{4}=\\frac{1}{2}$","$8+\\frac{1}{2}=\\frac{17}{2}$"],"설명":"$(1,\\ 8)$ 에서는 $y$ 를 $x$ 로 나눈 값이 $8$, $(4,\\ 2)$ 에서는 $\\frac{1}{2}$ 이다. 두 값을 더한다.","확인":"17/2","스킬":"G9"}]},"ns-1cc7e21cd500":{"길":"수직이면 기울기의 곱이 -1 임을 써서 직선을 세우고 a, b 를 읽는다","단계":[{"제목":"수직인 직선의 기울기 구하기","힌트":"기울기가 $2$ 인 직선에 수직인 직선의 기울기는?","식":["$2\\times m=-1$ 에서 $m=-\\frac{1}{2}$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":"-1/2","스킬":"G9"},{"제목":"점 (2, 1) 을 지나는 직선의 방정식 세우기","고비":true,"힌트":"기울기가 $-\\frac{1}{2}$ 이고 점 $(2,\\ 1)$ 을 지나는 직선을 $y=ax+b$ 꼴로 쓰면?","식":["$y-1=-\\frac{1}{2}(x-2)$","$y=-\\frac{1}{2}x+2$"],"설명":"점과 기울기를 알면 $y-y_1=m(x-x_1)$ 으로 쓰고 $y$ 에 대해 정리한다. 그러면 $a=-\\frac{1}{2}$, $b=2$ 이다.","확인":null,"스킬":"G9"},{"제목":"a+b 의 값 구하기","힌트":"$a=-\\frac{1}{2}$, $b=2$ 일 때 $a+b$ 는?","식":["$a+b=-\\frac{1}{2}+2=\\frac{3}{2}$"],"설명":"$2$ 를 $\\frac{4}{2}$ 로 고쳐 더한다.","확인":"3/2","스킬":"G9"}]},"ns-1dfe6c91530c":{"길":"PB 의 기울기가 a-2 로 정리되는 것을 이용해 Q 를 a 로 쓰고 평행선 사이 거리를 구한다","단계":[{"제목":"꼭짓점 P 와 직선 PB 의 기울기 구하기","고비":true,"힌트":"$f(x)=2(x-2)(x-a)$ 의 꼭짓점 $\\mathrm{P}$ 를 구해 직선 $\\mathrm{PB}$ 의 기울기를 $a$ 로 나타내면?","식":["$f(x)=2(x-2)(x-a)$ 의 축은 $x=\\frac{a+2}{2}$","$\\mathrm{P}\\left(\\frac{a+2}{2},\\ -\\frac{(a-2)^{2}}{2}\\right)$","직선 $\\mathrm{PB}$ 의 기울기 $\\frac{0+\\frac{(a-2)^{2}}{2}}{a-\\frac{a+2}{2}}=a-2$"],"설명":"두 근이 $2$, $a$ 이므로 축은 두 근의 중점이다. $x=\\frac{a+2}{2}$ 를 $f$ 에 넣으면 $2\\times\\frac{a-2}{2}\\times\\frac{2-a}{2}=-\\frac{(a-2)^{2}}{2}$ 이다. 기울기의 분모 $\\frac{a-2}{2}$ 로 분자 $\\frac{(a-2)^{2}}{2}$ 가 약분되어 $a-2$ 만 남는다.","확인":null,"스킬":"G9"},{"제목":"점 Q 의 좌표 구하기","힌트":"직선 $\\mathrm{AQ}$ 는 $\\mathrm{PB}$ 와 평행하다. 직선 $\\mathrm{AQ}$ 의 방정식과 $y=f(x)$ 를 연립해 $\\mathrm{Q}$ 의 좌표를 $a$ 로 나타내면?","식":["직선 $\\mathrm{AQ}:\\ y=(a-2)(x-2)$","$2(x-2)(x-a)=(a-2)(x-2)$ 에서 $x\\ne2$ 이므로 $2(x-a)=a-2$","$\\mathrm{Q}\\left(\\frac{3a-2}{2},\\ \\frac{3(a-2)^{2}}{2}\\right)$"],"설명":"평행한 직선은 기울기가 같아 $a-2$ 이다. 교점 중 하나가 $\\mathrm{A}$ 이므로 $(x-2)$ 로 나누어 다른 교점을 구한다. $x=\\frac{3a-2}{2}$ 를 직선의 식에 넣으면 $y=(a-2)\\times\\frac{3(a-2)}{2}=\\frac{3(a-2)^{2}}{2}$ 이다.","확인":null,"스킬":"G1"},{"제목":"삼각형 BRQ 의 넓이로 a 구하기","힌트":"$\\overline{\\mathrm{BR}}$, $\\overline{\\mathrm{RQ}}$ 를 $a$ 로 나타내고 넓이가 $24$ 라는 식에서 $a$ 는?","식":["$\\overline{\\mathrm{BR}}=\\frac{3a-2}{2}-a=\\frac{a-2}{2},\\ \\overline{\\mathrm{RQ}}=\\frac{3(a-2)^{2}}{2}$","$\\triangle\\mathrm{BRQ}=\\frac{1}{2}\\times\\frac{a-2}{2}\\times\\frac{3(a-2)^{2}}{2}=\\frac{3(a-2)^{3}}{8}=24$","$(a-2)^{3}=64$, $a=6$"],"설명":"$\\mathrm{R}$ 은 $\\mathrm{Q}$ 에서 $x$축에 내린 수선의 발이라 $\\mathrm{R}\\left(\\frac{3a-2}{2},\\ 0\\right)$ 이고 $\\angle\\mathrm{BRQ}=90^{\\circ}$ 이다. $(a-2)^{3}=4^{3}$ 에서 $a-2=4$ 이다.","확인":"6","스킬":"G10"},{"제목":"두 평행한 직선의 방정식 구하기","힌트":"$a=6$ 이면 기울기가 $4$ 이다. $\\mathrm{A}$ 를 지나는 직선 $\\mathrm{AQ}$ 와 $\\mathrm{B}$ 를 지나는 직선 $\\mathrm{PB}$ 의 방정식은?","식":["$\\mathrm{AQ}:\\ y=4(x-2)$, 즉 $4x-y-8=0$","$\\mathrm{PB}:\\ y=4(x-6)$, 즉 $4x-y-24=0$"],"설명":"$a-2=4$ 가 두 직선의 공통 기울기이다. 두 직선은 각각 $\\mathrm{A}(2,\\ 0)$, $\\mathrm{B}(6,\\ 0)$ 을 지난다.","확인":null,"스킬":"G9"},{"제목":"평행선 사이의 거리에서 k 구하기","힌트":"$\\mathrm{A}(2,\\ 0)$ 에서 직선 $4x-y-24=0$ 까지의 거리가 $\\frac{k\\sqrt{17}}{17}$ 일 때 $k$ 는?","식":["$\\frac{|4\\times2-0-24|}{\\sqrt{4^{2}+(-1)^{2}}}=\\frac{16}{\\sqrt{17}}$","$=\\frac{16\\sqrt{17}}{17}$"],"설명":"평행한 두 직선 사이의 거리는 한 직선 위의 점에서 다른 직선까지의 거리와 같다. 분모를 유리화해 $\\frac{k\\sqrt{17}}{17}$ 꼴로 맞추면 $k=16$ 이다.","확인":"16","스킬":"S4"}]},"ns-23857a1d084f":{"길":"교점의 좌표를 정수 + 분수 꼴로 바꿔 분모가 5 의 약수가 되는 m 을 찾는다","단계":[{"제목":"교점의 좌표를 m 으로 나타내기","힌트":"$\\frac{x}{2}+\\frac{y}{4}=1$ 에서 $y=-2x+4$ 이다. 이를 $mx-y+m+1=0$ 에 넣어 교점의 좌표를 $m$ 으로 쓰면?","식":["$mx-(-2x+4)+m+1=0$ 에서 $(m+2)x=3-m$","$x=\\frac{3-m}{m+2},\\ y=\\frac{6m+2}{m+2}$"],"설명":"$m=-2$ 이면 두 직선이 평행해 교점이 없으므로 $m\\ne-2$ 이다. $x$ 를 $y=-2x+4$ 에 넣어 정리하면 $y=\\frac{6m+2}{m+2}$ 이다.","확인":null,"스킬":"G1"},{"제목":"m+2=t 로 놓고 정수 부분 분리하기","고비":true,"힌트":"$m+2=t$ 로 놓으면 $x$, $y$ 를 '정수 + 분수' 꼴로 나타내면?","식":["$x=\\frac{5-t}{t}=-1+\\frac{5}{t}$","$y=\\frac{6t-10}{t}=6-\\frac{10}{t}$"],"설명":"$m=t-2$ 를 넣으면 $3-m=5-t$, $6m+2=6t-10$ 이다. 분자를 $t$ 로 나누어 정수 부분과 분수 부분으로 가른다.","확인":null,"스킬":"N4"},{"제목":"정수가 되는 t 의 값 찾기","힌트":"$-1+\\frac{5}{t}$, $6-\\frac{10}{t}$ 이 모두 정수이려면 $t$ 는 어떤 수여야 하는가?","식":["$\\frac{5}{t}$ 가 정수이면 $t=\\pm1,\\ \\pm5$","이때 $\\frac{10}{t}$ 도 정수이다"],"설명":"$t$ 는 정수이고 $\\frac{5}{t}$ 가 정수이려면 $t$ 가 $5$ 의 약수여야 한다. $5$ 의 약수는 $1$, $5$ 와 그 음수이다. 이 값은 $10$ 의 약수이기도 해서 $y$ 도 정수가 된다.","확인":null,"스킬":"N4"},{"제목":"m 의 값을 구해 합하기","힌트":"$m=t-2$ 로 네 값을 구해 더하면?","식":["$t=1,\\ 5,\\ -1,\\ -5$ 일 때 $m=-1,\\ 3,\\ -3,\\ -7$","$-1+3+(-3)+(-7)=-8$"],"설명":"네 $m$ 은 모두 정수이고 $m\\ne-2$ 를 만족한다. 네 값을 더한다.","확인":"-8","스킬":"N4"}]},"ns-29839a850fb8":{"길":"두 직각삼각형의 넓이가 같음을 이용해 사각형 OPDQ 의 넓이를 정사각형과 같게 놓는다","단계":[{"제목":"직선 AD, CD 의 절편 구하기","힌트":"직선 $\\mathrm{AD}$ 의 $y$절편과 직선 $\\mathrm{CD}$ 의 $x$절편을 $a$ 로 나타내면?","식":["$\\mathrm{AD}:\\ y=\\frac{a}{a+1}(x+1)$ 이므로 $\\mathrm{Q}\\left(0,\\ \\frac{a}{a+1}\\right)$","$\\mathrm{CD}:\\ y=\\frac{a+1}{a}x-1$ 이므로 $\\mathrm{P}\\left(\\frac{a}{a+1},\\ 0\\right)$"],"설명":"직선 $\\mathrm{AD}$ 의 기울기는 $\\frac{a-0}{a+1}$, 직선 $\\mathrm{CD}$ 의 기울기는 $\\frac{a+1}{a}$ 이다. $\\mathrm{AD}$ 에 $x=0$, $\\mathrm{CD}$ 에 $y=0$ 을 넣어 절편을 구한다.","확인":null,"스킬":"G9"},{"제목":"넓이가 같은 두 직각삼각형 알아보기","고비":true,"힌트":"$\\triangle\\mathrm{AOQ}$ 와 $\\triangle\\mathrm{COP}$ 의 넓이를 비교하면?","식":["$\\triangle\\mathrm{AOQ}=\\frac{1}{2}\\times1\\times\\frac{a}{a+1}=\\triangle\\mathrm{COP}$","정사각형 $\\mathrm{ABCO}$ 의 넓이와 사각형 $\\mathrm{OPDQ}$ 의 넓이가 같으면 $y$축이 넓이를 이등분한다"],"설명":"$y$축 왼쪽 부분은 정사각형 $\\mathrm{ABCO}$ 와 $\\triangle\\mathrm{AOQ}$ 로, 오른쪽 부분은 $\\triangle\\mathrm{COP}$ 와 사각형 $\\mathrm{OPDQ}$ 로 이루어진다. 두 삼각형의 넓이가 같으므로 정사각형과 사각형 $\\mathrm{OPDQ}$ 의 넓이가 같으면 이등분이다.","확인":null,"스킬":"G10"},{"제목":"사각형 OPDQ 의 넓이를 a 로 나타내기","힌트":"사각형 $\\mathrm{OPDQ}$ 를 대각선 $\\overline{\\mathrm{OD}}$ 로 나누어 넓이를 $a$ 로 나타내면?","식":["$\\triangle\\mathrm{OPD}=\\frac{1}{2}\\times\\frac{a}{a+1}\\times a$","$\\triangle\\mathrm{OQD}=\\frac{1}{2}\\times\\frac{a}{a+1}\\times a$","$\\square\\mathrm{OPDQ}=\\frac{a^{2}}{a+1}$"],"설명":"$\\overline{\\mathrm{OP}}$ 를 밑변으로 하면 높이는 $\\mathrm{D}$ 의 $y$ 좌표 $a$, $\\overline{\\mathrm{OQ}}$ 를 밑변으로 하면 높이는 $\\mathrm{D}$ 의 $x$ 좌표 $a$ 이다. 두 삼각형의 넓이가 같아 합은 $\\frac{a^{2}}{a+1}$ 이다.","확인":null,"스킬":"G10"},{"제목":"넓이 조건으로 a 구하기","힌트":"사각형 $\\mathrm{OPDQ}$ 의 넓이가 정사각형 $\\mathrm{ABCO}$ 의 넓이 $1$ 과 같다고 놓으면 $a$ 는?","식":["$\\frac{a^{2}}{a+1}=1$, $a^{2}-a-1=0$","$a>0$ 이므로 $a=\\frac{1+\\sqrt{5}}{2}$"],"설명":"분모를 없애 이차방정식을 세운다. 근의 공식으로 $\\frac{1\\pm\\sqrt{5}}{2}$ 가 나오고 $a$ 는 양수이므로 $+$ 인 근을 택한다.","확인":null,"스킬":"G10"}]},"ns-29c491b098c5":{"길":"절편으로 넓이를 구하고 부분분수로 쪼개 이웃한 항을 지운다","단계":[{"제목":"절편으로 넓이 f(n) 구하기","힌트":"직선 $nx+(n+1)y=1$ 의 $x$절편과 $y$절편은?","식":["$x$절편 $\\frac{1}{n}$, $y$절편 $\\frac{1}{n+1}$","$f(n)=\\frac{1}{2}\\times\\frac{1}{n}\\times\\frac{1}{n+1}=\\frac{1}{2n(n+1)}$"],"설명":"$y=0$ 을 넣으면 $x$절편, $x=0$ 을 넣으면 $y$절편이다. 두 절편이 직각을 낀 두 변이므로 넓이는 두 절편의 곱의 반이다.","확인":null,"스킬":"G10"},{"제목":"f(n) 을 부분분수로 쪼개기","고비":true,"힌트":"$\\frac{1}{n(n+1)}$ 을 $\\frac{1}{n}$ 과 $\\frac{1}{n+1}$ 의 차로 나타내면?","식":["$\\frac{1}{n}-\\frac{1}{n+1}=\\frac{1}{n(n+1)}$","$f(n)=\\frac{1}{2}\\left(\\frac{1}{n}-\\frac{1}{n+1}\\right)$"],"설명":"통분하면 $\\frac{(n+1)-n}{n(n+1)}=\\frac{1}{n(n+1)}$ 이다. 이렇게 쪼개면 더할 때 이웃한 항이 서로 지워진다.","확인":null,"스킬":"P6"},{"제목":"f(1)+f(2)+f(3) 계산하기","힌트":"쪼갠 식으로 세 값을 더하면 남는 항은?","식":["$f(1)+f(2)+f(3)=\\frac{1}{2}\\left\\{\\left(1-\\frac{1}{2}\\right)+\\left(\\frac{1}{2}-\\frac{1}{3}\\right)+\\left(\\frac{1}{3}-\\frac{1}{4}\\right)\\right\\}$","$=\\frac{1}{2}\\left(1-\\frac{1}{4}\\right)=\\frac{3}{8}$"],"설명":"$-\\frac{1}{2}$ 과 $+\\frac{1}{2}$, $-\\frac{1}{3}$ 과 $+\\frac{1}{3}$ 이 서로 지워져 처음의 $1$ 과 끝의 $-\\frac{1}{4}$ 만 남는다.","확인":"3/8","스킬":"P6"}]},"ns-2dea1561e57d":{"길":"꼭짓점을 공유한 삼각형의 넓이비를 밑변의 비로 바꿔 P, Q 의 위치를 정한다","단계":[{"제목":"점 P 의 위치 정하기","힌트":"$\\triangle\\mathrm{OPQ}$ 와 $\\triangle\\mathrm{OAQ}$ 는 꼭짓점 $\\mathrm{Q}$ 를 공유한다. 넓이비 $1:2$ 에서 $\\overline{\\mathrm{OP}}:\\overline{\\mathrm{OA}}$ 는?","식":["높이가 같으므로 $\\overline{\\mathrm{OP}}:\\overline{\\mathrm{OA}}=1:2$","$\\mathrm{P}$ 는 $\\overline{\\mathrm{OA}}$ 의 중점 $(2,\\ 1)$"],"설명":"두 삼각형은 $\\mathrm{Q}$ 에서 직선 $\\mathrm{OA}$ 까지의 거리가 같아 높이가 같다. 그래서 넓이의 비가 밑변 $\\overline{\\mathrm{OP}}$, $\\overline{\\mathrm{OA}}$ 의 비와 같다.","확인":null,"스킬":"S1"},{"제목":"점 Q 의 위치 정하기","고비":true,"힌트":"$\\triangle\\mathrm{OPQ}$ 와 $\\triangle\\mathrm{OPB}$ 는 꼭짓점 $\\mathrm{P}$ 를 공유한다. 넓이비 $2:3$ 에서 $\\overline{\\mathrm{OQ}}:\\overline{\\mathrm{OB}}$ 는?","식":["높이가 같으므로 $\\overline{\\mathrm{OQ}}:\\overline{\\mathrm{OB}}=2:3$","$\\mathrm{Q}\\left(\\frac{2}{3}\\times(-3),\\ \\frac{2}{3}\\times6\\right)=(-2,\\ 4)$"],"설명":"$\\mathrm{Q}$ 는 $\\overline{\\mathrm{OB}}$ 위에서 $\\mathrm{O}$ 로부터 $\\frac{2}{3}$ 만큼 간 점이라 좌표가 $\\mathrm{B}$ 의 좌표의 $\\frac{2}{3}$ 배이다. 제$2$사분면 위의 점이라는 조건과 맞는다.","확인":null,"스킬":"S1"},{"제목":"직선 PQ 의 방정식을 구해 a+b 계산하기","힌트":"$\\mathrm{P}(2,\\ 1)$, $\\mathrm{Q}(-2,\\ 4)$ 를 지나는 직선을 $ax+by-10=0$ 꼴로 쓰고 $a+b$ 를 구하면?","식":["기울기 $\\frac{4-1}{-2-2}=-\\frac{3}{4}$","$y-1=-\\frac{3}{4}(x-2)$, 즉 $3x+4y-10=0$","$a=3,\\ b=4$ 이므로 $a+b=7$"],"설명":"양변에 $4$ 를 곱하면 $4y-4=-3x+6$ 이고 정리하면 상수항이 $-10$ 으로 문제의 꼴과 같다. 그래서 $x$, $y$ 의 계수가 $a$, $b$ 이다.","확인":"7","스킬":"G9"}]},"ns-311fc3359a0f":{"길":"청소 못 하는 곳은 세 모서리의 사각형에서 부채꼴을 뺀 부분","단계":[{"제목":"삼각형을 좌표평면에 놓기","힌트":"직각 꼭짓점을 원점에 놓으면 빗변의 기울기는 얼마인가?","식":["$9^{2}+12^{2}=15^{2}$","$\\mathrm{(-9,\\ 0)},\\ \\mathrm{(0,\\ 12)}$ 을 지나는 직선의 기울기 $\\frac{12}{9}=\\frac43$","$4x-3y+36=0$"],"설명":"세 변의 길이가 $9,\\ 12,\\ 15$ 이면 $9^{2}+12^{2}=15^{2}$ 이므로 직각삼각형이다. 직각 꼭짓점을 원점에 두고 길이 $9$ 인 변을 $x$ 축 음의 방향, 길이 $12$ 인 변을 $y$ 축 양의 방향에 놓으면 빗변은 $4x-3y+36=0$ 이다.","확인":"4/3","스킬":"S4"},{"제목":"빗변 쪽 모서리의 원 중심 구하기","힌트":"$x$ 축에 닿은 원의 중심 $(a,\\ 1)$ 에서 빗변까지의 거리가 $1$ 이 되려면 $a$ 는?","식":["$\\frac{|4a-3+36|}{5}=1$","$4a+33=\\pm5$","$a=-7$"],"설명":"원이 $x$ 축과 빗변에 모두 닿으면 중심은 $x$ 축에서 $1$, 빗변에서 $1$ 떨어져 있다. 식에서 $a=-7$ 과 $a=-\\frac{19}{2}$ 가 나오는데 $-\\frac{19}{2}$ 는 삼각형 밖이라 버린다. 같은 방법으로 $y$ 축에 닿은 원의 중심은 $\\mathrm{(-1,\\ 9)}$, 직각 모서리에 닿은 원의 중심은 $\\mathrm{(-1,\\ 1)}$ 이다.","확인":"-7","스킬":"S4"},{"제목":"모서리별 사각형의 넓이 합","힌트":"모서리의 꼭짓점·두 접점·원의 중심을 이으면 접선의 길이와 사각형 넓이는 어떤 관계인가?","식":["$2\\times\\left(\\frac12\\times2\\times1\\right)=2$","$1\\times1=1$","$2\\times\\left(\\frac12\\times3\\times1\\right)=3$"],"설명":"청소기가 벽에 붙어 지나므로 청소할 수 없는 부분은 세 모서리에만 생기고, 각 모서리에서 꼭짓점·두 접점·원의 중심을 이은 사각형이 그 바탕이 된다. 꼭짓점에서 두 접점까지의 길이가 같고 반지름이 접선에 수직이어서 사각형 넓이는 접선의 길이에 $1$ 을 곱한 값이다. 접선의 길이는 모서리 $\\mathrm{(-9,\\ 0)}$ 에서 $2$, 직각 모서리에서 $1$, 모서리 $\\mathrm{(0,\\ 12)}$ 에서 $3$ 이므로 세 넓이의 합은 $6$ 이다.","확인":"6","스킬":"S12"},{"제목":"부채꼴 세 개의 넓이 합","고비":true,"힌트":"사각형 안의 부채꼴의 중심각은 꼭짓점의 각과 어떤 관계인가?","식":["$(180^{\\circ}-\\alpha)+(180^{\\circ}-\\beta)+(180^{\\circ}-\\gamma)=360^{\\circ}$","$\\pi\\times1^{2}=\\pi$"],"설명":"꼭짓점의 각이 $\\theta$ 이면 사각형의 나머지 두 각은 접점에서 $90^{\\circ}$ 씩이므로 중심의 각은 $180^{\\circ}-\\theta$ 이고, 이것이 부채꼴의 중심각이다. 삼각형의 세 내각 $\\alpha,\\ \\beta,\\ \\gamma$ 의 합이 $180^{\\circ}$ 이므로 세 중심각의 합은 $360^{\\circ}$ 이다. 따라서 세 부채꼴을 모으면 반지름이 $1$ 인 원 하나가 되어 넓이는 $\\pi$ 이다.","확인":"360","스킬":"S5"},{"제목":"청소할 수 없는 부분의 넓이","힌트":"사각형 넓이의 합에서 부채꼴 넓이의 합을 빼면?","식":["$2+1+3-\\pi$","$=6-\\pi$"],"설명":"각 모서리에서 청소되지 않는 부분은 사각형에서 부채꼴을 뺀 부분이다. 사각형 넓이의 합 $6$ 에서 부채꼴 넓이의 합 $\\pi$ 를 뺀다.","확인":null,"스킬":"S12"}]},"ns-3203e4f502fe":{"길":"교점 세 개를 구하고 한 변을 밑변으로 잡아 넓이를 구한다","단계":[{"제목":"세 직선의 교점 구하기","힌트":"직선을 두 개씩 연립하면 세 교점의 좌표는?","식":["$4x+3y+12=0,\\ 3x-4y+9=0\\ \\Rightarrow\\ (-3,\\ 0)$","$4x+3y+12=0,\\ 2x-y-4=0\\ \\Rightarrow\\ (0,\\ -4)$","$3x-4y+9=0,\\ 2x-y-4=0\\ \\Rightarrow\\ (5,\\ 6)$"],"설명":"세 직선을 두 개씩 짝지어 연립한 해가 삼각형의 세 꼭짓점이다.","확인":null,"스킬":"G1"},{"제목":"밑변의 길이와 높이 구하기","고비":true,"힌트":"$(0,\\ -4)$ 와 $(5,\\ 6)$ 이 놓인 직선은 어느 것이고, 나머지 꼭짓점에서 그 직선까지의 거리는?","식":["$\\sqrt{5^{2}+10^{2}}=5\\sqrt{5}$","$\\frac{|2\\times(-3)-0-4|}{\\sqrt{2^{2}+1^{2}}}=2\\sqrt{5}$"],"설명":"$(0,\\ -4)$ 와 $(5,\\ 6)$ 은 모두 $2x-y-4=0$ 위에 있으므로 이 선분을 밑변으로 잡는다. 높이는 나머지 꼭짓점 $(-3,\\ 0)$ 에서 이 직선까지의 거리이다.","확인":null,"스킬":"G10"},{"제목":"삼각형의 넓이 구하기","힌트":"밑변과 높이를 곱해 반으로 나누면?","식":["$\\frac12\\times5\\sqrt{5}\\times2\\sqrt{5}=25$"],"설명":"넓이는 밑변과 높이의 곱의 절반이다. $\\sqrt{5}\\times\\sqrt{5}=5$ 이므로 근호가 사라진다.","확인":"25","스킬":"G10"}]},"ns-32bc50491464":{"길":"$y-3x=k$ 로 두고 기울기 3인 직선을 영역에서 아래로 민다","단계":[{"제목":"색칠한 영역의 꼭짓점 읽기","힌트":"그림에서 영역의 세 꼭짓점은 어디인가?","식":["$(0,\\ 1),\\ (2,\\ 1),\\ (2,\\ 0)$"],"설명":"영역은 $y=1$, $x=2$, 두 점 $(0,\\ 1)$, $(2,\\ 0)$ 을 잇는 직선으로 둘러싸인 직각삼각형이다.","확인":null,"스킬":"G6"},{"제목":"최솟값을 주는 꼭짓점 찾기","고비":true,"힌트":"$y=3x+k$ 에서 $k$ 는 직선의 무엇이며, 아래로 밀 때 마지막에 닿는 꼭짓점은?","식":["$y-3x=k\\ \\Rightarrow\\ y=3x+k$","$(2,\\ 0)$"],"설명":"$k$ 는 기울기 $3$ 인 직선의 $y$ 절편이다. 직선을 영역과 만나는 채로 아래로 밀면 $y$ 절편이 줄어들고, 마지막으로 닿는 꼭짓점이 $(2,\\ 0)$ 이다.","확인":null,"스킬":"G9"},{"제목":"최솟값 계산하기","힌트":"$(2,\\ 0)$ 을 $y-3x$ 에 넣으면?","식":["$k=0-3\\times2=-6$"],"설명":"최솟값은 직선이 $(2,\\ 0)$ 을 지날 때의 $y-3x$ 의 값이다.","확인":"-6","스킬":"G9"}]},"ns-3c256064209c":{"길":"각의 이등분선은 두 변까지 거리가 같은 점으로 잡는다","단계":[{"제목":"이등분선의 거리 조건 세우기","힌트":"직선 $\\mathrm{AB}$ 의 식을 구한 뒤, 이등분선 위의 점 $\\mathrm{P}(x,\\ y)$ 에서 두 변까지의 거리를 같다고 놓으면?","식":["$\\mathrm{AB}:\\ 2x-y-4=0$","$|y|=\\frac{|2x-y-4|}{\\sqrt{5}}$"],"설명":"$\\mathrm{A}(2,\\ 0)$, $\\mathrm{B}(3,\\ 2)$ 를 지나는 직선의 기울기는 $2$ 이므로 $2x-y-4=0$ 이다. 각의 이등분선 위의 점은 두 변 $\\mathrm{OA}$ ($y=0$) 와 $\\mathrm{AB}$ 까지의 거리가 같다.","확인":null,"스킬":"S4"},{"제목":"부호를 정해 이등분선의 식 만들기","고비":true,"힌트":"$\\angle\\mathrm{OAB}$ 의 안쪽 점에서 $y$ 와 $2x-y-4$ 의 부호는 각각 어떠한가?","식":["$\\sqrt{5}\\,y=-(2x-y-4)$","$2x+(\\sqrt{5}-1)\\,y-4=0$"],"설명":"$\\angle\\mathrm{OAB}$ 의 안쪽에서는 $y>0$ 이고, 점 $\\mathrm{O}$ 에서 $2x-y-4=-4<0$ 이므로 $2x-y-4<0$ 이다. 따라서 절댓값을 풀면 $\\sqrt{5}\\,y=-(2x-y-4)$ 이고, 이는 기울기가 음수인 직선이다.","확인":null,"스킬":"C2"},{"제목":"점 D의 좌표 구하기","힌트":"이등분선의 식에 $x=0$ 을 넣으면 $y$ 좌표는?","식":["$(\\sqrt{5}-1)\\,y=4$","$y=\\frac{4}{\\sqrt{5}-1}=\\sqrt{5}+1$"],"설명":"점 $\\mathrm{D}$ 는 $y$ 축 위의 점이므로 이등분선의 식에 $x=0$ 을 대입한다. 분모를 유리화하면 $\\mathrm{D}(0,\\ \\sqrt{5}+1)$ 이다.","확인":null,"스킬":"G1"},{"제목":"사각형 OABC의 넓이 구하기","힌트":"대각선 $\\mathrm{AC}$ 로 나누면 두 삼각형의 넓이는 각각 얼마인가?","식":["$\\triangle\\mathrm{OAC}=\\frac12\\times2\\times4=4$","$\\triangle\\mathrm{ABC}=\\frac12\\left|2(2-4)+3(4-0)+0(0-2)\\right|=4$","$\\square\\mathrm{OABC}=4+4=8$"],"설명":"대각선 $\\mathrm{AC}$ 가 사각형을 삼각형 $\\mathrm{OAC}$ 와 $\\mathrm{ABC}$ 로 나눈다. $\\mathrm{OAC}$ 는 직각을 낀 두 변이 $2$, $4$ 이고 $\\mathrm{ABC}$ 는 세 꼭짓점의 좌표로 넓이를 구한다.","확인":"8","스킬":"S12"},{"제목":"사각형 ABCD의 넓이 구하기","힌트":"사각형 $\\mathrm{OABC}$ 에서 삼각형 $\\mathrm{OAD}$ 를 빼면?","식":["$\\triangle\\mathrm{OAD}=\\frac12\\times2\\times(\\sqrt{5}+1)=\\sqrt{5}+1$","$8-(\\sqrt{5}+1)=7-\\sqrt{5}$"],"설명":"점 $\\mathrm{D}$ 가 선분 $\\mathrm{OC}$ 위에 있으므로 사각형 $\\mathrm{ABCD}$ 는 사각형 $\\mathrm{OABC}$ 에서 삼각형 $\\mathrm{OAD}$ 를 뺀 도형이다.","확인":null,"스킬":"S12"}]},"ns-3c4feaa8f96b":{"길":"조건을 영역으로 그리고 이익 직선을 꼭짓점까지 민다","단계":[{"제목":"조건을 연립부등식으로 나타내기","힌트":"제품 $A$, $B$ 를 $x$개, $y$개 만들 때 시간과 비용의 제한은 어떻게 쓰는가?","식":["$2x+y\\le20$","$10x+30y\\le300\\ \\Rightarrow\\ x+3y\\le30$","$x\\ge0,\\ y\\ge0$"],"설명":"시간은 $A$ 가 $2$, $B$ 가 $1$ 씩 들고, 비용은 $A$ 가 $10$만원, $B$ 가 $30$만원씩 든다. 생산 개수는 음수가 될 수 없으므로 $x\\ge0,\\ y\\ge0$ 이다.","확인":null,"스킬":"C7"},{"제목":"영역의 꼭짓점 구하기","힌트":"두 경계선 $2x+y=20$, $x+3y=30$ 의 교점의 $x$ 좌표는?","식":["$x+3(20-2x)=30$","$x=6,\\ y=8$"],"설명":"영역은 네 점 $(0,\\ 0)$, $(10,\\ 0)$, $(6,\\ 8)$, $(0,\\ 10)$ 을 꼭짓점으로 하는 사각형이고, 그 가운데 두 경계선이 만나는 점이 $(6,\\ 8)$ 이다.","확인":"6","스킬":"G1"},{"제목":"이익이 최대인 꼭짓점 찾기","고비":true,"힌트":"이익 직선 $2x+3y=k$ 를 영역 위쪽으로 밀 때 마지막에 닿는 점은?","식":["$2x+3y=k\\ \\Rightarrow\\ y=-\\frac23x+\\frac k3$","$-2<-\\frac23<-\\frac13$"],"설명":"$k$ 가 클수록 직선이 위쪽에 놓인다. 기울기 $-\\frac23$ 은 두 경계선의 기울기 $-2$, $-\\frac13$ 사이에 있으므로, 직선을 밀면 마지막으로 두 경계선의 교점 $(6,\\ 8)$ 을 지난다.","확인":null,"스킬":"G6"},{"제목":"최대이익 계산하기","힌트":"$(6,\\ 8)$ 을 $2x+3y$ 에 넣으면?","식":["$k=2\\times6+3\\times8=36$"],"설명":"이익은 $2x+3y$ 만원이므로 $A$ 를 $6$개, $B$ 를 $8$개 만들 때 최대이고 그 값은 $36$만원이다.","확인":"36","스킬":"G6"}]},"ns-3d361bc46224":{"길":"교점을 지나고 기울기가 정해진 직선을 주어진 꼴로 맞춘다","단계":[{"제목":"두 직선의 교점 구하기","힌트":"두 식을 연립해 $y$ 를 소거하면 $x$ 는?","식":["$(2x+3y+1)+3(3x-y-2)=0$","$11x-5=0\\ \\Rightarrow\\ x=\\frac{5}{11}$","$y=-\\frac{7}{11}$"],"설명":"두 직선의 교점은 연립방정식의 해이다. 두 번째 식에 $3$ 을 곱해 더하면 $y$ 가 없어진다.","확인":"5/11","스킬":"G1"},{"제목":"수직인 직선의 기울기 구하기","힌트":"직선 $2x+y-1=0$ 의 기울기와 곱해서 $-1$ 이 되는 값은?","식":["$y=-2x+1$","$-2\\times m=-1\\ \\Rightarrow\\ m=\\frac12$"],"설명":"두 직선이 수직이면 기울기의 곱이 $-1$ 이다. $2x+y-1=0$ 의 기울기는 $-2$ 이다.","확인":"1/2","스킬":"G9"},{"제목":"직선의 식을 주어진 꼴로 맞추기","고비":true,"힌트":"교점 $\\left(\\frac{5}{11},\\ -\\frac{7}{11}\\right)$ 을 지나고 기울기가 $\\frac12$ 인 직선을 $ax+by-19=0$ 꼴로 정리하면 $b$ 의 값은?","식":["$y+\\frac{7}{11}=\\frac12\\left(x-\\frac{5}{11}\\right)$","$11x-22y-19=0$","$a=11,\\ b=-22$"],"설명":"양변에 $22$ 를 곱해 분수를 없애고 이항하면 상수항이 $-19$ 가 되어 주어진 꼴과 일치한다. 따라서 계수를 그대로 읽는다.","확인":"-22","스킬":"G3"},{"제목":"계수의 합 구하기","힌트":"$a=11,\\ b=-22$ 일 때 $a+b$ 는?","식":["$a+b=11+(-22)=-11$"],"설명":"앞 단계에서 읽은 두 계수를 더한다.","확인":"-11","스킬":"G3"}]},"ns-3ffafa3a0570":{"길":"G는 육각형의 중심이라 정삼각형 OAG의 높이가 평행선 사이 거리","단계":[{"제목":"정삼각형 OAG와 높이 GM 잡기","힌트":"$\\mathrm{G}$ 는 정육각형의 중심이다. 변 $\\mathrm{OA}$ 의 중점 $\\mathrm{M}$ 과 $\\mathrm{G}$ 를 이은 선분은 두 직선과 어떤 관계인가?","식":["$\\overline{\\mathrm{OG}}=\\overline{\\mathrm{AG}}=\\overline{\\mathrm{OA}}$","$\\overline{\\mathrm{GM}}\\perp y=x,\\ \\overline{\\mathrm{GM}}\\perp y=x+1$"],"설명":"대각선 $\\mathrm{BE}$ 의 중점 $\\mathrm{G}$ 는 정육각형의 중심이므로 삼각형 $\\mathrm{OAG}$ 는 한 변이 $\\overline{\\mathrm{OA}}$ 인 정삼각형이다. 변 $\\mathrm{OA}$ 의 중점 $\\mathrm{M}$ 과 $\\mathrm{G}$ 를 이은 선분은 $\\mathrm{OA}$ 에 수직이고, $\\mathrm{OA}$ 와 $\\mathrm{BE}$ 가 평행하므로 $y=x+1$ 에도 수직이다.","확인":null,"스킬":"S7"},{"제목":"평행선 사이의 거리로 GM 구하기","힌트":"$y=x+1$ 위의 점 $(0,\\ 1)$ 에서 직선 $x-y=0$ 까지의 거리는?","식":["$\\overline{\\mathrm{GM}}=\\frac{|0-1|}{\\sqrt{1^{2}+(-1)^{2}}}=\\frac{\\sqrt{2}}{2}$"],"설명":"$\\mathrm{GM}$ 은 두 평행선에 모두 수직이므로 그 길이는 두 평행선 사이의 거리와 같다.","확인":null,"스킬":"S4"},{"제목":"점 M의 좌표 구하기","힌트":"정삼각형의 높이가 $\\frac{\\sqrt{2}}{2}$ 일 때 한 변의 길이와 $\\overline{\\mathrm{OM}}$ 은?","식":["$\\frac{\\sqrt{3}}{2}\\,\\overline{\\mathrm{OA}}=\\frac{\\sqrt{2}}{2}\\ \\Rightarrow\\ \\overline{\\mathrm{OA}}=\\frac{\\sqrt{6}}{3}$","$\\overline{\\mathrm{OM}}=\\frac{\\sqrt{6}}{6}$","$\\mathrm{M}\\left(\\frac{\\sqrt{3}}{6},\\ \\frac{\\sqrt{3}}{6}\\right)$"],"설명":"정삼각형의 높이는 한 변의 $\\frac{\\sqrt{3}}{2}$ 배이다. 점 $\\mathrm{M}$ 은 $y=x$ 위에 있으므로 $(m,\\ m)$ 으로 두면 $\\sqrt{2}\\,m=\\frac{\\sqrt{6}}{6}$ 에서 $m=\\frac{\\sqrt{3}}{6}$ 이다.","확인":null,"스킬":"S3"},{"제목":"직각이등변삼각형으로 G의 좌표 구하기","고비":true,"힌트":"직선 $\\mathrm{GM}$ 의 기울기가 $-1$ 이면 $\\mathrm{M}$ 에서 $\\mathrm{G}$ 까지 가로와 세로로 각각 얼마씩 움직이는가?","식":["$\\overline{\\mathrm{GH}}=\\overline{\\mathrm{HM}}=\\frac12$","$\\mathrm{G}\\left(\\frac{\\sqrt{3}}{6}-\\frac12,\\ \\frac{\\sqrt{3}}{6}+\\frac12\\right)$"],"설명":"$\\mathrm{GM}$ 이 $y=x$ 에 수직이므로 기울기는 $-1$ 이다. $\\mathrm{M}$ 을 지나는 가로선과 $\\mathrm{G}$ 를 지나는 세로선이 만나는 점을 $\\mathrm{H}$ 라 하면 삼각형 $\\mathrm{GHM}$ 은 직각이등변삼각형이고, 빗변이 $\\frac{\\sqrt{2}}{2}$ 이므로 직각을 낀 변은 $\\frac12$ 이다. $\\mathrm{G}$ 는 $\\mathrm{M}$ 의 왼쪽 위에 있으므로 $x$ 좌표는 $\\frac12$ 줄고 $y$ 좌표는 $\\frac12$ 늘어난다.","확인":"1/2","스킬":"S4"},{"제목":"ab의 값 구하기","힌트":"$a=\\frac{\\sqrt{3}}{6}-\\frac12,\\ b=\\frac{\\sqrt{3}}{6}+\\frac12$ 의 곱은?","식":["$ab=\\left(\\frac{\\sqrt{3}}{6}\\right)^{2}-\\left(\\frac12\\right)^{2}$","$=\\frac{1}{12}-\\frac14=-\\frac16$"],"설명":"합차 공식 $(p-q)(p+q)=p^{2}-q^{2}$ 을 쓰면 근호가 사라진다.","확인":"-1/6","스킬":"S4"}]},"ns-43088eb0a7cd":{"길":"중근 조건으로 Q가 놓인 직선을 찾고 점과 직선 사이 거리를 쓴다","단계":[{"제목":"중근 조건으로 a+b 구하기","힌트":"판별식 $D=0$ 에서 $(a+b)^{2}-4(a+b-1)$ 을 $a+b$ 에 대한 식으로 정리하면?","식":["$\\frac{D}{4}=(a+b)^{2}-4(a+b-1)=0$","$(a+b-2)^{2}=0$","$a+b=2$"],"설명":"이차방정식이 중근을 가지려면 판별식이 $0$ 이어야 한다. $a+b$ 를 한 덩어리로 보고 전개하면 $(a+b)^{2}-4(a+b)+4=(a+b-2)^{2}$ 이다.","확인":"2","스킬":"A6"},{"제목":"점 Q가 움직이는 직선 찾기","고비":true,"힌트":"$a+b$ 가 정해지면 점 $\\mathrm{Q}(a,\\ b)$ 는 어떤 도형 위에 있고, $\\overline{\\mathrm{PQ}}$ 가 최소일 때 $\\mathrm{Q}$ 는 어디인가?","식":["$x+y-2=0$"],"설명":"$a+b=2$ 이므로 점 $\\mathrm{Q}(a,\\ b)$ 는 직선 $x+y-2=0$ 위의 점이다. 직선 위의 점 중 $\\mathrm{P}$ 와 가장 가까운 점은 $\\mathrm{P}$ 에서 내린 수선의 발이므로, $\\overline{\\mathrm{PQ}}$ 의 최솟값은 $\\mathrm{P}$ 와 이 직선 사이의 거리이다.","확인":null,"스킬":"S4"},{"제목":"점과 직선 사이의 거리 구하기","힌트":"$\\mathrm{P}(-2,\\ 0)$ 에서 직선 $x+y-2=0$ 까지의 거리는?","식":["$\\frac{|-2+0-2|}{\\sqrt{1^{2}+1^{2}}}=\\frac{4}{\\sqrt{2}}=2\\sqrt{2}$"],"설명":"점과 직선 사이의 거리 공식을 쓰고 분모를 유리화한다.","확인":null,"스킬":"S4"}]},"ns-45f5833bf4c0":{"길":"접은 선분이 각을 이등분함을 써서 길이를 k로 나타내고 수직 조건을 쓴다","단계":[{"제목":"접은 선분이 만드는 길이의 비","고비":true,"힌트":"접은 선분 $\\mathrm{BE}$ 가 각을 이등분함을 이용하면, $\\overline{\\mathrm{AE}}=2k$ 일 때 $\\overline{\\mathrm{A}'\\mathrm{M}}$ 은 $k$ 의 몇 배인가?","식":["$\\angle\\mathrm{EBA}=\\angle\\mathrm{EBA}'$","$\\overline{\\mathrm{A}'\\mathrm{P}}:\\overline{\\mathrm{PM}}=\\overline{\\mathrm{A}'\\mathrm{B}}:\\overline{\\mathrm{MB}}=2:1$","$\\overline{\\mathrm{PM}}=k,\\ \\overline{\\mathrm{A}'\\mathrm{P}}=2k,\\ \\overline{\\mathrm{A}'\\mathrm{M}}=3k$"],"설명":"접으면 $\\triangle\\mathrm{BEA}\\equiv\\triangle\\mathrm{BEA}'$ 이므로 $\\mathrm{BE}$ 는 $\\angle\\mathrm{A}'\\mathrm{BM}$ 의 이등분선이고, $\\mathrm{NM}$ 과 $\\mathrm{EB}$ 의 교점을 $\\mathrm{P}$ 라 하면 각의 이등분선 정리에서 $\\overline{\\mathrm{A}'\\mathrm{P}}:\\overline{\\mathrm{PM}}=\\overline{\\mathrm{A}'\\mathrm{B}}:\\overline{\\mathrm{MB}}=2:1$ 이다. $\\mathrm{PM}\\parallel\\mathrm{AE}$ 이고 $\\mathrm{M}$ 이 $\\mathrm{AB}$ 의 중점이므로 $\\overline{\\mathrm{AE}}=2k$ 이면 $\\overline{\\mathrm{PM}}=k$ 이다. 따라서 $\\overline{\\mathrm{A}'\\mathrm{P}}=2k$, $\\overline{\\mathrm{A}'\\mathrm{M}}=3k$ 이다.","확인":"3","스킬":"S2"},{"제목":"수직 조건으로 k 구하기","힌트":"$\\mathrm{A}$ 를 원점에 두고 $\\mathrm{AA}'$ 과 $\\mathrm{EB}$ 의 기울기의 곱이 $-1$ 이면 $k^{2}$ 은?","식":["$\\mathrm{E}(0,\\ 2k),\\ \\mathrm{B}(2,\\ 0),\\ \\mathrm{A}'(1,\\ 3k)$","$3k\\times(-k)=-1$","$k^{2}=\\frac13$"],"설명":"$\\mathrm{A}$ 를 원점, $\\mathrm{AB}$ 를 $x$ 축으로 놓으면 $\\mathrm{AA}'$ 의 기울기는 $3k$, $\\mathrm{EB}$ 의 기울기는 $\\frac{0-2k}{2-0}=-k$ 이다. 접은 선분 $\\mathrm{EB}$ 는 $\\mathrm{AA}'$ 의 수직이등분선이므로 기울기의 곱이 $-1$ 이고, $k>0$ 이므로 $k=\\frac{1}{\\sqrt{3}}$ 이다.","확인":"1/3","스킬":"S4"},{"제목":"직선 BE의 방정식 세우기","힌트":"기울기 $-k$ 이고 $y$ 절편이 $2k$ 인 직선을 $k=\\frac{1}{\\sqrt{3}}$ 로 쓰고 정리하면?","식":["$y=-\\frac{1}{\\sqrt{3}}x+\\frac{2}{\\sqrt{3}}$","$x+\\sqrt{3}\\,y-2=0$"],"설명":"$\\mathrm{E}\\left(0,\\ \\frac{2}{\\sqrt{3}}\\right)$ 와 $\\mathrm{B}(2,\\ 0)$ 을 지나는 직선이다. 양변에 $\\sqrt{3}$ 을 곱해 계수를 정리한다.","확인":null,"스킬":"S4"},{"제목":"점 N과 직선 BE 사이의 거리","힌트":"$\\mathrm{N}(1,\\ 2)$ 에서 직선 $x+\\sqrt{3}\\,y-2=0$ 까지의 거리는?","식":["$\\frac{|1+2\\sqrt{3}-2|}{\\sqrt{1^{2}+(\\sqrt{3})^{2}}}=\\frac{2\\sqrt{3}-1}{2}$"],"설명":"점 $\\mathrm{N}$ 은 선분 $\\mathrm{CD}$ 의 중점이므로 $\\mathrm{N}(1,\\ 2)$ 이다. 점과 직선 사이의 거리 공식을 쓴다.","확인":null,"스킬":"S4"}]},"ns-4799ab061706":{"길":"B를 원점에 놓고 접은 점 C′의 좌표를 구해 BD까지 거리를 낸다","단계":[{"제목":"직사각형을 좌표평면에 놓기","힌트":"$\\mathrm{B}$ 를 원점, $\\mathrm{BC}$ 를 $x$ 축에 놓으면 대각선 $\\mathrm{BD}$ 의 방정식은?","식":["$\\mathrm{B}(0,\\ 0),\\ \\mathrm{C}(2,\\ 0),\\ \\mathrm{D}(2,\\ 4)$","$\\mathrm{BD}:\\ 2x-y=0$"],"설명":"$\\overline{\\mathrm{BC}}=2$, $\\overline{\\mathrm{CD}}=\\overline{\\mathrm{AB}}=4$ 이므로 $\\mathrm{D}(2,\\ 4)$ 이고, 원점과 $\\mathrm{D}$ 를 지나는 직선은 $y=2x$ 이다.","확인":null,"스킬":"S4"},{"제목":"접은 점 C′의 좌표 구하기","고비":true,"힌트":"$\\overline{\\mathrm{BC}'}$ 의 길이와 $x$ 축과 이루는 각으로 $\\mathrm{C}'$ 의 $y$ 좌표를 구하면?","식":["$\\overline{\\mathrm{BC}'}=\\overline{\\mathrm{BC}}=2,\\ \\angle\\mathrm{CBC}'=2\\times15^{\\circ}=30^{\\circ}$","$\\mathrm{C}'(2\\cos30^{\\circ},\\ 2\\sin30^{\\circ})=(\\sqrt{3},\\ 1)$"],"설명":"접은 선분 $\\mathrm{BE}$ 는 $\\angle\\mathrm{CBC}'$ 를 이등분하므로 $\\angle\\mathrm{CBC}'=30^{\\circ}$ 이다. 접어도 길이는 변하지 않아 $\\overline{\\mathrm{BC}'}=\\overline{\\mathrm{BC}}=2$ 이므로, $\\mathrm{C}'$ 은 $x$ 축에서 $30^{\\circ}$ 방향으로 $2$ 만큼 떨어진 점이다.","확인":"1","스킬":"S6"},{"제목":"점 C′과 직선 BD 사이의 거리","힌트":"$(\\sqrt{3},\\ 1)$ 에서 직선 $2x-y=0$ 까지의 거리는?","식":["$\\frac{|2\\sqrt{3}-1|}{\\sqrt{2^{2}+(-1)^{2}}}=\\frac{2\\sqrt{3}-1}{\\sqrt{5}}$"],"설명":"점과 직선 사이의 거리 공식을 쓴다. $2\\sqrt{3}>1$ 이므로 절댓값 안은 양수이다.","확인":null,"스킬":"S4"},{"제목":"분모를 유리화해 꼴 맞추기","힌트":"분모를 유리화해 $a\\sqrt{15}-b\\sqrt{5}$ 꼴로 쓰면 $a$ 는?","식":["$\\frac{(2\\sqrt{3}-1)\\sqrt{5}}{5}=\\frac25\\sqrt{15}-\\frac15\\sqrt{5}$","$a=\\frac25,\\ b=\\frac15$"],"설명":"분자와 분모에 $\\sqrt{5}$ 를 곱하면 $\\frac{2\\sqrt{15}-\\sqrt{5}}{5}$ 이다. $a,\\ b$ 가 유리수이므로 $\\sqrt{15}$, $\\sqrt{5}$ 의 계수를 그대로 읽는다.","확인":"2/5","스킬":"A5"},{"제목":"25(a+b)의 값 구하기","힌트":"$a+b$ 를 구해 $25$ 를 곱하면?","식":["$25\\left(\\frac25+\\frac15\\right)=15$"],"설명":"$a+b=\\frac35$ 에 $25$ 를 곱한다.","확인":"15","스킬":"A5"}]},"ns-49caf353e719":{"길":"원점 대칭인 꼭짓점끼리 거리가 같음을 써서 세 점만 계산한다","단계":[{"제목":"정육각형의 꼭짓점 좌표 구하기","힌트":"$\\overline{\\mathrm{OA}_{1}}=4$ 이고 $\\mathrm{A}_{3},\\ \\mathrm{A}_{6}$ 이 $x$ 축 위이면 여섯 꼭짓점의 좌표는?","식":["$\\mathrm{A}_{6}(4,\\ 0),\\ \\mathrm{A}_{3}(-4,\\ 0)$","$\\mathrm{A}_{1}(2,\\ 2\\sqrt{3}),\\ \\mathrm{A}_{2}(-2,\\ 2\\sqrt{3})$","$\\mathrm{A}_{4}(-2,\\ -2\\sqrt{3}),\\ \\mathrm{A}_{5}(2,\\ -2\\sqrt{3})$"],"설명":"정육각형은 중심에서 각 꼭짓점까지의 거리가 $4$ 로 같고 이웃한 꼭짓점 사이의 중심각이 $60^{\\circ}$ 이다. $x$ 축 위의 꼭짓점에서 $60^{\\circ}$ 씩 돌리면 나머지 네 점의 좌표가 정해진다.","확인":null,"스킬":"S4"},{"제목":"원점 대칭인 꼭짓점 짝 묶기","힌트":"원점에 대해 대칭인 두 점에서 직선 $x+4y=0$ 까지의 거리는 서로 어떤 관계인가?","식":["$d_{1}=d_{4},\\ d_{2}=d_{5},\\ d_{3}=d_{6}$","$K=2\\left(d_{1}^{2}+d_{2}^{2}+d_{3}^{2}\\right)$"],"설명":"직선 $x+4y=0$ 이 원점을 지나므로 원점에 대해 대칭인 두 점은 직선까지의 거리가 같다. 정육각형에서 $\\mathrm{A}_{1}$ 과 $\\mathrm{A}_{4}$, $\\mathrm{A}_{2}$ 와 $\\mathrm{A}_{5}$, $\\mathrm{A}_{3}$ 과 $\\mathrm{A}_{6}$ 이 이런 짝이다.","확인":null,"스킬":"S4"},{"제목":"d₁²+d₂²의 값 구하기","고비":true,"힌트":"$\\mathrm{A}_{1},\\ \\mathrm{A}_{2}$ 에서 직선까지 거리의 제곱을 각각 구해 더하면?","식":["$d_{1}^{2}=\\frac{(2+8\\sqrt{3})^{2}}{17}=\\frac{196+32\\sqrt{3}}{17}$","$d_{2}^{2}=\\frac{(-2+8\\sqrt{3})^{2}}{17}=\\frac{196-32\\sqrt{3}}{17}$","$d_{1}^{2}+d_{2}^{2}=\\frac{392}{17}$"],"설명":"점 $(x,\\ y)$ 에서 직선 $x+4y=0$ 까지의 거리의 제곱은 $\\frac{(x+4y)^{2}}{1^{2}+4^{2}}=\\frac{(x+4y)^{2}}{17}$ 이다. 두 식을 더하면 $\\sqrt{3}$ 이 들어 있는 항이 서로 없어진다.","확인":"392/17","스킬":"S4"},{"제목":"K의 값 구하기","힌트":"$d_{3}^{2}$ 을 구해 $K=2\\left(d_{1}^{2}+d_{2}^{2}+d_{3}^{2}\\right)$ 에 넣으면?","식":["$d_{3}^{2}=\\frac{(-4)^{2}}{17}=\\frac{16}{17}$","$K=2\\left(\\frac{392}{17}+\\frac{16}{17}\\right)=48$"],"설명":"$\\mathrm{A}_{3}(-4,\\ 0)$ 에서는 $x+4y=-4$ 이다. 세 값을 더해 $2$ 배 하면 분모 $17$ 이 약분된다.","확인":"48","스킬":"S4"}]},"ns-4c8923c07c25":{"길":"원료 제한을 영역으로 그리고 정수 조건 아래 이익이 최대인 점을 찾는다","단계":[{"제목":"조건을 연립부등식으로 나타내기","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 를 $x$개, $y$개 만들 때 원료 $\\mathrm{P}$, $\\mathrm{Q}$ 의 제한은 어떻게 쓰는가?","식":["$x+2y\\le40$","$2x+y\\le60$","$x\\ge0,\\ y\\ge0$"],"설명":"원료 $\\mathrm{P}$ 는 $\\mathrm{A}$ 에 $1\\,L$, $\\mathrm{B}$ 에 $2\\,L$ 가 들고, 원료 $\\mathrm{Q}$ 는 $\\mathrm{A}$ 에 $2\\,L$, $\\mathrm{B}$ 에 $1\\,L$ 가 든다. 이익은 $4x+3y$ 만원이고, 완제품만 판매하므로 $x,\\ y$ 는 정수이다.","확인":null,"스킬":"C7"},{"제목":"경계선의 교점과 이익의 상한 구하기","힌트":"두 경계선의 교점에서 이익 $4x+3y$ 의 값은?","식":["$x=\\frac{80}{3},\\ y=\\frac{20}{3}$","$4\\times\\frac{80}{3}+3\\times\\frac{20}{3}=\\frac{380}{3}$"],"설명":"두 식을 연립하면 교점은 $\\left(\\frac{80}{3},\\ \\frac{20}{3}\\right)$ 이다. 이익 직선의 기울기 $-\\frac43$ 은 두 경계선의 기울기 $-2$, $-\\frac12$ 사이에 있으므로, 실수 범위의 최대 이익은 이 교점에서의 $\\frac{380}{3}$ 이다. 개수가 정수이면 이익도 정수이므로 이익은 $\\frac{380}{3}$ 이하의 정수이다.","확인":"380/3","스킬":"G6"},{"제목":"정수점에서 최대이익과 생산 개수 구하기","고비":true,"힌트":"$\\frac{380}{3}$ 이하의 가장 큰 정수를 이익으로 하는 정수점이 영역 안에 있는가?","식":["$4x+3y=126\\ \\Rightarrow\\ (x,\\ y)=(27,\\ 6)$","$27+2\\times6=39\\le40,\\ \\ 2\\times27+6=60\\le60$"],"설명":"$\\frac{380}{3}=126.\\cdots$ 이므로 먼저 이익이 $126$ 이 되는 정수점이 있는지 본다. $4x+3y=126$ 이면 $x$ 는 $3$ 의 배수인데, $x=27$ 일 때 $y=6$ 이 두 부등식을 모두 만족한다. $x=30$ 은 $2x+y\\le60$ 을, $x=24$ 는 $x+2y\\le40$ 을 어기므로 이 점뿐이며 $p=126$, $q=27$ 이다.","확인":"126","스킬":"G6"},{"제목":"p+q의 값 구하기","힌트":"$q$ 는 이익이 최대일 때 $\\mathrm{A}$ 의 생산 개수이다. $p+q$ 는?","식":["$p+q=126+27=153$"],"설명":"$p$ 는 최대이익, $q$ 는 그때 만든 $\\mathrm{A}$ 의 개수이다.","확인":"153","스킬":"C7"}]},"ns-4d90e57a1447":{"길":"평행한 두 변을 가진 사다리꼴 둘의 넓이가 같다는 조건으로 Q를 정한다","단계":[{"제목":"평행한 두 변과 점 P의 위치","힌트":"직선 $\\mathrm{AD}$ 의 기울기는 얼마인가?","식":["$\\frac{2-0}{0-4}=-\\frac12,\\ \\ \\frac{4-0}{0-8}=-\\frac12$","$\\overline{\\mathrm{AD}}=2\\sqrt{5},\\ \\overline{\\mathrm{BC}}=4\\sqrt{5}$","$\\overline{\\mathrm{AP}}=\\frac{\\sqrt{5}}{2},\\ \\overline{\\mathrm{DP}}=\\frac{3\\sqrt{5}}{2}$"],"설명":"두 변 $\\mathrm{AD}$, $\\mathrm{BC}$ 의 기울기가 같으므로 $\\mathrm{AD}\\parallel\\mathrm{BC}$ 이고 사각형 $\\mathrm{ABCD}$ 는 사다리꼴이다. $\\overline{\\mathrm{AD}}=\\sqrt{4^{2}+2^{2}}=2\\sqrt{5}$, $\\overline{\\mathrm{BC}}=\\sqrt{8^{2}+4^{2}}=4\\sqrt{5}$ 이고, 점 $\\mathrm{P}$ 가 $\\mathrm{AD}$ 를 $1:3$ 으로 나누므로 $\\overline{\\mathrm{AP}}=\\frac14\\overline{\\mathrm{AD}}$ 이다.","확인":"-1/2","스킬":"G9"},{"제목":"두 사다리꼴의 넓이를 같게 놓기","고비":true,"힌트":"직선 $l$ 이 나눈 두 사다리꼴 $\\mathrm{CDPQ}$, $\\mathrm{ABQP}$ 의 높이가 같으면 평행한 두 변의 길이의 합 사이에는 어떤 관계가 성립하는가?","식":["$\\frac12(\\overline{\\mathrm{DP}}+\\overline{\\mathrm{CQ}})\\,h=\\frac12(\\overline{\\mathrm{AP}}+\\overline{\\mathrm{BQ}})\\,h$","$\\overline{\\mathrm{DP}}+\\overline{\\mathrm{CQ}}=\\overline{\\mathrm{AP}}+\\overline{\\mathrm{BQ}}$"],"설명":"$\\mathrm{AD}\\parallel\\mathrm{BC}$ 이므로 두 사다리꼴의 높이는 평행선 사이의 거리 $h$ 로 같다. 직선 $l$ 이 넓이를 이등분하므로 평행한 두 변의 길이의 합이 서로 같다.","확인":null,"스킬":"G10"},{"제목":"CQ와 BQ의 길이 구하기","힌트":"$\\overline{\\mathrm{CQ}}+\\overline{\\mathrm{BQ}}=4\\sqrt{5}$ 와 앞의 식을 연립하면 $\\frac{\\overline{\\mathrm{CQ}}}{\\overline{\\mathrm{BQ}}}$ 는?","식":["$\\frac{3\\sqrt{5}}{2}+\\overline{\\mathrm{CQ}}=\\frac{\\sqrt{5}}{2}+\\overline{\\mathrm{BQ}}$","$\\overline{\\mathrm{BQ}}=\\frac{5\\sqrt{5}}{2},\\ \\overline{\\mathrm{CQ}}=\\frac{3\\sqrt{5}}{2}$","$\\overline{\\mathrm{CQ}}:\\overline{\\mathrm{BQ}}=3:5$"],"설명":"$\\overline{\\mathrm{CQ}}=4\\sqrt{5}-\\overline{\\mathrm{BQ}}$ 를 앞의 식에 대입해 $\\overline{\\mathrm{BQ}}$ 를 구한다. 점 $\\mathrm{Q}$ 는 선분 $\\mathrm{CB}$ 를 $3:5$ 로 내분하는 점이다.","확인":"3/5","스킬":"G10"},{"제목":"점 Q의 좌표와 a+2b 구하기","힌트":"선분 $\\mathrm{CB}$ 를 $3:5$ 로 내분하는 점의 좌표는?","식":["$\\mathrm{Q}\\left(\\frac{3\\times8+5\\times0}{3+5},\\ \\frac{3\\times0+5\\times4}{3+5}\\right)=\\left(3,\\ \\frac52\\right)$","$a+2b=3+5=8$"],"설명":"$\\mathrm{C}(0,\\ 4)$ 쪽에서 $3$, $\\mathrm{B}(8,\\ 0)$ 쪽에서 $5$ 의 비로 나누는 내분점 공식을 쓴다.","확인":"8","스킬":"G10"}]},"ns-5011f905f742":{"길":"수직이등분선은 중점과 기울기로 식을 세워 (가)(나)(다)를 구한다","단계":[{"제목":"(가) AB의 수직이등분선 구하기","힌트":"$\\mathrm{AB}$ 의 중점과 $\\mathrm{AB}$ 에 수직인 직선의 기울기로 식을 세우면 $y$ 절편은?","식":["$\\mathrm{M}\\left(-\\frac12,\\ 1\\right)$","$y-1=-\\frac12\\left(x+\\frac12\\right)$","$y=-\\frac12x+\\frac34$"],"설명":"$\\mathrm{AB}$ 의 기울기는 $\\frac{2-0}{0-(-1)}=2$ 이므로 수직인 직선의 기울기는 $-\\frac12$ 이다. 수직이등분선은 중점 $\\left(-\\frac12,\\ 1\\right)$ 을 지나므로 (가)에 알맞은 수는 $a=\\frac34$ 이다.","확인":"3/4","스킬":"S7"},{"제목":"(나) 교점의 y좌표 구하기","힌트":"$y=-\\frac12x+\\frac34$ 에 $x=\\frac{k-1}{2}$ 을 넣으면?","식":["$y=-\\frac12\\cdot\\frac{k-1}{2}+\\frac34=1-\\frac{k}{4}$","$f(k)=1-\\frac{k}{4},\\ \\ f(2)=\\frac12$"],"설명":"두 수직이등분선의 교점은 연립해서 구한다. $x=\\frac{k-1}{2}$ 을 대입하면 $y$ 좌표가 $k$ 의 식으로 나온다.","확인":"1/2","스킬":"S7"},{"제목":"(다) CA의 수직이등분선 구하기","고비":true,"힌트":"$\\mathrm{CA}$ 의 중점과 $\\mathrm{CA}$ 에 수직인 직선의 기울기로 식을 세우면 $y$ 절편은?","식":["$\\mathrm{CA}$ 의 기울기 $-\\frac{2}{k}\\ \\Rightarrow\\ \\frac{k}{2}$","$y-1=\\frac{k}{2}\\left(x-\\frac{k}{2}\\right)$","$y=\\frac{k}{2}x+1-\\frac{k^{2}}{4}$"],"설명":"$\\mathrm{C}(k,\\ 0)$, $\\mathrm{A}(0,\\ 2)$ 를 지나는 직선의 기울기는 $-\\frac{2}{k}$ 이므로 수직인 직선의 기울기는 $\\frac{k}{2}$ 이고, 중점 $\\left(\\frac{k}{2},\\ 1\\right)$ 을 지난다. 따라서 $g(k)=1-\\frac{k^{2}}{4}$ 이고 $g(3)=-\\frac54$ 이다.","확인":"-5/4","스킬":"S7"},{"제목":"세 값의 합 구하기","힌트":"$a=\\frac34$, $f(2)$, $g(3)$ 을 모두 더하면?","식":["$a+f(2)+g(3)=\\frac34+\\frac12+\\left(-\\frac54\\right)=0$"],"설명":"앞 단계에서 구한 세 값을 통분해 더한다.","확인":"0","스킬":"S7"}]},"ns-56bb61244fa7":{"길":"두 꼭짓점에서 대변에 내린 수선의 식을 세워 교점을 구한다","단계":[{"제목":"변 AC에 내린 수선의 방정식","힌트":"변 $\\mathrm{AC}$ 가 $x$ 축에 평행하면 점 $\\mathrm{B}$ 를 지나는 수선은 어떤 직선인가?","식":["$\\mathrm{A}(0,\\ 4),\\ \\mathrm{C}(2,\\ 4)\\ \\Rightarrow\\ \\mathrm{AC}:\\ y=4$","$x=1$"],"설명":"두 점 $\\mathrm{A}$, $\\mathrm{C}$ 의 $y$ 좌표가 같으므로 $\\mathrm{AC}$ 는 $y=4$ 이고, 이에 수직인 직선은 $y$ 축에 평행하다. 점 $\\mathrm{B}(1,\\ 1)$ 을 지나므로 $x=1$ 이다.","확인":null,"스킬":"G9"},{"제목":"변 BC에 내린 수선의 방정식","고비":true,"힌트":"$\\mathrm{BC}$ 의 기울기와 곱해서 $-1$ 이 되는 값은?","식":["$\\mathrm{BC}$ 의 기울기 $\\frac{4-1}{2-1}=3$","$m=-\\frac13$","$y=-\\frac13x+4$"],"설명":"$\\mathrm{A}$ 에서 $\\mathrm{BC}$ 에 내린 수선은 기울기가 $-\\frac13$ 이고 $\\mathrm{A}(0,\\ 4)$ 를 지나므로 $y$ 절편이 $4$ 이다.","확인":"-1/3","스킬":"G3"},{"제목":"두 수선의 교점으로 ab 구하기","힌트":"$x=1$ 을 $y=-\\frac13x+4$ 에 넣으면 $y$ 는?","식":["$y=-\\frac13+4=\\frac{11}{3}$","$\\mathrm{H}\\left(1,\\ \\frac{11}{3}\\right),\\ \\ ab=1\\times\\frac{11}{3}=\\frac{11}{3}$"],"설명":"수심은 세 수선이 만나는 점이므로 두 수선의 교점이 $\\mathrm{H}$ 이다.","확인":"11/3","스킬":"S7"}]},"ns-5ab98defae5d":{"길":"두 직선의 교점이 원점임을 써서 직각삼각형의 넓이로 k를 정한다","단계":[{"제목":"나머지 두 꼭짓점 구하기","힌트":"$y=-\\frac12x+k$ 와 각 직선을 연립하면 교점의 좌표는?","식":["$-3x=-\\frac12x+k\\ \\Rightarrow\\ \\mathrm{A}\\left(-\\frac{2k}{5},\\ \\frac{6k}{5}\\right)$","$\\frac13x=-\\frac12x+k\\ \\Rightarrow\\ \\mathrm{B}\\left(\\frac{6k}{5},\\ \\frac{2k}{5}\\right)$"],"설명":"$y=-3x$ 와 $y=\\frac13x$ 의 교점은 원점 $\\mathrm{O}$ 이므로, 나머지 두 꼭짓점 $\\mathrm{A}$, $\\mathrm{B}$ 는 이 직선들과 $y=-\\frac12x+k$ 의 교점이다.","확인":null,"스킬":"G1"},{"제목":"삼각형 AOB의 모양과 변의 길이","고비":true,"힌트":"두 직선 $y=-3x$, $y=\\frac13x$ 의 기울기의 곱과 $\\overline{\\mathrm{OA}}^{2}$, $\\overline{\\mathrm{OB}}^{2}$ 은?","식":["$-3\\times\\frac13=-1$","$\\overline{\\mathrm{OA}}^{2}=\\left(\\frac{2k}{5}\\right)^{2}+\\left(\\frac{6k}{5}\\right)^{2}=\\frac{40k^{2}}{25}$","$\\overline{\\mathrm{OB}}^{2}=\\left(\\frac{6k}{5}\\right)^{2}+\\left(\\frac{2k}{5}\\right)^{2}=\\frac{40k^{2}}{25}$"],"설명":"기울기의 곱이 $-1$ 이므로 두 직선은 원점에서 수직으로 만난다. $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$ 이므로 삼각형 $\\mathrm{AOB}$ 는 직각이등변삼각형이다.","확인":null,"스킬":"S4"},{"제목":"넓이 조건으로 k² 구하기","힌트":"직각을 낀 두 변이 같으므로 넓이는 $\\frac12\\overline{\\mathrm{OA}}^{2}$ 이다. 넓이가 $5$ 이면 $k^{2}$ 은?","식":["$\\frac12\\times\\frac{40k^{2}}{25}=5$","$\\frac{4k^{2}}{5}=5$","$k^{2}=\\frac{25}{4}$"],"설명":"$\\frac12\\times\\frac{40k^{2}}{25}=\\frac{4k^{2}}{5}$ 이므로 이 값이 $5$ 가 되는 $k^{2}$ 을 구한다.","확인":"25/4","스킬":"G10"},{"제목":"k의 값 구하기","힌트":"$k^{2}=\\frac{25}{4}$ 를 만족하는 $k$ 는?","식":["$k=\\pm\\frac52$"],"설명":"제곱해서 $\\frac{25}{4}$ 가 되는 수는 양수와 음수 두 개이다. 두 값 모두 $k\\ne0$ 이므로 삼각형이 만들어진다.","확인":null,"스킬":"G10"}]},"ns-5cc9aaf6b51c":{"길":"점 P를 t로 두고 직선 l을 t에 대한 식으로 정리해 정점을 찾는다","단계":[{"제목":"점 P, Q, R와 수직인 기울기","힌트":"$\\mathrm{P}(t,\\ 2-t)$ 로 두면 직선 $\\mathrm{QR}$ 의 기울기와 그에 수직인 기울기는?","식":["$\\mathrm{P}(t,\\ 2-t),\\ \\mathrm{Q}(t,\\ 0),\\ \\mathrm{R}(0,\\ 2-t)$","$\\frac{(2-t)-0}{0-t}=\\frac{t-2}{t}$","$m_{l}=-\\frac{t}{t-2}$"],"설명":"점 $\\mathrm{P}$ 가 직선 $x+y=2$ 위에 있으므로 $a=t$ 라 하면 $b=2-t$ 이다. 수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":null,"스킬":"G3"},{"제목":"직선 l의 방정식을 t로 정리하기","힌트":"$\\mathrm{P}$ 를 지나고 기울기가 $-\\frac{t}{t-2}$ 인 직선을 $t$ 에 대한 식으로 묶으면?","식":["$y-(2-t)=-\\frac{t}{t-2}(x-t)$","$t(x+y-4)-2y+4=0$"],"설명":"양변에 $t-2$ 를 곱해 전개하면 $t^{2}$ 항이 양쪽에서 사라지고 $t$ 에 대한 일차식이 된다.","확인":null,"스킬":"G3"},{"제목":"t에 관계없이 지나는 점 찾기","고비":true,"힌트":"$t$ 에 대한 항등식으로 보면 $t$ 의 계수와 나머지 항은 각각 어떤 조건을 만족하는가?","식":["$x+y-4=0$","$-2y+4=0$","$(c,\\ d)=(2,\\ 2)$"],"설명":"$t$ 의 값에 관계없이 성립하려면 $t$ 의 계수 $x+y-4$ 와 나머지 $-2y+4$ 가 모두 $0$ 이어야 한다. 두 식을 연립한 해가 직선 $l$ 이 항상 지나는 점이다.","확인":null,"스킬":"G3"},{"제목":"c²+d²의 값 구하기","힌트":"$(c,\\ d)=(2,\\ 2)$ 일 때 $c^{2}+d^{2}$ 은?","식":["$c^{2}+d^{2}=2^{2}+2^{2}=8$"],"설명":"정점의 좌표를 각각 제곱해 더한다.","확인":"8","스킬":"G3"}]},"ns-5de00584420c":{"길":"보기마다 수직·평행·정점 조건을 따로 확인한다","단계":[{"제목":"ㄱ 수직 조건 확인","힌트":"수직 조건 $a_{1}a_{2}+b_{1}b_{2}=0$ 에서 $k$ 의 값은?","식":["$k\\cdot1+1\\cdot k=0$","$k=0$"],"설명":"두 직선 $a_{1}x+b_{1}y+c_{1}=0$, $a_{2}x+b_{2}y+c_{2}=0$ 이 수직이면 $a_{1}a_{2}+b_{1}b_{2}=0$ 이다. 이를 만족하는 $k$ 는 하나뿐이므로 ㄱ은 참이다.","확인":"0","스킬":"C3"},{"제목":"ㄴ 평행 조건 확인","고비":true,"힌트":"평행 조건에서 나온 $k$ 의 후보 중 두 직선이 겹치지 않는 것은?","식":["$\\frac{k}{1}=\\frac{1}{k}\\ \\Rightarrow\\ k=\\pm1$","$k=1:\\ l,\\ m\\ \\Rightarrow\\ x+y+2=0$","$k=-1:\\ l\\ \\Rightarrow\\ y=x,\\ \\ m\\ \\Rightarrow\\ y=x+2$"],"설명":"$k=1$ 이면 두 직선이 같은 직선이어서 평행이 아니다. 따라서 평행이 되는 $k$ 는 하나뿐이므로 ㄴ은 거짓이다.","확인":"-1","스킬":"C3"},{"제목":"ㄷ 정점을 지나는 직선 확인","힌트":"$k$ 에 대한 항등식으로 보아 $l$, $m$ 이 $k$ 와 관계없이 지나는 점을 구하면?","식":["$l:\\ k(x+1)+y+1=0\\ \\Rightarrow\\ (-1,\\ -1)$","$m:\\ ky+x+2=0\\ \\Rightarrow\\ (-2,\\ 0)$","$y=\\frac{0-(-1)}{-2-(-1)}(x+2)\\ \\Rightarrow\\ x+y+2=0$"],"설명":"$l$ 은 $x+1=0$, $y+1=0$ 일 때 $k$ 와 무관하게 성립하고, $m$ 은 $y=0$, $x+2=0$ 일 때 성립한다. 두 점을 지나는 직선이 $x+y+2=0$ 이므로 ㄷ은 참이다.","확인":null,"스킬":"G3"},{"제목":"옳은 보기 고르기","힌트":"참인 보기만 모으면?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참"],"설명":"세 보기의 참 거짓을 모아 옳은 것만 고른다.","확인":null,"스킬":"C3"}]},"ns-5f0bb6fbfb59":{"길":"그림에서 a, b, c의 부호 관계를 읽어 새 직선의 기울기와 절편을 따진다","단계":[{"제목":"그림에서 a, b, c의 부호 관계 읽기","힌트":"그림의 직선은 기울기와 $y$ 절편이 각각 양수인가 음수인가?","식":["$y=-\\frac{a}{b}x-\\frac{c}{b}$","$-\\frac{a}{b}<0,\\ \\ -\\frac{c}{b}>0$","$\\frac{a}{b}>0,\\ \\ \\frac{c}{b}<0$"],"설명":"그림의 직선은 오른쪽 아래로 향하므로 기울기가 음수이고, $y$ 축과 양의 부분에서 만나므로 $y$ 절편이 양수이다. 따라서 $a$ 와 $b$ 는 같은 부호, $c$ 와 $b$ 는 다른 부호이다.","확인":null,"스킬":"G9"},{"제목":"새 직선의 기울기와 y절편의 부호","고비":true,"힌트":"$bx+cy+a=0$ 을 $y=\\cdots$ 꼴로 쓰고 $\\frac{b}{c}$, $\\frac{a}{c}$ 의 부호를 보면?","식":["$y=-\\frac{b}{c}x-\\frac{a}{c}$","$-\\frac{b}{c}>0,\\ \\ -\\frac{a}{c}>0$"],"설명":"$b$ 와 $c$ 는 다른 부호이므로 $\\frac{b}{c}<0$ 이고, $a$ 와 $c$ 도 다른 부호이므로 $\\frac{a}{c}<0$ 이다. 따라서 기울기와 $y$ 절편이 모두 양수이다.","확인":null,"스킬":"N5"},{"제목":"지나지 않는 사분면 찾기","힌트":"기울기와 $y$ 절편이 모두 양수인 직선이 지나는 사분면은?","식":["기울기 $>0$, $y$ 절편 $>0$ → 제 $1,\\ 2,\\ 3$ 사분면"],"설명":"$y$ 절편이 양수이므로 $y$ 축 위쪽을 지나고, 기울기가 양수이므로 오른쪽으로 갈수록 올라가 제1사분면을, 왼쪽으로 가면 제2사분면을 지난다. $x$ 절편은 음수이므로 제3사분면도 지나고, 지나지 않는 것은 제4사분면이다.","확인":null,"스킬":"G9"}]},"ns-672488330ad0":{"길":"원두 제한을 영역으로 그려 꼭짓점마다 이익을 비교한다","단계":[{"제목":"조건을 연립부등식으로 나타내기","힌트":"$A$, $B$ 를 $x$잔, $y$잔 만들 때 원두 $P$, $Q$ 의 제한은 어떻게 쓰는가?","식":["$7x+2y\\le60$","$2x+3y\\le39$","$x\\ge0,\\ y\\ge0$"],"설명":"원두 $P$ 는 $A$ 에 $7g$, $B$ 에 $2g$ 가 들고, 원두 $Q$ 는 $A$ 에 $2g$, $B$ 에 $3g$ 가 든다. 잔 수는 정수이므로 $x,\\ y$ 는 음이 아닌 정수이다.","확인":null,"스킬":"C7"},{"제목":"영역의 꼭짓점 구하기","힌트":"두 경계선 $7x+2y=60$, $2x+3y=39$ 의 교점의 $y$ 좌표는?","식":["$21x+6y=180,\\ \\ 4x+6y=78$","$17x=102\\ \\Rightarrow\\ x=6,\\ y=9$","$(0,\\ 0),\\ \\left(\\frac{60}{7},\\ 0\\right),\\ (6,\\ 9),\\ (0,\\ 13)$"],"설명":"두 식을 연립하면 교점은 $(6,\\ 9)$ 이다. 영역은 이 점과 $(0,\\ 0)$, $x$ 절편 $\\frac{60}{7}$, $y$ 절편 $13$ 을 꼭짓점으로 한다.","확인":"9","스킬":"G6"},{"제목":"변동 전 최대이익 a 구하기","힌트":"꼭짓점마다 이익 $5000x+3000y$ 를 구해 비교하면?","식":["$(0,\\ 0):\\ 0,\\ \\ (6,\\ 9):\\ 57000,\\ \\ (0,\\ 13):\\ 39000$","$\\left(\\frac{60}{7},\\ 0\\right):\\ \\frac{300000}{7}\\approx42857$","$a=57000$"],"설명":"일차식의 최댓값은 꼭짓점에서 생긴다. 가장 큰 값이 정수점인 꼭짓점 $(6,\\ 9)$ 에서 나오므로 잔 수가 정수라는 조건도 만족한다.","확인":"57000","스킬":"G6"},{"제목":"변동 후 최대이익 b 구하기","고비":true,"힌트":"같은 꼭짓점에서 이익 $3000x+6000y$ 를 비교하면?","식":["$(0,\\ 0):\\ 0,\\ \\ (6,\\ 9):\\ 72000,\\ \\ (0,\\ 13):\\ 78000$","$\\left(\\frac{60}{7},\\ 0\\right):\\ \\frac{180000}{7}\\approx25714$","$b=78000$"],"설명":"이번에는 $B$ 의 이익이 커져서 $B$ 만 만드는 꼭짓점 $(0,\\ 13)$ 에서 최대가 된다. 이 점도 정수점이므로 그대로 최대이익이 된다.","확인":"78000","스킬":"G6"},{"제목":"b−a의 값 구하기","힌트":"두 최대이익의 차는?","식":["$b-a=78000-57000=21000$"],"설명":"변동 후 최대이익에서 변동 전 최대이익을 뺀다.","확인":"21000","스킬":"C7"}]},"ns-6988a22d09c9":{"길":"k에 대해 정리해 거리식을 쓰고 분모의 최솟값을 찾는다","단계":[{"제목":"직선을 x, y에 대해 정리하기","힌트":"$k$ 가 붙은 항끼리 묶어 $ax+by+c=0$ 꼴로 쓰면?","식":["$-3x+y-2+k(x-y)=0$","$(k-3)x+(1-k)y-2=0$"],"설명":"$k$ 를 포함한 항 $kx-ky$ 를 $x$, $y$ 의 계수로 나누어 넣는다.","확인":null,"스킬":"G3"},{"제목":"원점과의 거리 f(k) 세우기","힌트":"원점에서 직선 $(k-3)x+(1-k)y-2=0$ 까지의 거리는?","식":["$f(k)=\\frac{|-2|}{\\sqrt{(k-3)^{2}+(1-k)^{2}}}$","$f(k)=\\frac{2}{\\sqrt{2k^{2}-8k+10}}$"],"설명":"원점과 직선 $ax+by+c=0$ 사이의 거리는 $\\frac{|c|}{\\sqrt{a^{2}+b^{2}}}$ 이다. 분모의 제곱근 안은 $(k-3)^{2}+(1-k)^{2}=2k^{2}-8k+10$ 이다.","확인":null,"스킬":"G3"},{"제목":"분모의 최솟값 구하기","고비":true,"힌트":"$2k^{2}-8k+10$ 을 완전제곱식으로 고치면 최솟값은 얼마인가?","식":["$2k^{2}-8k+10=2(k-2)^{2}+2$","$k=2$ 일 때 최솟값 $2$"],"설명":"$2(k-2)^{2}\\ge0$ 이므로 제곱근 안의 값은 $k=2$ 일 때 가장 작다.","확인":"2","스킬":"A6"},{"제목":"f(k)의 최댓값 구하기","힌트":"분모가 최소일 때 $f(k)$ 의 값은?","식":["$f(k)=\\frac{2}{\\sqrt{2}}=\\sqrt{2}$"],"설명":"분자가 양수 $2$ 로 일정하므로 분모가 최소일 때 $f(k)$ 가 최대이다.","확인":null,"스킬":"A6"}]},"ns-6d134ae013a2":{"길":"삼각비 값을 넣어 절편을 구하고 직각이등변삼각형의 넓이로 a를 정한다","단계":[{"제목":"삼각비 값을 넣어 절편 구하기","힌트":"$\\cos30^{\\circ},\\ \\sin60^{\\circ},\\ \\tan45^{\\circ}$ 의 값을 넣으면 $x$ 절편과 $y$ 절편은?","식":["$\\frac{\\sqrt{3}}{2}x+\\frac{\\sqrt{3}}{2}y=a$","$\\mathrm{A}\\left(\\frac{2a}{\\sqrt{3}},\\ 0\\right),\\ \\mathrm{B}\\left(0,\\ \\frac{2a}{\\sqrt{3}}\\right)$"],"설명":"$\\cos30^{\\circ}=\\sin60^{\\circ}=\\frac{\\sqrt{3}}{2}$, $\\tan45^{\\circ}=1$ 이다. $y=0$ 을 넣으면 $x$ 절편, $x=0$ 을 넣으면 $y$ 절편이 나온다.","확인":null,"스킬":"G9"},{"제목":"넓이 조건으로 a² 구하기","고비":true,"힌트":"$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$ 이므로 넓이를 $a$ 로 나타내고 $8$ 과 같다고 놓으면 $a^{2}$ 은?","식":["$\\frac12\\times\\frac{2a}{\\sqrt{3}}\\times\\frac{2a}{\\sqrt{3}}=\\frac{2a^{2}}{3}$","$\\frac{2a^{2}}{3}=8$","$a^{2}=12$"],"설명":"삼각형 $\\mathrm{OAB}$ 는 직각을 낀 두 변이 모두 $\\frac{2a}{\\sqrt{3}}$ 인 직각이등변삼각형이다.","확인":"12","스킬":"G10"},{"제목":"a의 값 구하기","힌트":"$a^{2}=12$ 이고 $a>0$ 이면 $a$ 는?","식":["$a=\\sqrt{12}=2\\sqrt{3}$"],"설명":"$a$ 가 양수이므로 양의 제곱근만 택한다.","확인":null,"스킬":"G10"}]},"ns-6e7c66ec2e87":{"길":"m과 관계없이 지나는 점을 찾고 선분의 두 끝 점을 지날 때 기울기를 비교한다","단계":[{"제목":"직선이 항상 지나는 정점 찾기","힌트":"$mx-y+m-1=0$ 을 $m$ 에 대해 묶으면 $m$ 과 관계없이 지나는 점은?","식":["$m(x+1)-(y+1)=0$","$(x,\\ y)=(-1,\\ -1)$"],"설명":"$m$ 에 대한 항등식으로 보면 $x+1=0$, $y+1=0$ 일 때 $m$ 의 값에 관계없이 성립한다. 따라서 이 직선은 기울기 $m$ 이 변해도 항상 점 $(-1,\\ -1)$ 을 지난다.","확인":null,"스킬":"G3"},{"제목":"제1사분면에서 만나는 범위 정하기","고비":true,"힌트":"직선 $2x+y-2=0$ 에서 제1사분면에 있는 부분은 어느 두 점 사이의 선분인가?","식":["$2x+y-2=0$ 의 $x$ 절편 $1$, $y$ 절편 $2$","$(1,\\ 0),\\ (0,\\ 2)$"],"설명":"제1사분면의 점은 $x>0$, $y>0$ 이다. 직선 $2x+y-2=0$ 에서 이를 만족하는 부분은 두 절편 $(1,\\ 0)$, $(0,\\ 2)$ 를 잇는 선분에서 양 끝점을 뺀 부분이다. 따라서 점 $(-1,\\ -1)$ 을 지나는 직선이 이 선분의 안쪽을 지나게 하면 된다.","확인":null,"스킬":"G6"},{"제목":"두 경계에서의 기울기 구하기","힌트":"$(-1,\\ -1)$ 과 $(1,\\ 0)$ 을 잇는 직선의 기울기는?","식":["$(1,\\ 0):\\ m=\\frac{0-(-1)}{1-(-1)}=\\frac12$","$(0,\\ 2):\\ m=\\frac{2-(-1)}{0-(-1)}=3$"],"설명":"양 끝점은 제외되므로 부등호에 등호가 붙지 않는다. 직선이 선분의 안쪽을 지나려면 $m$ 은 두 기울기 사이의 값이어야 한다.","확인":"1/2","스킬":"G9"},{"제목":"a+b의 값 구하기","힌트":"$a<m<b$ 와 비교해 $a+b$ 는?","식":["$\\frac12<m<3$","$a+b=\\frac12+3=\\frac72$"],"설명":"$m$ 의 범위의 양 끝이 $a$, $b$ 이다.","확인":"7/2","스킬":"G3"}]},"ns-70b6d8411b3b":{"길":"직선 위에서 원점과 가장 가까운 점은 원점에서 내린 수선의 발이다","단계":[{"제목":"원점을 지나는 수선의 방정식","고비":true,"힌트":"직선 $2x+y=5$ 의 기울기와 곱해서 $-1$ 이 되는 값은?","식":["$y=-2x+5$","$y=\\frac12x$"],"설명":"직선 위의 점 중 원점에 가장 가까운 점은 원점에서 이 직선에 내린 수선의 발이다. 수선의 기울기는 $\\frac12$ 이고 원점을 지난다.","확인":"1/2","스킬":"G9"},{"제목":"수선의 발 P의 좌표 구하기","힌트":"두 직선 $2x+y=5$, $y=\\frac12x$ 의 교점은?","식":["$2x+\\frac12x=5$","$x=2,\\ y=1$","$\\mathrm{P}(2,\\ 1)$"],"설명":"두 직선의 교점이 수선의 발이므로 연립해서 푼다.","확인":null,"스킬":"G1"}]},"ns-70b6da5ee400":{"길":"직선 l의 식으로 P, Q를 잡고 사다리꼴의 넓이 조건을 쓴다","단계":[{"제목":"직선 l과 두 점 P, Q의 좌표","힌트":"점 $(1,\\ 2)$ 를 지나고 기울기가 $m$ 인 직선이 $x=0$, $x=6$ 과 만나는 점은?","식":["$l:\\ y=m(x-1)+2$","$\\mathrm{P}(0,\\ 2-m),\\ \\mathrm{Q}(6,\\ 5m+2)$"],"설명":"직선 $l$ 의 식에 $x=0$ 과 $x=6$ 을 각각 대입하면 $\\mathrm{P}$, $\\mathrm{Q}$ 의 $y$ 좌표가 $m$ 의 식으로 나온다.","확인":null,"스킬":"G3"},{"제목":"사각형 OAQP의 넓이 구하기","힌트":"넓이의 비가 $1:2$ 이면 사각형 $\\mathrm{OAQP}$ 의 넓이는 직사각형 전체의 얼마인가?","식":["$\\square\\mathrm{OABC}=6\\times8=48$","$\\square\\mathrm{OAQP}=48\\times\\frac13=16$"],"설명":"두 사각형의 넓이의 비가 $1:2$ 이므로 사각형 $\\mathrm{OAQP}$ 는 전체의 $\\frac13$ 이다.","확인":"16","스킬":"G10"},{"제목":"넓이 식으로 기울기 구하기","고비":true,"힌트":"$\\overline{\\mathrm{OP}}$, $\\overline{\\mathrm{AQ}}$ 를 평행한 두 변으로 하는 사다리꼴의 넓이를 $m$ 으로 쓰면?","식":["$\\overline{\\mathrm{OP}}=2-m,\\ \\overline{\\mathrm{AQ}}=5m+2$","$\\frac12\\times6\\times(4m+4)=16$","$m=\\frac13$"],"설명":"$\\mathrm{OP}\\parallel\\mathrm{AQ}$ 이고 높이는 $\\overline{\\mathrm{OA}}=6$ 이다. 윗변과 아랫변의 합 $(2-m)+(5m+2)=4m+4$ 를 쓴다.","확인":"1/3","스킬":"G10"}]},"ns-710ee9ceb7c5":{"길":"밑변 AB는 고정이므로 높이가 최소인 접점을 찾는다","단계":[{"제목":"직선 AB의 방정식과 길이","힌트":"$\\mathrm{A}(5,\\ 2)$, $\\mathrm{B}(3,\\ -2)$ 를 지나는 직선의 기울기는?","식":["$\\frac{2-(-2)}{5-3}=2$","$\\mathrm{AB}:\\ y=2x-8$","$\\overline{\\mathrm{AB}}=\\sqrt{2^{2}+4^{2}}=2\\sqrt{5}$"],"설명":"삼각형의 넓이는 $\\frac12\\times\\overline{\\mathrm{AB}}\\times$(점 $\\mathrm{P}$ 에서 $\\mathrm{AB}$ 까지의 거리) 이고 $\\overline{\\mathrm{AB}}$ 는 고정이므로, 거리가 최소일 때 넓이가 최소이다.","확인":null,"스킬":"G10"},{"제목":"AB와 평행한 접선 찾기","고비":true,"힌트":"$\\mathrm{AB}$ 와 평행한 직선 $y=2x+k$ 가 $y=x^{2}$ 에 접하게 하는 $k$ 는?","식":["$x^{2}=2x+k\\ \\Rightarrow\\ x^{2}-2x-k=0$","$\\frac{D}{4}=1+k=0$","$k=-1$"],"설명":"곡선 위의 점 중 직선 $\\mathrm{AB}$ 에 가장 가까운 점은 $\\mathrm{AB}$ 와 평행한 접선의 접점이다. 접하려면 판별식이 $0$ 이어야 한다. 직선 $y=2x-8$ 은 곡선과 만나지 않아 곡선이 직선의 한쪽에만 있으므로 이 접점이 거리를 최소로 만든다.","확인":"-1","스킬":"G2"},{"제목":"두 평행선 사이의 거리 구하기","힌트":"직선 $2x-y-8=0$ 과 접선 위의 점 $(0,\\ -1)$ 사이의 거리는?","식":["$\\frac{|2\\times0-(-1)-8|}{\\sqrt{2^{2}+(-1)^{2}}}=\\frac{7}{\\sqrt{5}}$"],"설명":"평행한 두 직선 사이의 거리는 한 직선 위의 점에서 다른 직선까지의 거리와 같다.","확인":null,"스킬":"G10"},{"제목":"넓이의 최솟값 구하기","힌트":"밑변 $\\overline{\\mathrm{AB}}$ 와 높이로 넓이를 구하면?","식":["$\\frac12\\times2\\sqrt{5}\\times\\frac{7}{\\sqrt{5}}=7$"],"설명":"$\\sqrt{5}$ 가 약분되어 정수가 된다.","확인":"7","스킬":"G10"}]},"ns-748146df385c":{"길":"세 분수를 직선의 기울기로 읽어 크기를 비교한다","단계":[{"제목":"세 분수를 기울기로 읽기","힌트":"$\\mathrm{A}$ 를 원점에 두면 점 $\\mathrm{C}$ 와 점 $\\mathrm{P}$ 의 좌표는?","식":["$\\frac{n}{m}$ 은 $\\mathrm{AP}$ 의 기울기","$\\frac{b}{a}$ 는 $\\mathrm{AC}$ 의 기울기","$\\frac{b-n}{a-m}$ 은 $\\mathrm{PC}$ 의 기울기"],"설명":"$\\mathrm{A}$ 를 원점, $\\mathrm{AB}$ 를 $x$ 축, $\\mathrm{AD}$ 를 $y$ 축에 놓으면 $\\mathrm{C}(a,\\ b)$, $\\mathrm{P}(m,\\ n)$ 이다. 세 분수는 각각 두 점을 잇는 직선의 기울기이다.","확인":null,"스킬":"G9"},{"제목":"세 기울기의 크기 비교","고비":true,"힌트":"점 $\\mathrm{P}$ 는 대각선 $\\mathrm{AC}$ 의 위쪽에 있다. $\\mathrm{AP}$ 와 $\\mathrm{PC}$ 중 어느 쪽이 $\\mathrm{AC}$ 보다 가파른가?","식":["$\\frac{n}{m}>\\frac{b}{a}$","$\\frac{b-n}{a-m}<\\frac{b}{a}$"],"설명":"점 $\\mathrm{P}$ 가 직선 $\\mathrm{AC}$ 위쪽에 있으므로 $\\mathrm{A}$ 에서 $\\mathrm{P}$ 로 가는 직선은 $\\mathrm{AC}$ 보다 가파르고, $\\mathrm{P}$ 에서 $\\mathrm{C}$ 로 가는 직선은 $\\mathrm{AC}$ 보다 완만하다. 따라서 $\\frac{b-n}{a-m}<\\frac{b}{a}<\\frac{n}{m}$ 이다.","확인":null,"스킬":"G9"},{"제목":"보기의 참 거짓 가리기","힌트":"세 부등식과 맞는 보기는?","식":["ㄱ 거짓, ㄴ 거짓, ㄷ 참"],"설명":"ㄱ 은 $\\frac{n}{m}>\\frac{b}{a}$ 와 반대이고, ㄴ 은 $\\frac{n}{m}>\\frac{b-n}{a-m}$ 과 반대이므로 거짓이다. ㄷ 은 $\\frac{b-n}{a-m}<\\frac{b}{a}$ 와 같으므로 참이다.","확인":null,"스킬":"G9"}]},"ns-74bc5619d9ab":{"길":"이등변삼각형이므로 AM이 BC의 수직이등분선이고 M을 두 식에 넣는다","단계":[{"제목":"직선 AM의 방정식 세우기","힌트":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$ 이면 $\\mathrm{BC}$ 의 중점 $\\mathrm{M}$ 에서 $\\mathrm{AM}$ 과 $\\mathrm{BC}$ 는 어떤 관계인가?","식":["$\\mathrm{AM}\\perp\\mathrm{BC}\\ \\Rightarrow\\ \\mathrm{AM}$ 의 기울기 $-\\frac1m$","$y-3=-\\frac1m(x+2)$","$x+my-3m+2=0$"],"설명":"이등변삼각형의 꼭짓점 $\\mathrm{A}$ 에서 밑변의 중점 $\\mathrm{M}$ 으로 이은 선분은 밑변에 수직이다. $\\mathrm{BC}$ 의 기울기가 $m$ 이므로 $\\mathrm{AM}$ 의 기울기는 $-\\frac1m$ 이다.","확인":null,"스킬":"G9"},{"제목":"M(a, a)을 두 직선에 대입하기","고비":true,"힌트":"$\\mathrm{M}(a,\\ a)$ 가 $\\mathrm{AM}$ 위에 있을 때와 $\\mathrm{BC}$ 위에 있을 때 $a$ 를 $m$ 으로 쓰면?","식":["$a+ma-3m+2=0\\ \\Rightarrow\\ a=\\frac{3m-2}{m+1}$","$a=m(a-2)\\ \\Rightarrow\\ a=\\frac{2m}{m-1}$"],"설명":"점 $\\mathrm{M}$ 은 $y=x$ 위에 있으므로 $(a,\\ a)$ 로 놓고, $\\mathrm{AM}$ 과 $\\mathrm{BC}$ 의 식에 각각 넣어 $a$ 에 대해 푼다.","확인":null,"스킬":"G1"},{"제목":"m에 대한 이차방정식 세우기","힌트":"두 식의 $a$ 가 같다고 놓고 분모를 없애면?","식":["$\\frac{3m-2}{m+1}=\\frac{2m}{m-1}$","$(3m-2)(m-1)=2m(m+1)$","$m^{2}-7m+2=0$"],"설명":"양변에 $(m+1)(m-1)$ 을 곱해 분모를 없애고 전개해 정리한다.","확인":null,"스킬":"G1"},{"제목":"m의 값의 합 구하기","힌트":"서로 다른 두 실근인지 확인하고 근과 계수의 관계로 합을 구하면?","식":["$D=(-7)^{2}-4\\times1\\times2=41>0$","$m_{1}+m_{2}=7$"],"설명":"판별식이 양수이므로 서로 다른 두 실근을 가진다. 근과 계수의 관계에서 두 근의 합은 일차항 계수 $-7$ 의 부호를 바꾼 값이다.","확인":"7","스킬":"G1"}]},"ns-78c54ae77be7":{"길":"평행선 사이의 거리와 직선 l이 이루는 각으로 직각삼각형에서 길이를 구한다","단계":[{"제목":"평행선 사이의 거리와 MR의 길이","힌트":"$\\overline{\\mathrm{PQ}}$ 의 중점을 $\\mathrm{M}$, $\\mathrm{M}$ 에서 두 직선에 내린 수선의 발을 $\\mathrm{R}$, $\\mathrm{S}$ 라 하면 $\\overline{\\mathrm{MR}}$ 은?","식":["$\\frac{|0+2-4|}{\\sqrt{1^{2}+(-1)^{2}}}=\\sqrt{2}$","$\\overline{\\mathrm{MR}}=\\frac12\\times\\sqrt{2}=\\frac{\\sqrt{2}}{2}$"],"설명":"점 $(0,\\ -2)$ 는 $x-y-2=0$ 위에 있으므로 이 점에서 $x-y-4=0$ 까지의 거리가 두 평행선 사이의 거리이다. $\\mathrm{M}$ 은 두 직선의 한가운데에 있으므로 $\\overline{\\mathrm{MR}}$ 은 그 절반이다.","확인":null,"스킬":"S4"},{"제목":"삼각형 PRM의 각 구하기","고비":true,"힌트":"두 평행선이 $x$ 축과 이루는 각이 $45^{\\circ}$ 이고 $l$ 이 $75^{\\circ}$ 일 때, $\\angle\\mathrm{PMR}$ 은 몇 도인가?","식":["$75^{\\circ}-45^{\\circ}=30^{\\circ}$","$\\angle\\mathrm{PMR}=90^{\\circ}-30^{\\circ}=60^{\\circ}$"],"설명":"두 평행선의 기울기가 $1$ 이므로 $x$ 축과 이루는 각은 $45^{\\circ}$ 이고, $l$ 과 평행선이 이루는 각은 $30^{\\circ}$ 이다. 삼각형 $\\mathrm{PRM}$ 은 $\\angle\\mathrm{R}=90^{\\circ}$ 이므로 $\\angle\\mathrm{PMR}=60^{\\circ}$ 이다.","확인":"60","스킬":"S6"},{"제목":"PM의 길이 구하기","힌트":"직각삼각형 $\\mathrm{PRM}$ 에서 $\\overline{\\mathrm{MR}}=\\overline{\\mathrm{PM}}\\cos60^{\\circ}$ 를 쓰면?","식":["$\\frac{\\sqrt{2}}{2}=\\overline{\\mathrm{PM}}\\times\\frac12$","$\\overline{\\mathrm{PM}}=\\sqrt{2}$"],"설명":"$\\cos60^{\\circ}=\\frac12$ 이므로 $\\overline{\\mathrm{PM}}$ 은 $\\overline{\\mathrm{MR}}$ 의 $2$ 배이다.","확인":null,"스킬":"S6"},{"제목":"PQ의 길이 구하기","힌트":"$\\mathrm{M}$ 이 $\\overline{\\mathrm{PQ}}$ 의 중점이면 $\\overline{\\mathrm{PQ}}$ 는?","식":["$\\overline{\\mathrm{PQ}}=2\\overline{\\mathrm{PM}}=2\\sqrt{2}$"],"설명":"$\\mathrm{M}$ 이 $\\mathrm{PQ}$ 의 중점이므로 $\\overline{\\mathrm{PQ}}$ 는 $\\overline{\\mathrm{PM}}$ 의 $2$ 배이다.","확인":null,"스킬":"S6"}]},"ns-7f7333d9f209":{"길":"생산량을 문자로 두고 부등식 영역의 꼭짓점에서 이익이 최대인 점을 찾는다","단계":[{"제목":"생산량에 대한 부등식 세우기","고비":true,"힌트":"제품 $A$, $B$ 의 생산량을 $x$, $y$ 라 하면 원료와 전력의 조건은 각각 어떤 부등식인가?","식":["$30x+50y\\le2100,\\ 9x+6y\\le360$","$3x+5y\\le210,\\ 3x+2y\\le120$","$x\\ge0,\\ y\\ge0$"],"설명":"원료 사용량은 $30x+50y$, 전력 사용량은 $9x+6y$ 이고 각각 $2100$, $360$ 이하이다. 양변을 $10$, $3$ 으로 나누어 간단히 하고, 생산량은 $0$ 이상이다.","확인":null,"스킬":"C7"},{"제목":"경계선의 교점과 절편 구하기","힌트":"두 식 $3x+5y=210$, $3x+2y=120$ 을 변끼리 빼면 $y$ 는?","식":["$3y=90$","$(x,\\ y)=(20,\\ 30)$","$(0,\\ 0),\\ (40,\\ 0),\\ (0,\\ 42)$"],"설명":"두 식을 변끼리 빼면 $3y=90$ 이므로 $y=30$ 이고 $x=20$ 이다. 영역의 나머지 꼭짓점은 원점, 전력 직선의 $x$ 절편 $(40,\\ 0)$, 원료 직선의 $y$ 절편 $(0,\\ 42)$ 이다.","확인":"30","스킬":"G1"},{"제목":"꼭짓점에서 이익 비교하기","힌트":"이익 $6x+7y$ 의 값을 네 꼭짓점에서 구하면 가장 큰 값은?","식":["$6\\cdot0+7\\cdot0=0,\\ 6\\cdot40+7\\cdot0=240$","$6\\cdot0+7\\cdot42=294$","$6\\cdot20+7\\cdot30=330$"],"설명":"이익 $6x+7y$ 는 영역의 꼭짓점에서 최대가 된다. 네 꼭짓점 가운데 두 직선의 교점 $(20,\\ 30)$ 에서 가장 크므로 최대 이익은 $330$ 만 원이다.","확인":"330","스킬":"G6"}]},"ns-82013796f2b7":{"길":"이등분선의 비로 길이를 잡고 좌표에서 점 C를 정한 뒤 비로 나눈다","단계":[{"제목":"각의 이등분선 정리로 BD 구하기","힌트":"삼각형 $\\mathrm{ABD}$ 에서 $\\mathrm{BF}$ 가 $\\angle \\mathrm{B}$ 의 이등분선이면 $\\overline{\\mathrm{AF}}:\\overline{\\mathrm{FD}}$ 는 어떤 두 변의 비와 같은가?","식":["$\\overline{\\mathrm{AF}}:\\overline{\\mathrm{FD}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{BD}}$","$5:3=\\frac53:\\overline{\\mathrm{BD}}$","$\\overline{\\mathrm{BD}}=1$"],"설명":"$\\mathrm{BF}$ 는 삼각형 $\\mathrm{ABD}$ 에서 $\\angle \\mathrm{ABD}$ 의 이등분선이므로 $\\overline{\\mathrm{AF}}:\\overline{\\mathrm{FD}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{BD}}$ 이다. 이 비가 $5:3$ 이므로 $\\overline{\\mathrm{BD}}=\\frac53\\times\\frac35=1$ 이다.","확인":"1","스킬":"S10"},{"제목":"AD와 DF의 길이 구하기","힌트":"직각삼각형 $\\mathrm{ABD}$ 에서 빗변 $\\overline{\\mathrm{AB}}$ 와 한 변 $\\overline{\\mathrm{BD}}$ 를 알면 $\\overline{\\mathrm{AD}}$ 는?","식":["$\\overline{\\mathrm{AD}}=\\sqrt{\\left(\\frac53\\right)^{2}-1^{2}}=\\frac43$","$\\overline{\\mathrm{DF}}=\\frac38\\overline{\\mathrm{AD}}=\\frac12$"],"설명":"삼각형 $\\mathrm{ABD}$ 는 $\\angle \\mathrm{D}=90^{\\circ}$ 이므로 피타고라스 정리로 $\\overline{\\mathrm{AD}}$ 를 구한다. $\\mathrm{F}$ 가 $\\overline{\\mathrm{AD}}$ 를 $5:3$ 으로 나누므로 $\\overline{\\mathrm{DF}}$ 는 $\\overline{\\mathrm{AD}}$ 의 $\\frac38$ 이다.","확인":"4/3","스킬":"S3"},{"제목":"좌표를 놓고 직선 BF와 무게중심 구하기","힌트":"$\\mathrm{D}$ 를 원점, 직선 $\\mathrm{BC}$ 를 $x$ 축으로 놓으면 $\\mathrm{B}$, $\\mathrm{A}$, $\\mathrm{F}$ 의 좌표는?","식":["$\\mathrm{B}(-1,\\ 0),\\ \\mathrm{A}\\left(0,\\ \\frac43\\right),\\ \\mathrm{F}\\left(0,\\ \\frac12\\right),\\ \\mathrm{C}(k,\\ 0)$","$\\mathrm{BF}:\\ y=\\frac12x+\\frac12$","$\\mathrm{G}\\left(\\frac{k-1}{3},\\ \\frac49\\right)$"],"설명":"$\\mathrm{D}(0,\\ 0)$ 으로 놓으면 $\\mathrm{B}$ 는 $x$ 축 음의 방향에, $\\mathrm{A}$ 와 $\\mathrm{F}$ 는 $y$ 축 위에 있다. 점 $\\mathrm{C}$ 를 $(k,\\ 0)$ 으로 두면 무게중심 $\\mathrm{G}$ 는 세 꼭짓점 좌표의 평균이다. 직선 $\\mathrm{BF}$ 는 $\\mathrm{B}$, $\\mathrm{F}$ 를 지난다.","확인":null,"스킬":"S4"},{"제목":"거리 조건으로 BC의 길이 구하기","고비":true,"힌트":"점 $\\mathrm{G}$ 와 직선 $x-2y+1=0$ 사이의 거리 조건에서 $k$ 를 구하면 $\\overline{\\mathrm{BC}}=1+k$ 는?","식":["$\\frac{\\sqrt5}{15}=\\frac{\\left|\\frac{k-1}{3}-\\frac89+1\\right|}{\\sqrt5}=\\frac{\\left|\\frac k3-\\frac29\\right|}{\\sqrt5}$","$|3k-2|=3,\\ k=\\frac53$","$\\overline{\\mathrm{BC}}=1+k=\\frac83$"],"설명":"직선 $\\mathrm{BF}$ 는 $x-2y+1=0$ 이므로 점과 직선 사이의 거리 공식을 쓴다. $\\left|\\frac k3-\\frac29\\right|=\\frac13$ 에서 $|3k-2|=3$ 이고 $k=\\frac53$ 또는 $k=-\\frac13$ 이다. $\\mathrm{C}$ 는 $\\mathrm{D}$ 의 오른쪽에 있으므로 $k>0$ 이다.","확인":"8/3","스킬":"S4"},{"제목":"AC의 길이와 AE : EC 구하기","힌트":"$\\overline{\\mathrm{AC}}^{2}$ 은 직각삼각형 $\\mathrm{ADC}$ 에서 얼마이고, $\\mathrm{BE}$ 가 이등분선이면 $\\overline{\\mathrm{AE}}:\\overline{\\mathrm{EC}}$ 는?","식":["$\\overline{\\mathrm{AC}}^{2}=\\left(\\frac43\\right)^{2}+\\left(\\frac53\\right)^{2}=\\frac{41}{9}$","$\\overline{\\mathrm{AE}}:\\overline{\\mathrm{EC}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{BC}}=5:8$"],"설명":"$\\overline{\\mathrm{DC}}=k=\\frac53$ 이므로 직각삼각형 $\\mathrm{ADC}$ 에서 피타고라스 정리로 $\\overline{\\mathrm{AC}}^{2}$ 을 구한다. $\\mathrm{BE}$ 는 삼각형 $\\mathrm{ABC}$ 에서 $\\angle \\mathrm{B}$ 의 이등분선이므로 $\\overline{\\mathrm{AE}}:\\overline{\\mathrm{EC}}=\\frac53:\\frac83=5:8$ 이다.","확인":"41/9","스킬":"S3"},{"제목":"CE²−AE² 구하고 a+b 읽기","힌트":"$\\overline{\\mathrm{AC}}$ 를 $5:8$ 로 나눈 두 부분의 제곱의 차는 $\\overline{\\mathrm{AC}}^{2}$ 의 몇 배인가?","식":["$\\overline{\\mathrm{CE}}^{2}-\\overline{\\mathrm{AE}}^{2}=\\frac{64-25}{169}\\overline{\\mathrm{AC}}^{2}=\\frac{39}{169}\\times\\frac{41}{9}=\\frac{41}{39}$","$a=39,\\ b=41$","$a+b=80$"],"설명":"$\\overline{\\mathrm{AC}}$ 를 $5:8$ 로 나누면 $\\overline{\\mathrm{AE}}=\\frac5{13}\\overline{\\mathrm{AC}}$, $\\overline{\\mathrm{CE}}=\\frac8{13}\\overline{\\mathrm{AC}}$ 이다. 따라서 제곱의 차는 $\\frac{41}{39}$ 이고, $\\frac ba=\\frac{41}{39}$ 에서 $a$, $b$ 가 서로소이므로 $a=39$, $b=41$ 이다.","확인":"80","스킬":"A8"}]},"ns-84bb5787af1b":{"길":"일치와 평행은 계수비가 같다는 조건에서 시작하고 상수항으로 가른다","단계":[{"제목":"계수비 조건으로 k 후보 구하기","힌트":"$x$ 의 계수의 비와 $y$ 의 계수의 비가 같다는 식을 $k$ 로 세우면?","식":["$\\frac{k+1}{2}=\\frac{1}{-(k-2)}$","$(k+1)(k-2)=-2$","$k^{2}-k=0$"],"설명":"두 직선이 일치하거나 평행하려면 $x$ 의 계수의 비와 $y$ 의 계수의 비가 같아야 한다. 정리하면 $k(k-1)=0$ 이므로 $k=0$ 또는 $k=1$ 이다.","확인":null,"스킬":"G9"},{"제목":"상수항으로 일치와 평행 가르기","고비":true,"힌트":"$k=0$, $k=1$ 일 때 두 직선의 식을 각각 쓰면 완전히 같은가, 상수항만 다른가?","식":["$k=1:\\ 2x+y-1=0,\\ 2x+y-1=0$","$k=0:\\ x+y-1=0,\\ 2x+2y-1=0$","$a=1,\\ b=0$"],"설명":"$k=1$ 이면 두 식이 같으므로 일치하고 $a=1$ 이다. $k=0$ 이면 $x+y-1=0$ 과 $2x+2y-1=0$ 이고, 뒤의 식을 $x+y-\\frac12=0$ 으로 쓰면 $x$, $y$ 의 계수가 같고 상수항만 달라 평행하므로 $b=0$ 이다.","확인":"0","스킬":"G9"},{"제목":"a+2b의 값 구하기","힌트":"$a=1$, $b=0$ 을 $a+2b$ 에 대입하면?","식":["$a+2b=1+2\\times0=1$"],"설명":"일치할 때의 $k$ 가 $a=1$, 평행할 때의 $k$ 가 $b=0$ 이므로 $a+2b=1$ 이다.","확인":"1","스킬":"G9"}]},"ns-860d6faa1cee":{"길":"접어도 길이가 같음을 이용해 점의 좌표를 구하고 직선과의 거리를 잰다","단계":[{"제목":"접힌 점의 좌표 구하기","고비":true,"힌트":"접어도 $\\overline{\\mathrm{A}'\\mathrm{B}}=\\overline{\\mathrm{AB}}$ 이다. $\\mathrm{A}'(1,\\ k)$ 라 하면 $k^{2}$ 은?","식":["$\\mathrm{A}(0,\\ 0),\\ \\mathrm{B}(2,\\ 0),\\ \\mathrm{A}'(1,\\ k)$","$\\overline{\\mathrm{A}'\\mathrm{B}}=\\overline{\\mathrm{AB}}\\ \\Rightarrow\\ \\sqrt{1+k^{2}}=2$","$k^{2}=3,\\ k=\\sqrt3$"],"설명":"$\\mathrm{A}$ 를 원점, 변 $\\mathrm{AB}$ 를 $x$ 축에 놓으면 $\\mathrm{M}(1,\\ 0)$ 이므로 선분 $\\mathrm{MN}$ 위의 점 $\\mathrm{A}'$ 은 $(1,\\ k)$ 로 둘 수 있다. 접으면 $\\mathrm{A}$ 가 $\\mathrm{A}'$ 으로 옮겨지므로 $\\overline{\\mathrm{A}'\\mathrm{B}}=\\overline{\\mathrm{AB}}=2$ 이고, $1+k^{2}=4$ 에서 $k=\\sqrt3$ 이다.","확인":"3","스킬":"S4"},{"제목":"직선 A'B의 방정식 구하기","힌트":"두 점 $\\mathrm{A}'(1,\\ \\sqrt3)$, $\\mathrm{B}(2,\\ 0)$ 을 지나는 직선의 기울기는?","식":["$\\frac{0-\\sqrt3}{2-1}=-\\sqrt3$","$y=-\\sqrt3(x-2)$","$\\sqrt3x+y-2\\sqrt3=0$"],"설명":"기울기가 $-\\sqrt3$ 이고 $\\mathrm{B}(2,\\ 0)$ 을 지나므로 $y=-\\sqrt3x+2\\sqrt3$ 이다. 거리 공식에 쓰도록 $\\sqrt3x+y-2\\sqrt3=0$ 꼴로 바꾼다.","확인":null,"스킬":"G9"},{"제목":"점 A와 직선 사이의 거리 구하기","힌트":"원점에서 직선 $\\sqrt3x+y-2\\sqrt3=0$ 까지의 거리를 점과 직선 사이의 거리 공식으로 구하면?","식":["$\\frac{|\\sqrt3\\cdot0+0-2\\sqrt3|}{\\sqrt{(\\sqrt3)^{2}+1^{2}}}$","$=\\frac{2\\sqrt3}{2}=\\sqrt3$"],"설명":"점 $\\mathrm{A}$ 는 원점이므로 분자는 $|-2\\sqrt3|=2\\sqrt3$ 이고 분모는 $\\sqrt{3+1}=2$ 이다. 따라서 거리는 $\\sqrt3$ 이다.","확인":null,"스킬":"S4"}]},"ns-873e731ec8e7":{"길":"외각 이등분선 위의 점은 두 직선까지 거리가 같다는 식으로 y를 구한다","단계":[{"제목":"변 AB, AC의 직선 방정식 구하기","힌트":"직선 $\\mathrm{AC}$ 는 $\\mathrm{A}(3,\\ 6)$, $\\mathrm{C}\\left(\\frac32,\\ 0\\right)$ 를 지난다. 기울기는?","식":["$\\mathrm{AB}:\\ \\frac{6-0}{3-(-3)}=1,\\ y=x+3$","$\\mathrm{AC}:\\ \\frac{6-0}{3-\\frac32}=4,\\ y=4x-6$"],"설명":"두 점의 좌표로 기울기를 구하고 한 점을 대입해 식을 세운다. 직선 $\\mathrm{AB}$ 는 $x-y+3=0$, 직선 $\\mathrm{AC}$ 는 $4x-y-6=0$ 으로 쓸 수 있다.","확인":"4","스킬":"G9"},{"제목":"P에서 두 직선까지의 거리 식 세우기","힌트":"외각의 이등분선 위의 점은 두 변을 지나는 직선에서 같은 거리에 있다. $\\mathrm{P}(0,\\ y)$ 에서 직선 $\\mathrm{AC}$, $\\mathrm{AB}$ 까지의 거리는?","식":["$d_{1}=\\frac{|\\,0-y-6\\,|}{\\sqrt{4^{2}+1^{2}}}=\\frac{|\\,y+6\\,|}{\\sqrt{17}}$","$d_{2}=\\frac{|\\,0-y+3\\,|}{\\sqrt{1^{2}+1^{2}}}=\\frac{|\\,y-3\\,|}{\\sqrt{2}}$"],"설명":"각의 이등분선 위의 점은 각을 이루는 두 직선에서 같은 거리에 있다. 점 $\\mathrm{P}(0,\\ y)$ 에서 직선 $4x-y-6=0$ 과 $x-y+3=0$ 까지의 거리를 점과 직선 사이의 거리 공식으로 구한다.","확인":null,"스킬":"S4"},{"제목":"절댓값을 풀어 방정식 세우기","고비":true,"힌트":"그림에서 점 $\\mathrm{P}$ 는 점 $\\mathrm{A}$ 보다 위에 있다. 이때 $y+6$, $y-3$ 의 부호는?","식":["$y>6$ 이므로 $|\\,y+6\\,|=y+6,\\ |\\,y-3\\,|=y-3$","$\\frac{y+6}{\\sqrt{17}}=\\frac{y-3}{\\sqrt{2}}$","$\\sqrt{2}\\,y+6\\sqrt{2}=\\sqrt{17}\\,y-3\\sqrt{17}$"],"설명":"$d_{1}=d_{2}$ 로 놓는다. 그림에서 $\\mathrm{P}$ 는 $\\mathrm{A}$ 보다 위에 있어 $y>6$ 이므로 두 절댓값 안이 모두 양수이다. 양변에 $\\sqrt{2}\\sqrt{17}$ 을 곱하면 아래 식이 된다.","확인":null,"스킬":"C2"},{"제목":"y좌표 구하기","힌트":"$y$ 항을 한쪽으로 모아 정리하고 분모를 유리화하면 $y$ 는?","식":["$\\left(\\sqrt{17}-\\sqrt{2}\\right)y=6\\sqrt{2}+3\\sqrt{17}$","$y=\\frac{\\left(6\\sqrt{2}+3\\sqrt{17}\\right)\\left(\\sqrt{17}+\\sqrt{2}\\right)}{15}$","$y=\\frac{21+3\\sqrt{34}}{5}$"],"설명":"분모 $\\sqrt{17}-\\sqrt{2}$ 에 $\\sqrt{17}+\\sqrt{2}$ 를 곱하면 $17-2=15$ 로 유리화된다. 분자는 $63+9\\sqrt{34}$ 이므로 $15$ 로 약분하면 위의 값이 된다.","확인":null,"스킬":"A5"},{"제목":"a, b를 읽고 a+b 구하기","힌트":"$y=\\frac{a+b\\sqrt{34}}{5}$ 와 비교하면 $a$, $b$ 는?","식":["$a=21,\\ b=3$","$a+b=24$"],"설명":"$a$, $b$ 가 유리수이므로 유리수 부분과 $\\sqrt{34}$ 의 계수를 각각 비교한다. $a=21$, $b=3$ 이므로 $a+b=24$ 이다.","확인":"24","스킬":"A3"}]},"ns-8943d7a1944a":{"길":"정사각형을 좌표에 놓고 두 교점을 구해 사각형 넓이를 좌표로 잰다","단계":[{"제목":"좌표를 놓고 세 직선의 방정식 구하기","힌트":"$\\mathrm{B}$ 를 원점, 변 $\\mathrm{BC}$ 를 $x$ 축, 변 $\\mathrm{BA}$ 를 $y$ 축에 놓으면 직선 $\\mathrm{AF}$ 의 기울기는?","식":["$\\mathrm{A}(0,\\ 2),\\ \\mathrm{B}(0,\\ 0),\\ \\mathrm{C}(2,\\ 0),\\ \\mathrm{D}(2,\\ 2),\\ \\mathrm{E}(0,\\ 1),\\ \\mathrm{F}(1,\\ 0)$","$\\mathrm{AF}:\\ y=2-2x,\\ \\mathrm{DE}:\\ y=1+\\frac{x}{2}$","$\\mathrm{DB}:\\ y=x$"],"설명":"변의 길이가 $2$ 이므로 $\\mathrm{B}$ 를 원점에 두면 꼭짓점과 중점의 좌표가 위와 같다. 각 직선은 두 점의 좌표로 기울기를 구해 세운다.","확인":"-2","스킬":"S4"},{"제목":"교점 P의 좌표 구하기","힌트":"직선 $\\mathrm{AF}$ 와 $\\mathrm{DE}$ 를 연립하면 점 $\\mathrm{P}$ 의 $y$ 좌표는?","식":["$2-2x=1+\\frac{x}{2}$","$x=\\frac25$","$\\mathrm{P}\\left(\\frac25,\\ \\frac65\\right)$"],"설명":"점 $\\mathrm{P}$ 는 두 직선 $\\mathrm{AF}$, $\\mathrm{DE}$ 의 교점이므로 두 식을 연립한다. $x=\\frac25$ 를 $y=2-2x$ 에 대입하면 $y=\\frac65$ 이다.","확인":"6/5","스킬":"G1"},{"제목":"교점 Q의 좌표 구하기","힌트":"직선 $\\mathrm{AF}$ 와 $\\mathrm{DB}$ 를 연립하면 점 $\\mathrm{Q}$ 의 $x$ 좌표는?","식":["$2-2x=x$","$x=\\frac23$","$\\mathrm{Q}\\left(\\frac23,\\ \\frac23\\right)$"],"설명":"점 $\\mathrm{Q}$ 는 두 직선 $\\mathrm{AF}$, $\\mathrm{DB}$ 의 교점이다. $\\mathrm{DB}$ 는 $y=x$ 이므로 $x$ 와 $y$ 가 같다.","확인":"2/3","스킬":"G1"},{"제목":"신발끈 공식으로 넓이 구하기","고비":true,"힌트":"$\\mathrm{E}$, $\\mathrm{B}$, $\\mathrm{Q}$, $\\mathrm{P}$ 를 차례로 적어 신발끈 공식을 쓰면 넓이는?","식":["$\\mathrm{E}(0,\\ 1)\\to\\mathrm{B}(0,\\ 0)\\to\\mathrm{Q}\\left(\\frac23,\\ \\frac23\\right)\\to\\mathrm{P}\\left(\\frac25,\\ \\frac65\\right)\\to\\mathrm{E}$","$\\frac12\\left|\\left(\\frac23\\cdot\\frac65-\\frac25\\cdot\\frac23\\right)+\\left(\\frac25\\cdot1-0\\cdot\\frac65\\right)\\right|=\\frac12\\cdot\\frac{14}{15}$","$=\\frac{7}{15}$"],"설명":"꼭짓점을 한 방향으로 차례로 적고 $x_{i}y_{i+1}-x_{i+1}y_{i}$ 를 모두 더해 절댓값의 절반을 취한다. $\\mathrm{E}\\to\\mathrm{B}$ 와 $\\mathrm{B}\\to\\mathrm{Q}$ 의 항은 $0$ 이다.","확인":"7/15","스킬":"G10"}]},"ns-8b2cd37e1746":{"길":"두 넓이 조건을 삼각형 넓이의 같음으로 바꾸고 좌표로 k를 구한다","단계":[{"제목":"기울기와 길이 조건으로 점의 좌표 놓기","힌트":"$\\overline{\\mathrm{OA}}=k$ 라 하고 직선 $l$ 의 기울기 $-3$ 을 이용하면 $\\mathrm{B}$ 의 $y$ 좌표는?","식":["$\\mathrm{A}(k,\\ 0),\\ \\mathrm{C}(3k,\\ 0)$","$l:\\ y=-3(x-k)$","$\\mathrm{B}(0,\\ 3k)$"],"설명":"$\\overline{\\mathrm{OC}}=3\\overline{\\mathrm{OA}}$ 이므로 $\\mathrm{A}(k,\\ 0)$ 이면 $\\mathrm{C}(3k,\\ 0)$ 이다. 직선 $l$ 은 $\\mathrm{A}$ 를 지나고 기울기가 $-3$ 이므로 $y$ 절편은 $3k$ 이다.","확인":null,"스킬":"S4"},{"제목":"넓이 조건을 삼각형의 넓이 비교로 바꾸기","고비":true,"힌트":"□$\\mathrm{PDOA}$ 와 △$\\mathrm{PCB}$ 에 같은 △$\\mathrm{PAC}$ 를 더해 두 삼각형의 넓이를 비교하면 $d$ 는 $k$ 의 몇 배인가?","식":["$\\square\\mathrm{PDOA}+\\triangle\\mathrm{PAC}=\\triangle\\mathrm{DOC}$","$\\triangle\\mathrm{PCB}+\\triangle\\mathrm{PAC}=\\triangle\\mathrm{BAC}$","$\\frac12\\cdot3k\\cdot d=\\frac12\\cdot2k\\cdot3k\\ \\Rightarrow\\ d=2k$"],"설명":"□$\\mathrm{PDOA}$ 와 △$\\mathrm{PCB}$ 의 넓이가 같으므로 양쪽에 △$\\mathrm{PAC}$ 를 더해도 같다. 그러면 △$\\mathrm{DOC}$ 와 △$\\mathrm{BAC}$ 의 넓이가 같아져 $\\mathrm{D}(0,\\ d)$ 에서 $d=2k$ 를 얻는다.","확인":"2","스킬":"S8"},{"제목":"교점 P의 좌표 구하기","힌트":"직선 $m$ 은 $\\mathrm{C}(3k,\\ 0)$, $\\mathrm{D}(0,\\ 2k)$ 를 지난다. $l$ 과 $m$ 의 교점 $\\mathrm{P}$ 의 $x$ 좌표는 $k$ 의 몇 배인가?","식":["$m:\\ y=-\\frac23x+2k$","$-3x+3k=-\\frac23x+2k$","$\\mathrm{P}\\left(\\frac{3k}{7},\\ \\frac{12k}{7}\\right)$"],"설명":"직선 $m$ 의 기울기는 $-\\frac{2k}{3k}=-\\frac23$ 이고 $y$ 절편은 $2k$ 이다. $l:\\ y=-3x+3k$ 와 연립하면 $k=\\frac73x$ 이므로 $x=\\frac{3k}{7}$, $y=\\frac{12k}{7}$ 이다.","확인":"3/7","스킬":"G1"},{"제목":"넓이 9로 k²의 값 구하기","힌트":"△$\\mathrm{PCB}$ 의 넓이를 △$\\mathrm{BAC}$ 에서 △$\\mathrm{PAC}$ 를 빼서 $k$ 로 나타내면 $k^{2}$ 은?","식":["$\\triangle\\mathrm{BAC}=\\frac12\\cdot2k\\cdot3k=3k^{2}$","$\\triangle\\mathrm{PAC}=\\frac12\\cdot2k\\cdot\\frac{12k}{7}=\\frac{12}{7}k^{2}$","$3k^{2}-\\frac{12}{7}k^{2}=\\frac97k^{2}=9,\\ k^{2}=7$"],"설명":"점 $\\mathrm{P}$ 가 $\\overline{\\mathrm{AB}}$ 위에 있으므로 △$\\mathrm{BAC}$ 는 △$\\mathrm{PCB}$ 와 △$\\mathrm{PAC}$ 로 나뉜다. 밑변 $\\overline{\\mathrm{AC}}=2k$ 이고 $\\mathrm{P}$ 의 높이는 $\\frac{12k}{7}$ 이다.","확인":"7","스킬":"G10"},{"제목":"ab의 값 구하기","힌트":"$a=\\frac{3k}{7}$, $b=\\frac{12k}{7}$ 의 곱에 $k^{2}=7$ 을 대입하면?","식":["$ab=\\frac{3k}{7}\\times\\frac{12k}{7}=\\frac{36}{49}k^{2}$","$=\\frac{36}{49}\\times7=\\frac{36}{7}$"],"설명":"점 $\\mathrm{P}(a,\\ b)$ 의 좌표는 $a=\\frac{3k}{7}$, $b=\\frac{12k}{7}$ 이다. 곱 $ab$ 에 $k^{2}=7$ 을 대입한다.","확인":"36/7","스킬":"G10"}]},"ns-8b6c0af64d27":{"길":"세 경계 직선의 교점을 구해 원점을 포함한 삼각형 넓이로 잰다","단계":[{"제목":"부등식을 y에 대해 정리해 영역 읽기","고비":true,"힌트":"세 부등식을 $y\\ge$, $y\\le$ 꼴로 고치면 영역은 어떤 직선들로 둘러싸이는가?","식":["$y\\ge2x$","$y\\ge-\\frac43x$","$y\\le-\\frac12x+\\frac52$"],"설명":"각 부등식을 $y$ 에 대해 정리한다. 앞의 두 직선은 원점을 지나고 그 위쪽, 셋째 직선의 아래쪽이므로 영역은 원점과 두 교점을 꼭짓점으로 하는 삼각형이다.","확인":null,"스킬":"G6"},{"제목":"두 교점 A, B 구하기","힌트":"$y=-\\frac43x$ 와 $y=-\\frac12x+\\frac52$ 를 연립하면 점 $\\mathrm{B}$ 의 $y$ 좌표는?","식":["$2x=-\\frac12x+\\frac52\\ \\Rightarrow\\ \\mathrm{A}(1,\\ 2)$","$-\\frac43x=-\\frac12x+\\frac52\\ \\Rightarrow\\ \\mathrm{B}(-3,\\ 4)$"],"설명":"점 $\\mathrm{A}$ 는 $y=2x$ 와 $y=-\\frac12x+\\frac52$ 의 교점, 점 $\\mathrm{B}$ 는 $y=-\\frac43x$ 와 $y=-\\frac12x+\\frac52$ 의 교점이다.","확인":"4","스킬":"G1"},{"제목":"수선을 내려 사다리꼴 만들기","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 에서 $x$ 축에 수선을 내려 만든 사다리꼴의 넓이는?","식":["$\\frac12(2+4)\\times4=12$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$ 에서 $x$ 축에 내린 수선의 길이는 $2$, $4$ 이고 두 수선 사이의 거리는 $1-(-3)=4$ 이다. 이 사다리꼴 안에 삼각형 $\\mathrm{ABO}$ 와 두 직각삼각형이 들어 있다.","확인":"12","스킬":"G10"},{"제목":"두 직각삼각형을 빼 넓이 구하기","힌트":"사다리꼴에서 $\\mathrm{O}$ 의 양쪽에 있는 두 직각삼각형을 빼면?","식":["$\\frac12\\times3\\times4+\\frac12\\times1\\times2=7$","$12-7=5$"],"설명":"$\\mathrm{O}$ 의 왼쪽 직각삼각형은 밑변 $3$, 높이 $4$ 이고 오른쪽 직각삼각형은 밑변 $1$, 높이 $2$ 이다. 사다리꼴 넓이에서 두 넓이의 합을 빼면 삼각형 $\\mathrm{ABO}$ 의 넓이이다.","확인":"5","스킬":"G10"}]},"ns-8b957036ebe6":{"길":"밑변은 두 평행선 사이의 거리, 높이는 넓이에서 거꾸로 구한다","단계":[{"제목":"직선 PQ의 기울기 구하기","힌트":"$\\mathrm{PQ}$ 는 기울기가 $2$ 인 두 직선에 수직이다. 기울기의 곱은?","식":["$2\\times a=-1$","$a=-\\frac12$"],"설명":"서로 수직인 두 직선의 기울기의 곱은 $-1$ 이다. 따라서 직선 $\\mathrm{PQ}$ 의 기울기 $a$ 는 $-\\frac12$ 이다.","확인":"-1/2","스킬":"G9"},{"제목":"PQ의 길이 구하기","힌트":"$y=2x+6$ 위의 점 $(0,\\ 6)$ 에서 직선 $2x-y-4=0$ 까지의 거리는?","식":["$\\frac{|2\\cdot0-6-4|}{\\sqrt{2^{2}+1^{2}}}=\\frac{10}{\\sqrt5}$","$\\overline{\\mathrm{PQ}}=2\\sqrt5$"],"설명":"$\\mathrm{PQ}$ 가 두 평행선에 수직이므로 길이는 평행선 사이의 거리이다. 한 직선 위의 점 $(0,\\ 6)$ 에서 다른 직선까지의 거리를 구한다.","확인":null,"스킬":"G9"},{"제목":"원점에서 직선 PQ까지의 높이 구하기","고비":true,"힌트":"삼각형 $\\mathrm{OPQ}$ 의 넓이가 $20$ 이고 밑변이 $2\\sqrt5$ 일 때 높이는?","식":["$\\frac12\\times2\\sqrt5\\times h=20$","$h=\\frac{20}{\\sqrt5}=4\\sqrt5$"],"설명":"삼각형 $\\mathrm{OPQ}$ 의 밑변을 $\\overline{\\mathrm{PQ}}$ 로 보면 높이는 원점에서 직선 $\\mathrm{PQ}$ 까지의 거리 $h$ 이다.","확인":null,"스킬":"S8"},{"제목":"거리 공식으로 b 구하기","힌트":"원점에서 직선 $-\\frac12x-y+b=0$ 까지의 거리가 $4\\sqrt5$ 일 때 $b$ 는?","식":["$\\frac{|b|}{\\sqrt{\\frac14+1}}=4\\sqrt5$","$|b|=10,\\ b=10$"],"설명":"$|b|=4\\sqrt5\\times\\frac{\\sqrt5}{2}=10$ 이다. $\\mathrm{P}$, $\\mathrm{Q}$ 가 제 $1$ 사분면 위의 점이므로 $y$ 절편 $b$ 는 양수이고 $b=10$ 이다.","확인":"10","스킬":"G9"},{"제목":"ab의 값 구하기","힌트":"$a=-\\frac12$, $b=10$ 을 곱하면?","식":["$ab=-\\frac12\\times10=-5$"],"설명":"구한 $a$, $b$ 를 곱한다.","확인":"-5","스킬":"G9"}]},"ns-8fe1c38655dc":{"길":"접선은 중근 조건으로, 수직인 직선은 기울기의 곱 -1로 구한다","단계":[{"제목":"접선 l1과 점 Q 구하기","고비":true,"힌트":"$l_{1}:\\ y=m(x-1)+1$ 과 $y=x^{2}$ 을 연립한 식이 중근을 가지면 $m$ 은?","식":["$x^{2}=m(x-1)+1\\ \\Rightarrow\\ x^{2}-mx+m-1=0$","$D=m^{2}-4(m-1)=(m-2)^{2}=0$","$m=2,\\ l_{1}:\\ y=2x-1,\\ \\mathrm{Q}(0,\\ -1)$"],"설명":"접선은 포물선과 한 점에서만 만나므로 연립한 이차방정식이 중근을 가진다. 판별식 $D=0$ 에서 $m=2$ 이고 $y$ 절편이 $-1$ 이므로 $\\mathrm{Q}(0,\\ -1)$ 이다.","확인":"2","스킬":"G2"},{"제목":"수직인 직선 l2 구하기","힌트":"$l_{1}$ 의 기울기가 $2$ 일 때 수직인 $l_{2}$ 의 기울기는?","식":["$2\\times m'=-1,\\ m'=-\\frac12$","$l_{2}:\\ y=-\\frac12(x-1)+1=-\\frac12x+\\frac32$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이므로 $l_{2}$ 의 기울기는 $-\\frac12$ 이다. $l_{2}$ 는 $\\mathrm{P}(1,\\ 1)$ 을 지난다.","확인":"-1/2","스킬":"G9"},{"제목":"교점 R 구하기","힌트":"$y=x^{2}$ 과 $l_{2}$ 를 연립해 점 $\\mathrm{P}$ 가 아닌 교점의 $y$ 좌표는?","식":["$x^{2}=-\\frac12x+\\frac32\\ \\Rightarrow\\ 2x^{2}+x-3=0$","$(2x+3)(x-1)=0$","$x=-\\frac32\\ (x\\ne1),\\ \\mathrm{R}\\left(-\\frac32,\\ \\frac94\\right)$"],"설명":"$x=1$ 은 점 $\\mathrm{P}$ 이므로 $\\mathrm{R}$ 의 $x$ 좌표는 $-\\frac32$ 이다. $y=x^{2}$ 에 대입하면 $y=\\frac94$ 이다.","확인":"9/4","스킬":"G2"},{"제목":"직각삼각형 PQR의 넓이 구하기","힌트":"$l_{1}$ 과 $l_{2}$ 가 수직이므로 $\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{PR}}$ 를 두 변으로 하는 직각삼각형이다. 두 길이는?","식":["$\\overline{\\mathrm{PQ}}=\\sqrt{1^{2}+2^{2}}=\\sqrt5$","$\\overline{\\mathrm{PR}}=\\sqrt{\\left(\\frac52\\right)^{2}+\\left(\\frac54\\right)^{2}}=\\frac{5\\sqrt5}{4}$","$\\frac12\\times\\sqrt5\\times\\frac{5\\sqrt5}{4}=\\frac{25}{8}$"],"설명":"삼각형 $\\mathrm{PQR}$ 는 $\\mathrm{P}$ 에서 직각이므로 두 변의 길이의 곱의 절반이 넓이이다. 두 점 사이의 거리 공식으로 $\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{PR}}$ 를 구한다.","확인":"25/8","스킬":"S3"}]},"ns-9272fb07cdb0":{"길":"Q의 x좌표를 t로 두고 넓이 조건을 이차방정식으로 만든 뒤 근의 곱을 쓴다","단계":[{"제목":"점 P의 좌표와 점 Q 놓기","힌트":"직선 $y=2x+1$ 이 $x$ 축과 만나는 점 $\\mathrm{P}$ 의 $x$ 좌표는?","식":["$0=2x+1\\ \\Rightarrow\\ \\mathrm{P}\\left(-\\frac12,\\ 0\\right)$","$\\mathrm{Q}(t,\\ 2t+1),\\ \\mathrm{H}(t,\\ 0)$"],"설명":"$x$ 축 위의 점은 $y=0$ 이므로 $2x+1=0$ 에서 $x=-\\frac12$ 이다. $\\mathrm{Q}$ 는 직선 위의 점이므로 $x$ 좌표를 $t$ 로 두면 $(t,\\ 2t+1)$ 이고, 수선의 발 $\\mathrm{H}$ 는 $(t,\\ 0)$ 이다.","확인":"-1/2","스킬":"G10"},{"제목":"넓이 조건을 t의 방정식으로 쓰기","고비":true,"힌트":"$\\overline{\\mathrm{PH}}$, $\\overline{\\mathrm{QH}}$ 를 $t$ 로 나타내 삼각형의 넓이를 쓰면?","식":["$\\overline{\\mathrm{PH}}=\\left|t+\\frac12\\right|,\\ \\overline{\\mathrm{QH}}=|2t+1|$","$\\frac12\\left|t+\\frac12\\right||2t+1|=\\frac{(2t+1)^{2}}{4}=6$","$4t^{2}+4t-23=0$"],"설명":"삼각형 $\\mathrm{PQH}$ 는 $\\mathrm{H}$ 에서 직각이므로 넓이는 $\\frac12\\overline{\\mathrm{PH}}\\cdot\\overline{\\mathrm{QH}}$ 이다. $\\left|t+\\frac12\\right|=\\frac{|2t+1|}{2}$ 이므로 넓이는 $\\frac{(2t+1)^{2}}{4}$ 이다.","확인":null,"스킬":"G10"},{"제목":"근과 계수의 관계로 x좌표의 곱 구하기","힌트":"이차방정식 $4t^{2}+4t-23=0$ 의 두 근의 곱은?","식":["$D=16+368>0$ 이므로 서로 다른 두 실근","$t_{1}t_{2}=\\frac{-23}{4}$"],"설명":"서로 다른 두 실근이 두 점 $\\mathrm{Q}$ 의 $x$ 좌표이다. 이차방정식 $at^{2}+bt+c=0$ 에서 두 근의 곱은 $\\frac ca$ 이다.","확인":"-23/4","스킬":"A2"}]},"ns-93a314b49626":{"길":"분수식을 점 (5, 6)과 영역의 점을 잇는 직선의 기울기로 읽는다","단계":[{"제목":"분수식을 기울기로 읽기","고비":true,"힌트":"$\\frac{y-6}{x-5}=k$ 로 놓고 $y$ 에 대해 풀면 어떤 직선의 식인가?","식":["$\\frac{y-6}{x-5}=k\\ \\Rightarrow\\ y=k(x-5)+6$"],"설명":"$y=k(x-5)+6$ 은 점 $(5,\\ 6)$ 을 지나고 기울기가 $k$ 인 직선이다. 따라서 $\\frac{y-6}{x-5}$ 는 점 $(5,\\ 6)$ 과 영역 안의 점 $(x,\\ y)$ 를 이은 직선의 기울기이다.","확인":null,"스킬":"G9"},{"제목":"영역의 꼭짓점 읽기","힌트":"그림에서 색칠한 영역의 꼭짓점은 어디인가?","식":["$(1,\\ 2),\\ (1,\\ 5),\\ (4,\\ 5),\\ (4,\\ 1),\\ (3,\\ 1),\\ (3,\\ 2)$"],"설명":"색칠한 영역은 $1\\le x\\le4,\\ 1\\le y\\le5$ 인 직사각형에서 왼쪽 아래의 $1\\le x\\le3,\\ 1\\le y\\le2$ 인 부분이 빠진 모양이다.","확인":null,"스킬":"G6"},{"제목":"최댓값 M 구하기","힌트":"점 $(5,\\ 6)$ 과 각 꼭짓점을 이은 기울기 중 가장 큰 값은?","식":["$(4,\\ 1):\\ \\frac{1-6}{4-5}=5$","$(3,\\ 1):\\ \\frac52,\\ (3,\\ 2):\\ 2,\\ (4,\\ 5):\\ 1,\\ (1,\\ 2):\\ 1$","$M=5$"],"설명":"점 $(5,\\ 6)$ 은 영역의 오른쪽 위에 있어 기울기는 꼭짓점에서 최대, 최소가 된다. 꼭짓점별 기울기를 비교하면 $(4,\\ 1)$ 에서 $5$ 로 가장 크다.","확인":"5","스킬":"G9"},{"제목":"최솟값 m 구하기","힌트":"남은 꼭짓점 $(1,\\ 5)$ 와 점 $(5,\\ 6)$ 을 이은 기울기는?","식":["$(1,\\ 5):\\ \\frac{5-6}{1-5}=\\frac14$","$m=\\frac14$"],"설명":"앞에서 구한 다른 꼭짓점의 기울기는 모두 $1$ 이상이다. $(1,\\ 5)$ 에서 $\\frac14$ 로 가장 작으므로 $m=\\frac14$ 이다.","확인":"1/4","스킬":"G9"},{"제목":"(4/5)Mm의 값 구하기","힌트":"$M=5$, $m=\\frac14$ 을 대입하면?","식":["$\\frac45\\times5\\times\\frac14=1$"],"설명":"구한 $M$, $m$ 을 $\\frac45Mm$ 에 대입한다.","확인":"1","스킬":"G9"}]},"ns-94b1cd6eaa29":{"길":"한 변을 밑변으로 잡고 점과 직선 사이의 거리를 높이로 쓴다","단계":[{"제목":"직선 AB의 방정식 구하기","힌트":"$\\mathrm{A}(1,\\ 5)$, $\\mathrm{B}(2,\\ 2)$ 를 지나는 직선의 기울기는?","식":["$\\frac{5-2}{1-2}=-3$","$y=-3(x-1)+5$","$3x+y-8=0$"],"설명":"두 점의 좌표로 기울기를 구하고 $\\mathrm{A}$ 를 지나도록 식을 세운 뒤 $ax+by+c=0$ 꼴로 정리한다.","확인":"-3","스킬":"G10"},{"제목":"밑변 AB와 높이 구하기","고비":true,"힌트":"점 $\\mathrm{C}$ 에서 직선 $\\mathrm{AB}$ 까지의 거리가 높이이다. $\\overline{\\mathrm{AB}}$ 와 이 거리는?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(1-2)^{2}+(5-2)^{2}}=\\sqrt{10}$","$d=\\frac{|3\\cdot(-7)+(-1)-8|}{\\sqrt{3^{2}+1^{2}}}=\\frac{30}{\\sqrt{10}}=3\\sqrt{10}$"],"설명":"변 $\\mathrm{AB}$ 를 밑변으로 보면 높이는 점 $\\mathrm{C}$ 에서 직선 $\\mathrm{AB}$ 까지의 거리이다. 밑변의 길이는 두 점 사이의 거리 공식으로 구한다.","확인":null,"스킬":"G10"},{"제목":"삼각형의 넓이 구하기","힌트":"밑변과 높이의 곱의 절반은?","식":["$\\frac12\\cdot\\sqrt{10}\\cdot3\\sqrt{10}=15$"],"설명":"넓이는 밑변과 높이의 곱의 절반이다. $\\sqrt{10}\\times\\sqrt{10}=10$ 이므로 근호가 사라진다.","확인":"15","스킬":"G10"}]},"ns-954d44d2332f":{"길":"넓이의 절반이 되도록 직선이 CD와 만나는 점의 높이를 구해 기울기로 쓴다","단계":[{"제목":"도형 OABCDE의 넓이 구하기","힌트":"도형을 정사각형과 직사각형으로 나누면 전체 넓이는?","식":["$5\\times5+3\\times1=28$"],"설명":"$x\\le5$ 인 부분은 한 변의 길이가 $5$ 인 정사각형이고, 나머지는 가로 $3$, 세로 $1$ 인 직사각형이다.","확인":"28","스킬":"G10"},{"제목":"삼각형 OHF의 넓이 구하기","고비":true,"힌트":"$l$ 의 아래쪽 넓이가 $14$ 일 때 삼각형 $\\mathrm{OHF}$ 의 넓이는? ($\\mathrm{H}$ 는 $\\mathrm{C}$ 에서 $x$ 축에 내린 수선의 발, $\\mathrm{F}$ 는 $l$ 과 $\\overline{\\mathrm{CD}}$ 의 교점)","식":["$28\\div2=14$","$\\triangle\\mathrm{OHF}=14-3=11$"],"설명":"직선 $l$ 이 점 $\\mathrm{C}$ 를 지나면 아래쪽 넓이는 $\\frac{11}{2}$, 점 $\\mathrm{D}$ 를 지나면 $\\frac{31}{2}$ 이므로 이등분하는 직선은 선분 $\\mathrm{CD}$ 와 만난다. 그 점을 $\\mathrm{F}$ 라 하면 $l$ 아래쪽 넓이는 삼각형 $\\mathrm{OHF}$ 와 직사각형 $\\mathrm{HABC}$ 의 넓이 $3$ 의 합이다.","확인":"11","스킬":"G10"},{"제목":"FH의 길이 구하기","힌트":"$\\overline{\\mathrm{OH}}=5$ 이고 삼각형 $\\mathrm{OHF}$ 의 넓이가 $11$ 이면 $\\overline{\\mathrm{FH}}$ 는?","식":["$\\frac12\\times5\\times\\overline{\\mathrm{FH}}=11$","$\\overline{\\mathrm{FH}}=\\frac{22}{5}$"],"설명":"$\\mathrm{H}(5,\\ 0)$ 이므로 $\\overline{\\mathrm{OH}}=5$ 이고 삼각형 $\\mathrm{OHF}$ 는 $\\mathrm{H}$ 에서 직각이다.","확인":"22/5","스킬":"G10"},{"제목":"기울기와 p+q 구하기","힌트":"직선 $l$ 의 기울기는 $\\frac{\\overline{\\mathrm{FH}}}{\\overline{\\mathrm{OH}}}$ 이다. $\\frac qp$ 와 비교하면 $p+q$ 는?","식":["$\\frac{22}{5}\\div5=\\frac{22}{25}$","$p=25,\\ q=22$","$p+q=47$"],"설명":"$\\mathrm{F}\\left(5,\\ \\frac{22}{5}\\right)$ 이므로 원점을 지나는 직선의 기울기는 $\\frac{22}{25}$ 이다. $22$ 와 $25$ 는 서로소이다.","확인":"47","스킬":"G9"}]},"ns-9b285faa69e5":{"길":"거리의 비로 직선이 지나는 점을 먼저 잡고 거리 공식으로 기울기를 구한다","단계":[{"제목":"직선과 AB의 교점 구하기","고비":true,"힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 에서 $l$ 까지의 거리의 비가 $1:2$ 이면 $l$ 과 $\\overline{\\mathrm{AB}}$ 의 교점은 $\\overline{\\mathrm{AB}}$ 를 어떤 비로 나누는가?","식":["$l$ 과 $\\overline{\\mathrm{AB}}$ 의 교점 $\\mathrm{P}$ 에서 $\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PB}}=1:2$","$\\mathrm{P}\\left(\\frac{1\\cdot5+2\\cdot2}{3},\\ \\frac{1\\cdot(-4)+2\\cdot2}{3}\\right)=(3,\\ 0)$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$ 에서 $l$ 에 내린 수선의 발과 $\\mathrm{P}$ 가 만드는 두 직각삼각형은 닮음이므로 $\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PB}}$ 는 거리의 비 $1:2$ 와 같다. 따라서 $\\mathrm{P}$ 는 $\\overline{\\mathrm{AB}}$ 를 $1:2$ 로 내분하는 점이다.","확인":"3","스킬":"S1"},{"제목":"거리 조건으로 m의 식 세우기","힌트":"점 $(3,\\ 0)$ 을 지나는 $l$ 을 $mx-y-3m=0$ 으로 쓰면 점 $\\mathrm{A}$ 까지의 거리 조건은?","식":["$l:\\ y=m(x-3)\\ \\Rightarrow\\ mx-y-3m=0$","$\\frac{|2m-2-3m|}{\\sqrt{m^{2}+1}}=\\frac{|-m-2|}{\\sqrt{m^{2}+1}}=1$","$(m+2)^{2}=m^{2}+1$"],"설명":"직선 $l$ 이 $y$ 축에 평행하지 않으므로 기울기를 $m$ 으로 둘 수 있다. 점 $\\mathrm{A}(2,\\ 2)$ 에서 $l$ 까지의 거리가 $1$ 이므로 양변을 제곱해 근호를 없앤다.","확인":null,"스킬":"G9"},{"제목":"m의 값 구하기","힌트":"$(m+2)^{2}=m^{2}+1$ 을 풀면 $m$ 은?","식":["$m^{2}+4m+4=m^{2}+1$","$4m=-3$","$m=-\\frac34$"],"설명":"$m^{2}$ 이 양변에서 사라져 일차방정식이 된다.","확인":"-3/4","스킬":"G9"}]},"ns-9cf04c24da6b":{"길":"원료 조건을 부등식으로 쓰고 이익 직선이 마지막으로 닿는 점을 찾는다","단계":[{"제목":"생산량에 대한 부등식 세우기","고비":true,"힌트":"하루에 만드는 $A$, $B$ 의 개수를 $x$, $y$ 라 하면 원료 $p$, $q$ 의 조건은 각각 어떤 부등식인가?","식":["$3x+y\\le200$","$x+2y\\le150$","$x\\ge0,\\ y\\ge0$"],"설명":"원료 $p$ 는 $A$ 에 $3$, $B$ 에 $1$ 이 들어가 $3x+y$ 이고 최대공급량 $200$ 이하이다. 원료 $q$ 는 $A$ 에 $1$, $B$ 에 $2$ 가 들어가 $x+2y$ 이고 $150$ 이하이다.","확인":null,"스킬":"C7"},{"제목":"두 경계선의 교점 구하기","힌트":"$3x+y=200$ 과 $x+2y=150$ 을 연립하면 $x$ 는?","식":["$y=200-3x$ 를 $x+2y=150$ 에 대입","$-5x+400=150,\\ x=50$","$(x,\\ y)=(50,\\ 50)$"],"설명":"그림의 영역은 $(0,\\ 0)$, $\\left(\\frac{200}{3},\\ 0\\right)$, $(50,\\ 50)$, $(0,\\ 75)$ 를 꼭짓점으로 하는 사각형이다. 두 경계선의 교점이 $(50,\\ 50)$ 이다.","확인":"50","스킬":"G1"},{"제목":"이익을 직선으로 보고 최대인 점 찾기","힌트":"이익 $20000x+10000y=k$ 를 $y$ 에 대해 풀면 기울기는?","식":["$20000x+10000y=k\\ \\Rightarrow\\ y=-2x+\\frac{k}{10000}$","기울기 $-2$ 는 경계선의 기울기 $-3$ 과 $-\\frac12$ 사이"],"설명":"$k$ 가 클수록 직선은 위로 올라가고, 영역과 마지막으로 만나는 점에서 $k$ 가 최대이다. 기울기 $-2$ 가 두 경계선의 기울기 $-3$ 과 $-\\frac12$ 사이이므로 그 점은 두 경계선의 교점 $(50,\\ 50)$ 이다.","확인":null,"스킬":"G6"},{"제목":"최대 이익 구하기","힌트":"$x=50$, $y=50$ 일 때 이익은 몇 원인가?","식":["$20000\\times50+10000\\times50=1500000$"],"설명":"직선이 $(50,\\ 50)$ 을 지날 때 $k$ 가 최대이므로 하루의 최대이익은 $1500000$ 원이다.","확인":"1500000","스킬":"G6"}]},"ns-9fa30685cf3a":{"길":"잘려 나간 삼각형 ACD의 넓이가 전체의 절반이 되도록 k로 식을 세운다","단계":[{"제목":"직선 AB의 방정식과 점 C 구하기","힌트":"두 점 $\\mathrm{A}(4,\\ 0)$, $\\mathrm{B}(3,\\ 6)$ 을 지나는 직선 $\\mathrm{AB}$ 의 기울기는?","식":["$\\overline{\\mathrm{AB}}:\\ y=-6(x-4)=-6x+24$","$y=x+k$ 의 $x$ 절편은 $-k$ 이므로 $\\mathrm{C}(-k,\\ 0)$"],"설명":"기울기는 $\\frac{6-0}{3-4}=-6$ 이고 $\\mathrm{A}$ 를 지난다. 직선 $y=x+k$ 가 $x$ 축과 만나는 점 $\\mathrm{C}$ 는 $y=0$ 일 때의 $x$ 값이다.","확인":"-6","스킬":"G9"},{"제목":"교점 D의 좌표 구하기","힌트":"$y=x+k$ 와 $y=-6x+24$ 를 연립하면 점 $\\mathrm{D}$ 의 $x$ 좌표는?","식":["$x+k=-6x+24\\ \\Rightarrow\\ x=\\frac{24-k}{7}$","$y=\\frac{24-k}{7}+k=\\frac{6k+24}{7}$"],"설명":"점 $\\mathrm{D}$ 는 직선 $y=x+k$ 와 변 $\\mathrm{AB}$ 의 교점이다. 두 식을 연립해 $x$ 를 구하고 $y=x+k$ 에 대입한다.","확인":null,"스킬":"G1"},{"제목":"삼각형 ACD의 넓이로 식 세우기","고비":true,"힌트":"삼각형 $\\mathrm{OAB}$ 의 넓이가 $12$ 이므로 삼각형 $\\mathrm{ACD}$ 의 넓이는 $6$ 이다. $(k+4)^{2}$ 은?","식":["$\\triangle\\mathrm{OAB}=\\frac12\\times4\\times6=12$","$\\triangle\\mathrm{ACD}=\\frac12(4+k)\\times\\frac{6k+24}{7}=\\frac{3(k+4)^{2}}{7}=6$","$(k+4)^{2}=14$"],"설명":"직선 $y=x+k$ 가 삼각형 $\\mathrm{OAB}$ 의 넓이를 이등분하므로 오른쪽에 잘린 삼각형 $\\mathrm{ACD}$ 의 넓이가 $6$ 이다. 밑변 $\\overline{\\mathrm{AC}}=4+k$ 이고 높이는 $\\mathrm{D}$ 의 $y$ 좌표 $\\frac{6k+24}{7}$ 이다.","확인":"14","스킬":"G10"},{"제목":"k의 값 정하기","힌트":"$(k+4)^{2}=14$ 의 두 해 중 그림에 맞는 값은?","식":["$k+4=\\pm\\sqrt{14}$","$k=-4\\pm\\sqrt{14}$","$-4<k<0\\ \\Rightarrow\\ k=-4+\\sqrt{14}$"],"설명":"직선이 선분 $\\mathrm{OA}$ 위의 점 $\\mathrm{C}$ 를 지나려면 $x$ 절편 $-k$ 가 $0$ 과 $4$ 사이여야 하므로 $-4<k<0$ 이다. $-4-\\sqrt{14}$ 는 $-4$ 보다 작아 범위 밖이다.","확인":null,"스킬":"G10"}]},"ns-a6b9cc205178":{"길":"중심에서 각 변까지 거리가 같음을 써서 둘레를 같은 길이로 끊는다","단계":[{"제목":"한 영역이 닿는 둘레의 길이 구하기","고비":true,"힌트":"중심 $(-3,\\ -3)$ 에서 각 변까지의 거리는 $3$ 이다. 영역 하나의 넓이가 $6$ 이면 그 영역이 닿는 둘레의 길이 $s$ 는?","식":["$\\frac12\\times3\\times s=6$","$s=4$"],"설명":"세 직선이 모두 정사각형의 중심을 지나므로 각 영역은 중심과 둘레 위의 한 구간으로 이루어진다. 중심에서 모든 변까지의 거리가 $3$ 이어서 둘레 $s$ 인 구간이 만드는 넓이는 $\\frac12\\times3\\times s$ 이다. 넓이가 $6$ 이므로 둘레 $24$ 를 $4$ 씩 끊는다.","확인":"4","스킬":"S12"},{"제목":"둘레를 4씩 끊는 점 찾기","힌트":"$(\\alpha,\\ 0)$ 에서 둘레를 따라 $4$, $8$ 만큼 간 점은 변 $\\mathrm{OC}$ 위 어디인가?","식":["$(\\alpha,\\ 0)$ 에서 $\\mathrm{O}$ 까지 $-\\alpha$, 남은 $4+\\alpha$ 만큼 변 $\\mathrm{OC}$ 를 따라 내려간다","$\\mathrm{Q}_{1}(0,\\ -(4+\\alpha)),\\ \\mathrm{Q}_{2}(0,\\ -(8+\\alpha))$"],"설명":"나머지 세 점은 중심에 대해 대칭인 점이므로 세 직선은 중심과 $(\\alpha,\\ 0)$, $\\mathrm{Q}_{1}$, $\\mathrm{Q}_{2}$ 를 각각 지난다. $-3\\le\\alpha\\le-2$ 에서 $-(8+\\alpha)\\ge-6$ 이므로 $\\mathrm{Q}_{2}$ 도 변 $\\mathrm{OC}$ 위에 있다.","확인":null,"스킬":"S4"},{"제목":"직선 m, n의 기울기 구하기","힌트":"중심 $(-3,\\ -3)$ 과 $\\mathrm{Q}_{1}$, $\\mathrm{Q}_{2}$ 를 지나는 직선의 기울기는?","식":["$m:\\ \\frac{-(4+\\alpha)+3}{0+3}=-\\frac{\\alpha+1}{3}$","$n:\\ \\frac{-(8+\\alpha)+3}{0+3}=-\\frac{\\alpha+5}{3}$"],"설명":"두 직선 $m$, $n$ 은 중심 $(-3,\\ -3)$ 과 변 $\\mathrm{OC}$ 위의 점 $\\mathrm{Q}_{1}$, $\\mathrm{Q}_{2}$ 를 지난다. 두 점의 좌표로 기울기를 구한다.","확인":null,"스킬":"G9"},{"제목":"기울기의 곱을 α의 식으로 쓰기","힌트":"두 기울기의 곱을 $(\\alpha+3)^{2}$ 이 보이는 꼴로 고치면?","식":["$\\frac{(\\alpha+1)(\\alpha+5)}{9}$","$=\\frac{(\\alpha+3)^{2}-4}{9}$"],"설명":"음수 두 개의 곱이므로 $\\frac{(\\alpha+1)(\\alpha+5)}{9}$ 이다. $(\\alpha+1)(\\alpha+5)=\\alpha^{2}+6\\alpha+5=(\\alpha+3)^{2}-4$ 로 완전제곱 꼴을 만든다.","확인":null,"스킬":"A6"},{"제목":"곱의 최댓값 구하기","힌트":"$-3\\le\\alpha\\le-2$ 에서 $(\\alpha+3)^{2}$ 이 가장 클 때의 곱은?","식":["$0\\le(\\alpha+3)^{2}\\le1$","$\\alpha=-2$ 일 때 $\\frac{1-4}{9}=-\\frac13$"],"설명":"$\\alpha+3$ 의 범위가 $0$ 이상 $1$ 이하이므로 $(\\alpha+3)^{2}$ 은 $\\alpha=-2$ 에서 최대 $1$ 이다. 따라서 기울기의 곱의 최댓값은 $-\\frac13$ 이다.","확인":"-1/3","스킬":"A6"}]},"ns-ab4fff35da3d":{"길":"항상 지나는 점을 찾고 직사각형 꼭짓점을 지날 때를 경계로 잡는다","단계":[{"제목":"항상 지나는 점 찾기","힌트":"$m$ 에 대해 정리하면 $m$ 의 값에 관계없이 성립하는 점은?","식":["$m(x+2)-(y+1)=0$","$x+2=0,\\ y+1=0$","$(-2,\\ -1)$"],"설명":"식을 $m$ 에 대한 항등식으로 보면 $m$ 의 계수 $x+2$ 와 나머지 $-(y+1)$ 이 모두 $0$ 이어야 한다. 따라서 직선은 항상 점 $(-2,\\ -1)$ 을 지난다.","확인":null,"스킬":"G3"},{"제목":"경계가 되는 꼭짓점 찾기","고비":true,"힌트":"점 $(-2,\\ -1)$ 에서 직사각형의 꼭짓점 $(0,\\ 1)$, $(3,\\ 0)$ 을 지나는 직선의 기울기는?","식":["$(0,\\ 1):\\ \\frac{1-(-1)}{0-(-2)}=1$","$(3,\\ 0):\\ \\frac{0-(-1)}{3-(-2)}=\\frac15$"],"설명":"점 $(-2,\\ -1)$ 은 직사각형의 왼쪽 아래에 있다. 이 점을 지나는 직선이 직사각형과 만나려면 기울기가 가장 작은 꼭짓점 $(3,\\ 0)$ 과 가장 큰 꼭짓점 $(0,\\ 1)$ 을 지날 때 사이에 있어야 한다. 다른 두 꼭짓점 $(0,\\ 0)$, $(3,\\ 1)$ 의 기울기는 $\\frac12$, $\\frac25$ 로 그 사이에 든다.","확인":"1/5","스킬":"G3"},{"제목":"m의 범위 구하기","힌트":"두 경계 기울기 사이에서 $m$ 의 범위는?","식":["$\\frac15\\le m\\le1$"],"설명":"기울기가 $\\frac15$ 이상 $1$ 이하이면 직선이 직사각형과 만난다.","확인":null,"스킬":"G3"}]},"ns-b49f0785848c":{"길":"점 E의 높이를 a로 쓰고 사각형과 삼각형의 넓이를 a로 나타낸다","단계":[{"제목":"점 E의 좌표 구하기","힌트":"직선 $\\mathrm{AD}$ 의 식을 $a$ 로 쓰고 $x=0$ 을 대입하면 $\\mathrm{E}$ 의 $y$ 좌표는?","식":["$\\mathrm{AD}:\\ y=\\frac{2a}{a+1}(x+1)$","$\\mathrm{E}\\left(0,\\ \\frac{2a}{a+1}\\right)$"],"설명":"$\\mathrm{A}(-1,\\ 0)$, $\\mathrm{D}(a,\\ 2a)$ 를 지나는 직선의 기울기는 $\\frac{2a}{a+1}$ 이다. 점 $\\mathrm{E}$ 는 이 직선이 $y$ 축과 만나는 점이다.","확인":null,"스킬":"G10"},{"제목":"사각형 ABCD의 넓이 구하기","힌트":"대각선 $\\mathrm{AC}$ 로 나누면 삼각형 $\\mathrm{ABC}$ 와 $\\mathrm{ACD}$ 의 넓이의 합은?","식":["$\\triangle\\mathrm{ABC}=\\frac12\\cdot1\\cdot1=\\frac12$","$\\triangle\\mathrm{ACD}=\\frac12\\left|(-1)(-1-2a)+0\\cdot(2a-0)+a(0+1)\\right|=\\frac{3a+1}{2}$","$\\square\\mathrm{ABCD}=\\frac12+\\frac{3a+1}{2}=\\frac{3a+2}{2}$"],"설명":"삼각형 $\\mathrm{ABC}$ 는 직각을 낀 두 변이 모두 $1$ 인 직각이등변삼각형이다. 삼각형 $\\mathrm{ACD}$ 는 세 점의 좌표로 넓이를 구한다.","확인":null,"스킬":"G10"},{"제목":"삼각형 CDE의 넓이 구하기","힌트":"$y$ 축 위의 선분 $\\mathrm{CE}$ 를 밑변으로 보면 높이는 무엇인가?","식":["$\\overline{\\mathrm{CE}}=\\frac{2a}{a+1}+1=\\frac{3a+1}{a+1}$","$\\triangle\\mathrm{CDE}=\\frac12\\times\\frac{3a+1}{a+1}\\times a=\\frac{a(3a+1)}{2(a+1)}$"],"설명":"$\\mathrm{C}(0,\\ -1)$ 과 $\\mathrm{E}$ 가 모두 $y$ 축 위에 있으므로 $\\overline{\\mathrm{CE}}$ 를 밑변으로 하면 높이는 $\\mathrm{D}$ 의 $x$ 좌표 $a$ 이다.","확인":null,"스킬":"G10"},{"제목":"넓이 조건으로 방정식 세우기","고비":true,"힌트":"사각형 $\\mathrm{ABCD}$ 의 넓이가 삼각형 $\\mathrm{CDE}$ 의 $3$ 배라는 식을 $a$ 로 쓰고 정리하면?","식":["$\\frac{3a+2}{2}=3\\times\\frac{a(3a+1)}{2(a+1)}$","$(3a+2)(a+1)=3a(3a+1)$","$3a^{2}-a-1=0$"],"설명":"양변에 $2(a+1)$ 을 곱해 분모를 없앤 뒤 전개한다. $3a^{2}+5a+2=9a^{2}+3a$ 에서 $6a^{2}-2a-2=0$ 이고 양변을 $2$ 로 나누면 위의 식이 된다.","확인":null,"스킬":"G10"},{"제목":"a의 값 구하기","힌트":"$3a^{2}-a-1=0$ 을 근의 공식으로 풀고 양수인 값을 고르면?","식":["$a=\\frac{1\\pm\\sqrt{1+12}}{6}=\\frac{1\\pm\\sqrt{13}}{6}$","$a>0\\ \\Rightarrow\\ a=\\frac{1+\\sqrt{13}}{6}$"],"설명":"$\\frac{1-\\sqrt{13}}{6}$ 은 음수이므로 양수 $a$ 는 $\\frac{1+\\sqrt{13}}{6}$ 이다.","확인":null,"스킬":"G10"}]},"ns-bff0c93bd172":{"길":"수직 조건으로 두 직선을 세워 교점 P를 구하고 삼각형 넓이를 잰다","단계":[{"제목":"수직 조건으로 직선 AD 구하기","고비":true,"힌트":"$\\mathrm{AD}\\perp\\mathrm{OB}$ 이므로 $\\mathrm{OB}$ 의 기울기를 구해 $\\mathrm{AD}$ 의 기울기를 정하면?","식":["$\\mathrm{OB}$ 의 기울기 $\\frac{12-0}{-4-0}=-3$","$\\mathrm{AD}$ 의 기울기 $\\frac13$","$\\mathrm{AD}:\\ y=\\frac13(x-8)+6\\ \\Rightarrow\\ x-3y+10=0$"],"설명":"서로 수직인 두 직선의 기울기의 곱은 $-1$ 이다. $\\mathrm{AD}$ 는 $\\mathrm{A}(8,\\ 6)$ 을 지나고 $\\mathrm{OB}$ 에 수직이다.","확인":"1/3","스킬":"G9"},{"제목":"직선 OC와 교점 P 구하기","힌트":"$\\mathrm{OC}\\perp\\mathrm{AB}$ 이므로 $\\mathrm{OC}$ 의 식을 세워 $\\mathrm{AD}$ 와 연립하면 $\\mathrm{P}$ 의 $x$ 좌표는?","식":["$\\mathrm{AB}$ 의 기울기 $\\frac{12-6}{-4-8}=-\\frac12$","$\\mathrm{OC}:\\ y=2x$","$x-3(2x)+10=0\\ \\Rightarrow\\ \\mathrm{P}(2,\\ 4)$"],"설명":"$\\mathrm{OC}$ 는 원점을 지나고 $\\mathrm{AB}$ 에 수직이므로 기울기가 $2$ 이다. 점 $\\mathrm{P}$ 는 두 수선의 교점이다.","확인":"2","스킬":"G1"},{"제목":"무게중심 G 구하기","힌트":"무게중심 $\\mathrm{G}$ 의 $x$ 좌표는 세 꼭짓점의 $x$ 좌표의 평균이다. 얼마인가?","식":["$\\mathrm{G}\\left(\\frac{0+8+(-4)}{3},\\ \\frac{0+6+12}{3}\\right)$","$\\mathrm{G}\\left(\\frac43,\\ 6\\right)$"],"설명":"삼각형의 무게중심의 좌표는 세 꼭짓점의 좌표를 각각 평균한 값이다.","확인":"4/3","스킬":"S7"},{"제목":"삼각형 OPG의 넓이 구하기","힌트":"$\\overline{\\mathrm{OP}}$ 를 밑변으로 보면 높이는 점 $\\mathrm{G}$ 와 직선 $\\mathrm{OP}$ 사이의 거리이다. 넓이는?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{2^{2}+4^{2}}=2\\sqrt5$","$\\frac{\\left|2\\cdot\\frac43-6\\right|}{\\sqrt{2^{2}+(-1)^{2}}}=\\frac{2\\sqrt5}{3}$","$\\frac12\\times2\\sqrt5\\times\\frac{2\\sqrt5}{3}=\\frac{10}{3}$"],"설명":"직선 $\\mathrm{OP}$ 는 $2x-y=0$ 이다. 점 $\\mathrm{G}\\left(\\frac43,\\ 6\\right)$ 에서 이 직선까지의 거리가 높이이다.","확인":"10/3","스킬":"G10"}]},"ns-c34f044e237c":{"길":"AP=BP는 AB의 수직이등분선 위의 점이므로 포물선과 연립한다","단계":[{"제목":"교점 A, B 구하기","힌트":"$f(x)=g(x)$ 를 풀어 $x$ 좌표가 음수인 점 $\\mathrm{A}$ 의 $y$ 좌표는?","식":["$x^{2}+3x-3=-x+2\\ \\Rightarrow\\ x^{2}+4x-5=0$","$x=-5,\\ 1$","$\\mathrm{A}(-5,\\ 7),\\ \\mathrm{B}(1,\\ 1)$"],"설명":"두 그래프의 교점의 $x$ 좌표는 $f(x)=g(x)$ 의 해이다. 그림에서 $\\mathrm{A}$ 가 왼쪽이므로 $x=-5$ 를 $g(x)=-x+2$ 에 대입하면 $y=7$ 이다.","확인":"7","스킬":"G1"},{"제목":"선분 AB의 수직이등분선 구하기","고비":true,"힌트":"$\\mathrm{AB}$ 의 중점을 지나고 $\\mathrm{AB}$ 에 수직인 직선의 $y$ 절편은?","식":["중점 $\\left(\\frac{-5+1}{2},\\ \\frac{7+1}{2}\\right)=(-2,\\ 4)$","$\\mathrm{AB}$ 의 기울기 $-1$ 이므로 수직인 직선의 기울기는 $1$","$y=(x+2)+4=x+6$"],"설명":"$\\overline{\\mathrm{AP}}=\\overline{\\mathrm{BP}}$ 이면 점 $\\mathrm{P}$ 는 선분 $\\mathrm{AB}$ 의 수직이등분선 위에 있다. 수직이등분선은 중점을 지나고 $\\mathrm{AB}$ 에 수직이다.","확인":"6","스킬":"S4"},{"제목":"수직이등분선과 포물선의 교점 구하기","힌트":"$x^{2}+3x-3=x+6$ 을 풀고 $x<0$ 인 해를 고르면?","식":["$x^{2}+3x-3=x+6\\ \\Rightarrow\\ x^{2}+2x-9=0$","$x=-1\\pm\\sqrt{10}$","$x<0\\ \\Rightarrow\\ x=-1-\\sqrt{10}$"],"설명":"점 $\\mathrm{P}$ 는 $y=f(x)$ 위의 점이면서 수직이등분선 위의 점이므로 두 식을 연립한다. 근의 공식으로 $x=-1\\pm\\sqrt{10}$ 이고 $x$ 좌표가 음수이므로 $-1-\\sqrt{10}$ 이다.","확인":null,"스킬":"G1"}]},"ns-ce4a39710494":{"길":"OD를 구해 합동으로 점 C를 잡고 AD와 평행한 직선을 세운다","단계":[{"제목":"OD의 길이 구하기","힌트":"직각삼각형 $\\mathrm{AOD}$ 에서 $\\overline{\\mathrm{OA}}=3$, $\\overline{\\mathrm{AD}}=\\sqrt{10}$ 이면 $\\overline{\\mathrm{OD}}$ 는?","식":["$\\overline{\\mathrm{OD}}=\\sqrt{(\\sqrt{10})^{2}-3^{2}}=1$","$\\mathrm{D}(0,\\ 1)$"],"설명":"$\\mathrm{A}$ 는 $x$ 축 위, $\\mathrm{D}$ 는 $y$ 축 위에 있으므로 삼각형 $\\mathrm{AOD}$ 는 $\\mathrm{O}$ 에서 직각이다. 피타고라스 정리로 $\\overline{\\mathrm{OD}}$ 를 구한다.","확인":"1","스킬":"S3"},{"제목":"점 C의 좌표 구하기","고비":true,"힌트":"점 $\\mathrm{C}$ 에서 $y$ 축에 내린 수선의 발을 $\\mathrm{E}$ 라 하면 삼각형 $\\mathrm{AOD}$ 와 $\\mathrm{DEC}$ 가 합동이다. $\\mathrm{C}$ 의 $y$ 좌표는?","식":["$\\triangle\\mathrm{AOD}\\equiv\\triangle\\mathrm{DEC}$ (ASA)","$\\overline{\\mathrm{DE}}=\\overline{\\mathrm{OA}}=3,\\ \\overline{\\mathrm{EC}}=\\overline{\\mathrm{OD}}=1$","$\\mathrm{C}(1,\\ 1+3)=(1,\\ 4)$"],"설명":"정사각형이므로 $\\overline{\\mathrm{AD}}=\\overline{\\mathrm{DC}}$ 이고 $\\angle\\mathrm{ADC}=90^{\\circ}$ 이다. 그래서 두 직각삼각형이 합동이 되고 대응하는 변의 길이가 같다.","확인":"4","스킬":"S2"},{"제목":"직선 BC의 방정식 구하기","힌트":"$\\mathrm{BC}$ 는 $\\mathrm{AD}$ 와 평행하다. $\\mathrm{AD}$ 의 기울기와 점 $\\mathrm{C}$ 로 식을 세우면?","식":["$\\mathrm{AD}$ 의 기울기 $\\frac{1-0}{0-3}=-\\frac13$","$\\mathrm{BC}:\\ y-4=-\\frac13(x-1)$","$x+3y-13=0$"],"설명":"정사각형의 마주 보는 변은 평행하므로 $\\mathrm{BC}$ 의 기울기는 $\\mathrm{AD}$ 와 같다. 기울기가 $-\\frac13$ 이고 점 $\\mathrm{C}(1,\\ 4)$ 를 지난다.","확인":null,"스킬":"S4"}]},"ns-d379021607d2":{"길":"이웃한 변의 이동량으로 꼭짓점을 구하고 수직인 직선의 기울기를 쓴다","단계":[{"제목":"점 B, C의 좌표 구하기","고비":true,"힌트":"$\\mathrm{D}\\to\\mathrm{A}$ 의 이동량 $(+1,\\ -2)$ 에 수직이고 길이가 같은 $\\mathrm{A}\\to\\mathrm{B}$ 의 이동량을 구하면 $\\mathrm{B}$ 의 $x$ 좌표는?","식":["$\\mathrm{D}\\to\\mathrm{A}:\\ (+1,\\ -2)$","$\\mathrm{A}\\to\\mathrm{B}:\\ (+2,\\ +1)$","$\\mathrm{B}(3,\\ 1),\\ \\mathrm{C}(2,\\ 3)$"],"설명":"정사각형의 이웃한 두 변은 수직이고 길이가 같으므로 한 변의 이동량이 $(p,\\ q)$ 이면 이웃한 변은 $(-q,\\ p)$ 이다. $\\mathrm{D}\\to\\mathrm{A}$ 가 $(1,\\ -2)$ 이므로 $\\mathrm{A}\\to\\mathrm{B}$ 는 그림에서 오른쪽 위로 향하는 $(2,\\ 1)$ 이고, $\\mathrm{C}$ 는 $\\mathrm{D}$ 에서 같은 $(2,\\ 1)$ 만큼 이동한 점이다.","확인":"3","스킬":"S4"},{"제목":"점 F의 좌표 구하기","힌트":"$\\mathrm{B}\\to\\mathrm{E}$ 의 이동량 $(+1,\\ -1)$ 에 수직이고 길이가 같은 $\\mathrm{E}\\to\\mathrm{F}$ 의 이동량을 구하면 $\\mathrm{F}$ 의 $x$ 좌표는?","식":["$\\mathrm{B}\\to\\mathrm{E}:\\ (+1,\\ -1)$","$\\mathrm{E}\\to\\mathrm{F}:\\ (+1,\\ +1)$","$\\mathrm{F}(5,\\ 1)$"],"설명":"같은 방법으로 $\\mathrm{B}(3,\\ 1)$ 에서 $\\mathrm{E}(4,\\ 0)$ 으로 가는 이동량은 $(1,\\ -1)$ 이다. 정사각형 $\\mathrm{BEFG}$ 에서 $\\mathrm{E}\\to\\mathrm{F}$ 는 그림에서 오른쪽 위로 향하는 $(1,\\ 1)$ 이다.","확인":"5","스킬":"S4"},{"제목":"CF에 수직인 직선의 기울기 구하기","힌트":"$\\mathrm{C}(2,\\ 3)$, $\\mathrm{F}(5,\\ 1)$ 을 지나는 직선에 수직인 직선의 기울기는?","식":["$\\mathrm{CF}$ 의 기울기 $\\frac{1-3}{5-2}=-\\frac23$","수직인 직선의 기울기 $\\frac32$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이므로 $-\\frac23$ 에 곱해서 $-1$ 이 되는 값은 $\\frac32$ 이다.","확인":"3/2","스킬":"G9"},{"제목":"점 B를 지나는 직선의 방정식 구하기","힌트":"기울기가 $\\frac32$ 이고 $\\mathrm{B}(3,\\ 1)$ 을 지나는 직선을 $ax+by+c=0$ 꼴로 쓰면?","식":["$y-1=\\frac32(x-3)$","$y=\\frac32x-\\frac72$","$3x-2y-7=0$"],"설명":"한 점과 기울기를 알므로 점 기울기 꼴로 쓴 뒤 양변에 $2$ 를 곱해 정수 계수의 일반형으로 고친다.","확인":null,"스킬":"G9"}]},"ns-d8b8228eb2bb":{"길":"넓이의 비를 변의 길이의 비로 바꿔 P의 좌표를 먼저 구한다","단계":[{"제목":"넓이의 비를 길이의 비로 바꾸기","고비":true,"힌트":"삼각형 $\\mathrm{OAP}$, $\\mathrm{OBP}$ 는 밑변을 $\\overline{\\mathrm{AP}}$, $\\overline{\\mathrm{BP}}$ 로 보면 높이가 같다. 넓이의 비는 어떤 비와 같은가?","식":["높이가 같으므로 $\\triangle\\mathrm{OAP}:\\triangle\\mathrm{OBP}=\\overline{\\mathrm{AP}}:\\overline{\\mathrm{BP}}$","$\\overline{\\mathrm{AP}}:\\overline{\\mathrm{BP}}=4:1$"],"설명":"두 삼각형은 꼭짓점 $\\mathrm{O}$ 에서 직선 $\\mathrm{AB}$ 까지의 거리를 높이로 공유한다. 따라서 점 $\\mathrm{P}$ 는 $\\overline{\\mathrm{AB}}$ 를 $4:1$ 로 내분하는 점이다.","확인":null,"스킬":"S8"},{"제목":"점 P의 좌표 구하기","힌트":"$\\mathrm{P}$ 가 $\\overline{\\mathrm{AB}}$ 를 $4:1$ 로 내분하는 점이면 $y$ 좌표는?","식":["$\\mathrm{P}\\left(\\frac{4\\cdot0+1\\cdot4}{4+1},\\ \\frac{4\\cdot2+1\\cdot0}{4+1}\\right)$","$\\mathrm{P}\\left(\\frac45,\\ \\frac85\\right)$"],"설명":"$\\mathrm{A}(4,\\ 0)$ 에서 $\\mathrm{B}(0,\\ 2)$ 쪽으로 $\\frac45$ 만큼 간 점이므로 내분점 공식으로 좌표를 구한다.","확인":"8/5","스킬":"S4"},{"제목":"a의 값 구하기","힌트":"점 $\\mathrm{P}$ 가 직선 $y=ax+1$ 위에 있으므로 좌표를 대입하면?","식":["$\\frac85=\\frac45a+1$","$\\frac45a=\\frac35$","$a=\\frac34$"],"설명":"직선 위의 점의 좌표는 직선의 식을 만족한다. $x=\\frac45$, $y=\\frac85$ 를 대입해 $a$ 를 구하고, $a>0$ 을 만족하는지 확인한다.","확인":"3/4","스킬":"G9"}]},"ns-db63ce99240b":{"길":"세 점의 좌표를 t로 쓰고 C가 직선 AB 위에 있을 조건을 세운다","단계":[{"제목":"세 점의 좌표를 t로 나타내기","힌트":"$\\mathrm{C}$ 의 속력 $2\\sqrt2$ 를 $x$ 방향, $y$ 방향으로 나누면 각각 초속 얼마인가?","식":["$\\mathrm{A}(5t,\\ 0),\\ \\mathrm{B}(0,\\ 4t)$","기울기 $1$ 인 직선 위를 초속 $2\\sqrt2$ 로 가면 $x$, $y$ 방향으로 각각 초속 $\\frac{2\\sqrt2}{\\sqrt2}=2$","$\\mathrm{C}(2t,\\ 1+2t)$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$ 는 원점에서 축을 따라 속력과 시간의 곱만큼 움직인다. $y=x+1$ 은 기울기가 $1$ 이므로 $\\mathrm{C}$ 는 $x$, $y$ 방향으로 같은 양씩 움직이고, 그 속력을 $v$ 라 하면 $\\sqrt{v^{2}+v^{2}}=2\\sqrt2$ 에서 $v=2$ 이다.","확인":"2","스킬":"C7"},{"제목":"직선 AB에 점 C를 대입해 식 세우기","고비":true,"힌트":"직선 $\\mathrm{AB}$ 를 절편꼴로 쓰고 $\\mathrm{C}$ 의 좌표를 대입하면?","식":["$\\mathrm{AB}:\\ \\frac{x}{5t}+\\frac{y}{4t}=1$","$\\frac{2t}{5t}+\\frac{1+2t}{4t}=1$","$\\frac{1+2t}{4t}=\\frac35$"],"설명":"세 점이 한 직선 위에 있으려면 $\\mathrm{C}$ 가 직선 $\\mathrm{AB}$ 위에 있어야 한다. 직선 $\\mathrm{AB}$ 의 $x$ 절편은 $5t$, $y$ 절편은 $4t$ 이다. $\\frac{2t}{5t}=\\frac25$ 이므로 나머지 항은 $1-\\frac25=\\frac35$ 이다.","확인":null,"스킬":"G9"},{"제목":"t의 값 구하기","힌트":"$\\frac{1+2t}{4t}=\\frac35$ 를 풀면 $t$ 는?","식":["$5(1+2t)=12t$","$5+10t=12t$","$t=\\frac52$"],"설명":"양변에 $20t$ 를 곱해 분모를 없애고 $t$ 에 대해 푼다. $t=\\frac52=2.5$ 이다.","확인":"2.5","스킬":"G9"}]},"ns-df8982c75920":{"길":"세 교점을 구하고 원점 기준 두 삼각형의 넓이 차로 잰다","단계":[{"제목":"두 교점 A, B 구하기","힌트":"$y=-\\frac13x$ 와 $y=2x+7$ 을 연립하면 점 $\\mathrm{B}$ 의 $x$ 좌표는?","식":["$y=-x,\\ y=2x+7\\ \\Rightarrow\\ \\mathrm{A}\\left(-\\frac73,\\ \\frac73\\right)$","$y=-\\frac13x,\\ y=2x+7\\ \\Rightarrow\\ \\mathrm{B}(-3,\\ 1)$"],"설명":"$y=-x$ 와 $y=-\\frac13x$ 는 원점에서 만나므로 삼각형의 한 꼭짓점이 $\\mathrm{O}$ 이다. 나머지 두 꼭짓점 $\\mathrm{A}$, $\\mathrm{B}$ 는 $2x-y=-7$, 즉 $y=2x+7$ 과의 교점이다.","확인":"-3","스킬":"G1"},{"제목":"x축과의 교점 C 구하기","고비":true,"힌트":"직선 $y=2x+7$ 이 $x$ 축과 만나는 점 $\\mathrm{C}$ 의 $x$ 좌표는?","식":["$0=2x+7$","$\\mathrm{C}\\left(-\\frac72,\\ 0\\right)$"],"설명":"$\\mathrm{C}$ 를 잡으면 삼각형 $\\mathrm{OAB}$ 는 삼각형 $\\mathrm{OAC}$ 에서 삼각형 $\\mathrm{OBC}$ 를 뺀 도형이다. 두 삼각형은 밑변 $\\mathrm{OC}$ 가 $x$ 축 위에 있어 넓이를 구하기 쉽다.","확인":"-7/2","스킬":"G10"},{"제목":"삼각형의 넓이 구하기","힌트":"삼각형 $\\mathrm{OAC}$ 에서 삼각형 $\\mathrm{OBC}$ 를 빼면?","식":["$\\triangle\\mathrm{OAC}=\\frac12\\times\\frac72\\times\\frac73=\\frac{49}{12}$","$\\triangle\\mathrm{OBC}=\\frac12\\times\\frac72\\times1=\\frac74$","$\\frac{49}{12}-\\frac{21}{12}=\\frac73$"],"설명":"밑변 $\\overline{\\mathrm{OC}}=\\frac72$ 이고 높이는 $\\mathrm{A}$, $\\mathrm{B}$ 의 $y$ 좌표 $\\frac73$, $1$ 이다. 두 넓이의 차가 구하는 넓이이다.","확인":"7/3","스킬":"G10"}]},"ns-dfa6f6ef428c":{"길":"B를 원점에 두고 PQ·PR·PH 를 점 P 의 좌표로 나타낸다","단계":[{"제목":"직사각형을 좌표평면에 놓기","힌트":"점 $\\mathrm{B}$ 를 원점으로 하면 선분 $\\mathrm{AD}$ 를 $1:2$ 로 내분하는 점 $\\mathrm{S}$ 의 좌표는?","식":["$\\mathrm{B}(0,\\ 0),\\ \\mathrm{C}(12,\\ 0),\\ \\mathrm{A}(0,\\ 8),\\ \\mathrm{D}(12,\\ 8)$","$\\mathrm{S}\\left(\\frac{1\\times12+2\\times0}{1+2},\\ 8\\right)=\\mathrm{S}(4,\\ 8)$"],"설명":"$\\overline{\\mathrm{BC}}=12$ 는 $x$ 축 위에, $\\overline{\\mathrm{AB}}=8$ 은 $y$ 축 위에 놓는다. $\\overline{\\mathrm{AS}}:\\overline{\\mathrm{SD}}=1:2$ 이므로 $\\overline{\\mathrm{AS}}=4$ 이다.","확인":"4","스킬":"S4"},{"제목":"두 직선 AC, SC 의 방정식","힌트":"$\\mathrm{A}$, $\\mathrm{C}$ 를 지나는 직선과 $\\mathrm{S}$, $\\mathrm{C}$ 를 지나는 직선의 기울기는 각각 얼마인가?","식":["$\\mathrm{AC}:\\ y=8-\\frac{2}{3}x$","$\\mathrm{SC}:\\ x+y-12=0$"],"설명":"$\\mathrm{AC}$ 의 기울기는 $\\frac{0-8}{12-0}=-\\frac{2}{3}$ 이고 $y$ 절편이 $8$ 이다. $\\mathrm{SC}$ 의 기울기는 $\\frac{0-8}{12-4}=-1$ 이므로 $y=-(x-12)$, 곧 $x+y-12=0$ 이다.","확인":null,"스킬":"G9"},{"제목":"PQ, PR, PH 를 한 문자로 나타내기","고비":true,"힌트":"점 $\\mathrm{P}$ 의 $x$ 좌표를 $x$ 라 하면 세 수선의 길이는 각각 어떻게 되는가?","식":["$\\mathrm{P}\\left(x,\\ 8-\\frac{2}{3}x\\right)$","$\\overline{\\mathrm{PQ}}=x,\\ \\overline{\\mathrm{PR}}=8-\\frac{2}{3}x$","$\\overline{\\mathrm{PH}}=\\frac{\\left|x+\\left(8-\\frac{2}{3}x\\right)-12\\right|}{\\sqrt{2}}=\\frac{4-\\frac{x}{3}}{\\sqrt{2}}$"],"설명":"$\\overline{\\mathrm{PQ}}$ 는 점 $\\mathrm{P}$ 에서 직선 $\\mathrm{AB}$($y$ 축)까지, $\\overline{\\mathrm{PR}}$ 는 직선 $\\mathrm{BC}$($x$ 축)까지의 거리라 각각 $x$ 좌표, $y$ 좌표이다. $\\overline{\\mathrm{PH}}$ 는 점 $\\mathrm{P}$ 와 직선 $x+y-12=0$ 사이의 거리이다. $0<x<12$ 에서 $x+y-12=\\frac{x}{3}-4<0$ 이므로 절댓값을 벗기면 $4-\\frac{x}{3}$ 이다.","확인":null,"스킬":"S4"},{"제목":"조건식으로 x 구하기","힌트":"$\\overline{\\mathrm{PQ}}=\\frac{3\\sqrt{2}}{4}\\overline{\\mathrm{PH}}$ 에 세 길이를 대입하면 $x$ 는?","식":["$x=\\frac{3\\sqrt{2}}{4}\\times\\frac{4-\\frac{x}{3}}{\\sqrt{2}}=3-\\frac{x}{4}$","$\\frac{5}{4}x=3\\ \\Rightarrow\\ x=\\frac{12}{5}$"],"설명":"$\\sqrt{2}$ 가 약분되어 $x=3-\\frac{x}{4}$ 가 된다. 정리하면 $x=\\frac{12}{5}$ 이다.","확인":"12/5","스킬":"C7"},{"제목":"PR 의 길이와 p+q","힌트":"$x=\\frac{12}{5}$ 일 때 $\\overline{\\mathrm{PR}}$ 는 $\\frac{q}{p}$ 꼴로 얼마인가?","식":["$\\overline{\\mathrm{PR}}=8-\\frac{2}{3}\\times\\frac{12}{5}=\\frac{32}{5}$","$p=5,\\ q=32\\ \\Rightarrow\\ p+q=37$"],"설명":"$\\overline{\\mathrm{PR}}=\\frac{q}{p}$ 이고 $32$ 와 $5$ 는 서로소이므로 $q=32,\\ p=5$ 이다.","확인":"37","스킬":"S4"}]},"ns-f8b8ee9be5b2":{"길":"넓이 조건과 한 점을 지나는 조건으로 P, Q 의 높이 두 개를 구한다","단계":[{"제목":"사다리꼴 PBCQ 의 변의 길이 합","힌트":"사각형 $\\mathrm{PBCQ}$ 의 넓이는 정사각형 넓이의 몇 분의 몇인가?","식":["$\\square\\mathrm{APQD}=2\\,\\square\\mathrm{PBCQ}\\ \\Rightarrow\\ \\square\\mathrm{PBCQ}=\\frac{16}{3}$","$\\frac{1}{2}(p+q)\\times4=\\frac{16}{3}\\ \\Rightarrow\\ p+q=\\frac{8}{3}$"],"설명":"$\\mathrm{B}$ 를 원점, 직선 $\\mathrm{BC}$ 를 $x$ 축, 직선 $\\mathrm{BA}$ 를 $y$ 축으로 두고 $\\mathrm{P}(0,\\ p)$, $\\mathrm{Q}(4,\\ q)$ 라 한다. 두 사각형의 넓이 합이 $16$ 이고 한쪽이 다른 쪽의 $2$ 배이므로 $\\square\\mathrm{PBCQ}$ 는 $\\frac{16}{3}$ 이다. 사각형 $\\mathrm{PBCQ}$ 는 평행한 두 변이 $\\overline{\\mathrm{PB}}=p$, $\\overline{\\mathrm{CQ}}=q$ 이고 높이가 $4$ 인 사다리꼴이다.","확인":"8/3","스킬":"G10"},{"제목":"점 (1, 1) 을 지나는 조건","고비":true,"힌트":"직선 $\\mathrm{PQ}$ 의 방정식에 $x=1$ 을 대입해 $y=1$ 이 되려면 $p$, $q$ 사이에 어떤 관계가 있어야 하는가?","식":["$y=p+\\frac{q-p}{4}x$","$p+\\frac{q-p}{4}=1\\ \\Rightarrow\\ 3p+q=4$"],"설명":"직선 $\\mathrm{PQ}$ 는 $\\mathrm{P}(0,\\ p)$ 와 $\\mathrm{Q}(4,\\ q)$ 를 지나 기울기가 $\\frac{q-p}{4}$ 이다. 이 직선이 $\\mathrm{B}$ 에서 오른쪽으로 $1$, 위쪽으로 $1$ 인 점 $(1,\\ 1)$ 을 지나므로 식에 대입한다. 양변에 $4$ 를 곱하면 $3p+q=4$ 이다.","확인":null,"스킬":"G3"},{"제목":"연립하여 PB 의 길이 구하기","힌트":"두 식 $p+q=\\frac{8}{3}$, $3p+q=4$ 에서 $q$ 를 없애면 $p$ 는?","식":["$(3p+q)-(p+q)=4-\\frac{8}{3}$","$2p=\\frac{4}{3}\\ \\Rightarrow\\ p=\\frac{2}{3}$"],"설명":"두 식을 변끼리 빼면 $q$ 가 사라진다.","확인":"2/3","스킬":"A10"},{"제목":"DQ 의 길이 구하기","힌트":"$q$ 를 구하면 $\\overline{\\mathrm{DQ}}$ 는?","식":["$q=\\frac{8}{3}-\\frac{2}{3}=2$","$\\overline{\\mathrm{DQ}}=4-q=2$"],"설명":"$\\overline{\\mathrm{CQ}}=q$ 이고 $\\overline{\\mathrm{CD}}=4$ 이므로 $\\overline{\\mathrm{DQ}}=4-q$ 이다.","확인":"2","스킬":"G10"}]},"ns-fcde5f64f570":{"길":"대각선의 교점을 지나는 직선으로 삼각형 넓이를 이등분하는 기울기를 구한다","단계":[{"제목":"직사각형 이등분선이 지나는 점","힌트":"직사각형의 넓이를 이등분하는 직선이 항상 지나는 점은 어디인가?","식":["$\\left(\\frac{-2+2}{2},\\ \\frac{1+3}{2}\\right)=(0,\\ 2)$","$l:\\ y=mx+2$"],"설명":"직사각형을 이등분하는 직선은 두 대각선의 교점을 지난다. 대각선 $\\mathrm{AC}$ 의 중점이 그 교점이므로 직선 $l$ 은 $(0,\\ 2)$ 를 지난다. $l$ 의 기울기를 $m$ 이라 하면 $y=mx+2$ 이다.","확인":"2","스킬":"G10"},{"제목":"삼각형 GEF 의 넓이와 잘라낼 넓이","힌트":"삼각형 $\\mathrm{GEF}$ 의 밑변 $\\overline{\\mathrm{EF}}$ 와 높이는 각각 얼마인가?","식":["$\\frac{1}{2}\\times4\\times2=4$","$4\\div2=2$"],"설명":"$\\overline{\\mathrm{EF}}=4$ 이고 $\\mathrm{G}$ 의 높이가 $y=-2$ 에서 $y=0$ 까지 $2$ 이므로 넓이는 $4$ 이다. 직선 $l$ 이 이등분하려면 $\\mathrm{E}$ 쪽에서 잘리는 삼각형의 넓이가 $2$ 여야 한다.","확인":"4","스킬":"G10"},{"제목":"직선 l 과 두 변의 교점","힌트":"직선 $y=mx+2$ 와 직선 $\\mathrm{EG}$, $\\mathrm{EF}$ 의 교점은 각각 어디인가?","식":["$\\mathrm{EG}:\\ y=x-2\\ \\Rightarrow\\ \\left(\\frac{4}{1-m},\\ \\frac{2+2m}{1-m}\\right)$","$\\mathrm{EF}:\\ y=-2\\ \\Rightarrow\\ \\left(-\\frac{4}{m},\\ -2\\right)$"],"설명":"점 $(0,\\ 2)$ 와 $\\mathrm{G}(2,\\ 0)$ 을 지나는 직선의 기울기가 $-1$ 이므로, 직선이 $\\overline{\\mathrm{EG}}$ 와 $\\overline{\\mathrm{EF}}$ 를 모두 지나려면 $m<-1$ 이어야 한다. 이때 두 교점과 $\\mathrm{E}$ 가 작은 삼각형을 이룬다.","확인":null,"스킬":"G1"},{"제목":"넓이 조건으로 m 의 식 세우기","고비":true,"힌트":"작은 삼각형의 밑변과 높이를 $m$ 으로 나타내면?","식":["밑변 $-\\frac{4}{m}$, 높이 $\\frac{2+2m}{1-m}+2=\\frac{4}{1-m}$","$\\frac{1}{2}\\times\\left(-\\frac{4}{m}\\right)\\times\\frac{4}{1-m}=2\\ \\Rightarrow\\ m^{2}-m-4=0$"],"설명":"$m<0$ 이므로 밑변 $-\\frac{4}{m}$ 는 양수이고, 높이는 $\\mathrm{E}$ 의 $y$ 좌표 $-2$ 와 교점의 $y$ 좌표의 차이다. 넓이가 $2$ 가 되는 식을 정리하면 $m^{2}-m-4=0$ 이다.","확인":null,"스킬":"G10"},{"제목":"기울기 선택과 a+b","힌트":"$m^{2}-m-4=0$ 의 두 근 중 $m<-1$ 인 것은?","식":["$m=\\frac{1\\pm\\sqrt{17}}{2}$","$m<-1\\ \\Rightarrow\\ m=\\frac{1-\\sqrt{17}}{2}$","$a=1,\\ b=-1\\ \\Rightarrow\\ a+b=0$"],"설명":"$\\frac{1+\\sqrt{17}}{2}$ 는 양수라 버리고 $\\frac{1-\\sqrt{17}}{2}\\approx-1.56$ 만 조건에 맞는다. $\\frac{a+b\\sqrt{17}}{2}$ 와 비교하면 $a=1,\\ b=-1$ 이다.","확인":"0","스킬":"A3"}]},"ns-01fe5b952b18":{"길":"직각삼각형 PAC 의 높이로 삼각형 ABC 의 밑변과 높이를 구한다","단계":[{"제목":"원의 중심과 반지름 구하기","힌트":"원의 방정식을 $(x-a)^{2}+(y-b)^{2}=r^{2}$ 꼴로 고치면 $r^{2}$ 은?","식":["$(x-1)^{2}+(y-3)^{2}=20$","$\\mathrm{C}(1,\\ 3),\\ \\overline{\\mathrm{CA}}=2\\sqrt{5}$"],"설명":"$x^{2}-2x$ 에 $1$, $y^{2}-6y$ 에 $9$ 를 더해 완전제곱식으로 만들면 우변이 $10+1+9=20$ 이 된다.","확인":"20","스킬":"A6"},{"제목":"접선의 길이 PA 구하기","힌트":"직각삼각형 $\\mathrm{PAC}$ 에서 $\\overline{\\mathrm{PC}}^{2}$ 은 얼마인가?","식":["$\\overline{\\mathrm{PC}}^{2}=(9-1)^{2}+(7-3)^{2}=80$","$\\overline{\\mathrm{PA}}=\\sqrt{80-20}=2\\sqrt{15}$"],"설명":"접선은 접점에서 반지름과 수직이므로 $\\angle\\mathrm{PAC}=90^{\\circ}$ 이다. 피타고라스 정리로 $\\overline{\\mathrm{PA}}^{2}=\\overline{\\mathrm{PC}}^{2}-\\overline{\\mathrm{CA}}^{2}$ 이다.","확인":"80","스킬":"S5"},{"제목":"PC 에 내린 수선의 길이","고비":true,"힌트":"$\\overline{\\mathrm{AB}}$ 와 $\\overline{\\mathrm{PC}}$ 의 교점을 $\\mathrm{M}$ 이라 할 때, 직각삼각형 $\\mathrm{PAC}$ 의 넓이를 두 가지로 나타내면?","식":["$\\frac{1}{2}\\times\\overline{\\mathrm{PA}}\\times\\overline{\\mathrm{CA}}=\\frac{1}{2}\\times\\overline{\\mathrm{PC}}\\times\\overline{\\mathrm{AM}}$","$\\overline{\\mathrm{AM}}=\\frac{2\\sqrt{15}\\times2\\sqrt{5}}{4\\sqrt{5}}=\\sqrt{15}$","$\\overline{\\mathrm{CM}}=\\sqrt{20-15}=\\sqrt{5}$"],"설명":"$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}}$, $\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CB}}$ 이므로 직선 $\\mathrm{PC}$ 는 선분 $\\mathrm{AB}$ 의 수직이등분선이다. 그래서 $\\mathrm{M}$ 은 $\\mathrm{AB}$ 의 중점이고 $\\overline{\\mathrm{AB}}=2\\overline{\\mathrm{AM}}$ 이다. 높이 $\\overline{\\mathrm{AM}}$ 은 직각삼각형의 넓이를 두 가지로 나타내 구하고, $\\overline{\\mathrm{CM}}$ 은 $\\triangle\\mathrm{ACM}$ 에서 피타고라스 정리로 구한다.","확인":null,"스킬":"S8"},{"제목":"삼각형 ABC 의 넓이와 S²","힌트":"밑변 $\\overline{\\mathrm{AB}}$, 높이 $\\overline{\\mathrm{CM}}$ 로 넓이를 구하면?","식":["$S=\\frac{1}{2}\\times2\\sqrt{15}\\times\\sqrt{5}=\\sqrt{75}$","$S^{2}=75$"],"설명":"$\\overline{\\mathrm{AB}}=2\\sqrt{15}$ 가 밑변이고 $\\overline{\\mathrm{CM}}=\\sqrt{5}$ 가 높이이다. $S=\\sqrt{75}$ 를 제곱하면 근호가 없어진다.","확인":"75","스킬":"S8"}]},"ns-026a3492fa24":{"길":"두 직선이 수직이면 ∠APB 가 직각이라 AB 는 원의 지름이다","단계":[{"제목":"두 직선의 위치 관계","힌트":"두 직선 $l$, $m$ 의 기울기의 곱은?","식":["$l$ 의 기울기 $-4$, $m$ 의 기울기 $\\frac{1}{4}$","$-4\\times\\frac{1}{4}=-1\\ \\Rightarrow\\ l\\perp m$"],"설명":"$m:\\ -x+4y-48=0$ 에서 $y=\\frac{1}{4}x+12$ 이다. 기울기의 곱이 $-1$ 이면 두 직선은 수직이다.","확인":"-1","스킬":"G9"},{"제목":"선분 AB 가 지름인 까닭","고비":true,"힌트":"원 $C$ 위의 세 점 $\\mathrm{A}$, $\\mathrm{P}$, $\\mathrm{B}$ 에서 $\\angle\\mathrm{APB}$ 가 직각이면 $\\overline{\\mathrm{AB}}$ 는 원의 무엇인가?","식":["$l\\perp m\\ \\Rightarrow\\ \\angle\\mathrm{APB}=90^{\\circ}$","$\\overline{\\mathrm{AB}}=2r$"],"설명":"$\\mathrm{A}$ 는 $l$ 위에, $\\mathrm{B}$ 는 $m$ 위에 있으므로 $\\angle\\mathrm{APB}$ 는 두 직선이 이루는 각 $90^{\\circ}$ 이다. 원주각이 $90^{\\circ}$ 이면 현 $\\mathrm{AB}$ 는 지름이다. 원 $C$ 의 반지름을 $r$ 이라 하면 $\\overline{\\mathrm{AB}}=2r$ 이다.","확인":null,"스킬":"S5"},{"제목":"교점 P 와 반지름 구하기","힌트":"두 직선을 연립해 $\\mathrm{P}$ 를 구한 뒤 $\\overline{\\mathrm{QP}}$ 를 계산하면?","식":["$4x+y+5=0,\\ -x+4y-48=0\\ \\Rightarrow\\ \\mathrm{P}(-4,\\ 11)$","$r=\\overline{\\mathrm{QP}}=\\sqrt{(-4-4)^{2}+(11-5)^{2}}=10$"],"설명":"원 $C$ 는 중심이 $\\mathrm{Q}$ 이고 $\\mathrm{P}$ 를 지나므로 반지름은 $\\overline{\\mathrm{QP}}$ 이다.","확인":"10","스킬":"G1"},{"제목":"선분 AB 의 길이","힌트":"지름은 반지름의 몇 배인가?","식":["$\\overline{\\mathrm{AB}}=2r=20$"],"설명":"$\\overline{\\mathrm{AB}}$ 는 지름이므로 반지름의 $2$ 배이다.","확인":"20","스킬":"S5"}]},"ns-03ee439eb779":{"길":"각이 직각이 되는 경계 원을 먼저 찾고 둔각 영역을 고리 모양으로 본다","단계":[{"제목":"직각일 때의 사각형 OAPB","힌트":"$\\angle\\mathrm{APB}=90^{\\circ}$ 이면 사각형 $\\mathrm{OAPB}$ 의 네 각은 각각 얼마인가?","식":["$\\angle\\mathrm{OAP}=\\angle\\mathrm{OBP}=\\angle\\mathrm{APB}=90^{\\circ}$","$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}=4$"],"설명":"접선은 접점을 지나는 반지름에 수직이므로 $\\angle\\mathrm{OAP}=\\angle\\mathrm{OBP}=90^{\\circ}$ 이다. 세 각이 직각이면 나머지 각도 직각이므로 직사각형이고, 이웃한 두 변 $\\overline{\\mathrm{OA}}$, $\\overline{\\mathrm{OB}}$ 가 같아 한 변이 $4$ 인 정사각형이다.","확인":null,"스킬":"S5"},{"제목":"경계가 되는 원의 반지름","힌트":"정사각형의 대각선 $\\overline{\\mathrm{OP}}$ 에 대해 $\\overline{\\mathrm{OP}}^{2}$ 은?","식":["$\\overline{\\mathrm{OP}}^{2}=4^{2}+4^{2}=32$","$\\overline{\\mathrm{OP}}=4\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{OP}}$ 는 한 변이 $4$ 인 정사각형의 대각선이다. $\\angle\\mathrm{APB}=90^{\\circ}$ 인 점 $\\mathrm{P}$ 는 원점에서 $4\\sqrt{2}$ 만큼 떨어진 점들이므로 반지름 $4\\sqrt{2}$ 인 원 위에 있다.","확인":"32","스킬":"S3"},{"제목":"둔각이 되는 거리 범위","고비":true,"힌트":"$\\overline{\\mathrm{OP}}$ 가 $4\\sqrt{2}$ 보다 작아지면 $\\angle\\mathrm{APB}$ 는 직각보다 커지는가 작아지는가?","식":["$\\sin\\frac{\\angle\\mathrm{APB}}{2}=\\frac{4}{\\overline{\\mathrm{OP}}}$","$\\angle\\mathrm{APB}>90^{\\circ}\\ \\Leftrightarrow\\ 4<\\overline{\\mathrm{OP}}<4\\sqrt{2}$"],"설명":"직각삼각형 $\\mathrm{OAP}$ 에서 $\\sin\\angle\\mathrm{APO}=\\frac{4}{\\overline{\\mathrm{OP}}}$ 이고 $\\angle\\mathrm{APO}=\\frac{\\angle\\mathrm{APB}}{2}$ 이다. $\\overline{\\mathrm{OP}}$ 가 작을수록 $\\angle\\mathrm{APO}$ 가 커져 $\\angle\\mathrm{APB}$ 도 커진다. 점 $\\mathrm{P}$ 는 원 밖에 있으므로 $\\overline{\\mathrm{OP}}>4$ 이다.","확인":null,"스킬":"S5"},{"제목":"영역의 넓이 구하기","힌트":"반지름 $4\\sqrt{2}$ 인 원에서 반지름 $4$ 인 원을 뺀 넓이는?","식":["$\\pi\\times(4\\sqrt{2})^{2}-\\pi\\times4^{2}=32\\pi-16\\pi$","$=16\\pi$"],"설명":"둔각이 되는 점들은 두 원 사이의 고리 모양 영역에 있다. 큰 원의 넓이에서 작은 원의 넓이를 뺀다.","확인":null,"스킬":"S12"}]},"ns-047f1a6dc5f0":{"길":"중심을 $(-r,\\ r)$ 로 두고 직선까지의 거리가 $r$ 임을 쓴다","단계":[{"제목":"원의 중심과 반지름 문자로 놓기","힌트":"$x$ 축, $y$ 축에 모두 접하고 제$2$사분면에 있는 원의 중심 좌표는?","식":["$(-r,\\ r)\\ (r>0)$"],"설명":"두 축에 모두 접하면 중심에서 두 축까지의 거리가 모두 반지름 $r$ 이다. 중심이 제$2$사분면에 있으므로 $x$ 좌표는 음수, $y$ 좌표는 양수라 $(-r,\\ r)$ 이다.","확인":null,"스킬":"S13"},{"제목":"접선 조건을 거리로 나타내기","고비":true,"힌트":"원이 직선에 접하면 중심에서 직선까지의 거리는 무엇과 같은가?","식":["$\\frac{|4(-r)-3r+3|}{\\sqrt{4^{2}+(-3)^{2}}}=r$","$|3-7r|=5r$"],"설명":"접선이면 중심에서 직선까지의 거리가 반지름과 같다. 점과 직선 사이의 거리 공식에서 분모는 $\\sqrt{16+9}=5$ 이므로 양변에 $5$ 를 곱한다.","확인":null,"스킬":"S5"},{"제목":"절댓값을 풀어 큰 반지름 고르기","힌트":"절댓값을 두 경우로 풀면 $r$ 의 두 값 중 큰 것은?","식":["$3-7r=5r\\ \\Rightarrow\\ r=\\frac{1}{4}$","$3-7r=-5r\\ \\Rightarrow\\ r=\\frac{3}{2}$"],"설명":"절댓값 안이 양수일 때와 음수일 때로 나누어 푼다. 두 값 모두 $r>0$ 이므로 가능하고, 문제에서 큰 원을 묻고 있으므로 $\\frac{3}{2}$ 이다.","확인":"3/2","스킬":"C2"}]},"ns-04afc544afe6":{"길":"원 위의 점에서의 접선 공식으로 방정식을 쓰고 $y=mx+n$ 꼴로 바꾼다","단계":[{"제목":"접선의 방정식 세우기","고비":true,"힌트":"원 $x^{2}+y^{2}=r^{2}$ 위의 점 $(x_{1},\\ y_{1})$ 에서의 접선의 방정식은?","식":["$3\\times x+1\\times y=10$","$3x+y=10$"],"설명":"원 $x^{2}+y^{2}=r^{2}$ 위의 점 $(x_{1},\\ y_{1})$ 에서의 접선은 $x_{1}x+y_{1}y=r^{2}$ 이다. 여기서 $r^{2}=10$ 이고 접점이 $(3,\\ 1)$ 이므로 $3x+y=10$ 이다.","확인":null,"스킬":"S5"},{"제목":"m, n 을 읽어 m+n 구하기","힌트":"$3x+y=10$ 을 $y=mx+n$ 꼴로 고치면 $m$, $n$ 은?","식":["$y=-3x+10\\ \\Rightarrow\\ m=-3,\\ n=10$","$m+n=7$"],"설명":"$y$ 에 대해 정리하면 $x$ 의 계수가 $m$, 상수항이 $n$ 이다.","확인":"7","스킬":"S5"}]},"ns-04d839536a7b":{"길":"원 밖의 점 Q 와 중심 사이의 거리에 반지름을 더하고 빼서 최대·최소를 구한다","단계":[{"제목":"중심과 점 Q 사이의 거리","힌트":"원의 중심은 어디이고, 그 중심과 $\\mathrm{Q}$ 사이의 거리는?","식":["중심 $(2,\\ -1)$, 반지름 $2$","$\\sqrt{(5-2)^{2}+(3+1)^{2}}=5$"],"설명":"$(x-2)^{2}+(y+1)^{2}=4$ 에서 중심은 $(2,\\ -1)$, 반지름은 $2$ 이다. 거리가 반지름 $2$ 보다 크므로 점 $\\mathrm{Q}$ 는 원 밖에 있다.","확인":"5","스킬":"S13"},{"제목":"PQ 가 가장 길 때","고비":true,"힌트":"중심과 $\\mathrm{Q}$ 를 지나는 직선이 원과 만나는 두 점 중 어느 쪽이 $\\mathrm{P}$ 일 때 $\\overline{\\mathrm{PQ}}$ 가 가장 긴가?","식":["$5+2=7$"],"설명":"$\\mathrm{Q}$ 에서 먼 쪽 교점이 $\\mathrm{P}$ 일 때 $\\overline{\\mathrm{PQ}}$ 가 최대이다. 이때 $\\overline{\\mathrm{PQ}}$ 는 중심까지의 거리에 반지름을 더한 값이다.","확인":"7","스킬":"S13"},{"제목":"PQ 가 가장 짧을 때","힌트":"$\\mathrm{Q}$ 에서 가까운 쪽 교점이 $\\mathrm{P}$ 이면 $\\overline{\\mathrm{PQ}}$ 는?","식":["$5-2=3$"],"설명":"$\\mathrm{Q}$ 에서 가까운 쪽 교점이 $\\mathrm{P}$ 일 때 $\\overline{\\mathrm{PQ}}$ 가 최소이고, 중심까지의 거리에서 반지름을 뺀 값이다.","확인":"3","스킬":"S13"}]},"ns-0521625afee7":{"길":"점 P 의 자취를 원으로 구하고 평행사변형의 대각선 성질로 PQ 를 PM 으로 바꾼다","단계":[{"제목":"도형 S 의 방정식 구하기","힌트":"$\\mathrm{P}(x,\\ y)$ 로 놓고 $3\\overline{\\mathrm{AP}}=2\\overline{\\mathrm{BP}}$ 의 양변을 제곱하면?","식":["$9\\left\\{(x+3)^{2}+y^{2}\\right\\}=4\\left\\{(x-2)^{2}+y^{2}\\right\\}$","$x^{2}+14x+y^{2}+13=0\\ \\Rightarrow\\ (x+7)^{2}+y^{2}=36$"],"설명":"$\\overline{\\mathrm{AP}}:\\overline{\\mathrm{BP}}=2:3$ 이므로 $3\\overline{\\mathrm{AP}}=2\\overline{\\mathrm{BP}}$ 이고, 제곱하면 근호 없이 정리된다. 전개하면 $5x^{2}+70x+5y^{2}+65=0$ 이고 $5$ 로 나눈 뒤 완전제곱식으로 고치면 중심 $(-7,\\ 0)$, 반지름 $6$ 인 원이다.","확인":"6","스킬":"A6"},{"제목":"대각선의 중점으로 PQ 바꾸기","고비":true,"힌트":"평행사변형 $\\mathrm{CPDQ}$ 의 두 대각선은 어느 선분이고, 서로 어떤 관계인가?","식":["$\\mathrm{M}\\left(\\frac{0+10}{2},\\ \\frac{8+2}{2}\\right)=\\mathrm{M}(5,\\ 5)$","$\\overline{\\mathrm{PQ}}=2\\overline{\\mathrm{PM}}$"],"설명":"꼭짓점이 $\\mathrm{C},\\ \\mathrm{P},\\ \\mathrm{D},\\ \\mathrm{Q}$ 순서이므로 대각선은 $\\overline{\\mathrm{CD}}$ 와 $\\overline{\\mathrm{PQ}}$ 이다. 평행사변형의 두 대각선은 서로를 이등분하므로 $\\overline{\\mathrm{PQ}}$ 의 중점은 $\\overline{\\mathrm{CD}}$ 의 중점 $\\mathrm{M}$ 이다. $\\mathrm{M}$ 은 $\\mathrm{P}$ 의 위치와 상관없이 고정된 점이다.","확인":"5","스킬":"S2"},{"제목":"점 M 과 원의 중심 사이의 거리","힌트":"$\\mathrm{M}(5,\\ 5)$ 와 원의 중심 $(-7,\\ 0)$ 사이의 거리는?","식":["$\\sqrt{(5+7)^{2}+(5-0)^{2}}=\\sqrt{169}=13$"],"설명":"거리 $13$ 이 반지름 $6$ 보다 크므로 점 $\\mathrm{M}$ 은 원 밖에 있다.","확인":"13","스킬":"S13"},{"제목":"PM 의 최솟값과 PQ 의 최솟값","힌트":"원 밖의 점 $\\mathrm{M}$ 에서 원 위의 점 $\\mathrm{P}$ 까지 거리의 최솟값은?","식":["$\\overline{\\mathrm{PM}}\\ge13-6=7$","$\\overline{\\mathrm{PQ}}=2\\overline{\\mathrm{PM}}\\ge14$"],"설명":"원 밖의 점에서 원 위의 점까지 거리의 최솟값은 중심까지의 거리에서 반지름을 뺀 값이다. $\\overline{\\mathrm{PQ}}=2\\overline{\\mathrm{PM}}$ 이므로 최솟값은 $14$ 이다.","확인":"14","스킬":"S5"}]},"ns-057a88bea371":{"길":"만나지 않을 조건은 중심에서 직선까지의 거리가 반지름보다 큰 것이다","단계":[{"제목":"평행한 직선의 방정식","힌트":"기울기가 $-1$ 이고 $y$ 절편이 $-k$ 인 직선의 방정식은?","식":["$y=-x-k$","$x+y+k=0$"],"설명":"$x+y+5=0$ 은 기울기가 $-1$ 이고, 평행한 직선은 기울기가 같다. $y$ 절편이 $-k$ 이므로 $y=-x-k$ 이다.","확인":null,"스킬":"G9"},{"제목":"만나지 않을 조건을 식으로","고비":true,"힌트":"원과 직선이 만나지 않으려면 중심에서 직선까지의 거리와 반지름 사이에 어떤 관계가 있어야 하는가?","식":["$\\frac{|1-2+k|}{\\sqrt{1^{2}+1^{2}}}>\\sqrt{2}$","$|k-1|>2$"],"설명":"중심 $(1,\\ -2)$ 에서 직선 $x+y+k=0$ 까지의 거리가 반지름 $\\sqrt{2}$ 보다 크면 만나지 않는다. 양변에 $\\sqrt{2}$ 를 곱하면 $|k-1|>2$ 이다.","확인":null,"스킬":"G2"},{"제목":"자연수 k 의 최솟값","힌트":"$|k-1|>2$ 를 풀면 $k$ 의 범위는?","식":["$k-1>2$ 또는 $k-1<-2$","$k>3$ 또는 $k<-1$"],"설명":"$k$ 가 자연수이므로 $k>3$ 만 해당하고, 이를 만족하는 가장 작은 자연수는 $4$ 이다.","확인":"4","스킬":"C2"}]},"ns-058cf943241f":{"길":"밑변 AB 는 고정이므로 P 와 직선 AB 사이의 거리가 최소일 때를 찾는다","단계":[{"제목":"직선 AB 의 방정식과 AB 의 길이","힌트":"두 점 $\\mathrm{A}$, $\\mathrm{B}$ 를 지나는 직선의 기울기는?","식":["$\\frac{1-5}{4-2}=-2$","$y-5=-2(x-2)\\ \\Rightarrow\\ 2x+y-9=0$","$\\overline{\\mathrm{AB}}=\\sqrt{(4-2)^{2}+(1-5)^{2}}=2\\sqrt{5}$"],"설명":"삼각형 $\\mathrm{PAB}$ 에서 $\\overline{\\mathrm{AB}}$ 는 점 $\\mathrm{P}$ 와 상관없이 일정하므로 밑변으로 삼는다. 넓이가 최소이려면 높이, 곧 $\\mathrm{P}$ 와 직선 $\\mathrm{AB}$ 사이의 거리가 최소여야 한다.","확인":"-2","스킬":"G9"},{"제목":"P 와 직선 AB 사이 거리의 최솟값","고비":true,"힌트":"원의 중심에서 직선 $\\mathrm{AB}$ 까지의 거리에서 무엇을 빼면 원 위의 점까지의 최소 거리가 되는가?","식":["$\\frac{|2\\times0+0-9|}{\\sqrt{2^{2}+1^{2}}}=\\frac{9\\sqrt{5}}{5}$","$d=\\frac{9\\sqrt{5}}{5}-1$"],"설명":"중심 $(0,\\ 0)$ 에서 직선까지의 거리 $\\frac{9\\sqrt{5}}{5}$ 가 반지름 $1$ 보다 커서 직선은 원과 만나지 않는다. 원 위의 점에서 직선까지 거리의 최솟값은 중심까지의 거리에서 반지름을 뺀 값이다.","확인":null,"스킬":"S5"},{"제목":"삼각형 PAB 의 넓이의 최솟값","힌트":"밑변 $2\\sqrt{5}$, 높이 $\\frac{9\\sqrt{5}}{5}-1$ 인 삼각형의 넓이는?","식":["$\\frac{1}{2}\\times2\\sqrt{5}\\times\\left(\\frac{9\\sqrt{5}}{5}-1\\right)=9-\\sqrt{5}$"],"설명":"$\\sqrt{5}\\times\\frac{9\\sqrt{5}}{5}=9$ 이고 $\\sqrt{5}\\times1=\\sqrt{5}$ 이므로 $9-\\sqrt{5}$ 이다.","확인":null,"스킬":"S8"}]},"ns-059f8bffae2a":{"길":"x 항과 y 항을 각각 완전제곱식으로 묶어 표준형으로 만든다","단계":[{"제목":"표준형으로 고치기","고비":true,"힌트":"$x$ 항과 $y$ 항을 각각 완전제곱식으로 묶으면?","식":["$(x^{2}-4x+4)+(y^{2}-2y+1)=-4+4+1$","$(x-2)^{2}+(y-1)^{2}=1$"],"설명":"$x^{2}-4x$ 에는 $4$, $y^{2}-2y$ 에는 $1$ 을 더해 완전제곱식을 만들고, 같은 수를 우변에도 더한다.","확인":null,"스킬":"A6"},{"제목":"반지름 읽기","힌트":"$(x-a)^{2}+(y-b)^{2}=r^{2}$ 에서 우변이 $1$ 이면 반지름 $r$ 은?","식":["$r^{2}=1\\ \\Rightarrow\\ r=1$"],"설명":"우변은 반지름의 제곱이고 반지름은 양수이다.","확인":"1","스킬":"A6"}]},"ns-0633486f15f4":{"길":"y축과의 교점은 x=0 을 넣은 이차방정식의 두 근이다","단계":[{"제목":"y축과 만나는 두 점","고비":true,"힌트":"원의 방정식에 $x=0$ 을 대입한 $y$ 의 이차방정식의 해는?","식":["$y^{2}+2y-3=0$","$(y+3)(y-1)=0\\ \\Rightarrow\\ y=-3,\\ 1$"],"설명":"$y$ 축 위의 점은 $x=0$ 이므로 대입하면 $y$ 에 대한 이차방정식이 되고, 두 근이 두 점의 $y$ 좌표이다.","확인":null,"스킬":"G1"},{"제목":"선분 PQ 의 길이","힌트":"$y$ 축 위의 두 점 $(0,\\ -3)$, $(0,\\ 1)$ 사이의 거리는?","식":["$\\overline{\\mathrm{PQ}}=|1-(-3)|=4$"],"설명":"두 점이 모두 $y$ 축 위에 있으므로 $y$ 좌표의 차가 선분의 길이이다.","확인":"4","스킬":"G1"}]},"ns-0642f427eea6":{"길":"중심·접점·P 가 이루는 직각삼각형에서 반각의 사인을 구한다","단계":[{"제목":"원의 중심과 반지름","힌트":"원의 방정식을 표준형으로 고치면 반지름은?","식":["$(x-2)^{2}+(y-1)^{2}=25$","중심 $(2,\\ 1)$, 반지름 $5$"],"설명":"$x^{2}-4x$ 에는 $4$, $y^{2}-2y$ 에는 $1$ 을 더해 완전제곱식으로 만들면 우변이 $20+4+1=25$ 이다.","확인":"5","스킬":"A6"},{"제목":"중심과 점 P 사이의 거리","힌트":"중심 $(2,\\ 1)$ 과 $\\mathrm{P}(-4,\\ -7)$ 사이의 거리는?","식":["$\\sqrt{(2+4)^{2}+(1+7)^{2}}=10$"],"설명":"거리가 반지름 $5$ 보다 크므로 점 $\\mathrm{P}$ 는 원 밖에 있다.","확인":"10","스킬":"S5"},{"제목":"접선 사이 각의 절반","고비":true,"힌트":"중심 $\\mathrm{C}$, 접점 $\\mathrm{T}$, 점 $\\mathrm{P}$ 로 이루어진 직각삼각형에서 $\\angle\\mathrm{CPT}$ 의 사인은?","식":["$\\sin\\frac{\\theta}{2}=\\frac{5}{10}=\\frac{1}{2}$","$\\frac{\\theta}{2}=30^{\\circ}$"],"설명":"접선은 접점에서 반지름과 수직이고, 중심과 $\\mathrm{P}$ 를 잇는 선은 두 접선이 이루는 각 $\\theta$ 를 이등분한다. 직각삼각형에서 빗변이 $\\overline{\\mathrm{CP}}=10$, 접점 쪽 변이 반지름 $5$ 이므로 $\\sin\\frac{\\theta}{2}=\\frac{1}{2}$ 이다.","확인":"30","스킬":"S6"},{"제목":"cos θ 의 값","힌트":"$\\theta=60^{\\circ}$ 일 때 $\\cos\\theta$ 는?","식":["$\\theta=60^{\\circ}\\ \\Rightarrow\\ \\cos\\theta=\\frac{1}{2}$"],"설명":"$\\frac{\\theta}{2}=30^{\\circ}$ 이므로 $\\theta=60^{\\circ}$ 이다.","확인":"1/2","스킬":"S6"}]},"ns-074d8c8884c0":{"길":"AB 의 중점 M 을 잡아 중선정리로 PM 의 식으로 바꾼다","단계":[{"제목":"중선정리로 식 바꾸기","고비":true,"힌트":"선분 $\\mathrm{AB}$ 의 중점 $\\mathrm{M}$ 의 좌표와 $\\overline{\\mathrm{AM}}$ 의 길이는?","식":["$\\mathrm{M}\\left(\\frac{3+3}{2},\\ \\frac{5+3}{2}\\right)=\\mathrm{M}(3,\\ 4)$","$\\overline{\\mathrm{AM}}=1$","$\\overline{\\mathrm{PA}}^{2}+\\overline{\\mathrm{PB}}^{2}=2\\left(\\overline{\\mathrm{PM}}^{2}+\\overline{\\mathrm{AM}}^{2}\\right)=2\\left(\\overline{\\mathrm{PM}}^{2}+1\\right)$"],"설명":"삼각형 $\\mathrm{PAB}$ 에서 $\\mathrm{M}$ 이 $\\overline{\\mathrm{AB}}$ 의 중점이면 중선정리로 $\\overline{\\mathrm{PA}}^{2}+\\overline{\\mathrm{PB}}^{2}=2\\left(\\overline{\\mathrm{PM}}^{2}+\\overline{\\mathrm{AM}}^{2}\\right)$ 이다. $\\overline{\\mathrm{AB}}=2$ 이므로 $\\overline{\\mathrm{AM}}=1$ 이다. 이제 $\\overline{\\mathrm{PM}}$ 의 최솟값과 최댓값만 구하면 된다.","확인":"1","스킬":"S2"},{"제목":"점 M 과 원의 중심 사이의 거리","힌트":"원의 중심 $\\mathrm{O}$ 와 $\\mathrm{M}(3,\\ 4)$ 사이의 거리는?","식":["$\\overline{\\mathrm{OM}}=\\sqrt{3^{2}+4^{2}}=5$"],"설명":"$\\overline{\\mathrm{OM}}=5$ 가 반지름 $2$ 보다 크므로 점 $\\mathrm{M}$ 은 원 밖에 있다.","확인":"5","스킬":"S4"},{"제목":"PM 의 최솟값과 최댓값","힌트":"원 밖의 점 $\\mathrm{M}$ 에서 원 위의 점 $\\mathrm{P}$ 까지 거리의 최솟값과 최댓값은?","식":["$5-2\\le\\overline{\\mathrm{PM}}\\le5+2$","$3\\le\\overline{\\mathrm{PM}}\\le7$"],"설명":"중심 $\\mathrm{O}$ 와 $\\mathrm{M}$ 을 지나는 직선이 원과 만나는 두 점에서 각각 최솟값, 최댓값이 된다. 최솟값은 중심까지의 거리에서 반지름을 뺀 값이고, 최댓값은 반지름을 더한 값이다.","확인":null,"스킬":"S5"},{"제목":"a, b 와 b-a 구하기","힌트":"$\\overline{\\mathrm{PM}}$ 의 최솟값, 최댓값을 $2\\left(\\overline{\\mathrm{PM}}^{2}+1\\right)$ 에 넣어 $a$, $b$ 를 구하면 $b-a$ 는?","식":["$a=2\\left(3^{2}+1\\right)=20$","$b=2\\left(7^{2}+1\\right)=100$","$b-a=80$"],"설명":"$2\\left(\\overline{\\mathrm{PM}}^{2}+1\\right)$ 은 $\\overline{\\mathrm{PM}}$ 이 클수록 커지므로 최솟값은 $\\overline{\\mathrm{PM}}=3$ 일 때, 최댓값은 $\\overline{\\mathrm{PM}}=7$ 일 때이다.","확인":"80","스킬":"S2"}]},"ns-07e0ad2d00b1":{"길":"두 축에 접하는 원의 중심을 $(r,\\ r)$ 로 두고 중심 사이 거리에 두 반지름을 더한다","단계":[{"제목":"원의 중심을 문자로 놓기","힌트":"점 $(2,\\ 1)$ 이 제$1$사분면 위에 있을 때 두 축에 모두 접하는 원의 중심은?","식":["$(r,\\ r)\\ (r>0)$"],"설명":"두 축에 모두 접하는 원의 중심에서 두 축까지의 거리는 모두 반지름 $r$ 이다. 점 $(2,\\ 1)$ 이 제$1$사분면 위에 있으므로 원은 제$1$사분면에 놓이고 중심은 $(r,\\ r)$ 이다.","확인":null,"스킬":"S13"},{"제목":"점 (2, 1) 을 지나는 조건","고비":true,"힌트":"중심 $(r,\\ r)$ 에서 점 $(2,\\ 1)$ 까지의 거리가 반지름과 같다는 식을 세우면?","식":["$(2-r)^{2}+(1-r)^{2}=r^{2}$","$r^{2}-6r+5=0\\ \\Rightarrow\\ (r-1)(r-5)=0$"],"설명":"원이 점 $(2,\\ 1)$ 을 지나므로 중심과 그 점 사이의 거리가 반지름 $r$ 이다. 전개하면 $4-4r+r^{2}+1-2r+r^{2}=r^{2}$ 이고 정리하면 $r^{2}-6r+5=0$ 이다.","확인":null,"스킬":"S13"},{"제목":"두 원의 중심 사이의 거리","힌트":"두 원의 반지름을 구했을 때 두 중심 사이 거리의 제곱은?","식":["$r=1,\\ 5\\ \\Rightarrow\\ C_{1}(1,\\ 1),\\ C_{2}(5,\\ 5)$","$\\overline{C_{1}C_{2}}^{2}=(5-1)^{2}+(5-1)^{2}=32$"],"설명":"반지름이 $1$ 인 원의 중심은 $(1,\\ 1)$, 반지름이 $5$ 인 원의 중심은 $(5,\\ 5)$ 이다. 거리의 제곱이 $32$ 이므로 거리는 $4\\sqrt{2}$ 이다.","확인":"32","스킬":"S13"},{"제목":"AB 의 최댓값","힌트":"두 원 위의 점 사이 거리가 최대이려면 중심 사이 거리에 무엇을 더하는가?","식":["$\\overline{C_{1}C_{2}}=4\\sqrt{2}$","$4\\sqrt{2}+1+5=6+4\\sqrt{2}$"],"설명":"두 점이 각각 두 중심을 잇는 직선 위에서 바깥쪽 끝에 있을 때 $\\overline{\\mathrm{AB}}$ 가 최대이다. 최댓값은 중심 사이의 거리에 두 반지름을 더한 값이다.","확인":null,"스킬":"S5"}]},"ns-088ea7c8c45b":{"길":"두 원의 교점을 지나는 원을 식1+k·식2=0 으로 두고 한 점으로 k 를 정한다","단계":[{"제목":"교점을 지나는 도형의 식 세우기","고비":true,"힌트":"두 원의 교점을 모두 지나는 도형은 두 식을 어떻게 결합한 꼴로 쓸 수 있는가?","식":["$\\left(x^{2}+y^{2}-4x-6y+9\\right)+k\\left(x^{2}+y^{2}-2x-4y+4\\right)=0$"],"설명":"두 원의 교점의 좌표는 두 식을 모두 $0$ 으로 만든다. 그러므로 첫째 식에 둘째 식의 $k$ 배를 더한 식도 $0$ 이 되어 교점을 지나고, $k$ 를 정하면 원이 하나 정해진다.","확인":null,"스킬":"A3"},{"제목":"점 (-1, 0) 을 대입해 k 구하기","힌트":"$x=-1,\\ y=0$ 을 대입하면 $k$ 는?","식":["$(1+4+9)+k(1+2+4)=0$","$14+7k=0\\ \\Rightarrow\\ k=-2$"],"설명":"구하는 원이 점 $(-1,\\ 0)$ 을 지나므로 그 좌표를 대입해도 식이 성립한다.","확인":"-2","스킬":"A3"},{"제목":"표준형으로 고쳐 반지름 읽기","힌트":"$k=-2$ 를 대입해 정리한 뒤 표준형으로 고치면 반지름은?","식":["$-x^{2}-y^{2}+2y+1=0\\ \\Rightarrow\\ x^{2}+y^{2}-2y-1=0$","$x^{2}+(y-1)^{2}=2\\ \\Rightarrow\\ r=\\sqrt{2}$"],"설명":"$x^{2}$, $y^{2}$ 의 계수가 $-1$ 이므로 양변에 $-1$ 을 곱해 정리한다. $y^{2}-2y$ 를 완전제곱식 $(y-1)^{2}-1$ 로 바꾸면 우변이 $2$ 가 된다.","확인":null,"스킬":"A6"}]},"ns-09373a00b945":{"길":"점 P 를 (p, q) 로 놓고 p²+q²=4 를 이용해 q 의 일차식으로 만든다","단계":[{"제목":"두 제곱의 합을 p, q 로 나타내기","힌트":"$\\mathrm{P}(p,\\ q)$ 로 놓고 거리 공식을 쓰면 $\\overline{\\mathrm{PA}}^{2}+\\overline{\\mathrm{PB}}^{2}$ 은?","식":["$\\overline{\\mathrm{PA}}^{2}=(p+3)^{2}+(q-2)^{2}$","$\\overline{\\mathrm{PB}}^{2}=(p-3)^{2}+(q-4)^{2}$","$\\overline{\\mathrm{PA}}^{2}+\\overline{\\mathrm{PB}}^{2}=2p^{2}+2q^{2}-12q+38$"],"설명":"전개하면 $6p$ 와 $-6p$ 가 서로 없어진다. 상수항은 $9+4+9+16=38$ 이다.","확인":null,"스킬":"S4"},{"제목":"원의 식으로 q 만 남기기","고비":true,"힌트":"$p^{2}+q^{2}=4$ 를 이용하면 $2p^{2}+2q^{2}-12q+38$ 은 $q$ 에 대한 어떤 식이 되는가?","식":["$2\\left(p^{2}+q^{2}\\right)-12q+38=2\\times4-12q+38$","$=-12q+46$"],"설명":"점 $\\mathrm{P}$ 는 원 $x^{2}+y^{2}=4$ 위의 점이므로 $p^{2}+q^{2}=4$ 이다. $2p^{2}+2q^{2}$ 을 $2\\left(p^{2}+q^{2}\\right)$ 로 묶어 대입하면 $q$ 만 남는다.","확인":"46","스킬":"A1"},{"제목":"q 의 범위와 최솟값","힌트":"$q$ 의 계수가 음수이므로 $q$ 가 클수록 식의 값은 어떻게 되는가?","식":["$-2\\le q\\le2$","$q=2$ 일 때 $-12\\times2+46=22$"],"설명":"점 $\\mathrm{P}$ 가 반지름 $2$ 인 원 위에 있으므로 $-2\\le q\\le2$ 이다. $q$ 의 계수가 음수라 $q$ 가 최대인 $2$ 일 때 식이 최소가 된다.","확인":"22","스킬":"S4"}]},"ns-0b0c3da6acfd":{"길":"연립방정식의 해의 개수를 직선과 원의 교점 개수로 바꿔 센다","단계":[{"제목":"직선과 원으로 바꿔 거리 구하기","힌트":"원점에서 직선 $5x+12y-a=0$ 까지의 거리에서 분모 $\\sqrt{5^{2}+12^{2}}$ 은?","식":["$x^{2}+y^{2}=a$ 는 중심이 원점이고 반지름이 $\\sqrt{a}$ 인 원","$d=\\frac{|-a|}{\\sqrt{5^{2}+12^{2}}}=\\frac{a}{13}$"],"설명":"연립방정식의 실수해는 직선 $5x+12y=a$ 와 원 $x^{2}+y^{2}=a$ 의 교점의 좌표이다. $a\\ge0$ 이므로 $|-a|=a$ 이다.","확인":"13","스킬":"G2"},{"제목":"거리와 반지름 비교로 a 의 범위 구하기","고비":true,"힌트":"$a>0$ 일 때 $\\frac{a}{13}>\\sqrt{a}$ 를 만족하는 $a$ 의 범위는?","식":["$\\frac{a}{13}>\\sqrt{a}\\ \\Leftrightarrow\\ \\sqrt{a}>13\\ \\Leftrightarrow\\ a>169$","$d=r\\ \\Leftrightarrow\\ a=169,\\ \\ d<r\\ \\Leftrightarrow\\ 0<a<169$"],"설명":"$a>0$ 이면 $\\sqrt{a}>0$ 이므로 부등식의 양변을 $\\sqrt{a}$ 로 나눌 수 있다. $d>r$ 이면 만나지 않고, $d=r$ 이면 접하여 한 쌍, $d<r$ 이면 두 점에서 만난다.","확인":"169","스킬":"G2"},{"제목":"a=0 인 경우 따로 살피기","힌트":"$a=0$ 이면 $x^{2}+y^{2}=0$ 은 어떤 도형인가?","식":["$x^{2}+y^{2}=0\\ \\Rightarrow\\ (x,\\ y)=(0,\\ 0)$","$5\\times0+12\\times0=0$"],"설명":"$a=0$ 이면 원이 아니라 원점 한 점이고, 이 점은 직선 $5x+12y=0$ 위에 있다. 그래서 해가 오직 한 쌍 $(0,\\ 0)$ 이다. 거리와 반지름의 비교는 $a>0$ 에서만 쓸 수 있어 이 경우를 따로 센다.","확인":null,"스킬":"C2"},{"제목":"p, q, r 의 값 구하기","힌트":"해가 없는 경우, 한 쌍인 경우, 두 쌍인 경우의 $a$ 의 범위에서 각각 가장 작은 음이 아닌 정수는?","식":["해가 없음: $a>169\\ \\Rightarrow\\ p=170$","한 쌍: $a=0,\\ 169\\ \\Rightarrow\\ q=0$","두 쌍: $0<a<169\\ \\Rightarrow\\ r=1$"],"설명":"$a$ 는 음이 아닌 정수이다. $169$ 보다 큰 가장 작은 정수는 $170$ 이고, 한 쌍이 되는 $a$ 는 $0$ 과 $169$ 이므로 최솟값이 $0$ 이다. 두 쌍이 되는 $0<a<169$ 에서 가장 작은 정수는 $1$ 이다.","확인":null,"스킬":"C2"},{"제목":"p+2q+3r 계산","힌트":"$p=170,\\ q=0,\\ r=1$ 을 대입하면?","식":["$170+2\\times0+3\\times1=173$"],"설명":"구한 세 값을 $p+2q+3r$ 에 그대로 대입한다.","확인":"173","스킬":"G2"}]},"ns-0ba06933063f":{"길":"수직인 두 접선의 교점이 그리는 원을 구하고 직선까지 거리의 최댓값을 구한다","단계":[{"제목":"점 P 가 그리는 원 구하기","고비":true,"힌트":"수직인 두 접선과 두 접점, 원의 중심을 이으면 어떤 사각형이 되는가?","식":["$\\overline{\\mathrm{CP}}=\\sqrt{2}\\times\\sqrt{10}=2\\sqrt{5}$","$(x-1)^{2}+(y-2)^{2}=20$"],"설명":"두 접점을 $\\mathrm{T}_{1}$, $\\mathrm{T}_{2}$ 라 하면 접선과 반지름이 수직이므로 사각형 $\\mathrm{CT}_{1}\\mathrm{PT}_{2}$ 는 네 각이 모두 직각이다. 이웃한 두 변이 반지름으로 같아 한 변이 $\\sqrt{10}$ 인 정사각형이고, $\\overline{\\mathrm{CP}}$ 는 그 대각선이다. 그래서 점 $\\mathrm{P}$ 는 중심 $\\mathrm{C}(1,\\ 2)$ 에서 $2\\sqrt{5}$ 만큼 떨어진 원 위에 있다.","확인":"20","스킬":"S5"},{"제목":"중심과 직선 사이의 거리","힌트":"원의 중심 $(1,\\ 2)$ 에서 직선 $2x+y+5=0$ 까지의 거리는?","식":["$\\frac{|2\\times1+2+5|}{\\sqrt{2^{2}+1^{2}}}=\\frac{9}{\\sqrt{5}}=\\frac{9\\sqrt{5}}{5}$"],"설명":"직선 $y=-2x-5$ 는 $2x+y+5=0$ 이다. 점 $\\mathrm{P}$ 가 그리는 원의 중심은 처음 원의 중심 $(1,\\ 2)$ 와 같다.","확인":null,"스킬":"S13"},{"제목":"거리의 최댓값","힌트":"원 위의 점에서 직선까지 거리의 최댓값은 중심까지의 거리에 무엇을 더한 값인가?","식":["$\\frac{9\\sqrt{5}}{5}+2\\sqrt{5}=\\frac{19\\sqrt{5}}{5}$"],"설명":"중심에서 직선에 내린 수선이 원과 만나는 두 점 중 직선에서 먼 쪽이 최대이다. 최댓값은 중심까지의 거리에 반지름 $2\\sqrt{5}$ 를 더한 값이고, $2\\sqrt{5}=\\frac{10\\sqrt{5}}{5}$ 로 통분해 더한다.","확인":null,"스킬":"S5"},{"제목":"q-p 구하기","힌트":"$\\frac{19\\sqrt{5}}{5}=\\frac{q}{p}\\sqrt{5}$ 에서 서로소인 자연수 $p$, $q$ 는?","식":["$q=19,\\ p=5\\ \\Rightarrow\\ q-p=14$"],"설명":"$19$ 와 $5$ 는 서로소이므로 $\\frac{19}{5}$ 가 기약분수이다.","확인":"14","스킬":"S4"}]},"ns-0c23a8acc563":{"길":"중심에서 현에 수선을 내려 반지름²=거리²+반현² 으로 식을 세운다","단계":[{"제목":"원의 중심과 반지름 놓기","힌트":"중심이 $y$ 축 위에서 $x$ 축 위쪽에 있고 $x$ 축에 접하는 원의 중심과 반지름을 $a$ 로 나타내면?","식":["중심 $\\mathrm{C}(0,\\ a)$, 반지름 $a\\ (a>0)$"],"설명":"$x$ 축에 접하므로 중심에서 $x$ 축까지의 거리가 반지름이다. 중심이 $x$ 축 위쪽에 있으므로 $y$ 좌표 $a$ 가 양수이고 반지름과 같다.","확인":null,"스킬":"S13"},{"제목":"수선의 발로 직각삼각형 만들기","힌트":"중심 $\\mathrm{C}$ 에서 현 $\\mathrm{AB}$ 에 내린 수선의 발 $\\mathrm{H}$ 에 대해 $\\overline{\\mathrm{AH}}$ 는?","식":["$\\overline{\\mathrm{AH}}=\\frac{1}{2}\\overline{\\mathrm{AB}}=2$","$\\overline{\\mathrm{CH}}=\\frac{|0+2a+1|}{\\sqrt{1^{2}+2^{2}}}=\\frac{2a+1}{\\sqrt{5}}$"],"설명":"중심에서 현에 내린 수선은 현을 이등분하므로 $\\overline{\\mathrm{AH}}=2$ 이다. $\\overline{\\mathrm{CH}}$ 는 점 $(0,\\ a)$ 와 직선 $x+2y+1=0$ 사이의 거리이고, $a>0$ 이므로 절댓값 안이 양수이다.","확인":"2","스킬":"S5"},{"제목":"피타고라스 정리로 식 세우기","고비":true,"힌트":"직각삼각형 $\\mathrm{CAH}$ 에서 $\\overline{\\mathrm{CA}}$ 가 빗변일 때 세 변 사이의 관계식은?","식":["$a^{2}=2^{2}+\\frac{(2a+1)^{2}}{5}$","$5a^{2}=20+4a^{2}+4a+1\\ \\Rightarrow\\ a^{2}-4a-21=0$"],"설명":"$\\overline{\\mathrm{CA}}$ 는 반지름 $a$ 이고 $\\angle\\mathrm{CHA}=90^{\\circ}$ 이므로 $\\overline{\\mathrm{CA}}^{2}=\\overline{\\mathrm{AH}}^{2}+\\overline{\\mathrm{CH}}^{2}$ 이다. 양변에 $5$ 를 곱해 분모를 없앤 뒤 정리한다.","확인":null,"스킬":"S3"},{"제목":"a 의 값과 반지름","힌트":"$a^{2}-4a-21=0$ 을 인수분해하고 $a>0$ 인 해를 고르면?","식":["$(a-7)(a+3)=0$","$a>0\\ \\Rightarrow\\ a=7$"],"설명":"$a=-3$ 은 반지름이 양수라는 조건에 맞지 않는다. 반지름은 $a$ 와 같다.","확인":"7","스킬":"S5"}]},"ns-0d192c796238":{"길":"두 원의 식을 빼서 공통현의 직선을 얻고 기울기를 4 와 같게 놓는다","단계":[{"제목":"공통현의 방정식 구하기","고비":true,"힌트":"두 원의 식을 변끼리 빼면 $x^{2}$, $y^{2}$ 항이 없어진다. 남는 식은?","식":["$\\left(x^{2}+y^{2}+2ay+a^{2}-4\\right)-\\left(x^{2}+y^{2}+2x-8\\right)=0$","$-2x+2ay+a^{2}+4=0$"],"설명":"두 원의 교점은 두 식을 모두 만족하므로 두 식의 차도 만족한다. $x^{2}$, $y^{2}$ 이 사라진 일차식이라 두 교점을 지나는 직선의 방정식이다.","확인":null,"스킬":"A10"},{"제목":"직선의 기울기 읽기","힌트":"$y$ 에 대해 정리하면 $x$ 의 계수는?","식":["$2ay=2x-a^{2}-4$","$y=\\frac{1}{a}x-\\frac{a^{2}+4}{2a}$"],"설명":"$0<a^{2}<24$ 에서 $a\\ne0$ 이므로 양변을 $2a$ 로 나눌 수 있다. $x$ 의 계수 $\\frac{1}{a}$ 이 기울기이다.","확인":null,"스킬":"A10"},{"제목":"평행 조건으로 a 구하기","힌트":"직선 $y=4x$ 와 평행하려면 기울기가 같아야 한다. $a$ 는?","식":["$\\frac{1}{a}=4\\ \\Rightarrow\\ a=\\frac{1}{4}$"],"설명":"평행한 두 직선은 기울기가 같다. $a=\\frac{1}{4}$ 이면 $a^{2}=\\frac{1}{16}$ 이라 $0<a^{2}<24$ 를 만족한다.","확인":"1/4","스킬":"G9"}]},"ns-0dc1de02192d":{"길":"기울기 1/2 인 직선 y=x/2+c 를 두고 원점까지의 거리를 반지름과 같게 놓는다","단계":[{"제목":"평행한 직선의 방정식","힌트":"기울기가 $\\frac{1}{2}$ 이고 $y$ 절편이 $c$ 인 직선을 일차식 꼴로 쓰면?","식":["$y=\\frac{1}{2}x+c$","$x-2y+2c=0$"],"설명":"$2x-4y+5=0$ 은 $y=\\frac{1}{2}x+\\frac{5}{4}$ 이므로 기울기가 $\\frac{1}{2}$ 이다. 평행한 직선은 기울기가 같다.","확인":null,"스킬":"G9"},{"제목":"접하는 조건으로 |2c| 구하기","고비":true,"힌트":"원점에서 직선까지의 거리가 반지름 $\\sqrt{20}$ 과 같다는 식에서 $|2c|$ 는?","식":["$\\frac{|2c|}{\\sqrt{1^{2}+(-2)^{2}}}=\\sqrt{20}$","$|2c|=\\sqrt{20}\\times\\sqrt{5}=10$"],"설명":"원 $x^{2}+y^{2}=20$ 은 중심이 원점이고 반지름이 $\\sqrt{20}$ 이다. 접하면 원점에서 직선까지의 거리가 반지름과 같다.","확인":"10","스킬":"G2"},{"제목":"양수인 y 절편 고르기","힌트":"$|2c|=10$ 에서 $c$ 는 어떤 값이고, 그중 양수는?","식":["$|c|=5\\ \\Rightarrow\\ c=5,\\ -5$","$c>0\\ \\Rightarrow\\ c=5$"],"설명":"$y$ 절편이 $c$ 이므로 두 접선의 $y$ 절편은 $5$ 와 $-5$ 이고, 양수인 것은 $5$ 이다.","확인":"5","스킬":"G2"}]},"ns-0e3c8fb349da":{"길":"접선 l 을 구하고 두 축에 접하는 원의 중심을 네 사분면으로 나누어 반지름을 모두 구한다","단계":[{"제목":"접선 l 의 방정식 구하기","힌트":"기울기가 $1$ 인 직선 $y=x+c$ 와 원의 중심 $(1,\\ 2)$ 사이의 거리가 반지름과 같다는 식은?","식":["$\\frac{|1-2+c|}{\\sqrt{1^{2}+1^{2}}}=2$","$|c-1|=2\\sqrt{2}\\ \\Rightarrow\\ c=1\\pm2\\sqrt{2}$"],"설명":"직선 $y=x+c$ 는 $x-y+c=0$ 이다. 접하므로 중심에서 직선까지의 거리가 반지름 $2$ 와 같다. 접선 $l$ 은 두 개이다.","확인":null,"스킬":"S5"},{"제목":"두 축에 접하는 원의 중심 나누기","고비":true,"힌트":"두 축에 접하는 원의 중심은 사분면에 따라 어떻게 나타내고, 직선 $x-y+c=0$ 까지의 거리 조건은 어떻게 되는가?","식":["중심 $(r,\\ r),\\ (-r,\\ -r)$ 일 때 $\\frac{|c|}{\\sqrt{2}}=r$","중심 $(-r,\\ r)$ 일 때 $\\frac{|c-2r|}{\\sqrt{2}}=r$","중심 $(r,\\ -r)$ 일 때 $\\frac{|c+2r|}{\\sqrt{2}}=r$"],"설명":"두 축에 모두 접하는 원의 중심은 $(\\pm r,\\ \\pm r)$ 의 네 꼴이다. 중심이 직선 $y=x$ 위에 있는 두 경우는 $x-y$ 의 값이 $0$ 이라 같은 식이 된다. 나머지 두 경우는 중심 좌표를 $x-y+c$ 에 넣어 따로 계산한다.","확인":null,"스킬":"C2"},{"제목":"중심이 직선 y=x 위에 있을 때","힌트":"$r=\\frac{|c|}{\\sqrt{2}}$ 에 두 $c$ 의 값을 넣으면 $r$ 은?","식":["$c=1+2\\sqrt{2}\\ \\Rightarrow\\ r=2+\\frac{\\sqrt{2}}{2}$","$c=1-2\\sqrt{2}\\ \\Rightarrow\\ r=2-\\frac{\\sqrt{2}}{2}$"],"설명":"$\\frac{1+2\\sqrt{2}}{\\sqrt{2}}=\\frac{\\sqrt{2}+4}{2}$ 이고, $|1-2\\sqrt{2}|=2\\sqrt{2}-1$ 이므로 $\\frac{2\\sqrt{2}-1}{\\sqrt{2}}=\\frac{4-\\sqrt{2}}{2}$ 이다.","확인":null,"스킬":"C2"},{"제목":"중심이 제2사분면에 있을 때","힌트":"$|c-2r|=\\sqrt{2}r$ 에서 $c$ 가 양수일 때 $r$ 은?","식":["$c-2r=\\pm\\sqrt{2}r\\ \\Rightarrow\\ r=\\frac{c}{2\\pm\\sqrt{2}}$","$c=1+2\\sqrt{2}\\ \\Rightarrow\\ r=\\frac{3\\sqrt{2}-2}{2},\\ \\frac{6+5\\sqrt{2}}{2}$"],"설명":"$r>0$ 이고 $2\\pm\\sqrt{2}>0$ 이므로 $c>0$ 인 $c=1+2\\sqrt{2}$ 만 가능하다. 분모의 근호는 켤레를 곱해 없앤다.","확인":null,"스킬":"C2"},{"제목":"중심이 제4사분면에 있을 때","힌트":"$|c+2r|=\\sqrt{2}r$ 에서 $c$ 가 음수일 때 $r$ 은?","식":["$c+2r=\\pm\\sqrt{2}r\\ \\Rightarrow\\ r=\\frac{-c}{2\\pm\\sqrt{2}}$","$c=1-2\\sqrt{2}\\ \\Rightarrow\\ r=\\frac{5\\sqrt{2}-6}{2},\\ \\frac{3\\sqrt{2}+2}{2}$"],"설명":"$c+2r=\\pm\\sqrt{2}r$ 에서 $c=(-2\\pm\\sqrt{2})r$ 이고 $-2\\pm\\sqrt{2}<0$ 이므로 $c<0$ 인 $c=1-2\\sqrt{2}$ 만 가능하다. $-c=2\\sqrt{2}-1$ 을 넣고 유리화한다.","확인":null,"스킬":"C2"},{"제목":"최댓값과 최솟값의 합","힌트":"구한 반지름 여섯 개 중 가장 큰 것과 가장 작은 것의 합은?","식":["최대 $\\frac{6+5\\sqrt{2}}{2}$, 최소 $\\frac{5\\sqrt{2}-6}{2}$","$\\frac{6+5\\sqrt{2}}{2}+\\frac{5\\sqrt{2}-6}{2}=5\\sqrt{2}$"],"설명":"여섯 반지름은 대략 $2.71,\\ 1.29,\\ 1.12,\\ 6.54,\\ 3.12,\\ 0.54$ 이다. 가장 큰 것은 $\\frac{6+5\\sqrt{2}}{2}$, 가장 작은 것은 $\\frac{5\\sqrt{2}-6}{2}$ 이다.","확인":null,"스킬":"C2"}]},"ns-0f3696776980":{"길":"직선이 지나는 정점을 찾아 H 가 그리는 원을 구하고 거리 범위의 정수를 센다","단계":[{"제목":"직선이 지나는 정점 구하기","힌트":"식을 $m$ 에 대해 정리했을 때 $m$ 의 값에 관계없이 직선이 지나는 점은?","식":["$m(x+2y-3)+(y-x)=0$","$x+2y-3=0,\\ y-x=0\\ \\Rightarrow\\ \\mathrm{Q}(1,\\ 1)$"],"설명":"$m$ 의 값에 관계없이 성립하려면 $m$ 의 계수와 나머지 부분이 모두 $0$ 이어야 한다. 두 식을 연립하면 정점 $\\mathrm{Q}(1,\\ 1)$ 이다.","확인":null,"스킬":"G3"},{"제목":"점 H 가 움직이는 도형","고비":true,"힌트":"직선이 항상 $\\mathrm{Q}$ 를 지날 때 $\\angle\\mathrm{PHQ}$ 의 크기는?","식":["$\\angle\\mathrm{PHQ}=90^{\\circ}$","$\\mathrm{PQ}$ 의 중점 $(2,\\ 3)$, 반지름 $\\frac{1}{2}\\overline{\\mathrm{PQ}}=\\sqrt{5}$"],"설명":"$\\mathrm{H}$ 는 $\\mathrm{P}$ 에서 직선에 내린 수선의 발이고 직선은 $\\mathrm{Q}$ 를 지나므로 $\\angle\\mathrm{PHQ}=90^{\\circ}$ 이다. 선분 $\\mathrm{PQ}$ 에 대한 원주각이 직각이면 $\\mathrm{H}$ 는 $\\mathrm{PQ}$ 를 지름으로 하는 원 위에 있다. $\\overline{\\mathrm{PQ}}=\\sqrt{2^{2}+4^{2}}=2\\sqrt{5}$ 이므로 반지름은 $\\sqrt{5}$ 이다.","확인":null,"스킬":"S5"},{"제목":"주어진 식의 뜻과 중심까지의 거리","힌트":"$\\sqrt{(a-6)^{2}+b^{2}}$ 은 $\\mathrm{H}$ 와 어느 점 사이의 거리이고, 그 점과 원의 중심 사이의 거리는?","식":["$\\sqrt{(a-6)^{2}+b^{2}}=\\overline{\\mathrm{HD}},\\ \\mathrm{D}(6,\\ 0)$","$\\sqrt{(6-2)^{2}+(0-3)^{2}}=5$"],"설명":"점 $\\mathrm{D}$ 를 $(6,\\ 0)$ 이라 하면 구하는 값은 $\\overline{\\mathrm{HD}}$ 이다. 중심까지의 거리 $5$ 가 반지름 $\\sqrt{5}$ 보다 크므로 $\\mathrm{D}$ 는 원 밖에 있다.","확인":"5","스킬":"S4"},{"제목":"HD 가 가질 수 있는 범위","힌트":"원 밖의 점 $\\mathrm{D}$ 에서 원 위의 점까지 거리의 최솟값과 최댓값은?","식":["$5-\\sqrt{5}\\le\\overline{\\mathrm{HD}}\\le5+\\sqrt{5}$","$2.76\\cdots\\le\\overline{\\mathrm{HD}}\\le7.23\\cdots$"],"설명":"최솟값은 중심까지의 거리에서 반지름을 뺀 값이고, 최댓값은 더한 값이다. $\\sqrt{5}=2.236\\cdots$ 이다.","확인":null,"스킬":"S5"},{"제목":"정수인 거리와 점의 개수","힌트":"범위 안에 있는 정수는 무엇이고, 각 정수 거리를 갖는 원 위의 점은 몇 개인가?","식":["$\\overline{\\mathrm{HD}}=3,\\ 4,\\ 5,\\ 6,\\ 7$","각각 원 위에 $2$ 개씩, $5\\times2=10$"],"설명":"범위의 양 끝이 아닌 거리는 원 위에 같은 거리인 점이 두 개씩 있다. 정수 $3,\\ 4,\\ 5,\\ 6,\\ 7$ 은 모두 양 끝 값 사이에 있다.","확인":null,"스킬":"C2"},{"제목":"빠지는 점 확인과 최종 개수","힌트":"$m$ 이 실수일 때 나올 수 없는 직선에 해당하는 $\\mathrm{H}$ 는 어느 점인가?","식":["$x+2y-3=0$ 일 때 $\\mathrm{H}=\\mathrm{Q}$","$\\overline{\\mathrm{QD}}=\\sqrt{(6-1)^{2}+(0-1)^{2}}=\\sqrt{26}$"],"설명":"식 $m(x+2y-3)+(y-x)=0$ 에서 $m$ 이 실수이면 직선 $x+2y-3=0$ 은 나오지 않는다. 이 직선은 $\\mathrm{Q}$ 에서 $\\overline{\\mathrm{PQ}}$ 에 수직이라 $\\mathrm{H}=\\mathrm{Q}$ 인 경우가 빠진다. 그런데 $\\sqrt{26}$ 은 정수가 아니어서 센 $10$ 개에는 영향이 없다.","확인":"10","스킬":"G3"}]},"ns-0fd10e5889aa":{"길":"접선은 중심과 접점을 잇는 반지름에 수직임을 이용해 접선의 식을 세운다","단계":[{"제목":"중심과 접점을 잇는 직선의 기울기","힌트":"원의 중심 $(-3,\\ 2)$ 와 접점 $(1,\\ -2)$ 를 지나는 직선의 기울기는?","식":["$(x+3)^{2}+(y-2)^{2}=32$","$\\frac{-2-2}{1-(-3)}=-1$"],"설명":"$x^{2}+6x$ 에는 $9$, $y^{2}-4y$ 에는 $4$ 를 더해 완전제곱식으로 만들면 우변이 $19+9+4=32$ 이고 중심은 $(-3,\\ 2)$ 이다.","확인":"-1","스킬":"A6"},{"제목":"접선의 방정식 구하기","고비":true,"힌트":"접선은 반지름에 수직이다. 반지름의 기울기가 $-1$ 이면 접선의 기울기와 $y$ 절편은?","식":["$-1\\times m=-1\\ \\Rightarrow\\ m=1$","$y+2=x-1\\ \\Rightarrow\\ y=x-3$"],"설명":"수직인 두 직선은 기울기의 곱이 $-1$ 이므로 접선의 기울기는 $1$ 이다. 접점 $(1,\\ -2)$ 를 지나는 기울기 $1$ 인 직선을 구한다.","확인":"-3","스킬":"S5"},{"제목":"점 (k, -5) 를 대입해 k 구하기","힌트":"접선 $y=x-3$ 에 $(k,\\ -5)$ 를 대입하면 $k$ 는?","식":["$-5=k-3\\ \\Rightarrow\\ k=-2$"],"설명":"접선이 점 $(k,\\ -5)$ 를 지나므로 그 좌표를 접선의 식에 넣어도 성립한다.","확인":"-2","스킬":"S5"}]},"ns-0fe0c9b292fd":{"길":"k 로 묶어 항상 지나는 점을 원과 직선의 교점으로 본다","단계":[{"제목":"식을 k 에 대해 묶기","힌트":"$k$ 가 곱해진 항만 모아서 묶으면?","식":["$x^{2}+y^{2}-9+k(x+y-2)=0$"],"설명":"$k$ 가 곱해진 항 $kx+ky-2k$ 를 $k(x+y-2)$ 로 묶는다. 나머지 $x^{2}+y^{2}-9$ 는 $k$ 와 무관한 식이다.","확인":null,"스킬":"A3"},{"제목":"항상 지나는 점의 조건 세우기","힌트":"$k$ 가 어떤 값이어도 식이 성립하려면 묶은 두 부분은 각각 얼마여야 할까?","식":["$x^{2}+y^{2}-9=0$","$x+y-2=0$"],"설명":"$k$ 의 값에 관계없이 성립하려면 $k$ 의 계수와 나머지가 모두 $0$ 이어야 한다. 따라서 점 $\\mathrm{A}$, $\\mathrm{B}$ 는 원 $x^{2}+y^{2}=9$ 와 직선 $x+y=2$ 의 교점이다.","확인":null,"스킬":"A3"},{"제목":"현 AB 의 중점의 좌표 구하기","고비":true,"힌트":"현의 중점은 중심에서 그 현에 내린 수선의 발이다. 이 수선은 어떤 직선일까?","식":["$y=x$","$x+y=2,\\ y=x \\Rightarrow x=1,\\ y=1$","$(a,\\ b)=(1,\\ 1)$"],"설명":"원의 중심 $(0,\\ 0)$ 에서 직선 $x+y=2$ 에 내린 수선은 기울기가 $1$ 인 $y=x$ 이다. 현의 중점은 이 수선과 직선 $x+y=2$ 의 교점이므로 두 식을 연립해 구한다.","확인":null,"스킬":"S5"},{"제목":"2a+b 의 값 구하기","힌트":"$a=1,\\ b=1$ 을 $2a+b$ 에 대입하면?","식":["$2a+b=2\\times1+1=3$"],"설명":"구한 중점의 좌표를 $2a+b$ 에 대입한다.","확인":"3","스킬":"S5"}]},"ns-0fe48493f4ca":{"길":"접선의 길이와 직각삼각형의 닮음으로 현 QR 까지의 거리를 구한다","단계":[{"제목":"접선의 길이 구하기","힌트":"직각삼각형 $\\mathrm{OQP}$ 에서 $\\overline{\\mathrm{PQ}}$ 의 길이는?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{1^{2}+2^{2}}=\\sqrt{5}$","$\\overline{\\mathrm{PQ}}=\\sqrt{\\overline{\\mathrm{OP}}^{2}-\\overline{\\mathrm{OQ}}^{2}}=\\sqrt{5-1}=2$"],"설명":"접점에서 반지름과 접선은 수직이므로 삼각형 $\\mathrm{OQP}$ 는 $\\angle \\mathrm{OQP}=90^{\\circ}$ 인 직각삼각형이다. 피타고라스 정리로 접선의 길이를 구한다.","확인":null,"스킬":"S5"},{"제목":"중심에서 현 QR 까지의 거리 구하기","고비":true,"힌트":"$\\overline{\\mathrm{QR}}$ 의 중점 $\\mathrm{M}$ 은 $\\overline{\\mathrm{OP}}$ 위에 있다. $\\overline{\\mathrm{OQ}}^{2}$ 을 $\\overline{\\mathrm{OM}}$ 과 $\\overline{\\mathrm{OP}}$ 로 나타내면?","식":["$\\overline{\\mathrm{OQ}}^{2}=\\overline{\\mathrm{OM}}\\cdot\\overline{\\mathrm{OP}}$","$1=\\overline{\\mathrm{OM}}\\cdot\\sqrt{5}$","$\\overline{\\mathrm{OM}}=\\dfrac{1}{\\sqrt{5}}$"],"설명":"두 접점 $\\mathrm{Q}$, $\\mathrm{R}$ 은 직선 $\\mathrm{OP}$ 에 대칭이므로 중점 $\\mathrm{M}$ 은 $\\overline{\\mathrm{OP}}$ 위에 있고 $\\overline{\\mathrm{QR}}\\perp\\overline{\\mathrm{OP}}$ 이다. 직각삼각형 $\\mathrm{OQP}$ 에서 꼭짓점 $\\mathrm{Q}$ 에서 빗변에 내린 수선의 발이 $\\mathrm{M}$ 이므로 $\\overline{\\mathrm{OQ}}^{2}=\\overline{\\mathrm{OM}}\\cdot\\overline{\\mathrm{OP}}$ 이다.","확인":null,"스킬":"S5"},{"제목":"QM 과 PM 의 길이 구하기","힌트":"$\\overline{\\mathrm{QM}}$ 은 직각삼각형 $\\mathrm{OQM}$ 에서, $\\overline{\\mathrm{PM}}$ 은 $\\overline{\\mathrm{OP}}-\\overline{\\mathrm{OM}}$ 으로 구하면?","식":["$\\overline{\\mathrm{QM}}=\\sqrt{1-\\dfrac{1}{5}}=\\dfrac{2}{\\sqrt{5}}$","$\\overline{\\mathrm{PM}}=\\sqrt{5}-\\dfrac{1}{\\sqrt{5}}=\\dfrac{4}{\\sqrt{5}}$"],"설명":"$\\overline{\\mathrm{QR}}=2\\overline{\\mathrm{QM}}=\\dfrac{4}{\\sqrt{5}}$ 이다. $\\overline{\\mathrm{PM}}$ 은 $\\overline{\\mathrm{OP}}$ 에서 $\\overline{\\mathrm{OM}}$ 을 뺀 길이이다.","확인":null,"스킬":"S3"},{"제목":"삼각형 PQR 의 넓이 구하기","힌트":"밑변을 $\\overline{\\mathrm{QR}}$, 높이를 $\\overline{\\mathrm{PM}}$ 으로 보면 넓이는?","식":["$\\triangle \\mathrm{PQR}=\\dfrac{1}{2}\\cdot\\overline{\\mathrm{QR}}\\cdot\\overline{\\mathrm{PM}}$","$=\\dfrac{1}{2}\\cdot\\dfrac{4}{\\sqrt{5}}\\cdot\\dfrac{4}{\\sqrt{5}}=\\dfrac{8}{5}$"],"설명":"$\\overline{\\mathrm{PM}}\\perp\\overline{\\mathrm{QR}}$ 이므로 $\\overline{\\mathrm{PM}}$ 이 밑변 $\\overline{\\mathrm{QR}}$ 에 대한 높이이다.","확인":"8/5","스킬":"S8"}]},"ns-11d9afefa9a2":{"길":"접하면 중심에서 직선까지의 거리가 반지름과 같다","단계":[{"제목":"중심에서 직선까지의 거리 나타내기","힌트":"직선을 $ax+by+c=0$ 꼴로 바꾸고 원점과의 거리를 $k$ 로 나타내면?","식":["$2x-y+k=0$","$d=\\dfrac{|k|}{\\sqrt{2^{2}+(-1)^{2}}}=\\dfrac{|k|}{\\sqrt{5}}$"],"설명":"원 $x^{2}+y^{2}=4$ 의 중심은 원점이고 반지름은 $2$ 이다. 점과 직선 사이의 거리 공식을 쓴다.","확인":null,"스킬":"G2"},{"제목":"접할 조건으로 k 구하기","고비":true,"힌트":"접할 때 거리 $d$ 와 반지름 $2$ 의 관계는?","식":["$\\dfrac{|k|}{\\sqrt{5}}=2$","$|k|=2\\sqrt{5}$","$k=2\\sqrt{5}$"],"설명":"직선이 원에 접하면 중심과 직선 사이의 거리가 반지름과 같다. $k>0$ 이므로 절댓값 기호를 그대로 벗긴다.","확인":null,"스킬":"G2"}]},"ns-125343ccafed":{"길":"원 위의 점에서의 접선을 구해 주어진 점을 대입한다","단계":[{"제목":"접선의 방정식 구하기","고비":true,"힌트":"원 $x^{2}+y^{2}=r^{2}$ 위의 점 $(x_{1},\\ y_{1})$ 에서의 접선은 어떤 꼴일까?","식":["$x_{1}x+y_{1}y=r^{2}$","$3x+4y=25$"],"설명":"원 $x^{2}+y^{2}=r^{2}$ 위의 점 $(x_{1},\\ y_{1})$ 에서의 접선은 $x_{1}x+y_{1}y=r^{2}$ 이다. $(x_{1},\\ y_{1})=(3,\\ 4)$, $r^{2}=25$ 를 대입한다.","확인":null,"스킬":"S5"},{"제목":"접선 위의 점으로 a 구하기","힌트":"접선의 식에 $x=a,\\ y=\\dfrac{1}{4}$ 을 넣으면?","식":["$3a+4\\cdot\\dfrac{1}{4}=25$","$3a=24$","$a=8$"],"설명":"점 $\\left(a,\\ \\dfrac{1}{4}\\right)$ 이 접선 위에 있으므로 접선의 방정식을 만족한다.","확인":"8","스킬":"S5"}]},"ns-1314dcfa269c":{"길":"넓이가 최소인 원은 공통현이 지름이므로 현의 길이로 거리를 구한다","단계":[{"제목":"최소인 원의 반지름 구하기","힌트":"두 교점을 지나는 원 중 가장 작은 원은 두 교점을 잇는 현을 어떻게 하는 원일까?","식":["$\\pi r^{2}=9\\pi$","$r=3$","$\\overline{\\mathrm{AB}}=2r=6$"],"설명":"두 교점 $\\mathrm{A}$, $\\mathrm{B}$ 를 지나는 원은 $\\overline{\\mathrm{AB}}$ 를 현으로 가지므로 지름이 $\\overline{\\mathrm{AB}}$ 이상이다. 넓이가 최소인 원은 $\\overline{\\mathrm{AB}}$ 가 지름인 원이므로 반지름이 $3$ 이고 $\\overline{\\mathrm{AB}}=6$ 이다.","확인":"3","스킬":"S5"},{"제목":"원점에서 직선까지의 거리 구하기","고비":true,"힌트":"반지름 $\\sqrt{15}$, 반현 $3$ 으로 직각삼각형을 만들면 중심에서 현까지의 거리는?","식":["$d=\\sqrt{(\\sqrt{15})^{2}-3^{2}}$","$d=\\sqrt{6}$"],"설명":"중심 $\\mathrm{O}$ 에서 현 $\\mathrm{AB}$ 에 내린 수선은 현을 이등분한다. 반지름 $\\sqrt{15}$, 반현 $3$, 거리 $d$ 가 직각삼각형을 이루므로 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"},{"제목":"거리 공식으로 a²+b² 구하기","힌트":"원점과 직선 $ax+by-6=0$ 사이의 거리를 $a$, $b$ 로 나타내고 $\\sqrt{6}$ 과 같다고 하면?","식":["$\\dfrac{|-6|}{\\sqrt{a^{2}+b^{2}}}=\\sqrt{6}$","$\\sqrt{a^{2}+b^{2}}=\\sqrt{6}$","$a^{2}+b^{2}=6$"],"설명":"원점과 직선 사이의 거리가 $\\sqrt{6}$ 이어야 한다. 점과 직선 사이의 거리 공식으로 식을 세우고 양변을 제곱한다.","확인":"6","스킬":"S5"}]},"ns-14fa77c9a281":{"길":"x²+y² 을 원점까지 거리의 제곱으로 보고 영역의 꼭짓점을 살핀다","단계":[{"제목":"영역을 부등식으로 읽기","힌트":"그림의 어두운 부분은 $x$ 와 $y$ 가 각각 어떤 범위일까?","식":["$2\\le x\\le 4$","$-1\\le y\\le 1$"],"설명":"어두운 부분은 가로가 $2$ 에서 $4$, 세로가 $-1$ 에서 $1$ 인 정사각형 영역이다.","확인":null,"스킬":"S4"},{"제목":"x²+y² 의 최댓값 M 구하기","고비":true,"힌트":"$x^{2}+y^{2}$ 은 원점에서 점 $(x,\\ y)$ 까지 거리의 제곱이다. 원점에서 가장 먼 꼭짓점은?","식":["$x^{2}+y^{2}=\\overline{\\mathrm{OP}}^{2}$","$\\mathrm{P}(4,\\ 1)$ 또는 $\\mathrm{P}(4,\\ -1)$","$M=4^{2}+1^{2}=17$"],"설명":"점 $(x,\\ y)$ 를 $\\mathrm{P}$ 라 하면 $x^{2}+y^{2}$ 은 $\\overline{\\mathrm{OP}}^{2}$ 이다. 원점에서 가장 먼 점은 $x$ 와 $|y|$ 가 모두 가장 큰 꼭짓점이다.","확인":"17","스킬":"S4"},{"제목":"x²+y² 의 최솟값 m 구하기","힌트":"원점에서 영역까지 가장 가까운 점은 어디일까?","식":["$\\mathrm{P}(2,\\ 0)$","$m=2^{2}+0^{2}=4$"],"설명":"영역의 왼쪽 변 $x=2$ 위에서 $y=0$ 인 점이 원점에 가장 가깝다. 그 점에서 $x^{2}+y^{2}$ 이 최소이다.","확인":null,"스킬":"S4"},{"제목":"M+m 계산하기","힌트":"$M=17,\\ m=4$ 이면 $M+m$ 은?","식":["$M+m=17+4=21$"],"설명":"앞에서 구한 최댓값과 최솟값을 더한다.","확인":"21","스킬":"S4"}]},"ns-1509dabdb94f":{"길":"밑변 AB 는 고정이고 높이는 중심까지 거리에 반지름을 더해 최대로 한다","단계":[{"제목":"직선 AB 의 방정식과 길이 구하기","힌트":"두 점 $\\mathrm{A}(0,\\ -3)$, $\\mathrm{B}(4,\\ 0)$ 을 지나는 직선과 $\\overline{\\mathrm{AB}}$ 의 길이는?","식":["$y=\\dfrac{3}{4}x-3$","$3x-4y-12=0$","$\\overline{\\mathrm{AB}}=\\sqrt{4^{2}+3^{2}}=5$"],"설명":"기울기는 $\\dfrac{0-(-3)}{4-0}=\\dfrac{3}{4}$ 이고 $y$ 절편은 $-3$ 이다. $\\overline{\\mathrm{AB}}$ 가 삼각형의 밑변이 된다.","확인":"5","스킬":"S4"},{"제목":"중심에서 직선 AB 까지의 거리 구하기","힌트":"원의 중심 $(-2,\\ 2)$ 와 직선 $3x-4y-12=0$ 사이의 거리는?","식":["$d=\\dfrac{|3\\cdot(-2)-4\\cdot 2-12|}{\\sqrt{3^{2}+(-4)^{2}}}$","$d=\\dfrac{26}{5}$"],"설명":"원 $(x+2)^{2}+(y-2)^{2}=4$ 의 중심은 $(-2,\\ 2)$ 이고 반지름은 $2$ 이다. 점과 직선 사이의 거리 공식을 쓴다.","확인":"26/5","스킬":"S5"},{"제목":"높이의 최댓값 구하기","고비":true,"힌트":"원 위의 점 $\\mathrm{P}$ 에서 직선 $\\mathrm{AB}$ 까지의 거리가 가장 클 때 $\\mathrm{P}$ 는 중심을 기준으로 어느 쪽에 있을까?","식":["$h_{\\max}=d+r$","$h_{\\max}=\\dfrac{26}{5}+2=\\dfrac{36}{5}$"],"설명":"$d>r$ 이므로 원은 직선과 만나지 않는다. 중심에서 직선에 내린 수선이 원과 만나는 두 점 중 직선에서 먼 쪽의 점이 가장 멀고, 그 거리는 중심까지의 거리에 반지름을 더한 값이다.","확인":"36/5","스킬":"S5"},{"제목":"삼각형 ABP 의 넓이 최댓값 구하기","힌트":"밑변 $\\overline{\\mathrm{AB}}$ 와 최대 높이로 넓이를 구하면?","식":["$\\dfrac{1}{2}\\cdot 5\\cdot\\dfrac{36}{5}=18$"],"설명":"밑변이 고정되어 있으므로 높이가 최대일 때 넓이가 최대이다.","확인":"18","스킬":"S5"}]},"ns-15ea44af211d":{"길":"반지름 r 에 대한 이차방정식을 세워 근과 계수의 관계를 쓴다","단계":[{"제목":"원의 방정식을 반지름 r 로 나타내기","힌트":"점 $(3,\\ 2)$ 가 제1사분면에 있을 때 두 축에 접하는 원의 중심은 어디일까?","식":["$(x-r)^{2}+(y-r)^{2}=r^{2}$"],"설명":"점 $(3,\\ 2)$ 가 제1사분면에 있으므로 이 점을 지나고 두 축에 접하는 원은 제1사분면에 놓인다. 반지름이 $r$ 이면 중심은 $(r,\\ r)$ 이다.","확인":null,"스킬":"S5"},{"제목":"점을 대입해 r 의 이차방정식 만들기","힌트":"원의 방정식에 $x=3,\\ y=2$ 를 대입하고 정리하면?","식":["$(3-r)^{2}+(2-r)^{2}=r^{2}$","$r^{2}-10r+13=0$"],"설명":"전개하면 $13-10r+2r^{2}=r^{2}$ 이다. 원이 두 개이므로 이 이차방정식의 두 근이 두 원의 반지름이다.","확인":null,"스킬":"A2"},{"제목":"근과 계수의 관계로 제곱의 합 구하기","고비":true,"힌트":"두 근을 $r_{1},\\ r_{2}$ 라 할 때 $r_{1}^{2}+r_{2}^{2}$ 을 합과 곱으로 나타내면?","식":["$r_{1}+r_{2}=10,\\ r_{1}r_{2}=13$","$r_{1}^{2}+r_{2}^{2}=(r_{1}+r_{2})^{2}-2r_{1}r_{2}$","$=100-26=74$"],"설명":"두 근을 직접 구하지 않아도 근과 계수의 관계로 합과 곱을 알 수 있다. 제곱의 합은 합의 제곱에서 곱의 두 배를 빼서 구한다.","확인":"74","스킬":"A2"},{"제목":"두 원의 넓이의 합 구하기","힌트":"넓이의 합 $\\pi r_{1}^{2}+\\pi r_{2}^{2}$ 에 앞의 값을 넣으면?","식":["$\\pi r_{1}^{2}+\\pi r_{2}^{2}=\\pi(r_{1}^{2}+r_{2}^{2})=74\\pi$"],"설명":"원의 넓이는 $\\pi r^{2}$ 이므로 두 반지름의 제곱의 합에 $\\pi$ 를 곱한다.","확인":null,"스킬":"A2"}]},"ns-16195cc26ce8":{"길":"원 위의 점과 직선 사이 거리의 최댓값은 중심까지 거리에 반지름을 더한 값이다","단계":[{"제목":"직선 AB 의 방정식 구하기","힌트":"두 점 $\\mathrm{A}(-1,\\ -7)$, $\\mathrm{B}(7,\\ 1)$ 을 지나는 직선의 기울기와 식은?","식":["$\\dfrac{1-(-7)}{7-(-1)}=1$","$y=x-6$"],"설명":"기울기가 $1$ 이고 점 $\\mathrm{B}(7,\\ 1)$ 을 지나므로 $y-1=x-7$ 이다. 정리하면 $x-y-6=0$ 이다.","확인":null,"스킬":"G9"},{"제목":"중심에서 직선 AB 까지의 거리 구하기","힌트":"원의 중심 $(0,\\ 0)$ 과 직선 $x-y-6=0$ 사이의 거리는?","식":["$d=\\dfrac{|0-0-6|}{\\sqrt{1^{2}+(-1)^{2}}}$","$d=\\dfrac{6}{\\sqrt{2}}=3\\sqrt{2}$"],"설명":"원 $x^{2}+y^{2}=5^{2}$ 의 중심은 원점이고 반지름은 $5$ 이다. 점과 직선 사이의 거리 공식을 쓴다.","확인":null,"스킬":"S5"},{"제목":"거리의 최댓값 구하기","고비":true,"힌트":"원 위의 점에서 직선까지의 거리가 가장 클 때는 중심까지의 거리에 무엇을 더한 값일까?","식":["$d+r=3\\sqrt{2}+5$"],"설명":"중심에서 직선에 내린 수선의 연장선이 원과 만나는 점 중 직선에서 먼 쪽의 점이 가장 멀다. 그 거리는 중심까지의 거리 $d$ 에 반지름 $r$ 을 더한 값이다.","확인":null,"스킬":"S5"}]},"ns-173b251b97b7":{"길":"원주각 45° 에서 중심각 90° 를 읽어 B 의 좌표를 문자로 놓는다","단계":[{"제목":"중심각으로 점 B 의 좌표 놓기","고비":true,"힌트":"호 $\\mathrm{QB}$ 에 대한 원주각이 $45^{\\circ}$ 이면 중심각 $\\angle \\mathrm{QOB}$ 는 얼마일까?","식":["$\\mathrm{P}(0,\\ b),\\ \\mathrm{Q}(a,\\ b),\\ r^{2}=a^{2}+b^{2}$","$\\angle \\mathrm{QOB}=2\\angle \\mathrm{BAQ}=90^{\\circ}$","$\\mathrm{B}(b,\\ -a)$"],"설명":"한 호에 대한 중심각은 원주각의 $2$ 배이므로 $\\angle \\mathrm{QOB}=90^{\\circ}$ 이다. $\\overline{\\mathrm{OQ}}=\\overline{\\mathrm{OB}}$ 이고 $\\mathrm{B}$ 는 제$4$사분면에 있으므로 $\\mathrm{B}$ 는 $\\mathrm{Q}$ 를 시계 방향으로 $90^{\\circ}$ 돌린 점이다.","확인":null,"스킬":"S5"},{"제목":"비 2:5 로 점 A 의 좌표 구하기","힌트":"$\\mathrm{P}$ 는 $\\overline{\\mathrm{AB}}$ 를 $2:5$ 로 나누는 점이다. 내분점의 좌표 공식으로 $\\mathrm{A}$ 의 좌표는?","식":["$0=\\dfrac{5x_{\\mathrm{A}}+2b}{7},\\ \\ b=\\dfrac{5y_{\\mathrm{A}}-2a}{7}$","$\\mathrm{A}\\left(-\\dfrac{2b}{5},\\ \\dfrac{7b+2a}{5}\\right)$"],"설명":"$\\mathrm{A}$ 는 제$2$사분면, $\\mathrm{B}$ 는 제$4$사분면에 있으므로 $y$ 축 위의 점 $\\mathrm{P}$ 는 두 점 사이에 있다. $\\overline{\\mathrm{AP}}:\\overline{\\mathrm{PB}}=2:5$ 이므로 내분점의 좌표 공식에서 $\\mathrm{A}$ 의 좌표를 거꾸로 구한다.","확인":null,"스킬":"S4"},{"제목":"직선이 지나는 점으로 식 세우기","힌트":"직선 $l$ 은 점 $(1,\\ 0)$ 을 지난다. $\\mathrm{P}$ 에서 $(1,\\ 0)$ 으로의 기울기와 $\\mathrm{P}$ 에서 $\\mathrm{B}$ 로의 기울기를 같게 놓으면?","식":["$\\dfrac{-a-b}{b-0}=\\dfrac{0-b}{1-0}$","$a+b=b^{2}$"],"설명":"직선 $l$ 은 $y=m(x-1)$ 이므로 점 $(1,\\ 0)$ 을 지나고 $\\mathrm{P}$ 와 $\\mathrm{B}$ 도 지난다. 어느 두 점을 잡아도 기울기가 같다.","확인":null,"스킬":"S4"},{"제목":"A 가 원 위에 있을 조건으로 a, b 의 관계 구하기","힌트":"점 $\\mathrm{A}$ 의 좌표를 $x^{2}+y^{2}=a^{2}+b^{2}$ 에 넣고 정리하면?","식":["$\\dfrac{4b^{2}}{25}+\\dfrac{(7b+2a)^{2}}{25}=a^{2}+b^{2}\\ \\Rightarrow\\ 28b^{2}+28ab-21a^{2}=0$","$4b^{2}+4ab-3a^{2}=(2b-a)(2b+3a)=0$","$a=2b$"],"설명":"$\\mathrm{A}$ 는 원 위의 점이므로 원점까지 거리의 제곱이 $r^{2}=a^{2}+b^{2}$ 이다. $a>0$, $b>0$ 이므로 $2b+3a>0$ 이고, 따라서 $2b-a=0$ 이다.","확인":null,"스킬":"S5"},{"제목":"b 의 값 구하기","힌트":"$a=2b$ 를 $a+b=b^{2}$ 에 넣으면 $b$ 는?","식":["$2b+b=b^{2}$","$b^{2}=3b$","$b=3,\\ a=6$"],"설명":"$b>0$ 이므로 양변을 $b$ 로 나눌 수 있다. $b$ 를 구하면 $a=2b$ 에서 $a$ 도 정해진다.","확인":"3","스킬":"A10"},{"제목":"r² 의 값 구하기","힌트":"$r^{2}=a^{2}+b^{2}$ 에 구한 값을 넣으면?","식":["$r^{2}=6^{2}+3^{2}=45$"],"설명":"점 $\\mathrm{Q}(a,\\ b)$ 가 원 위의 점이므로 $r^{2}=a^{2}+b^{2}$ 이다.","확인":"45","스킬":"S5"}]},"ns-1795e024a3ab":{"길":"굴린 원의 중심은 접선과 평행한 직선 위에 있다","단계":[{"제목":"원 O 의 반지름 제곱 구하기","힌트":"접점 $\\mathrm{A}$ 가 원 위의 점이므로 $r^{2}$ 은?","식":["$r^{2}=\\overline{\\mathrm{OA}}^{2}=1^{2}+(-2)^{2}=5$"],"설명":"원 $\\mathrm{O}$ 의 중심은 원점이다. 굴려도 원의 크기는 변하지 않으므로 원 $\\mathrm{O}_{1}$ 의 $r^{2}$ 도 같은 값이다.","확인":"5","스킬":"S5"},{"제목":"접선 l 의 기울기 구하기","힌트":"점 $\\mathrm{A}(1,\\ -2)$ 를 지나는 직선을 $y=m(x-1)-2$ 로 놓고 원점과의 거리를 $\\sqrt{5}$ 와 같게 놓으면 $m$ 은?","식":["$mx-y-m-2=0$","$\\dfrac{|-m-2|}{\\sqrt{m^{2}+1}}=\\sqrt{5}$","$4m^{2}-4m+1=0,\\ m=\\dfrac{1}{2}$"],"설명":"접선은 중심에서 거리가 반지름과 같은 직선이므로 거리 공식을 쓴다. 양변을 제곱하면 $(m+2)^{2}=5(m^{2}+1)$ 이고 정리하면 $(2m-1)^{2}=0$ 이다.","확인":"1/2","스킬":"G9"},{"제목":"굴린 원의 중심이 놓이는 직선 찾기","고비":true,"힌트":"원이 직선 $l$ 에 접한 채 굴러도 반지름은 같다. 중심은 $l$ 과 어떤 관계인 직선 위에 있을까?","식":["$\\dfrac{b}{a}=\\dfrac{1}{2}$","$\\dfrac{a}{b}=2$"],"설명":"중심에서 $l$ 까지의 거리가 항상 $\\sqrt{5}$ 이므로 중심은 $l$ 과 평행한 직선 위를 움직인다. 이 직선은 원점도 지나므로 $y=\\dfrac{1}{2}x$ 이고, 중심 $(a,\\ b)$ 를 대입하면 $\\dfrac{b}{a}=\\dfrac{1}{2}$ 이다.","확인":"2","스킬":"S5"},{"제목":"r²−a/b 계산하기","힌트":"$r^{2}=5,\\ \\dfrac{a}{b}=2$ 를 대입하면?","식":["$r^{2}-\\dfrac{a}{b}=5-2=3$"],"설명":"앞에서 구한 두 값을 식에 대입한다.","확인":"3","스킬":"S5"}]},"ns-1af1c439a292":{"길":"두 가게까지 거리의 비가 일정한 점의 자취는 원이다","단계":[{"제목":"배송료가 같을 조건 세우기","힌트":"ⓐ제품 한 상자의 $1\\mathrm{km}$ 당 배송료를 $c$ 라 하고 두 제품의 배송료를 거리로 나타내면?","식":["$10\\cdot c\\cdot\\overline{\\mathrm{PA}}=20\\cdot 1.5c\\cdot\\overline{\\mathrm{PB}}$","$\\overline{\\mathrm{PA}}=3\\overline{\\mathrm{PB}}$"],"설명":"ⓐ제품 가게를 $\\mathrm{A}$, ⓑ제품 가게를 $\\mathrm{B}$, 배송 지점을 $\\mathrm{P}$ 라 한다. 배송료는 상자 수와 거리에 비례하므로 양쪽 배송료가 같다는 식에서 $c$ 가 약분된다.","확인":null,"스킬":"C7"},{"제목":"좌표로 옮겨 식 정리하기","고비":true,"힌트":"$\\mathrm{A}(-4,\\ 0)$, $\\mathrm{B}(4,\\ 0)$, $\\mathrm{P}(x,\\ y)$ 로 놓고 $\\overline{\\mathrm{PA}}^{2}=9\\overline{\\mathrm{PB}}^{2}$ 을 전개하면?","식":["$(x+4)^{2}+y^{2}=9\\{(x-4)^{2}+y^{2}\\}$","$x^{2}+y^{2}-10x+16=0$"],"설명":"두 가게 사이의 거리가 $8$ 이므로 중점을 원점으로 잡아 좌표를 놓는다. 양변을 제곱해 근호를 없애고 정리하면 $8x^{2}+8y^{2}-80x+128=0$ 이고, 양변을 $8$ 로 나눈다.","확인":null,"스킬":"S4"},{"제목":"원의 중심과 반지름 읽기","힌트":"$x$ 항을 완전제곱식으로 묶으면 반지름은?","식":["$(x-5)^{2}+y^{2}=9$","$r=3$"],"설명":"$x^{2}-10x$ 에 $25$ 를 더해 완전제곱식으로 만든다. 배송료가 같은 지점의 모임은 중심이 $(5,\\ 0)$ 이고 반지름이 $3$ 인 원이다.","확인":"3","스킬":"A6"},{"제목":"도형의 길이 구하기","힌트":"반지름이 $3$ 인 원의 둘레는?","식":["$2\\pi\\cdot 3=6\\pi$"],"설명":"배송료가 같아지는 모든 지점은 원 전체를 이루므로 도형의 길이는 원의 둘레이다.","확인":null,"스킬":"S5"}]},"ns-1d6921705ea8":{"길":"영역의 두 부등식에 보기의 점을 하나씩 대입한다","단계":[{"제목":"영역 S 의 조건 정리하기","힌트":"두 부등식을 $a$, $b$ 에 대한 조건으로 바꾸고 둘째 식은 절댓값으로 나타내면?","식":["$a^{2}+b^{2}<4$","$a^{2}-b^{2}>0\\ \\Rightarrow\\ |a|>|b|$"],"설명":"점 $(a,\\ b)$ 가 $S$ 에 있으므로 두 부등식에 $x=a$, $y=b$ 를 넣은 식이 성립한다. 각 보기의 점은 $x^{2}+y^{2}<4$, $x^{2}-y^{2}>0$ 에 넣어 확인한다.","확인":null,"스킬":"G6"},{"제목":"ㄱ 의 점 검토하기","힌트":"점 $\\left(\\dfrac{a}{2},\\ \\dfrac{b}{2}\\right)$ 의 $x^{2}+y^{2}$ 과 $x^{2}-y^{2}$ 은 $a$, $b$ 로 어떻게 나타날까?","식":["$\\dfrac{a^{2}}{4}+\\dfrac{b^{2}}{4}=\\dfrac{a^{2}+b^{2}}{4}<1<4$","$\\dfrac{a^{2}}{4}-\\dfrac{b^{2}}{4}=\\dfrac{a^{2}-b^{2}}{4}>0$"],"설명":"두 부등식을 모두 만족하므로 ㄱ 의 점은 영역 $S$ 에 있다. 따라서 ㄱ 은 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 의 점 검토하기","고비":true,"힌트":"점 $(b,\\ a)$ 에서는 $x$ 와 $y$ 의 역할이 바뀐다. $x^{2}-y^{2}$ 의 부호는?","식":["$x^{2}-y^{2}=b^{2}-a^{2}<0$"],"설명":"$a^{2}-b^{2}>0$ 이므로 $b^{2}-a^{2}<0$ 이다. 둘째 부등식 $x^{2}-y^{2}>0$ 을 만족하지 않으므로 ㄴ 은 거짓이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 의 점 검토와 결론","힌트":"점 $(-a,\\ -b)$ 를 두 부등식에 넣으면 $a$, $b$ 의 조건과 어떻게 달라질까?","식":["$(-a)^{2}+(-b)^{2}=a^{2}+b^{2}<4$","$(-a)^{2}-(-b)^{2}=a^{2}-b^{2}>0$"],"설명":"제곱은 부호가 바뀌어도 같으므로 두 조건이 그대로 성립해 ㄷ 은 참이다. 따라서 영역 $S$ 에 있는 점은 ㄱ, ㄷ 이다.","확인":null,"스킬":"C3"}]},"ns-1dc341ba9fa0":{"길":"두 접선이 수직이면 중심·접점·A 가 정사각형을 이룬다","단계":[{"제목":"사각형 ABOC 의 모양 알아보기","고비":true,"힌트":"접점에서 접선과 반지름이 이루는 각과 두 접선 사이의 각으로 사각형 $\\mathrm{ABOC}$ 의 각을 보면?","식":["$\\angle \\mathrm{ABO}=\\angle \\mathrm{ACO}=\\angle \\mathrm{BAC}=90^{\\circ}$","$\\overline{\\mathrm{OB}}=\\overline{\\mathrm{OC}}=r$","$\\overline{\\mathrm{AO}}=r\\sqrt{2}$"],"설명":"접점에서 접선과 반지름은 수직이고 두 접선도 서로 수직이므로 사각형 $\\mathrm{ABOC}$ 는 네 각이 모두 직각이다. 이웃한 두 변 $\\overline{\\mathrm{OB}}$, $\\overline{\\mathrm{OC}}$ 가 반지름 $r$ 로 같으므로 한 변이 $r$ 인 정사각형이고, 대각선 $\\overline{\\mathrm{AO}}$ 는 $r\\sqrt{2}$ 이다.","확인":null,"스킬":"S5"},{"제목":"중심 O 와 점 A 사이 거리의 제곱 구하기","힌트":"$\\mathrm{O}(1,\\ 2)$ 와 $\\mathrm{A}(5,\\ 4)$ 의 가로 차와 세로 차의 제곱을 더하면?","식":["$\\overline{\\mathrm{AO}}^{2}=(5-1)^{2}+(4-2)^{2}=20$"],"설명":"원의 중심은 $(1,\\ 2)$ 이다. 두 점 사이의 거리 공식으로 $\\overline{\\mathrm{AO}}^{2}$ 을 구한다.","확인":"20","스킬":"S4"},{"제목":"r 의 값 구하기","힌트":"$\\overline{\\mathrm{AO}}=r\\sqrt{2}$ 의 양변을 제곱하면 $r^{2}$ 은?","식":["$(r\\sqrt{2})^{2}=20$","$r^{2}=10$","$r=\\sqrt{10}$"],"설명":"$r>0$ 이므로 양의 제곱근을 택한다.","확인":null,"스킬":"S5"}]},"ns-1dd531a86d69":{"길":"완전제곱으로 중심과 반지름을 읽고 보기를 하나씩 확인한다","단계":[{"제목":"완전제곱식으로 중심과 반지름 읽기","힌트":"$x$ 항과 $y$ 항을 각각 완전제곱식으로 묶으면?","식":["$(x-k)^{2}+(y-3k)^{2}=10k^{2}+2k+1$"],"설명":"$x^{2}-2kx$ 에 $k^{2}$ 을, $y^{2}-6ky$ 에 $9k^{2}$ 을 더해 완전제곱식으로 만들고 같은 값을 우변에도 더한다. 중심은 $(k,\\ 3k)$ 이다.","확인":null,"스킬":"A6"},{"제목":"ㄱ, ㄴ 검토하기","힌트":"ㄱ 은 점 $(-1,\\ 0)$ 을 식에 넣고, ㄴ 은 중심의 좌표를 직선의 식에 넣으면?","식":["$(-1-k)^{2}+(0-3k)^{2}=10k^{2}+2k+1$","$y=3k=3\\cdot x$"],"설명":"ㄱ 은 좌변이 $k^{2}+2k+1+9k^{2}=10k^{2}+2k+1$ 이 되어 우변과 같으므로 참이다. ㄴ 은 중심의 $y$ 좌표가 $x$ 좌표의 $3$ 배이므로 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 의 x축과의 교점 구하기","고비":true,"힌트":"$y=0$ 을 대입해 $x$ 에 대한 식을 풀면 교점의 $x$ 좌표는?","식":["$(x-k)^{2}=k^{2}+2k+1=(k+1)^{2}$","$x=2k+1$ 또는 $x=-1$"],"설명":"$k>-\\dfrac{1}{2}$ 이면 $2k+1>0$ 이므로 두 값이 서로 다르다. 따라서 원은 $x$ 축과 서로 다른 두 점에서 만나므로 ㄷ 은 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄹ 검토와 결론","힌트":"두 교점의 $x$ 좌표 $2k+1$ 과 $-1$ 의 부호는 서로 같을까 다를까?","식":["$2k+1>0>-1$"],"설명":"원은 $x$ 축과 $x$ 좌표의 부호가 서로 다른 두 점에서 만난다. 위쪽 호와 아래쪽 호가 각각 $y$ 축을 가로지르므로 네 사분면을 모두 지나 ㄹ 도 참이다. 따라서 ㄱ, ㄴ, ㄷ, ㄹ 이 모두 옳다.","확인":null,"스킬":"C3"}]},"ns-1f9594757d2d":{"길":"세 반원을 각각 원으로 보고 접점의 y좌표를 따로 구한다","단계":[{"제목":"세 반원의 방정식 읽기","힌트":"그림에서 각 반원의 중심과 반지름, 위쪽인지 아래쪽인지를 읽으면?","식":["$x^{2}+y^{2}=4\\ \\ (y\\ge 0)$","$(x+1)^{2}+y^{2}=1\\ \\ (y\\ge 0)$","$(x-1)^{2}+y^{2}=1\\ \\ (y\\le 0)$"],"설명":"큰 반원은 원점이 중심이고 반지름이 $2$ 인 원의 위쪽 절반이다. 작은 두 반원은 지름이 각각 $-2$ 에서 $0$, $0$ 에서 $2$ 인 구간이므로 중심이 $(-1,\\ 0)$, $(1,\\ 0)$ 이고 반지름이 $1$ 이다.","확인":null,"스킬":"S5"},{"제목":"큰 반원의 접점 구하기","힌트":"원 $x^{2}+y^{2}=4$ 위의 점 $(x_{0},\\ y_{0})$ 에서의 접선이 $(4,\\ 0)$ 을 지나게 하면?","식":["$x_{0}x+y_{0}y=4$","$4x_{0}=4,\\ x_{0}=1$","$y_{0}=\\sqrt{3}$"],"설명":"접선의 방정식에 $(4,\\ 0)$ 을 넣어 $x_{0}$ 를 구한다. $y_{0}^{2}=4-1=3$ 이고 위쪽 반원이므로 $y_{0}>0$ 이다.","확인":null,"스킬":"S5"},{"제목":"왼쪽 작은 반원의 접점 구하기","고비":true,"힌트":"중심이 $(-1,\\ 0)$ 인 원 위의 점 $(x_{0},\\ y_{0})$ 에서의 접선의 식에 $(4,\\ 0)$ 을 넣으면 $x_{0}$ 는?","식":["$(x_{0}+1)(x+1)+y_{0}y=1$","$5(x_{0}+1)=1,\\ x_{0}=-\\dfrac{4}{5}$","$y_{0}=\\dfrac{2\\sqrt{6}}{5}$"],"설명":"원 $(x+1)^{2}+y^{2}=1$ 을 $x$ 축 방향으로 $1$ 만큼 옮기면 원점이 중심인 원이므로 접선의 식은 $(x_{0}+1)(x+1)+y_{0}y=1$ 이다. $y_{0}^{2}=1-\\left(\\dfrac{1}{5}\\right)^{2}=\\dfrac{24}{25}$ 이고 위쪽 반원이므로 $y_{0}>0$ 이다.","확인":"-4/5","스킬":"S5"},{"제목":"오른쪽 아래 반원의 접점 구하기","힌트":"중심이 $(1,\\ 0)$ 인 원에서도 같은 방법으로 접점의 $x$ 좌표를 구하면?","식":["$(x_{0}-1)(x-1)+y_{0}y=1$","$3(x_{0}-1)=1,\\ x_{0}=\\dfrac{4}{3}$","$y_{0}=-\\dfrac{2\\sqrt{2}}{3}$"],"설명":"$(4,\\ 0)$ 을 대입하면 $3(x_{0}-1)=1$ 이다. $y_{0}^{2}=1-\\left(\\dfrac{1}{3}\\right)^{2}=\\dfrac{8}{9}$ 이고 아래쪽 반원이므로 $y_{0}<0$ 이다.","확인":"4/3","스킬":"S5"},{"제목":"접점의 y좌표의 곱 구하기","힌트":"세 접점의 $y$ 좌표 $\\sqrt{3},\\ \\dfrac{2\\sqrt{6}}{5},\\ -\\dfrac{2\\sqrt{2}}{3}$ 를 곱하면?","식":["$\\sqrt{3}\\cdot\\dfrac{2\\sqrt{6}}{5}\\cdot\\left(-\\dfrac{2\\sqrt{2}}{3}\\right)=-\\dfrac{8}{5}$"],"설명":"$\\sqrt{3}\\cdot\\sqrt{6}\\cdot\\sqrt{2}=6$ 이므로 곱은 $-\\dfrac{4\\cdot 6}{15}=-\\dfrac{8}{5}$ 이다. 반원이므로 각 원에서 그림 위에 있는 접점은 한 개씩이다.","확인":"-8/5","스킬":"S5"}]},"ns-279ae955ef9a":{"길":"정점이 원 안에 있으므로 중심을 지날 때 최대, 그 현에 수직일 때 최소","단계":[{"제목":"직선이 항상 지나는 점 찾기","힌트":"$a$ 가 들어 있는 항을 묶으면 직선은 어느 점을 지날까?","식":["$y=2a(x+3)+3$","$(-3,\\ 3)$"],"설명":"$a$ 의 값에 관계없이 $x+3=0$ 이면 $y=3$ 이 된다. 따라서 직선은 점 $(-3,\\ 3)$ 을 지나고 기울기가 $2a$ 이다.","확인":null,"스킬":"G3"},{"제목":"정점이 원 안에 있는지 확인하기","힌트":"정점과 원점 사이 거리의 제곱을 $r^{2}=24$ 와 비교하면?","식":["$(-3)^{2}+3^{2}=18<24$"],"설명":"정점이 원의 내부에 있으므로 어떤 기울기의 직선도 원과 서로 다른 두 점에서 만난다.","확인":"18","스킬":"S5"},{"제목":"현의 길이의 최댓값 M 구하기","힌트":"정점을 지나는 현 중 가장 긴 것은 어떤 현일까?","식":["$M=2\\sqrt{24}=4\\sqrt{6}$"],"설명":"정점과 원점을 잇는 직선의 기울기는 $-1$ 이므로 $a=-\\dfrac{1}{2}$ 일 때 직선이 원점을 지난다. 이때 현은 지름이므로 길이가 최대이다.","확인":null,"스킬":"S5"},{"제목":"현의 길이의 최솟값 m 구하기","고비":true,"힌트":"정점을 $\\mathrm{H}$ 라 할 때 현이 중심에서 가장 멀어지는 경우, 현과 $\\overline{\\mathrm{OH}}$ 는 어떤 관계일까?","식":["$\\overline{\\mathrm{OH}}=3\\sqrt{2}$","$\\overline{\\mathrm{P}'\\mathrm{H}}=\\sqrt{24-18}=\\sqrt{6}$","$m=2\\sqrt{6}$"],"설명":"중심에서 현까지의 거리가 클수록 현은 짧다. 정점 $\\mathrm{H}(-3,\\ 3)$ 을 지나는 현 중 중심에서 가장 먼 것은 $\\overline{\\mathrm{OH}}$ 에 수직인 현 $\\mathrm{P}'\\mathrm{Q}'$ 이다. 직각삼각형 $\\mathrm{OHP}'$ 에서 피타고라스 정리로 반현의 길이를 구하고 $2$ 배 한다.","확인":null,"스킬":"S5"},{"제목":"M+m 계산하기","힌트":"$M=4\\sqrt{6},\\ m=2\\sqrt{6}$ 을 더하면?","식":["$M+m=4\\sqrt{6}+2\\sqrt{6}=6\\sqrt{6}$"],"설명":"근호 안의 수가 같으므로 계수끼리 더한다.","확인":null,"스킬":"S5"}]},"ns-285b007f6b56":{"길":"AP=x, BP=y 로 놓고 직선과 원이 접할 때 2x+3y 가 최대이다","단계":[{"제목":"AP, BP 사이의 관계식 세우기","힌트":"지름에 대한 원주각은 얼마이므로 $\\overline{\\mathrm{AP}}$, $\\overline{\\mathrm{BP}}$, $\\overline{\\mathrm{AB}}$ 사이에 어떤 관계가 있을까?","식":["$\\angle \\mathrm{APB}=90^{\\circ}$","$x^{2}+y^{2}=8^{2}=64$"],"설명":"$\\overline{\\mathrm{AP}}=x$, $\\overline{\\mathrm{BP}}=y$ 라 한다. 지름 $\\overline{\\mathrm{AB}}$ 에 대한 원주각은 $90^{\\circ}$ 이므로 삼각형 $\\mathrm{APB}$ 에 피타고라스 정리를 쓴다. 점 $\\mathrm{P}$ 는 반원 위에 있으므로 $x\\ge 0$, $y\\ge 0$ 이다.","확인":"64","스킬":"S5"},{"제목":"접할 때 최대가 됨을 이용해 k 구하기","고비":true,"힌트":"$2x+3y=k$ 로 놓으면 $k$ 가 최대일 때 이 직선과 원 $x^{2}+y^{2}=64$ 는 어떤 위치 관계일까?","식":["$\\dfrac{|k|}{\\sqrt{2^{2}+3^{2}}}=8$","$|k|=8\\sqrt{13}$"],"설명":"$(x,\\ y)$ 는 원 $x^{2}+y^{2}=64$ 위의 점이고 직선 $2x+3y=k$ 가 이 원과 만나야 한다. $k$ 가 가장 클 때는 직선이 원에 접할 때이므로 원의 중심과 직선 사이의 거리가 반지름 $8$ 과 같다.","확인":null,"스킬":"G2"},{"제목":"접점의 위치를 확인하고 최댓값 정하기","힌트":"접점의 $x$, $y$ 좌표가 모두 $0$ 이상이어야 반원 위의 점이다. 접점의 좌표는?","식":["$(x,\\ y)=\\left(\\dfrac{16}{\\sqrt{13}},\\ \\dfrac{24}{\\sqrt{13}}\\right)$","$k_{\\max}=8\\sqrt{13}$"],"설명":"접점은 원점에서 직선에 내린 수선의 발이므로 $(2t,\\ 3t)$ 꼴이고, $13t=k$ 에서 $t=\\dfrac{8}{\\sqrt{13}}$ 이다. 두 좌표가 모두 양수이므로 접점이 반원 위에 있어 이 값이 실제로 가능하다.","확인":null,"스킬":"S5"}]},"ns-295c9c5df4f1":{"길":"접선 조건으로 a, b 의 관계를 세우고 근과 계수로 QR 에 적용한다","단계":[{"제목":"직선 PQ 의 방정식 구하기","힌트":"$\\mathrm{P}(a,\\ a^{2})$, $\\mathrm{Q}(b,\\ b^{2})$ 을 지나는 직선의 기울기와 식은?","식":["$\\dfrac{a^{2}-b^{2}}{a-b}=a+b$","$y=(a+b)(x-a)+a^{2}$","$(a+b)x-y-ab=0$"],"설명":"기울기는 $\\dfrac{a^{2}-b^{2}}{a-b}=a+b$ 이다. 점 $\\mathrm{P}$ 를 지나므로 $y-a^{2}=(a+b)(x-a)$ 이고, 정리하면 $y=(a+b)x-ab$ 이다.","확인":null,"스킬":"S4"},{"제목":"접선 조건으로 상수 구하기","힌트":"직선 $\\mathrm{PQ}$ 가 원 $C_{2}$ 에 접하므로 중심 $(0,\\ 2)$ 와의 거리는 반지름과 같다. 이 식을 정리하면 $(a-b)^{2}-a^{2}b^{2}$ 은?","식":["$\\dfrac{|-2-ab|}{\\sqrt{(a+b)^{2}+1}}=1$","$(2+ab)^{2}=(a+b)^{2}+1$","$(a-b)^{2}-a^{2}b^{2}=3$"],"설명":"$4+4ab+a^{2}b^{2}=a^{2}+2ab+b^{2}+1$ 에서 $a^{2}-2ab+b^{2}-a^{2}b^{2}=3$ 이다. 점 $\\mathrm{P}$, $\\mathrm{Q}$ 의 위치에 관계없이 접선 조건만 쓰므로 값은 상수 $3$ 이다.","확인":"3","스킬":"G2"},{"제목":"b, c 가 근인 이차방정식 세우기","고비":true,"힌트":"점 $\\mathrm{P}$ 에서 그은 다른 접선과 $C_{1}$ 의 교점이 $\\mathrm{R}$ 이다. $\\mathrm{P}$, $\\mathrm{R}$ 에도 같은 관계가 성립한다면 $b$, $c$ 는 어떤 방정식의 근일까?","식":["$(a-c)^{2}-a^{2}c^{2}=3$","$(a-x)^{2}-a^{2}x^{2}-3=0$","$(1-a^{2})x^{2}-2ax+a^{2}-3=0$"],"설명":"직선 $\\mathrm{PR}$ 도 원 $C_{2}$ 의 접선이므로 $\\mathrm{R}$ 의 $x$ 좌표 $c$ 에 대해서도 같은 계산이 성립한다. 따라서 $x=b$, $x=c$ 가 모두 이 방정식을 만족하고, $\\mathrm{Q}\\ne\\mathrm{R}$ 이므로 $b$, $c$ 는 서로 다른 두 근이다.","확인":null,"스킬":"A2"},{"제목":"근과 계수의 관계로 b+c, bc 구하기","힌트":"이차방정식의 두 근의 합과 곱은 계수로 어떻게 나타날까?","식":["$b+c=\\dfrac{2a}{1-a^{2}}$","$bc=\\dfrac{a^{2}-3}{1-a^{2}}$"],"설명":"$(1-a^{2})x^{2}-2ax+a^{2}-3=0$ 에서 두 근의 합은 $-\\dfrac{-2a}{1-a^{2}}$, 곱은 $\\dfrac{a^{2}-3}{1-a^{2}}$ 이다.","확인":null,"스킬":"A2"},{"제목":"직선 QR 과 중심 사이의 거리 구하기","힌트":"직선 $\\mathrm{QR}$ 도 직선 $\\mathrm{PQ}$ 와 같은 꼴로 쓸 수 있다. 중심 $(0,\\ 2)$ 와의 거리에 앞의 합과 곱을 넣으면?","식":["$(b+c)x-y-bc=0$","$-2-bc=\\dfrac{a^{2}+1}{1-a^{2}},\\ \\ \\sqrt{(b+c)^{2}+1}=\\dfrac{a^{2}+1}{|1-a^{2}|}$","$d=\\dfrac{|-2-bc|}{\\sqrt{(b+c)^{2}+1}}=1$"],"설명":"$-2-bc=\\dfrac{-2(1-a^{2})-(a^{2}-3)}{1-a^{2}}=\\dfrac{a^{2}+1}{1-a^{2}}$ 이다. $(b+c)^{2}+1=\\dfrac{4a^{2}+(1-a^{2})^{2}}{(1-a^{2})^{2}}=\\dfrac{(a^{2}+1)^{2}}{(1-a^{2})^{2}}$ 이므로 두 값이 절댓값까지 같아 거리가 $1$ 이다.","확인":null,"스킬":"A2"},{"제목":"교점의 개수와 이유 쓰기","힌트":"중심과 직선 $\\mathrm{QR}$ 사이의 거리와 반지름 $1$ 을 비교하면 직선과 원의 위치 관계는?","식":["$d=1=r$"],"설명":"중심과 직선 사이의 거리가 반지름과 같으므로 직선 $\\mathrm{QR}$ 은 원 $C_{2}$ 에 접한다. 따라서 서로 다른 교점의 개수는 $1$ 개이다.","확인":null,"스킬":"G2"}]},"ns-2c0d6678e6e8":{"길":"정삼각형의 높이가 원 위의 점과 직선 사이의 거리이다","단계":[{"제목":"원의 중심에서 직선까지의 거리 구하기","힌트":"원의 중심 $(0,\\ 0)$ 과 직선 $x-y-6=0$ 사이의 거리는?","식":["$d=\\dfrac{|-6|}{\\sqrt{1^{2}+(-1)^{2}}}=3\\sqrt{2}$"],"설명":"원 $x^{2}+y^{2}=2$ 의 반지름은 $\\sqrt{2}$ 이다. $d>\\sqrt{2}$ 이므로 원은 직선과 만나지 않는다.","확인":null,"스킬":"G2"},{"제목":"점 A 와 직선 사이 거리의 범위 구하기","힌트":"원 위의 점에서 직선까지 거리의 최솟값과 최댓값은 $d$ 와 반지름으로 어떻게 나타날까?","식":["$h_{\\min}=d-r=2\\sqrt{2}$","$h_{\\max}=d+r=4\\sqrt{2}$"],"설명":"원이 직선과 만나지 않으므로 중심에서 직선에 내린 수선이 원과 만나는 두 점이 각각 직선에서 가장 가까운 점과 가장 먼 점이다.","확인":null,"스킬":"S5"},{"제목":"정삼각형의 넓이를 높이로 나타내기","고비":true,"힌트":"변 $\\mathrm{BC}$ 가 직선 위에 있으므로 점 $\\mathrm{A}$ 에서 직선까지의 거리는 정삼각형의 무엇일까?","식":["$h=\\dfrac{\\sqrt{3}}{2}s$","$S=\\dfrac{\\sqrt{3}}{4}s^{2}=\\dfrac{h^{2}}{\\sqrt{3}}$"],"설명":"$\\mathrm{BC}$ 가 직선 위에 있으므로 $\\mathrm{A}$ 에서 직선까지의 거리 $h$ 가 정삼각형의 높이이다. 한 변의 길이를 $s$ 라 하면 $s=\\dfrac{2h}{\\sqrt{3}}$ 이므로 넓이는 $h^{2}$ 에 비례한다.","확인":null,"스킬":"S1"},{"제목":"넓이의 최댓값과 최솟값의 비 구하기","힌트":"넓이는 $h^{2}$ 에 비례하므로 $\\dfrac{M}{m}$ 은 $h_{\\max}^{2}$ 과 $h_{\\min}^{2}$ 의 비이다. 값은?","식":["$M=\\dfrac{(4\\sqrt{2})^{2}}{\\sqrt{3}},\\ \\ m=\\dfrac{(2\\sqrt{2})^{2}}{\\sqrt{3}}$","$\\dfrac{M}{m}=\\dfrac{32}{8}=4$"],"설명":"$h$ 가 최대일 때 넓이가 최대이고, $h$ 가 최소일 때 넓이가 최소이다.","확인":"4","스킬":"S5"}]},"ns-2f86095cd8b5":{"길":"두 넓이에 같은 조각을 더하면 원의 넓이와 삼각형의 넓이가 같아진다","단계":[{"제목":"원 C 의 중심과 반지름 구하기","힌트":"원이 두 축에 접하고 $\\mathrm{A}(0,\\ 3)$ 이 $y$ 축과의 접점이면 중심과 반지름은?","식":["$r=3$","$\\mathrm{C}(3,\\ 3)$"],"설명":"원이 $x$ 축과 $y$ 축에 모두 접하므로 중심은 $(r,\\ r)$ 이다. 점 $\\mathrm{A}$ 가 $y$ 축과의 접점이므로 중심의 $y$ 좌표가 $3$ 이고, 따라서 $r=3$ 이다.","확인":null,"스킬":"S13"},{"제목":"넓이가 같다는 조건을 원과 삼각형으로 바꾸기","고비":true,"힌트":"직선 $\\mathrm{AB}$ 아래쪽에 있는 원의 조각을 두 부분에 각각 더하면 어떤 도형이 될까?","식":["$S_{1}+T=\\pi\\cdot 3^{2}=9\\pi$","$S_{2}+T=\\triangle \\mathrm{OAB}$","$S_{1}=S_{2}\\ \\Rightarrow\\ \\triangle \\mathrm{OAB}=9\\pi$"],"설명":"빗금 친 부분의 넓이를 $S_{1}$, 어두운 부분의 넓이를 $S_{2}$, 직선 $\\mathrm{AB}$ 아래쪽 원의 조각의 넓이를 $T$ 라 한다. 빗금 친 부분에 $T$ 를 더하면 원 전체가 되고, 어두운 부분에 $T$ 를 더하면 삼각형 $\\mathrm{OAB}$ 가 된다. $S_{1}=S_{2}$ 이므로 원의 넓이와 삼각형의 넓이가 같다.","확인":null,"스킬":"S8"},{"제목":"삼각형의 넓이로 점 B 의 좌표 구하기","힌트":"$\\mathrm{B}(b,\\ 0)$ 이라 하고 $\\triangle \\mathrm{OAB}=\\dfrac{1}{2}\\cdot\\overline{\\mathrm{OA}}\\cdot\\overline{\\mathrm{OB}}$ 를 $9\\pi$ 와 같게 놓으면?","식":["$\\dfrac{1}{2}\\cdot 3\\cdot b=9\\pi$","$b=6\\pi$","$\\mathrm{B}(6\\pi,\\ 0)$"],"설명":"삼각형 $\\mathrm{OAB}$ 는 $\\angle \\mathrm{AOB}=90^{\\circ}$ 인 직각삼각형이므로 밑변 $\\overline{\\mathrm{OB}}=b$, 높이 $\\overline{\\mathrm{OA}}=3$ 으로 넓이를 구한다.","확인":null,"스킬":"S8"}]},"ns-309cc2b3cd83":{"길":"자취는 내분점과 외분점을 지름으로 하는 원이다","단계":[{"제목":"선분 AB 의 내분점과 외분점 구하기","힌트":"$\\mathrm{A}(1,\\ 0)$, $\\mathrm{B}(4,\\ 0)$ 을 $2:1$ 로 내분하는 점과 외분하는 점의 좌표는?","식":["$\\left(\\dfrac{2\\cdot 4+1\\cdot 1}{2+1},\\ 0\\right)=(3,\\ 0)$","$\\left(\\dfrac{2\\cdot 4-1\\cdot 1}{2-1},\\ 0\\right)=(7,\\ 0)$"],"설명":"두 정점에서의 거리의 비가 $2:1$ 인 점의 자취는 선분 $\\mathrm{AB}$ 를 $2:1$ 로 내분하는 점과 외분하는 점을 지름의 양 끝으로 하는 원이다.","확인":null,"스킬":"C3"},{"제목":"자취의 방정식 구하고 ㉠ 판단하기","힌트":"지름의 양 끝점 $(3,\\ 0)$, $(7,\\ 0)$ 으로 원의 중심과 반지름을 구하면?","식":["$\\dfrac{3+7}{2}=5,\\ \\ \\dfrac{7-3}{2}=2$","$(x-5)^{2}+y^{2}=4$"],"설명":"중심은 지름의 양 끝점의 중점 $(5,\\ 0)$ 이고 반지름은 지름의 절반인 $2$ 이다. 따라서 ㉠ 은 참이다.","확인":null,"스킬":"S5"},{"제목":"㉡ 판단하기","힌트":"자취가 $x$ 축과 만나는 점은 어디이고, 그중 외분점은 어느 것일까?","식":["$(x-5)^{2}=4$","$x=3$ 또는 $x=7$"],"설명":"$y=0$ 을 대입하면 $x=3$ 또는 $x=7$ 이고, 이 중 $(7,\\ 0)$ 은 선분 $\\mathrm{AB}$ 를 $2:1$ 로 외분하는 점이다. 따라서 ㉡ 은 참이다.","확인":null,"스킬":"C3"},{"제목":"㉢ 판단하기","고비":true,"힌트":"$\\angle \\mathrm{PAB}$ 가 최대일 때 점 $\\mathrm{A}$ 를 지나는 직선과 원은 어떤 위치 관계일까?","식":["$\\dfrac{|5m-m|}{\\sqrt{m^{2}+1}}=2$","$12m^{2}=4,\\ m=\\pm\\dfrac{1}{\\sqrt{3}}$","$\\tan\\theta=\\dfrac{1}{\\sqrt{3}}\\ \\Rightarrow\\ \\theta=30^{\\circ}$"],"설명":"$\\angle \\mathrm{PAB}$ 는 점 $\\mathrm{A}$ 를 지나는 직선 $y=m(x-1)$ 이 원에 접할 때 최대이다. 이때 중심 $(5,\\ 0)$ 과 직선 사이의 거리가 반지름 $2$ 와 같다. 기울기가 $\\dfrac{1}{\\sqrt{3}}$ 이므로 최대 각도는 $30^{\\circ}$ 이고 $45^{\\circ}$ 가 아니다. 따라서 ㉢ 은 거짓이고 옳은 것은 ㉠, ㉡ 이다.","확인":null,"스킬":"S5"}]},"ns-36869176c289":{"길":"중심에서 직선까지의 거리가 반지름 이하이면 만난다","단계":[{"제목":"완전제곱으로 중심과 반지름 읽기","힌트":"$x$ 항과 $y$ 항을 각각 완전제곱식으로 묶으면?","식":["$(x-1)^{2}+(y+2)^{2}=2$"],"설명":"$x^{2}-2x$ 에 $1$ 을, $y^{2}+4y$ 에 $4$ 를 더하고 같은 값을 우변에도 더한다. 중심은 $(1,\\ -2)$ 이고 반지름은 $\\sqrt{2}$ 이다.","확인":null,"스킬":"G2"},{"제목":"만날 조건으로 k 의 범위 구하기","고비":true,"힌트":"직선 $x+y-k=0$ 과 중심 사이의 거리가 반지름 이하가 되는 $k$ 의 범위는?","식":["$\\dfrac{|1-2-k|}{\\sqrt{2}}\\le\\sqrt{2}$","$|k+1|\\le 2$","$-3\\le k\\le 1$"],"설명":"직선과 원이 만나려면 중심과 직선 사이의 거리가 반지름보다 크지 않아야 한다. 절댓값을 풀면 $-2\\le k+1\\le 2$ 이다.","확인":null,"스킬":"G2"},{"제목":"정수 k 의 개수 세기","힌트":"$-3\\le k\\le 1$ 을 만족하는 정수는 몇 개일까?","식":["$k=-3,\\ -2,\\ -1,\\ 0,\\ 1$"],"설명":"양 끝값도 포함되므로 $-3$ 부터 $1$ 까지 정수를 모두 센다.","확인":"5","스킬":"G2"}]},"ns-3763d1009b2c":{"길":"식을 점 (2, 0) 까지 거리의 제곱으로 보고 둘레 위의 최대·최소를 찾는다","단계":[{"제목":"식을 거리의 제곱으로 바꾸기","힌트":"$x^{2}+y^{2}-4x+4$ 를 $x$ 에 대해 완전제곱식으로 묶으면?","식":["$x^{2}+y^{2}-4x+4=(x-2)^{2}+y^{2}$"],"설명":"$(x-2)^{2}+y^{2}$ 은 점 $(x,\\ y)$ 와 점 $\\mathrm{D}(2,\\ 0)$ 사이 거리의 제곱이다. 따라서 $M$, $m$ 은 둘레 위의 점과 $\\mathrm{D}$ 사이 거리의 제곱의 최댓값과 최솟값이다.","확인":null,"스킬":"A6"},{"제목":"최댓값 M 구하기","힌트":"$\\mathrm{D}$ 에서 가장 먼 둘레 위의 점은 꼭짓점 중 어디일까? 네 꼭짓점에서의 값을 비교하면?","식":["$\\mathrm{O}:4,\\ \\mathrm{A}:4,\\ \\mathrm{B}:5,\\ \\mathrm{C}:5$","$M=5$"],"설명":"각 변 위에서 거리의 제곱은 양 끝점에서 최대가 되므로 가장 먼 점은 꼭짓점이다. 예를 들어 $\\mathrm{B}(4,\\ 1)$ 에서는 $(4-2)^{2}+1^{2}=5$ 이다.","확인":"5","스킬":"S4"},{"제목":"최솟값 m 구하기","고비":true,"힌트":"$\\mathrm{D}(2,\\ 0)$ 에서 각 변까지의 거리를 비교하면 가장 가까운 변은 어디이고 그 거리의 제곱은?","식":["$3x-2y-10=0$","$d=\\dfrac{|3\\cdot 2-0-10|}{\\sqrt{3^{2}+(-2)^{2}}}=\\dfrac{4}{\\sqrt{13}}$","$m=d^{2}=\\dfrac{16}{13}$"],"설명":"가장 가까운 변은 $\\overline{\\mathrm{AB}}$ 이다. 다른 변까지 거리의 제곱은 $\\mathrm{OA}$ 가 $2$, $\\mathrm{BC}$ 가 $\\dfrac{5}{2}$, $\\mathrm{OC}$ 가 $\\dfrac{16}{5}$ 로 모두 $\\dfrac{16}{13}$ 보다 크다. $\\mathrm{D}$ 에서 $\\overline{\\mathrm{AB}}$ 에 내린 수선의 발도 선분 위에 있으므로 이 거리가 실제로 둘레 위에서 나온다.","확인":"16/13","스킬":"S4"},{"제목":"13(M−m) 계산하기","힌트":"$M=5,\\ m=\\dfrac{16}{13}$ 을 $13(M-m)$ 에 넣으면?","식":["$13\\left(5-\\dfrac{16}{13}\\right)=65-16=49$"],"설명":"분배법칙으로 $13$ 을 곱하면 분모가 약분된다.","확인":"49","스킬":"S4"}]},"ns-377bfc2474dd":{"길":"C 의 시선 각이 A, B 사이의 틈 안에 들어갈 때가 가장 가깝다","단계":[{"제목":"시선과 접선이 이루는 각 구하기","힌트":"$\\mathrm{P}$ 에서 원기둥 $\\mathrm{A}$ 의 밑면의 원에 그은 접선과 $\\overline{\\mathrm{PA}}$ 가 이루는 각은?","식":["$\\sin\\alpha=\\dfrac{1}{2}$","$\\alpha=30^{\\circ}$"],"설명":"접점에서 반지름과 접선은 수직이므로 직각삼각형에서 $\\sin\\alpha=\\dfrac{\\text{반지름}}{\\overline{\\mathrm{PA}}}=\\dfrac{1}{2}$ 이다. 전시물 $\\mathrm{B}$ 도 같은 값이다.","확인":"30","스킬":"S6"},{"제목":"가려지지 않는 조건 세우기","고비":true,"힌트":"$\\overline{\\mathrm{PA}}\\perp\\overline{\\mathrm{PB}}$ 일 때 $\\mathrm{A}$, $\\mathrm{B}$ 사이로 보이는 틈의 각은 얼마이고, $\\mathrm{C}$ 가 이 틈에 완전히 들어가려면 한쪽으로 몇 도까지 퍼질 수 있을까?","식":["$90^{\\circ}-30^{\\circ}-30^{\\circ}=30^{\\circ}$","$\\varphi\\le 15^{\\circ}$"],"설명":"$\\mathrm{A}$ 가 가리는 각과 $\\mathrm{B}$ 가 가리는 각을 빼면 틈은 $30^{\\circ}$ 이다. $\\mathrm{C}$ 의 시선 각이 틈 안에 들어가야 하고 $d$ 가 최소일 때는 $\\mathrm{C}$ 가 틈의 이등분선 위에 있으므로, 중심에서 한쪽으로 퍼지는 각 $\\varphi$ 는 $15^{\\circ}$ 이하이다.","확인":"15","스킬":"S5"},{"제목":"C 의 시선 각을 d 로 나타내기","힌트":"$\\mathrm{P}$ 에서 반지름 $2$ 인 원에 그은 접선과 $\\overline{\\mathrm{PC}}$ 가 이루는 각 $\\varphi$ 에 대해 $\\sin\\varphi$ 를 $d$ 로 나타내면?","식":["$\\sin\\varphi=\\dfrac{2}{d}$","$\\dfrac{2}{d}\\le\\sin 15^{\\circ}$"],"설명":"첫째 단계와 같은 직각삼각형에서 $\\sin\\varphi$ 는 반지름을 $\\overline{\\mathrm{PC}}=d$ 로 나눈 값이다. $\\varphi\\le 15^{\\circ}$ 이면 $\\sin\\varphi\\le\\sin 15^{\\circ}$ 이다.","확인":null,"스킬":"S6"},{"제목":"d 의 최솟값 구하기","힌트":"$\\sin 15^{\\circ}=\\sin(45^{\\circ}-30^{\\circ})$ 로 값을 구해 $d\\ge\\dfrac{2}{\\sin 15^{\\circ}}$ 에 넣으면?","식":["$\\sin 15^{\\circ}=\\dfrac{\\sqrt{6}-\\sqrt{2}}{4}$","$d\\ge\\dfrac{8}{\\sqrt{6}-\\sqrt{2}}=2\\sqrt{6}+2\\sqrt{2}$"],"설명":"덧셈정리로 $\\sin 15^{\\circ}=\\dfrac{\\sqrt{2}}{2}\\cdot\\dfrac{\\sqrt{3}}{2}-\\dfrac{\\sqrt{2}}{2}\\cdot\\dfrac{1}{2}$ 이다. 분모를 유리화하면 $d$ 의 최솟값이 나온다.","확인":null,"스킬":"S6"}]},"ns-3f5eae757e9e":{"길":"C 는 직선에서 거리 1 이하인 띠이므로 원판과 띠를 겹쳐 본다","단계":[{"제목":"집합 C 의 뜻 읽기","고비":true,"힌트":"$C$ 의 점 $(x,\\ y)$ 에서 직선 $B$ 위의 점 $(x_{2},\\ y_{2})$ 를 빼면 어느 집합에 속할까?","식":["$(x-x_{2},\\ y-y_{2})\\in A$","$(x-x_{2})^{2}+(y-y_{2})^{2}\\le 1$"],"설명":"$C$ 의 점은 직선 $B$ 위의 한 점 $(x_{2},\\ y_{2})$ 에서 거리가 $1$ 이하이다. 따라서 $C$ 는 직선 $B$ 로부터 거리가 $1$ 이하인 점들의 집합, 즉 폭이 $2$ 인 띠이다.","확인":null,"스킬":"G4"},{"제목":"띠를 부등식으로 나타내기","힌트":"직선 $x-y+\\sqrt{2}=0$ 으로부터의 거리가 $1$ 이하인 점의 조건은?","식":["$\\dfrac{|x-y+\\sqrt{2}|}{\\sqrt{2}}\\le 1$","$0\\le y-x\\le 2\\sqrt{2}$"],"설명":"점과 직선 사이의 거리 공식으로 부등식을 세운다. $|x-y+\\sqrt{2}|\\le\\sqrt{2}$ 에서 $-\\sqrt{2}\\le x-y+\\sqrt{2}\\le\\sqrt{2}$ 이다.","확인":null,"스킬":"C6"},{"제목":"원판 A 안에서 y−x 의 범위 구하기","힌트":"직선 $y-x=c$ 가 원판 $x^{2}+y^{2}\\le 1$ 과 만나려면 $c$ 의 범위는?","식":["$\\dfrac{|c|}{\\sqrt{2}}\\le 1\\ \\Rightarrow\\ |c|\\le\\sqrt{2}$","$y-x\\le\\sqrt{2}<2\\sqrt{2}$"],"설명":"원점과 직선 $x-y+c=0$ 사이의 거리가 반지름 $1$ 이하여야 원판과 만난다. 원판 안에서는 $y-x\\le\\sqrt{2}$ 이므로 띠의 위쪽 경계 $y-x=2\\sqrt{2}$ 는 영향을 주지 않는다.","확인":null,"스킬":"C6"},{"제목":"교집합의 넓이 구하기","힌트":"남은 조건 $y\\ge x$ 는 원판을 어떻게 나눌까?","식":["$A\\cap C=\\{(x,\\ y)\\mid x^{2}+y^{2}\\le 1,\\ y\\ge x\\}$","$\\dfrac{1}{2}\\cdot\\pi\\cdot 1^{2}=\\dfrac{\\pi}{2}$"],"설명":"직선 $y=x$ 는 원점을 지나므로 원판을 반으로 나눈다. $A\\cap C$ 는 반원판이므로 넓이는 원판 넓이의 절반이다.","확인":null,"스킬":"G4"}]},"ns-4007fc313ecc":{"길":"접선 사이각이 직각인 경우를 경계로 OP의 범위를 잡는다","단계":[{"제목":"직각일 때 사각형 OAPB의 모양","힌트":"$\\angle \\mathrm{APB}=90^\\circ$ 이면 $\\mathrm{O}$, $\\mathrm{A}$, $\\mathrm{P}$, $\\mathrm{B}$ 를 이은 사각형은 어떤 모양일까?","식":["$\\angle \\mathrm{OAP}=\\angle \\mathrm{OBP}=\\angle \\mathrm{APB}=90^\\circ$","$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{AP}}=\\overline{\\mathrm{PB}}=\\overline{\\mathrm{BO}}=2$"],"설명":"접점에서 반지름과 접선은 수직이므로 네 각이 모두 직각이고 $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}=2$ 이다. 이웃한 두 변이 같은 직사각형이므로 정사각형이다.","확인":null,"스킬":"S5"},{"제목":"경계가 되는 OP의 길이","힌트":"정사각형 $\\mathrm{OAPB}$ 에서 대각선 $\\overline{\\mathrm{OP}}$ 는 한 변의 몇 배일까?","식":["$\\overline{\\mathrm{OP}}=\\sqrt{2}\\times 2=2\\sqrt{2}$"],"설명":"정사각형의 대각선은 한 변의 $\\sqrt{2}$ 배이다. 따라서 $\\angle \\mathrm{APB}$ 가 직각인 점 $\\mathrm{P}$ 는 원점에서 거리가 $2\\sqrt{2}$ 인 곳에 있다.","확인":null,"스킬":"S3"},{"제목":"둔각이 되는 OP의 범위","고비":true,"힌트":"$\\mathrm{P}$ 가 원에서 멀어질수록 $\\angle \\mathrm{APB}$ 는 커질까 작아질까?","식":["$\\sin\\dfrac{\\angle \\mathrm{APB}}{2}=\\dfrac{2}{\\overline{\\mathrm{OP}}}$","$\\angle \\mathrm{APB}>90^\\circ \\iff \\overline{\\mathrm{OP}}<2\\sqrt{2}$","$2<\\overline{\\mathrm{OP}}<2\\sqrt{2}$"],"설명":"$\\mathrm{P}$ 가 원에 가까울수록 두 접선이 벌어져 $\\angle \\mathrm{APB}$ 가 커지고 멀어질수록 작아진다. 직각일 때가 $\\overline{\\mathrm{OP}}=2\\sqrt{2}$ 이므로 둔각은 이보다 가까운 경우이다. $\\mathrm{P}$ 는 원의 외부의 점이므로 $\\overline{\\mathrm{OP}}>2$ 이다.","확인":null,"스킬":"S5"},{"제목":"두 원 사이 영역의 넓이","힌트":"$\\mathrm{P}$ 가 존재하는 영역은 반지름이 $2$, $2\\sqrt{2}$ 인 두 원 사이이다. 넓이는?","식":["$\\pi(2\\sqrt{2})^{2}-\\pi\\times 2^{2}$","$8\\pi-4\\pi=4\\pi$"],"설명":"$2<\\overline{\\mathrm{OP}}<2\\sqrt{2}$ 이므로 영역은 원점이 중심인 큰 원에서 작은 원을 뺀 고리 모양이다. 경계선은 넓이에 영향을 주지 않는다.","확인":null,"스킬":"S12"}]},"ns-443b262efb1a":{"길":"접선과 길이 조건으로 Q의 위치를 잡아 기울기를 구한다","단계":[{"제목":"접선의 방정식 구하기","힌트":"접선 $y=k(x-2)$ 에서 원의 중심까지의 거리가 반지름과 같다는 식을 세우면?","식":["$\\dfrac{|2k|}{\\sqrt{k^{2}+1}}=\\sqrt{2}$","$k^{2}=1$","$y=x-2,\\ y=-x+2$"],"설명":"접선은 원의 중심 $\\mathrm{O}$ 에서 거리가 반지름 $\\sqrt{2}$ 와 같다. 정리하면 $k=\\pm 1$ 이다. 그림에서 $\\mathrm{A}$ 는 $y$ 축의 양의 부분에 있으므로 직선 $\\mathrm{AP}$ 는 $y=-x+2$ 이고 $\\mathrm{A}(0,\\ 2)$, $\\mathrm{B}(0,\\ -2)$ 이다.","확인":null,"스킬":"G2"},{"제목":"AQ의 길이 구하기","힌트":"$\\overline{\\mathrm{AQ}}=x$ 로 두고 $2\\overline{\\mathrm{QP}}=\\overline{\\mathrm{AQ}}+\\overline{\\mathrm{PB}}$ 에 대입하면?","식":["$\\overline{\\mathrm{AP}}=\\overline{\\mathrm{BP}}=2\\sqrt{2}$","$2(2\\sqrt{2}-x)=x+2\\sqrt{2}$","$x=\\dfrac{2\\sqrt{2}}{3}$"],"설명":"$\\overline{\\mathrm{AP}}=\\overline{\\mathrm{BP}}=\\sqrt{2^{2}+2^{2}}=2\\sqrt{2}$ 이고 $\\overline{\\mathrm{QP}}=2\\sqrt{2}-x$ 이다. 조건식에 대입해 정리하면 $3x=2\\sqrt{2}$ 이다.","확인":null,"스킬":"C7"},{"제목":"점 Q의 좌표 구하기","고비":true,"힌트":"$\\triangle \\mathrm{PQH}$ 와 $\\triangle \\mathrm{PAO}$ 의 닮음비로 $\\mathrm{Q}$ 의 $y$ 좌표를 구하면?","식":["$\\overline{\\mathrm{PQ}}:\\overline{\\mathrm{PA}}=\\dfrac{4\\sqrt{2}}{3}:2\\sqrt{2}=2:3$","$\\overline{\\mathrm{QH}}=\\dfrac{2}{3}\\times 2=\\dfrac{4}{3},\\ \\overline{\\mathrm{PH}}=\\dfrac{2}{3}\\times 2=\\dfrac{4}{3}$","$\\mathrm{Q}\\left(\\dfrac{2}{3},\\ \\dfrac{4}{3}\\right)$"],"설명":"$\\mathrm{Q}$ 에서 $x$ 축에 내린 수선의 발을 $\\mathrm{H}$ 라 하면 두 삼각형은 닮음이고 닮음비는 $2:3$ 이다. $\\overline{\\mathrm{AO}}=\\overline{\\mathrm{PO}}=2$ 이므로 $\\overline{\\mathrm{QH}}=\\overline{\\mathrm{PH}}=\\frac{4}{3}$ 이고, $\\mathrm{H}$ 의 $x$ 좌표는 $2-\\frac{4}{3}=\\frac{2}{3}$ 이다.","확인":"4/3","스킬":"S1"},{"제목":"기울기 m 구하기","힌트":"직선 $y=mx$ 가 $\\mathrm{Q}$ 를 지난다는 식에서 $m$ 은?","식":["$\\dfrac{4}{3}=m\\times\\dfrac{2}{3}$","$m=2$"],"설명":"직선 $y=mx$ 는 원점과 $\\mathrm{Q}$ 를 지나므로 $m$ 은 $\\mathrm{Q}$ 의 $y$ 좌표를 $x$ 좌표로 나눈 값이다.","확인":"2","스킬":"G9"}]},"ns-468ebbd1aa58":{"길":"중심과 반지름을 시간 t 로 쓰고 B가 원 안에 드는 t 의 범위를 구한다","단계":[{"제목":"t시간 뒤 태풍의 중심과 반지름","힌트":"$\\mathrm{A}$ 를 원점으로 두면 북동쪽으로 시간당 $12\\sqrt{2}$ 이동한 중심의 좌표는?","식":["$\\left(\\dfrac{12\\sqrt{2}\\,t}{\\sqrt{2}},\\ \\dfrac{12\\sqrt{2}\\,t}{\\sqrt{2}}\\right)=(12t,\\ 12t)$","$r=6t$"],"설명":"북동쪽은 동쪽과 북쪽으로 같은 양씩 가는 방향이다. 이동 거리 $12\\sqrt{2}\\,t$ 를 $\\sqrt{2}$ 로 나눈 $12t$ 가 각 좌표의 변화량이다. 반지름은 시간당 $6$ 씩 늘어 $6t$ 이다.","확인":null,"스킬":"S4"},{"제목":"영향권 조건식 세우기","힌트":"$\\mathrm{B}(120,\\ 180)$ 이 원의 내부 또는 경계에 있으려면 중심까지의 거리와 반지름 사이에 어떤 관계가 필요할까?","식":["$(120-12t)^{2}+(180-12t)^{2}\\le (6t)^{2}$"],"설명":"원의 내부와 경계에 있는 점은 중심까지의 거리가 반지름 이하이다. 거리와 반지름이 모두 양수이므로 제곱끼리 비교해도 같다.","확인":null,"스킬":"C7"},{"제목":"t에 대한 이차부등식으로 정리","고비":true,"힌트":"좌변을 전개해 $t^{2}$ 항을 모은 뒤 양변의 공통인수로 나누면?","식":["$288t^{2}-7200t+46800\\le 36t^{2}$","$252t^{2}-7200t+46800\\le 0$","$7t^{2}-200t+1300\\le 0$"],"설명":"$(120-12t)^{2}+(180-12t)^{2}=288t^{2}-7200t+46800$ 이다. 이항한 뒤 양변을 $36$ 으로 나누면 계수가 간단해진다.","확인":null,"스킬":"C7"},{"제목":"영향권에 들어오는 시각과 나가는 시각","힌트":"$7t^{2}-200t+1300=(t-\\square)(7t-\\square)$ 로 인수분해하면 작은 근은?","식":["$(t-10)(7t-130)\\le 0$","$10\\le t\\le\\dfrac{130}{7}$"],"설명":"$t=10$ 일 때 $\\mathrm{B}$ 가 처음 영향권에 들어오고 $t=\\frac{130}{7}$ 일 때 벗어난다. 이차항의 계수가 양수이므로 두 근 사이에서 부등식이 성립한다.","확인":"10","스킬":"G6"},{"제목":"영향권에 있는 시간과 a+b","힌트":"나가는 시각에서 들어오는 시각을 뺀 시간을 기약분수 $\\frac{b}{a}$ 로 나타내면 $a+b$ 는?","식":["$\\dfrac{130}{7}-10=\\dfrac{60}{7}$","$a=7,\\ b=60$","$a+b=67$"],"설명":"분모 $7$ 과 분자 $60$ 은 서로소이므로 $a=7$, $b=60$ 이다.","확인":"67","스킬":"C7"}]},"ns-46a53d31e230":{"길":"영역의 꼭짓점에서 원점까지 거리의 제곱을 비교한다","단계":[{"제목":"두 경계선의 교점","힌트":"$2x+3y=18$ 에서 $2x+y=10$ 을 변끼리 빼면 $y$ 는?","식":["$(2x+3y)-(2x+y)=18-10$","$2y=8,\\ y=4$","$x=3$"],"설명":"두 식을 빼면 $x$ 가 소거되어 $y$ 가 정해진다. $y=4$ 를 $2x+y=10$ 에 대입하면 $x=3$ 이다.","확인":"4","스킬":"A10"},{"제목":"영역의 꼭짓점 구하기","고비":true,"힌트":"두 경계선이 각각 $x$ 축, $y$ 축과 만나는 점 중 영역의 꼭짓점이 되는 점은?","식":["$2x+y=10,\\ y=0 \\Rightarrow (5,\\ 0)$","$2x+3y=18,\\ x=0 \\Rightarrow (0,\\ 6)$","$(0,\\ 0),\\ (5,\\ 0),\\ (3,\\ 4),\\ (0,\\ 6)$"],"설명":"$x\\ge 0$, $y\\ge 0$ 이므로 영역은 제1사분면 안에 있다. $x$ 축 위에서는 $2x+y=10$ 이 먼저 영역을 막고 $y$ 축 위에서는 $2x+3y=18$ 이 먼저 막는다. 여기에 원점과 교점 $(3,\\ 4)$ 를 더한 네 점이 꼭짓점이다.","확인":null,"스킬":"G6"},{"제목":"꼭짓점에서 x²+y² 비교","힌트":"네 꼭짓점을 $x^{2}+y^{2}$ 에 대입했을 때 가장 큰 값은?","식":["$0,\\ 25,\\ 25,\\ 36$","$\\max=36$"],"설명":"$x^{2}+y^{2}$ 은 원점에서 점까지 거리의 제곱이다. 볼록한 다각형 영역에서 원점으로부터 가장 먼 점은 꼭짓점이므로 네 값만 비교하면 된다.","확인":"36","스킬":"S4"}]},"ns-4a96b63bcc3f":{"길":"외각이등분선의 비로 C의 자취를 원으로 보고 반지름을 구한다","단계":[{"제목":"AD와 BD의 길이","힌트":"좌표의 차를 이용해 $\\overline{\\mathrm{AD}}$, $\\overline{\\mathrm{BD}}$ 를 구하면?","식":["$\\overline{\\mathrm{AD}}=\\sqrt{15^{2}+30^{2}}=15\\sqrt{5}$","$\\overline{\\mathrm{BD}}=\\sqrt{10^{2}+20^{2}}=10\\sqrt{5}$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{D}$ 는 기울기가 $2$ 인 한 직선 위에 있고 $\\mathrm{D}$ 는 $\\mathrm{B}$ 의 바깥쪽에 있다. 두 점 사이의 거리 공식으로 각각 구한다.","확인":null,"스킬":"S4"},{"제목":"CA와 CB의 길이의 비","힌트":"외각의 이등분선은 대변 $\\mathrm{AB}$ 를 어떤 비로 외분할까?","식":["$\\overline{\\mathrm{CA}}:\\overline{\\mathrm{CB}}=\\overline{\\mathrm{AD}}:\\overline{\\mathrm{BD}}$","$=15\\sqrt{5}:10\\sqrt{5}=3:2$","$\\dfrac{\\overline{\\mathrm{CA}}}{\\overline{\\mathrm{CB}}}=\\dfrac{3}{2}$"],"설명":"삼각형의 외각의 이등분선은 대변을 두 변의 길이의 비로 외분한다. 따라서 $\\overline{\\mathrm{CA}}:\\overline{\\mathrm{CB}}$ 는 $\\overline{\\mathrm{AD}}:\\overline{\\mathrm{BD}}$ 와 같다.","확인":"3/2","스킬":"S10"},{"제목":"점 C가 그리는 원의 지름의 양 끝","고비":true,"힌트":"$\\overline{\\mathrm{AB}}$ 를 $3:2$ 로 내분하는 점의 $x$ 좌표는?","식":["$\\left(\\dfrac{3\\times 8+2\\times 3}{3+2},\\ \\dfrac{3\\times(-2)+2\\times(-12)}{3+2}\\right)=(6,\\ -6)$","$\\left(\\dfrac{3\\times 8-2\\times 3}{3-2},\\ \\dfrac{3\\times(-2)-2\\times(-12)}{3-2}\\right)=(18,\\ 18)$"],"설명":"두 점 $\\mathrm{A}$, $\\mathrm{B}$ 까지의 거리의 비가 $3:2$ 로 일정한 점은 아폴로니우스의 원 위에 있다. 이 원은 $\\overline{\\mathrm{AB}}$ 를 $3:2$ 로 내분하는 점과 외분하는 점을 지름의 양 끝으로 한다. 외분점은 $\\mathrm{D}$ 와 같다.","확인":"6","스킬":"S5"},{"제목":"원의 중심과 반지름","힌트":"지름의 양 끝 $(6,\\ -6)$, $(18,\\ 18)$ 의 중점인 중심의 $x$ 좌표는?","식":["$\\left(\\dfrac{6+18}{2},\\ \\dfrac{-6+18}{2}\\right)=(12,\\ 6)$","$r=\\dfrac{1}{2}\\sqrt{12^{2}+24^{2}}=6\\sqrt{5}$"],"설명":"중심은 지름의 양 끝점의 중점이다. 지름의 길이는 두 끝점 사이의 거리 $12\\sqrt{5}$ 이고 반지름은 그 절반이다.","확인":"12","스킬":"S13"},{"제목":"C와 직선 AB 사이 거리의 최댓값","힌트":"원의 중심 $(12,\\ 6)$ 이 직선 $\\mathrm{AB}$ 위에 있다면 거리의 최댓값은 무엇과 같을까?","식":["$y=2x-18,\\ 2\\times 12-18=6$","$d_{\\max}=r=6\\sqrt{5}$"],"설명":"직선 $\\mathrm{AB}$ 의 방정식은 $y=2x-18$ 이고 중심 $(12,\\ 6)$ 이 이 직선 위에 있다. 이때 원 위의 점에서 직선까지의 거리는 중심을 지나는 수직선과 만나는 점에서 가장 크고, 그 값이 반지름이다.","확인":null,"스킬":"S13"}]},"ns-4acaba46b15e":{"길":"수직인 두 접선이 만드는 정사각형으로 중심과 A 사이 거리를 잡는다","단계":[{"제목":"중심과 점 A 사이의 거리","고비":true,"힌트":"두 접선이 수직이면 중심, 두 접점, 점 $\\mathrm{A}$ 를 이은 사각형은 어떤 모양일까?","식":["$\\overline{\\mathrm{OA}}=\\sqrt{10}\\times\\sqrt{2}=2\\sqrt{5}$"],"설명":"원의 중심을 $\\mathrm{O}(1,\\ 2)$ 라 한다. 접점에서 반지름과 접선은 수직이므로 네 점 $\\mathrm{O}$, 두 접점, $\\mathrm{A}$ 를 이은 사각형은 네 각이 직각이고 이웃한 두 변이 반지름 $\\sqrt{10}$ 으로 같은 정사각형이다. 대각선 $\\overline{\\mathrm{OA}}$ 는 한 변의 $\\sqrt{2}$ 배이다.","확인":null,"스킬":"S5"},{"제목":"a에 대한 방정식 세우기","힌트":"$\\mathrm{O}(1,\\ 2)$ 와 $\\mathrm{A}(a,\\ 4)$ 사이 거리의 제곱을 $(2\\sqrt{5})^{2}$ 과 같게 놓으면?","식":["$(a-1)^{2}+(4-2)^{2}=20$","$a^{2}-2a-15=0$"],"설명":"거리 공식의 제곱근을 없애려고 양변을 제곱한다. 전개하면 $a^{2}-2a+1+4=20$ 이고 정리하면 $a^{2}-2a-15=0$ 이다.","확인":null,"스킬":"S4"},{"제목":"a 값들의 합","힌트":"이차방정식 $a^{2}-2a-15=0$ 의 두 근의 합은 일차항의 계수와 어떤 관계일까?","식":["$(a-5)(a+3)=0$","$a=5,\\ -3$","$5+(-3)=2$"],"설명":"두 근 모두 중심에서 $2\\sqrt{5}$ 떨어져 있어 반지름 $\\sqrt{10}$ 보다 멀므로 원 밖의 점이다. 근과 계수의 관계에서도 합은 $2$ 이다.","확인":"2","스킬":"A2"}]},"ns-4b8b25f1c0f2":{"길":"옮긴 직선과 원이 접할 조건을 거리로 쓰고 근과 계수의 관계를 쓴다","단계":[{"제목":"평행이동한 직선의 방정식","힌트":"$y$ 축으로 $k$ 만큼 옮기면 $y$ 대신 무엇을 넣을까?","식":["$x-2(y-k)=0$","$x-2y+2k=0$"],"설명":"$y$ 축 방향으로 $k$ 만큼 평행이동하면 $y$ 를 $y-k$ 로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"원의 중심과 반지름","힌트":"원의 방정식을 $(x-p)^{2}+(y-q)^{2}=r^{2}$ 꼴로 고치면 반지름 $r$ 은?","식":["$(x-2)^{2}+(y+3)^{2}=4$","$r=2$"],"설명":"$x^{2}-4x$ 와 $y^{2}+6y$ 를 각각 완전제곱식으로 만들면 $(x-2)^{2}-4+(y+3)^{2}-9+9=0$ 이다. 중심은 $(2,\\ -3)$ 이고 반지름은 $2$ 이다.","확인":"2","스킬":"A6"},{"제목":"접할 조건 세우기","고비":true,"힌트":"중심 $(2,\\ -3)$ 에서 직선 $x-2y+2k=0$ 까지의 거리가 반지름과 같다는 식을 세우면?","식":["$\\dfrac{|2-2\\times(-3)+2k|}{\\sqrt{1^{2}+(-2)^{2}}}=2$","$|2k+8|=2\\sqrt{5}$","$k^{2}+8k+11=0$"],"설명":"원과 직선이 접하면 중심에서 직선까지의 거리가 반지름과 같다. 양변을 제곱해 $4k^{2}+32k+44=0$ 을 얻고 $4$ 로 나눈다.","확인":null,"스킬":"G2"},{"제목":"αβ의 값","힌트":"$k^{2}+8k+11=0$ 의 두 근이 $\\alpha,\\ \\beta$ 일 때 곱은 상수항과 어떤 관계일까?","식":["$\\alpha\\beta=11$"],"설명":"판별식이 $64-44=20>0$ 이므로 서로 다른 두 실근이 있다. 근과 계수의 관계에서 두 근의 곱은 상수항 $11$ 이다.","확인":"11","스킬":"A2"}]},"ns-4c251739c144":{"길":"공통현이 지름인 원이 가장 작음을 이용해 반현의 길이를 구한다","단계":[{"제목":"공통현의 방정식","힌트":"두 원의 방정식을 변끼리 빼면 $x^{2}+y^{2}$ 항이 사라진다. 남는 직선은?","식":["$(x^{2}+y^{2}-9)-(x^{2}+y^{2}-2x+4y-11)=0$","$2x-4y+2=0$"],"설명":"두 원의 교점은 두 방정식을 모두 만족하므로 뺀 식도 만족한다. 이 직선이 두 교점을 잇는 공통현을 포함한다.","확인":null,"스킬":"G1"},{"제목":"원점과 공통현 사이의 거리","힌트":"원 $x^{2}+y^{2}=9$ 의 중심 $\\mathrm{O}$ 에서 직선 $2x-4y+2=0$ 까지의 거리는?","식":["$\\overline{\\mathrm{OM}}=\\dfrac{|2|}{\\sqrt{2^{2}+(-4)^{2}}}=\\dfrac{1}{\\sqrt{5}}$"],"설명":"점과 직선 사이의 거리 공식에 $(0,\\ 0)$ 을 대입한다. 수선의 발을 $\\mathrm{M}$ 이라 한다.","확인":null,"스킬":"G2"},{"제목":"반현의 길이의 제곱","힌트":"교점을 $\\mathrm{A}$, $\\mathrm{B}$ 라 할 때 직각삼각형 $\\mathrm{OMA}$ 에서 $\\overline{\\mathrm{AM}}^{2}$ 은?","식":["$\\overline{\\mathrm{OA}}=3,\\ \\overline{\\mathrm{OM}}=\\dfrac{1}{\\sqrt{5}}$","$\\overline{\\mathrm{AM}}^{2}=9-\\dfrac{1}{5}=\\dfrac{44}{5}$"],"설명":"원의 중심에서 현에 내린 수선은 현을 이등분하므로 $\\mathrm{M}$ 은 $\\overline{\\mathrm{AB}}$ 의 중점이다. 직각삼각형 $\\mathrm{OMA}$ 에서 피타고라스 정리를 쓴다.","확인":"44/5","스킬":"S3"},{"제목":"넓이가 최소인 원","고비":true,"힌트":"두 점 $\\mathrm{A}$, $\\mathrm{B}$ 를 지나는 원의 지름은 $\\overline{\\mathrm{AB}}$ 보다 짧을 수 있을까?","식":["$r^{2}=\\overline{\\mathrm{AM}}^{2}=\\dfrac{44}{5}$","$\\mathrm{S}=\\dfrac{44}{5}\\pi$","$5\\mathrm{S}=44\\pi$"],"설명":"두 점을 지나는 원에서 현 $\\overline{\\mathrm{AB}}$ 는 지름보다 길 수 없다. 따라서 $\\overline{\\mathrm{AB}}$ 가 지름일 때 넓이가 최소이고 이때 반지름은 $\\overline{\\mathrm{AM}}$ 이다.","확인":null,"스킬":"S5"}]},"ns-4e1308a9bbe5":{"길":"내접원의 반지름과 접선의 길이로 접점을 찾아 직선을 세운다","단계":[{"제목":"내접원의 반지름","힌트":"직선 $\\mathrm{AB}$ 의 방정식을 구해 원점 $\\mathrm{O}$ 까지의 거리를 구하면?","식":["$y-6=\\dfrac{2}{11}(x-8)\\Rightarrow 2x-11y+50=0$","$r=\\dfrac{50}{\\sqrt{2^{2}+11^{2}}}=2\\sqrt{5}$"],"설명":"내접원은 세 변에 접하므로 중심 $\\mathrm{O}$ 에서 변 $\\mathrm{AB}$ 까지의 거리가 반지름이다. $\\mathrm{AB}$ 의 기울기는 $\\dfrac{6-2}{8-(-14)}=\\dfrac{2}{11}$ 이다.","확인":null,"스킬":"G2"},{"제목":"접선의 길이 AM","힌트":"$\\mathrm{AC}$ 위의 접점 $\\mathrm{M}$ 에 대해 $\\overline{\\mathrm{AM}}^{2}$ 은?","식":["$\\overline{\\mathrm{OA}}=\\sqrt{8^{2}+6^{2}}=10$","$\\overline{\\mathrm{AM}}^{2}=10^{2}-(2\\sqrt{5})^{2}=80$"],"설명":"접점 $\\mathrm{M}$ 에서 반지름 $\\overline{\\mathrm{OM}}$ 과 접선 $\\mathrm{AC}$ 는 수직이므로 직각삼각형 $\\mathrm{OMA}$ 에서 피타고라스 정리를 쓴다. $\\overline{\\mathrm{AM}}=4\\sqrt{5}$ 이다.","확인":"80","스킬":"S3"},{"제목":"접점 M 이 놓이는 직선","힌트":"$x^{2}+y^{2}=20$ 과 $(x-8)^{2}+(y-6)^{2}=80$ 을 연립해 이차항을 소거하면?","식":["$x^{2}+y^{2}=20$","$(x-8)^{2}+(y-6)^{2}=80$","$4x+3y-10=0$"],"설명":"$\\mathrm{M}(x,\\ y)$ 는 $\\overline{\\mathrm{OM}}=2\\sqrt{5}$, $\\overline{\\mathrm{AM}}=4\\sqrt{5}$ 를 만족하는 점이다. 둘째 식을 전개해 첫째 식을 대입하면 이차항이 사라져 직선의 방정식이 된다.","확인":null,"스킬":"G1"},{"제목":"접점 M 의 좌표","고비":true,"힌트":"$4x+3y-10=0$ 을 $x^{2}+y^{2}=20$ 에 대입해 얻는 두 해 중 직선 $\\mathrm{AB}$ 위의 접점이 아닌 점의 $x$ 좌표는?","식":["$5x^{2}-16x-16=0$","$x=4,\\ -\\dfrac{4}{5}$","$\\mathrm{M}(4,\\ -2)$"],"설명":"$y=\\dfrac{10-4x}{3}$ 을 대입해 정리하면 $5x^{2}-16x-16=0$ 이다. $x=-\\dfrac{4}{5}$ 일 때의 점 $\\left(-\\dfrac{4}{5},\\ \\dfrac{22}{5}\\right)$ 는 직선 $\\mathrm{AB}$ 위의 접점이므로 $\\mathrm{AC}$ 위의 접점은 $\\mathrm{M}(4,\\ -2)$ 이다.","확인":"4","스킬":"G1"},{"제목":"직선 AC 의 방정식","힌트":"$\\mathrm{OM}\\perp \\mathrm{AC}$ 이므로 $\\mathrm{AC}$ 의 기울기는 $\\mathrm{OM}$ 의 기울기와 어떤 관계일까?","식":["$\\dfrac{-2-0}{4-0}=-\\dfrac{1}{2},\\ -\\dfrac{1}{2}\\times m=-1,\\ m=2$","$y-6=2(x-8)$","$2x-y-10=0$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이므로 $\\mathrm{AC}$ 의 기울기는 $2$ 이다. 이 직선은 $\\mathrm{A}(8,\\ 6)$ 을 지난다.","확인":null,"스킬":"G9"}]},"ns-4f7d353a4383":{"길":"직각삼각형의 넓이를 두 가지로 세어 공통현의 반을 구한다","단계":[{"제목":"삼각형 OAO′ 의 모양","힌트":"세 변의 길이 $6$, $8$, $10$ 사이에 어떤 관계가 있을까?","식":["$\\overline{\\mathrm{OA}}^{2}+\\overline{\\mathrm{O'A}}^{2}=6^{2}+8^{2}=100=10^{2}$","$\\angle \\mathrm{OAO'}=90^\\circ$"],"설명":"교점 $\\mathrm{A}$ 는 두 원 위의 점이므로 $\\overline{\\mathrm{OA}}=6$, $\\overline{\\mathrm{O'A}}=8$ 이다. 피타고라스 정리의 역으로 $\\triangle \\mathrm{OAO'}$ 은 직각삼각형이다.","확인":null,"스킬":"S3"},{"제목":"넓이를 두 가지로 세어 AH 구하기","고비":true,"힌트":"중심선과 공통현이 만나는 점을 $\\mathrm{H}$ 라 하고 $\\triangle \\mathrm{OAO'}$ 의 넓이를 밑변을 바꿔 두 번 쓰면 $\\overline{\\mathrm{AH}}$ 는?","식":["$\\dfrac{1}{2}\\times 6\\times 8=\\dfrac{1}{2}\\times 10\\times\\overline{\\mathrm{AH}}$","$\\overline{\\mathrm{AH}}=\\dfrac{24}{5}$"],"설명":"두 원의 중심을 잇는 선분은 공통현을 수직이등분하므로 $\\overline{\\mathrm{AH}}$ 는 빗변 $\\overline{\\mathrm{OO'}}$ 에 내린 높이이다. 직각을 낀 두 변을 밑변과 높이로 본 넓이와 빗변을 밑변으로 본 넓이는 같다.","확인":"24/5","스킬":"S8"},{"제목":"공통현의 길이","힌트":"$\\mathrm{H}$ 가 $\\overline{\\mathrm{AB}}$ 의 중점이므로 $\\overline{\\mathrm{AB}}$ 는?","식":["$\\overline{\\mathrm{AB}}=2\\overline{\\mathrm{AH}}=\\dfrac{48}{5}=9.6$"],"설명":"공통현은 중심선에 의해 이등분되므로 $\\overline{\\mathrm{AB}}$ 는 $\\overline{\\mathrm{AH}}$ 의 두 배이다. 길이의 단위는 $\\mathrm{cm}$ 이다.","확인":"9.6","스킬":"S2"}]},"ns-4ff131e9835c":{"길":"넓이가 최대일 때 중심과 P를 잇는 직선이 AB와 수직임을 쓴다","단계":[{"제목":"넓이가 최대일 때 P의 위치","고비":true,"힌트":"밑변 $\\overline{\\mathrm{AB}}$ 가 고정이므로 넓이가 최대이려면 $\\mathrm{P}$ 와 직선 $\\mathrm{AB}$ 사이의 무엇이 최대여야 할까?","식":["$\\mathrm{CP}\\perp \\mathrm{AB}$"],"설명":"밑변이 고정이면 높이, 즉 $\\mathrm{P}$ 에서 직선 $\\mathrm{AB}$ 까지의 거리가 최대일 때 넓이가 최대이다. 이때 $\\mathrm{P}$ 에서의 접선이 $\\mathrm{AB}$ 와 평행하고, 접선은 반지름 $\\mathrm{CP}$ 와 수직이므로 $\\mathrm{CP}\\perp \\mathrm{AB}$ 이다. 원의 중심은 $\\mathrm{C}(0,\\ 2)$ 이다.","확인":null,"스킬":"S5"},{"제목":"직선 AB 의 기울기","힌트":"$\\mathrm{A}(5,\\ 2)$, $\\mathrm{B}(4,\\ 5)$ 를 지나는 직선의 기울기는?","식":["$\\dfrac{5-2}{4-5}=-3$"],"설명":"두 점의 $y$ 좌표의 차를 $x$ 좌표의 차로 나눈다.","확인":"-3","스킬":"G9"},{"제목":"구하는 직선의 기울기","힌트":"수직인 두 직선의 기울기의 곱은 얼마일까?","식":["$-3\\times a=-1$","$a=\\dfrac{1}{3}$"],"설명":"직선 $\\mathrm{CP}$ 가 $\\mathrm{AB}$ 와 수직이므로 두 기울기의 곱은 $-1$ 이다.","확인":"1/3","스킬":"G9"}]},"ns-50aeea9e644b":{"길":"중심 사이의 거리와 두 반지름의 합·차를 비교한다","단계":[{"제목":"두 원의 중심 사이의 거리","힌트":"두 중심 $(0,\\ 0)$, $(4,\\ 3)$ 사이의 거리는?","식":["$\\sqrt{4^{2}+3^{2}}=5$"],"설명":"두 원의 반지름은 $1$, $r$ 이다. 두 점 사이의 거리 공식으로 중심 사이의 거리를 구한다.","확인":"5","스킬":"S5"},{"제목":"외접일 때의 r","힌트":"외접하면 중심 사이의 거리는 두 반지름과 어떤 관계일까?","식":["$1+r=5$","$r=4$"],"설명":"외접하면 중심 사이의 거리가 두 반지름의 합과 같다. 따라서 $a=4$ 이다.","확인":null,"스킬":"S5"},{"제목":"내접일 때의 r","고비":true,"힌트":"내접하면 중심 사이의 거리는 두 반지름의 차와 같다. $r>0$ 인 해는?","식":["$|r-1|=5\\Rightarrow r=6,\\ -4$","$r>0\\Rightarrow r=6$"],"설명":"내접하면 중심 사이의 거리가 두 반지름의 차의 절댓값과 같다. $r>0$ 이어야 하므로 $b=6$ 이다.","확인":"6","스킬":"S5"},{"제목":"b−a 의 값","힌트":"앞에서 구한 두 값의 차는?","식":["$b-a=6-4=2$"],"설명":"$a=4$, $b=6$ 이므로 차는 $2$ 이다.","확인":"2","스킬":"S5"}]},"ns-551d4d5b76b9":{"길":"마주 보는 각의 합으로 DE가 AC와 수직임을 알아 원을 세운다","단계":[{"제목":"직선 AC 의 방정식","힌트":"$\\mathrm{A}(0,\\ 10)$, $\\mathrm{C}(4,\\ 0)$ 을 지나는 직선의 기울기는?","식":["$\\dfrac{0-10}{4-0}=-\\dfrac{5}{2}$","$y=-\\dfrac{5}{2}x+10$"],"설명":"기울기를 구한 뒤 $y$ 절편 $10$ 을 쓴다.","확인":"-5/2","스킬":"G9"},{"제목":"DE 와 AC 의 위치 관계","고비":true,"힌트":"$\\angle \\mathrm{EBC}$ 가 직각이면 같은 원 위의 사각형 $\\mathrm{BCFE}$ 에서 마주 보는 $\\angle \\mathrm{EFC}$ 는 몇 도일까?","식":["$\\angle \\mathrm{EBC}=90^\\circ$","$\\angle \\mathrm{EFC}=180^\\circ-90^\\circ=90^\\circ$","$\\mathrm{DE}\\perp \\mathrm{AC}$"],"설명":"$\\mathrm{B}$ 는 원점, $\\mathrm{E}$ 는 $y$ 축 위의 점, $\\mathrm{C}$ 는 $x$ 축 위의 점이므로 $\\angle \\mathrm{EBC}=90^\\circ$ 이다. 원에 내접하는 사각형에서 마주 보는 두 각의 합은 $180^\\circ$ 이므로 $\\angle \\mathrm{EFC}=90^\\circ$ 이다. $\\mathrm{F}$ 는 직선 $\\mathrm{DE}$ 와 $\\mathrm{AC}$ 의 교점이다.","확인":null,"스킬":"S5"},{"제목":"직선 DE 와 점 E 의 좌표","힌트":"$\\mathrm{D}(15,\\ 9)$ 를 지나고 $\\mathrm{AC}$ 에 수직인 직선이 $y$ 축과 만나는 점 $\\mathrm{E}$ 의 $y$ 좌표는?","식":["$-\\dfrac{5}{2}\\times m=-1,\\ m=\\dfrac{2}{5}$","$y-9=\\dfrac{2}{5}(x-15)\\Rightarrow y=\\dfrac{2}{5}x+3$","$\\mathrm{E}(0,\\ 3)$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다. $\\mathrm{E}$ 는 $y$ 축 위의 점이므로 $x=0$ 을 대입해 $y$ 좌표를 구한다.","확인":"3","스킬":"G3"},{"제목":"원의 방정식과 반지름","힌트":"$x^{2}+y^{2}+Ax+By+C=0$ 에 $\\mathrm{B}$, $\\mathrm{C}$, $\\mathrm{E}$ 를 대입해 구한 원의 $r^{2}$ 은?","식":["$C=0,\\ 16+4A=0,\\ 9+3B=0$","$x^{2}+y^{2}-4x-3y=0$","$(x-2)^{2}+\\left(y-\\dfrac{3}{2}\\right)^{2}=\\dfrac{25}{4}$"],"설명":"세 점을 차례로 대입해 $C=0$, $A=-4$, $B=-3$ 을 얻는다. 완전제곱식으로 고치면 $r^{2}=\\dfrac{25}{4}$ 이다. $\\angle \\mathrm{EBC}=90^\\circ$ 이므로 $\\overline{\\mathrm{EC}}=5$ 가 지름이라는 점으로도 확인된다.","확인":"25/4","스킬":"S13"},{"제목":"원의 넓이 S 와 16S","힌트":"$\\mathrm{S}=\\pi r^{2}$ 에 대입하면 $16\\mathrm{S}$ 는?","식":["$\\mathrm{S}=\\pi\\times\\dfrac{25}{4}=\\dfrac{25}{4}\\pi$","$16\\mathrm{S}=100\\pi$"],"설명":"반지름의 제곱 $\\dfrac{25}{4}$ 에 $\\pi$ 를 곱해 넓이를 구하고 $16$ 배 한다.","확인":null,"스킬":"S13"}]},"ns-55e7c3ce0c7e":{"길":"중심선과 공통현이 수직임을 이용해 대각선의 곱으로 넓이를 구한다","단계":[{"제목":"공통현의 방정식","힌트":"두 원의 방정식에서 $x^{2}+y^{2}$ 항을 소거하면 남는 직선은?","식":["$x^{2}+y^{2}-16=0$","$x^{2}+y^{2}-6x-6y+14=0$","$6x+6y-30=0,\\ x+y=5$"],"설명":"둘째 원의 방정식을 전개해 첫째 식에서 빼면 두 교점을 지나는 직선이 나온다.","확인":null,"스킬":"G1"},{"제목":"공통현의 길이","힌트":"원점에서 직선 $x+y=5$ 까지의 거리를 이용해 $\\overline{\\mathrm{PQ}}^{2}$ 을 구하면?","식":["$d=\\dfrac{5}{\\sqrt{2}}$","$\\left(\\dfrac{\\overline{\\mathrm{PQ}}}{2}\\right)^{2}=16-\\dfrac{25}{2}=\\dfrac{7}{2}$","$\\overline{\\mathrm{PQ}}^{2}=14$"],"설명":"원점에서 현에 내린 수선은 현을 이등분하므로 반지름 $4$ 와 거리 $d$ 로 반현의 길이를 구한다. 현 전체는 반현의 두 배이다.","확인":"14","스킬":"S5"},{"제목":"사각형의 대각선과 넓이 공식","고비":true,"힌트":"두 중심을 잇는 $\\overline{\\mathrm{OC}}$ 와 공통현 $\\overline{\\mathrm{PQ}}$ 는 어떤 위치 관계일까?","식":["$\\overline{\\mathrm{OC}}\\perp \\overline{\\mathrm{PQ}}$","$\\overline{\\mathrm{OC}}=\\sqrt{3^{2}+3^{2}}=3\\sqrt{2}$","$\\square \\mathrm{POQC}=\\dfrac{1}{2}\\times \\overline{\\mathrm{OC}}\\times \\overline{\\mathrm{PQ}}$"],"설명":"두 원의 중심을 잇는 직선은 공통현을 수직이등분한다. $\\mathrm{O}$ 와 $\\mathrm{C}$ 는 직선 $x+y=5$ 의 서로 반대쪽에 있으므로 사각형 $\\mathrm{POQC}$ 의 두 대각선은 $\\overline{\\mathrm{OC}}$, $\\overline{\\mathrm{PQ}}$ 이고 서로 수직이다. 대각선이 수직인 사각형의 넓이는 두 대각선의 곱의 절반이다.","확인":null,"스킬":"S8"},{"제목":"사각형의 넓이","힌트":"$\\overline{\\mathrm{PQ}}=\\sqrt{14}$, $\\overline{\\mathrm{OC}}=3\\sqrt{2}$ 를 대입하면?","식":["$\\dfrac{1}{2}\\times 3\\sqrt{2}\\times \\sqrt{14}=\\dfrac{3}{2}\\sqrt{28}=3\\sqrt{7}$"],"설명":"$\\sqrt{2}\\times\\sqrt{14}=\\sqrt{28}=2\\sqrt{7}$ 이므로 넓이는 $\\dfrac{1}{2}\\times 3\\times 2\\sqrt{7}=3\\sqrt{7}$ 이다.","확인":null,"스킬":"S8"}]},"ns-57d0d5a26322":{"길":"현의 길이를 n 으로 나타내 자연수 조건을 약수 조건으로 바꾼다","단계":[{"제목":"현의 길이의 제곱","힌트":"$y=\\dfrac{1}{n}$ 을 원의 방정식에 대입해 $x^{2}$ 을 구하면?","식":["$x^{2}+\\left(\\dfrac{1}{n}-1\\right)^{2}=1$","$x^{2}=\\dfrac{2}{n}-\\dfrac{1}{n^{2}}$","$l_{n}^{2}=(2x)^{2}=\\dfrac{8}{n}-\\dfrac{4}{n^{2}}$"],"설명":"두 교점은 $y$ 축에 대칭이므로 $x$ 좌표가 $\\pm x$ 이고 $l_{n}=2|x|$ 이다.","확인":null,"스킬":"G1"},{"제목":"n 을 곱한 식 정리","힌트":"$n\\times l_{n}^{2}$ 을 정리하면 어떤 꼴이 될까?","식":["$n\\left(l_{n}\\right)^{2}=8-\\dfrac{4}{n}$"],"설명":"$l_{n}^{2}$ 에 $n$ 을 곱하면 상수 $8$ 과 분수 $\\dfrac{4}{n}$ 만 남는다.","확인":null,"스킬":"N2"},{"제목":"자연수가 되는 n 의 값","고비":true,"힌트":"$\\dfrac{4}{n}$ 가 정수가 되는 자연수 $n$ 은 모두 몇 개일까?","식":["$n\\mid 4$","$n=1,\\ 2,\\ 4$","$8-\\dfrac{4}{n}=4,\\ 6,\\ 7$"],"설명":"$8-\\dfrac{4}{n}$ 이 자연수이려면 $\\dfrac{4}{n}$ 이 정수여야 하므로 $n$ 은 $4$ 의 약수이다. 세 값 모두 식의 값이 자연수이다.","확인":"3","스킬":"N2"},{"제목":"집합 X 의 원소의 곱","힌트":"$X=\\{1,\\ 2,\\ 4\\}$ 의 모든 원소의 곱은?","식":["$1\\times 2\\times 4=8$"],"설명":"세 원소를 모두 곱한다.","확인":"8","스킬":"N2"}]},"ns-5d44be82e7e9":{"길":"접선 방향과 원둘레만큼의 이동으로 중심의 새 위치를 구한다","단계":[{"제목":"접선 l 의 기울기","힌트":"접선은 접점을 지나는 반지름 $\\mathrm{OA}$ 와 수직이다. $\\mathrm{OA}$ 의 기울기는?","식":["$\\dfrac{-2-0}{1-0}=-2$","$-2\\times m=-1,\\ m=\\dfrac{1}{2}$"],"설명":"접선의 기울기와 접점을 지나는 반지름의 기울기의 곱은 $-1$ 이다.","확인":"1/2","스킬":"G9"},{"제목":"원이 한 바퀴 굴러 간 거리","힌트":"한 바퀴 굴러 간 거리는 원의 둘레와 같다. 반지름 $\\overline{\\mathrm{OA}}$ 로 둘레를 구하면?","식":["$r=\\overline{\\mathrm{OA}}=\\sqrt{1^{2}+(-2)^{2}}=\\sqrt{5}$","$2\\pi r=2\\sqrt{5}\\pi$"],"설명":"미끄러지지 않고 한 바퀴 구르면 중심이 직선을 따라 움직인 거리가 원의 둘레와 같다.","확인":null,"스킬":"S5"},{"제목":"중심 O₁ 의 좌표","고비":true,"힌트":"기울기가 $\\dfrac{1}{2}$ 인 방향으로 $2\\sqrt{5}\\pi$ 만큼 가면 $x$ 방향으로 얼마나 이동할까?","식":["$\\left(\\dfrac{2}{\\sqrt{5}},\\ \\dfrac{1}{\\sqrt{5}}\\right)$","$\\mathrm{O}_{1}=\\left(2\\sqrt{5}\\pi\\times\\dfrac{2}{\\sqrt{5}},\\ 2\\sqrt{5}\\pi\\times\\dfrac{1}{\\sqrt{5}}\\right)=(4\\pi,\\ 2\\pi)$"],"설명":"중심은 $l$ 과 평행하게 이동한다. 기울기 $\\frac{1}{2}$ 인 방향은 $x$ 방향으로 $2$, $y$ 방향으로 $1$ 씩 가는 방향이고 그 길이는 $\\sqrt{5}$ 이다. 이동 거리를 이 길이로 나눈 비율을 곱하면 각 좌표의 이동량이 나온다. 처음 중심은 원점이다.","확인":null,"스킬":"S4"},{"제목":"a+b 의 값","힌트":"$a=4\\pi$, $b=2\\pi$ 를 더하면?","식":["$a+b=4\\pi+2\\pi=6\\pi$"],"설명":"중심의 좌표 $(a,\\ b)$ 의 두 값을 더한다.","확인":null,"스킬":"S4"}]},"ns-6101a67c3b20":{"길":"닮음 때문에 PQ 가 PB 에 비례함을 보고 지름일 때를 찾는다","단계":[{"제목":"교점 A, B 의 좌표","힌트":"$x=0$ 을 $\\mathrm{C}_{1}$ 의 방정식에 대입해 $\\mathrm{A}$ 의 $y$ 좌표를 구하면?","식":["$(0+6)^{2}+y^{2}=10^{2}$","$y=\\pm 8$","$\\mathrm{A}(0,\\ 8),\\ \\mathrm{B}(0,\\ -8)$"],"설명":"두 교점이 $y$ 축 위에 있으므로 $x=0$ 이다. 그림에서 $\\mathrm{A}$ 는 $y$ 축의 양의 부분에 있다.","확인":"8","스킬":"G1"},{"제목":"삼각형 PBQ 의 모양","고비":true,"힌트":"$\\mathrm{P}$ 가 $\\mathrm{C}_{1}$ 위에서 움직여도 $\\angle \\mathrm{APB}$, $\\angle \\mathrm{AQB}$ 는 어떻게 될까?","식":["$\\angle \\mathrm{APB}=\\angle \\mathrm{AP'B},\\ \\angle \\mathrm{AQB}=\\angle \\mathrm{AQ'B}$","$\\triangle \\mathrm{PBQ}\\sim\\triangle \\mathrm{P'BQ'}$"],"설명":"같은 호에 대한 원주각은 같으므로 $\\mathrm{P}$ 가 움직여도 $\\triangle \\mathrm{PBQ}$ 의 두 각이 변하지 않는다. 따라서 모든 $\\triangle \\mathrm{PBQ}$ 는 서로 닮음이고 $\\overline{\\mathrm{PQ}}$ 는 $\\overline{\\mathrm{PB}}$ 에 비례한다.","확인":null,"스킬":"S1"},{"제목":"PQ 가 최대가 되는 경우","힌트":"$\\overline{\\mathrm{PQ}}$ 가 $\\overline{\\mathrm{PB}}$ 에 비례한다면 $\\overline{\\mathrm{PB}}$ 가 가장 길 때는 언제일까?","식":["$\\overline{\\mathrm{PB}}=2\\times 10=20$","$\\angle \\mathrm{PAB}=\\angle \\mathrm{BAQ}=90^\\circ$","$\\overline{\\mathrm{BQ}}=2\\times 17=34$"],"설명":"$\\overline{\\mathrm{PB}}$ 는 $\\mathrm{C}_{1}$ 의 지름일 때 가장 길다. 이때 $\\angle \\mathrm{PAB}=90^\\circ$ 이고 $\\mathrm{P}$, $\\mathrm{A}$, $\\mathrm{Q}$ 가 한 직선 위에 있으므로 $\\angle \\mathrm{BAQ}=90^\\circ$ 이다. 따라서 $\\overline{\\mathrm{BQ}}$ 는 $\\mathrm{C}_{2}$ 의 지름이다.","확인":null,"스킬":"S5"},{"제목":"P, Q 의 좌표","힌트":"$\\mathrm{B}(0,\\ -8)$ 과 $\\mathrm{C}_{2}$ 의 중심 $(15,\\ 0)$ 을 이용해 $\\mathrm{Q}$ 의 $x$ 좌표를 구하면?","식":["$\\mathrm{P}=(2\\times(-6)-0,\\ 2\\times 0-(-8))=(-12,\\ 8)$","$\\mathrm{Q}=(2\\times 15-0,\\ 2\\times 0-(-8))=(30,\\ 8)$"],"설명":"$\\mathrm{C}_{1}$ 의 중심 $(-6,\\ 0)$ 은 $\\overline{\\mathrm{PB}}$ 의 중점이고, $\\mathrm{C}_{2}$ 의 중심 $(15,\\ 0)$ 은 $\\overline{\\mathrm{BQ}}$ 의 중점이다.","확인":"30","스킬":"S4"},{"제목":"PQ 의 최댓값","힌트":"$\\mathrm{P}$ 와 $\\mathrm{Q}$ 의 $y$ 좌표가 같으므로 두 점 사이의 거리는?","식":["$\\overline{\\mathrm{PQ}}=30-(-12)=42$"],"설명":"두 점은 모두 직선 $y=8$ 위에 있으므로 거리는 $x$ 좌표의 차이다. 이 직선은 $\\mathrm{A}$ 를 지난다.","확인":"42","스킬":"S5"}]},"ns-635683fd7ed2":{"길":"접점 A, B 가 두 원의 교점임을 이용해 공통현의 식을 얻는다","단계":[{"제목":"접선의 길이 CA","힌트":"직각삼각형 $\\mathrm{OAC}$ 에서 $\\overline{\\mathrm{CA}}^{2}$ 을 구하면?","식":["$\\overline{\\mathrm{OC}}^{2}=c^{2}+d^{2},\\ \\overline{\\mathrm{OA}}^{2}=5$","$\\overline{\\mathrm{CA}}^{2}=c^{2}+d^{2}-5$"],"설명":"접점 $\\mathrm{A}$ 에서 반지름 $\\mathrm{OA}$ 와 접선 $\\mathrm{CA}$ 는 수직이므로 직각삼각형 $\\mathrm{OAC}$ 에서 피타고라스 정리를 쓴다. $\\mathrm{C}$ 는 원 밖의 점이므로 $c^{2}+d^{2}>5$ 이다.","확인":null,"스킬":"S3"},{"제목":"A, B 를 지나는 또 다른 원","힌트":"$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CB}}$ 이면 $\\mathrm{A}$, $\\mathrm{B}$ 는 점 $\\mathrm{C}$ 를 중심으로 하는 어떤 원 위에 있을까?","식":["$(x-c)^{2}+(y-d)^{2}=c^{2}+d^{2}-5$","$x^{2}+y^{2}-2cx-2dy=-5$"],"설명":"한 점에서 그은 두 접선의 길이는 같으므로 $\\mathrm{A}$, $\\mathrm{B}$ 는 중심이 $\\mathrm{C}$ 이고 반지름이 $\\sqrt{c^{2}+d^{2}-5}$ 인 원 위에도 있다. 전개하면 $c^{2}+d^{2}$ 이 양변에서 사라진다.","확인":null,"스킬":"S5"},{"제목":"두 원의 공통현","고비":true,"힌트":"$x^{2}+y^{2}=5$ 를 위 식에 대입하면 $\\mathrm{A}$, $\\mathrm{B}$ 가 만족하는 직선은?","식":["$5-2cx-2dy=-5$","$cx+dy=5$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$ 는 두 원의 교점이므로 두 식을 모두 만족한다. 이차항을 $5$ 로 바꾸면 $x$, $y$ 의 일차식만 남고 이것이 직선 $\\mathrm{AB}$ 의 방정식이다.","확인":null,"스킬":"G1"}]},"ns-6385c7e88447":{"길":"원 밖의 점에서 그은 직선의 길이의 곱을 접선의 길이로 바꾼다","단계":[{"제목":"원 밖의 점에서 그은 두 선분의 길이의 곱","고비":true,"힌트":"$\\mathrm{A}$ 에서 원에 접선을 그어 접점을 $\\mathrm{T}$ 라 하면 $\\overline{\\mathrm{AB}}\\times\\overline{\\mathrm{AC}}$ 는 어떤 길이와 관계가 있을까?","식":["$\\overline{\\mathrm{AB}}\\times\\overline{\\mathrm{AC}}=\\overline{\\mathrm{AT}}^{2}$"],"설명":"원 밖의 점 $\\mathrm{A}$ 를 지나는 직선이 원과 두 점 $\\mathrm{B}$, $\\mathrm{C}$ 에서 만나면 $\\overline{\\mathrm{AB}}\\times\\overline{\\mathrm{AC}}$ 는 접선의 길이의 제곱과 같다. 교점 $\\mathrm{B}$, $\\mathrm{C}$ 를 직접 구하지 않아도 된다.","확인":null,"스킬":"S5"},{"제목":"점 A 와 원의 중심 사이 거리의 제곱","힌트":"$\\mathrm{A}$ 는 $y$ 절편이므로 $\\mathrm{A}(0,\\ 5)$ 이다. 원의 중심 $\\mathrm{O}(5,\\ 4)$ 까지의 거리의 제곱은?","식":["$\\overline{\\mathrm{OA}}^{2}=5^{2}+(4-5)^{2}=26$"],"설명":"$26>3^{2}$ 이므로 $\\mathrm{A}$ 는 원 밖의 점이다.","확인":"26","스킬":"S3"},{"제목":"접선의 길이의 제곱","힌트":"직각삼각형 $\\mathrm{OTA}$ 에서 $\\overline{\\mathrm{AT}}^{2}$ 은?","식":["$\\overline{\\mathrm{AT}}^{2}=\\overline{\\mathrm{OA}}^{2}-r^{2}=26-3^{2}=17$","$\\overline{\\mathrm{AB}}\\times\\overline{\\mathrm{AC}}=17$"],"설명":"접점에서 반지름과 접선은 수직이므로 피타고라스 정리를 쓴다. 반지름은 $r=3$ 이다.","확인":"17","스킬":"S3"}]},"ns-674faa93725e":{"길":"직선의 식을 먼저 구하고 중심까지의 거리에 반지름을 더하고 뺀다","단계":[{"제목":"직선의 기울기","힌트":"$\\mathrm{A}(8,\\ -1)$, $\\mathrm{B}(11,\\ 5)$ 를 지나는 직선의 기울기는?","식":["$\\dfrac{5-(-1)}{11-8}=2$"],"설명":"두 점의 $y$ 좌표의 차를 $x$ 좌표의 차로 나눈다.","확인":"2","스킬":"G9"},{"제목":"직선의 방정식","힌트":"기울기가 $2$ 이고 $\\mathrm{A}$ 를 지나는 직선의 식은?","식":["$y+1=2(x-8)$","$y=2x-17$"],"설명":"한 점과 기울기를 알면 점-기울기 꼴로 쓸 수 있다.","확인":null,"스킬":"G3"},{"제목":"중심에서 직선까지의 거리","고비":true,"힌트":"원의 중심 $(3,\\ 4)$ 에서 직선 $2x-y-17=0$ 까지의 거리는?","식":["$\\dfrac{|2\\times 3-4-17|}{\\sqrt{2^{2}+(-1)^{2}}}=\\dfrac{15}{\\sqrt{5}}=3\\sqrt{5}$"],"설명":"$3\\sqrt{5}$ 는 약 $6.7$ 이고 반지름 $5$ 보다 크므로 직선은 원과 만나지 않는다. 따라서 원 위의 점과 직선 사이 거리의 최댓값과 최솟값은 중심까지의 거리에 반지름을 더하거나 뺀 값이다.","확인":null,"스킬":"G2"},{"제목":"거리의 최댓값과 최솟값","힌트":"중심에서 직선까지의 거리에 반지름을 더하고 빼면?","식":["$3\\sqrt{5}+5$","$3\\sqrt{5}-5$"],"설명":"직선에서 가장 먼 원 위의 점은 중심의 반대쪽에 있고 가장 가까운 점은 중심 쪽에 있다.","확인":null,"스킬":"S13"}]},"ns-67aeaa89ba06":{"길":"두 부등식의 영역을 원의 안팎으로 읽어 넓이를 뺀다","단계":[{"제목":"두 부등식이 나타내는 영역","힌트":"$x^{2}+y^{2}\\le 36$ 과 $x^{2}+(y+3)^{2}\\ge 9$ 는 각각 원의 안쪽일까 바깥쪽일까?","식":["$x^{2}+y^{2}\\le 6^{2}$","$x^{2}+(y+3)^{2}\\ge 3^{2}$"],"설명":"첫째 식은 중심이 원점이고 반지름이 $6$ 인 원의 내부와 경계이다. 둘째 식은 중심이 $(0,\\ -3)$ 이고 반지름이 $3$ 인 원의 외부와 경계이다.","확인":null,"스킬":"G6"},{"제목":"작은 원의 위치","고비":true,"힌트":"두 원의 중심 사이의 거리와 반지름의 차를 비교하면 두 원은 어떤 관계일까?","식":["$\\overline{\\mathrm{OO'}}=3=6-3$"],"설명":"중심 사이의 거리가 두 반지름의 차와 같으므로 작은 원은 큰 원에 안쪽으로 접한다. 작은 원의 내부는 모두 큰 원 안에 들어 있다.","확인":null,"스킬":"S5"},{"제목":"영역의 넓이","힌트":"큰 원의 넓이에서 작은 원의 넓이를 빼면?","식":["$6^{2}\\pi-3^{2}\\pi=27\\pi$"],"설명":"구하는 영역은 큰 원에서 작은 원의 내부를 뺀 부분이다. 경계선은 넓이에 영향을 주지 않는다.","확인":null,"스킬":"G6"}]},"ns-68af4faa6f15":{"길":"넓이를 4등분하는 두 직선은 중심을 지나 서로 수직임을 쓴다","단계":[{"제목":"원의 중심과 4등분의 조건","고비":true,"힌트":"원의 넓이를 $4$ 등분하는 두 직선은 모두 어떤 점을 지나고 서로 어떤 관계일까?","식":["$(x-2)^{2}+(y-3)^{2}=1$","$\\mathrm{O}(2,\\ 3)$"],"설명":"원의 방정식을 완전제곱식으로 고치면 중심이 $(2,\\ 3)$ 이다. 두 직선이 넓이를 $4$ 등분하려면 둘 다 중심을 지나고 서로 수직이어야 한다.","확인":null,"스킬":"S5"},{"제목":"p 의 값","힌트":"$y=px$ 가 중심 $(2,\\ 3)$ 을 지난다는 식은?","식":["$3=2p$","$p=\\dfrac{3}{2}$"],"설명":"직선 $y=px$ 에 중심의 좌표를 대입한다.","확인":"3/2","스킬":"G9"},{"제목":"q 의 값","힌트":"두 직선이 수직이면 기울기의 곱은 얼마일까?","식":["$p\\times q=-1$","$q=-\\dfrac{2}{3}$"],"설명":"수직인 두 직선의 기울기의 곱은 $-1$ 이다.","확인":"-2/3","스킬":"G9"},{"제목":"r 의 값","힌트":"$y=-\\dfrac{2}{3}x+r$ 이 중심 $(2,\\ 3)$ 을 지난다는 식은?","식":["$3=-\\dfrac{2}{3}\\times 2+r$","$r=\\dfrac{13}{3}$"],"설명":"이 직선도 중심을 지나므로 중심의 좌표를 대입해 $r$ 을 구한다.","확인":"13/3","스킬":"G3"},{"제목":"p+q+r 의 값","힌트":"세 값을 통분해 더하면?","식":["$\\dfrac{3}{2}-\\dfrac{2}{3}+\\dfrac{13}{3}=\\dfrac{9-4+26}{6}=\\dfrac{31}{6}$"],"설명":"분모를 $6$ 으로 통분해 분자끼리 계산한다.","확인":"31/6","스킬":"G9"}]},"ns-6bc47b5aba4c":{"길":"거리의 비가 일정한 점의 자취를 원으로 잡고 보기를 하나씩 따진다","단계":[{"제목":"점 P 의 자취의 지름의 양 끝","힌트":"$\\overline{\\mathrm{AB}}$ 를 $2:3$ 으로 내분하는 점의 $x$ 좌표는?","식":["$\\left(\\dfrac{2\\times 2+3\\times(-3)}{2+3},\\ \\dfrac{2\\times 1+3\\times 1}{2+3}\\right)=(-1,\\ 1)$","$\\left(\\dfrac{2\\times 2-3\\times(-3)}{2-3},\\ \\dfrac{2\\times 1-3\\times 1}{2-3}\\right)=(-13,\\ 1)$"],"설명":"두 점 $\\mathrm{A}$, $\\mathrm{B}$ 까지의 거리의 비가 일정한 점은 아폴로니우스의 원 위에 있다. 이 원은 $\\overline{\\mathrm{AB}}$ 를 $2:3$ 으로 내분하는 점과 외분하는 점을 지름의 양 끝으로 한다.","확인":"-1","스킬":"S5"},{"제목":"ㄱ 판정: 자취의 방정식","힌트":"지름의 양 끝 $(-1,\\ 1)$, $(-13,\\ 1)$ 로 중심과 반지름을 구하면?","식":["$\\left(\\dfrac{-1-13}{2},\\ \\dfrac{1+1}{2}\\right)=(-7,\\ 1)$","$r=\\dfrac{-1-(-13)}{2}=6$","$(x+7)^{2}+(y-1)^{2}=36$"],"설명":"중심은 두 끝점의 중점이고 반지름은 두 끝점 사이 거리의 절반이다. 얻은 식이 보기 ㄱ 과 같으므로 ㄱ 은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 판정: 삼각형 PAB 의 넓이의 최댓값","힌트":"밑변 $\\overline{\\mathrm{AB}}=5$ 일 때 높이의 최댓값은 얼마일까?","식":["$h_{\\max}=6$","$\\dfrac{1}{2}\\times 5\\times 6=15$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$ 는 직선 $y=1$ 위에 있고 원의 중심 $(-7,\\ 1)$ 도 이 직선 위에 있다. 따라서 원 위의 점에서 직선 $\\mathrm{AB}$ 까지의 거리의 최댓값은 반지름 $6$ 이다. 최대 넓이 $15$ 는 보기의 $30$ 과 다르므로 ㄴ 은 옳지 않다.","확인":"15","스킬":"S8"},{"제목":"ㄷ 판정: 직선 BP 의 기울기의 최솟값","고비":true,"힌트":"$\\mathrm{B}$ 를 지나는 직선 $mx-y-2m+1=0$ 이 원에 접할 때 중심까지의 거리 조건은?","식":["$\\dfrac{|-7m-1-2m+1|}{\\sqrt{m^{2}+1}}=\\dfrac{|-9m|}{\\sqrt{m^{2}+1}}=6$","$81m^{2}=36(m^{2}+1)$","$m=\\pm\\dfrac{2\\sqrt{5}}{5}$"],"설명":"직선 $\\mathrm{BP}$ 의 기울기가 가장 크거나 가장 작은 때는 직선이 원에 접할 때이다. $\\mathrm{B}$ 는 원의 중심에서 $9$ 만큼 떨어져 원 밖에 있다. 기울기의 최솟값은 $-\\dfrac{2\\sqrt{5}}{5}$ 이므로 ㄷ 은 옳다. 따라서 옳은 것은 ㄱ, ㄷ 이다.","확인":null,"스킬":"G2"}]},"ns-6f58b10fa655":{"길":"가장 짧은 현과 지름 사이의 정수 길이마다 현의 개수를 센다","단계":[{"제목":"가장 짧은 현의 길이","힌트":"$\\mathrm{OP}$ 에 수직인 현의 반 길이의 제곱은 얼마일까?","식":["$\\overline{\\mathrm{OP}}=3$","$\\left(\\dfrac{l}{2}\\right)^{2}=4^{2}-3^{2}=7$","$l=2\\sqrt{7}\\approx 5.3$"],"설명":"점 $\\mathrm{P}$ 를 지나는 현 중에서 중심 $\\mathrm{O}$ 에서 가장 먼 현이 가장 짧다. 중심에서 현까지의 거리는 $\\overline{\\mathrm{OP}}$ 이하이고, 같을 때가 현이 $\\mathrm{OP}$ 에 수직일 때이다.","확인":"7","스킬":"S5"},{"제목":"정수가 될 수 있는 현의 길이","힌트":"가장 긴 현은 지름 $8$ 이다. $2\\sqrt{7}$ 과 $8$ 사이의 정수는 모두 몇 개일까?","식":["$5<2\\sqrt{7}<6$","$2\\sqrt{7}\\le l\\le 8$","$l=6,\\ 7,\\ 8$"],"설명":"$2\\sqrt{7}=\\sqrt{28}$ 이고 $25<28<36$ 이므로 $5<2\\sqrt{7}<6$ 이다. 따라서 정수 길이는 $6$, $7$, $8$ 이다.","확인":"3","스킬":"S5"},{"제목":"길이별 현의 개수","고비":true,"힌트":"점 $\\mathrm{P}$ 를 지나는 현은 길이마다 $x$ 축에 대칭으로 몇 개씩 생길까?","식":["$6\\to 2,\\ 7\\to 2,\\ 8\\to 1$","$2+2+1=5$"],"설명":"점 $\\mathrm{P}$ 를 지나는 현의 길이는 가장 짧은 현에서 지름까지 변한다. 지름이 아닌 길이마다 $x$ 축에 대칭인 현이 $2$ 개씩 있고 지름은 $x$ 축 하나뿐이다. 따라서 $2+2+1=5$ 이다.","확인":"5","스킬":"S2"}]},"ns-72283b1788f4":{"길":"접선 방향으로 원둘레만큼 이동한 중심의 좌표를 구한다","단계":[{"제목":"접선 l 의 기울기와 방정식","힌트":"접점 $\\mathrm{T}(3,\\ -4)$ 에서 접선의 기울기는 반지름 $\\mathrm{OT}$ 의 기울기와 어떤 관계일까?","식":["$\\dfrac{-4}{3}\\times m=-1,\\ m=\\dfrac{3}{4}$","$3x-4y-25=0$"],"설명":"접선과 접점을 지나는 반지름은 수직이므로 기울기의 곱이 $-1$ 이다. 원 $x^{2}+y^{2}=25$ 위의 점 $(3,\\ -4)$ 를 지나는 접선이므로 $l$ 은 $3x-4y-25=0$ 이다.","확인":"3/4","스킬":"G9"},{"제목":"원이 한 바퀴 굴러 간 거리","힌트":"반지름이 $5$ 인 원이 한 바퀴 굴러 가면 중심이 움직인 거리는?","식":["$\\overline{\\mathrm{OO_1}}=2\\pi\\times 5=10\\pi$"],"설명":"미끄러지지 않고 한 바퀴 구르면 접점이 $l$ 위에서 원의 둘레 $10\\pi$ 만큼 움직인다. 중심은 $l$ 과 평행하게 같은 거리를 이동하므로 $\\overline{\\mathrm{OO_1}}=10\\pi$ 이다.","확인":null,"스킬":"S5"},{"제목":"중심 O₁ 의 좌표","고비":true,"힌트":"$\\overline{\\mathrm{OO_1}}$ 의 기울기가 $\\dfrac{3}{4}$ 이고 길이가 $10\\pi$ 일 때 $a$ 는?","식":["$\\sqrt{a^{2}+b^{2}}=10\\pi,\\ \\dfrac{b}{a}=\\dfrac{3}{4}$","$a=8\\pi,\\ b=6\\pi$"],"설명":"중심은 $l$ 과 평행하게 이동하므로 $\\overline{\\mathrm{OO_1}}$ 의 기울기도 $\\dfrac{3}{4}$ 이다. $b=\\dfrac{3}{4}a$ 를 길이의 식에 넣으면 $\\dfrac{25}{16}a^{2}=100\\pi^{2}$ 이고 $a>0$ 이므로 $a=8\\pi$ 이다.","확인":null,"스킬":"S4"},{"제목":"a+b 의 값","힌트":"$a=8\\pi$, $b=6\\pi$ 를 더하면?","식":["$a+b=8\\pi+6\\pi=14\\pi$"],"설명":"중심의 좌표 $(a,\\ b)$ 의 두 값을 더한다.","확인":null,"스킬":"S4"}]},"ns-72a2f597b59e":{"길":"두 거리 조건으로 접선 y=mx+n 의 m 과 n 을 연립한다","단계":[{"제목":"중심과 접선 l 사이의 거리","힌트":"작은 원의 반지름 $4$ 와 반현 $2\\sqrt{3}$ 의 직각삼각형에서 중심 $(-6,\\ 0)$ 에서 $l$ 까지의 거리는?","식":["$\\left(\\dfrac{\\overline{\\mathrm{AB}}}{2}\\right)^{2}=(2\\sqrt{3})^{2}=12$","$d=\\sqrt{4^{2}-12}=2$"],"설명":"현의 중점과 원의 중심을 잇는 선분은 현에 수직이다. 반지름이 빗변인 직각삼각형에서 피타고라스 정리를 쓴다.","확인":"2","스킬":"S5"},{"제목":"접선 l 의 식","힌트":"$l:\\ mx-y+n=0$ 이 원점에서 거리 $6$ 인 접선이 되는 조건은?","식":["$\\dfrac{|n|}{\\sqrt{m^{2}+1}}=6$","$n=6\\sqrt{m^{2}+1}$"],"설명":"$l$ 은 원 $x^{2}+y^{2}=36$ 의 접선이므로 원점에서 $l$ 까지의 거리가 반지름 $6$ 이다. 그림에서 $l$ 은 오른쪽 위로 올라가고 $y$ 절편이 양수이므로 $m>0$, $n>0$ 이다.","확인":null,"스킬":"G2"},{"제목":"중심까지의 두 번째 거리 조건","고비":true,"힌트":"$n=6\\sqrt{m^{2}+1}$ 을 $\\dfrac{|-6m+n|}{\\sqrt{m^{2}+1}}=2$ 에 대입하면?","식":["$|6\\sqrt{m^{2}+1}-6m|=2\\sqrt{m^{2}+1}$","$3m=2\\sqrt{m^{2}+1}$"],"설명":"$\\sqrt{m^{2}+1}>m$ 이므로 절댓값 안은 양수이다. $6\\sqrt{m^{2}+1}-6m=2\\sqrt{m^{2}+1}$ 을 정리하면 $6m=4\\sqrt{m^{2}+1}$ 이다.","확인":null,"스킬":"G2"},{"제목":"m² 의 값","힌트":"$3m=2\\sqrt{m^{2}+1}$ 의 양변을 제곱해 $m^{2}$ 을 구하면?","식":["$9m^{2}=4(m^{2}+1)$","$m^{2}=\\dfrac{4}{5}$"],"설명":"양변이 모두 양수이므로 제곱해도 같은 식이다. $5m^{2}=4$ 이다.","확인":"4/5","스킬":"S5"},{"제목":"직선 l 의 기울기","힌트":"$m>0$ 일 때 $m^{2}=\\dfrac{4}{5}$ 의 해는?","식":["$m=\\sqrt{\\dfrac{4}{5}}=\\dfrac{2\\sqrt{5}}{5}$"],"설명":"$m>0$ 이므로 양의 제곱근만 취하고 분모를 유리화한다.","확인":null,"스킬":"S5"}]},"ns-748df547006d":{"길":"영역의 꼭짓점과 원점에서 직선까지의 최단 거리로 최대·최소를 찾는다","단계":[{"제목":"영역의 꼭짓점","힌트":"세 경계선 $x=2$, $y=2$, $x+y=2$ 가 만드는 삼각형의 꼭짓점은?","식":["$x=2,\\ x+y=2\\Rightarrow (2,\\ 0)$","$y=2,\\ x+y=2\\Rightarrow (0,\\ 2)$","$x=2,\\ y=2\\Rightarrow (2,\\ 2)$"],"설명":"$x\\le 2$, $y\\le 2$ 이고 $x+y\\ge 2$ 이므로 영역은 직선 $x+y=2$ 의 위쪽에 있는 삼각형이다.","확인":null,"스킬":"G6"},{"제목":"최댓값 a","힌트":"$x^{2}+y^{2}$ 은 원점까지 거리의 제곱이다. 원점에서 가장 먼 꼭짓점에서의 값은?","식":["$2^{2}+2^{2}=8$"],"설명":"삼각형 영역에서 원점으로부터 가장 먼 점은 꼭짓점이다. 세 꼭짓점 중 $(2,\\ 2)$ 가 가장 멀다.","확인":"8","스킬":"G6"},{"제목":"최솟값을 갖는 점","고비":true,"힌트":"원점에서 직선 $x+y=2$ 에 내린 수선의 발의 $x$ 좌표는?","식":["$y=x,\\ x+y=2\\Rightarrow (1,\\ 1)$","$b=1^{2}+1^{2}=2$"],"설명":"원점에서 가장 가까운 점은 원점에서 직선 $x+y=2$ 에 내린 수선의 발이다. 이 점 $(1,\\ 1)$ 은 두 꼭짓점 $(2,\\ 0)$, $(0,\\ 2)$ 사이의 변 위에 있으므로 영역에 포함된다.","확인":"1","스킬":"G6"},{"제목":"a+b 의 값","힌트":"최댓값과 최솟값을 더하면?","식":["$a+b=8+2=10$"],"설명":"앞에서 구한 두 값을 더한다.","확인":"10","스킬":"G6"}]},"ns-7a2053b4b9ef":{"길":"수선의 발로 PQ 를 중심 사이 거리와 비교해 최댓값을 구한다","단계":[{"제목":"두 원의 중심 사이의 거리","힌트":"$\\mathrm{C}_{1}$ 의 중심 $\\mathrm{O}_{1}(-6,\\ 0)$ 과 $\\mathrm{C}_{2}$ 의 중심 $\\mathrm{O}_{2}(15,\\ 0)$ 사이의 거리는?","식":["$\\overline{\\mathrm{O_1O_2}}=15-(-6)=21$"],"설명":"두 중심이 모두 $x$ 축 위에 있으므로 $x$ 좌표의 차가 거리이다.","확인":"21","스킬":"S5"},{"제목":"PQ 와 수선의 발 사이의 길이","힌트":"$\\mathrm{O}_{1}$, $\\mathrm{O}_{2}$ 에서 직선 $\\mathrm{PQ}$ 에 내린 수선의 발 $\\mathrm{M}$, $\\mathrm{N}$ 은 각각 현 $\\mathrm{PA}$, $\\mathrm{AQ}$ 의 어디에 있을까?","식":["$\\mathrm{M}=\\dfrac{p}{2},\\ \\mathrm{N}=\\dfrac{q}{2}$","$\\overline{\\mathrm{MN}}=\\dfrac{|q-p|}{2}=\\dfrac{\\overline{\\mathrm{PQ}}}{2}$"],"설명":"중심에서 현에 내린 수선의 발은 현의 중점이므로 $\\mathrm{M}$, $\\mathrm{N}$ 은 $\\overline{\\mathrm{PA}}$, $\\overline{\\mathrm{AQ}}$ 의 중점이다. 직선 $\\mathrm{PQ}$ 를 수직선으로 보고 $\\mathrm{A}$ 를 원점, $\\mathrm{P}$, $\\mathrm{Q}$ 의 좌표를 $p$, $q$ 라 하면 $\\mathrm{M}$, $\\mathrm{N}$ 의 좌표는 $\\dfrac{p}{2}$, $\\dfrac{q}{2}$ 이다.","확인":null,"스킬":"S2"},{"제목":"MN 과 중심 사이의 거리의 비교","고비":true,"힌트":"$\\overline{\\mathrm{MN}}$ 과 $\\overline{\\mathrm{O_1O_2}}$ 중 어느 쪽이 더 길거나 같을까?","식":["$\\overline{\\mathrm{MN}}\\le\\overline{\\mathrm{O_1O_2}}=21$","$\\overline{\\mathrm{PQ}}=2\\overline{\\mathrm{MN}}\\le 42$"],"설명":"$\\mathrm{O_1}$ 에서 $\\overline{\\mathrm{O_2N}}$ 에 수선을 그으면 빗변이 $\\overline{\\mathrm{O_1O_2}}$ 이고 한 변이 $\\overline{\\mathrm{MN}}$ 인 직각삼각형이 생긴다. 빗변은 다른 변보다 짧을 수 없으므로 $\\overline{\\mathrm{MN}}\\le\\overline{\\mathrm{O_1O_2}}$ 이고, 같아지는 것은 $\\mathrm{PQ}$ 가 $\\mathrm{O_1O_2}$ 와 평행할 때이다.","확인":null,"스킬":"S5"},{"제목":"최댓값이 실제로 나오는지 확인","힌트":"$\\mathrm{PQ}$ 가 $x$ 축과 평행하면 $\\overline{\\mathrm{PQ}}$ 는?","식":["$y=8:\\ \\mathrm{P}(-12,\\ 8),\\ \\mathrm{Q}(30,\\ 8)$","$\\overline{\\mathrm{PQ}}=30-(-12)=42$"],"설명":"$x=0$ 을 $\\mathrm{C}_{1}$ 에 대입하면 $\\mathrm{A}(0,\\ 8)$ 이다. $\\mathrm{A}$ 를 지나고 $x$ 축에 평행한 직선 $y=8$ 이 $\\mathrm{C}_{1}$ 과 만나는 다른 점은 $(-12,\\ 8)$ 이고 $\\mathrm{C}_{2}$ 와 만나는 다른 점은 $(30,\\ 8)$ 이다. 이 $\\mathrm{P}$ 는 $\\mathrm{A}$, $\\mathrm{B}$ 가 아니므로 등호가 성립한다.","확인":"42","스킬":"S5"}]},"ns-7e0ffa91a1d2":{"길":"중심에서 현에 내린 수선으로 직각삼각형을 만들어 거리를 구한다","단계":[{"제목":"중심에서 현까지의 거리","힌트":"현의 절반과 반지름으로 직각삼각형을 만들면 중심에서 현까지의 거리는?","식":["$\\overline{\\mathrm{AH}}=\\frac{1}{2}\\times 8=4$","$\\overline{\\mathrm{OH}}=\\sqrt{5^{2}-4^{2}}=3$"],"설명":"중심 $\\mathrm{O}$에서 현 $\\mathrm{AB}$에 내린 수선의 발 $\\mathrm{H}$는 현의 중점이다. 직각삼각형 $\\mathrm{OHA}$에서 빗변이 반지름 $5$, 한 변이 $4$이므로 $\\overline{\\mathrm{OH}}=3$이다.","확인":"3","스킬":"S5","고비":true},{"제목":"점과 직선 사이의 거리로 나타낸 OH","힌트":"중심 $(1,1)$과 직선 $x-y+k=0$ 사이의 거리를 $k$로 나타내면?","식":["$\\overline{\\mathrm{OH}}=\\frac{|1-1+k|}{\\sqrt{1^{2}+(-1)^{2}}}=\\frac{|k|}{\\sqrt{2}}$"],"설명":"직선 $y=x+k$를 $x-y+k=0$으로 고쳐 점과 직선 사이의 거리 공식에 중심 $(1,1)$을 대입한다.","확인":null,"스킬":"S4"},{"제목":"두 거리를 같게 놓아 구한 k","힌트":"$\\frac{|k|}{\\sqrt{2}}$가 앞에서 구한 거리와 같다고 놓으면 $k$는?","식":["$\\frac{|k|}{\\sqrt{2}}=3$","$|k|=3\\sqrt{2}$","$k=\\pm 3\\sqrt{2}$"],"설명":"절댓값 안의 값이 양수 또는 음수일 수 있으므로 $k$는 부호가 다른 두 값이다.","확인":null,"스킬":"C2"}]},"ns-8accb690f3ae":{"길":"AB의 기울기와 OE의 기울기가 수직임을 이용해 외접원의 지름을 찾는다","단계":[{"제목":"이등변삼각형의 꼭짓점 A와 점 B","힌트":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AO}}$이면 점 $\\mathrm{A}$의 $y$좌표와 $\\mathrm{B}$의 $y$좌표는 어떤 관계인가?","식":["$\\mathrm{A}(p,\\,q)$, $\\mathrm{B}(0,\\,2q)$","$\\mathrm{C}(q,\\,p)$"],"설명":"점 $\\mathrm{A}$는 선분 $\\mathrm{OB}$의 수직이등분선 위에 있으므로 $\\mathrm{B}$의 $y$좌표는 $\\mathrm{A}$의 $y$좌표의 $2$배이다. 직선 $y=x$에 대한 대칭이동은 $x$좌표와 $y$좌표를 서로 바꾼다.","확인":null,"스킬":"S5"},{"제목":"점 A의 좌표를 t와 m으로 나타내기","힌트":"$\\mathrm{C}$가 $y=mx$ 위에 있고 $\\overline{\\mathrm{AO}}=t\\sqrt{m^{2}+1}$이면 $p,\\,q$는?","식":["$p=mq$","$\\overline{\\mathrm{AO}}=q\\sqrt{m^{2}+1}$이므로 $q=t$","$\\mathrm{A}(mt,\\,t)$, $\\mathrm{B}(0,\\,2t)$"],"설명":"점 $\\mathrm{C}(q,\\,p)$를 $y=mx$에 대입하면 $p=mq$이다. 이를 $\\overline{\\mathrm{AO}}$에 넣으면 $q=t$이다.","확인":null,"스킬":"G9"},{"제목":"각 OED가 직각이므로 지름은 OD","힌트":"직선 $\\mathrm{AB}$의 기울기와 직선 $y=mx$의 기울기의 곱은?","식":["직선 $\\mathrm{AB}$의 기울기 $=\\frac{t-2t}{mt-0}=-\\frac{1}{m}$","$-\\frac{1}{m}\\times m=-1$","$\\angle\\mathrm{OED}=90^\\circ$"],"설명":"두 직선이 수직이므로 삼각형 $\\mathrm{ODE}$는 $\\angle\\mathrm{OED}=90^\\circ$인 직각삼각형이다. 직각의 대변인 $\\overline{\\mathrm{OD}}$가 외접원의 지름이다.","확인":null,"스킬":"S5","고비":true},{"제목":"점 D의 좌표와 지름 OD","힌트":"직선 $\\mathrm{AB}$와 $y=x$의 교점의 좌표는?","식":["직선 $\\mathrm{AB}$: $y=-\\frac{1}{m}x+2t$","$\\mathrm{D}\\left(\\frac{2mt}{m+1},\\,\\frac{2mt}{m+1}\\right)$","$\\overline{\\mathrm{OD}}=\\sqrt{2}\\times\\frac{2mt}{m+1}$"],"설명":"$y=x$를 직선 $\\mathrm{AB}$의 식에 대입하면 $x\\left(1+\\frac{1}{m}\\right)=2t$이다. $\\mathrm{D}$는 $y=x$ 위의 점이므로 원점까지의 거리는 $x$좌표의 $\\sqrt{2}$배이다.","확인":null,"스킬":"S4"},{"제목":"외접원의 넓이와 a+b+c","힌트":"반지름은 $\\overline{\\mathrm{OD}}$의 절반이다. 넓이를 $\\frac{cm^{2}}{m^{2}+am+b}t^{2}\\pi$ 꼴로 쓰면 $a,\\,b,\\,c$는?","식":["반지름 $=\\frac{\\sqrt{2}\\,mt}{m+1}$","넓이 $=\\frac{2m^{2}}{m^{2}+2m+1}t^{2}\\pi$","$a=2,\\ b=1,\\ c=2$","$a+b+c=5$"],"설명":"$\\pi r^{2}$에 반지름을 대입하고 분모 $(m+1)^{2}$을 전개해 주어진 꼴과 비교한다.","확인":"5","스킬":"A3"}]},"ns-8b3f6bae4a57":{"길":"두 직선이 수직이면 AC가 지름이고, D가 AC에서 가장 먼 점일 때 넓이가 최대다","단계":[{"제목":"세 교점 A, B, C의 좌표","힌트":"두 직선을 연립하면 교점 $\\mathrm{B}$의 $x$좌표는?","식":["$\\mathrm{A}(2,\\,0)$","$3x-6=-\\frac{1}{3}x+4$에서 $x=3$, $\\mathrm{B}(3,\\,3)$","$\\mathrm{C}(0,\\,4)$"],"설명":"$l$에 $y=0$을 대입하면 $\\mathrm{A}$, 두 직선을 연립하면 $\\mathrm{B}$, $m$에 $x=0$을 대입하면 $\\mathrm{C}$이다.","확인":"3","스킬":"G1"},{"제목":"수직인 두 직선과 원 K의 지름","힌트":"$l$과 $m$의 기울기의 곱은 얼마이고, 그러면 $\\angle\\mathrm{ABC}$는?","식":["$3\\times\\left(-\\frac{1}{3}\\right)=-1$","$\\angle\\mathrm{ABC}=90^\\circ$","$\\overline{\\mathrm{AC}}=\\sqrt{2^{2}+4^{2}}=2\\sqrt{5}$, 반지름 $\\sqrt{5}$"],"설명":"두 직선이 수직이므로 원주각 $\\angle\\mathrm{ABC}$가 직각이고, $\\overline{\\mathrm{AC}}$가 원 $K$의 지름이다.","확인":null,"스킬":"S5"},{"제목":"삼각형 ABC의 넓이","힌트":"$\\overline{\\mathrm{AB}}$와 $\\overline{\\mathrm{BC}}$의 길이를 구해 직각삼각형의 넓이를 구하면?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{1^{2}+3^{2}}=\\sqrt{10}$, $\\overline{\\mathrm{BC}}=\\sqrt{3^{2}+1^{2}}=\\sqrt{10}$","$\\triangle\\mathrm{ABC}=\\frac{1}{2}\\times\\sqrt{10}\\times\\sqrt{10}=5$"],"설명":"$\\angle\\mathrm{ABC}=90^\\circ$이므로 $\\overline{\\mathrm{AB}}$와 $\\overline{\\mathrm{BC}}$가 밑변과 높이이다.","확인":"5","스킬":"G10"},{"제목":"삼각형 ACD가 최대일 때의 사각형 넓이","힌트":"밑변 $\\overline{\\mathrm{AC}}$를 고정하면 $\\mathrm{D}$가 어디에 있을 때 높이가 가장 큰가?","식":["높이의 최댓값 $=$ 반지름 $\\sqrt{5}$","$\\triangle\\mathrm{ACD}\\le\\frac{1}{2}\\times 2\\sqrt{5}\\times\\sqrt{5}=5$","$\\square\\mathrm{ABCD}=\\triangle\\mathrm{ABC}+\\triangle\\mathrm{ACD}\\le 5+5=10$"],"설명":"$\\overline{\\mathrm{AC}}$가 지름이므로 중심이 $\\overline{\\mathrm{AC}}$ 위에 있다. 호 $\\mathrm{AC}$ 위의 점 중 $\\overline{\\mathrm{AC}}$에서 가장 먼 점까지의 거리는 반지름이다.","확인":"10","스킬":"G10","고비":true}]},"ns-8ba5448b0295":{"길":"원 C의 중심을 문자로 놓고 외접 조건으로 r을 구한 뒤 접선과 접점을 구한다","단계":[{"제목":"원 C의 중심과 반지름","힌트":"$y$축에 접하고 중심이 $y=\\sqrt{3}x$ 위에 있는 반지름 $r$인 원의 중심은?","식":["중심의 $x$좌표 $=r$","중심 $(r,\\,\\sqrt{3}r)$"],"설명":"$y$축에 접하면 중심의 $x$좌표는 반지름과 같다. 중심이 $y=\\sqrt{3}x$ 위에 있으므로 $y$좌표는 $\\sqrt{3}r$이다.","확인":null,"스킬":"S5"},{"제목":"외접 조건으로 구한 r","힌트":"두 원이 외접하면 중심 사이의 거리는 반지름의 합과 어떤 관계인가?","식":["$\\sqrt{r^{2}+(\\sqrt{3}r)^{2}}=2+r$","$2r=2+r$","$r=2$"],"설명":"외접하는 두 원의 중심 사이의 거리는 두 반지름의 합이다. $\\sqrt{4r^{2}}=2r$이므로 방정식이 간단해진다.","확인":"2","스킬":"S5"},{"제목":"접점 T와 접선, 점 A","힌트":"두 원의 반지름이 같으면 접점은 두 중심의 어디에 있고, 접선은 $\\mathrm{OT}$와 어떤 관계인가? 접선이 $x$축과 만나는 점의 $x$좌표는?","식":["중심 $(0,0)$, $(2,\\,2\\sqrt{3})$의 중점 $\\mathrm{T}(1,\\,\\sqrt{3})$","접선: $x+\\sqrt{3}y=4$","$\\mathrm{A}(4,\\,0)$"],"설명":"반지름이 같은 두 원이 외접하면 접점은 두 중심의 중점이다. 접선은 $\\mathrm{OT}$에 수직이므로 $x+\\sqrt{3}y=1+3$이다. $y=0$을 대입하면 $\\mathrm{A}$를 얻는다.","확인":"4","스킬":"S4","고비":true},{"제목":"AT의 길이와 r²+l²","힌트":"$\\mathrm{A}(4,0)$, $\\mathrm{T}(1,\\sqrt{3})$ 사이의 거리의 제곱과 $r^{2}$의 합은?","식":["$l=\\sqrt{(4-1)^{2}+(\\sqrt{3})^{2}}=2\\sqrt{3}$","$r^{2}+l^{2}=4+12=16$"],"설명":"두 점 사이의 거리를 구한 뒤 $r=2$와 함께 제곱의 합을 계산한다.","확인":"16","스킬":"S3"}]},"ns-92cbb0d9fc96":{"길":"보기마다 대입·중심·판별식·x축 교점으로 참거짓을 가린다","단계":[{"제목":"ㄱ, ㄴ의 참거짓","힌트":"점 $(-1,0)$을 대입하면 좌변은 $k$에 관계없이 얼마가 되고, 중심의 좌표는?","식":["$(-1)^{2}+0-2k(-1)-0-2k-1=0$","중심 $(k,\\,3k)$"],"설명":"$(-1,0)$을 대입하면 $k$가 모두 소거되어 식이 성립하므로 ㄱ은 참이다. 중심은 $(k,\\,3k)$로 $y=3x$ 위에 있으므로 ㄴ도 참이다.","확인":null,"스킬":"C1"},{"제목":"ㄷ: x축과 만나는 점","힌트":"$y=0$을 대입한 $x$에 대한 이차방정식의 판별식은?","식":["$x^{2}-2kx-2k-1=0$","$\\frac{D}{4}=k^{2}+2k+1=(k+1)^{2}$","$(x+1)\\{x-(2k+1)\\}=0$"],"설명":"$k>-\\frac{1}{2}$이면 $k+1>0$이므로 $\\frac{D}{4}>0$이다. 두 근 $-1$과 $2k+1$도 서로 다르므로 ㄷ은 참이다.","확인":null,"스킬":"G2"},{"제목":"ㄹ: 원이 지나는 사분면","힌트":"$x$축과 만나는 두 점의 $x$좌표 부호는 어떻게 되고, 위·아래 호는 $y$축을 지나는가?","식":["$x=-1<0$, $x=2k+1>0$","위쪽 호와 아래쪽 호가 모두 $y$축과 만난다"],"설명":"$x$축과 음수, 양수의 두 점에서 만나는 원은 $x$축 위쪽 호와 아래쪽 호가 각각 $y$축을 지난다. 그러므로 네 사분면을 모두 지나 ㄹ도 참이다.","확인":null,"스킬":"G7","고비":true},{"제목":"옳은 보기 모두 고르기","힌트":"ㄱ, ㄴ, ㄷ, ㄹ 중 거짓인 보기가 있는가?","식":["ㄱ 참, ㄴ 참, ㄷ 참, ㄹ 참"],"설명":"네 보기가 모두 참이므로 옳은 것만을 있는 대로 고르면 ㄱ, ㄴ, ㄷ, ㄹ이다.","확인":null,"스킬":"C3"}]},"ns-957807b92403":{"길":"최대는 가장 먼 꼭짓점까지 거리에 반지름을 더하고, 최소는 가까운 변까지 거리에서 뺀다","단계":[{"제목":"원의 중심과 반지름","힌트":"$x^{2}+y^{2}-6x-6y+13=0$을 완전제곱 꼴로 고치면 중심은?","식":["$(x-3)^{2}+(y-3)^{2}=5$","중심 $(3,\\,3)$, 반지름 $\\sqrt{5}$"],"설명":"$x$와 $y$에 대해 각각 완전제곱식을 만들어 중심과 반지름을 읽는다.","확인":null,"스킬":"A6"},{"제목":"최댓값 M","힌트":"마름모의 꼭짓점 중 원의 중심에서 가장 먼 점은?","식":["$\\mathrm{B}(-3,\\,0)$까지 거리 $=\\sqrt{(3+3)^{2}+3^{2}}=3\\sqrt{5}$","$M=3\\sqrt{5}+\\sqrt{5}=4\\sqrt{5}$"],"설명":"마름모 위의 점 중 중심에서 가장 먼 점은 꼭짓점 $\\mathrm{B}$이다. 거기에 반지름을 더하면 $\\overline{\\mathrm{PQ}}$의 최댓값이다.","확인":null,"스킬":"S4"},{"제목":"최솟값 m","힌트":"마름모에서 원의 중심에 가장 가까운 변은 어느 변이고, 직선의 방정식은?","식":["직선 $\\mathrm{AD}$: $x+3y-3=0$","거리 $=\\frac{|3+9-3|}{\\sqrt{10}}=\\frac{9\\sqrt{10}}{10}$","$m=\\frac{9\\sqrt{10}}{10}-\\sqrt{5}$"],"설명":"중심에서 변 $\\mathrm{AD}$에 내린 수선의 발은 선분 $\\mathrm{AD}$ 위에 있다. 이 거리에서 반지름을 빼면 최솟값이다.","확인":null,"스킬":"S4","고비":true},{"제목":"Mm의 계산과 a-b","힌트":"$M\\times m$을 전개해 $a\\sqrt{2}+b$ 꼴로 쓰면 $a$와 $b$는?","식":["$Mm=4\\sqrt{5}\\left(\\frac{9\\sqrt{10}}{10}-\\sqrt{5}\\right)=18\\sqrt{2}-20$","$a=18,\\ b=-20$","$a-b=38$"],"설명":"$\\sqrt{5}\\times\\sqrt{10}=5\\sqrt{2}$를 이용해 전개한다.","확인":"38","스킬":"A3"}]},"ns-97f83b7556ea":{"길":"직선이 지나는 정점을 먼저 보고 반원과 만나는 개수를 나누어 센다","단계":[{"제목":"태극문양을 이루는 원과 반원","힌트":"그림에서 큰 원과 두 반원의 중심과 반지름은 각각 무엇인가?","식":["큰 원: $x^{2}+y^{2}=4$","오른쪽 위 반원: 중심 $(1,\\,0)$, 반지름 $1$","왼쪽 아래 반원: 중심 $(-1,\\,0)$, 반지름 $1$"],"설명":"큰 원의 지름이 $4$이고 두 반원의 지름은 각각 $2$이다. 위 반원은 $y\\ge 0$ 부분, 아래 반원은 $y\\le 0$ 부분이다.","확인":null,"스킬":"S5"},{"제목":"정점을 지나는 직선과 이미 정해진 교점의 개수","힌트":"직선 $y=a(x+1)$은 $a$에 관계없이 어떤 점을 지나고, 그 점은 어떤 원의 중심인가? 위 반원과 만나야 하는 점은 몇 개인가?","식":["$(-1,\\,0)$을 지난다","큰 원과 $2$점, 아래 반원과 $1$점","위 반원과 만나야 하는 점의 개수 $=5-3$"],"설명":"$(-1,0)$은 큰 원의 내부이자 아래 반원의 중심이므로 큰 원과 두 점, 아래 반원과는 한 점에서 만난다. 따라서 위 반원과 서로 다른 두 점에서 만나야 한다.","확인":"2","스킬":"G3"},{"제목":"위 반원과 만나기 위한 a의 부호","힌트":"위 반원은 $y\\ge 0$ 부분이다. 직선이 $x>-1$인 부분에서 $y\\ge 0$이 되려면 $a$의 부호는?","식":["위 반원은 $x>-1$ 구간에 있다","$y=a(x+1)\\ge 0$이려면 $a>0$"],"설명":"$a<0$이면 $x>-1$에서 직선이 $x$축 아래에 있어 위 반원과 만나지 못한다. 따라서 $a>0$이다.","확인":null,"스킬":"G3","고비":true},{"제목":"직선과 위 반원의 거리 조건","힌트":"중심 $(1,0)$과 직선 $ax-y+a=0$ 사이의 거리가 반지름 $1$보다 작을 조건은?","식":["$\\frac{|a+a|}{\\sqrt{a^{2}+1}}<1$","$4a^{2}<a^{2}+1$","$a^{2}<\\frac{1}{3}$"],"설명":"원과 서로 다른 두 점에서 만나려면 중심에서 직선까지의 거리가 반지름보다 작아야 한다.","확인":null,"스킬":"G2"},{"제목":"a의 범위 정리","힌트":"$a>0$이고 $a^{2}<\\frac{1}{3}$을 함께 만족하는 범위는?","식":["$0<a<\\frac{1}{\\sqrt{3}}$"],"설명":"$a>0$이므로 $a^{2}<\\frac{1}{3}$에서 $a<\\frac{1}{\\sqrt{3}}$이다. 이 범위에서 교점은 모두 $5$개이다.","확인":null,"스킬":"G6"}]},"ns-9d65de304ff8":{"길":"원의 넓이를 이등분하는 직선은 중심을 지난다","단계":[{"제목":"원의 중심","힌트":"$x$와 $y$에 대해 완전제곱식을 만들면 중심의 좌표는?","식":["$(x-1)^{2}+(y+2)^{2}=9$","중심 $(1,\\,-2)$"],"설명":"$x^{2}-2x$와 $y^{2}+4y$를 각각 완전제곱 꼴로 고쳐 중심을 읽는다.","확인":null,"스킬":"A6"},{"제목":"중심을 지나는 직선의 k","힌트":"넓이를 이등분하는 직선이 지나야 하는 점은 어디이고, $y=kx+3$에 대입하면 $k$는?","식":["$-2=k\\times 1+3$","$k=-5$"],"설명":"원의 넓이를 이등분하는 직선은 원의 중심을 지난다. 중심의 좌표를 직선의 식에 대입한다.","확인":"-5","스킬":"S4","고비":true}]},"ns-a0afd4d95687":{"길":"OA가 접선이라 방멱으로 현 PQ를 구하고 중심에서 직선까지 거리로 기울기를 잡는다","단계":[{"제목":"방멱으로 구한 현 PQ의 길이","힌트":"$x$축은 원에 원점에서 접한다. $\\overline{\\mathrm{OA}}^{2}=\\overline{\\mathrm{AP}}\\times\\overline{\\mathrm{AQ}}$이면 $\\overline{\\mathrm{PQ}}$는?","식":["$(\\sqrt{15})^{2}=3\\times\\overline{\\mathrm{AQ}}$, $\\overline{\\mathrm{AQ}}=5$","$\\overline{\\mathrm{PQ}}=5-3=2$"],"설명":"원 $x^{2}+(y-3)^{2}=9$는 $x$축에 원점에서 접하므로 $\\overline{\\mathrm{OA}}$는 접선이다. 점 $\\mathrm{A}$에서 그은 접선과 할선 사이에 $\\overline{\\mathrm{OA}}^{2}=\\overline{\\mathrm{AP}}\\times\\overline{\\mathrm{AQ}}$가 성립한다.","확인":"2","스킬":"S5","고비":true},{"제목":"중심에서 현까지의 거리","힌트":"중심 $\\mathrm{C}(0,3)$에서 $\\overline{\\mathrm{PQ}}$에 내린 수선의 발 $\\mathrm{H}$에 대해 $\\overline{\\mathrm{CH}}$는?","식":["$\\overline{\\mathrm{PH}}=\\frac{1}{2}\\overline{\\mathrm{PQ}}=1$","$\\overline{\\mathrm{CH}}^{2}=3^{2}-1^{2}$","$\\overline{\\mathrm{CH}}=2\\sqrt{2}$"],"설명":"수선의 발 $\\mathrm{H}$는 현의 중점이다. 직각삼각형 $\\mathrm{CHP}$에서 빗변은 반지름 $3$이다.","확인":null,"스킬":"S3"},{"제목":"기울기에 대한 이차방정식","힌트":"직선 $ax-y+\\sqrt{15}a=0$과 $\\mathrm{C}(0,3)$ 사이의 거리가 $2\\sqrt{2}$라고 놓으면?","식":["$\\frac{|-3+\\sqrt{15}a|}{\\sqrt{a^{2}+1}}=2\\sqrt{2}$","$7a^{2}-6\\sqrt{15}a+1=0$"],"설명":"두 직선 $l$, $m$은 모두 점 $\\mathrm{A}$를 지나므로 $y=a(x+\\sqrt{15})$로 놓는다. 양변을 제곱하면 $a$에 대한 이차방정식이 된다.","확인":null,"스킬":"G3"},{"제목":"근과 계수의 관계로 구한 p+q","힌트":"두 직선의 기울기는 이 이차방정식의 두 근이다. 두 근의 곱을 $\\frac{q}{p}$로 놓으면 $p+q$는?","식":["두 근의 곱 $=\\frac{1}{7}=\\frac{q}{p}$","$p=7,\\ q=1$","$p+q=8$"],"설명":"이차방정식의 두 근의 곱은 상수항을 이차항의 계수로 나눈 값이다. $p$, $q$가 서로소이므로 $\\frac{1}{7}$ 그대로 읽는다.","확인":"8","스킬":"A2"}]},"ns-a824e6c99cdd":{"길":"두 원의 중심을 접선 조건으로 구해 이동량 a, b를 부호까지 읽는다","단계":[{"제목":"원 C의 중심","힌트":"$y$축에 접하는 반지름 $1$인 원의 중심 $x$좌표는? 그림에서 중심은 직선 $l$의 위쪽과 아래쪽 중 어느 쪽인가?","식":["중심 $(1,\\,p)$","$\\frac{|2+p-10|}{\\sqrt{5}}=1$","중심이 직선 위쪽이므로 $p=8+\\sqrt{5}$"],"설명":"직선 $l$과 접하므로 중심에서 직선까지의 거리가 반지름 $1$이다. 그림에서 원 $C$는 직선 $l$의 위쪽에 있으므로 $p-8>0$이다.","확인":null,"스킬":"G4","고비":true},{"제목":"원 C'의 중심","힌트":"$x$축에 접하는 반지름 $1$인 원의 중심 $y$좌표는? 그림에서 중심은 직선 $l$의 어느 쪽인가?","식":["중심 $(q,\\,1)$","$\\frac{|2q+1-10|}{\\sqrt{5}}=1$","중심이 직선 아래쪽이므로 $q=\\frac{9-\\sqrt{5}}{2}$"],"설명":"원 $C'$는 직선 $l$의 원점 쪽에 있으므로 $2q-9<0$이다.","확인":null,"스킬":"G4"},{"제목":"평행이동량 a, b","힌트":"중심 $(1,\\,8+\\sqrt{5})$가 중심 $\\left(\\frac{9-\\sqrt{5}}{2},\\,1\\right)$로 옮겨졌다. 각 좌표의 변화량은?","식":["$a=\\frac{9-\\sqrt{5}}{2}-1=\\frac{7-\\sqrt{5}}{2}$","$b=1-(8+\\sqrt{5})=-7-\\sqrt{5}$"],"설명":"평행이동한 양은 나중 중심의 좌표에서 처음 중심의 좌표를 뺀 값이다.","확인":null,"스킬":"G4"},{"제목":"ab의 값","힌트":"$\\frac{7-\\sqrt{5}}{2}\\times(-7-\\sqrt{5})$를 곱셈공식으로 계산하면?","식":["$ab=-\\frac{(7-\\sqrt{5})(7+\\sqrt{5})}{2}$","$ab=-\\frac{49-5}{2}=-22$"],"설명":"$-7-\\sqrt{5}=-(7+\\sqrt{5})$이므로 합차 공식을 쓴다.","확인":"-22","스킬":"A3"}]},"ns-ac57bc9734a9":{"길":"CQ로 점 Q를 정하고 Q를 지나는 접선을 거리 조건으로 구한다","단계":[{"제목":"점 Q의 좌표","힌트":"$\\mathrm{C}(-3,0)$이고 $\\mathrm{Q}(-9,\\,b)$일 때 $\\overline{\\mathrm{CQ}}=2\\sqrt{13}$으로 $b$를 구하면?","식":["$\\sqrt{6^{2}+b^{2}}=2\\sqrt{13}$","$b^{2}=16$","$b=4$"],"설명":"점 $\\mathrm{Q}$는 직선 $x=-9$ 위에 있고 제 $2$사분면의 점이므로 $b>0$이다.","확인":"4","스킬":"S4"},{"제목":"점 Q를 지나는 직선의 식","힌트":"$\\mathrm{Q}(-9,4)$를 지나고 기울기가 $m$인 직선을 $mx-y+\\cdots=0$ 꼴로 쓰면?","식":["$y=m(x+9)+4$","$mx-y+9m+4=0$"],"설명":"기울기가 없는 직선 $x=-9$는 원과 $(-9,0)$에서 접하지만 접점이 제 $2$사분면의 점이 아니므로 $l$이 아니다.","확인":null,"스킬":"G3"},{"제목":"접선의 기울기","힌트":"중심 $(-3,0)$에서 이 직선까지의 거리가 반지름 $6$과 같다고 놓으면 $m$은?","식":["$\\frac{|-3m+9m+4|}{\\sqrt{1+m^{2}}}=6$","$(6m+4)^{2}=36(1+m^{2})$","$m=\\frac{5}{12}$"],"설명":"원에 접하면 중심에서 직선까지의 거리가 반지름과 같다. 양변을 제곱하면 $m^{2}$항이 소거되어 일차방정식이 된다.","확인":"5/12","스킬":"G2","고비":true},{"제목":"접선 l의 방정식","힌트":"$m=\\frac{5}{12}$를 $y=m(x+9)+4$에 대입해 정리하면?","식":["$y=\\frac{5}{12}(x+9)+4$","$y=\\frac{5}{12}x+\\frac{31}{4}$"],"설명":"$\\frac{5}{12}\\times 9=\\frac{15}{4}$에 $4$를 더하면 $\\frac{31}{4}$이다.","확인":null,"스킬":"G3"}]},"ns-afd674e7c6c9":{"길":"접힌 호가 속한 원을 구하고 접은 선을 두 원의 공통현으로 본다","단계":[{"제목":"접힌 호가 속한 원의 방정식","힌트":"$x$축에 $(-1,0)$에서 접하는 반지름 $3$인 원의 중심은? 접힌 호는 $x$축 위쪽에 있다.","식":["중심 $(-1,\\,3)$","$(x+1)^{2}+(y-3)^{2}=9$"],"설명":"$x$축에 $(-1,0)$에서 접하면 중심은 $(-1,\\,\\pm 3)$이고, 접힌 호가 $x$축 위쪽에 있으므로 중심은 $(-1,3)$이다.","확인":null,"스킬":"S5"},{"제목":"접은 선 PQ는 두 원의 공통현","힌트":"접힌 호는 원래 원을 선분 $\\mathrm{PQ}$에 대해 접은 모양이다. $\\mathrm{P}$, $\\mathrm{Q}$는 두 원에서 각각 어떤 점인가?","식":["$\\mathrm{P},\\,\\mathrm{Q}$는 원 $x^{2}+y^{2}=9$ 위의 점","$\\mathrm{P},\\,\\mathrm{Q}$는 원 $(x+1)^{2}+(y-3)^{2}=9$ 위의 점"],"설명":"접은 선 위의 점은 접어도 움직이지 않는다. 따라서 $\\mathrm{P}$, $\\mathrm{Q}$는 두 원의 교점이고 직선 $\\mathrm{PQ}$는 두 원의 공통현을 지나는 직선이다.","확인":null,"스킬":"S2","고비":true},{"제목":"두 원의 식을 빼서 구한 직선","힌트":"두 원의 방정식을 모두 $x^{2}+y^{2}+\\cdots=0$ 꼴로 쓰고 빼면?","식":["$x^{2}+y^{2}-9=0$","$x^{2}+y^{2}+2x-6y+1=0$","두 식을 빼면 $2x-6y+10=0$","$x-3y+5=0$"],"설명":"두 원의 방정식에서 $x^{2}+y^{2}$항이 같으므로 빼면 두 교점을 지나는 직선의 방정식이 된다.","확인":null,"스킬":"A10"}]},"ns-b0343d33b55e":{"길":"대칭으로 중심을 y=x 위에 놓고 무게중심이 원 위에 있을 조건을 거리로 세운다","단계":[{"제목":"중심의 위치와 접선의 길이","힌트":"두 접선이 $y=x$에 대해 대칭이면 원의 중심은 어느 직선 위에 있고, $\\overline{\\mathrm{OA}}^{2}$은 어떻게 나타내는가?","식":["중심 $\\mathrm{C}(c,\\,c)$","$\\overline{\\mathrm{OC}}=\\sqrt{2}\\,c$","$\\overline{\\mathrm{OA}}^{2}=\\overline{\\mathrm{OC}}^{2}-(2\\sqrt{2})^{2}=2c^{2}-8$"],"설명":"두 접선 $l$, $l'$이 직선 $y=x$에 대해 대칭이므로 원의 중심도 $y=x$ 위에 있고 $a=b=c$이다. 삼각형 $\\mathrm{OAC}$는 $\\angle\\mathrm{OAC}=90^\\circ$인 직각삼각형이다.","확인":null,"스킬":"S5"},{"제목":"무게중심의 위치를 OC 위의 거리로 나타내기","힌트":"$\\overline{\\mathrm{AB}}$의 중점 $\\mathrm{M}$은 $\\overline{\\mathrm{OC}}$ 위에 있다. $\\overline{\\mathrm{OM}}$은 직각삼각형 $\\mathrm{OAC}$에서 어떻게 구하고, 무게중심 $\\mathrm{G}$는 $\\overline{\\mathrm{OC}}$ 위의 어디에 있어야 하는가?","식":["$\\overline{\\mathrm{OM}}=\\frac{\\overline{\\mathrm{OA}}^{2}}{\\overline{\\mathrm{OC}}}=\\frac{2c^{2}-8}{\\sqrt{2}\\,c}$","$\\overline{\\mathrm{OG}}=\\frac{2}{3}\\overline{\\mathrm{OM}}$","$\\overline{\\mathrm{OG}}=\\overline{\\mathrm{OC}}-2\\sqrt{2}=\\sqrt{2}\\,c-2\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{AM}}$은 직각삼각형 $\\mathrm{OAC}$의 높이이므로 $\\overline{\\mathrm{OA}}^{2}=\\overline{\\mathrm{OM}}\\times\\overline{\\mathrm{OC}}$이다. 무게중심 $\\mathrm{G}$는 $\\overline{\\mathrm{OM}}$을 $2:1$로 나누는 점이고 직선 $\\mathrm{OC}$ 위의 원 위의 점이다. $\\mathrm{G}$는 $\\mathrm{M}$보다 원점에 가까우므로 원점에서 가까운 교점이다.","확인":null,"스킬":"S7","고비":true},{"제목":"c에 대한 방정식과 c의 값","힌트":"$\\frac{2}{3}\\times\\frac{2c^{2}-8}{\\sqrt{2}\\,c}=\\sqrt{2}\\,c-2\\sqrt{2}$의 양변에 $\\sqrt{2}\\,c$를 곱해 정리하면 $c$는?","식":["$\\frac{4c^{2}-16}{3}=2c^{2}-4c$","$c^{2}-6c+8=0$","$c=2$ 또는 $c=4$, $c>2$이므로 $c=4$"],"설명":"$\\overline{\\mathrm{OC}}>2\\sqrt{2}$이어야 접선이 그어지므로 $\\sqrt{2}\\,c>2\\sqrt{2}$에서 $c>2$이다.","확인":"4","스킬":"A1"},{"제목":"각 BOA의 코사인","힌트":"직각삼각형 $\\mathrm{OAC}$에서 $\\sin\\angle\\mathrm{AOC}$는? $\\overline{\\mathrm{OC}}$는 $\\angle\\mathrm{AOB}$를 이등분한다.","식":["$\\overline{\\mathrm{OC}}=4\\sqrt{2}$","$\\sin\\angle\\mathrm{AOC}=\\frac{2\\sqrt{2}}{4\\sqrt{2}}=\\frac{1}{2}$","$\\angle\\mathrm{AOC}=30^\\circ$, $\\angle\\mathrm{BOA}=60^\\circ$"],"설명":"두 접선의 대칭이므로 $\\overline{\\mathrm{OC}}$는 $\\angle\\mathrm{BOA}$의 이등분선이다.","확인":"1/2","스킬":"S6"},{"제목":"구하는 값의 계산","힌트":"$a+b$는 얼마이고, $\\cos\\angle\\mathrm{BOA}$로 나누면?","식":["$a+b=4+4=8$","$\\frac{8}{\\frac{1}{2}}=16$"],"설명":"$a=b=c=4$이므로 $a+b=8$이다.","확인":"16","스킬":"A3"}]},"ns-b1995f5a5534":{"길":"AB의 직선을 구하고 넓이가 최대일 때 C에서의 접선이 AB와 평행함을 쓴다","단계":[{"제목":"두 접점 A, B를 지나는 직선","힌트":"$\\angle\\mathrm{OAP}=90^\\circ$이면 $\\mathrm{A}$, $\\mathrm{B}$는 $\\mathrm{OP}$를 지름으로 하는 원 위에 있다. 두 원의 식을 빼면?","식":["$\\mathrm{OP}$를 지름으로 하는 원: $x^{2}+y^{2}-4x-2y=0$","$x^{2}+y^{2}=2$와 빼면 $4x+2y=2$","$\\mathrm{AB}$: $2x+y=1$"],"설명":"점 $\\mathrm{P}(4,2)$에서 그은 접선은 반지름과 수직이므로 $\\mathrm{A}$, $\\mathrm{B}$는 $\\mathrm{OP}$를 지름으로 하는 원과 주어진 원의 교점이다. 두 교점을 지나는 직선은 두 원의 식을 빼서 얻는다.","확인":null,"스킬":"S2"},{"제목":"넓이가 최대일 때의 접선의 기울기","힌트":"밑변 $\\mathrm{AB}$를 고정하면 높이가 최대인 $\\mathrm{C}$에서의 접선은 $\\mathrm{AB}$와 어떤 관계인가? 그 접선의 기울기는?","식":["$\\mathrm{C}$에서의 접선 $\\parallel\\mathrm{AB}$","$\\mathrm{AB}$의 기울기 $=-2$","$2x+y+q=0$이므로 $p=2$"],"설명":"원 위의 점 중 직선 $\\mathrm{AB}$에서 가장 먼 점에서의 접선은 $\\mathrm{AB}$와 평행하다. $px+y+q=0$의 기울기가 $-2$이므로 $p=2$이다.","확인":"2","스킬":"S5","고비":true},{"제목":"원점과의 거리로 구한 q","힌트":"접선 $2x+y+q=0$과 원점 사이의 거리가 반지름과 같다고 놓으면 $q$는? 부호는 $\\mathrm{C}$가 $\\mathrm{AB}$의 어느 쪽에 있는지로 정한다.","식":["$\\frac{|q|}{\\sqrt{5}}=\\sqrt{2}$","$|q|=\\sqrt{10}$","$\\mathrm{C}$는 $\\mathrm{AB}$의 반대쪽, $2x+y<0$인 쪽이므로 $q=\\sqrt{10}$"],"설명":"$\\mathrm{AB}$와 접선은 원점을 기준으로 서로 반대쪽에 있다. $\\mathrm{AB}$는 $2x+y=1>0$이므로 접선은 $2x+y=-q<0$이어야 한다.","확인":null,"스킬":"S5"},{"제목":"pq의 값","힌트":"$p=2$, $q=\\sqrt{10}$일 때 $pq$는?","식":["$pq=2\\sqrt{10}$"],"설명":"앞에서 구한 $p$와 $q$를 곱한다.","확인":null,"스킬":"A3"}]},"ns-bc42c5dfc660":{"길":"C를 한 문자로 놓고 x축 접선과 내접 조건으로 식을 세운다","단계":[{"제목":"원 O1과 점 C의 좌표","힌트":"$\\mathrm{O}_{2}$가 $x$축에 접하면 반지름과 $\\mathrm{C}$의 $y$좌표는 어떤 관계인가?","식":["$\\mathrm{O}_{1}$: $x^{2}+y^{2}=1$","$\\mathrm{C}\\left(a,\\,\\frac{a+1}{3}\\right)$","$\\mathrm{O}_{2}$의 반지름 $r=\\frac{a+1}{3}$"],"설명":"$\\mathrm{C}$는 직선 $x-3y+1=0$ 위에 있으므로 $y=\\frac{x+1}{3}$이다. $x$축에 접하므로 반지름은 $\\mathrm{C}$의 $y$좌표와 같다.","확인":null,"스킬":"G1"},{"제목":"내접 조건으로 세운 방정식","힌트":"내접하는 두 원에서 $\\overline{\\mathrm{OC}}$는 두 반지름과 어떤 관계인가?","식":["$\\overline{\\mathrm{OC}}=1-r$","$a^{2}+\\left(\\frac{a+1}{3}\\right)^{2}=\\left(1-\\frac{a+1}{3}\\right)^{2}$","$3a^{2}+2a-1=0$"],"설명":"내접하는 두 원은 중심 사이의 거리가 두 반지름의 차와 같다. 전개하면 양변의 $\\left(\\frac{a+1}{3}\\right)^{2}$이 소거된다.","확인":null,"스킬":"S5","고비":true},{"제목":"a의 값 결정","힌트":"$3a^{2}+2a-1=0$을 인수분해한 두 근 중 그림에 맞는 값은?","식":["$(3a-1)(a+1)=0$","$a=\\frac{1}{3}$"],"설명":"$a=-1$이면 $\\mathrm{C}=(-1,0)$으로 반지름이 $0$이 되어 원이 되지 않는다. 그림에서 $\\mathrm{C}$는 제 $1$사분면에 있으므로 $a>0$이다.","확인":"1/3","스킬":"A6"},{"제목":"삼각형 ABC의 넓이","힌트":"$\\angle\\mathrm{B}=90^\\circ$인 직각삼각형에서 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{BC}}$는?","식":["$\\overline{\\mathrm{AB}}=\\frac{1}{3}+1=\\frac{4}{3}$","$\\overline{\\mathrm{BC}}=\\frac{a+1}{3}=\\frac{4}{9}$","$\\triangle\\mathrm{ABC}=\\frac{1}{2}\\times\\frac{4}{3}\\times\\frac{4}{9}=\\frac{8}{27}$"],"설명":"$\\mathrm{B}$의 $x$좌표는 $\\mathrm{C}$의 $x$좌표와 같은 $\\frac{1}{3}$이고, $\\overline{\\mathrm{BC}}$는 반지름이다.","확인":"8/27","스킬":"G10"}]},"ns-c3be3c529df5":{"길":"제4사분면의 점을 지나고 두 축에 접하면 중심은 (r, -r)이다","단계":[{"제목":"중심과 반지름 문자로 놓기","힌트":"점 $(2,-1)$이 제 $4$사분면에 있다. 두 축에 접하는 원의 중심은 반지름 $r$로 어떻게 나타내는가?","식":["중심 $(r,\\,-r)$, 반지름 $r$","$(2-r)^{2}+(-1+r)^{2}=r^{2}$"],"설명":"두 축에 동시에 접하면 중심에서 두 축까지의 거리가 모두 $r$이다. 제 $4$사분면의 점을 지나므로 중심도 제 $4$사분면에 있다.","확인":null,"스킬":"S4","고비":true},{"제목":"반지름 r의 두 값","힌트":"전개해서 정리한 이차방정식의 두 근 중 큰 값(큰 원의 반지름)은?","식":["$r^{2}-6r+5=0$","$(r-1)(r-5)=0$","$r=1$ 또는 $r=5$"],"설명":"$(2-r)^{2}+(r-1)^{2}=r^{2}$을 전개하면 $r^{2}$항이 하나 남아 이차방정식이 된다.","확인":"5","스킬":"A6"},{"제목":"두 중심 사이의 거리","힌트":"두 중심 $(1,-1)$, $(5,-5)$ 사이의 거리는?","식":["$\\sqrt{(5-1)^{2}+(-5+1)^{2}}=4\\sqrt{2}$"],"설명":"두 중심의 $x$좌표의 차와 $y$좌표의 차가 모두 $4$이다.","확인":null,"스킬":"S3"}]},"ns-c685fb5c2fa6":{"길":"접선과 반지름의 수직, 지름 위의 직각으로 닮은 직각삼각형을 만든다","단계":[{"제목":"중심 A에서 P까지의 거리","힌트":"반지름이 $10$인 세 원이 일렬로 접하면 $\\overline{\\mathrm{AP}}$는 반지름과 지름 몇 개의 합인가?","식":["$\\overline{\\mathrm{AP}}=10+20+20=50$"],"설명":"$\\mathrm{A}$는 원 $O$의 왼쪽 끝이므로 $\\overline{\\mathrm{AO}}=10$이다. 이웃한 중심 사이의 거리는 지름 $20$이다.","확인":"50","스킬":"S5"},{"제목":"접선의 길이 AC","힌트":"접선과 반지름이 수직이면 직각삼각형 $\\mathrm{ACP}$에서 $\\overline{\\mathrm{AC}}$는?","식":["$\\overline{\\mathrm{AC}}=\\sqrt{50^{2}-10^{2}}=\\sqrt{2400}=20\\sqrt{6}$"],"설명":"접점 $\\mathrm{C}$에서 $\\angle\\mathrm{ACP}=90^\\circ$이고 $\\overline{\\mathrm{CP}}=10$이다.","확인":null,"스킬":"S3"},{"제목":"닮은 직각삼각형으로 구한 AD와 AC의 비","힌트":"원 $O$의 지름 $\\mathrm{AE}$에 대해 $\\angle\\mathrm{ADE}=90^\\circ$이다. 삼각형 $\\mathrm{ADE}$와 닮은 삼각형은 무엇이고, $\\overline{\\mathrm{AD}}:\\overline{\\mathrm{AC}}$는?","식":["$\\triangle\\mathrm{ADE}\\sim\\triangle\\mathrm{ACP}$","$\\overline{\\mathrm{AD}}:\\overline{\\mathrm{AC}}=\\overline{\\mathrm{AE}}:\\overline{\\mathrm{AP}}=20:50$","$\\frac{\\overline{\\mathrm{AD}}}{\\overline{\\mathrm{AC}}}=\\frac{2}{5}$"],"설명":"$\\mathrm{E}$는 원 $O$의 오른쪽 끝이고 $\\overline{\\mathrm{AE}}$는 지름이다. 지름에 대한 원주각이 직각이고 $\\angle\\mathrm{A}$를 공유하므로 두 직각삼각형이 닮음이다.","확인":"2/5","스킬":"S1","고비":true},{"제목":"AD의 길이","힌트":"$\\overline{\\mathrm{AC}}=20\\sqrt{6}$에 닮음비를 곱하면?","식":["$\\overline{\\mathrm{AD}}=\\frac{2}{5}\\times 20\\sqrt{6}=8\\sqrt{6}$"],"설명":"앞에서 구한 비를 $\\overline{\\mathrm{AC}}$에 곱한다.","확인":null,"스킬":"S1"}]},"ns-c86476fa789a":{"길":"두 접선이 직선 l에 수직임을 이용해 절편을 r로 나타내고 사다리꼴 넓이를 구한다","단계":[{"제목":"접선의 기울기","힌트":"직선 $l$의 기울기는 얼마이고, $\\mathrm{A}$, $\\mathrm{B}$에서의 접선의 기울기는?","식":["$l$: $y=\\frac{1}{2}x$","접선 $\\perp l$이므로 기울기 $-2$","접선: $2x+y-c=0$"],"설명":"접선은 접점에서 반지름과 수직이고, 반지름은 직선 $l$ 위에 있다. 두 접선은 기울기가 같은 평행한 직선이다.","확인":"-2","스킬":"G9"},{"제목":"두 접선의 y절편","힌트":"중심 $(4,2)$에서 접선 $2x+y-c=0$까지의 거리가 반지름 $r$이라 놓으면 $c$는?","식":["$\\frac{|8+2-c|}{\\sqrt{5}}=r$","$c=10\\pm\\sqrt{5}\\,r$"],"설명":"두 접선의 $y$절편이 $10-\\sqrt{5}\\,r$와 $10+\\sqrt{5}\\,r$이다. 작은 값이 $l_{1}$, 큰 값이 $l_{2}$에 해당한다.","확인":null,"스킬":"S4"},{"제목":"사다리꼴 DCEF의 넓이","힌트":"삼각형 $\\mathrm{OEF}$에서 삼각형 $\\mathrm{OCD}$를 빼면 넓이를 $r$로 어떻게 나타내는가?","식":["$\\mathrm{D}(0,\\,c_{1})$, $\\mathrm{C}\\left(\\frac{c_{1}}{2},\\,0\\right)$, $\\mathrm{F}(0,\\,c_{2})$, $\\mathrm{E}\\left(\\frac{c_{2}}{2},\\,0\\right)$","넓이 $=\\frac{c_{2}^{2}}{4}-\\frac{c_{1}^{2}}{4}=\\frac{(c_{2}-c_{1})(c_{2}+c_{1})}{4}$","$=\\frac{2\\sqrt{5}\\,r\\times 20}{4}=10\\sqrt{5}\\,r$"],"설명":"$y$절편이 $c$인 접선 $2x+y=c$의 $x$절편은 $\\frac{c}{2}$이다. 사다리꼴은 두 직각삼각형의 넓이의 차이다.","확인":null,"스킬":"G10","고비":true},{"제목":"반지름 r의 값","힌트":"$10\\sqrt{5}\\,r=\\frac{50\\sqrt{5}}{3}$을 풀면?","식":["$r=\\frac{50\\sqrt{5}}{3\\times 10\\sqrt{5}}=\\frac{5}{3}$"],"설명":"양변을 $10\\sqrt{5}$로 나눈다.","확인":"5/3","스킬":"G10"}]},"ns-c9c0c40eca73":{"길":"등대에서 항로까지의 거리와 반지름으로 현의 길이를 구한다","단계":[{"제목":"등대에서 항로까지의 거리","힌트":"등대에서 항로에 내린 수선과 배, 등대를 이은 선분으로 직각삼각형을 만들면 거리는?","식":["빗변 $80$, 한 각 $45^\\circ$","거리 $=80\\sin 45^\\circ=40\\sqrt{2}$"],"설명":"항로는 북동쪽이므로 동서 방향과 $45^\\circ$를 이룬다. 등대에서 항로까지의 거리는 배와 등대 사이의 거리에 $\\sin 45^\\circ$를 곱한 값이다.","확인":null,"스킬":"S6","고비":true},{"제목":"빛의 영역 안에 있는 항로의 절반","힌트":"반지름 $60$과 앞에서 구한 거리로 만든 직각삼각형의 나머지 변은?","식":["$\\sqrt{60^{2}-(40\\sqrt{2})^{2}}=\\sqrt{3600-3200}=\\sqrt{400}$","$=20$"],"설명":"항로가 빛의 원과 만나는 현의 절반이 이 직각삼각형의 나머지 변이다.","확인":"20","스킬":"S5"},{"제목":"영역 안에서 움직이는 길이","힌트":"현의 절반 $20$으로 현 전체의 길이를 구하면?","식":["$2\\times 20=40$"],"설명":"배가 빛의 영역에 들어와 움직이는 길이는 현의 길이와 같다.","확인":"40","스킬":"S5"}]},"ns-ca648e058a28":{"길":"각의 이등분선 정리로 CA:CB를 구해 C의 자취인 원을 찾고 E에서 가장 먼 점을 잡는다","단계":[{"제목":"각의 이등분선이 나누는 비","힌트":"$\\overline{\\mathrm{AD}}$와 $\\overline{\\mathrm{DB}}$의 길이를 구하면 $\\overline{\\mathrm{CA}}:\\overline{\\mathrm{CB}}$는?","식":["$\\overline{\\mathrm{AD}}=\\sqrt{2^{2}+2^{2}}=2\\sqrt{2}$, $\\overline{\\mathrm{DB}}=\\sqrt{3^{2}+3^{2}}=3\\sqrt{2}$","$\\overline{\\mathrm{CA}}:\\overline{\\mathrm{CB}}=\\overline{\\mathrm{AD}}:\\overline{\\mathrm{DB}}=2:3$"],"설명":"삼각형의 각의 이등분선은 대변을 두 변의 길이의 비로 나눈다. $\\angle\\mathrm{ACB}$의 이등분선이 $\\mathrm{D}$를 지나므로 $\\overline{\\mathrm{AD}}:\\overline{\\mathrm{DB}}=\\overline{\\mathrm{CA}}:\\overline{\\mathrm{CB}}$이다.","확인":"2/3","스킬":"A8"},{"제목":"C가 만족하는 식","힌트":"$3\\overline{\\mathrm{CA}}=2\\overline{\\mathrm{CB}}$의 양변을 제곱해 $a$, $b$로 정리하면?","식":["$9\\{(a-3)^{2}+(b-7)^{2}\\}=4\\{(a-8)^{2}+(b-2)^{2}\\}$","$5a^{2}+5b^{2}+10a-110b+250=0$","$a^{2}+b^{2}+2a-22b+50=0$"],"설명":"$\\mathrm{C}(a,b)$에서 두 점 $\\mathrm{A}$, $\\mathrm{B}$까지의 거리를 좌표로 쓰고 제곱해서 비교한다. 양변을 $5$로 나누면 원의 방정식 꼴이 된다.","확인":null,"스킬":"S4","고비":true},{"제목":"점 C의 자취인 원","힌트":"$a$와 $b$에 대해 각각 완전제곱식을 만들면 우변의 값은?","식":["$(a+1)^{2}+(b-11)^{2}=72$","중심 $\\mathrm{M}(-1,\\,11)$, 반지름 $6\\sqrt{2}$"],"설명":"$a^{2}+2a$와 $b^{2}-22b$를 완전제곱 꼴로 고치면 $1+121-50=72$가 우변이 된다. 점 $\\mathrm{C}$는 이 원 위를 움직인다.","확인":"72","스킬":"A6"},{"제목":"E와 C 사이의 거리의 최댓값","힌트":"$\\mathrm{E}(-12,0)$에서 원의 중심까지의 거리에 반지름을 더하면?","식":["$\\overline{\\mathrm{EM}}=\\sqrt{(-1+12)^{2}+11^{2}}=11\\sqrt{2}$","$\\overline{\\mathrm{EC}}\\le 11\\sqrt{2}+6\\sqrt{2}=17\\sqrt{2}$"],"설명":"원 밖의 점에서 원 위의 점까지 거리가 가장 먼 것은 중심까지의 거리에 반지름을 더한 값이다. 그 점은 직선 $\\mathrm{AB}$ 위에 있지 않으므로 삼각형이 만들어진다.","확인":null,"스킬":"S5"}]},"ns-cc88c21afab1":{"길":"접선의 방정식을 쓰고 중심에서 접선까지의 거리가 반지름보다 작을 조건을 세운다","단계":[{"제목":"점 P에서의 접선의 방정식","힌트":"원 $x^{2}+y^{2}=9$ 위의 점 $\\mathrm{P}(a,b)$에서의 접선은 어떤 식인가?","식":["$ax+by=9$","$a^{2}+b^{2}=9$"],"설명":"원 $x^{2}+y^{2}=r^{2}$ 위의 점 $(x_{1},y_{1})$에서의 접선은 $x_{1}x+y_{1}y=r^{2}$이다. 점 $\\mathrm{P}$가 원 위에 있으므로 $a^{2}+b^{2}=9$이다.","확인":null,"스킬":"S5"},{"제목":"중심 (9, 0)에서 접선까지의 거리","힌트":"점 $(9,0)$과 직선 $ax+by-9=0$ 사이의 거리를 $a^{2}+b^{2}=9$를 써서 $a$만으로 나타내면?","식":["$\\frac{|9a-9|}{\\sqrt{a^{2}+b^{2}}}=\\frac{9|a-1|}{3}$","$=3|a-1|$"],"설명":"분모의 $\\sqrt{a^{2}+b^{2}}$는 $\\sqrt{9}=3$이므로 $b$가 소거된다.","확인":null,"스킬":"G2","고비":true},{"제목":"서로 다른 두 점에서 만날 조건","힌트":"거리가 반지름 $1$보다 작아야 할 때 $a$의 범위는?","식":["$3|a-1|<1$","$|a-1|<\\frac{1}{3}$","$\\frac{2}{3}<a<\\frac{4}{3}$"],"설명":"직선과 원이 서로 다른 두 점에서 만나려면 중심에서 직선까지의 거리가 반지름보다 작아야 한다.","확인":null,"스킬":"G6"}]},"ns-d2086125cc80":{"길":"두 영역에 공통 부분을 더해 삼각형 OAB의 넓이를 원의 넓이와 같게 놓는다","단계":[{"제목":"두 넓이가 같을 조건","힌트":"빗금 친 부분과 어두운 부분에 각각 직선 아래쪽 원의 부분을 더하면 어떤 두 넓이가 같아지는가?","식":["빗금 친 부분 $+$ 공통 부분 $=$ 원 $C$","어두운 부분 $+$ 공통 부분 $=\\triangle\\mathrm{OAB}$","$\\triangle\\mathrm{OAB}=\\pi\\times 2^{2}=4\\pi$"],"설명":"직선 아래쪽에 있는 원의 부분은 어두운 부분에도, 원 $C$에서 빗금 친 부분을 뺀 나머지에도 같이 들어 있다. 두 영역의 넓이가 같으면 삼각형 $\\mathrm{OAB}$의 넓이와 원 $C$의 넓이가 같다.","확인":null,"스킬":"S12","고비":true},{"제목":"점 B의 x좌표","힌트":"$\\mathrm{A}(0,2)$이고 $\\mathrm{B}$의 $x$좌표를 $a$로 놓았을 때 삼각형 $\\mathrm{OAB}$의 넓이로 식을 세우면?","식":["$\\frac{1}{2}\\times 2\\times a=4\\pi$","$a=4\\pi$"],"설명":"밑변이 $\\overline{\\mathrm{OB}}=a$, 높이가 $\\overline{\\mathrm{OA}}=2$인 직각삼각형이다.","확인":null,"스킬":"G10"},{"제목":"직선 AB의 기울기","힌트":"두 점 $(0,2)$, $(4\\pi,0)$를 지나는 직선의 기울기는?","식":["$\\frac{0-2}{4\\pi-0}=-\\frac{1}{2\\pi}$"],"설명":"$y$절편이 $2$, $x$절편이 $4\\pi$이므로 기울기는 $-\\frac{2}{4\\pi}$이다.","확인":null,"스킬":"G9"}]},"ns-d30c5c818dd8":{"길":"원의 방정식을 세우고 k마다 교점을 구해 겹치는 점을 가려낸다","단계":[{"제목":"네 원의 방정식","힌트":"원점과 $(2,0)$을 지름의 양 끝으로 하는 원의 중심과 반지름은?","식":["$(x\\mp 1)^{2}+y^{2}=1$, $x^{2}+(y\\mp 1)^{2}=1$","정리하면 $x^{2}+y^{2}=\\pm 2x$, $x^{2}+y^{2}=\\pm 2y$"],"설명":"네 원은 중심이 $(\\pm 1,0)$, $(0,\\pm 1)$이고 반지름이 $1$이며 모두 원점을 지난다. $x^{2}+y^{2}$을 왼쪽으로 모으면 $k$를 대입하기 쉽다.","확인":null,"스킬":"S5"},{"제목":"k=1일 때의 교점의 개수","힌트":"$x^{2}+y^{2}=1$과 $x^{2}+y^{2}=2x$를 연립하면 교점은 몇 개이고, 네 원의 교점이 서로 겹치는가?","식":["$1=2x$, $x=\\frac{1}{2}$, $y=\\pm\\frac{\\sqrt{3}}{2}$","나머지 세 원도 각각 $2$점씩, 모두 서로 다른 점","$f(1)=4\\times 2$"],"설명":"원마다 교점의 좌표는 $\\left(\\frac{1}{2},\\pm\\frac{\\sqrt{3}}{2}\\right)$, $\\left(\\pm\\frac{\\sqrt{3}}{2},\\frac{1}{2}\\right)$, $\\left(-\\frac{1}{2},\\pm\\frac{\\sqrt{3}}{2}\\right)$, $\\left(\\pm\\frac{\\sqrt{3}}{2},-\\frac{1}{2}\\right)$로 모두 다르다.","확인":"8","스킬":"G1"},{"제목":"k=2일 때의 교점의 개수","힌트":"$x^{2}+y^{2}=2$와 $x^{2}+y^{2}=2x$의 교점을 구하고, 네 원에서 나온 점이 겹치는지 따져 보면?","식":["$2=2x$, $x=1$, $y=\\pm 1$","네 원의 교점은 $(\\pm 1,\\,\\pm 1)$의 네 점뿐","$f(2)=4$"],"설명":"각 원에서 나오는 두 점이 이웃한 원에서도 나오므로 서로 겹친다. 서로 다른 점은 네 점이다.","확인":"4","스킬":"C2","고비":true},{"제목":"f(1)+f(2)","힌트":"앞에서 구한 두 값을 더하면?","식":["$f(1)+f(2)=8+4=12$"],"설명":"서로 다른 교점의 개수를 각각 구했으므로 더한다.","확인":"12","스킬":"C2"}]},"ns-d8558e190740":{"길":"접힌 호가 속한 원을 구하고 접은 선 AB를 두 원의 공통현으로 본다","단계":[{"제목":"접힌 호가 속한 원의 방정식","힌트":"$x$축에 $(2,0)$에서 접하는 반지름 $4$인 원의 중심은? 접힌 호는 $x$축 위쪽에 있다.","식":["중심 $(2,\\,4)$","$(x-2)^{2}+(y-4)^{2}=16$"],"설명":"접힌 원도 반지름이 $4$이다. $x$축에 $(2,0)$에서 접하고 그림에서 $x$축 위쪽에 있으므로 중심은 $(2,4)$이다.","확인":null,"스킬":"S5"},{"제목":"접은 선 AB는 두 원의 공통현","힌트":"접은 선 위의 두 점 $\\mathrm{A}$, $\\mathrm{B}$는 접기 전과 접은 후의 원에서 각각 어떤 점인가?","식":["$\\mathrm{A},\\,\\mathrm{B}$는 $x^{2}+y^{2}=16$ 위의 점","$\\mathrm{A},\\,\\mathrm{B}$는 $(x-2)^{2}+(y-4)^{2}=16$ 위의 점"],"설명":"접는 선 위의 점은 접어도 움직이지 않는다. 따라서 $\\mathrm{A}$, $\\mathrm{B}$는 두 원의 교점이고 직선 $\\mathrm{AB}$는 두 원의 교점을 지나는 직선이다.","확인":null,"스킬":"S2","고비":true},{"제목":"두 원의 식을 빼서 구한 직선","힌트":"두 원의 방정식을 모두 $x^{2}+y^{2}+\\cdots=0$ 꼴로 쓰고 빼면?","식":["$x^{2}+y^{2}-16=0$","$x^{2}+y^{2}-4x-8y+4=0$","빼면 $4x+8y-20=0$","$x+2y-5=0$"],"설명":"$x^{2}+y^{2}$항이 같으므로 빼면 두 교점을 지나는 직선의 방정식이 된다.","확인":null,"스킬":"A10"},{"제목":"a+b의 값","힌트":"$x+2y-5=0$을 $ax+by-5=0$과 비교하면 $a$, $b$는?","식":["$a=1,\\ b=2$","$a+b=3$"],"설명":"상수항이 $-5$로 같으므로 $x$, $y$의 계수를 그대로 비교한다.","확인":"3","스킬":"A3"}]},"ns-ddad1a7be153":{"길":"넓이를 AP와 원에서 AP까지의 최소 거리로 쓰면 AP가 약분되어 한 변수만 남는다","단계":[{"제목":"넓이식과 Q의 최소 거리","힌트":"$\\mathrm{AP}$를 밑변으로 보면 높이는 $\\mathrm{Q}$에서 직선 $\\mathrm{AP}$까지의 거리이다. 원의 중심 $\\mathrm{C}$에서 직선 $\\mathrm{AP}$에 내린 수선의 발을 $\\mathrm{H}$라 하면 이 거리의 최솟값은?","식":["$\\triangle\\mathrm{AQP}=\\frac{1}{2}\\times\\overline{\\mathrm{AP}}\\times\\overline{\\mathrm{QH}}$","$\\overline{\\mathrm{QH}}=\\overline{\\mathrm{CH}}-1$일 때 최소","$\\triangle\\mathrm{AQP}\\ge\\frac{1}{2}\\times\\overline{\\mathrm{AP}}\\times(\\overline{\\mathrm{CH}}-1)$"],"설명":"원의 중심 $\\mathrm{C}$에서 직선까지의 거리 $\\overline{\\mathrm{CH}}$에서 반지름 $1$을 뺀 값이 원 위의 점에서 직선까지의 최소 거리이다.","확인":null,"스킬":"S12","고비":true},{"제목":"AP의 길이와 CH의 길이","힌트":"$\\mathrm{P}(a,0)$으로 놓고 직선 $\\mathrm{AP}$의 방정식을 세운 뒤 $\\mathrm{C}(0,3)$과의 거리를 구하면?","식":["$\\overline{\\mathrm{AP}}=\\sqrt{(a-4)^{2}+9}$","직선 $\\mathrm{AP}$: $3x+(a-4)y-3a=0$","$\\overline{\\mathrm{CH}}=\\frac{|3(a-4)-3a|}{\\sqrt{9+(a-4)^{2}}}=\\frac{12}{\\overline{\\mathrm{AP}}}$"],"설명":"직선 $\\mathrm{AP}$는 $\\mathrm{A}(4,3)$과 $\\mathrm{P}(a,0)$를 지난다. 두 식 모두 $\\sqrt{(a-4)^{2}+9}$를 포함한다.","확인":null,"스킬":"S4"},{"제목":"넓이를 AP만의 식으로 정리","힌트":"$\\frac{1}{2}\\times\\overline{\\mathrm{AP}}\\times\\left(\\frac{12}{\\overline{\\mathrm{AP}}}-1\\right)$을 전개하면?","식":["$\\frac{1}{2}\\times\\overline{\\mathrm{AP}}\\times\\left(\\frac{12}{\\overline{\\mathrm{AP}}}-1\\right)=6-\\frac{\\overline{\\mathrm{AP}}}{2}$"],"설명":"$\\overline{\\mathrm{AP}}$가 약분되어 넓이는 $\\overline{\\mathrm{AP}}$가 클수록 작다. $\\overline{\\mathrm{CH}}=\\frac{12}{\\overline{\\mathrm{AP}}}\\ge\\frac{12}{5}>1$이므로 원은 직선 $\\mathrm{AP}$와 만나지 않는다.","확인":null,"스킬":"A1"},{"제목":"AP가 최대일 때의 길이","힌트":"$0\\le a\\le 4$에서 $(a-4)^{2}$이 최대가 되는 $a$를 넣으면 $\\overline{\\mathrm{AP}}$는?","식":["$a=0$일 때 $(a-4)^{2}$ 최대","$\\overline{\\mathrm{AP}}=\\sqrt{16+9}=5$"],"설명":"$\\mathrm{P}$는 선분 위의 점이므로 $0\\le a\\le 4$이다. 넓이가 최소이려면 $\\overline{\\mathrm{AP}}$가 최대이어야 한다.","확인":"5","스킬":"G7"},{"제목":"넓이의 최솟값","힌트":"$6-\\frac{\\overline{\\mathrm{AP}}}{2}$에 $\\overline{\\mathrm{AP}}$의 최댓값을 넣으면?","식":["$6-\\frac{5}{2}=\\frac{7}{2}$"],"설명":"$\\overline{\\mathrm{AP}}$의 최댓값을 정리된 넓이식에 대입한다.","확인":"7/2","스킬":"G7"}]},"ns-ddfda6d1b1b8":{"길":"수직인 두 접선에서 중심각을 알아내고, 중심과 직선 사이 거리로 식을 세운다","단계":[{"제목":"두 접선이 만드는 중심각","힌트":"접점에서 반지름과 접선이 이루는 각, 두 접선이 이루는 각을 쓰면 사각형의 남은 한 각은 얼마인가?","식":["$360^\\circ-90^\\circ-90^\\circ-90^\\circ=90^\\circ$"],"설명":"원의 중심을 $\\mathrm{C}$, 두 접선의 교점을 $\\mathrm{P}$라 하면 사각형 $\\mathrm{CAPB}$에서 세 각이 $90^\\circ$이다. 따라서 $\\angle \\mathrm{ACB}=90^\\circ$이다.","확인":null,"스킬":"S5"},{"제목":"중심에서 현까지의 거리","힌트":"삼각형 ACB는 어떤 삼각형이며, 중심에서 AB까지의 거리는 반지름의 몇 배인가?","식":["$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CB}}=r,\\ \\angle \\mathrm{ACB}=90^\\circ$","$d=\\frac{r}{\\sqrt{2}}$"],"설명":"삼각형 $\\mathrm{ACB}$는 직각이등변삼각형이다. 빗변 $\\mathrm{AB}$에 내린 높이가 중심에서 현까지의 거리이므로 $d=\\frac{r}{\\sqrt{2}}$이다.","확인":null,"스킬":"S5"},{"제목":"점과 직선 사이 거리로 식 세우기","힌트":"중심 $(r,\\ r)$에서 직선 $mx-y=0$까지의 거리를 $\\frac{r}{\\sqrt{2}}$와 같다고 놓으면 어떤 식이 되는가?","식":["$\\frac{r|m-1|}{\\sqrt{m^2+1}}=\\frac{r}{\\sqrt{2}}$","$m^2-4m+1=0$"],"설명":"원이 $x$축, $y$축에 접하고 제1사분면에 있으므로 중심은 $(r,\\ r)$이다. $r$을 약분하고 양변을 제곱하면 $2(m-1)^2=m^2+1$이므로 $m^2-4m+1=0$이다.","확인":null,"스킬":"S13","고비":true},{"제목":"가능한 m의 값의 합","힌트":"이차방정식의 두 근이 모두 양수일 때 두 근의 합은 얼마인가?","식":["$m=2\\pm\\sqrt{3}$","$(2+\\sqrt{3})+(2-\\sqrt{3})=4$"],"설명":"두 근 $2\\pm\\sqrt{3}$이 모두 $m>0$을 만족한다. 근과 계수의 관계로도 합은 $4$이다.","확인":"4","스킬":"A2"}]},"ns-eed7904e6392":{"길":"평행한 두 접선 사이 거리로 반지름을 잡고, 중심까지 거리로 현을 구한다","단계":[{"제목":"원의 반지름","힌트":"평행한 두 접선 사이의 거리는 원의 무엇과 같은가?","식":["$\\frac{|2-(-3)|}{\\sqrt{(\\sqrt{3})^2+1}}=\\frac{5}{2}$","$r=\\frac{5}{4}$"],"설명":"평행한 두 직선이 모두 원에 접하므로 두 직선 사이의 거리가 지름이다. 지름이 $\\frac{5}{2}$이므로 반지름은 $\\frac{5}{4}$이다.","확인":"5/4","스킬":"S5"},{"제목":"중심에서 현까지의 거리","힌트":"접선 $y=\\sqrt{3}x+2$와 $y=\\sqrt{3}x+1$ 사이 거리를 이용하면 중심까지의 거리는 얼마인가?","식":["$\\frac{|2-1|}{\\sqrt{(\\sqrt{3})^2+1}}=\\frac{1}{2}$","$d=\\frac{5}{4}-\\frac{1}{2}=\\frac{3}{4}$"],"설명":"직선 $y=\\sqrt{3}x+1$은 접선 $y=\\sqrt{3}x+2$보다 중심에 $\\frac{1}{2}$만큼 가깝다. 따라서 중심에서 이 직선까지의 거리는 반지름에서 $\\frac{1}{2}$을 뺀 값이다.","확인":"3/4","스킬":"S5","고비":true},{"제목":"현 PQ의 길이의 제곱","힌트":"반지름이 $\\frac{5}{4}$이고 중심까지의 거리가 $\\frac{3}{4}$일 때 $a^2$은 얼마인가?","식":["$\\frac{a}{2}=\\sqrt{\\left(\\frac{5}{4}\\right)^2-\\left(\\frac{3}{4}\\right)^2}=1$","$a=2,\\ a^2=4$"],"설명":"중심에서 현에 내린 수선은 현을 이등분한다. 반지름을 빗변으로 하는 직각삼각형에 피타고라스 정리를 쓰면 $\\frac{a}{2}=1$이다.","확인":"4","스킬":"S3"}]},"ns-f7232bf3f7f1":{"길":"세 점을 지나는 원의 중심으로 반지름을 잡고, 접선 조건으로 최댓값을 구한다","단계":[{"제목":"원의 중심과 반지름","힌트":"세 점 $(0,\\ 0)$, $(0,\\ 2)$, $(2,\\ 0)$을 이은 삼각형은 어떤 삼각형인가?","식":["$\\text{중심 }(1,\\ 1),\\ r=\\sqrt{2}$"],"설명":"세 점을 이은 삼각형은 직각삼각형이고, 직각삼각형의 외심은 빗변의 중점이다. 빗변 양 끝 $(0,\\ 2)$, $(2,\\ 0)$의 중점이 $(1,\\ 1)$이고 반지름은 $\\sqrt{2}$이다.","확인":null,"스킬":"S5"},{"제목":"접선 조건으로 구한 최댓값","힌트":"직선 $x+y=k$가 원에 접할 때 $k$의 값은 무엇인가?","식":["$\\frac{|1+1-k|}{\\sqrt{2}}=\\sqrt{2}$","$k=0$ 또는 $k=4$"],"설명":"$x+y=k$가 원과 접할 때 $k$가 최대 또는 최소가 된다. 중심 $(1,\\ 1)$에서 직선까지의 거리가 반지름과 같으므로 $|2-k|=2$이고, 최댓값은 $k=4$이다.","확인":"4","스킬":"G2","고비":true},{"제목":"최댓값과 반지름의 합","힌트":"최댓값과 반지름을 더하면 얼마인가?","식":["$4+\\sqrt{2}$"],"설명":"최댓값 $4$와 반지름 $\\sqrt{2}$의 합은 $4+\\sqrt{2}$이다.","확인":null,"스킬":"G2"}]},"ns-f86378fcc2aa":{"길":"식을 한 점까지 거리의 제곱으로 보고, 꼭짓점과 변까지의 거리로 최대·최소를 잡는다","단계":[{"제목":"식을 거리의 제곱으로 바꾸기","힌트":"식을 $(x-a)^2+y^2$ 꼴로 정리하면 어떤 점까지의 거리의 제곱인가?","식":["$x^2+y^2-4x+4=(x-2)^2+y^2$"],"설명":"주어진 식은 점 $\\mathrm{P}(2,\\ 0)$과 점 $(x,\\ y)$ 사이 거리의 제곱이다. 사각형 둘레 위에서 이 값이 가장 클 때와 가장 작을 때를 찾는다.","확인":null,"스킬":"A6"},{"제목":"최댓값 M","힌트":"점 P에서 각 꼭짓점까지 거리의 제곱은 얼마인가?","식":["$\\mathrm{PO}^2=4,\\ \\mathrm{PA}^2=4,\\ \\mathrm{PB}^2=5,\\ \\mathrm{PC}^2=5$","$M=5$"],"설명":"선분 위의 점까지의 거리는 끝점에서 가장 크므로 최댓값은 꼭짓점에서 생긴다. 가장 큰 값은 $\\mathrm{PB}^2=\\mathrm{PC}^2=5$이다.","확인":"5","스킬":"S4"},{"제목":"최솟값 m","힌트":"점 P에서 가장 가까운 변까지의 거리는 얼마인가?","식":["$\\mathrm{AB}:\\ 3x-2y-10=0$","$d=\\frac{|3\\cdot 2-10|}{\\sqrt{13}}=\\frac{4}{\\sqrt{13}}$","$m=d^2=\\frac{16}{13}$"],"설명":"나머지 세 변까지 거리의 제곱은 $\\mathrm{OA}$가 $2$, $\\mathrm{BC}$가 $\\frac{5}{2}$, $\\mathrm{CO}$가 $\\frac{16}{5}$로 더 크다. 점 $\\mathrm{P}$에서 $\\mathrm{AB}$에 내린 수선의 발은 변 위에 있으므로 최솟값은 $\\frac{16}{13}$이다.","확인":"16/13","스킬":"S4","고비":true},{"제목":"M과 m으로 구한 값","힌트":"$M=5$, $m=\\frac{16}{13}$을 대입하면 $13(M-m)$은 얼마인가?","식":["$13\\left(5-\\frac{16}{13}\\right)=65-16=49$"],"설명":"$M-m=\\frac{49}{13}$이므로 $13(M-m)=49$이다.","확인":"49","스킬":"A6"}]},"ns-fc4666563504":{"길":"A, B의 좌표를 문자로 잡고, 직각삼각형의 외접원 지름 OD를 구한다","단계":[{"제목":"점 A, B의 좌표","힌트":"점 C의 좌표를 $(t,\\ tm)$으로 놓으면 A와 B의 좌표는 어떻게 되는가?","식":["$\\mathrm{C}(t,\\ tm),\\ \\mathrm{A}(tm,\\ t)$","$\\mathrm{B}(0,\\ 2t)$"],"설명":"$\\overline{\\mathrm{OC}}=\\overline{\\mathrm{OA}}=t\\sqrt{m^2+1}$이고 $\\mathrm{C}$가 $y=mx$ 위에 있으므로 $\\mathrm{C}(t,\\ tm)$이며, $y=x$에 대칭인 $\\mathrm{A}$는 $(tm,\\ t)$이다. $\\overline{\\mathrm{AO}}=\\overline{\\mathrm{AB}}$이므로 $\\mathrm{A}$에서 $y$축에 내린 수선의 발이 $\\overline{\\mathrm{OB}}$의 중점이고, 그 $y$좌표가 $t$이므로 $\\mathrm{B}(0,\\ 2t)$이다.","확인":null,"스킬":"S4"},{"제목":"외접원의 지름 찾기","힌트":"직선 AB의 기울기와 직선 $y=mx$의 기울기의 곱은 얼마인가?","식":["$\\mathrm{AB}:\\ y=-\\frac{1}{m}x+2t$","$m\\times\\left(-\\frac{1}{m}\\right)=-1$"],"설명":"$\\mathrm{A}$와 $\\mathrm{B}$를 지나는 직선의 기울기는 $\\frac{t-2t}{tm-0}=-\\frac{1}{m}$이다. 직선 $\\mathrm{AB}$와 $y=mx$가 수직이므로 $\\angle \\mathrm{OED}=90^\\circ$이고, 직각삼각형의 외접원은 빗변 $\\mathrm{OD}$를 지름으로 한다.","확인":null,"스킬":"S5","고비":true},{"제목":"점 D의 좌표와 지름 OD","힌트":"직선 $y=x$와 직선 AB의 교점 D의 좌표는 어떻게 되는가?","식":["$\\mathrm{D}\\left(\\frac{2tm}{m+1},\\ \\frac{2tm}{m+1}\\right)$","$\\overline{\\mathrm{OD}}=\\frac{2\\sqrt{2}\\,tm}{m+1}$"],"설명":"$x=-\\frac{1}{m}x+2t$에서 $x\\left(1+\\frac{1}{m}\\right)=2t$이므로 $x=\\frac{2tm}{m+1}$이다. $\\mathrm{D}$는 $y=x$ 위의 점이므로 $\\overline{\\mathrm{OD}}$는 $x$좌표의 $\\sqrt{2}$배이다.","확인":null,"스킬":"G1"},{"제목":"외접원의 넓이","힌트":"지름이 $\\overline{\\mathrm{OD}}$이므로 반지름의 제곱에 $\\pi$를 곱하면 어떤 식이 되는가?","식":["$\\pi\\left(\\frac{\\sqrt{2}\\,tm}{m+1}\\right)^2=\\frac{2m^2}{m^2+2m+1}t^2\\pi$"],"설명":"반지름은 $\\frac{\\sqrt{2}\\,tm}{m+1}$이고 $(m+1)^2=m^2+2m+1$이다.","확인":null,"스킬":"S5"},{"제목":"a+b+c의 값","힌트":"주어진 꼴과 비교해 $a$, $b$, $c$를 구하면 합은 얼마인가?","식":["$a=2,\\ b=1,\\ c=2$","$a+b+c=5$"],"설명":"분모 $m^2+am+b$는 $m^2+2m+1$과, 분자 $cm^2$은 $2m^2$과 각각 비교한다.","확인":"5","스킬":"A3"}]},"ns-00f5aaf9aada":{"길":"세 대칭점의 좌표를 구하고, 사다리꼴에서 삼각형 둘을 빼 넓이를 구한다","단계":[{"제목":"세 대칭점의 좌표","힌트":"점 $(2,\\ 1)$을 직선과 점에 대해 각각 대칭이동하면 좌표는 어떻게 되는가?","식":["$\\mathrm{B}(2\\times 3-2,\\ 1)=(4,\\ 1)$","$\\mathrm{C}(2,\\ 2\\times 3-1)=(2,\\ 5)$","$\\mathrm{D}(2\\times 1-2,\\ 2\\times 2-1)=(0,\\ 3)$"],"설명":"직선 $x=3$에 대한 대칭은 $x$좌표만 $2\\times 3-x$로, 직선 $y=3$에 대한 대칭은 $y$좌표만 $2\\times 3-y$로 바뀐다. 점 $(1,\\ 2)$에 대한 대칭은 두 좌표 모두 $2\\times(\\text{중심 좌표})-(\\text{원래 좌표})$로 바뀐다.","확인":null,"스킬":"G10"},{"제목":"삼각형을 둘러싼 사다리꼴의 넓이","힌트":"점 $(0,\\ 5)$, $(2,\\ 5)$, $(4,\\ 1)$, $(0,\\ 1)$을 꼭짓점으로 하는 사다리꼴의 넓이는 얼마인가?","식":["$\\frac{1}{2}\\times(2+4)\\times 4=12$"],"설명":"윗변은 $(0,\\ 5)$에서 $(2,\\ 5)$까지 $2$, 아랫변은 $(0,\\ 1)$에서 $(4,\\ 1)$까지 $4$, 높이는 $4$이다. 점 $\\mathrm{C}$, $\\mathrm{B}$가 이 사다리꼴의 꼭짓점이고 점 $\\mathrm{D}$는 왼쪽 변 위에 있다.","확인":"12","스킬":"G10","고비":true},{"제목":"남는 두 삼각형을 빼서 구한 넓이","힌트":"사다리꼴에서 삼각형 $\\mathrm{BCD}$ 바깥의 두 직각삼각형 넓이는 각각 얼마인가?","식":["$12-\\frac{1}{2}\\times 2\\times 2-\\frac{1}{2}\\times 2\\times 4=12-2-4=6$"],"설명":"위쪽 삼각형은 두 점 $(0,\\ 5)$, $(2,\\ 5)$와 $\\mathrm{D}$로 이루어져 넓이가 $2$이고, 아래쪽 삼각형은 $(0,\\ 1)$, $\\mathrm{B}$, $\\mathrm{D}$로 이루어져 넓이가 $4$이다. 이를 빼면 삼각형 $\\mathrm{BCD}$의 넓이가 남는다.","확인":"6","스킬":"G10"}]},"ns-027649f1b714":{"길":"옮긴 원들이 덮는 영역을 찾고, 영역에서 y축까지의 최소 거리를 두 번 더한다","단계":[{"제목":"평행이동한 도형이 덮는 영역","힌트":"$(a,\\ b)$는 어떤 원 위의 점이며, 그 점을 중심으로 반지름 $1$인 원을 모두 그리면 어떤 영역이 되는가?","식":["$(a,\\ b)$는 중심 $(5,\\ 3)$, 반지름 $1$인 원 위의 점","$C'$ 전체는 중심 $(5,\\ 3)$, 반지름 $2$인 원의 내부와 둘레"],"설명":"원 $C$를 $(a,\\ b)$만큼 옮기면 중심이 $(a,\\ b)$이고 반지름이 $1$인 원이 된다. $(a,\\ b)$가 반지름 $1$인 원 위를 움직이므로 이 원들이 지나는 점은 중심 $(5,\\ 3)$에서 거리가 $2$ 이하인 점이다.","확인":null,"스킬":"G4","고비":true},{"제목":"영역에서 y축까지의 최소 거리","힌트":"중심 $(5,\\ 3)$에서 $y$축까지의 거리에서 반지름을 빼면 얼마인가?","식":["$5-2=3$"],"설명":"중심에서 $y$축까지의 거리가 $5$이고 반지름이 $2$이므로, 영역 위의 점에서 $y$축 위의 점까지의 거리는 $3$ 이상이다. 등호는 $(3,\\ 3)$과 $(0,\\ 3)$ 사이에서 성립한다.","확인":"3","스킬":"S13"},{"제목":"AP+BP의 최솟값","힌트":"$\\overline{\\mathrm{AP}}$와 $\\overline{\\mathrm{BP}}$가 각각 $3$ 이상이면 합은 얼마 이상이며, 언제 같아지는가?","식":["$\\overline{\\mathrm{AP}}+\\overline{\\mathrm{BP}}\\ge 3+3=6$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$를 모두 $(3,\\ 3)$, $\\mathrm{P}$를 $(0,\\ 3)$으로 잡으면 합이 $6$이 되어 등호가 성립한다. 두 점이 같은 점인 경우를 허용하므로 가능하다.","확인":"6","스킬":"G4"}]},"ns-07dc8fda0dba":{"길":"직선 y=x 대칭으로 좌표를 바꿔 쓰고, 두 점의 좌표를 비교해 a, b를 구한다","단계":[{"제목":"대칭이동한 점의 좌표","힌트":"직선 $y=x$에 대한 대칭이동에서 $x$좌표와 $y$좌표는 어떻게 바뀌는가?","식":["$(2a,\\ -3b+1)\\to(-3b+1,\\ 2a)$"],"설명":"직선 $y=x$에 대한 대칭이동은 $x$좌표와 $y$좌표를 서로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"좌표 비교로 구한 a, b","힌트":"대칭이동한 점이 $(5b-9,\\ -4a+1)$과 같으려면 $x$좌표끼리, $y$좌표끼리 어떤 식이 세워지는가?","식":["$-3b+1=5b-9,\\ 2a=-4a+1$","$a=\\frac{1}{6},\\ b=\\frac{5}{4}$"],"설명":"두 점이 같으므로 대응하는 좌표가 각각 같다. 첫 식에서 $8b=10$, 둘째 식에서 $6a=1$이다.","확인":null,"스킬":"A10","고비":true},{"제목":"6a+4b의 값","힌트":"구한 $a$, $b$를 대입하면 $6a+4b$는 얼마인가?","식":["$6\\times\\frac{1}{6}+4\\times\\frac{5}{4}=1+5=6$"],"설명":"$6a=1$, $4b=5$이므로 합은 $6$이다.","확인":"6","스킬":"A10"}]},"ns-08028a9a3ebb":{"길":"결과 점에서 평행이동과 대칭이동을 거꾸로 되돌려 처음 점을 구한다","단계":[{"제목":"평행이동 되돌리기","힌트":"마지막에 $x$축 방향으로 $2$, $y$축 방향으로 $3$ 옮겼으므로, 그 전의 점은 어디인가?","식":["$(-3-2,\\ 4-3)=(-5,\\ 1)$"],"설명":"마지막 이동을 거꾸로 하려면 $x$좌표에서 $2$를, $y$좌표에서 $3$을 뺀다. 이 점이 대칭이동한 직후의 점이다.","확인":null,"스킬":"C5","고비":true},{"제목":"대칭이동 되돌리기","힌트":"직선 $y=-x$에 대한 대칭이동에서 좌표는 어떻게 바뀌는가?","식":["$(x,\\ y)\\to(-y,\\ -x)$","$(-5,\\ 1)\\to(-1,\\ 5)$"],"설명":"직선 $y=-x$에 대한 대칭이동은 $(x,\\ y)$를 $(-y,\\ -x)$로 보내고, 같은 이동을 다시 하면 원래 점으로 돌아온다. 따라서 처음 점은 $(-1,\\ 5)$이다.","확인":null,"스킬":"G4"},{"제목":"a+b의 값","힌트":"처음 점의 두 좌표를 더하면 얼마인가?","식":["$a=-1,\\ b=5$","$a+b=4$"],"설명":"처음 점 $(a,\\ b)$가 $(-1,\\ 5)$이다.","확인":"4","스킬":"C5"}]},"ns-08aa8ab3aa59":{"길":"대칭이동한 두 원에서 최대일 때의 점 위치를 잡아 삼각형의 밑변과 높이를 구한다","단계":[{"제목":"대칭이동한 두 원의 방정식","힌트":"$\\mathrm{P}'$이 그리는 도형과 $\\mathrm{Q}'$이 그리는 도형은 각각 어떤 원인가?","식":["$\\mathrm{P}':\\ (x+1)^2+(y+2)^2=16$","$\\mathrm{Q}':\\ (x-2)^2+(y+1)^2=16$"],"설명":"$y$축 대칭은 $x$를 $-x$로, 직선 $y=-x$ 대칭은 $(x,\\ y)$를 $(-y,\\ -x)$로 바꾼다. 두 원의 반지름은 모두 $4$이고 중심은 각각 $(-1,\\ -2)$, $(2,\\ -1)$이다.","확인":null,"스킬":"G4"},{"제목":"선분의 길이가 최대가 되는 조건","힌트":"두 원 위의 점 사이 거리가 최대일 때 두 점은 중심을 잇는 직선 위의 어디에 놓이는가?","식":["$\\text{중심 사이 거리}=\\sqrt{3^2+1^2}=\\sqrt{10}$","$\\overline{\\mathrm{P}'\\mathrm{Q}'}=\\sqrt{10}+4+4=\\sqrt{10}+8$"],"설명":"두 점이 중심을 지나는 직선 위에서 서로 바깥쪽 끝에 놓일 때 거리가 최대이다. 그 값은 중심 사이 거리에 두 반지름을 더한 값이다.","확인":null,"스킬":"S2","고비":true},{"제목":"두 중심을 지나는 직선의 방정식","힌트":"두 중심 $(-1,\\ -2)$, $(2,\\ -1)$을 지나는 직선의 방정식은 무엇인가?","식":["$y=\\frac{1}{3}x-\\frac{5}{3}$","$x-3y-5=0$"],"설명":"두 중심을 지나는 직선의 기울기는 $\\frac{-1-(-2)}{2-(-1)}=\\frac{1}{3}$이다. 길이가 최대일 때 $\\mathrm{P}'$, $\\mathrm{Q}'$은 모두 이 직선 위에 있다.","확인":null,"스킬":"G9"},{"제목":"원점에서 직선까지의 거리","힌트":"원점 $\\mathrm{O}$에서 직선 $x-3y-5=0$까지의 거리는 얼마인가?","식":["$\\frac{|-5|}{\\sqrt{1^2+(-3)^2}}=\\frac{5}{\\sqrt{10}}$"],"설명":"삼각형 $\\mathrm{OP'Q'}$에서 밑변을 $\\overline{\\mathrm{P}'\\mathrm{Q}'}$으로 보면 높이는 원점에서 이 직선까지의 거리이다.","확인":null,"스킬":"G1"},{"제목":"삼각형의 넓이","힌트":"밑변 $\\sqrt{10}+8$, 높이 $\\frac{5}{\\sqrt{10}}$인 삼각형의 넓이는 얼마인가?","식":["$\\frac{1}{2}\\times\\frac{5}{\\sqrt{10}}\\times(\\sqrt{10}+8)=\\frac{5}{2}+\\frac{20}{\\sqrt{10}}$","$=2\\sqrt{10}+\\frac{5}{2}$"],"설명":"$\\frac{20}{\\sqrt{10}}=2\\sqrt{10}$이므로 넓이는 $2\\sqrt{10}+\\frac{5}{2}$이다.","확인":null,"스킬":"G10"}]},"ns-08e9cb1da7d9":{"길":"y=x 대칭은 x와 y를 바꿔 쓰고, 수직 조건과 한 점으로 직선을 정한다","단계":[{"제목":"대칭이동한 직선의 방정식","힌트":"직선 $y=x$에 대한 대칭이동은 식에서 $x$와 $y$를 어떻게 바꾸는가?","식":["$x=2y+1$","$y=\\frac{1}{2}x-\\frac{1}{2}$"],"설명":"$y=x$에 대한 대칭이동은 $x$와 $y$를 서로 바꾼다. 바꾼 식을 $y$에 대해 정리하면 기울기가 $\\frac{1}{2}$인 직선이다.","확인":null,"스킬":"G4","고비":true},{"제목":"수직인 직선의 기울기","힌트":"기울기가 $\\frac{1}{2}$인 직선과 수직인 직선의 기울기는 얼마인가?","식":["$\\frac{1}{2}\\times m=-1,\\ m=-2$"],"설명":"두 직선이 수직이면 기울기의 곱이 $-1$이다.","확인":"-2","스킬":"G9"},{"제목":"점 (8, -3)을 지나는 직선","힌트":"기울기가 $-2$이고 점 $(8,\\ -3)$을 지나는 직선의 방정식은 무엇인가?","식":["$y+3=-2(x-8)$","$y=-2x+13$"],"설명":"점과 기울기가 주어진 직선은 $y-y_1=m(x-x_1)$ 꼴로 세운 뒤 $y$에 대해 정리한다.","확인":null,"스킬":"G3"}]},"ns-09a9fed3a8c7":{"길":"평행이동한 직선의 식을 세우고, 수직 조건과 x절편으로 a, b를 구한다","단계":[{"제목":"평행이동한 직선의 방정식","힌트":"$x$축 방향으로 $2$, $y$축 방향으로 $-3$ 옮기면 $x$, $y$ 대신 무엇을 대입하는가?","식":["$y+3=a(x-2)+b$","$y=ax-2a+b-3$"],"설명":"$x$축 방향으로 $p$, $y$축 방향으로 $q$만큼 옮기면 $x$ 대신 $x-p$, $y$ 대신 $y-q$를 넣는다. 여기서 $p=2$, $q=-3$이다.","확인":null,"스킬":"G4"},{"제목":"수직 조건으로 구한 기울기","힌트":"직선 $x-4y-12=0$의 기울기는 얼마이며, 수직인 직선의 기울기는 얼마인가?","식":["$x-4y-12=0\\Rightarrow y=\\frac{1}{4}x-3$","$a\\times\\frac{1}{4}=-1,\\ a=-4$"],"설명":"평행이동해도 기울기는 변하지 않으므로 옮긴 직선의 기울기는 $a$이다. 수직이면 두 기울기의 곱이 $-1$이다.","확인":"-4","스킬":"G9"},{"제목":"x절편 조건으로 구한 a+b","힌트":"직선 $x-4y-12=0$이 $x$축과 만나는 점을 옮긴 직선도 지난다면 $b$는 얼마인가?","식":["$x-4y-12=0$의 $x$절편 $(12,\\ 0)$","$0=-4\\times 12+8+b-3,\\ b=43$","$a+b=-4+43=39$"],"설명":"두 직선이 $x$축 위에서 만나므로 옮긴 직선은 $(12,\\ 0)$을 지난다. 이 점을 $y=-4x+8+b-3$에 대입하면 $b=43$이다.","확인":"39","스킬":"G1","고비":true}]},"ns-0a17bd05da21":{"길":"평행이동한 점의 좌표를 (7, -9)와 같다고 놓고 a, b를 구한다","단계":[{"제목":"좌표를 맞춰 구한 a, b","힌트":"평행이동한 점의 $x$좌표, $y$좌표를 각각 $7$, $-9$와 같다고 놓으면 어떤 식이 되는가?","식":["$3+a=7,\\ -1+b=-9$","$a=4,\\ b=-8$"],"설명":"$x$축 방향으로 $a$, $y$축 방향으로 $b$ 옮기면 점은 $(3+a,\\ -1+b)$가 된다. 이 점이 $(7,\\ -9)$와 일치한다.","확인":null,"스킬":"G4","고비":true},{"제목":"a+b의 값","힌트":"구한 $a$, $b$를 더하면 얼마인가?","식":["$a+b=4+(-8)=-4$"],"설명":"$a=4$, $b=-8$이다.","확인":"-4","스킬":"G4"}]},"ns-0b8ce87c369f":{"길":"접는 선을 AB의 수직이등분선으로 놓고, 원점과 P도 같은 선에 대해 대칭이라는 조건을 쓴다","단계":[{"제목":"접는 선의 방정식","힌트":"점 A와 B가 겹치도록 접는 선은 선분 AB의 어떤 직선인가?","식":["$\\overline{\\mathrm{AB}}$의 중점 $(4,\\ 3)$, 기울기 $\\frac{5-1}{5-3}=2$","$y=-\\frac{1}{2}x+5$"],"설명":"접는 선은 $\\overline{\\mathrm{AB}}$의 수직이등분선이다. 중점 $(4,\\ 3)$을 지나고, 기울기는 $2$와 곱해서 $-1$이 되는 $-\\frac{1}{2}$이다.","확인":null,"스킬":"G4"},{"제목":"원점과 P가 만족하는 두 조건","힌트":"$\\overline{\\mathrm{OP}}$의 중점은 접는 선 위에 있고 $\\overline{\\mathrm{OP}}$는 접는 선과 수직일 때, 어떤 식이 세워지는가?","식":["$\\frac{b}{2}=-\\frac{1}{2}\\times\\frac{a}{2}+5\\ \\Rightarrow\\ a+2b=20$","$\\frac{b}{a}=2\\ \\Rightarrow\\ b=2a$"],"설명":"접는 선은 $\\overline{\\mathrm{OP}}$의 수직이등분선이기도 하다. 중점 $\\left(\\frac{a}{2},\\ \\frac{b}{2}\\right)$가 접는 선 위에 있고, $\\overline{\\mathrm{OP}}$의 기울기 $\\frac{b}{a}$는 접는 선의 기울기 $-\\frac{1}{2}$와 곱이 $-1$이므로 $2$이다.","확인":null,"스킬":"G4","고비":true},{"제목":"연립방정식의 풀이와 ab의 값","힌트":"두 식을 연립해 $a$, $b$를 구하면 $ab$는 얼마인가?","식":["$a+2(2a)=20,\\ a=4,\\ b=8$","$ab=32$"],"설명":"$b=2a$를 $a+2b=20$에 대입하면 $5a=20$이므로 $a=4$이고 $b=8$이다.","확인":"32","스킬":"A10"}]},"ns-0f611f279250":{"길":"대칭점이 만족하는 조건으로 x, y를 x', y'로 나타내 직선의 식에 대입한다","단계":[{"제목":"대칭점이 만족하는 조건","힌트":"점 P와 대칭점 P'에 대해 선분 PP'의 중점은 어디에 있고, 직선 PP'는 대칭축과 어떤 관계인가?","식":["$\\frac{x+x'}{2}+\\frac{y+y'}{2}-1=0,\\ \\frac{y'-y}{x'-x}=1$","$x=1-y',\\ y=1-x'$"],"설명":"중점이 직선 $x+y-1=0$ 위에 있고, 직선 $\\mathrm{PP}'$는 기울기가 $-1$인 이 직선과 수직이므로 기울기가 $1$이다. 두 식을 연립하면 $x=1-y'$, $y=1-x'$이다.","확인":null,"스킬":"G4","고비":true},{"제목":"대칭이동한 직선의 방정식","힌트":"$x=1-y'$, $y=1-x'$을 $x-2y+1=0$에 대입하면 어떤 식이 되는가?","식":["$(1-y')-2(1-x')+1=0$","$2x'-y'=0$"],"설명":"점 $\\mathrm{P}$가 직선 $x-2y+1=0$ 위에 있으므로 대입할 수 있다. $x'$, $y'$을 $x$, $y$로 고쳐 쓰면 $2x-y=0$이고, $ax+by=0$과 비교하면 $a=2$, $b=-1$이다.","확인":null,"스킬":"G4"},{"제목":"-2b/a의 값","힌트":"$a=2$, $b=-1$을 대입하면 $-\\frac{2b}{a}$는 얼마인가?","식":["$-\\frac{2\\times(-1)}{2}=1$"],"설명":"$-2b=2$이고 $a=2$이므로 값은 $1$이다.","확인":"1","스킬":"G4"}]},"ns-104b0b97ccc9":{"길":"이동마다 f의 x, y 자리에 넣을 식을 정해 네 번 차례로 바꾼다","단계":[{"제목":"x축 방향 평행이동","힌트":"$x$축의 양의 방향으로 $2$만큼 평행이동하면 $x$ 자리에 무엇을 넣는가?","식":["$x\\to x-2$","$f(1-y,\\ 2x-4)=0$"],"설명":"도형을 $x$축 방향으로 $p$만큼 옮기면 $x$ 자리에 $x-p$를 넣는다.","확인":null,"스킬":"G4"},{"제목":"직선 y=2에 대한 대칭이동","힌트":"직선 $y=2$에 대한 대칭이동에서 $y$ 자리에 무엇을 넣는가?","식":["$y\\to 4-y$","$f(-3+y,\\ 2x-4)=0$"],"설명":"직선 $y=k$에 대한 대칭이동은 $y$ 자리에 $2k-y$를 넣는다. $f(1-(4-y),\\ 2x-4)$를 정리하면 첫 자리가 $-3+y$이다.","확인":null,"스킬":"G4"},{"제목":"y축 대칭이동","힌트":"$y$축에 대한 대칭이동에서 $x$ 자리에 무엇을 넣는가?","식":["$x\\to -x$","$f(-3+y,\\ -2x-4)=0$"],"설명":"$y$축 대칭이동은 $x$ 자리에 $-x$를 넣는다. 둘째 자리 $2x-4$가 $-2x-4$로 바뀐다.","확인":null,"스킬":"G4"},{"제목":"점 (1, 1)에 대한 대칭이동","힌트":"점 $(1,\\ 1)$에 대한 대칭이동에서 $x$, $y$ 자리에 각각 무엇을 넣는가?","식":["$x\\to 2-x,\\ y\\to 2-y$","$f(-3+(2-y),\\ -2(2-x)-4)=f(-1-y,\\ 2x-8)=0$"],"설명":"점 $(a,\\ b)$에 대한 대칭이동은 $x$ 자리에 $2a-x$, $y$ 자리에 $2b-y$를 넣는다. 두 자리를 각각 정리하면 $-1-y$와 $2x-8$이 된다.","확인":null,"스킬":"G4","고비":true}]},"ns-10d0699071e6":{"길":"평행이동한 직선의 식을 세우고, 수직 조건과 y절편 조건으로 a, b를 정한다","단계":[{"제목":"평행이동한 직선의 방정식","힌트":"$x$축 방향으로 $-1$, $y$축 방향으로 $2$만큼 옮기면 $x$, $y$ 자리에 무엇을 넣는가?","식":["$y-2=a(x+1)+b$","$y=ax+a+b+2$"],"설명":"$x$ 대신 $x+1$, $y$ 대신 $y-2$를 넣는다.","확인":null,"스킬":"G4"},{"제목":"수직 조건으로 구한 기울기","힌트":"직선 $y=3x-1$과 수직인 직선의 기울기는 얼마인가?","식":["$a\\times 3=-1$","$a=-\\frac{1}{3}$"],"설명":"평행이동해도 기울기는 변하지 않으므로 옮긴 직선의 기울기가 $a$이다. 수직인 두 직선은 기울기의 곱이 $-1$이다.","확인":"-1/3","스킬":"G9"},{"제목":"y절편 조건으로 구한 a+b","힌트":"$y$축 위에서 만난다면 두 직선의 $y$절편은 어떤 관계인가?","식":["$a+b+2=-1$","$a+b=-3$"],"설명":"$y$축 위에서 만나므로 옮긴 직선의 $y$절편 $a+b+2$가 $y=3x-1$의 $y$절편 $-1$과 같다.","확인":"-3","스킬":"G1","고비":true}]},"ns-1271018e45d2":{"길":"세 대칭이동으로 생기는 네 직선이 마름모를 이룸을 보고 넓이를 b로 나타낸다","단계":[{"제목":"대칭이동으로 생기는 직선","힌트":"$f$, $g$, $h$는 각각 어떤 대칭이동이며, 직선 $y=-2x+b$는 어떤 직선으로 바뀌는가?","식":["$f$는 $y$축 대칭이므로 $y=2x+b$","$g$는 $x$축 대칭이므로 $y=2x-b$","$h$는 원점 대칭이므로 $y=-2x-b$"],"설명":"제1사분면의 부분은 두 점 $(0,\\ b)$, $\\left(\\frac{b}{2},\\ 0\\right)$를 잇는 선분이다. 세 대칭이동으로 나머지 세 사분면에 같은 모양의 선분이 하나씩 생기고, 네 선분이 마름모를 이룬다.","확인":null,"스킬":"G4"},{"제목":"둘러싸인 도형의 넓이","힌트":"꼭짓점이 $\\left(\\pm\\frac{b}{2},\\ 0\\right)$, $(0,\\ \\pm b)$인 마름모의 두 대각선의 길이는 각각 얼마인가?","식":["가로 대각선 $b$, 세로 대각선 $2b$","$\\frac{1}{2}\\times b\\times 2b=b^2$"],"설명":"마름모의 넓이는 두 대각선의 곱의 절반이다. 한 사분면의 삼각형 넓이 $\\frac{1}{2}\\times\\frac{b}{2}\\times b$의 $4$배로 구해도 $b^2$이다.","확인":null,"스킬":"G10","고비":true},{"제목":"b의 값","힌트":"넓이 $b^2$이 $1$이 되는 양수 $b$는 얼마인가?","식":["$b^2=1$","$b=1\\ (b>0)$"],"설명":"$b>0$이므로 $b=-1$은 버린다.","확인":"1","스킬":"G10"}]},"ns-1c18c7185c21":{"길":"접는 선을 한 쌍의 대칭점으로 정하고, 다른 쌍도 같은 선에 대한 대칭 조건으로 푼다","단계":[{"제목":"접는 선의 방정식","힌트":"점 $(0,\\ 2)$와 $(4,\\ 0)$이 겹치도록 접는 선은 두 점을 잇는 선분의 어떤 직선인가?","식":["중점 $(2,\\ 1)$, 선분의 기울기 $-\\frac{1}{2}$","$y=2x-3$"],"설명":"접는 선은 두 점을 잇는 선분의 수직이등분선이다. 기울기는 $-\\frac{1}{2}$와 곱이 $-1$인 $2$이고 중점 $(2,\\ 1)$을 지난다.","확인":null,"스킬":"G4"},{"제목":"(7, 1)과 (m, n)이 만족하는 두 조건","힌트":"접는 선은 두 점 $(7,\\ 1)$, $(m,\\ n)$을 잇는 선분의 수직이등분선이기도 하다. 이 조건을 식으로 쓰면 무엇인가?","식":["$\\frac{1+n}{2}=2\\times\\frac{7+m}{2}-3\\ \\Rightarrow\\ 2m-n+7=0$","$\\frac{n-1}{m-7}=-\\frac{1}{2}\\ \\Rightarrow\\ m+2n=9$"],"설명":"중점 $\\left(\\frac{7+m}{2},\\ \\frac{1+n}{2}\\right)$가 접는 선 위에 있다. 두 점을 잇는 직선의 기울기는 접는 선의 기울기 $2$와 곱이 $-1$이므로 $-\\frac{1}{2}$이다.","확인":null,"스킬":"G4","고비":true},{"제목":"m, n의 값과 mn","힌트":"두 식을 연립해 $m$, $n$을 구하면 $mn$은 얼마인가?","식":["$m+2(2m+7)=9,\\ m=-1,\\ n=5$","$mn=-5$"],"설명":"첫 식에서 $n=2m+7$이므로 이를 둘째 식에 대입하면 $5m+14=9$이다.","확인":"-5","스킬":"A10"}]},"ns-1c7edb266e6b":{"길":"옮긴 직선의 식을 세우고, 접하는 조건을 중심과 직선 사이 거리로 쓴다","단계":[{"제목":"옮긴 직선의 방정식","힌트":"직선 $y=\\frac{x}{2}$를 $y=x$에 대해 대칭이동하고 $x$축 방향으로 $m$만큼 옮긴 직선의 방정식은 무엇인가?","식":["$x=\\frac{y}{2}\\ \\Rightarrow\\ y=2x$","$y=2(x-m)\\ \\Rightarrow\\ 2x-y-2m=0$"],"설명":"$y=x$에 대한 대칭이동은 $x$와 $y$를 서로 바꾼다. $x$축 방향으로 $m$만큼 옮기므로 $x$ 대신 $x-m$을 넣는다.","확인":null,"스킬":"G4"},{"제목":"원에 접하는 조건","힌트":"원의 중심 $(2,\\ 1)$에서 직선까지의 거리가 반지름과 같다고 놓으면 어떤 식이 되는가?","식":["$\\frac{|2\\times 2-1-2m|}{\\sqrt{5}}=\\sqrt{5}$","$|3-2m|=5$"],"설명":"원과 직선이 접하면 중심에서 직선까지의 거리가 반지름 $\\sqrt{5}$와 같다. 점과 직선 사이 거리 공식의 분모는 $\\sqrt{2^2+(-1)^2}=\\sqrt{5}$이다.","확인":null,"스킬":"G2","고비":true},{"제목":"m의 값","힌트":"절댓값 식을 풀고 $m>0$인 값을 고르면 $m$은 얼마인가?","식":["$3-2m=\\pm 5$","$m=-1$ 또는 $m=4$","$m>0$이므로 $m=4$"],"설명":"$3-2m=5$이면 $m=-1$, $3-2m=-5$이면 $m=4$이고 조건 $m>0$에 맞는 것은 $4$이다.","확인":"4","스킬":"G2"}]},"ns-247cea2b0708":{"길":"점의 이동에서 이동량을 읽고, 원의 식의 x, y 자리에 그 이동량을 반영한다","단계":[{"제목":"평행이동의 이동량","힌트":"점 $(1,\\ 2)$가 $(3,\\ 1)$로 옮겨질 때 $x$좌표와 $y$좌표는 각각 얼마나 변하는가?","식":["$x$축 방향으로 $3-1=2$, $y$축 방향으로 $1-2=-1$"],"설명":"도착점의 좌표에서 출발점의 좌표를 뺀 값이 이동량이다.","확인":null,"스킬":"G4"},{"제목":"이동한 도형의 방정식","힌트":"$x$축 방향으로 $2$, $y$축 방향으로 $-1$ 옮기면 $x$, $y$ 자리에 무엇을 넣는가?","식":["$(x-2+1)^2+(y+1-1)^2=5$","$(x-1)^2+y^2=5$"],"설명":"$x$ 대신 $x-2$, $y$ 대신 $y+1$을 넣는다. 원의 중심 $(-1,\\ 1)$이 $(1,\\ 0)$으로 옮겨지고 반지름은 변하지 않는다.","확인":null,"스킬":"G4","고비":true}]},"ns-260aca3ed9e5":{"길":"C를 두 반지름에 대해 대칭이동해 세 변의 합을 한 선분의 길이로 바꾼다","단계":[{"제목":"둘레를 한 선분으로 펴기","힌트":"점 $\\mathrm{C}$를 직선 $\\mathrm{OP}$, $\\mathrm{OQ}$에 대해 각각 대칭이동한 점을 $\\mathrm{C}_1$, $\\mathrm{C}_2$라 하면 세 변의 합은 어떤 꺾인 선의 길이와 같은가?","식":["$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{C}_1\\mathrm{A}},\\ \\overline{\\mathrm{CB}}=\\overline{\\mathrm{C}_2\\mathrm{B}}$","$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}=\\overline{\\mathrm{C}_1\\mathrm{A}}+\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}_2}\\ge\\overline{\\mathrm{C}_1\\mathrm{C}_2}$"],"설명":"직선에 대한 대칭이동은 거리를 보존하므로 점 $\\mathrm{A}$, $\\mathrm{B}$에서 $\\mathrm{C}$까지의 거리는 $\\mathrm{C}_1$, $\\mathrm{C}_2$까지의 거리와 같다. 꺾인 선의 길이는 양 끝을 잇는 선분의 길이보다 짧을 수 없다.","확인":null,"스킬":"S14","고비":true},{"제목":"도형을 좌표평면에 놓기","힌트":"점 O를 원점으로 하고 $y$축이 각 POQ를 이등분하도록 놓으면 직선 OP, OQ의 방정식과 점 C의 좌표는 무엇인가?","식":["$\\mathrm{OQ}:\\ y=\\sqrt{3}x,\\ \\mathrm{OP}:\\ y=-\\sqrt{3}x$","$\\mathrm{C}(0,\\ 10)$"],"설명":"$y$축이 각을 이등분하면 두 반지름은 $x$축과 $60^\\circ$, $120^\\circ$의 각을 이루므로 기울기가 $\\pm\\sqrt{3}$이다. 대칭이동하면 $\\overline{\\mathrm{OC}_1}=\\overline{\\mathrm{OC}_2}=10$, $\\angle \\mathrm{C}_1\\mathrm{OC}_2=120^\\circ$이므로 $\\mathrm{C}$의 위치와 관계없이 값이 같다. 계산이 쉽도록 $\\mathrm{C}$를 $(0,\\ 10)$에 둔다.","확인":null,"스킬":"S4"},{"제목":"대칭점의 좌표","힌트":"$(0,\\ 10)$을 직선 $y=\\sqrt{3}x$와 $y=-\\sqrt{3}x$에 대해 대칭이동한 점의 좌표는 각각 무엇인가?","식":["$\\mathrm{C}_1(5\\sqrt{3},\\ 5),\\ \\mathrm{C}_2(-5\\sqrt{3},\\ 5)$"],"설명":"$\\overline{\\mathrm{CC}_1}$의 중점이 $y=\\sqrt{3}x$ 위에 있고 $\\overline{\\mathrm{CC}_1}$의 기울기가 $-\\frac{1}{\\sqrt{3}}$이라는 두 조건을 연립하면 $\\mathrm{C}_1(5\\sqrt{3},\\ 5)$이다. 두 직선은 $y$축에 대칭이므로 $\\mathrm{C}_2$는 $x$좌표의 부호만 바뀐다.","확인":null,"스킬":"G4"},{"제목":"둘레의 최솟값","힌트":"두 점 $\\mathrm{C}_1$, $\\mathrm{C}_2$ 사이의 거리는 얼마인가?","식":["$\\overline{\\mathrm{C}_1\\mathrm{C}_2}=5\\sqrt{3}-(-5\\sqrt{3})=10\\sqrt{3}$"],"설명":"두 점의 $y$좌표가 같으므로 거리는 $x$좌표의 차이다.","확인":null,"스킬":"S14"}]},"ns-2681a55fa614":{"길":"원점 대칭의 규칙 x→−x, y→−y를 넣어 식이 그대로인지 보기마다 확인한다","단계":[{"제목":"원점 대칭이동의 식","힌트":"원점에 대한 대칭이동에서 $x$, $y$ 자리에 각각 무엇을 넣는가?","식":["$x\\to -x,\\ y\\to -y$"],"설명":"원점에 대칭이동한 도형이 처음 도형과 일치하려면 $x$, $y$를 $-x$, $-y$로 바꾼 식이 처음 식과 같아야 한다.","확인":null,"스킬":"G4"},{"제목":"ㄱ과 ㄴ의 판정","힌트":"ㄱ과 ㄴ에 $-x$, $-y$를 넣으면 식이 그대로인가?","식":["ㄱ. $-y=-(-x)$, 즉 $y=-x$","ㄴ. $|-x-y|=1$, 즉 $|x+y|=1$"],"설명":"ㄱ은 양변의 부호를 모두 바꾸면 처음 식이 된다. ㄴ은 $|-(x+y)|=|x+y|$이므로 처음 식과 같다.","확인":null,"스킬":"G4"},{"제목":"ㄷ의 판정과 답","힌트":"ㄷ에 $-x$, $-y$를 넣으면 우변의 부호는 어떻게 되는가?","식":["ㄷ. $(-x)^2+(-y)^2=2(-x-y)$, 즉 $x^2+y^2=-2(x+y)$","처음 식과 다르므로 답은 ㄱ, ㄴ"],"설명":"좌변은 제곱이라 그대로지만 우변은 부호가 바뀌어 처음 식과 같지 않다. 따라서 원점에 대칭인 도형은 ㄱ, ㄴ이다.","확인":null,"스킬":"G4","고비":true}]},"ns-29f43cca719d":{"길":"접는 선을 수직이등분선으로 정하고, 다른 점의 대칭 조건을 두 식으로 세워 푼다","단계":[{"제목":"접는 선의 방정식","힌트":"점 A가 $(2,\\ 2)$로 옮겨지도록 접는 선은 두 점을 잇는 선분의 어떤 직선인가?","식":["$(8,\\ 0)$과 $(2,\\ 2)$의 중점 $(5,\\ 1)$, 기울기 $-\\frac{1}{3}$","$y=3x-14$"],"설명":"접는 선 $\\mathrm{PQ}$는 두 점 $(8,\\ 0)$, $(2,\\ 2)$를 잇는 선분의 수직이등분선이다. 기울기는 $-\\frac{1}{3}$과 곱이 $-1$인 $3$이고 중점 $(5,\\ 1)$을 지난다.","확인":null,"스킬":"G4"},{"제목":"(8, 5)와 (a, b)가 만족하는 두 조건","힌트":"접는 선은 두 점 $(8,\\ 5)$, $(a,\\ b)$를 잇는 선분의 수직이등분선이기도 하다. 이를 식으로 쓰면 무엇인가?","식":["$\\frac{b-5}{a-8}=-\\frac{1}{3}\\ \\Rightarrow\\ a+3b=23$","$\\frac{b+5}{2}=3\\times\\frac{8+a}{2}-14\\ \\Rightarrow\\ b=3a-9$"],"설명":"두 점을 잇는 직선은 접는 선과 수직이므로 기울기가 $-\\frac{1}{3}$이고, 중점 $\\left(\\frac{8+a}{2},\\ \\frac{b+5}{2}\\right)$는 접는 선 위에 있다.","확인":null,"스킬":"G4","고비":true},{"제목":"연립방정식의 풀이와 a+b","힌트":"두 식을 연립해 $a$, $b$를 구하면 $a+b$는 얼마인가?","식":["$a+3(3a-9)=23,\\ a=5,\\ b=6$","$a+b=11$"],"설명":"$b=3a-9$를 $a+3b=23$에 대입하면 $10a=50$이다.","확인":"11","스킬":"A10"}]},"ns-2a5ae5e7dde1":{"길":"공이 부딪히는 벽마다 출발점과 도착점을 대칭이동해 반사 경로를 한 직선으로 편다","단계":[{"제목":"좌표 설정과 벽의 방정식","힌트":"점 C를 원점으로 놓으면 공의 처음 위치와 네 벽의 방정식은 어떻게 되는가?","식":["$\\mathrm{X}(-0.4,\\ 0.5)$","$\\mathrm{CD}:\\ x=0,\\ \\mathrm{BC}:\\ y=0,\\ \\mathrm{AB}:\\ x=-2,\\ \\mathrm{AD}:\\ y=1$"],"설명":"$\\mathrm{C}$를 원점, $\\mathrm{CB}$ 방향을 $-x$ 방향, $\\mathrm{CD}$ 방향을 $y$ 방향으로 놓는다. 가로 $2$, 세로 $1$이므로 $\\mathrm{B}(-2,\\ 0)$, $\\mathrm{A}(-2,\\ 1)$, $\\mathrm{D}(0,\\ 1)$이다.","확인":null,"스킬":"S4"},{"제목":"반사 경로를 직선으로 펴기","힌트":"벽에 부딪히는 순서대로 출발점과 도착점을 대칭이동하면 경로는 어떤 모양이 되는가?","식":["$\\mathrm{X}\\to\\mathrm{X}_1(0.4,\\ 0.5)\\to\\mathrm{X}_2(0.4,\\ -0.5)$","$\\mathrm{C}\\to\\mathrm{C}_1(0,\\ 2)\\to\\mathrm{C}_2(-4,\\ 2)$"],"설명":"공은 $\\mathrm{CD}$, $\\mathrm{BC}$에 먼저 부딪히므로 $\\mathrm{X}$를 $y$축, $x$축에 차례로 대칭이동한다. 마지막에 $\\mathrm{AD}$, $\\mathrm{AB}$에 부딪히므로 도착점 $\\mathrm{C}$를 $y=1$, $x=-2$에 대해 차례로 대칭이동한다. 이렇게 하면 반사되는 경로가 한 직선 $\\mathrm{C}_2\\mathrm{X}_2$로 펴진다.","확인":null,"스킬":"S14","고비":true},{"제목":"직선 C₂X₂의 기울기와 방정식","힌트":"두 점 $\\mathrm{C}_2(-4,\\ 2)$, $\\mathrm{X}_2(0.4,\\ -0.5)$를 지나는 직선의 기울기는 얼마인가?","식":["$\\frac{-0.5-2}{0.4-(-4)}=-\\frac{25}{44}$","$y=-\\frac{25}{44}(x+4)+2$"],"설명":"$\\frac{-2.5}{4.4}=-\\frac{25}{44}$이다.","확인":"-25/44","스킬":"G9"},{"제목":"선분 CP의 길이","힌트":"직선이 $y$축과 만나는 점의 $y$좌표는 얼마이며, 이 값은 $\\overline{\\mathrm{CP}}$와 어떤 관계인가?","식":["$x=0$일 때 $y=-\\frac{25}{44}\\times 4+2=-\\frac{3}{11}$","$\\overline{\\mathrm{CP}}=\\left|-\\frac{3}{11}\\right|=\\frac{3}{11}$"],"설명":"직선이 $y$축, 곧 벽 $\\mathrm{CD}$를 펴 놓은 선과 만나는 점은 $\\mathrm{P}$를 $x$축에 대칭이동한 점이다. 따라서 $\\overline{\\mathrm{CP}}$는 $y$절편의 절댓값이다.","확인":"3/11","스킬":"G1"}]},"ns-2bb8c42589ee":{"길":"식의 변화에서 이동을 읽고, 꺾이는 점의 이동으로 새 그래프를 그려 넓이를 구한다","단계":[{"제목":"도형의 이동 읽기","힌트":"$f(x-2,\\ -y+1)=0$은 $f(x,\\ y)=0$ 위의 점 $(X,\\ Y)$를 어디로 옮긴 도형인가?","식":["$x-2=X,\\ -y+1=Y$","$(X,\\ Y)\\to(X+2,\\ 1-Y)$"],"설명":"$x-2$, $-y+1$이 원래 도형 위 점의 좌표 $X$, $Y$가 되므로 $x=X+2$, $y=1-Y$이다. $x$축에 대칭이동한 뒤 $x$축 방향으로 $2$, $y$축 방향으로 $1$만큼 옮긴 것이다.","확인":null,"스킬":"G4"},{"제목":"꺾이는 점의 이동","힌트":"그래프가 꺾이는 점 $(-1,\\ -1)$과 지나는 점 $(0,\\ 0)$은 어디로 옮겨지는가?","식":["$(-1,\\ -1)\\to(1,\\ 2),\\ (0,\\ 0)\\to(2,\\ 1)$","$x\\le 1$에서 $y=2$, $x\\ge 1$에서 $y=-x+3$"],"설명":"왼쪽의 수평선 $y=-1$은 $y=2$로 바뀌고, 기울기 $1$인 직선은 기울기 $-1$인 직선으로 바뀐다. 이 직선은 $(1,\\ 2)$, $(2,\\ 1)$을 지나므로 $y=-x+3$이고 $x$축과 $(3,\\ 0)$에서 만난다.","확인":null,"스킬":"G4","고비":true},{"제목":"둘러싸인 부분의 넓이","힌트":"$(0,\\ 0)$, $(3,\\ 0)$, $(1,\\ 2)$, $(0,\\ 2)$를 꼭짓점으로 하는 사다리꼴의 넓이는 얼마인가?","식":["$\\frac{1}{2}\\times(1+3)\\times 2=4$"],"설명":"윗변은 $y=2$ 위의 길이 $1$, 아랫변은 $x$축 위의 길이 $3$, 높이는 $2$이다.","확인":"4","스킬":"G10"}]},"ns-2fdcd503ada5":{"길":"대칭이동한 원의 중심을 k로 나타내고, 원이 두 축 안쪽에 있을 조건을 부등식으로 푼다","단계":[{"제목":"대칭이동한 원의 중심","힌트":"원 $\\mathrm{C}_1$의 중심 $(5,\\ 3)$을 직선 $2x-y+k=0$에 대해 대칭이동한 점의 좌표는 어떻게 되는가?","식":["$d=2\\times 5-3+k=7+k$","$(p,\\ q)=\\left(5-\\frac{4(7+k)}{5},\\ 3+\\frac{2(7+k)}{5}\\right)$"],"설명":"점을 직선 $2x-y+k=0$에 대해 대칭이동하면 $(5,\\ 3)-\\frac{2d}{5}(2,\\ -1)$로 옮겨진다. 여기서 $d$는 점 $(5,\\ 3)$을 직선의 좌변에 대입한 값이다.","확인":null,"스킬":"G4"},{"제목":"원이 제1사분면에 들어갈 조건","힌트":"반지름이 $1$인 원 전체가 $x\\ge 0$, $y\\ge 0$에 있으려면 중심의 좌표는 어떤 조건을 만족해야 하는가?","식":["$p\\ge 1,\\ q\\ge 1$"],"설명":"원 $\\mathrm{C}_2$의 반지름은 $\\mathrm{C}_1$과 같은 $1$이다. 중심에서 $y$축, $x$축까지의 거리가 반지름 $1$ 이상이어야 원이 두 축의 안쪽에 놓인다.","확인":null,"스킬":"S13","고비":true},{"제목":"k의 범위","힌트":"두 부등식 $p\\ge 1$, $q\\ge 1$을 $k$에 대해 풀면 범위는 어떻게 되는가?","식":["$5-\\frac{4(7+k)}{5}\\ge 1\\ \\Rightarrow\\ 7+k\\le 5$","$3+\\frac{2(7+k)}{5}\\ge 1\\ \\Rightarrow\\ 7+k\\ge -5$","$-12\\le k\\le -2$"],"설명":"두 조건을 모두 만족하는 $k$의 범위가 $a\\le k\\le b$이다.","확인":null,"스킬":"G6"},{"제목":"b-a의 값","힌트":"$a$, $b$의 값을 읽어 $b-a$를 계산하면 얼마인가?","식":["$a=-12,\\ b=-2$","$b-a=-2-(-12)=10$"],"설명":"범위의 양 끝이 $a$, $b$이다.","확인":"10","스킬":"G6"}]},"ns-31bc4217cce1":{"길":"$y$축과 직선 $x=-1$에 대칭이동해 꺾인 길을 한 선분으로 편다","단계":[{"제목":"A, B의 $y$축 대칭이동","힌트":"$\\overline{\\mathrm{AD}}$의 길이를 그대로 두고 A를 $y$축 반대편으로 보내면 어느 점인가?","식":["$\\mathrm{A}'(5,\\ 6)$","$\\mathrm{B}'(3,\\ -4)$"],"설명":"D, C가 $y$축 위에 있으므로 $\\overline{\\mathrm{AD}}=\\overline{\\mathrm{A}'\\mathrm{D}}$, $\\overline{\\mathrm{CB}}=\\overline{\\mathrm{CB}'}$이다. A', B'는 $x>0$ 쪽에, E는 $x=-1$ 위에 있어 선분 A'E, B'E가 각각 $y$축을 지나므로 D, C를 그 교점으로 잡으면 $\\overline{\\mathrm{A}'\\mathrm{D}}+\\overline{\\mathrm{DE}}=\\overline{\\mathrm{A}'\\mathrm{E}}$, $\\overline{\\mathrm{EC}}+\\overline{\\mathrm{CB}'}=\\overline{\\mathrm{EB}'}$이다.","확인":null,"스킬":"S14"},{"제목":"$\\mathrm{B}'$의 직선 $x=-1$ 대칭이동","힌트":"E가 직선 $x=-1$ 위에 있을 때 $\\overline{\\mathrm{EB}'}$와 같은 길이의 선분을 만들려면 B'를 어디로 보내는가?","식":["$\\mathrm{B}''(-5,\\ -4)$","$\\overline{\\mathrm{A}'\\mathrm{E}}+\\overline{\\mathrm{EB}'}=\\overline{\\mathrm{A}'\\mathrm{E}}+\\overline{\\mathrm{EB}''}\\ge\\overline{\\mathrm{A}'\\mathrm{B}''}$"],"설명":"B'의 $x$좌표 3은 직선 $x=-1$에서 4만큼 오른쪽이므로 대칭점은 왼쪽으로 4만큼 간 $x=-5$이다. 합은 두 점 A', B'' 사이의 거리보다 작을 수 없다.","확인":null,"스킬":"G4","고비":true},{"제목":"등호가 성립하는 위치","힌트":"직선 A'B''가 직선 $x=-1$, $y$축과 만나는 점은 각각 어디인가?","식":["직선 $\\mathrm{A}'\\mathrm{B}''$: $y=x+1$","$\\mathrm{E}(-1,\\ 0)$, $\\mathrm{D}(0,\\ 1)$, $\\mathrm{C}(0,\\ -1)$"],"설명":"직선 $y=x+1$은 $x=-1$에서 E를 지나고, 선분 A'E는 $y$축을 $(0,\\ 1)$에서, 선분 EB'는 $y$축을 $(0,\\ -1)$에서 만난다. 세 점이 모두 조건에 맞는 위치이므로 등호가 성립한다.","확인":null,"스킬":"S14"},{"제목":"최솟값 계산","힌트":"A'$(5,\\ 6)$과 B''$(-5,\\ -4)$ 사이의 거리는?","식":["$\\overline{\\mathrm{A}'\\mathrm{B}''}=\\sqrt{10^2+10^2}=10\\sqrt{2}$"],"설명":"가로 차와 세로 차가 모두 10이므로 거리는 $10\\sqrt{2}$이다.","확인":null,"스킬":"S14"}]},"ns-325fe67caa8a":{"길":"P를 $y$축과 직선 $y=x$에 각각 대칭이동해 둘레를 한 선분으로 편다","단계":[{"제목":"P의 $y$축 대칭이동","힌트":"Q가 $y$축 위에 있을 때 $\\overline{\\mathrm{PQ}}$와 길이가 같은 선분을 만들려면 P를 어디로 보내는가?","식":["$\\mathrm{P}'(-1,\\ 3)$","$\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{P}'\\mathrm{Q}}$"],"설명":"$y$축에 대칭이동하면 $x$좌표의 부호만 바뀐다. Q가 $y$축 위의 점이므로 P와 P'에서 Q까지의 거리가 같다.","확인":"-1","스킬":"G4"},{"제목":"P의 직선 $y=x$ 대칭이동","힌트":"직선 $y=x$에 대칭이동하면 좌표가 어떻게 바뀌는가?","식":["$\\mathrm{P}''(3,\\ 1)$","$\\overline{\\mathrm{PR}}=\\overline{\\mathrm{P}''\\mathrm{R}}$"],"설명":"직선 $y=x$에 대한 대칭이동은 $x$좌표와 $y$좌표를 서로 바꾼다. R이 직선 $y=x$ 위의 점이므로 P와 P''에서 R까지의 거리가 같다.","확인":null,"스킬":"G4"},{"제목":"둘레를 한 선분으로 펴기","힌트":"둘레를 P', P''를 써서 바꾸면 어떤 꺾인 길이 되는가?","식":["$\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}}=\\overline{\\mathrm{P}'\\mathrm{Q}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}''}\\ge\\overline{\\mathrm{P}'\\mathrm{P}''}$"],"설명":"P'에서 Q, R을 거쳐 P''에 이르는 꺾인 길이므로 두 점을 잇는 선분보다 짧을 수 없다. 최솟값은 $\\overline{\\mathrm{P}'\\mathrm{P}''}$이다.","확인":null,"스킬":"S14","고비":true},{"제목":"최솟값 계산","힌트":"P'$(-1,\\ 3)$과 P''$(3,\\ 1)$ 사이의 거리는?","식":["직선 $\\mathrm{P}'\\mathrm{P}''$: $y=-\\frac{1}{2}x+\\frac{5}{2}$","$\\overline{\\mathrm{P}'\\mathrm{P}''}=\\sqrt{4^2+2^2}=2\\sqrt{5}$"],"설명":"이 직선은 $y$축과 $\\mathrm{Q}\\left(0,\\ \\frac{5}{2}\\right)$, 직선 $y=x$와 $\\mathrm{R}\\left(\\frac{5}{3},\\ \\frac{5}{3}\\right)$에서 만나고 P', Q, R, P'' 순으로 놓이므로 등호가 성립한다. 가로 차 4, 세로 차 2이므로 최솟값은 $2\\sqrt{5}$이다.","확인":null,"스킬":"S14"}]},"ns-3a358e4acca6":{"길":"모서리를 원점으로 두고 A를 거울 직선에 대칭이동해 빛의 경로를 곧게 편다","단계":[{"제목":"좌표 설정","힌트":"모서리를 원점, 두 벽을 축으로 두면 A, B, 거울 직선은 어떻게 나타나는가?","식":["$\\mathrm{A}(1,\\ 2)$, $\\mathrm{B}(5,\\ 1)$","거울: $x+y=1$"],"설명":"그림에서 A는 모서리에서 가로 1, 세로 2인 지점이고 B는 가로 5, 세로 1인 지점이다. 거울은 $(0,\\ 1)$과 $(1,\\ 0)$을 잇는 선분이다.","확인":null,"스킬":"S4"},{"제목":"A의 거울 대칭이동","힌트":"$\\overline{\\mathrm{AA}'}$이 거울에 수직이고 중점이 거울 위에 있으려면 A'는 어디인가?","식":["$\\frac{b-2}{a-1}=1$, $\\frac{a+1}{2}+\\frac{b+2}{2}=1$","$\\mathrm{A}'(-1,\\ 0)$"],"설명":"$\\mathrm{A}'(a,\\ b)$라 하자. 거울의 기울기가 $-1$이므로 $\\overline{\\mathrm{AA}'}$의 기울기는 1이고, 중점이 $x+y=1$ 위에 있다. 연립하면 $a=-1$, $b=0$이다.","확인":"-1","스킬":"G4"},{"제목":"꺾인 길 펴기","힌트":"반사점을 P라 할 때 $\\overline{\\mathrm{AP}}+\\overline{\\mathrm{PB}}$를 A'를 써서 바꾸면 어떻게 되는가?","식":["$\\overline{\\mathrm{AP}}+\\overline{\\mathrm{PB}}=\\overline{\\mathrm{A}'\\mathrm{P}}+\\overline{\\mathrm{PB}}\\ge\\overline{\\mathrm{A}'\\mathrm{B}}$"],"설명":"P가 거울 위에 있으면 $\\overline{\\mathrm{AP}}=\\overline{\\mathrm{A}'\\mathrm{P}}$이다. 직선 A'B가 거울과 만나는 점은 $\\left(\\frac{5}{7},\\ \\frac{2}{7}\\right)$로 거울 선분 $0\\le x\\le 1$ 위에 있어 등호가 성립한다.","확인":null,"스킬":"S14","고비":true},{"제목":"빛이 움직인 거리","힌트":"A'$(-1,\\ 0)$과 B$(5,\\ 1)$ 사이의 거리는?","식":["$\\overline{\\mathrm{A}'\\mathrm{B}}=\\sqrt{6^2+1^2}=\\sqrt{37}$"],"설명":"가로 차는 6, 세로 차는 1이므로 거리는 $\\sqrt{37}$이다.","확인":null,"스킬":"S14"}]},"ns-42c3661ef2ea":{"길":"접어도 길이가 변하지 않음과 접는 선이 대응점을 잇는 선분의 수직이등분선임을 쓴다","단계":[{"제목":"F'의 위치","힌트":"$\\overline{\\mathrm{O}'\\mathrm{F}'}$의 길이와 두 점의 세로 차로 가로 차를 구하면?","식":["$\\mathrm{D}(0,\\ 8)$, $\\mathrm{E}(12,\\ 8)$ → 직선 $\\mathrm{DE}$: $y=8$","$\\mathrm{O}'(s,\\ 12)$, $\\mathrm{F}'(s+3,\\ 8)$"],"설명":"접어도 길이가 변하지 않으므로 $\\overline{\\mathrm{O}'\\mathrm{F}'}=\\overline{\\mathrm{OF}}=5$이다. O'와 F'의 세로 차는 $12-8=4$이므로 가로 차는 $\\sqrt{5^2-4^2}=3$이고, 그림에서 F'는 O'의 오른쪽이다.","확인":"3","스킬":"S4"},{"제목":"O'의 좌표","힌트":"접는 선은 $\\overline{\\mathrm{OO}'}$과 $\\overline{\\mathrm{FF}'}$을 각각 수직이등분하므로 두 선분의 기울기는 어떤 관계인가?","식":["$\\frac{12}{s}=\\frac{8}{s-2}$","$s=6$"],"설명":"접는 선이 두 선분 모두에 수직이므로 $\\overline{\\mathrm{OO}'}\\parallel\\overline{\\mathrm{FF}'}$이다. $\\mathrm{F}'(s+3,\\ 8)$이므로 $\\overline{\\mathrm{FF}'}$의 기울기는 $\\frac{8}{s-2}$이고, 두 기울기가 같다는 식에서 $s=6$이다.","확인":"6","스킬":"G4","고비":true},{"제목":"접는 선 PQ의 방정식","힌트":"접는 선은 $\\overline{\\mathrm{OO}'}$의 중점을 지나고 $\\overline{\\mathrm{OO}'}$에 수직이다. 기울기와 $y$절편은?","식":["$\\overline{\\mathrm{OO}'}$의 중점 $(3,\\ 6)$, 기울기 $m=-\\frac{1}{2}$","$y=-\\frac{1}{2}x+\\frac{15}{2}$"],"설명":"$\\mathrm{O}'(6,\\ 12)$이므로 $\\overline{\\mathrm{OO}'}$의 기울기는 2이고 접는 선의 기울기는 $-\\frac{1}{2}$이다. 점 $(3,\\ 6)$을 지나므로 $y-6=-\\frac{1}{2}(x-3)$에서 $n=\\frac{15}{2}$이다.","확인":"15/2","스킬":"G9"},{"제목":"$n-m$의 계산","힌트":"$m=-\\frac{1}{2}$, $n=\\frac{15}{2}$일 때 $n-m$은?","식":["$n-m=\\frac{15}{2}-\\left(-\\frac{1}{2}\\right)=8$"],"설명":"$m$이 음수이므로 빼면 두 분수의 합이 된다.","확인":"8","스킬":"G9"}]},"ns-4beb99a8364c":{"길":"A를 $y$축과 직선 $y=-\\frac{1}{2}x$에 각각 대칭이동해 둘레를 한 선분으로 편다","단계":[{"제목":"둘레를 한 선분으로 펴기","힌트":"B, C가 움직이는 직선에 대해 A를 각각 대칭이동하면 둘레는 어떤 꺾인 길이 되는가?","식":["$\\mathrm{A}_{1}(2,\\ 4)$","$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}=\\overline{\\mathrm{A}_{2}\\mathrm{B}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}_{1}}\\ge\\overline{\\mathrm{A}_{1}\\mathrm{A}_{2}}$"],"설명":"A를 $y$축에 대칭이동한 점을 $\\mathrm{A}_{1}$, 직선 $y=-\\frac{1}{2}x$에 대칭이동한 점을 $\\mathrm{A}_{2}$라 하면 $\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CA}_{1}}$, $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{A}_{2}\\mathrm{B}}$이다. 꺾인 길은 두 점을 잇는 선분보다 짧을 수 없으므로 최솟값은 $\\overline{\\mathrm{A}_{1}\\mathrm{A}_{2}}$이다.","확인":null,"스킬":"S14"},{"제목":"직선 $y=-\\frac{1}{2}x$에 대한 대칭점","힌트":"$\\overline{\\mathrm{AA}_{2}}$가 직선에 수직이고 중점이 직선 위에 있는 조건으로 식을 세우면?","식":["$\\frac{b+4}{2}=-\\frac{1}{2}\\cdot\\frac{a-2}{2}$","$\\frac{b-4}{a+2}=2$","$\\mathrm{A}_{2}\\left(-\\frac{22}{5},\\ -\\frac{4}{5}\\right)$"],"설명":"$\\mathrm{A}_{2}(a,\\ b)$라 하면 $\\overline{\\mathrm{AA}_{2}}$의 중점 $\\left(\\frac{a-2}{2},\\ \\frac{b+4}{2}\\right)$가 직선 위에 있고, 기울기는 직선의 기울기 $-\\frac{1}{2}$와 수직이어서 2이다. 연립하면 $a=-\\frac{22}{5}$, $b=-\\frac{4}{5}$이다.","확인":"-22/5","스킬":"G4","고비":true},{"제목":"최솟값 계산","힌트":"$\\mathrm{A}_{1}(2,\\ 4)$와 $\\mathrm{A}_{2}$ 사이의 거리는?","식":["$\\overline{\\mathrm{A}_{1}\\mathrm{A}_{2}}=\\sqrt{\\left(\\frac{32}{5}\\right)^2+\\left(\\frac{24}{5}\\right)^2}=8$"],"설명":"가로 차는 $2+\\frac{22}{5}=\\frac{32}{5}$, 세로 차는 $4+\\frac{4}{5}=\\frac{24}{5}$이다. 직선 $\\mathrm{A}_{1}\\mathrm{A}_{2}$는 $y$축과 $\\left(0,\\ \\frac{5}{2}\\right)$, 직선 $y=-\\frac{1}{2}x$와 $(-2,\\ 1)$에서 만나 선분 위에 있으므로 등호가 성립한다.","확인":"8","스킬":"S14"}]},"ns-576b73ae91c6":{"길":"A를 두 직선에 각각 대칭이동해 둘레를 한 선분으로 편다","단계":[{"제목":"직선 $y=-x$에 대한 대칭점","힌트":"직선 $y=-x$에 대칭이동하면 $(x,\\ y)$는 어떤 점으로 가는가?","식":["$(x,\\ y)\\to(-y,\\ -x)$","$\\mathrm{A}_{1}(-10,\\ 0)$"],"설명":"직선 $y=-x$에 대한 대칭이동은 $x$, $y$를 서로 바꾸고 부호를 모두 바꾼다. B가 이 직선 위에 있으므로 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{A}_{1}\\mathrm{B}}$이다.","확인":"-10","스킬":"G4"},{"제목":"직선 $y=2x$에 대한 대칭점","힌트":"$\\overline{\\mathrm{AA}_{2}}$가 직선에 수직이고 중점이 직선 위에 있는 조건으로 식을 세우면?","식":["$\\frac{b+10}{2}=2\\cdot\\frac{a}{2}$","$\\frac{b-10}{a}=-\\frac{1}{2}$","$\\mathrm{A}_{2}(8,\\ 6)$"],"설명":"$\\mathrm{A}_{2}(a,\\ b)$라 하면 $\\overline{\\mathrm{AA}_{2}}$의 중점 $\\left(\\frac{a}{2},\\ \\frac{b+10}{2}\\right)$가 직선 $y=2x$ 위에 있고, 기울기는 $-\\frac{1}{2}$이다. 연립하면 $a=8$, $b=6$이다.","확인":"8","스킬":"G4","고비":true},{"제목":"둘레를 한 선분으로 펴기","힌트":"$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}$를 $\\mathrm{A}_{1}$, $\\mathrm{A}_{2}$를 써서 바꾸면?","식":["$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}=\\overline{\\mathrm{A}_{1}\\mathrm{B}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}_{2}}\\ge\\overline{\\mathrm{A}_{1}\\mathrm{A}_{2}}$"],"설명":"직선 $\\mathrm{A}_{1}\\mathrm{A}_{2}$: $y=\\frac{x+10}{3}$은 직선 $y=-x$와 $\\left(-\\frac{5}{2},\\ \\frac{5}{2}\\right)$, 직선 $y=2x$와 $(2,\\ 4)$에서 만난다. $\\mathrm{A}_{1}$, B, C, $\\mathrm{A}_{2}$ 순으로 놓이므로 등호가 성립한다.","확인":null,"스킬":"S14"},{"제목":"최솟값 계산","힌트":"$\\mathrm{A}_{1}(-10,\\ 0)$과 $\\mathrm{A}_{2}(8,\\ 6)$ 사이의 거리는?","식":["$\\overline{\\mathrm{A}_{1}\\mathrm{A}_{2}}=\\sqrt{18^2+6^2}=6\\sqrt{10}$"],"설명":"가로 차 18, 세로 차 6이므로 $\\sqrt{360}=6\\sqrt{10}$이다.","확인":null,"스킬":"S14"}]},"ns-57c8147e5a1f":{"길":"점을 몇 개 직접 옮겨 세 번마다 반복되는 규칙을 찾고 보기를 하나씩 확인한다","단계":[{"제목":"처음 일곱 개 점","힌트":"$\\mathrm{P}_{1}(0,\\ 0)$에서 시작해 $x$와 $y$의 크기를 비교하며 한 점씩 옮기면?","식":["$\\mathrm{P}_{2}(1,\\ 0)$, $\\mathrm{P}_{3}(0,\\ 1)$, $\\mathrm{P}_{4}(1,\\ 1)$","$\\mathrm{P}_{5}(2,\\ 1)$, $\\mathrm{P}_{6}(1,\\ 2)$, $\\mathrm{P}_{7}(2,\\ 2)$"],"설명":"$x\\le y$이면 $x$축 방향으로 1만큼 이동하고, $x>y$이면 $x$와 $y$를 서로 바꾼다. 이 규칙대로 한 점씩 옮긴다.","확인":null,"스킬":"C6"},{"제목":"세 번마다 반복되는 규칙","힌트":"점 $(n,\\ n)$에서 시작해 세 번 옮기면 어디에 도착하는가?","식":["$\\mathrm{P}_{3n+1}(n,\\ n)$","$\\mathrm{P}_{3n+2}(n+1,\\ n)$","$\\mathrm{P}_{3n+3}(n,\\ n+1)$"],"설명":"$(n,\\ n)$은 $x\\le y$이므로 $(n+1,\\ n)$으로 가고, 이 점은 $x>y$이므로 $(n,\\ n+1)$로 간다. 이 점은 $x\\le y$이므로 $(n+1,\\ n+1)$로 가서 같은 규칙이 반복된다.","확인":null,"스킬":"P1","고비":true},{"제목":"ㄱ, ㄴ 판정","힌트":"$\\mathrm{P}_{3n}$의 좌표와 $\\overline{\\mathrm{P}_{3}\\mathrm{P}_{5}}$, $\\overline{\\mathrm{P}_{21}\\mathrm{P}_{23}}$의 길이를 구하면?","식":["$\\mathrm{P}_{3n}(n-1,\\ n)$ → ㄱ 거짓","$\\mathrm{P}_{21}(6,\\ 7)$, $\\mathrm{P}_{23}(8,\\ 7)$","$\\overline{\\mathrm{P}_{3}\\mathrm{P}_{5}}=\\overline{\\mathrm{P}_{21}\\mathrm{P}_{23}}=2$ → ㄴ 참"],"설명":"$3n=3(n-1)+3$이므로 $\\mathrm{P}_{3n}$은 $(n-1,\\ n)$이고, $\\mathrm{P}_{3}(0,\\ 1)$만 봐도 $(n,\\ n)$이 아니다. $21=3\\cdot6+3$, $23=3\\cdot7+2$이므로 $\\mathrm{P}_{21}(6,\\ 7)$, $\\mathrm{P}_{23}(8,\\ 7)$이고, 두 선분은 모두 $y$좌표가 같은 길이 2의 선분이다.","확인":"2","스킬":"P1"},{"제목":"ㄷ 판정과 결론","힌트":"$\\mathrm{P}_{11}$과 $\\mathrm{P}_{12}$를 구해 선분의 기울기를 직선 $y=x$의 기울기와 비교하면?","식":["$\\mathrm{P}_{11}(4,\\ 3)$, $\\mathrm{P}_{12}(3,\\ 4)$","기울기 $\\frac{4-3}{3-4}=-1$","옳은 것: ㄴ, ㄷ"],"설명":"$11=3\\cdot3+2$, $12=3\\cdot3+3$이므로 두 점은 $(4,\\ 3)$, $(3,\\ 4)$이다. 선분의 기울기 $-1$과 직선 $y=x$의 기울기 1의 곱이 $-1$이므로 수직이다. 따라서 옳은 것은 ㄴ, ㄷ이다.","확인":null,"스킬":"G9"}]},"ns-583827b03d40":{"길":"대응하는 꼭짓점의 좌표 사이의 규칙을 찾아 $g$를 $f$로 나타낸다","단계":[{"제목":"대응하는 꼭짓점 읽기","힌트":"그림에서 A, D가 각각 어느 점으로 옮겨졌는가?","식":["$\\mathrm{A}(2,\\ 2)\\to\\mathrm{A}'(-4,\\ 1)$","$\\mathrm{D}(3,\\ 5)\\to\\mathrm{D}'(-1,\\ 2)$"],"설명":"두 사각형은 합동이고 꼭짓점 순서의 방향이 반대이므로 대칭이동이 들어 있다. A, B, C, D에 A', B', C', D'가 차례로 대응한다.","확인":null,"스킬":"G4"},{"제목":"좌표 변환 규칙","힌트":"대응하는 두 점에서 $x$좌표와 $y$좌표 사이에 어떤 관계가 있는가?","식":["$-4=2-6$, $1=2-1$","$-1=5-6$, $2=3-1$","$(X,\\ Y)\\to(Y-6,\\ X-1)$"],"설명":"A'의 $x$좌표 $-4$는 A의 $y$좌표 2보다 6 작고, A'의 $y$좌표 1은 A의 $x$좌표 2보다 1 작다. D, D'도 같은 관계이므로 직선 $y=x$ 대칭이동 뒤 $x$축 방향으로 $-6$, $y$축 방향으로 $-1$만큼 평행이동한 것이다.","확인":"-6","스킬":"G4"},{"제목":"$g$를 $f$로 나타내기","힌트":"$g(x,\\ y)=0$ 위의 점 $(x,\\ y)$는 $f=0$ 위의 어떤 점이 옮겨진 것인가?","식":["$x=Y-6$, $y=X-1$","$X=y+1$, $Y=x+6$","$g(x,\\ y)=f(y+1,\\ x+6)$"],"설명":"$(x,\\ y)$는 $f=0$ 위의 점 $(X,\\ Y)$가 옮겨진 점이므로 $f(X,\\ Y)=0$이다. $X$, $Y$를 $x$, $y$로 바꿔 쓰면 $f(y+1,\\ x+6)=0$이다.","확인":null,"스킬":"G4","고비":true}]},"ns-5b49d20d95cc":{"길":"D를 왼쪽으로 옮겨 $\\overline{\\mathrm{BC}}$를 없애고 $x$축 대칭으로 길을 한 선분으로 편다","단계":[{"제목":"변하지 않는 길이","힌트":"$\\overline{\\mathrm{DA}}$와 $\\overline{\\mathrm{BC}}$의 길이는 얼마이고 둘레에서 무엇이 남는가?","식":["$\\overline{\\mathrm{DA}}=\\sqrt{3^2+4^2}=5$, $\\overline{\\mathrm{BC}}=1$","둘레 $=\\overline{\\mathrm{AB}}+\\overline{\\mathrm{CD}}+6$"],"설명":"DA의 길이 5와 BC의 길이 1은 변하지 않는다. 둘레에서 상수 6을 떼고 $\\overline{\\mathrm{AB}}+\\overline{\\mathrm{CD}}$의 최솟값을 구하면 된다.","확인":"6","스킬":"S3"},{"제목":"$\\overline{\\mathrm{CD}}$를 $\\overline{\\mathrm{BD}'}$로 옮기기","힌트":"D를 왼쪽으로 1 옮긴 점 D'에서 B까지의 거리는 어느 선분과 길이가 같은가?","식":["$\\mathrm{D}'(2,\\ 1)$","$\\overline{\\mathrm{CD}}=\\overline{\\mathrm{BD}'}$","둘레 $=\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BD}'}+6$"],"설명":"그림에서 B가 C의 왼쪽이므로 $\\mathrm{B}(b,\\ 0)$이면 $\\mathrm{C}(b+1,\\ 0)$이다. D를 $x$축 방향으로 $-1$만큼 평행이동한 점 D'에서 B까지의 거리는 D에서 C까지의 거리와 같다.","확인":"2","스킬":"G4","고비":true},{"제목":"$x$축 대칭으로 펴기","힌트":"B가 $x$축 위의 점일 때 $\\overline{\\mathrm{BD}'}$를 같은 길이의 선분으로 바꾸면 길이 어떻게 펴지는가?","식":["$\\mathrm{D}''(2,\\ -1)$","$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BD}'}=\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BD}''}\\ge\\overline{\\mathrm{AD}''}=\\sqrt{2^2+6^2}=2\\sqrt{10}$"],"설명":"D'를 $x$축에 대칭이동한 점 D''에 대해 $\\overline{\\mathrm{BD}'}=\\overline{\\mathrm{BD}''}$이다. 직선 AD''가 $x$축과 만나는 점 $\\mathrm{B}\\left(\\frac{5}{3},\\ 0\\right)$에서 등호가 성립한다.","확인":null,"스킬":"S14"},{"제목":"둘레의 최솟값","힌트":"$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{CD}}$의 최솟값에 고정된 길이를 더하면?","식":["$2\\sqrt{10}+6$"],"설명":"$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{CD}}$의 최솟값 $2\\sqrt{10}$에 고정된 길이 6을 더한다.","확인":null,"스킬":"S14"}]},"ns-5d57ef0edae6":{"길":"Q의 좌표를 P의 $x$, $y$를 바꾼 점으로 쓰고 선분 PQ의 길이로 바꿔 본다","단계":[{"제목":"수선의 발까지의 길이를 좌표로","힌트":"P$(x,\\ y)$의 대칭점 Q의 좌표와 두 수선의 길이는?","식":["$\\mathrm{P}(x,\\ y)$, $\\mathrm{Q}(y,\\ x)$","$\\overline{\\mathrm{PP}'}=y$, $\\overline{\\mathrm{QQ}'}=x$","$\\left|\\overline{\\mathrm{PP}'}-\\overline{\\mathrm{QQ}'}\\right|=|y-x|$"],"설명":"직선 $y=x$에 대한 대칭이동은 $x$와 $y$를 서로 바꾼다. 원 위의 점은 $x$, $y$가 모두 2 이상 6 이하의 양수이므로 수선의 길이는 좌표와 같다.","확인":null,"스킬":"G4"},{"제목":"$|y-x|$와 선분 PQ의 길이","힌트":"P와 Q 사이의 거리를 $x$, $y$로 나타내면?","식":["$\\overline{\\mathrm{PQ}}=\\sqrt{(y-x)^2+(x-y)^2}=\\sqrt{2}\\,|y-x|$","$|y-x|=\\frac{\\overline{\\mathrm{PQ}}}{\\sqrt{2}}$"],"설명":"원의 중심 $(4,\\ 4)$가 직선 $y=x$ 위에 있으므로 원이 이 직선에 대칭이고 Q도 원 위의 점이다. 따라서 PQ는 원의 현이고 $|y-x|$가 최대일 때 PQ가 최대이다.","확인":null,"스킬":"S13","고비":true},{"제목":"PQ가 최대인 경우","힌트":"원의 현 중 가장 긴 것은 어떤 현이고, 그 길이는?","식":["PQ는 지름: 중심을 지나고 기울기 $-1$","$\\overline{\\mathrm{PQ}}_{\\max}=4$"],"설명":"현은 중심을 지날 때 가장 길고 그 길이는 지름이다. 반지름이 2이므로 지름은 4이고, 이때 $\\mathrm{P}(4-\\sqrt{2},\\ 4+\\sqrt{2})$, $\\mathrm{Q}(4+\\sqrt{2},\\ 4-\\sqrt{2})$로 P, Q가 서로 대칭인 점이 된다.","확인":null,"스킬":"S5"},{"제목":"최댓값 계산","힌트":"$\\overline{\\mathrm{PQ}}=4$일 때 $|y-x|$의 값은?","식":["$|y-x|=\\frac{4}{\\sqrt{2}}=2\\sqrt{2}$"],"설명":"$|y-x|=\\frac{\\overline{\\mathrm{PQ}}}{\\sqrt{2}}$에 $\\overline{\\mathrm{PQ}}=4$를 넣으면 $2\\sqrt{2}$이다.","확인":null,"스킬":"G4"}]},"ns-61f8218b0eac":{"길":"B를 원점에 두고 C를 직선 MN에 대칭이동한 점 P로 직선 MP를 구한다","단계":[{"제목":"좌표 설정과 직선 MN","힌트":"B를 원점으로 두면 C, D, M, N의 좌표와 직선 MN의 기울기는?","식":["$\\mathrm{B}(0,\\ 0)$, $\\mathrm{C}(8,\\ 0)$, $\\mathrm{D}(8,\\ 6)$","$\\mathrm{M}(4,\\ 0)$, $\\mathrm{N}(8,\\ 3)$","직선 $\\mathrm{MN}$: $3x-4y-12=0$"],"설명":"그림에서 $\\overline{\\mathrm{BC}}=8$이 가로, $\\overline{\\mathrm{CD}}=6$이 세로이다. M, N이 각 변의 중점이므로 위 좌표가 되고, 직선 MN의 기울기는 $\\frac{3}{4}$이다.","확인":"3/4","스킬":"S4"},{"제목":"C의 대칭점 P","힌트":"$\\overline{\\mathrm{CP}}$가 직선 MN에 수직이고 중점이 직선 MN 위에 있는 조건으로 식을 세우면?","식":["$3a-4b=0$","$4a+3b=32$","$\\mathrm{P}\\left(\\frac{128}{25},\\ \\frac{96}{25}\\right)$"],"설명":"$\\mathrm{P}(a,\\ b)$라 하면 $\\overline{\\mathrm{CP}}$의 중점 $\\left(\\frac{a+8}{2},\\ \\frac{b}{2}\\right)$가 직선 MN 위에 있어 $3a-4b=0$이다. $\\overline{\\mathrm{CP}}$의 기울기는 직선 MN의 기울기와 수직이어서 $\\frac{b}{a-8}=-\\frac{4}{3}$, 즉 $4a+3b=32$이다.","확인":"128/25","스킬":"G4","고비":true},{"제목":"직선 MP의 기울기","힌트":"$\\mathrm{M}(4,\\ 0)$과 P를 지나는 직선의 기울기는?","식":["$\\frac{\\frac{96}{25}}{\\frac{128}{25}-4}=\\frac{96}{28}=\\frac{24}{7}$","직선 $\\mathrm{MP}$: $y=\\frac{24}{7}(x-4)$"],"설명":"P의 $x$좌표에서 M의 $x$좌표를 빼면 $\\frac{128}{25}-4=\\frac{28}{25}$이므로 기울기는 $\\frac{96}{28}=\\frac{24}{7}$이다.","확인":"24/7","스킬":"G9"},{"제목":"DQ의 길이와 $14k$","힌트":"직선 MP가 직선 CD(곧 $x=8$)와 만나는 점 Q의 $y$좌표는?","식":["$\\mathrm{Q}\\left(8,\\ \\frac{96}{7}\\right)$","$k=\\frac{96}{7}-6=\\frac{54}{7}$","$14k=108$"],"설명":"$x=8$을 대입하면 $y=\\frac{24}{7}\\times4=\\frac{96}{7}$이다. Q가 D$(8,\\ 6)$ 위쪽에 있으므로 $k=\\frac{96}{7}-6=\\frac{54}{7}$이고 $14k=108$이다.","확인":"108","스킬":"S4"}]},"ns-6388b11d6b6a":{"길":"제1사분면에 있는 부분의 넓이를 구한 뒤 네 번 복사한다","단계":[{"제목":"제1사분면에 있는 곡선","힌트":"원이 두 좌표축과 만나는 점과 중심의 위치를 보면 제1사분면 부분은 어떤 곡선인가?","식":["$\\mathrm{A}(0,\\ 2)$, $\\mathrm{B}(2,\\ 0)$, 원점도 원 위의 점","중심 $(1,\\ 1)$은 $\\overline{\\mathrm{AB}}$의 중점"],"설명":"원은 $y$축과 $(0,\\ 0)$, $(0,\\ 2)$에서, $x$축과 $(0,\\ 0)$, $(2,\\ 0)$에서 만난다. 중심이 선분 AB의 중점이므로 AB는 지름이고, 제1사분면에 있는 곡선은 AB를 지름으로 하는 반원이다.","확인":null,"스킬":"S13","고비":true},{"제목":"제1사분면 부분의 넓이","힌트":"반원과 삼각형 AOB로 나누어 넓이를 더하면?","식":["반원: $\\frac{1}{2}\\times\\pi\\times(\\sqrt{2})^2=\\pi$","$\\triangle\\mathrm{AOB}=\\frac{1}{2}\\times2\\times2=2$","$\\pi+2$"],"설명":"곡선과 두 좌표축으로 둘러싸인 부분은 반지름의 제곱이 2인 반원과 삼각형 AOB로 나뉜다. 둘을 더하면 $\\pi+2$이다.","확인":null,"스킬":"S12"},{"제목":"네 번 복사한 전체 넓이","힌트":"$x$축, $y$축, 원점에 대칭이동한 도형은 각각 어느 사분면에 놓이는가?","식":["$4(\\pi+2)=4\\pi+8$"],"설명":"세 번의 대칭이동으로 얻은 도형이 제2, 3, 4사분면을 하나씩 채우고 서로 겹치지 않는다. 전체 넓이는 제1사분면 도형 넓이의 4배이다.","확인":null,"스킬":"G4"}]},"ns-65d06023397a":{"길":"첫 직선의 $x$, $y$를 서로 바꾼 식이 둘째 직선과 같도록 계수를 비교한다","단계":[{"제목":"대칭이동한 직선의 식","힌트":"직선 $y=x$에 대한 대칭이동은 $x$, $y$를 어떻게 바꾸는가?","식":["$ax+(b-1)y=1\\ \\to\\ (b-1)x+ay=1$","$(a-3)x-(b+1)y=1$"],"설명":"직선 $y=x$에 대한 대칭이동은 $x$와 $y$를 서로 바꾼다. 대칭이동한 첫 직선이 둘째 직선과 같아야 한다.","확인":null,"스킬":"G4"},{"제목":"계수 비교","힌트":"우변이 모두 1이면 $x$, $y$의 계수는 어떤 관계인가?","식":["$b-1=a-3$, $a=-(b+1)$","$a-b=2$, $a+b=-1$"],"설명":"두 식의 우변이 모두 1이므로 $x$의 계수끼리, $y$의 계수끼리 같다. $x$의 계수에서 $b-1=a-3$, $y$의 계수에서 $a=-(b+1)$이므로 $a+b=-1$이다.","확인":"-1","스킬":"A3","고비":true}]},"ns-669dc3148256":{"길":"이동한 삼각형의 꼭짓점을 $a$로 쓰고 겹친 부분의 넓이를 $a$의 이차식으로 나타낸다","단계":[{"제목":"이동한 삼각형의 꼭짓점","힌트":"$y$축 대칭 뒤 $x$축 방향으로 $a$만큼 옮기면 O, A, B는 각각 어디로 가는가?","식":["$\\mathrm{O}(0,\\ 0)\\to\\mathrm{O}'(a,\\ 0)$","$\\mathrm{A}(4,\\ 0)\\to\\mathrm{A}'(a-4,\\ 0)$","$\\mathrm{B}(3,\\ 4)\\to\\mathrm{B}'(a-3,\\ 4)$"],"설명":"$y$축 대칭이동은 $x$좌표의 부호를 바꾸므로 $(0,\\ 0)$, $(-4,\\ 0)$, $(-3,\\ 4)$가 된다. 여기에 $x$좌표 $+a$를 한다.","확인":null,"스킬":"G4"},{"제목":"직선 OB와 O'B'가 만드는 삼각형","힌트":"직선 OB와 직선 O'B'의 교점과 두 점 O, O'로 삼각형을 만들면 넓이는?","식":["직선 $\\mathrm{OB}$: $y=\\frac{4}{3}x$","직선 $\\mathrm{O}'\\mathrm{B}'$: $y=-\\frac{4}{3}(x-a)$","교점 $\\left(\\frac{a}{2},\\ \\frac{2a}{3}\\right)$, 넓이 $\\frac{a^2}{3}$"],"설명":"두 삼각형이 겹친 부분은 이 삼각형 안에 들어 있다. $0<a\\le4$이면 이 삼각형 전체가 겹친 부분이다.","확인":null,"스킬":"G10"},{"제목":"$4<a<6$일 때 잘려 나가는 부분","힌트":"직선 AB와 직선 O'B'의 교점의 높이는? 잘려 나가는 삼각형의 넓이는?","식":["직선 $\\mathrm{AB}$: $y=-4(x-4)$","교점의 $y$좌표 $2a-8$, 밑변 $a-4$","삼각형 하나의 넓이 $(a-4)^2$, 양쪽 합 $2(a-4)^2$"],"설명":"$a>4$이면 O'가 A의 오른쪽으로 나가므로 삼각형 OO'의 오른쪽 아래가 변 AB 밖으로 잘려 나간다. 잘려 나가는 부분은 밑변 $a-4$, 높이 $2a-8$인 삼각형으로 넓이가 $(a-4)^2$이고, 왼쪽에도 대칭인 삼각형이 하나 더 있다.","확인":null,"스킬":"S12","고비":true},{"제목":"넓이 $S(a)$와 최대가 되는 $a$","힌트":"$S(a)=\\frac{a^2}{3}-2(a-4)^2$을 전개해 이차식의 꼭짓점의 $a$좌표를 구하면?","식":["$S(a)=-\\frac{5}{3}a^2+16a-32$"],"설명":"축의 위치는 $a=-\\frac{16}{2\\cdot\\left(-\\frac{5}{3}\\right)}=\\frac{24}{5}$이다. $4<\\frac{24}{5}<6$이므로 이 구간 안에 있다.","확인":"24/5","스킬":"A6"},{"제목":"최댓값과 다른 구간의 비교","힌트":"$a=\\frac{24}{5}$를 대입한 값과 다른 구간의 넓이의 최댓값을 비교하면?","식":["$S\\left(\\frac{24}{5}\\right)=\\frac{32}{5}$","$0<a\\le4$: $\\frac{a^2}{3}\\le\\frac{16}{3}$","$6\\le a<8$: $(8-a)^2\\le4$"],"설명":"$6\\le a<8$에서는 겹친 부분이 밑변 $8-a$, 높이 $2(8-a)$인 삼각형이다. 세 구간의 값 중 $\\frac{32}{5}$가 가장 크므로 최댓값은 $\\frac{32}{5}$이다.","확인":"32/5","스킬":"C2"}]},"ns-702ffc5a2574":{"길":"정삼각형의 변의 길이 조건으로 $a+b$를 구해 옮긴 원의 중심을 알아낸다","단계":[{"제목":"정삼각형의 변의 길이 조건","힌트":"$\\overline{\\mathrm{OA}}^2$의 값은? 정삼각형이면 $\\overline{\\mathrm{OB}}$, $\\overline{\\mathrm{AB}}$는 어떻게 되는가?","식":["$\\overline{\\mathrm{OA}}^2=2^2+2^2=8$","$a^2+b^2=8$","$(a-2)^2+(b-2)^2=8$"],"설명":"정삼각형이므로 $\\overline{\\mathrm{OB}}=\\overline{\\mathrm{AB}}=\\overline{\\mathrm{OA}}$이다. 두 변의 길이의 제곱을 각각 $\\overline{\\mathrm{OA}}^2$과 같다고 놓는다.","확인":"8","스킬":"S4"},{"제목":"$a+b$의 값","힌트":"둘째 식을 전개한 뒤 첫째 식을 대입하면?","식":["$a^2+b^2-4(a+b)+8=8$","$8-4(a+b)+8=8$","$a+b=2$"],"설명":"$(a-2)^2+(b-2)^2=a^2+b^2-4a-4b+8$이다. $a^2+b^2=8$을 대입하면 $a+b$만 남는다.","확인":null,"스킬":"A2","고비":true},{"제목":"옮긴 원의 중심과 반지름","힌트":"원의 중심 $(0,\\ 0)$이 $x$축, $y$축 방향으로 각각 $a+b$만큼 옮겨지면 어디인가?","식":["중심 $(a+b,\\ a+b)=(2,\\ 2)$","반지름 $1$"],"설명":"평행이동해도 반지름은 변하지 않으므로 옮긴 원은 점 A를 중심으로 하는 반지름 1의 원이다.","확인":null,"스킬":"S13"},{"제목":"$\\overline{\\mathrm{OP}}$의 길이","힌트":"A에서 거리가 1인 선분 OA 위의 점 P는 O에서 얼마 떨어져 있는가?","식":["$\\overline{\\mathrm{OA}}=2\\sqrt{2}$, $\\overline{\\mathrm{AP}}=1$","$\\overline{\\mathrm{OP}}=2\\sqrt{2}-1$"],"설명":"P는 선분 OA 위에서 A로부터 1만큼 떨어진 점이므로 $\\overline{\\mathrm{OP}}=\\overline{\\mathrm{OA}}-\\overline{\\mathrm{AP}}$이다.","확인":null,"스킬":"S13"}]},"ns-778e2c65b0b5":{"길":"병원을 학교가 있는 도로에 대칭이동해 S에서 학교를 거쳐 병원까지의 길을 곧게 편다","단계":[{"제목":"좌표 설정과 병원의 위치","힌트":"사거리를 원점으로 두면 S의 좌표는? 병원 $\\mathrm{H}(0,\\ y)$가 S에서 $\\frac{\\sqrt{17}}{4}$만큼 떨어져 있으려면 $y$는?","식":["$\\mathrm{S}(1,\\ 2)$, $\\mathrm{H}(0,\\ y)$","$1^2+(y-2)^2=\\frac{17}{16}$","$y=\\frac{7}{4}$"],"설명":"병원이 있는 도로를 $y$축, 학교가 있는 도로를 $x$축으로 두면 S는 $y$축에서 1, $x$축에서 2 떨어져 있다. $(y-2)^2=\\frac{1}{16}$이므로 $y=\\frac{7}{4}$ 또는 $\\frac{9}{4}$이고, 그림에서 병원이 S보다 아래에 있으므로 $\\frac{7}{4}$이다.","확인":"7/4","스킬":"S4"},{"제목":"꺾인 길 펴기","힌트":"학교 P가 $x$축 위에 있을 때 $\\overline{\\mathrm{PH}}$를 같은 길이의 선분으로 바꾸려면 병원을 어디로 보내는가?","식":["$\\mathrm{H}'\\left(0,\\ -\\frac{7}{4}\\right)$","$\\overline{\\mathrm{SP}}+\\overline{\\mathrm{PH}}=\\overline{\\mathrm{SP}}+\\overline{\\mathrm{PH}'}\\ge\\overline{\\mathrm{SH}'}$"],"설명":"S에서 병원까지의 직선거리 $\\frac{\\sqrt{17}}{4}$는 고정이다. 병원 H를 $x$축에 대칭이동한 점 H'에 대해 $\\overline{\\mathrm{PH}}=\\overline{\\mathrm{PH}'}$이므로, 거리가 최소가 되는 학교 P는 직선 SH' 위에 있다.","확인":null,"스킬":"S14","고비":true},{"제목":"학교의 위치","힌트":"직선 SH'와 $x$축의 교점의 $x$좌표는?","식":["직선 $\\mathrm{SH}'$의 기울기 $\\frac{2-\\left(-\\frac{7}{4}\\right)}{1-0}=\\frac{15}{4}$","$y=\\frac{15}{4}x-\\frac{7}{4}$","$\\mathrm{P}\\left(\\frac{7}{15},\\ 0\\right)$"],"설명":"$y=0$을 대입하면 $x=\\frac{7}{15}$이다. 학교 P는 이 점이다.","확인":"7/15","스킬":"G3"},{"제목":"S에서 학교까지의 거리","힌트":"$\\mathrm{S}(1,\\ 2)$와 $\\mathrm{P}\\left(\\frac{7}{15},\\ 0\\right)$ 사이의 거리는?","식":["$\\overline{\\mathrm{SP}}=\\sqrt{\\left(1-\\frac{7}{15}\\right)^2+2^2}=\\sqrt{\\frac{964}{225}}$","$=\\frac{2\\sqrt{241}}{15}$"],"설명":"$\\left(\\frac{8}{15}\\right)^2+4=\\frac{64+900}{225}=\\frac{964}{225}$이고 $964=4\\times241$이다.","확인":null,"스킬":"S3"},{"제목":"$a+b$의 값","힌트":"$\\frac{b\\sqrt{241}}{a}$와 비교하면 서로소인 $a$, $b$는?","식":["$\\frac{b\\sqrt{241}}{a}=\\frac{2\\sqrt{241}}{15}$","$a=15,\\ b=2$","$a+b=17$"],"설명":"2와 15는 서로소이므로 $a=15$, $b=2$이다.","확인":"17","스킬":"C7"}]},"ns-7ad0e724116c":{"길":"대칭이동한 직선이 원의 중심을 지난다는 조건을 쓴다","단계":[{"제목":"대칭이동한 직선의 식","힌트":"직선 $y=x$에 대한 대칭이동은 $x$, $y$를 어떻게 바꾸는가?","식":["$3x-2y+1=0\\ \\to\\ 3y-2x+1=0$"],"설명":"직선 $y=x$에 대한 대칭이동은 $x$와 $y$를 서로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"넓이를 이등분하는 조건","힌트":"원의 넓이를 이등분하는 직선은 원의 어느 점을 지나는가?","식":["원의 중심 $(a,\\ 1)$이 직선 $3y-2x+1=0$ 위에 있다"],"설명":"원의 넓이를 이등분하는 직선은 원의 중심을 지난다. 따라서 중심의 좌표가 직선의 방정식을 만족한다.","확인":null,"스킬":"S13","고비":true},{"제목":"$a$의 값","힌트":"중심 $(a,\\ 1)$을 $3y-2x+1=0$에 대입하면?","식":["$3\\cdot1-2a+1=0$","$a=2$"],"설명":"$4-2a=0$이므로 $a=2$이다.","확인":"2","스킬":"G4"}]},"ns-7b4db73adae3":{"길":"O를 원점으로 두고 A를 두 도로에 각각 대칭이동해 한 바퀴 도는 길을 한 선분으로 편다","단계":[{"제목":"좌표 설정","힌트":"O를 원점, 도로 $l$을 $x$축으로 두면 도로 $m$의 식과 A의 좌표는?","식":["$l$: $y=0$, $m$: $y=x$","$\\mathrm{A}(3,\\ 1)$"],"설명":"$l$과 $m$이 이루는 각이 $45^\\circ$이므로 $m$은 직선 $y=x$이다. A는 O에서 동쪽으로 3, 북쪽으로 1인 점이다.","확인":null,"스킬":"S4"},{"제목":"A의 두 대칭점","힌트":"B가 $l$ 위에, C가 $m$ 위에 있을 때 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AC}}$와 길이가 같은 선분을 만들려면 A를 어디로 보내는가?","식":["$\\mathrm{A}_{1}(3,\\ -1)$, $\\mathrm{A}_{2}(1,\\ 3)$","$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}=\\overline{\\mathrm{A}_{1}\\mathrm{B}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}_{2}}\\ge\\overline{\\mathrm{A}_{1}\\mathrm{A}_{2}}$"],"설명":"$x$축 대칭이동은 $y$좌표의 부호를 바꾸고, 직선 $y=x$ 대칭이동은 $x$, $y$를 서로 바꾼다. $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{A}_{1}\\mathrm{B}}$, $\\overline{\\mathrm{AC}}=\\overline{\\mathrm{A}_{2}\\mathrm{C}}$이므로 길이가 최소가 되는 B, C는 직선 $\\mathrm{A}_{1}\\mathrm{A}_{2}$ 위에 있다.","확인":null,"스킬":"S14","고비":true},{"제목":"정류소 C의 위치","힌트":"직선 $\\mathrm{A}_{1}\\mathrm{A}_{2}$와 직선 $y=x$의 교점의 $x$좌표는?","식":["직선 $\\mathrm{A}_{1}\\mathrm{A}_{2}$: $y=-2x+5$","$x=-2x+5$","$\\mathrm{C}\\left(\\frac{5}{3},\\ \\frac{5}{3}\\right)$"],"설명":"기울기는 $\\frac{3-(-1)}{1-3}=-2$이고 $\\mathrm{A}_{2}(1,\\ 3)$을 지나므로 $y=-2x+5$이다. 이 직선은 $x$축과 $\\left(\\frac{5}{2},\\ 0\\right)$에서 만나 B가 되고, $\\mathrm{A}_{1}$, B, C, $\\mathrm{A}_{2}$ 순으로 놓이므로 등호가 성립한다.","확인":"5/3","스킬":"G1"},{"제목":"두 정류소 사이의 거리","힌트":"$\\mathrm{A}(3,\\ 1)$과 $\\mathrm{C}\\left(\\frac{5}{3},\\ \\frac{5}{3}\\right)$ 사이의 거리는?","식":["$\\overline{\\mathrm{AC}}=\\sqrt{\\left(\\frac{4}{3}\\right)^2+\\left(\\frac{2}{3}\\right)^2}=\\sqrt{\\frac{20}{9}}=\\frac{2\\sqrt{5}}{3}$"],"설명":"가로 차는 $3-\\frac{5}{3}=\\frac{4}{3}$, 세로 차는 $\\frac{5}{3}-1=\\frac{2}{3}$이다.","확인":null,"스킬":"S3"}]},"ns-80a840ff7287":{"길":"$x$ 대신 $-x$, $y$ 대신 $y-1$이 각각 어떤 이동인지 차례로 읽는다","단계":[{"제목":"$f(-x,\\ y)=0$의 그래프","힌트":"$x$ 대신 $-x$를 넣으면 그래프는 어떻게 움직이는가?","식":["$f(x,\\ y)=0\\ \\to\\ f(-x,\\ y)=0$: $y$축 대칭","꺾이는 점 $(0,\\ 1)$, $x$절편 $(-1,\\ 0)$"],"설명":"$x$를 $-x$로 바꾸면 그래프가 $y$축에 대하여 대칭이동한다. 수평선은 $x\\ge0$ 쪽으로, 비스듬한 선은 $x\\le0$ 쪽으로 간다.","확인":null,"스킬":"G4"},{"제목":"$y$ 대신 $y-1$의 의미","힌트":"$y$ 대신 $y-1$을 넣으면 그래프는 위아래 어느 쪽으로 얼마나 움직이는가?","식":["$f(-x,\\ y-1)=0$: $y$축 방향으로 $+1$","꺾이는 점 $(0,\\ 2)$, $x$절편 $(-2,\\ 0)$"],"설명":"$f(x,\\ y-1)=0$은 $f(x,\\ y)=0$을 $y$축 방향으로 1만큼 평행이동한 그래프이다. 따라서 꺾이는 점의 $y$좌표가 위로 1만큼 커진다.","확인":"2","스킬":"G4","고비":true},{"제목":"알맞은 그래프 고르기","힌트":"꺾이는 점의 위치와 수평선·비스듬한 선의 방향이 모두 맞는 그림은?","식":["수평선 $y=2$ ($x\\ge0$)","비스듬한 선: $(0,\\ 2)$와 $(-2,\\ 0)$을 지난다","정답 ⑤"],"설명":"수평선이 $y=2$에서 오른쪽으로 뻗고 비스듬한 선이 $x=-2$에서 $x$축과 만나며 왼쪽 아래로 내려가는 그림이다.","확인":null,"스킬":"G4"}]},"ns-811e8a4d4c77":{"길":"A와 C를 직선 $y=x$에 대칭이동해 P, Q를 각각 따로 구한다","단계":[{"제목":"A, C의 대칭점","힌트":"직선 $y=x$에 대칭이동하면 좌표가 어떻게 바뀌는가?","식":["$\\mathrm{A}'(2,\\ 0)$","$\\mathrm{C}'(6,\\ 0)$"],"설명":"직선 $y=x$에 대한 대칭이동은 $x$좌표와 $y$좌표를 서로 바꾼다. P, Q가 이 직선 위에 있으므로 $\\overline{\\mathrm{AP}}=\\overline{\\mathrm{A}'\\mathrm{P}}$, $\\overline{\\mathrm{QC}}=\\overline{\\mathrm{QC}'}$이다.","확인":null,"스킬":"G4"},{"제목":"점 P의 위치","힌트":"$\\overline{\\mathrm{AP}}+\\overline{\\mathrm{PB}}$만 따로 보면 최소가 되는 P는 어디인가?","식":["$\\overline{\\mathrm{AP}}+\\overline{\\mathrm{PB}}=\\overline{\\mathrm{A}'\\mathrm{P}}+\\overline{\\mathrm{PB}}\\ge\\overline{\\mathrm{A}'\\mathrm{B}}$","직선 $\\mathrm{A}'\\mathrm{B}$: $y=-2x+4$","$\\mathrm{P}\\left(\\frac{4}{3},\\ \\frac{4}{3}\\right)$"],"설명":"P와 Q는 서로 영향을 주지 않으므로 $\\overline{\\mathrm{AP}}+\\overline{\\mathrm{PB}}$와 $\\overline{\\mathrm{BQ}}+\\overline{\\mathrm{QC}}$를 각각 최소로 만든다. P는 직선 $\\mathrm{A}'\\mathrm{B}$와 직선 $y=x$의 교점이며 $x=-2x+4$에서 $x=\\frac{4}{3}$이다.","확인":"4/3","스킬":"S14","고비":true},{"제목":"점 Q의 위치","힌트":"$\\overline{\\mathrm{BQ}}+\\overline{\\mathrm{QC}}$를 C'를 써서 바꾸면 Q는 어디인가?","식":["$\\overline{\\mathrm{BQ}}+\\overline{\\mathrm{QC}}=\\overline{\\mathrm{BQ}}+\\overline{\\mathrm{QC}'}\\ge\\overline{\\mathrm{BC}'}$","직선 $\\mathrm{BC}'$: $y=-\\frac{2}{3}x+4$","$\\mathrm{Q}\\left(\\frac{12}{5},\\ \\frac{12}{5}\\right)$"],"설명":"Q는 직선 $\\mathrm{BC}'$와 직선 $y=x$의 교점이다. $x=-\\frac{2}{3}x+4$에서 $\\frac{5}{3}x=4$이므로 $x=\\frac{12}{5}$이다.","확인":"12/5","스킬":"S14"},{"제목":"선분 PQ의 길이","힌트":"P, Q가 모두 직선 $y=x$ 위에 있을 때 $\\overline{\\mathrm{PQ}}$를 $x$좌표의 차로 나타내면?","식":["$\\overline{\\mathrm{PQ}}=\\sqrt{2}\\left|\\frac{12}{5}-\\frac{4}{3}\\right|=\\frac{16\\sqrt{2}}{15}$"],"설명":"직선 $y=x$ 위의 두 점은 $x$좌표의 차와 $y$좌표의 차가 같으므로 거리는 $x$좌표 차의 $\\sqrt{2}$배이다. $\\frac{12}{5}-\\frac{4}{3}=\\frac{16}{15}$이다.","확인":null,"스킬":"G4"}]},"ns-8673362b30a6":{"길":"그래프의 대표 점 세 개를 보기마다 옮겨 그림과 비교한다","단계":[{"제목":"ㄱ 판정","힌트":"$y$ 대신 $y-1$을 넣으면 그래프는 어느 방향으로 얼마나 움직이는가?","식":["대표 점: $(-1,\\ 0)$, $(0,\\ 1)$, $(1,\\ 0)$","$f(x,\\ y-1)=0$: $y$축 방향으로 $+1$","$(-1,\\ 1)$, $(0,\\ 2)$, $(1,\\ 1)$ → ㄱ 참"],"설명":"그래프의 왼쪽 끝, 꼭대기, 오른쪽 끝을 대표 점으로 잡는다. $y$ 대신 $y-1$을 넣으면 그래프가 $y$축 방향으로 1만큼 올라가고, 옮긴 세 점이 그림 ㄱ과 같다.","확인":null,"스킬":"G4"},{"제목":"ㄴ 판정","힌트":"$x$ 대신 $-x$를 넣으면 대표 점은 어디로 가는가?","식":["$f(-x,\\ y)=0$: $y$축 대칭","$(1,\\ 0)$, $(0,\\ 1)$, $(-1,\\ 0)$: 호는 오른쪽, 선분은 왼쪽","그림 ㄴ은 $x$축 아래에 있다 → ㄴ 거짓"],"설명":"$y$축 대칭이동이므로 $y$좌표는 그대로이고 호와 선분이 좌우로 바뀐다. 그림 ㄴ은 $y$좌표의 부호가 바뀐 모양이어서 $f(x,\\ -y)=0$의 그래프이다.","확인":null,"스킬":"G4"},{"제목":"ㄷ 판정과 결론","힌트":"$f(y-1,\\ -x)=0$ 위의 점 $(x,\\ y)$는 원래 그래프의 어떤 점 $(X,\\ Y)$에서 온 것인가?","식":["$X=y-1$, $Y=-x$ → $(x,\\ y)=(-Y,\\ X+1)$","$(-1,\\ 0)\\to(0,\\ 0)$, $(0,\\ 1)\\to(-1,\\ 1)$, $(1,\\ 0)\\to(0,\\ 2)$","옳은 것: ㄱ, ㄷ"],"설명":"$(y-1,\\ -x)$가 원래 그래프 위의 점이므로 옮겨진 점은 $(-Y,\\ X+1)$이다. 세 점이 그림 ㄷ의 $(0,\\ 0)$, $(-1,\\ 1)$, $(0,\\ 2)$와 같고 호와 선분의 모양도 같아 참이다. 따라서 옳은 것은 ㄱ, ㄷ이다.","확인":null,"스킬":"G4","고비":true}]},"ns-89cb57666da4":{"길":"P를 $x$축과 직선 $y=2x+4$에 각각 대칭이동해 둘레를 한 선분으로 편다","단계":[{"제목":"P의 $x$축 대칭점","힌트":"R이 $x$축 위에 있을 때 $\\overline{\\mathrm{PR}}$와 길이가 같은 선분을 만들려면 P를 어디로 보내는가?","식":["$\\mathrm{P}_{1}(4,\\ -2)$","$\\overline{\\mathrm{PR}}=\\overline{\\mathrm{P}_{1}\\mathrm{R}}$"],"설명":"$x$축 대칭이동은 $y$좌표의 부호만 바꾼다. R이 $x$축 위의 점이므로 P와 $\\mathrm{P}_{1}$에서 R까지의 거리가 같다.","확인":null,"스킬":"G4"},{"제목":"P의 직선 $y=2x+4$ 대칭점","힌트":"$\\overline{\\mathrm{PP}_{2}}$가 직선에 수직이고 중점이 직선 위에 있는 조건으로 식을 세우면?","식":["$\\frac{b+2}{2}=2\\cdot\\frac{a+4}{2}+4$","$\\frac{b-2}{a-4}=-\\frac{1}{2}$","$\\mathrm{P}_{2}(-4,\\ 6)$"],"설명":"$\\mathrm{P}_{2}(a,\\ b)$라 하면 $\\overline{\\mathrm{PP}_{2}}$의 중점 $\\left(\\frac{a+4}{2},\\ \\frac{b+2}{2}\\right)$가 직선 위에 있고, 기울기는 직선의 기울기 2와 수직이어서 $-\\frac{1}{2}$이다. 정리하면 $b=2a+14$, $a=8-2b$이므로 $a=-4$, $b=6$이다.","확인":"-4","스킬":"G4","고비":true},{"제목":"둘레를 한 선분으로 펴기","힌트":"둘레를 $\\mathrm{P}_{1}$, $\\mathrm{P}_{2}$를 써서 바꾸면 어떤 꺾인 길이 되는가?","식":["$\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}}=\\overline{\\mathrm{P}_{2}\\mathrm{Q}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}_{1}}\\ge\\overline{\\mathrm{P}_{1}\\mathrm{P}_{2}}$","직선 $\\mathrm{P}_{1}\\mathrm{P}_{2}$: $y=-x+2$"],"설명":"이 직선은 $x$축과 $\\mathrm{R}(2,\\ 0)$, 직선 $y=2x+4$와 $\\mathrm{Q}\\left(-\\frac{2}{3},\\ \\frac{8}{3}\\right)$에서 만난다. $\\mathrm{P}_{1}$, R, Q, $\\mathrm{P}_{2}$ 순으로 놓이므로 등호가 성립한다.","확인":null,"스킬":"S14"},{"제목":"둘레의 최솟값","힌트":"$\\mathrm{P}_{1}(4,\\ -2)$와 $\\mathrm{P}_{2}(-4,\\ 6)$ 사이의 거리는?","식":["$\\overline{\\mathrm{P}_{1}\\mathrm{P}_{2}}=\\sqrt{8^2+8^2}=8\\sqrt{2}$"],"설명":"가로 차와 세로 차가 모두 8이므로 거리는 $8\\sqrt{2}$이다.","확인":null,"스킬":"S3"}]},"ns-8f9bdd1ba4dc":{"길":"P, Q를 각각 X, Y가 있는 변에 대칭이동해 꺾인 길을 한 선분으로 편다","단계":[{"제목":"좌표 설정","힌트":"B를 원점으로 두면 P, Q의 좌표와 변 AD, BC의 방정식은?","식":["$\\mathrm{B}(0,\\ 0)$, $\\mathrm{C}(7,\\ 0)$, $\\mathrm{A}(0,\\ 6)$","$\\mathrm{P}(0,\\ 5)$, $\\mathrm{Q}(7,\\ 1)$","변 $\\mathrm{AD}$: $y=6$, 변 $\\mathrm{BC}$: $y=0$"],"설명":"$\\overline{\\mathrm{AB}}=6$이므로 A는 B의 위로 6인 점이고, $\\overline{\\mathrm{AP}}=1$이므로 P의 $y$좌표는 $6-1=5$이다. $\\overline{\\mathrm{CQ}}=1$이므로 Q의 $y$좌표는 1이다.","확인":"5","스킬":"S4"},{"제목":"대칭점으로 펴기","힌트":"X가 변 AD 위에, Y가 변 BC 위에 있을 때 $\\overline{\\mathrm{PX}}$, $\\overline{\\mathrm{YQ}}$와 길이가 같은 선분을 만들려면 P, Q를 어디로 보내는가?","식":["$\\mathrm{P}'(0,\\ 7)$, $\\mathrm{Q}'(7,\\ -1)$","$\\overline{\\mathrm{PX}}+\\overline{\\mathrm{XY}}+\\overline{\\mathrm{YQ}}=\\overline{\\mathrm{P}'\\mathrm{X}}+\\overline{\\mathrm{XY}}+\\overline{\\mathrm{YQ}'}\\ge\\overline{\\mathrm{P}'\\mathrm{Q}'}$"],"설명":"P를 직선 $y=6$에 대칭이동하면 $y$좌표가 $12-5=7$이 되고, Q를 직선 $y=0$에 대칭이동하면 $y$좌표의 부호가 바뀐다. 합이 최소가 되려면 X, Y가 선분 $\\mathrm{P}'\\mathrm{Q}'$ 위에 있어야 한다.","확인":null,"스킬":"S14","고비":true},{"제목":"직선 XY의 기울기","힌트":"직선 XY는 직선 $\\mathrm{P}'\\mathrm{Q}'$와 같다. 이 직선의 기울기는?","식":["직선 $\\mathrm{XY}$의 기울기 $=\\frac{-1-7}{7-0}=-\\frac{8}{7}$","직선 $y=7-\\frac{8}{7}x$"],"설명":"이 직선은 $y=6$과 $x=\\frac{7}{8}$에서, $y=0$과 $x=\\frac{49}{8}$에서 만나고 두 점 모두 변 위($0\\le x\\le7$)에 있으므로 X, Y가 실제로 존재한다.","확인":"-8/7","스킬":"G9"}]},"ns-931a7df2781e":{"길":"꼭짓점만 옮겨 원점까지의 거리 조건을 식으로 쓴다","단계":[{"제목":"처음 꼭짓점의 좌표","힌트":"$y=x^2+2x+3$을 완전제곱식으로 고치면 꼭짓점은?","식":["$y=(x+1)^2+2$","꼭짓점 $(-1,\\ 2)$"],"설명":"$x^2+2x+3=(x+1)^2+2$이므로 꼭짓점은 $(-1,\\ 2)$이다.","확인":"-1","스킬":"A6","고비":true},{"제목":"옮긴 꼭짓점의 좌표","힌트":"곡선을 $x$축 방향으로 $m$, $y$축 방향으로 $n$만큼 옮기면 꼭짓점의 좌표는?","식":["$(-1+m,\\ 2+n)=(m-1,\\ n+2)$"],"설명":"평행이동하면 꼭짓점도 같은 방향으로 같은 만큼 움직인다.","확인":null,"스킬":"G4"},{"제목":"원점까지의 거리 조건","힌트":"원점에서 옮긴 꼭짓점까지의 거리가 5라는 조건을 식으로 쓰면?","식":["$\\sqrt{(m-1)^2+(n+2)^2}=5$","$(m-1)^2+(n+2)^2=25$"],"설명":"원점과 점 $(m-1,\\ n+2)$ 사이의 거리를 구해 5와 같다고 놓고 양변을 제곱한다.","확인":null,"스킬":"C7"}]},"ns-931d60319e29":{"길":"대칭이동과 평행이동을 식에 차례로 반영해 직선의 방정식을 구한 뒤 대입한다","단계":[{"제목":"대칭이동한 직선","힌트":"직선 $y=x$에 대한 대칭이동은 $x$, $y$를 어떻게 바꾸는가?","식":["$2x-3y+6=0\\ \\to\\ 2y-3x+6=0$","$3x-2y-6=0$"],"설명":"직선 $y=x$에 대한 대칭이동은 $x$와 $y$를 서로 바꾼다. 양변에 $-1$을 곱해 정리한다.","확인":null,"스킬":"G4"},{"제목":"평행이동한 직선","힌트":"$x$축 방향으로 $-3$, $y$축 방향으로 $+2$만큼 옮기면 $x$, $y$ 자리에 무엇을 넣는가?","식":["$3(x+3)-2(y-2)-6=0$","$3x-2y+7=0$"],"설명":"$x$축 방향으로 $-3$만큼 옮기면 $x$ 대신 $x+3$을, $y$축 방향으로 $+2$만큼 옮기면 $y$ 대신 $y-2$를 넣는다. 전개하면 상수항이 $9+4-6=7$이다.","확인":"7","스킬":"G4","고비":true},{"제목":"점을 대입해 고르기","힌트":"각 점의 좌표를 $3x-2y+7$에 대입하면 값이 0이 아닌 점은?","식":["①, ②, ③, ⑤: 대입한 값이 모두 $0$","$(-1,\\ 5)$: $3\\cdot(-1)-2\\cdot5+7=-6\\ne0$"],"설명":"직선 위의 점이면 대입한 값이 0이다. 값이 0이 아닌 점은 $(-1,\\ 5)$이므로 정답은 ④이다.","확인":null,"스킬":"G4"}]},"ns-96572c01545c":{"길":"평행이동으로 생긴 평행사변형의 넓이에서 대각선이 나누는 한 부분을 구한다","단계":[{"제목":"사각형 $\\mathrm{ABDC}$ 와 삼각형 $\\mathrm{BED}$ 의 넓이 관계","힌트":"평행이동이면 $\\overline{\\mathrm{AC}}$ 와 $\\overline{\\mathrm{BD}}$ 는 어떤 관계이고, $\\mathrm{E}$ 는 대각선 위에서 어떤 점인가?","식":["$\\triangle\\mathrm{BED}=\\dfrac14\\,\\square\\mathrm{ABDC}$"],"설명":"두 점 $\\mathrm{A}$, $\\mathrm{B}$ 를 같은 방향으로 같은 거리만큼 옮겼으므로 $\\overline{\\mathrm{AC}}\\parallel\\overline{\\mathrm{BD}}$ 이고 길이가 같다. 따라서 $\\mathrm{ABDC}$ 는 평행사변형이고 대각선 $\\mathrm{AD}$, $\\mathrm{BC}$ 의 교점 $\\mathrm{E}$ 는 두 대각선의 중점이다. 대각선이 평행사변형을 넓이가 같은 네 삼각형으로 나누므로 $\\triangle\\mathrm{BED}$ 는 전체의 $\\dfrac14$ 이다.","확인":"1/4","스킬":"G4"},{"제목":"현 $\\mathrm{AB}$ 의 길이","힌트":"원의 중심에서 직선까지의 거리와 반지름으로 현의 길이를 어떻게 구하는가?","식":["$d=\\dfrac{|2-2-4|}{\\sqrt5}=\\dfrac{4}{\\sqrt5}$","$\\overline{\\mathrm{AB}}=2\\sqrt{3^2-\\left(\\dfrac{4}{\\sqrt5}\\right)^2}=2\\sqrt{\\dfrac{29}{5}}$"],"설명":"원 $C_1$ 의 중심은 $(1,2)$ 이고 반지름은 $3$ 이다. 중심에서 직선 $2x-y-4=0$ 까지의 거리를 $d$ 라 하면 현의 길이는 $2\\sqrt{r^2-d^2}$ 이다.","확인":null,"스킬":"S5"},{"제목":"평행한 두 직선 $\\mathrm{AB}$, $\\mathrm{CD}$ 사이의 거리","힌트":"직선 $\\mathrm{CD}$ 의 식은 직선 $\\mathrm{AB}$ 를 같은 만큼 평행이동하면 어떻게 되는가?","식":["$2(x-8)-(y+4)-4=0$, 즉 $2x-y-24=0$","$\\dfrac{|-24+4|}{\\sqrt5}=\\dfrac{20}{\\sqrt5}=4\\sqrt5$"],"설명":"평행이동하면 점 $(x,y)$ 가 $(x+8,y-4)$ 로 옮겨지므로 $x$ 대신 $x-8$, $y$ 대신 $y+4$ 를 넣는다. 평행한 두 직선 $2x-y+c_1=0$, $2x-y+c_2=0$ 사이의 거리는 $\\dfrac{|c_1-c_2|}{\\sqrt5}$ 이다.","확인":null,"스킬":"G4","고비":true},{"제목":"평행사변형 $\\mathrm{ABDC}$ 의 넓이","힌트":"밑변을 $\\overline{\\mathrm{AB}}$ 로 보면 높이는 어느 길이인가?","식":["$\\square\\mathrm{ABDC}=2\\sqrt{\\dfrac{29}{5}}\\times4\\sqrt5=8\\sqrt{29}$"],"설명":"밑변 $\\overline{\\mathrm{AB}}$ 에 대한 높이는 두 평행선 사이의 거리이다. 넓이는 밑변과 높이의 곱이다.","확인":null,"스킬":"G10"},{"제목":"삼각형 $\\mathrm{BED}$ 의 넓이","힌트":"첫 단계의 넓이 관계를 쓰면?","식":["$\\triangle\\mathrm{BED}=\\dfrac14\\times8\\sqrt{29}=2\\sqrt{29}$"],"설명":"삼각형 $\\mathrm{BED}$ 는 평행사변형 넓이의 $\\dfrac14$ 이므로 값이 바로 정해진다.","확인":null,"스킬":"S8"}]},"ns-970ea770e2f1":{"길":"움직이는 점이 놓인 변에 대해 두 점을 대칭이동해 꺾인 길을 한 선분으로 편다","단계":[{"제목":"좌표 설정과 두 점 $\\mathrm{P}$, $\\mathrm{Q}$ 의 좌표","힌트":"점 $\\mathrm{B}$ 를 원점으로 놓으면 $\\mathrm{P}$, $\\mathrm{Q}$ 의 좌표는?","식":["$\\mathrm{B}(0,0),\\ \\mathrm{C}(7,0),\\ \\mathrm{A}(0,6),\\ \\mathrm{D}(7,6)$","$\\mathrm{P}(0,5),\\ \\mathrm{Q}(7,1)$"],"설명":"세로 $\\overline{\\mathrm{AB}}=6$ 이고 $\\overline{\\mathrm{AP}}=1$ 이므로 $\\mathrm{P}$ 의 $y$ 좌표는 $5$ 이다. $\\overline{\\mathrm{CQ}}=1$ 이므로 $\\mathrm{Q}$ 의 $y$ 좌표는 $1$ 이다.","확인":null,"스킬":"S4"},{"제목":"두 점의 대칭이동","힌트":"$\\mathrm{X}$ 는 직선 $y=6$ 위, $\\mathrm{Y}$ 는 $x$축 위에 있다. $\\mathrm{P}$, $\\mathrm{Q}$ 는 각각 어느 직선에 대칭이동해야 하는가?","식":["$\\mathrm{P}'(0,7),\\ \\mathrm{Q}'(7,-1)$","$\\overline{\\mathrm{PX}}+\\overline{\\mathrm{XY}}+\\overline{\\mathrm{YQ}}=\\overline{\\mathrm{P}'\\mathrm{X}}+\\overline{\\mathrm{XY}}+\\overline{\\mathrm{YQ}'}$"],"설명":"$\\mathrm{P}$ 를 직선 $y=6$ 에 대칭이동한 점을 $\\mathrm{P}'$, $\\mathrm{Q}$ 를 $x$축에 대칭이동한 점을 $\\mathrm{Q}'$ 이라 한다. $\\overline{\\mathrm{PX}}=\\overline{\\mathrm{P}'\\mathrm{X}}$, $\\overline{\\mathrm{YQ}}=\\overline{\\mathrm{YQ}'}$ 이므로 세 선분의 합이 $\\mathrm{P}'$ 에서 $\\mathrm{Q}'$ 으로 가는 꺾인 길이 된다.","확인":null,"스킬":"G4","고비":true},{"제목":"직선 $\\mathrm{P}'\\mathrm{Q}'$ 와 두 변의 교점","힌트":"직선 $\\mathrm{P}'\\mathrm{Q}'$ 가 $y=6$, $y=0$ 과 만나는 점은 변 $\\mathrm{AD}$, $\\mathrm{BC}$ 위에 있는가?","식":["$y=-\\dfrac87x+7$","$y=6$ 일 때 $x=\\dfrac78,\\ \\ y=0$ 일 때 $x=\\dfrac{49}{8}$"],"설명":"두 교점의 $x$ 좌표가 모두 $0$ 이상 $7$ 이하이므로 $\\mathrm{X}$, $\\mathrm{Y}$ 를 이 점으로 잡을 수 있다. 따라서 $\\overline{\\mathrm{P}'\\mathrm{X}}+\\overline{\\mathrm{XY}}+\\overline{\\mathrm{YQ}'}\\ge\\overline{\\mathrm{P}'\\mathrm{Q}'}$ 에서 등호가 성립한다.","확인":null,"스킬":"G4"},{"제목":"꺾인 길의 최솟값","힌트":"두 점 $\\mathrm{P}'$, $\\mathrm{Q}'$ 사이의 거리는?","식":["$\\overline{\\mathrm{P}'\\mathrm{Q}'}=\\sqrt{7^2+8^2}=\\sqrt{113}$"],"설명":"가로 방향의 차가 $7$, 세로 방향의 차가 $8$ 이므로 피타고라스 정리로 거리가 정해진다.","확인":null,"스킬":"S3"}]},"ns-97b5875bfcf6":{"길":"$\\mathrm{P}$ 를 직선 $y=x$ 와 $y$축에 대칭이동해 둘레를 한 선분으로 편다","단계":[{"제목":"두 대칭점 구하기","힌트":"$\\mathrm{P}$ 를 직선 $y=x$ 에 대칭이동하면 좌표가 어떻게 되고, $y$축에 대칭이동하면 어떻게 되는가?","식":["$\\mathrm{P}'(3,1),\\ \\mathrm{P}''(-1,3)$"],"설명":"$y=x$ 에 대칭이동한 점을 $\\mathrm{P}'$, $y$축에 대칭이동한 점을 $\\mathrm{P}''$ 이라 한다. $y=x$ 에 대칭이면 $x$ 좌표와 $y$ 좌표가 서로 바뀌고, $y$축에 대칭이면 $x$ 좌표의 부호가 바뀐다.","확인":null,"스킬":"G4","고비":true},{"제목":"둘레를 한 선분으로 펴기","힌트":"$\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{PR}}$ 을 대칭점으로 바꾸면 둘레는 어떤 꺾인 길이 되는가?","식":["$\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}}=\\overline{\\mathrm{P}'\\mathrm{Q}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}''}\\ge\\overline{\\mathrm{P}'\\mathrm{P}''}$"],"설명":"대칭이동하면 $\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{P}'\\mathrm{Q}}$, $\\overline{\\mathrm{PR}}=\\overline{\\mathrm{P}''\\mathrm{R}}$ 이다. 직선 $\\mathrm{P}'\\mathrm{P}''$ 이 $y=x$ 와 $y$축을 선분 $\\mathrm{P}'\\mathrm{P}''$ 위에서 만나므로 등호가 성립한다.","확인":null,"스킬":"G4"},{"제목":"두 대칭점 사이의 거리","힌트":"$\\mathrm{P}'(3,1)$ 과 $\\mathrm{P}''(-1,3)$ 사이의 거리는?","식":["$\\overline{\\mathrm{P}'\\mathrm{P}''}=\\sqrt{(3+1)^2+(1-3)^2}=\\sqrt{20}=2\\sqrt5$"],"설명":"두 점의 좌표 차로 거리 공식을 쓰면 둘레의 최솟값이 정해진다.","확인":null,"스킬":"S3"}]},"ns-98f8d714f25e":{"길":"$\\mathrm{A}$ 를 $y=x$ 와 $x$축에 대칭이동해 둘레를 한 직선 위의 길이로 만든다","단계":[{"제목":"두 대칭점 구하기","힌트":"$\\mathrm{A}(4,1)$ 을 직선 $y=x$ 와 $x$축에 각각 대칭이동하면?","식":["$\\mathrm{A}'(1,4),\\ \\mathrm{A}''(4,-1)$"],"설명":"$y=x$ 에 대칭이동한 점을 $\\mathrm{A}'$, $x$축에 대칭이동한 점을 $\\mathrm{A}''$ 이라 한다. $y=x$ 에 대칭이면 좌표가 서로 바뀌고, $x$축에 대칭이면 $y$ 좌표의 부호가 바뀐다.","확인":null,"스킬":"G4","고비":true},{"제목":"둘레가 최소가 되는 조건","힌트":"$\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AC}}$ 를 대칭점으로 바꾸면 합이 최소일 때 점들의 위치는?","식":["$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}=\\overline{\\mathrm{A}'\\mathrm{B}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}''}\\ge\\overline{\\mathrm{A}'\\mathrm{A}''}$"],"설명":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{A}'\\mathrm{B}}$, $\\overline{\\mathrm{AC}}=\\overline{\\mathrm{A}''\\mathrm{C}}$ 이다. 점 $\\mathrm{B}$, $\\mathrm{C}$ 가 선분 $\\mathrm{A}'\\mathrm{A}''$ 위에 있을 때 등호가 성립하여 둘레가 최소가 된다.","확인":null,"스킬":"G4"},{"제목":"직선 $\\mathrm{A}'\\mathrm{A}''$ 의 방정식","힌트":"두 점 $(1,4)$, $(4,-1)$ 을 지나는 직선의 기울기는?","식":["$\\dfrac{-1-4}{4-1}=-\\dfrac53$","$y-4=-\\dfrac53(x-1)$, 즉 $5x+3y-17=0$"],"설명":"기울기를 구한 뒤 한 점의 좌표를 대입해 직선의 식을 세운다.","확인":"-5/3","스킬":"G3"},{"제목":"점 $\\mathrm{B}$, $\\mathrm{C}$ 의 좌표","힌트":"이 직선과 $y=x$, $x$축의 교점은 각각 어디인가?","식":["$5x+3x-17=0$ 에서 $b=\\dfrac{17}{8}$","$y=0$ 에서 $c=\\dfrac{17}{5}$"],"설명":"점 $\\mathrm{B}$ 는 $y=x$ 위의 점이므로 $x$, $y$ 에 같은 값을 넣는다. 점 $\\mathrm{C}$ 는 $x$축 위의 점이므로 $y=0$ 을 넣는다.","확인":null,"스킬":"G1"},{"제목":"$8b+5c$ 의 값","힌트":"$b$, $c$ 를 대입하면?","식":["$8\\cdot\\dfrac{17}{8}+5\\cdot\\dfrac{17}{5}=17+17=34$"],"설명":"각 항의 분모가 약분되어 간단히 계산된다.","확인":"34","스킬":"G4"}]},"ns-99246ffc6cd4":{"길":"$\\mathrm{P}$ 를 직선 $y=x$ 와 $y$축에 대칭이동해 둘레를 한 선분으로 편다","단계":[{"제목":"두 대칭점 구하기","힌트":"$\\mathrm{P}(-1,-7)$ 을 직선 $y=x$ 에 대칭이동하면 좌표가 어떻게 되고, $y$축에 대칭이동하면 어떻게 되는가?","식":["$\\mathrm{P}'(-7,-1),\\ \\mathrm{P}''(1,-7)$"],"설명":"$y=x$ 에 대칭이동한 점을 $\\mathrm{P}'$, $y$축에 대칭이동한 점을 $\\mathrm{P}''$ 이라 한다. $y=x$ 에 대칭이면 $x$ 좌표와 $y$ 좌표가 서로 바뀌고, $y$축에 대칭이면 $x$ 좌표의 부호가 바뀐다.","확인":null,"스킬":"G4","고비":true},{"제목":"둘레를 한 선분으로 펴기","힌트":"$\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{PR}}$ 을 대칭점으로 바꾸면 둘레는 어떤 꺾인 길이 되는가?","식":["$\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}}=\\overline{\\mathrm{P}'\\mathrm{Q}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}''}\\ge\\overline{\\mathrm{P}'\\mathrm{P}''}$"],"설명":"대칭이동하면 $\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{P}'\\mathrm{Q}}$, $\\overline{\\mathrm{PR}}=\\overline{\\mathrm{P}''\\mathrm{R}}$ 이다. 직선 $\\mathrm{P}'\\mathrm{P}''$ 이 $y=x$ 와 $y$축을 선분 $\\mathrm{P}'\\mathrm{P}''$ 위에서 만나므로 등호가 성립한다.","확인":null,"스킬":"G4"},{"제목":"두 대칭점 사이의 거리","힌트":"$\\mathrm{P}'(-7,-1)$ 과 $\\mathrm{P}''(1,-7)$ 사이의 거리는?","식":["$\\overline{\\mathrm{P}'\\mathrm{P}''}=\\sqrt{(1+7)^2+(-7+1)^2}=\\sqrt{100}=10$"],"설명":"가로 방향의 차와 세로 방향의 차로 거리 공식을 쓰면 둘레의 최솟값이 정해진다.","확인":"10","스킬":"S3"}]},"ns-9ad9c707ce5f":{"길":"조건 (가)로 부호를 정하고 $z^2=-16$ 에서 $z$ 의 실수부를 $0$ 으로 놓는다","단계":[{"제목":"조건 (가)에서 $a$, $b$ 의 부호","힌트":"$a$, $b$ 의 부호를 나누어 보면 $\\dfrac{\\sqrt a}{\\sqrt b}=-\\sqrt{\\dfrac ab}$ 가 성립하는 경우는?","식":["$a>0,\\ b<0$"],"설명":"음수의 제곱근 성질에서 $\\dfrac{\\sqrt a}{\\sqrt b}=-\\sqrt{\\dfrac ab}$ 는 $a>0$, $b<0$ 일 때만 성립한다. 다른 부호 조합에서는 두 변이 같지 않다.","확인":null,"스킬":"A5","고비":true},{"제목":"조건 (나)에서 $z$ 의 실수부와 허수부","힌트":"$z^2=-16$ 을 만족하는 $z$ 는 어떤 꼴인가?","식":["$z=\\pm4i$","$a+b-2=0,\\ \\ a-b=\\pm4$"],"설명":"$z=p+qi$ 로 놓으면 $z^2=p^2-q^2+2pqi=-16$ 이므로 $p=0$, $q=\\pm4$ 이다. 즉 $z$ 의 실수부는 $0$ 이고 허수부는 $\\pm4$ 이다.","확인":null,"스킬":"A5"},{"제목":"$a$, $b$ 의 값","힌트":"$a>0>b$ 이면 $a-b$ 의 부호는? 그때 연립하면 $a$ 의 값은?","식":["$a-b>0$ 이므로 $a-b=4$","$a+b=2,\\ a-b=4$ 에서 $a=3,\\ b=-1$"],"설명":"(가)에서 $a-b>0$ 이므로 $a-b=-4$ 는 버린다. 두 식을 더하면 $a$ 가 먼저 정해진다.","확인":"3","스킬":"A10"},{"제목":"평행이동한 점의 좌표","힌트":"$(2,4)$ 의 $x$ 좌표에 $a$, $y$ 좌표에 $b$ 를 더하면?","식":["$(2+3,\\ 4+(-1))=(5,3)$"],"설명":"평행이동 $(x,y)\\to(x+a,\\ y+b)$ 는 $x$ 좌표에 $a$, $y$ 좌표에 $b$ 를 더하는 이동이다.","확인":null,"스킬":"G4"}]},"ns-9fb3330d8099":{"길":"$\\overline{\\mathrm{AB}}$ 는 고정이므로 $\\mathrm{A}$ 를 $y=x$ 에 대칭이동해 $\\overline{\\mathrm{PA}}+\\overline{\\mathrm{PB}}$ 를 편다","단계":[{"제목":"고정된 변의 길이","힌트":"$\\mathrm{P}$ 가 움직여도 변하지 않는 변은 무엇이고 그 길이는?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(7-5)^2+(3-1)^2}=2\\sqrt2$"],"설명":"둘레는 $\\overline{\\mathrm{PA}}+\\overline{\\mathrm{PB}}+\\overline{\\mathrm{AB}}$ 이고 $\\overline{\\mathrm{AB}}$ 는 $\\mathrm{P}$ 와 무관하다. 따라서 $\\overline{\\mathrm{PA}}+\\overline{\\mathrm{PB}}$ 의 최솟값을 구하면 된다.","확인":null,"스킬":"S3"},{"제목":"대칭점으로 $\\overline{\\mathrm{PA}}+\\overline{\\mathrm{PB}}$ 펴기","힌트":"$\\mathrm{A}$ 를 직선 $y=x$ 에 대칭이동한 점은?","식":["$\\mathrm{A}'(1,5)$","$\\overline{\\mathrm{PA}}+\\overline{\\mathrm{PB}}=\\overline{\\mathrm{PA}'}+\\overline{\\mathrm{PB}}\\ge\\overline{\\mathrm{A}'\\mathrm{B}}$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$ 는 모두 $y=x$ 의 아래쪽에 있으므로 한 점을 대칭이동해 일직선 위에 놓는다. 직선 $\\mathrm{A}'\\mathrm{B}$ 가 $y=x$ 와 선분 $\\mathrm{A}'\\mathrm{B}$ 위에서 만나므로 등호가 성립한다.","확인":null,"스킬":"G4","고비":true},{"제목":"둘레의 최솟값","힌트":"$\\overline{\\mathrm{A}'\\mathrm{B}}$ 의 길이에 $\\overline{\\mathrm{AB}}$ 를 더하면?","식":["$\\overline{\\mathrm{A}'\\mathrm{B}}=\\sqrt{(7-1)^2+(3-5)^2}=2\\sqrt{10}$","$2\\sqrt{10}+2\\sqrt2$"],"설명":"$\\overline{\\mathrm{PA}}+\\overline{\\mathrm{PB}}$ 의 최솟값에 고정된 변 $\\overline{\\mathrm{AB}}$ 를 더한다.","확인":null,"스킬":"S3"}]},"ns-b0a8e7358855":{"길":"접는 선이 $\\overline{\\mathrm{AA}'}$ 와 $\\overline{\\mathrm{FF}'}$ 의 수직이등분선임을 이용해 기울기를 같게 놓는다","단계":[{"제목":"접기 전후의 점 놓기","힌트":"$\\mathrm{A}$, $\\mathrm{F}$ 의 좌표와, $\\mathrm{OC}$ 위의 $\\mathrm{A}'$, 직선 $\\mathrm{DE}$ 위의 $\\mathrm{F}'$ 의 좌표 꼴은?","식":["$\\mathrm{A}(12,0),\\ \\mathrm{F}(12,5)$","$\\mathrm{A}'(0,s),\\ \\mathrm{F}'(4,t)$"],"설명":"한 변이 $12$ 인 정사각형이므로 $\\mathrm{A}(12,0)$ 이다. $\\mathrm{E}$ 는 $\\overline{\\mathrm{OA}}$ 를 $1:2$ 로 내분하므로 $\\mathrm{E}(4,0)$ 이고, 직선 $\\mathrm{DE}$ 는 $x=4$ 이다.","확인":null,"스킬":"G4"},{"제목":"$\\mathrm{F}'$ 과 $\\mathrm{A}'$ 의 $y$ 좌표의 차","힌트":"접어도 길이는 변하지 않는다. $\\overline{\\mathrm{A}'\\mathrm{F}'}$ 의 길이로 $t-s$ 를 구하면?","식":["$\\overline{\\mathrm{A}'\\mathrm{F}'}=\\overline{\\mathrm{AF}}=5$","$4^2+(t-s)^2=5^2\\ \\Rightarrow\\ t=s+3$"],"설명":"$\\mathrm{A}'$ 과 $\\mathrm{F}'$ 의 $x$ 좌표 차가 $4$ 이므로 $y$ 좌표 차는 $3$ 이다. 그림에서 $\\mathrm{F}'$ 이 $\\mathrm{A}'$ 보다 위에 있으므로 $t=s+3$ 이다.","확인":"3","스킬":"S3"},{"제목":"$s$ 의 값","힌트":"접는 선은 $\\overline{\\mathrm{AA}'}$ 와 $\\overline{\\mathrm{FF}'}$ 를 각각 수직이등분한다. 두 선분에서 구한 접는 선의 기울기를 같게 놓으면 $s$ 는?","식":["$\\dfrac{12}{s}=\\dfrac{8}{s-2}$","$s=6$"],"설명":"$\\overline{\\mathrm{AA}'}$ 의 기울기가 $-\\dfrac{s}{12}$ 이므로 접는 선의 기울기는 $\\dfrac{12}{s}$ 이다. $\\overline{\\mathrm{FF}'}$ 의 기울기는 $\\dfrac{t-5}{4-12}=\\dfrac{s-2}{-8}$ 이므로 접는 선의 기울기는 $\\dfrac{8}{s-2}$ 이다. 두 값이 같으므로 $s$ 가 정해진다.","확인":"6","스킬":"G4","고비":true},{"제목":"접는 선 $\\mathrm{PQ}$ 의 방정식","힌트":"기울기 $m$ 과 $\\overline{\\mathrm{AA}'}$ 의 중점으로 직선의 식을 세우면 $n$ 은?","식":["$m=\\dfrac{12}{6}=2$","$y-3=2(x-6)\\ \\Rightarrow\\ y=2x-9$"],"설명":"$\\mathrm{A}(12,0)$ 과 $\\mathrm{A}'(0,6)$ 의 중점은 $(6,3)$ 이다. 접는 선은 이 중점을 지나고 기울기가 $2$ 이다.","확인":"-9","스킬":"G9"},{"제목":"$mn$ 의 값","힌트":"$m$, $n$ 을 곱하면?","식":["$mn=2\\times(-9)=-18$"],"설명":"$m=2$, $n=-9$ 이므로 곱이 바로 정해진다.","확인":"-18","스킬":"G9"}]},"ns-c5fc6c552cff":{"길":"공이 맞는 두 벽에 대해 $\\mathrm{A}$, $\\mathrm{B}$ 를 대칭이동해 경로를 한 직선으로 편다","단계":[{"제목":"공이 맞는 두 벽의 위치","힌트":"그림에서 공이 차례로 맞는 두 쿠션은 어느 직선 위에 있는가?","식":["$y=0,\\ \\ x=8$"],"설명":"첫 쿠션은 $x$축 위의 점 $\\mathrm{P}$ 이다. 둘째 쿠션은 점 $\\mathrm{X}(8,0)$ 을 지나는 세로 변 $x=8$ 위의 점이다.","확인":null,"스킬":"G4"},{"제목":"두 점의 대칭이동","힌트":"$\\mathrm{A}$ 는 $x$축에, $\\mathrm{B}$ 는 직선 $x=8$ 에 대칭이동하면?","식":["$\\mathrm{A}'(3,-1),\\ \\mathrm{B}'(11,3)$"],"설명":"$\\mathrm{A}$ 를 $x$축에 대칭이동한 점을 $\\mathrm{A}'$, $\\mathrm{B}$ 를 직선 $x=8$ 에 대칭이동한 점을 $\\mathrm{B}'$ 이라 한다. 두 번 반사되는 경로가 $\\mathrm{A}'$ 에서 $\\mathrm{B}'$ 로 가는 직선으로 펴진다.","확인":null,"스킬":"G4","고비":true},{"제목":"직선 $\\mathrm{A}'\\mathrm{B}'$ 의 방정식","힌트":"두 점 $(3,-1)$, $(11,3)$ 을 지나는 직선의 기울기는?","식":["$\\dfrac{3-(-1)}{11-3}=\\dfrac12$","$y=\\dfrac12(x-3)-1$"],"설명":"기울기를 구한 뒤 한 점을 지나도록 직선의 식을 세운다.","확인":"1/2","스킬":"G3"},{"제목":"점 $\\mathrm{P}$ 의 좌표","힌트":"직선 $\\mathrm{A}'\\mathrm{B}'$ 이 $x$축과 만나는 점은?","식":["$0=\\dfrac12(x-3)-1\\ \\Rightarrow\\ x=5$","$\\mathrm{P}(5,0)$"],"설명":"점 $\\mathrm{P}$ 는 직선 $\\mathrm{A}'\\mathrm{B}'$ 과 $x$축의 교점이다. 이 직선이 $x=8$ 과 만나는 점의 $y$ 좌표는 $\\dfrac32$ 로 당구대 변 위에 있다.","확인":null,"스킬":"G1"}]},"ns-ce23438c27c3":{"길":"$f$ 의 그래프 위의 점이 옮겨지는 규칙을 찾고 꼭짓점을 따라가 그림을 고른다","단계":[{"제목":"점의 이동 규칙","힌트":"$f(x+1,-y+1)=0$ 위의 점 $(X,Y)$ 에 대해, $f(x,y)=0$ 위의 대응하는 점 $(x,y)$ 는?","식":["$x=X+1,\\ \\ y=-Y+1$","$(x,y)\\to(x-1,\\ 1-y)$"],"설명":"$f(X+1,-Y+1)=0$ 이므로 $(X+1,-Y+1)$ 이 $f(x,y)=0$ 위의 점이다. 따라서 $X=x-1$, $Y=1-y$ 이고, $x$축 대칭 뒤 $x$축 방향으로 $-1$, $y$축 방향으로 $1$ 만큼 평행이동한 것이다.","확인":null,"스킬":"G4","고비":true},{"제목":"꼭짓점 세 점의 이동","힌트":"그래프의 꼭짓점 $(0,1)$, $(1,0)$, $(2,1)$ 은 각각 어디로 옮겨지는가?","식":["$(0,1)\\to(-1,0)$","$(1,0)\\to(0,1)$","$(2,1)\\to(1,0)$"],"설명":"각 점의 $x$ 좌표에서 $1$ 을 빼고, $y$ 좌표는 $1$ 에서 원래 $y$ 좌표를 뺀 값으로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"곡선 부분의 방향과 그림 선택","힌트":"원래 곡선은 $y=1$ 보다 위쪽이었다. 이동하면 어느 쪽에 놓이고, 꼭짓점이 $(-1,0)$, $(0,1)$, $(1,0)$ 인 그림은 몇 번인가?","식":["$y>1\\ \\Rightarrow\\ 1-y<0$"],"설명":"원래 곡선의 $y$ 좌표는 $1$ 보다 크다. 이동 후에는 $1-y<0$ 이므로 곡선이 $x$축 아래쪽에 놓인다. 꼭짓점이 $(-1,0)$, $(0,1)$, $(1,0)$ 이고 곡선이 $x$축 아래에 있는 그림은 ② 이다.","확인":null,"스킬":"G4"}]},"ns-d3a74c2df4e7":{"길":"$\\mathrm{C}'$ 로 $m$, $n$ 을 정해 직각삼각형임을 확인하고 내접원의 반지름과 중심을 구한다","단계":[{"제목":"$m$, $n$ 의 값","힌트":"$\\mathrm{C}(1,5)$ 를 $y$축에 대칭이동한 점을 $x$축 방향 $m$, $y$축 방향 $n$ 만큼 옮기면 $(-5,2)$ 이다. $m$, $n$ 은?","식":["$(-1,5)\\to(-1+m,\\ 5+n)=(-5,2)$","$m=-4,\\ \\ n=-3$"],"설명":"$y$축 대칭이면 $x$ 좌표의 부호만 바뀌어 $\\mathrm{C}$ 는 $(-1,5)$ 가 된다. 이 점에 $m$, $n$ 을 각각 더한 것이 $\\mathrm{C}'$ 이다.","확인":null,"스킬":"G4"},{"제목":"삼각형 $\\mathrm{A}'\\mathrm{B}'\\mathrm{C}'$ 의 꼭짓점과 한 변의 길이","힌트":"같은 이동을 $\\mathrm{A}$, $\\mathrm{B}$ 에도 적용하면 꼭짓점은? $\\overline{\\mathrm{A}'\\mathrm{B}'}$ 의 길이는?","식":["$\\mathrm{A}'(-5,-3),\\ \\mathrm{B}'(-17,-3),\\ \\mathrm{C}'(-5,2)$","$\\overline{\\mathrm{A}'\\mathrm{B}'}=12$"],"설명":"$\\mathrm{A}(1,0)\\to(-1,0)\\to(-5,-3)$, $\\mathrm{B}(13,0)\\to(-13,0)\\to(-17,-3)$ 이다. $\\overline{\\mathrm{A}'\\mathrm{B}'}$ 은 $x$축에 평행하고 $\\overline{\\mathrm{A}'\\mathrm{C}'}$ 은 $y$축에 평행하므로 $\\mathrm{A}'$ 에서 직각이다.","확인":"12","스킬":"G4"},{"제목":"내접원의 반지름","힌트":"직각삼각형의 넓이를 두 방법으로 쓰면 반지름은?","식":["$\\overline{\\mathrm{A}'\\mathrm{C}'}=5,\\ \\ \\overline{\\mathrm{B}'\\mathrm{C}'}=13$","$\\dfrac12\\cdot12\\cdot5=\\dfrac12\\,r\\,(12+5+13)$","$r=2$"],"설명":"삼각형의 넓이는 내접원의 반지름과 둘레의 곱의 절반이다. 직각을 낀 두 변으로 구한 넓이와 같다고 놓는다.","확인":"2","스킬":"S7"},{"제목":"내접원의 중심","힌트":"중심은 직각을 낀 두 변에서 각각 $r$ 만큼 떨어진 삼각형 안쪽의 점이다. $x$ 좌표 $a$ 는?","식":["$a=-5-2=-7,\\ \\ b=-3+2=-1$"],"설명":"직각을 낀 두 변은 직선 $x=-5$ 와 $y=-3$ 이다. 삼각형은 $x=-5$ 의 왼쪽, $y=-3$ 의 위쪽에 있으므로 중심의 $x$ 좌표는 $-5-r$, $y$ 좌표는 $-3+r$ 이다.","확인":"-7","스킬":"S7","고비":true},{"제목":"$a+b+|r|$ 의 값","힌트":"$a$, $b$, $|r|$ 을 더하면?","식":["$-7+(-1)+2=-6$"],"설명":"구한 중심의 좌표와 반지름을 대입한다.","확인":"-6","스킬":"S7"}]},"ns-d80659a41c29":{"길":"교차점을 원점으로 잡고 $\\mathrm{A}$, $\\mathrm{B}$ 를 각각 다른 도로에 대칭이동해 한 선분으로 편다","단계":[{"제목":"좌표 설정","힌트":"두 고속도로의 교차점을 원점으로 하고 한 도로를 $y$축, 다른 도로를 $x$축으로 잡으면 $\\mathrm{A}$, $\\mathrm{B}$ 의 좌표는?","식":["$\\mathrm{A}(1,5),\\ \\mathrm{B}(4,2)$"],"설명":"그림에서 $\\mathrm{A}$ 는 세로 도로에서 $1$, 가로 도로에서 $5$ 만큼 떨어져 있고 $\\mathrm{B}$ 는 세로 도로에서 $4$, 가로 도로에서 $2$ 만큼 떨어져 있다. 따라서 $\\mathrm{P}$ 는 $y$축 위, $\\mathrm{Q}$ 는 $x$축 위의 점이다.","확인":null,"스킬":"S4"},{"제목":"두 점의 대칭이동","힌트":"$\\mathrm{P}$ 는 $y$축 위, $\\mathrm{Q}$ 는 $x$축 위에 있다. $\\mathrm{A}$, $\\mathrm{B}$ 를 각각 어느 축에 대칭이동해야 하는가?","식":["$\\mathrm{A}'(-1,5),\\ \\mathrm{B}'(4,-2)$","$\\overline{\\mathrm{AP}}+\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QB}}=\\overline{\\mathrm{A}'\\mathrm{P}}+\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QB}'}$"],"설명":"$\\mathrm{A}$ 를 $y$축에 대칭이동한 점을 $\\mathrm{A}'$, $\\mathrm{B}$ 를 $x$축에 대칭이동한 점을 $\\mathrm{B}'$ 이라 하면 $\\overline{\\mathrm{AP}}=\\overline{\\mathrm{A}'\\mathrm{P}}$, $\\overline{\\mathrm{QB}}=\\overline{\\mathrm{QB}'}$ 이다.","확인":null,"스킬":"G4","고비":true},{"제목":"도로 길이의 최솟값","힌트":"세 선분의 합이 가장 작아지는 경우의 값은 어떤 선분의 길이인가?","식":["$\\overline{\\mathrm{A}'\\mathrm{P}}+\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QB}'}\\ge\\overline{\\mathrm{A}'\\mathrm{B}'}$","$\\overline{\\mathrm{A}'\\mathrm{B}'}=\\sqrt{(4+1)^2+(-2-5)^2}=\\sqrt{74}$"],"설명":"직선 $\\mathrm{A}'\\mathrm{B}'$ 이 $y$축, $x$축과 만나는 점을 $\\mathrm{P}$, $\\mathrm{Q}$ 로 잡을 수 있으므로 등호가 성립한다. 두 점의 가로 방향의 차는 $5$, 세로 방향의 차는 $7$ 이다.","확인":null,"스킬":"S3"}]},"ns-d89c8280c802":{"길":"$\\mathrm{C}$ 를 직선 $\\mathrm{BE}$ 에 대칭이동한 $\\mathrm{C}'$ 의 좌표를 구해 직선 $\\mathrm{BC}'$ 까지의 거리를 잰다","단계":[{"제목":"좌표 설정","힌트":"$\\mathrm{B}$ 를 원점으로 $\\mathrm{BC}$ 를 $x$축, $\\mathrm{BA}$ 를 $y$축으로 잡으면 $\\mathrm{E}$ 의 좌표는?","식":["$\\mathrm{A}(0,6),\\ \\mathrm{B}(0,0),\\ \\mathrm{C}(6,0),\\ \\mathrm{D}(6,6)$","$\\mathrm{E}(6,2)$"],"설명":"$\\overline{\\mathrm{CD}}$ 를 $1:2$ 로 내분하는 점이므로 $\\overline{\\mathrm{CE}}=2$ 이다. 직선 $\\mathrm{BE}$ 의 방정식은 $y=\\dfrac13x$ 이다.","확인":null,"스킬":"S4"},{"제목":"대칭점 $\\mathrm{C}'$ 이 만족하는 두 조건","힌트":"$\\mathrm{C}'(a,b)$ 라 하면 $\\overline{\\mathrm{CC}'}$ 의 중점과 $\\overline{\\mathrm{CC}'}$ 의 기울기는 직선 $\\mathrm{BE}$ 와 어떤 관계인가?","식":["$\\dfrac b2=\\dfrac13\\cdot\\dfrac{a+6}{2}\\ \\Rightarrow\\ a-3b=-6$","$\\dfrac{b}{a-6}\\cdot\\dfrac13=-1\\ \\Rightarrow\\ 3a+b=18$"],"설명":"$\\mathrm{C}'$ 은 $\\mathrm{C}$ 를 직선 $\\mathrm{BE}$ 에 대칭이동한 점이다. 따라서 $\\overline{\\mathrm{CC}'}$ 의 중점이 직선 $\\mathrm{BE}$ 위에 있고, $\\overline{\\mathrm{CC}'}$ 은 직선 $\\mathrm{BE}$ 에 수직이다.","확인":null,"스킬":"G4","고비":true},{"제목":"$\\mathrm{C}'$ 의 좌표","힌트":"두 식을 연립하면 $b$ 는?","식":["$a-3b=-6,\\ \\ 3a+b=18$","$a=\\dfrac{24}{5},\\ \\ b=\\dfrac{18}{5}$"],"설명":"$a=3b-6$ 을 $3a+b=18$ 에 대입하면 $10b=36$ 이다.","확인":"18/5","스킬":"A10"},{"제목":"직선 $\\mathrm{BC}'$ 의 방정식","힌트":"원점과 $\\mathrm{C}'$ 을 지나는 직선의 기울기는?","식":["$\\dfrac{b}{a}=\\dfrac{18/5}{24/5}=\\dfrac34$","$3x-4y=0$"],"설명":"직선 $\\mathrm{BC}'$ 은 원점을 지나므로 기울기만 구하면 식이 정해진다.","확인":"3/4","스킬":"G9"},{"제목":"점 $\\mathrm{A}$ 와 직선 $\\mathrm{BC}'$ 사이의 거리","힌트":"점 $(0,6)$ 과 직선 $3x-4y=0$ 사이의 거리는?","식":["$\\dfrac{|3\\cdot0-4\\cdot6|}{\\sqrt{3^2+4^2}}=\\dfrac{24}{5}$"],"설명":"점과 직선 사이의 거리 공식을 쓴다.","확인":"24/5","스킬":"G4"}]},"ns-e0be8cc7754a":{"길":"식의 변환을 따라 꼭짓점을 옮기고, $\\mathrm{B}$ 를 중심으로 하는 원과 삼각형의 교점 수를 센다","단계":[{"제목":"삼각형 $\\mathrm{ABC}$ 에서 $\\mathrm{P}$ 가 그리는 도형으로의 이동 규칙","힌트":"$f(x+3,2-y)=0$ 위의 점 $(X,Y)$ 가 $f(x-5,y-4)=0$ 위의 점 $(X',Y')$ 로 옮겨질 때 $X'$, $Y'$ 를 $X$, $Y$ 로 나타내면?","식":["$X+3=X'-5,\\ \\ 2-Y=Y'-4$","$(X,Y)\\to(X+8,\\ 6-Y)$"],"설명":"두 식은 같은 함수 $f$ 의 같은 값을 가리키므로 대응하는 인수끼리 같다고 놓는다. $y$ 좌표는 부호가 바뀌고 $6$ 이 더해지므로 $x$축 대칭 뒤 평행이동한 것이다.","확인":null,"스킬":"G4"},{"제목":"이동한 삼각형의 꼭짓점","힌트":"세 꼭짓점 $\\mathrm{A}(0,4)$, $\\mathrm{B}(-2,0)$, $\\mathrm{C}(2,0)$ 에 이동 규칙을 적용하면?","식":["$\\mathrm{A}'(8,2),\\ \\mathrm{B}'(6,6),\\ \\mathrm{C}'(10,6)$"],"설명":"$(X,Y)\\to(X+8,\\ 6-Y)$ 에 각 점을 대입한다. 점 $\\mathrm{P}$ 는 삼각형 $\\mathrm{A}'\\mathrm{B}'\\mathrm{C}'$ 위를 움직이고, 점 $\\mathrm{B}$ 는 그대로 $(-2,0)$ 이다.","확인":null,"스킬":"G4"},{"제목":"$\\overline{\\mathrm{BP}}$ 의 범위","힌트":"$\\mathrm{B}(-2,0)$ 에서 삼각형 $\\mathrm{A}'\\mathrm{B}'\\mathrm{C}'$ 위의 점까지의 거리 중 가장 짧은 값과 가장 긴 값은?","식":["직선 $\\mathrm{A}'\\mathrm{B}'$: $y=-2x+18$","$\\dfrac{|2\\cdot(-2)+0-18|}{\\sqrt5}=\\dfrac{22}{\\sqrt5}\\approx9.84$","$\\overline{\\mathrm{BC}'}=\\sqrt{12^2+6^2}=\\sqrt{180}\\approx13.4$"],"설명":"수선의 발 $(6.8,\\ 4.4)$ 가 선분 $\\mathrm{A}'\\mathrm{B}'$ 위에 있으므로 최솟값은 점과 직선 사이의 거리이다. 세 꼭짓점까지의 거리 $\\sqrt{104}$, $10$, $\\sqrt{180}$ 중 가장 큰 것이 최댓값이다.","확인":null,"스킬":"S5"},{"제목":"정수 값마다 대응하는 점 $\\mathrm{P}$ 의 개수","힌트":"정수 $10,\\ 11,\\ 12,\\ 13$ 마다 중심이 $\\mathrm{B}$ 이고 반지름이 그 값인 원이 삼각형과 만나는 점은 몇 개인가?","식":["$n=10,\\ 11,\\ 12,\\ 13$ 일 때 $\\overline{\\mathrm{BP}}=n$ 인 점 $\\mathrm{P}$ 는 각각 $2$ 개"],"설명":"$n=10$ 이면 원이 직선 $\\mathrm{A}'\\mathrm{B}'$ 과 두 점에서 만나는데, 하나는 꼭짓점 $\\mathrm{B}'$ 이고 다른 하나는 수선의 발과 $\\mathrm{A}'$ 사이에 있다. $n=11,12,13$ 이면 원은 선분 $\\mathrm{B}'\\mathrm{C}'$ 과 선분 $\\mathrm{A}'\\mathrm{C}'$ 에서 한 점씩 만난다.","확인":"2","스킬":"C2","고비":true},{"제목":"조건을 만족하는 점 $\\mathrm{P}$ 의 개수","힌트":"정수 값의 개수와 값마다의 점의 개수를 곱하면?","식":["$4\\times2=8$"],"설명":"정수 값이 네 개이고 값마다 점이 두 개씩이므로 전체 개수가 정해진다.","확인":"8","스킬":"C2"}]},"ns-e1a2aeb34181":{"길":"$\\mathrm{C}$ 를 $x$축, $y$축에 차례로 대칭이동해 꺾인 길을 펴고 직선 $\\mathrm{AB}$ 까지의 최단거리를 잡는다","단계":[{"제목":"$\\mathrm{C}$ 의 두 번 대칭이동","힌트":"$\\mathrm{C}(4,1)$ 을 $x$축에 대칭이동한 점과, 그 점을 다시 $y$축에 대칭이동한 점은?","식":["$\\mathrm{C}_1(4,-1),\\ \\mathrm{C}_2(-4,-1)$"],"설명":"$\\mathrm{P}$ 는 $x$축 위의 점이므로 $\\overline{\\mathrm{CP}}=\\overline{\\mathrm{C}_1\\mathrm{P}}$ 이다. $\\mathrm{Q}$ 는 $y$축 위의 점이므로 $\\overline{\\mathrm{C}_1\\mathrm{Q}}=\\overline{\\mathrm{C}_2\\mathrm{Q}}$ 이다.","확인":null,"스킬":"G4","고비":true},{"제목":"합이 최소가 되는 조건","힌트":"세 선분의 합을 $\\mathrm{C}_2$ 에서 $\\mathrm{R}$ 까지의 거리와 비교하면 어떤 부등식이 되는가?","식":["$\\overline{\\mathrm{CP}}+\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QR}}\\ge\\overline{\\mathrm{C}_1\\mathrm{Q}}+\\overline{\\mathrm{QR}}$","$\\overline{\\mathrm{C}_1\\mathrm{Q}}+\\overline{\\mathrm{QR}}=\\overline{\\mathrm{C}_2\\mathrm{Q}}+\\overline{\\mathrm{QR}}\\ge\\overline{\\mathrm{C}_2\\mathrm{R}}$"],"설명":"$\\mathrm{R}$ 가 선분 $\\mathrm{AB}$ 위를 움직이므로 $\\overline{\\mathrm{C}_2\\mathrm{R}}$ 은 $\\mathrm{C}_2$ 에서 직선 $\\mathrm{AB}$ 에 내린 수선의 발에서 최소이다. 수선의 발이 선분 $\\mathrm{AB}$ 위에 있는지는 마지막에 확인한다.","확인":null,"스킬":"G4"},{"제목":"직선 $\\mathrm{AB}$ 의 방정식","힌트":"두 점 $(2,6)$, $(5,2)$ 를 지나는 직선의 기울기는?","식":["$\\dfrac{2-6}{5-2}=-\\dfrac43$","$4x+3y=26$"],"설명":"기울기를 구한 뒤 한 점을 대입해 직선의 식을 정리한다.","확인":"-4/3","스킬":"G3"},{"제목":"수선 $\\mathrm{C}_2\\mathrm{R}$ 의 방정식","힌트":"직선 $\\mathrm{AB}$ 에 수직인 직선의 기울기는? 점 $\\mathrm{C}_2(-4,-1)$ 을 지나는 식은?","식":["$-\\dfrac43\\cdot m=-1\\ \\Rightarrow\\ m=\\dfrac34$","$y+1=\\dfrac34(x+4)$, 즉 $3x-4y=-8$"],"설명":"두 직선이 수직이면 기울기의 곱이 $-1$ 이다.","확인":"3/4","스킬":"G9"},{"제목":"점 $\\mathrm{R}$ 의 $x$ 좌표","힌트":"두 직선 $4x+3y=26$, $3x-4y=-8$ 의 교점의 $x$ 좌표는?","식":["$16x+12y=104,\\ \\ 9x-12y=-24$","$25x=80\\ \\Rightarrow\\ x=\\dfrac{16}{5}$"],"설명":"$y$ 를 소거하면 $x$ 가 정해진다. $2\\le\\dfrac{16}{5}\\le5$ 이므로 수선의 발은 선분 $\\mathrm{AB}$ 위에 있다.","확인":"16/5","스킬":"A10"}]},"ns-e1f44f08613c":{"길":"부딪힌 변의 반대 순서로 구멍 $\\mathrm{C}$ 를 차례로 대칭이동해 공의 경로를 한 직선으로 편다","단계":[{"제목":"좌표 설정과 공의 위치","힌트":"$\\mathrm{B}$ 를 원점으로 놓으면 공의 $x$ 좌표는?","식":["$\\mathrm{B}(0,0),\\ \\mathrm{C}(2,0),\\ \\mathrm{D}(2,1),\\ \\mathrm{A}(0,1)$","공 $(1.6,\\ 0.5)$"],"설명":"공은 변 $\\mathrm{CD}$ 에서 $0.4\\,\\mathrm{m}$ 떨어져 있으므로 $x$ 좌표는 $2-0.4$ 이다. 변 $\\mathrm{BC}$ 에서 $0.5\\,\\mathrm{m}$ 떨어져 있으므로 $y$ 좌표는 $0.5$ 이다.","확인":"1.6","스킬":"S4"},{"제목":"구멍 $\\mathrm{C}$ 의 차례 대칭이동","힌트":"마지막에 부딪힌 변부터 거꾸로 $\\mathrm{C}$ 를 차례로 대칭이동하면 마지막 점은 어디인가?","식":["$\\mathrm{C}(2,0)\\to(2,2)\\to(2,-2)\\to(-2,-2)\\to(-2,4)\\to(-2,-4)$"],"설명":"부딪힌 순서가 $\\mathrm{BC}$, $\\mathrm{AD}$, $\\mathrm{AB}$, $\\mathrm{BC}$, $\\mathrm{AD}$ 이므로 반대로 $\\mathrm{AD}$($y=1$), $\\mathrm{BC}$($y=0$), $\\mathrm{AB}$($x=0$), $\\mathrm{AD}$($y=1$), $\\mathrm{BC}$($y=0$) 에 차례로 대칭이동한다. 한 번 대칭이동할 때마다 그 변에서 꺾이는 경로가 곧게 펴진다.","확인":null,"스킬":"G4","고비":true},{"제목":"공에서 마지막 점까지의 가로·세로 방향의 차","힌트":"공 $(1.6,\\ 0.5)$ 와 점 $(-2,-4)$ 의 $x$ 좌표의 차는?","식":["$1.6-(-2)=3.6,\\ \\ 0.5-(-4)=4.5$"],"설명":"펼친 경로는 공에서 $(-2,-4)$ 까지의 선분이므로 공이 움직인 거리는 이 선분의 길이이다.","확인":"3.6","스킬":"S3"},{"제목":"공이 움직인 거리","힌트":"가로 $3.6$, 세로 $4.5$ 인 직각삼각형의 빗변은 얼마인가?","식":["$\\sqrt{3.6^2+4.5^2}=\\sqrt{0.9^2(4^2+5^2)}=0.9\\sqrt{41}$"],"설명":"$3.6=0.9\\times4$, $4.5=0.9\\times5$ 이므로 $0.9$ 를 묶어 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3"}]},"ns-e323ff45fa76":{"길":"새 식에서 점의 이동 규칙을 구해 꼭짓점을 옮기고 직각삼각형의 내심을 구한다","단계":[{"제목":"점의 이동 규칙","힌트":"$f(y+2,3-x)=0$ 위의 점 $(X,Y)$ 에 대해, $f(x,y)=0$ 위의 대응하는 점 $(x,y)$ 는?","식":["$x=Y+2,\\ \\ y=3-X$","$(x,y)\\to(3-y,\\ x-2)$"],"설명":"새 도형 위의 점 $(X,Y)$ 는 $(Y+2,\\ 3-X)$ 가 $f(x,y)=0$ 위의 점이다. 이를 $X$, $Y$ 에 대해 풀면 원래 점 $(x,y)$ 가 $(3-y,\\ x-2)$ 로 옮겨진다.","확인":null,"스킬":"G4","고비":true},{"제목":"이동한 삼각형의 꼭짓점","힌트":"세 꼭짓점 $\\mathrm{A}(1,4)$, $\\mathrm{B}(1,0)$, $\\mathrm{C}(3,0)$ 에 이동 규칙을 적용하면?","식":["$\\mathrm{A}(1,4)\\to(-1,-1)$","$\\mathrm{B}(1,0)\\to(3,-1)$","$\\mathrm{C}(3,0)\\to(3,1)$"],"설명":"$(x,y)\\to(3-y,\\ x-2)$ 에 각 점을 대입한다. 새 삼각형은 $(3,-1)$ 에서 직각이다.","확인":null,"스킬":"G4"},{"제목":"내접원의 반지름","힌트":"직각을 낀 두 변과 빗변의 길이로 반지름을 구하면?","식":["직각을 낀 두 변 $4,\\ 2$, 빗변 $2\\sqrt5$","$r=\\dfrac{4+2-2\\sqrt5}{2}=3-\\sqrt5$"],"설명":"직각 꼭짓점에서 접점까지의 거리가 $r$ 이고 접선의 길이가 같으므로, 직각을 낀 변 $p$, $q$ 와 빗변 $c$ 에 대해 $p+q-2r=c$ 이다.","확인":null,"스킬":"S7"},{"제목":"내심의 좌표","힌트":"내심은 직각을 낀 두 변 $x=3$, $y=-1$ 에서 각각 $r$ 만큼 떨어진 삼각형 안쪽의 점이다. 좌표는?","식":["$(a,b)=(3-r,\\ -1+r)=(\\sqrt5,\\ 2-\\sqrt5)$"],"설명":"삼각형은 직선 $x=3$ 의 왼쪽, 직선 $y=-1$ 의 위쪽에 있으므로 내심의 $x$ 좌표는 $3-r$, $y$ 좌표는 $-1+r$ 이다.","확인":null,"스킬":"S7"},{"제목":"$2a+b$ 의 값","힌트":"$a$, $b$ 를 대입하면?","식":["$2\\sqrt5+(2-\\sqrt5)=2+\\sqrt5$"],"설명":"$a=\\sqrt5$, $b=2-\\sqrt5$ 를 대입하면 근호 항을 합쳐 정리된다.","확인":null,"스킬":"G4"}]},"ns-e7869ae82ca9":{"길":"$g$ 의 꼭짓점이 $f$ 의 어느 꼭짓점과 대응하는지 정하고 인수를 구해 선지와 맞춘다","단계":[{"제목":"좌표를 읽을 수 있는 꼭짓점","힌트":"그림에서 $f$ 와 $g$ 에서 좌표가 읽히는 꼭짓점을 세 점씩 찾으면?","식":["$f$: $(0,0),\\ (0,-2),\\ (2,-1)$","$g$: $(-1,2),\\ (-3,2),\\ (-2,0)$"],"설명":"$f$ 의 오른쪽 뾰족한 점과 왼쪽 두 끝점, $g$ 의 아래쪽 뾰족한 점과 위쪽 두 끝점이 서로 대응한다.","확인":null,"스킬":"G4"},{"제목":"대응하는 점의 짝","힌트":"뾰족한 점끼리 짝지으면 나머지 두 끝점은 어떻게 짝지어지는가?","식":["$g(-2,0)=f(2,-1)$","$g(-1,2)=f(0,0)$","$g(-3,2)=f(0,-2)$"],"설명":"$f$ 의 오른쪽을 향한 모양을 시계 방향으로 $90^\\circ$ 돌리면 $g$ 의 아래를 향한 모양이 된다. 이때 $f$ 의 위쪽 끝 $(0,0)$ 은 $g$ 의 오른쪽 끝 $(-1,2)$ 로, 아래쪽 끝 $(0,-2)$ 는 왼쪽 끝 $(-3,2)$ 로 옮겨진다.","확인":null,"스킬":"G4","고비":true},{"제목":"$g(x,y)=f(u,v)$ 의 두 인수","힌트":"$u=ax+by+c$ 로 놓고 세 대응에서 $a$, $b$, $c$ 를 구하면?","식":["$u$: $-2a+c=2,\\ -a+2b+c=0,\\ -3a+2b+c=0\\ \\Rightarrow\\ u=-y+2$","$v$: $-2a+c=-1,\\ -a+2b+c=0,\\ -3a+2b+c=-2\\ \\Rightarrow\\ v=x+1$"],"설명":"$u$ 는 세 점에서 $2,\\ 0,\\ 0$, $v$ 는 $-1,\\ 0,\\ -2$ 의 값을 가진다. 둘째와 셋째 식을 빼면 $a$ 가 먼저 정해지고 나머지가 차례로 정해진다.","확인":null,"스킬":"A3"},{"제목":"선지와 맞추기","힌트":"구한 두 인수와 같은 꼴의 선지는 몇 번인가?","식":["$g(x,y)=f(-y+2,\\ x+1)$"],"설명":"구한 두 인수 $-y+2$, $x+1$ 이 선지 ① 과 같다. 나머지 선지는 $g(-2,0)$ 또는 $g(-1,2)$ 를 대입하면 $f$ 의 꼭짓점과 어긋난다.","확인":null,"스킬":"G4"}]},"ns-e88902d66614":{"길":"$|y|=f(|x|)$ 의 그래프를 그리고 반지름에 따른 교점 수를 구간별로 센다","단계":[{"제목":"$|y|=f(|x|)$ 의 그래프 그리기","힌트":"$f(|x|)\\ge0$ 이어야 하므로 $t=|x|$ 일 때 $f(t)\\ge0$ 인 $t$ 의 범위는?","식":["$0\\le|x|\\le1$ 일 때 $|y|=1-|x|$","$|x|\\ge3$ 일 때 $|y|=|x|-3$"],"설명":"$|y|\\ge0$ 이므로 $f(|x|)\\ge0$ 인 부분에만 그래프가 생긴다. 그림에서 $f(t)\\ge0$ 은 $0\\le t\\le1$ 과 $t\\ge3$ 이고, $1<|x|<3$ 에는 그래프가 없다.","확인":null,"스킬":"G5"},{"제목":"마름모 부분과 원의 교점 수","힌트":"원점에서 마름모의 변까지의 거리와 꼭짓점까지의 거리에 따라 교점은 몇 개인가?","식":["$r=\\dfrac{\\sqrt2}{2}$ 일 때 $4$개","$\\dfrac{\\sqrt2}{2}<r<1$ 일 때 $8$개","$r=1$ 일 때 $4$개"],"설명":"마름모 $|x|+|y|=1$ 의 변까지의 거리는 $\\dfrac{1}{\\sqrt2}=\\dfrac{\\sqrt2}{2}$ 이고 꼭짓점까지의 거리는 $1$ 이다. 이 범위 밖의 $r$ 에서는 원과 마름모가 만나지 않는다.","확인":null,"스킬":"S5"},{"제목":"바깥쪽 꺾은선과 원의 교점 수","힌트":"반직선 $y=x-3$ ($x\\ge3$) 위에서 원점과 가장 가까운 점은 어디이고, 반지름이 커지면 교점은 몇 개가 되는가?","식":["$r<3$ 일 때 $0$개","$r=3$ 일 때 $2$개","$r>3$ 일 때 $4$개"],"설명":"직선 $y=x-3$ 에서 원점과 가장 가까운 점 $(1.5,\\ -1.5)$ 는 반직선 밖에 있으므로, 반직선에서 가장 가까운 점은 끝점 $(3,0)$ 이다. 반지름이 $3$ 보다 크면 네 반직선과 한 점씩 만난다.","확인":null,"스킬":"S5","고비":true},{"제목":"교점이 4개인 정수 $r$ 의 개수","힌트":"두 결과를 합쳐 $0<r<7$ 에서 교점이 $4$개가 되는 정수 $r$ 은 몇 개인가?","식":["$r=\\dfrac{\\sqrt2}{2},\\ \\ 1,\\ \\ r>3$","정수 $r=1,\\ 4,\\ 5,\\ 6$"],"설명":"$r=2$ 는 교점이 없고 $r=3$ 은 교점이 $2$개이므로 제외한다. 조건에 맞는 정수는 $1$ 과 $4$ 이상 $6$ 이하이다.","확인":"4","스킬":"C2"}]},"ns-e8ee73dc4dd7":{"길":"$\\mathrm{A}$ 를 직선에 대칭이동해 둘레를 바꾸고, $\\mathrm{C}$ 의 조건 때문에 경계에서 최소가 됨을 확인한다","단계":[{"제목":"직선 $y=-2x+2$ 에 대한 $\\mathrm{A}$ 의 대칭점","힌트":"$\\mathrm{A}'(p,q)$ 라 하면 $\\overline{\\mathrm{AA}'}$ 의 중점은 직선 위에 있고 $\\overline{\\mathrm{AA}'}$ 의 기울기는 얼마인가?","식":["$2p+q=-4,\\ \\ p-2q=-6$","$\\mathrm{A}'\\left(-\\dfrac{14}{5},\\ \\dfrac85\\right)$"],"설명":"중점 $\\left(\\dfrac{p+2}{2},\\ \\dfrac{q+4}{2}\\right)$ 가 직선 위에 있고, 직선의 기울기가 $-2$ 이므로 $\\overline{\\mathrm{AA}'}$ 의 기울기는 $\\dfrac12$ 이다. 두 식을 연립해 $p$, $q$ 를 구한다.","확인":null,"스킬":"G4"},{"제목":"둘레를 $\\overline{\\mathrm{A}'\\mathrm{C}}+\\overline{\\mathrm{CA}}$ 로 바꾸기","힌트":"$\\overline{\\mathrm{AB}}$ 를 $\\overline{\\mathrm{A}'\\mathrm{B}}$ 로 바꾸면 둘레는 어떤 부등식이 되는가?","식":["$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}=\\overline{\\mathrm{A}'\\mathrm{B}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}\\ge\\overline{\\mathrm{A}'\\mathrm{C}}+\\overline{\\mathrm{CA}}$"],"설명":"$\\mathrm{A}$ 와 $\\mathrm{C}$ 가 직선 $y=-2x+2$ 의 같은 쪽에 있으므로 $\\mathrm{B}$ 를 선분 $\\mathrm{A}'\\mathrm{C}$ 위에 잡을 수 있어 등호가 성립한다. 이제 $\\mathrm{C}$ 에 대한 $\\overline{\\mathrm{A}'\\mathrm{C}}+\\overline{\\mathrm{CA}}$ 의 최솟값을 구하면 된다.","확인":null,"스킬":"G4"},{"제목":"$\\mathrm{C}$ 의 $x$ 좌표 조건과 최소가 되는 위치","힌트":"$\\mathrm{A}$ 를 $x$축에 대칭이동한 $\\mathrm{A}''(2,-4)$ 를 쓰면, 직선 $\\mathrm{A}'\\mathrm{A}''$ 이 $x$축과 만나는 점의 $x$ 좌표는?","식":["직선 $\\mathrm{A}'\\mathrm{A}''$ 의 기울기 $-\\dfrac76$","$x$축과 만나는 점의 $x$ 좌표 $-\\dfrac{10}{7}<2$"],"설명":"조건 없이 최소가 되는 점은 $x=-\\dfrac{10}{7}$ 인데 이는 $x\\ge2$ 를 만족하지 않는다. $\\overline{\\mathrm{A}'\\mathrm{C}}+\\overline{\\mathrm{CA}}$ 는 $x=-\\dfrac{10}{7}$ 에서 최소이고 그보다 오른쪽에서는 증가하므로, $x\\ge2$ 에서는 $\\mathrm{C}(2,0)$ 에서 최소이다.","확인":"-10/7","스킬":"C2","고비":true},{"제목":"$\\mathrm{C}(2,0)$ 일 때의 둘레","힌트":"$\\overline{\\mathrm{A}'\\mathrm{C}}$ 와 $\\overline{\\mathrm{CA}}$ 의 길이를 더하면?","식":["$\\overline{\\mathrm{A}'\\mathrm{C}}=\\sqrt{\\left(\\dfrac{24}{5}\\right)^2+\\left(\\dfrac85\\right)^2}=\\dfrac{8\\sqrt{10}}{5}$","$\\overline{\\mathrm{CA}}=4$","$\\dfrac{8\\sqrt{10}}{5}+4=\\dfrac{8\\sqrt{10}+20}{5}$"],"설명":"$\\mathrm{A}'$ 과 $\\mathrm{C}$ 의 $x$ 좌표 차는 $2+\\dfrac{14}{5}=\\dfrac{24}{5}$, $y$ 좌표 차는 $\\dfrac85$ 이다. $\\overline{\\mathrm{CA}}$ 는 $x$ 좌표가 같아 $y$ 좌표 차 $4$ 와 같다.","확인":null,"스킬":"S3"},{"제목":"$a+b$ 의 값","힌트":"$\\dfrac{a\\sqrt{10}+b}{5}$ 와 비교하면 $a$, $b$ 는?","식":["$a=8,\\ \\ b=20$","$a+b=28$"],"설명":"$\\dfrac{8\\sqrt{10}+20}{5}$ 과 식의 꼴이 같으므로 $a$, $b$ 가 정해진다.","확인":"28","스킬":"G4"}]},"ns-f0b4673e961a":{"길":"$\\mathrm{A}$ 를 $y$축과 직선 $y=x$ 에 대칭이동해 둘레를 한 선분으로 편다","단계":[{"제목":"두 대칭점 구하기","힌트":"$\\mathrm{A}(2,4)$ 를 $y$축에 대칭이동하면 좌표가 어떻게 되고, 직선 $y=x$ 에 대칭이동하면 어떻게 되는가?","식":["$\\mathrm{A}'(-2,4),\\ \\mathrm{A}''(4,2)$"],"설명":"$y$축에 대칭이동한 점을 $\\mathrm{A}'$, 직선 $y=x$ 에 대칭이동한 점을 $\\mathrm{A}''$ 이라 한다. $y$축에 대칭이면 $x$ 좌표의 부호가 바뀌고, $y=x$ 에 대칭이면 $x$ 좌표와 $y$ 좌표가 서로 바뀐다.","확인":null,"스킬":"G4","고비":true},{"제목":"둘레를 한 선분으로 펴기","힌트":"$\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{CA}}$ 를 대칭점으로 바꾸면 둘레는 어떤 꺾인 길이 되는가?","식":["$\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}}=\\overline{\\mathrm{A}'\\mathrm{B}}+\\overline{\\mathrm{BC}}+\\overline{\\mathrm{CA}''}\\ge\\overline{\\mathrm{A}'\\mathrm{A}''}$"],"설명":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{A}'\\mathrm{B}}$, $\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CA}''}$ 이다. 직선 $\\mathrm{A}'\\mathrm{A}''$ 이 $y$축과 $\\left(0,\\dfrac{10}{3}\\right)$, 직선 $y=x$ 와 $\\left(\\dfrac52,\\dfrac52\\right)$ 에서 선분 위로 만나므로 등호가 성립한다.","확인":null,"스킬":"G4"},{"제목":"두 대칭점 사이의 거리","힌트":"$\\mathrm{A}'(-2,4)$ 와 $\\mathrm{A}''(4,2)$ 사이의 거리는?","식":["$\\overline{\\mathrm{A}'\\mathrm{A}''}=\\sqrt{(4+2)^2+(2-4)^2}=\\sqrt{40}=2\\sqrt{10}$"],"설명":"두 점의 좌표 차로 거리 공식을 쓰면 둘레의 최솟값이 정해진다.","확인":null,"스킬":"S3"}]},"ns-f6d91c25e6a4":{"길":"그림 1 의 꼭짓점이 옮겨진 곳으로 점의 이동 규칙을 만든 뒤 식을 거꾸로 푼다","단계":[{"제목":"그림 1 의 꼭짓점 문자로 놓기","힌트":"그림 1 의 직각삼각형의 세 꼭짓점을 $a$, $b$ 로 나타내면?","식":["$(0,b),\\ (a,b),\\ (a,0)$"],"설명":"그림 1 은 위쪽 변이 수평이고 오른쪽 변이 수직인 직각삼각형이다. 직각 꼭짓점은 $(a,b)$ 이다.","확인":null,"스킬":"G4"},{"제목":"그림 2 에서 대응하는 꼭짓점","힌트":"그림 2 에서 $y$축 위의 꼭짓점, 높이가 $1$ 인 꼭짓점, 직각 꼭짓점은 각각 그림 1 의 어느 꼭짓점이 옮겨진 것인가?","식":["$(a,0)\\to(0,\\ a+1)$","$(0,b)\\to(-b,\\ 1)$","$(a,b)\\to(-b,\\ a+1)$"],"설명":"그림 1 의 수평 변은 그림 2 에서 수직 변이 되고, 수직 변은 수평 변이 된다. 그림 2 의 직각 꼭짓점은 왼쪽 위이고 $y$축 위의 꼭짓점이 그 오른쪽에 있다.","확인":null,"스킬":"G4"},{"제목":"점의 이동 규칙","힌트":"세 대응에서 $x$ 좌표와 $y$ 좌표는 각각 어떤 꼴로 바뀌는가?","식":["$(x,y)\\to(-y,\\ x+1)$"],"설명":"세 대응 모두 새 $x$ 좌표는 원래 $y$ 좌표의 부호를 바꾼 값이고 새 $y$ 좌표는 원래 $x$ 좌표에 $1$ 을 더한 값이다.","확인":null,"스킬":"G4","고비":true},{"제목":"그림 2 의 도형의 방정식","힌트":"그림 2 위의 점 $(X,Y)$ 에 대응하는 원래 점 $(x,y)$ 를 $X$, $Y$ 로 나타내면?","식":["$X=-y,\\ \\ Y=x+1\\ \\Rightarrow\\ x=Y-1,\\ \\ y=-X$","$f(y-1,\\ -x)=0$"],"설명":"원래 점 $(x,y)=(Y-1,\\ -X)$ 가 $f(x,y)=0$ 위에 있으므로 문자를 바꿔 쓰면 $f(y-1,\\ -x)=0$ 이다. 이 꼴은 선지 ② 이다.","확인":null,"스킬":"G4"}]},"ns-f709acee4ac9":{"길":"출발점은 변 $\\mathrm{AB}$ 에, 도착점은 변 $\\mathrm{BC}$ 에 대칭이동해 경로를 한 직선으로 편다","단계":[{"제목":"좌표 설정","힌트":"$\\mathrm{B}$ 를 원점으로 놓으면 $\\mathrm{E}$, $\\mathrm{F}$ 의 좌표는?","식":["$\\mathrm{B}(0,0),\\ \\mathrm{A}(0,6),\\ \\mathrm{C}(10,0),\\ \\mathrm{D}(10,6)$","$\\mathrm{E}(5,6),\\ \\mathrm{F}(10,2)$"],"설명":"$\\mathrm{E}$ 는 변 $\\mathrm{AD}$ 의 중점이다. $\\mathrm{F}$ 는 변 $\\mathrm{CD}$ 를 $1:2$ 로 내분하므로 $\\mathrm{C}$ 에서 위로 $6\\times\\dfrac13$ 만큼 떨어져 있다.","확인":null,"스킬":"S4"},{"제목":"두 점의 대칭이동","힌트":"먼저 부딪히는 변 $\\mathrm{AB}$ 에 대해 $\\mathrm{E}$ 를, 나중에 부딪히는 변 $\\mathrm{BC}$ 에 대해 $\\mathrm{F}$ 를 대칭이동하면?","식":["$\\mathrm{E}'(-5,6),\\ \\mathrm{F}'(10,-2)$"],"설명":"변 $\\mathrm{AB}$ 는 $x=0$ 이고 변 $\\mathrm{BC}$ 는 $y=0$ 이다. 반사하는 경로가 $\\mathrm{E}'$ 에서 $\\mathrm{F}'$ 로 가는 직선으로 펴진다.","확인":null,"스킬":"G4","고비":true},{"제목":"최단 거리","힌트":"두 점 $(-5,6)$, $(10,-2)$ 사이의 거리는?","식":["$\\overline{\\mathrm{E}'\\mathrm{F}'}=\\sqrt{(10+5)^2+(-2-6)^2}=\\sqrt{225+64}=17$"],"설명":"직선 $\\mathrm{E}'\\mathrm{F}'$ 이 변 $\\mathrm{AB}$ 위의 점 $\\left(0,\\dfrac{10}{3}\\right)$ 과 변 $\\mathrm{BC}$ 위의 점 $\\left(\\dfrac{25}{4},0\\right)$ 을 지나므로 실제 경로로 쓸 수 있다.","확인":"17","스킬":"S3"}]},"ns-fa3101ca26bc":{"길":"두 삼각형의 대칭을 이용해 공통부분의 꼭짓점을 잡고 넓이를 구한다","단계":[{"제목":"대칭이동한 점 $\\mathrm{C}$, $\\mathrm{D}$ 의 좌표","힌트":"직선 $y=x$ 에 대한 대칭이동은 점의 좌표를 어떻게 바꾸는가?","식":["$\\mathrm{C}(0,2),\\ \\mathrm{D}(2,1)$"],"설명":"직선 $y=x$ 에 대하여 대칭이동하면 점 $(a,b)$ 가 $(b,a)$ 로 옮겨진다. 따라서 $\\mathrm{A}(2,0)$ 은 $\\mathrm{C}(0,2)$ 로, $\\mathrm{B}(1,2)$ 는 $\\mathrm{D}(2,1)$ 로 옮겨진다.","확인":null,"스킬":"G4"},{"제목":"공통부분의 꼭짓점 좌표","힌트":"공통부분의 경계가 되는 네 변의 직선 식을 세우면 어느 두 직선끼리 만나서 꼭짓점이 생기는가?","식":["$\\mathrm{OB}:y=2x,\\ \\mathrm{OD}:y=\\dfrac12x,\\ \\mathrm{AB}:y=-2x+4,\\ \\mathrm{CD}:y=-\\dfrac12x+2$","$\\left(\\dfrac45,\\dfrac85\\right),\\ \\left(\\dfrac43,\\dfrac43\\right),\\ \\left(\\dfrac85,\\dfrac45\\right)$"],"설명":"공통부분은 점 $\\mathrm{O}$ 와 세 교점을 꼭짓점으로 하는 사각형이다. 직선 $\\mathrm{OB}$ 와 $\\mathrm{CD}$ 의 교점이 $\\left(\\dfrac45,\\dfrac85\\right)$, 직선 $\\mathrm{AB}$ 와 $\\mathrm{CD}$ 의 교점이 $\\left(\\dfrac43,\\dfrac43\\right)$, 직선 $\\mathrm{OD}$ 와 $\\mathrm{AB}$ 의 교점이 $\\left(\\dfrac85,\\dfrac45\\right)$ 이다.","확인":null,"스킬":"G1","고비":true},{"제목":"공통부분의 넓이 $S$","힌트":"두 삼각형이 $y=x$ 에 대하여 대칭이므로 공통부분을 어떻게 나누어 구하면 편한가?","식":["$\\dfrac12\\left|\\dfrac85\\cdot\\dfrac43-\\dfrac43\\cdot\\dfrac45\\right|=\\dfrac{8}{15}$","$S=2\\times\\dfrac{8}{15}=\\dfrac{16}{15}$"],"설명":"두 삼각형이 $y=x$ 에 대하여 대칭이므로 공통부분도 대칭이다. 직선 $y=x$ 아래쪽 부분은 세 점 $\\mathrm{O}(0,0)$, $\\left(\\dfrac85,\\dfrac45\\right)$, $\\left(\\dfrac43,\\dfrac43\\right)$ 을 꼭짓점으로 하는 삼각형이고, 이 넓이의 $2$ 배가 $S$ 이다.","확인":"16/15","스킬":"G10"},{"제목":"$15S$ 의 값","힌트":"$S$ 에 $15$ 를 곱하면 얼마인가?","식":["$15S=15\\times\\dfrac{16}{15}=16$"],"설명":"$S=\\dfrac{16}{15}$ 이므로 $15S=16$ 이고, 이 값은 선지 ② 이다.","확인":"16","스킬":"G10"}]},"ns-fc6087bb779c":{"길":"점 P 를 두 직선에 대칭이동해 꺾인 둘레를 한 선분으로 펴 본다","단계":[{"제목":"둘레의 길이를 한 선분의 길이로 바꾸기","힌트":"점 $\\mathrm{P}$ 를 $x$축과 직선 $y=2x$ 에 대하여 각각 대칭이동하면 $\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{PR}}$ 은 어느 선분으로 바뀌는가?","식":["$\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{P}''\\mathrm{Q}},\\ \\overline{\\mathrm{PR}}=\\overline{\\mathrm{P}\\,'\\mathrm{R}}$","$\\overline{\\mathrm{P}''\\mathrm{Q}}+\\overline{\\mathrm{QR}}+\\overline{\\mathrm{RP}\\,'}\\ge\\overline{\\mathrm{P}\\,'\\mathrm{P}''}$","$\\mathrm{P}''(3,-1)$"],"설명":"점 $\\mathrm{P}$ 를 직선 $y=2x$ 에 대하여 대칭이동한 점을 $\\mathrm{P}\\,'$, $x$축에 대하여 대칭이동한 점을 $\\mathrm{P}''$ 라 하면 $\\overline{\\mathrm{PR}}=\\overline{\\mathrm{P}\\,'\\mathrm{R}}$, $\\overline{\\mathrm{PQ}}=\\overline{\\mathrm{P}''\\mathrm{Q}}$ 이다. 따라서 둘레의 길이는 $\\mathrm{P}\\,'$, $\\mathrm{R}$, $\\mathrm{Q}$, $\\mathrm{P}''$ 를 잇는 꺾인 선의 길이이고, $\\mathrm{R}$, $\\mathrm{Q}$ 가 $\\overline{\\mathrm{P}\\,'\\mathrm{P}''}$ 위에 있을 때 가장 짧다. $x$축 대칭이므로 $\\mathrm{P}''$ 의 좌표는 $(3,-1)$ 이다.","확인":null,"스킬":"S14"},{"제목":"직선 $y=2x$ 에 대한 $\\mathrm{P}$ 의 대칭점 $\\mathrm{P}\\,'$","힌트":"$\\mathrm{P}\\,'(a,b)$ 라 두면 선분 $\\mathrm{PP}\\,'$ 의 중점과 기울기는 어떤 조건을 만족하는가?","식":["$\\dfrac{b+1}{2}=2\\cdot\\dfrac{a+3}{2},\\ \\dfrac{b-1}{a-3}=-\\dfrac12$","$\\mathrm{P}\\,'(-1,3)$"],"설명":"$\\overline{\\mathrm{PP}\\,'}$ 의 중점이 직선 $y=2x$ 위에 있고, $\\overline{\\mathrm{PP}\\,'}$ 은 이 직선과 수직이므로 기울기가 $-\\dfrac12$ 이다. 두 식을 연립하면 $a=-1$, $b=3$ 이다.","확인":null,"스킬":"G4","고비":true},{"제목":"둘레의 길이의 최솟값 $\\overline{\\mathrm{P}\\,'\\mathrm{P}''}$","힌트":"두 점 $(-1,3)$, $(3,-1)$ 사이의 거리는 얼마인가?","식":["$\\overline{\\mathrm{P}\\,'\\mathrm{P}''}=\\sqrt{(3+1)^2+(-1-3)^2}=4\\sqrt2$"],"설명":"두 점 사이의 거리 공식을 쓰면 $\\sqrt{16+16}=4\\sqrt2$ 이다. 따라서 둘레의 길이의 최솟값은 $4\\sqrt2$ 이다.","확인":null,"스킬":"S14"}]},"ns-0101a94020bb":{"길":"조건제시법으로 된 집합을 원소나열법으로 바꿔 비교한다","단계":[{"제목":"집합 $B$ 의 원소 나열과 원소의 개수","힌트":"$x$, $y$ 에 $A$ 의 원소를 넣어 $x+y$ 로 가능한 값을 모두 적으면 원소는 몇 개인가?","식":["$B=\\{0,1,2,3,4\\}$"],"설명":"$x$, $y$ 가 각각 $0,1,2$ 중 하나이므로 합은 $0$ 부터 $4$ 까지의 정수가 모두 나온다. 예를 들어 $3=1+2$, $4=2+2$ 이다.","확인":"5","스킬":"C6","고비":true},{"제목":"집합 $C$ 의 원소 나열","힌트":"$|x|<1$ 을 만족하는 정수는 무엇인가?","식":["$-1<x<1$","$C=\\{0\\}$"],"설명":"$|x|<1$ 은 $-1<x<1$ 과 같다. 이 범위에 있는 정수는 $0$ 하나뿐이다.","확인":"0","스킬":"C6"},{"제목":"세 집합의 포함 관계","힌트":"$C$, $A$, $B$ 의 원소를 비교하면 어느 집합이 어느 집합에 들어가는가?","식":["$C=\\{0\\}\\subset A=\\{0,1,2\\}\\subset B=\\{0,1,2,3,4\\}$"],"설명":"$C$ 의 원소 $0$ 은 $A$ 에 있고, $A$ 의 원소 $0,1,2$ 는 모두 $B$ 에 있다. 반대 방향은 성립하지 않으므로 $C\\subset A\\subset B$ 이다.","확인":null,"스킬":"C6"}]},"ns-02799f901a11":{"길":"합을 정리해 해를 구한 뒤 정수 조건으로 각 보기를 판정한다","단계":[{"제목":"$f_1(x)+\\cdots+f_p(x)$ 의 정리","힌트":"$x(x-k)$ 를 $k=1$ 부터 $p$ 까지 더하면 $x^2$ 항과 $x$ 항은 각각 어떻게 되는가?","식":["$\\displaystyle\\sum_{k=1}^{p}x(x-k)=px^2-\\dfrac{p(p+1)}{2}x$","$px\\left(x-\\dfrac{p+1}{2}\\right)=0$"],"설명":"$x^2$ 항은 $p$ 번 더해져 $px^2$ 이 되고, $x$ 항의 계수는 $-(1+2+\\cdots+p)=-\\dfrac{p(p+1)}{2}$ 이다.","확인":null,"스킬":"P6"},{"제목":"집합 $\\mathrm{A}_p$ 의 원소와 정수 조건","힌트":"해 $x=\\dfrac{p+1}{2}$ 이 정수가 되려면 $p$ 는 어떤 수여야 하는가?","식":["$x=0$ 또는 $x=\\dfrac{p+1}{2}$","$p$ 가 홀수: $\\mathrm{A}_p=\\left\\{0,\\dfrac{p+1}{2}\\right\\}$","$p$ 가 짝수: $\\mathrm{A}_p=\\{0\\}$"],"설명":"$p$ 는 자연수이므로 방정식의 해는 $0$ 과 $\\dfrac{p+1}{2}$ 이다. $\\dfrac{p+1}{2}$ 은 $p+1$ 이 짝수일 때, 즉 $p$ 가 홀수일 때만 정수이다.","확인":null,"스킬":"N5","고비":true},{"제목":"ㄱ 의 판별, $\\mathrm{A}_4$ 의 원소의 개수","힌트":"$p=4$ 는 짝수이므로 $\\mathrm{A}_4$ 의 원소는 무엇인가?","식":["$\\mathrm{A}_4=\\{0\\}$"],"설명":"$p=4$ 이면 $\\dfrac{p+1}{2}=\\dfrac52$ 로 정수가 아니므로 원소는 $0$ 하나뿐이다. 원소가 $3$개라는 ㄱ 은 거짓이다.","확인":"1","스킬":"C3"},{"제목":"ㄴ 의 판별, 합집합의 원소의 합","힌트":"$p=8,9,10$ 중 정수 해가 하나 더 생기는 것은 어느 것이고 그 값은 얼마인가?","식":["$\\mathrm{A}_8=\\{0\\},\\ \\mathrm{A}_9=\\{0,5\\},\\ \\mathrm{A}_{10}=\\{0\\}$","$\\mathrm{A}_8\\cup\\mathrm{A}_9\\cup\\mathrm{A}_{10}=\\{0,5\\}$"],"설명":"$p=9$ 만 홀수이고 $\\dfrac{9+1}{2}=5$ 이다. 합집합의 원소는 $0$, $5$ 이므로 모든 원소의 합은 $5$ 이다. 합이 $10$ 이라는 ㄴ 은 거짓이다.","확인":"5","스킬":"C3"},{"제목":"ㄷ 의 판별, $0$ 이 모든 $\\mathrm{A}_p$ 의 원소인지","힌트":"$x=0$ 은 어떤 자연수 $p$ 에서도 방정식의 해인가?","식":["$px\\left(x-\\dfrac{p+1}{2}\\right)=0$ 에 $x=0$ 대입","$0\\in\\mathrm{A}_i\\cap\\mathrm{A}_j$"],"설명":"$x=0$ 은 모든 자연수 $p$ 에서 방정식의 해이고 정수이므로 $0\\in\\mathrm{A}_p$ 이다. 따라서 서로 다른 $i,\\ j$ 에 대하여 $0\\in\\mathrm{A}_i\\cap\\mathrm{A}_j$ 이고 ㄷ 은 참이다. 옳은 것은 ㄷ 뿐이다.","확인":null,"스킬":"C3"}]},"ns-02a299a53c56":{"길":"색칠한 부분을 집합식으로 읽고 선지마다 그 안에 들어가는지 본다","단계":[{"제목":"색칠한 부분을 집합식으로 나타내기","힌트":"색칠한 부분은 $\\mathrm{A}$ 의 어느 부분과 $\\mathrm{B}$, $\\mathrm{C}$ 의 어느 부분으로 이루어져 있는가?","식":["(색칠한 부분) $=\\{\\mathrm{A}-(\\mathrm{B}\\cup\\mathrm{C})\\}\\cup(\\mathrm{B}\\cap\\mathrm{C})$"],"설명":"위쪽의 $\\mathrm{A}$ 만의 영역은 $\\mathrm{A}$ 에서 $\\mathrm{B}$, $\\mathrm{C}$ 를 모두 뺀 부분이다. 아래쪽의 $\\mathrm{B}$ 와 $\\mathrm{C}$ 가 겹치는 부분은 $\\mathrm{B}\\cap\\mathrm{C}$ 전체이다. 이 두 부분의 합집합이 색칠한 부분이다.","확인":null,"스킬":"C4","고비":true},{"제목":"①, ②, ④, ⑤ 가 나타내는 영역","힌트":"각 선지를 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 의 영역으로 풀어 쓰면 무엇인가?","식":["$(\\mathrm{A}-\\mathrm{B})\\cap(\\mathrm{A}-\\mathrm{C})=\\mathrm{A}-(\\mathrm{B}\\cup\\mathrm{C})$","$(\\mathrm{A}\\cap\\mathrm{C})-\\mathrm{C}=\\varnothing$","$(\\mathrm{B}\\cap\\mathrm{C})-\\mathrm{A}\\subset\\mathrm{B}\\cap\\mathrm{C}$","$(\\mathrm{A}-\\mathrm{B})-\\mathrm{C}=\\mathrm{A}-(\\mathrm{B}\\cup\\mathrm{C})$"],"설명":"①, ⑤ 는 $\\mathrm{A}$ 에서 $\\mathrm{B}$, $\\mathrm{C}$ 를 모두 뺀 영역이므로 색칠한 부분에 들어간다. ② 는 공집합이고 공집합은 모든 집합의 부분집합이다. ④ 는 $\\mathrm{B}\\cap\\mathrm{C}$ 의 일부이므로 색칠한 부분에 들어간다.","확인":null,"스킬":"C4"},{"제목":"부분집합이 아닌 선지 ③","힌트":"$(\\mathrm{A}\\cap\\mathrm{B})-\\mathrm{C}$ 는 그림의 어느 영역이고 색칠되어 있는가?","식":["$(\\mathrm{A}\\cap\\mathrm{B})-\\mathrm{C}\\not\\subset\\{\\mathrm{A}-(\\mathrm{B}\\cup\\mathrm{C})\\}\\cup(\\mathrm{B}\\cap\\mathrm{C})$"],"설명":"$(\\mathrm{A}\\cap\\mathrm{B})-\\mathrm{C}$ 는 $\\mathrm{A}$ 와 $\\mathrm{B}$ 가 겹치는 부분 중 $\\mathrm{C}$ 밖의 영역이다. 이 영역은 그림에서 색칠되어 있지 않으므로 색칠한 부분의 부분집합이 아니다. 따라서 옳지 않은 것은 ③ 이다.","확인":null,"스킬":"C4"}]},"ns-06b5eb60d1fc":{"길":"세 집합의 합집합 공식에서 삼중 교집합을 문자로 두고 범위를 잡는다","단계":[{"제목":"적어도 한 과목을 선택한 학생 수","힌트":"전체 $80$ 명에서 아무 과목도 선택하지 않은 학생 수를 빼면 몇 명인가?","식":["$n(A\\cup B\\cup C)=80-5=75$"],"설명":"$n\\left((A\\cup B\\cup C)^{C}\\right)=5$ 는 세 과목을 모두 선택하지 않은 학생 수이다. 나머지 학생은 적어도 한 과목을 선택했다.","확인":"75","스킬":"C4"},{"제목":"$n(B\\cap C)$ 와 $n(A\\cap B\\cap C)$ 의 관계","힌트":"합집합의 원소의 개수 공식에 주어진 값을 넣으면 $n(B\\cap C)-n(A\\cap B\\cap C)$ 는 얼마인가?","식":["$75=36+37+31-12-14-n(B\\cap C)+n(A\\cap B\\cap C)$","$n(B\\cap C)-n(A\\cap B\\cap C)=3$"],"설명":"$n(A\\cup B\\cup C)=n(A)+n(B)+n(C)-n(A\\cap B)-n(B\\cap C)-n(A\\cap C)+n(A\\cap B\\cap C)$ 이다. 값을 넣어 정리하면 $75=78-\\{n(B\\cap C)-n(A\\cap B\\cap C)\\}$ 이다.","확인":"3","스킬":"C10"},{"제목":"두 과목 이상 선택한 학생 수를 $t$ 로 나타내기","힌트":"세 교집합의 개수를 더하면 $A\\cap B\\cap C$ 는 몇 번 세어지는가?","식":["$t=n(A\\cap B\\cap C)$ 일 때 $n(B\\cap C)=t+3$","$12+14+(t+3)-2t=29-t$"],"설명":"두 과목 이상 선택한 학생은 $A\\cap B$, $A\\cap C$, $B\\cap C$ 의 합집합이다. 세 교집합의 개수를 더하면 $A\\cap B\\cap C$ 가 $3$ 번 세어지므로 $2t$ 를 빼야 한다. $n(B\\cap C)=t+3$ 을 대입하면 $29-t$ 이다.","확인":null,"스킬":"A10"},{"제목":"$t$ 의 최댓값","힌트":"$A\\cap B\\cap C$ 는 $A\\cap B$ 의 부분집합이므로 $t$ 는 얼마까지 클 수 있는가?","식":["$t\\le n(A\\cap B)=12$","$t=12$ 일 때 모든 영역의 학생 수가 $0$ 이상"],"설명":"$A\\cap B\\cap C\\subset A\\cap B$ 이므로 $t\\le12$ 이다. $t=12$ 이면 $A\\cap B$ 에만 속하는 영역이 $0$ 명이고 나머지 영역도 모두 $0$ 명 이상이므로 가능하다.","확인":"12","스킬":"C10","고비":true},{"제목":"두 과목 이상 선택한 학생 수의 최솟값","힌트":"$29-t$ 가 가장 작아지려면 $t$ 는 어떤 값이어야 하는가?","식":["$29-12=17$"],"설명":"$29-t$ 는 $t$ 가 클수록 작아지므로 $t=12$ 일 때 최솟값 $17$ 을 갖는다.","확인":"17","스킬":"C4"}]},"ns-08201fec0955":{"길":"20 미만의 소수를 나열해 선지의 원소가 들어 있는지 따진다","단계":[{"제목":"집합 $A$ 의 원소 나열과 원소의 개수","힌트":"$20$ 미만의 소수를 모두 적으면 몇 개인가?","식":["$A=\\{2,3,5,7,11,13,17,19\\}$"],"설명":"소수는 약수가 $1$ 과 자기 자신뿐인 $2$ 이상의 자연수이다. $20$ 미만에서 이런 수는 모두 $8$ 개이다.","확인":"8","스킬":"C4"},{"제목":"옳지 않은 선지 찾기","힌트":"각 선지의 수가 $A$ 에 들어 있는지 비교하면 어느 것이 어긋나는가?","식":["$2\\in A,\\ 3\\in A,\\ 6\\notin A,\\ 15\\notin A$","$\\varnothing\\subset A$"],"설명":"$2$, $3$ 은 $A$ 의 원소이고 $15=3\\times5$ 는 소수가 아니므로 $15\\notin A$ 이다. 공집합은 모든 집합의 부분집합이다. $6=2\\times3$ 은 소수가 아니므로 $6\\in A$ 는 옳지 않다.","확인":null,"스킬":"C4","고비":true}]},"ns-09df030811fa":{"길":"최소 원소가 되는 원소별로 부분집합의 개수를 세어 더한다","단계":[{"제목":"최소 원소가 $\\dfrac{1}{4^3}$ 인 부분집합의 개수","힌트":"$\\dfrac{1}{4^3}$ 이 최소 원소가 되려면 이보다 큰 원소 $1$, $\\dfrac14$, $\\dfrac{1}{4^2}$ 은 각각 넣을지 말지를 정하면 몇 가지인가?","식":["$2^3=8$"],"설명":"$\\dfrac{1}{4^3}$ 을 반드시 넣고, 이보다 작은 원소 $\\dfrac{1}{4^4}$ 은 넣지 않는다. 이보다 큰 원소 세 개는 넣거나 넣지 않거나 자유이므로 $2^3$ 가지이다. 일반적으로 $\\dfrac{1}{4^k}$ 이 최소 원소인 부분집합은 $2^k$ 개이다.","확인":"8","스킬":"P4","고비":true},{"제목":"원소별 최소 원소의 합","힌트":"$\\dfrac{1}{4^k}$ 이 최소 원소인 부분집합이 $2^k$ 개이면 그 합에 더해지는 양은 얼마인가?","식":["$2^k\\cdot\\dfrac{1}{4^k}=\\left(\\dfrac12\\right)^k$","$1+\\dfrac12+\\dfrac14+\\dfrac18+\\dfrac1{16}$"],"설명":"$k=0,1,2,3,4$ 에 대하여 각각 $2^k$ 개의 부분집합에서 최소 원소 $\\dfrac{1}{4^k}$ 이 뽑힌다. 이를 모두 더하면 첫째항 $1$, 공비 $\\dfrac12$ 인 등비수열의 합이 된다.","확인":null,"스킬":"P1"},{"제목":"뽑은 원소들의 합","힌트":"공비가 $\\dfrac12$ 인 다섯 항의 합은 얼마인가?","식":["$\\dfrac{16}{16}+\\dfrac{8}{16}+\\dfrac{4}{16}+\\dfrac{2}{16}+\\dfrac{1}{16}=\\dfrac{31}{16}$"],"설명":"분모를 $16$ 으로 통분하면 분자의 합이 $31$ 이다. 따라서 구하는 값은 $\\dfrac{31}{16}$ 이다.","확인":"31/16","스킬":"P1"}]},"ns-0b8aa8dd602b":{"길":"연산 △ 의 뜻에 맞게 ㄱㄴㄷ 을 반례와 정리로 판정한다","단계":[{"제목":"ㄱ 의 반례","힌트":"$\\mathrm{A}\\triangle\\mathrm{B}=\\mathrm{B}$ 이면서 $\\mathrm{B}\\ne\\varnothing$ 인 두 집합이 있는가?","식":["$\\mathrm{A}=\\varnothing,\\ \\mathrm{B}=\\{1\\}$ 이면 $\\mathrm{A}\\triangle\\mathrm{B}=\\{1\\}=\\mathrm{B}$"],"설명":"$\\mathrm{A}=\\varnothing$ 이면 $\\mathrm{A}-\\mathrm{B}=\\varnothing$, $\\mathrm{B}-\\mathrm{A}=\\mathrm{B}$ 이므로 $\\mathrm{A}\\triangle\\mathrm{B}=\\mathrm{B}$ 이다. 이때 $\\mathrm{B}$ 는 공집합이 아니어도 되므로 ㄱ 은 거짓이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 의 판별, $\\mathrm{C}\\triangle\\mathrm{D}$ 의 원소의 개수","힌트":"순허수는 $b=0$ 인 경우를 포함하는가? $\\mathrm{C}$ 와 $\\mathrm{D}$ 중 한쪽에만 속하는 수는 무엇인가?","식":["$\\mathrm{C}=\\{bi\\,|\\,b\\ne0\\}$","$\\mathrm{D}=\\{bi\\,|\\,b\\text{는 실수}\\}$","$\\mathrm{C}\\triangle\\mathrm{D}=\\{0\\}$"],"설명":"순허수는 실수부분이 $0$ 이고 허수부분이 $0$ 이 아닌 수이므로 $\\mathrm{C}$ 에 $0$ 은 없다. $\\mathrm{D}$ 는 $b=0$ 도 허용하므로 $0$ 을 원소로 가진다. 따라서 $\\mathrm{C}\\triangle\\mathrm{D}=\\{0\\}\\ne\\varnothing$ 이고 ㄴ 은 거짓이다.","확인":"1","스킬":"A5","고비":true},{"제목":"ㄷ 의 판별, 서로소인 두 집합","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 가 서로소이면 $\\mathrm{A}-\\mathrm{B}$ 와 $\\mathrm{B}-\\mathrm{A}$ 는 각각 무엇인가?","식":["$\\mathrm{A}-\\mathrm{B}=\\mathrm{A},\\ \\mathrm{B}-\\mathrm{A}=\\mathrm{B}$","$\\mathrm{A}\\triangle\\mathrm{B}=\\mathrm{A}\\cup\\mathrm{B}$"],"설명":"서로소이면 공통 원소가 없으므로 $\\mathrm{A}$ 에서 $\\mathrm{B}$ 를 빼도 $\\mathrm{A}$ 는 변하지 않고, $\\mathrm{B}$ 에서 $\\mathrm{A}$ 를 빼도 $\\mathrm{B}$ 는 변하지 않는다. 따라서 ㄷ 은 참이고, 옳은 것은 ㄷ 뿐이다.","확인":null,"스킬":"C3"}]},"ns-0f2d096b9fcc":{"길":"드모르간 법칙으로 합집합의 원소 수부터 구하고 합집합 공식을 쓴다","단계":[{"제목":"합집합의 원소의 개수 $n(A\\cup B)$","힌트":"$A^{C}\\cap B^{C}=(A\\cup B)^{C}$ 이므로 $n(A\\cup B)$ 는 얼마인가?","식":["$n(A\\cup B)=n(U)-n\\left((A\\cup B)^{C}\\right)=25-5=20$"],"설명":"드모르간 법칙에 의해 $A^{C}\\cap B^{C}=(A\\cup B)^{C}$ 이다. 전체 원소의 개수에서 이 부분의 원소의 개수를 빼면 $n(A\\cup B)$ 이다.","확인":"20","스킬":"C4","고비":true},{"제목":"$n(B)$ 의 값","힌트":"$n(A\\cup B)=n(A)+n(B)-n(A\\cap B)$ 에서 $n(B)$ 는 얼마인가?","식":["$n(B)=n(A\\cup B)-n(A)+n(A\\cap B)=20-10+3=13$"],"설명":"합집합의 원소의 개수 공식을 $n(B)$ 에 대하여 정리하고 앞 단계의 $20$ 과 주어진 값을 대입한다.","확인":"13","스킬":"C4"}]},"ns-0fd489bfeb10":{"길":"집합 A 의 원소를 먼저 확인하고 원소 관계와 부분집합 관계를 구분한다","단계":[{"제목":"집합 $A$ 의 원소의 개수","힌트":"$A=\\{\\varnothing,\\ 1,\\ \\{2\\}\\}$ 에서 쉼표로 구분된 원소는 몇 개인가?","식":["$A$ 의 원소: $\\varnothing,\\ 1,\\ \\{2\\}$"],"설명":"$\\varnothing$ 과 $\\{2\\}$ 는 각각 하나의 원소로 들어 있다. 따라서 $A$ 의 원소는 $\\varnothing$, $1$, $\\{2\\}$ 세 개이다.","확인":"3","스킬":"C4","고비":true},{"제목":"원소 관계 $\\in$ 로 쓴 선지 ①, ②","힌트":"$2$ 와 $\\{1\\}$ 은 $A$ 의 원소 세 개 중에 있는가?","식":["$2\\notin A$","$\\{1\\}\\notin A$"],"설명":"$A$ 의 원소는 $\\varnothing$, $1$, $\\{2\\}$ 이다. $2$ 는 원소가 아니고 $\\{2\\}$ 가 원소이다. $\\{1\\}$ 도 원소가 아니고 $1$ 이 원소이다. 따라서 ①, ② 는 거짓이다.","확인":null,"스킬":"C4"},{"제목":"부분집합 관계 $\\subset$ 로 쓴 선지 ③, ④, ⑤","힌트":"$\\{a\\}\\subset A$ 가 되려면 $a$ 는 $A$ 의 원소여야 하는가?","식":["$\\varnothing\\in A\\ \\Rightarrow\\ \\{\\varnothing\\}\\subset A$","$2\\notin A\\ \\Rightarrow\\ \\{2\\}\\not\\subset A,\\ \\{1,2\\}\\not\\subset A$"],"설명":"$\\{\\varnothing\\}$ 의 원소 $\\varnothing$ 이 $A$ 의 원소이므로 $\\{\\varnothing\\}\\subset A$ 이다. $\\{2\\}$ 의 원소 $2$ 와 $\\{1,2\\}$ 의 원소 $2$ 는 $A$ 의 원소가 아니므로 ④, ⑤ 는 거짓이다. 따라서 옳은 것은 ③ 이다.","확인":null,"스킬":"C4"}]},"ns-23b262f7669d":{"길":"대칭차의 원소 수를 교집합 크기로 나타내고 가능한 범위를 따진다","단계":[{"제목":"$n(\\mathrm{X}\\triangle\\mathrm{Y})$ 를 교집합의 크기로 나타내기","힌트":"$(\\mathrm{X}\\cup\\mathrm{Y})-(\\mathrm{X}\\cap\\mathrm{Y})$ 의 원소의 개수를 $n(\\mathrm{X})$, $n(\\mathrm{Y})$, $n(\\mathrm{X}\\cap\\mathrm{Y})$ 로 쓰면?","식":["$n(\\mathrm{X}\\cup\\mathrm{Y})=n(\\mathrm{X})+n(\\mathrm{Y})-n(\\mathrm{X}\\cap\\mathrm{Y})$","$n(\\mathrm{X}\\triangle\\mathrm{Y})=9-2n(\\mathrm{X}\\cap\\mathrm{Y})$"],"설명":"$\\mathrm{X}\\cap\\mathrm{Y}\\subset\\mathrm{X}\\cup\\mathrm{Y}$ 이므로 $n(\\mathrm{X}\\triangle\\mathrm{Y})=n(\\mathrm{X}\\cup\\mathrm{Y})-n(\\mathrm{X}\\cap\\mathrm{Y})$ 이다. 합집합 공식을 대입하고 $n(\\mathrm{X})=4$, $n(\\mathrm{Y})=5$ 를 쓰면 $9-2n(\\mathrm{X}\\cap\\mathrm{Y})$ 이다.","확인":null,"스킬":"C6"},{"제목":"$n(\\mathrm{X}\\cap\\mathrm{Y})$ 의 최솟값","힌트":"$n(\\mathrm{X}\\cup\\mathrm{Y})$ 는 전체집합의 원소의 개수를 넘을 수 있는가?","식":["$n(\\mathrm{X}\\cap\\mathrm{Y})=4+5-n(\\mathrm{X}\\cup\\mathrm{Y})\\ge4+5-6$"],"설명":"$\\mathrm{X}\\cup\\mathrm{Y}\\subset\\mathrm{U}$ 이므로 $n(\\mathrm{X}\\cup\\mathrm{Y})\\le6$ 이다. 따라서 교집합의 크기는 $3$ 이상이고, $\\mathrm{X}=\\{1,2,3,4\\}$, $\\mathrm{Y}=\\{1,3,4,5,6\\}$ 이면 $3$ 이 실제로 나온다.","확인":"3","스킬":"C2","고비":true},{"제목":"$n(\\mathrm{X}\\cap\\mathrm{Y})$ 의 최댓값","힌트":"교집합은 $\\mathrm{X}$ 보다 원소가 많을 수 있는가?","식":["$n(\\mathrm{X}\\cap\\mathrm{Y})\\le n(\\mathrm{X})=4$"],"설명":"교집합은 $\\mathrm{X}$ 의 부분집합이므로 $4$ 를 넘지 못한다. $\\mathrm{X}=\\{1,2,3,4\\}$, $\\mathrm{Y}=\\{1,2,3,4,5\\}$ 이면 $\\mathrm{X}\\subset\\mathrm{Y}$ 이므로 $4$ 가 실제로 나온다.","확인":"4","스킬":"C2"},{"제목":"$5p+3q$ 의 값","힌트":"교집합이 가장 작을 때와 가장 클 때 $9-2n(\\mathrm{X}\\cap\\mathrm{Y})$ 는 각각 얼마인가?","식":["$p=9-2\\cdot3=3,\\ q=9-2\\cdot4=1$","$5p+3q=15+3=18$"],"설명":"$n(\\mathrm{X}\\triangle\\mathrm{Y})$ 는 교집합이 작을수록 크다. 교집합이 $3$ 일 때 최댓값 $p=3$, $4$ 일 때 최솟값 $q=1$ 이다.","확인":"18","스킬":"C2"}]},"ns-2c4ad7d1e32d":{"길":"좌변을 대칭차 꼴로 정리하고 우변과 같아지는 조건을 찾는다","단계":[{"제목":"좌변의 정리","힌트":"드모르간 법칙으로 $\\mathrm{A}^{\\mathrm{c}}\\cup\\mathrm{B}^{\\mathrm{c}}$ 를 바꾸면 좌변은 어떤 집합이 되는가?","식":["$\\mathrm{A}^{\\mathrm{c}}\\cup\\mathrm{B}^{\\mathrm{c}}=(\\mathrm{A}\\cap\\mathrm{B})^{\\mathrm{c}}$","$(\\mathrm{A}\\cup\\mathrm{B})-(\\mathrm{A}\\cap\\mathrm{B})=(\\mathrm{A}-\\mathrm{B})\\cup(\\mathrm{B}-\\mathrm{A})$"],"설명":"$(\\mathrm{A}\\cup\\mathrm{B})\\cap(\\mathrm{A}\\cap\\mathrm{B})^{\\mathrm{c}}$ 은 합집합에서 교집합을 뺀 집합이다. 이것은 한쪽에만 속하는 원소의 모임이므로 $(\\mathrm{A}-\\mathrm{B})\\cup(\\mathrm{B}-\\mathrm{A})$ 이다.","확인":null,"스킬":"C4"},{"제목":"$\\mathrm{A}-\\mathrm{B}$ 와 같아질 조건","힌트":"$\\mathrm{A}-\\mathrm{B}$ 와 $\\mathrm{B}-\\mathrm{A}$ 는 공통 원소가 있는가?","식":["$(\\mathrm{A}-\\mathrm{B})\\cup(\\mathrm{B}-\\mathrm{A})=\\mathrm{A}-\\mathrm{B}\\iff\\mathrm{B}-\\mathrm{A}=\\varnothing$"],"설명":"$\\mathrm{A}-\\mathrm{B}$ 와 $\\mathrm{B}-\\mathrm{A}$ 는 서로소이다. 합집합이 $\\mathrm{A}-\\mathrm{B}$ 와 같으려면 $\\mathrm{B}-\\mathrm{A}$ 의 원소가 없어야 한다.","확인":null,"스킬":"C4","고비":true},{"제목":"$\\mathrm{B}-\\mathrm{A}=\\varnothing$ 의 의미","힌트":"$\\mathrm{B}$ 에서 $\\mathrm{A}$ 를 빼고 남는 것이 없으면 $\\mathrm{B}$ 와 $\\mathrm{A}$ 의 관계는?","식":["$\\mathrm{B}-\\mathrm{A}=\\varnothing\\iff\\mathrm{B}\\subset\\mathrm{A}$"],"설명":"$\\mathrm{B}$ 의 모든 원소가 $\\mathrm{A}$ 에 속해야 $\\mathrm{B}-\\mathrm{A}$ 가 비므로 $\\mathrm{B}\\subset\\mathrm{A}$ 이다. 따라서 필요충분조건은 ③ 이다.","확인":null,"스킬":"C4"}]},"ns-3543504ee1a7":{"길":"부분집합의 개수를 2의 거듭제곱으로 쓰고 거듭제곱이 되는 조건을 찾는다","단계":[{"제목":"조건을 지수 식으로 나타내기","힌트":"원소가 $n$ 개인 집합의 부분집합의 개수는 몇 개이며, 이를 조건식에 넣으면?","식":["$f(\\mathrm{A})=2^{n(\\mathrm{A})}$","$2^{20}+2^{n(\\mathrm{B})}=2^{n(\\mathrm{A}\\cup\\mathrm{B})}$"],"설명":"원소가 $n$ 개인 집합의 부분집합은 $2^n$ 개이다. $n(\\mathrm{A})=20$ 이므로 $f(\\mathrm{A})=2^{20}$ 이고, 조건식은 $2^{20}+2^{n(\\mathrm{B})}=2^{n(\\mathrm{A}\\cup\\mathrm{B})}$ 이 된다.","확인":null,"스킬":"C7"},{"제목":"$n(\\mathrm{B})$ 와 $n(\\mathrm{A}\\cup\\mathrm{B})$ 의 값","힌트":"$2^{20}\\left(1+2^{n(\\mathrm{B})-20}\\right)$ 이 $2$ 의 거듭제곱이 되려면 $1+2^{m}$ 에서 $m$ 은 얼마여야 하는가?","식":["$2^{20}\\left(1+2^{n(\\mathrm{B})-20}\\right)=2^{n(\\mathrm{A}\\cup\\mathrm{B})}$","$n(\\mathrm{B})=20,\\ 2^{20}+2^{20}=2^{21}$"],"설명":"$n(\\mathrm{B})\\ge20$ 이므로 $m=n(\\mathrm{B})-20\\ge0$ 이다. $m\\ge1$ 이면 $1+2^m$ 은 $1$ 보다 큰 홀수가 되어 $2$ 의 거듭제곱이 아니다. 따라서 $m=0$ 이고 $1+1=2$ 이므로 $n(\\mathrm{B})=20$, $n(\\mathrm{A}\\cup\\mathrm{B})=21$ 이다.","확인":"21","스킬":"N1","고비":true},{"제목":"교집합의 원소의 개수","힌트":"$n(\\mathrm{A}\\cap\\mathrm{B})=n(\\mathrm{A})+n(\\mathrm{B})-n(\\mathrm{A}\\cup\\mathrm{B})$ 에 값을 넣으면?","식":["$n(\\mathrm{A}\\cap\\mathrm{B})=20+20-21=19$"],"설명":"합집합의 원소의 개수 공식을 교집합에 대하여 정리하고 앞 단계의 값을 대입한다.","확인":"19","스킬":"C4"},{"제목":"$f(\\mathrm{A}\\cap\\mathrm{B})$ 의 값","힌트":"원소가 $19$ 개인 집합의 부분집합의 개수는?","식":["$f(\\mathrm{A}\\cap\\mathrm{B})=2^{19}$"],"설명":"원소가 $19$ 개인 집합의 부분집합은 $2^{19}$ 개이다. 이 값은 선지 ⑤ 이다.","확인":null,"스킬":"N1"}]},"ns-40a1060cd4eb":{"길":"원소마다 그 원소가 최대인 부분집합의 개수를 세어 합을 구한다","단계":[{"제목":"최대 원소가 $\\dfrac12$ 인 부분집합의 개수","힌트":"$\\dfrac12$ 이 최대가 되려면 나머지 원소 세 개는 각각 넣을지 말지를 정하면 몇 가지인가?","식":["$2^3=8$"],"설명":"$\\dfrac12$ 은 전체집합에서 가장 큰 원소이므로 반드시 넣고, 나머지 세 원소는 자유롭게 넣거나 뺄 수 있다. 따라서 $2^3$ 개이다.","확인":"8","스킬":"P4","고비":true},{"제목":"나머지 원소가 최대인 경우의 개수","힌트":"$\\dfrac14$, $\\dfrac18$, $\\dfrac1{16}$ 이 최대인 부분집합은 각각 몇 개이고 모두 더하면 몇 개인가?","식":["$\\dfrac14:2^2=4,\\ \\dfrac18:2^1=2,\\ \\dfrac1{16}:2^0=1$","$8+4+2+1=15$"],"설명":"최대 원소보다 작은 원소만 자유롭게 정할 수 있다. 네 경우의 개수를 더하면 공집합이 아닌 부분집합의 개수 $2^4-1$ 과 같다.","확인":"15","스킬":"P3"},{"제목":"$a_1+a_2+\\cdots+a_n$ 의 값","힌트":"최대 원소 각각에 그 개수를 곱해 더하면 얼마인가?","식":["$8\\cdot\\dfrac12+4\\cdot\\dfrac14+2\\cdot\\dfrac18+1\\cdot\\dfrac1{16}=\\dfrac{85}{16}$"],"설명":"각 원소가 최대 원소로 뽑히는 횟수에 그 원소의 값을 곱해 더하면 $4+1+\\dfrac14+\\dfrac1{16}$ 이고, 통분하면 $\\dfrac{85}{16}$ 이다.","확인":"85/16","스킬":"P1"},{"제목":"$16(a_1+a_2+\\cdots+a_n)$ 의 값","힌트":"합에 $16$ 을 곱하면?","식":["$16\\times\\dfrac{85}{16}=85$"],"설명":"$16$ 과 분모 $16$ 이 약분되어 $85$ 가 남는다. 이 값은 선지 ② 이다.","확인":"85","스킬":"P1"}]},"ns-4487158d1221":{"길":"원소 하나하나가 놓이는 위치를 고르는 문제로 바꿔 곱의 법칙으로 센다","단계":[{"제목":"원소 하나가 놓일 수 있는 위치의 수","힌트":"$1$ 부터 $5$ 까지의 원소 하나가 $A$, $B$ 에 속하는 방식은 모두 몇 가지인가?","식":["$A$ 에만, $B$ 에만, 둘 다, 어느 쪽에도 없음 $\\to 4$ 가지"],"설명":"$A\\cup B\\subset\\{1,2,3,4,5\\}$ 이므로 각 원소는 $A$ 만, $B$ 만, 둘 다, 어느 쪽에도 속하지 않음 중 하나이다. 각 원소의 위치를 정하면 순서쌍 $(A,B)$ 가 하나 정해진다.","확인":"4","스킬":"P3"},{"제목":"교집합의 원소를 고르는 방법의 수","힌트":"$n(A\\cap B)=1$ 이면 $A$, $B$ 둘 다에 속하는 원소는 몇 개이며, 그 원소를 고르는 방법은?","식":["$_5\\mathrm{C}_1=5$"],"설명":"둘 다에 속하는 원소가 정확히 한 개이므로 다섯 개의 원소 중 그 하나를 고르는 방법은 $5$ 가지이다.","확인":"5","스킬":"P4"},{"제목":"나머지 네 원소가 놓이는 방법의 수","힌트":"교집합의 원소가 이미 정해졌다면 나머지 원소 하나에게 허용되는 위치는 몇 가지인가?","식":["$3^4=81$"],"설명":"나머지 네 원소는 교집합에 들어가면 안 되므로 $A$ 만, $B$ 만, 어느 쪽에도 없음의 $3$ 가지 중 하나이다. 네 원소가 각각 $3$ 가지이므로 $3^4$ 이다.","확인":"81","스킬":"P3","고비":true},{"제목":"순서쌍 $(A,B)$ 의 개수","힌트":"교집합의 원소를 고르는 방법과 나머지 원소의 위치를 정하는 방법을 곱하면?","식":["$5\\times81=405$"],"설명":"곱의 법칙에 의해 $5\\times3^4=405$ 이고, 이 값은 선지 ⑤ 이다.","확인":"405","스킬":"P4"}]},"ns-45e690bb3ff8":{"길":"세 집합의 크기를 더할 때 몇 번씩 세어지는지 따져 합집합을 모두의 수로 나타낸다","단계":[{"제목":"합집합의 원소의 개수를 모두 좋아하는 학생 수로 나타내기","힌트":"세 집합의 크기를 더하면 정확히 두 가지만 좋아하는 학생과 세 가지 모두 좋아하는 학생은 각각 몇 번씩 세어지는가?","식":["$t=n(\\mathrm{A}\\cap\\mathrm{B}\\cap\\mathrm{C})$","$25+20+15=(\\text{한 가지만})+2\\times14+3t$","$n(\\mathrm{A}\\cup\\mathrm{B}\\cup\\mathrm{C})=(32-3t)+14+t=46-2t$"],"설명":"크기의 합 $60$ 에서 한 가지만 좋아하는 학생은 $1$ 번, 두 가지만 좋아하는 학생은 $2$ 번, 세 가지 모두 좋아하는 학생은 $3$ 번 세어진다. 이를 이용해 한 가지만 좋아하는 학생 수를 $32-3t$ 로 두고 더하면 합집합의 원소의 개수가 $46-2t$ 이다.","확인":null,"스킬":"C10"},{"제목":"합집합의 원소의 개수의 최솟값","힌트":"세 가지 운동을 모두 좋아하지 않는 학생이 $4$ 명 이하이면 하나 이상 좋아하는 학생은 최소 몇 명인가?","식":["$n(\\mathrm{A}\\cup\\mathrm{B}\\cup\\mathrm{C})\\ge38-4=34$"],"설명":"합집합의 원소의 개수는 전체 $38$ 명에서 아무것도 좋아하지 않는 학생 수를 뺀 값이다. 그 학생이 $4$ 명 이하이므로 합집합은 $34$ 명 이상이다.","확인":"34","스킬":"C7","고비":true},{"제목":"세 가지 운동 모두를 좋아하는 학생 수의 최댓값","힌트":"$46-2t\\ge34$ 를 만족시키는 $t$ 의 최댓값은 얼마인가?","식":["$46-2t\\ge34\\ \\Rightarrow\\ t\\le6$"],"설명":"$t=6$ 이면 합집합이 $34$ 명이고, 한 가지만 좋아하는 학생은 $32-18=14$ 명으로 $0$ 이상이므로 가능하다. 따라서 최댓값은 $6$ 이다.","확인":"6","스킬":"C7"}]},"ns-5492bc145276":{"길":"집합 등식을 포함 관계로 바꿔 X 가 반드시 가져야 할 원소를 찾는다","단계":[{"제목":"두 조건을 포함 관계로 바꾸기","힌트":"$\\mathrm{A}\\cap\\mathrm{X}=\\mathrm{A}$ 는 어떤 관계이고, $\\mathrm{A}^{\\mathrm{c}}\\cap\\mathrm{B}$ 의 원소는 무엇인가?","식":["$\\mathrm{A}\\cap\\mathrm{X}=\\mathrm{A}\\iff\\mathrm{A}\\subset\\mathrm{X}$","$\\mathrm{A}^{\\mathrm{c}}\\cap\\mathrm{B}=\\{5,7\\}$","$(\\mathrm{A}^{\\mathrm{c}}\\cap\\mathrm{B})-\\mathrm{X}=\\varnothing\\iff\\{5,7\\}\\subset\\mathrm{X}$"],"설명":"$\\mathrm{A}$ 와 $\\mathrm{X}$ 의 교집합이 $\\mathrm{A}$ 이면 $\\mathrm{A}$ 가 $\\mathrm{X}$ 의 부분집합이다. $\\mathrm{A}^{\\mathrm{c}}\\cap\\mathrm{B}$ 는 $\\mathrm{B}$ 에서 $\\mathrm{A}$ 의 원소를 뺀 $\\{5,7\\}$ 이고, 이를 $\\mathrm{X}$ 로 빼서 공집합이면 $\\{5,7\\}\\subset\\mathrm{X}$ 이다.","확인":null,"스킬":"C4","고비":true},{"제목":"자유롭게 정할 수 있는 원소의 개수","힌트":"$\\mathrm{X}$ 가 반드시 포함하는 원소는 몇 개이고, 전체집합의 나머지 원소는 몇 개인가?","식":["$\\{1,2,3,5,7\\}\\subset\\mathrm{X}$","$10-5=5$"],"설명":"$\\mathrm{X}$ 는 $\\{1,2,3\\}$ 과 $\\{5,7\\}$ 을 모두 포함해야 하므로 반드시 들어가는 원소가 $5$ 개이다. 전체집합 $\\{1,2,\\cdots,10\\}$ 의 나머지 $5$ 개는 넣을지 말지 마음대로이다.","확인":"5","스킬":"C4"},{"제목":"집합 $\\mathrm{X}$ 의 개수","힌트":"자유로운 원소 $5$ 개 각각을 넣을지 말지 정하는 경우의 수는?","식":["$2^5=32$"],"설명":"나머지 $5$ 개의 원소는 각각 넣거나 넣지 않을 수 있으므로 $\\mathrm{X}$ 는 $2^5$ 개이다.","확인":"32","스킬":"C4"}]},"ns-5b3cdebd3e00":{"길":"차가 2 이하인 소수끼리 못 쓰게 걸러 큰 소수부터 고르고 합의 홀짝을 맞춘다","단계":[{"제목":"함께 넣을 수 없는 소수의 쌍","힌트":"$A=\\{2,3,5,7,11,13,17,19\\}$ 에서 두 소수의 차가 $2$ 이하인 쌍은 모두 몇 개인가?","식":["$(2,3),\\ (3,5),\\ (5,7),\\ (11,13),\\ (17,19)$"],"설명":"조건 (가) 는 서로 다른 두 원소의 차가 $3$ 이상이라는 뜻이다. 따라서 차가 $2$ 이하인 위의 다섯 쌍은 두 수를 한꺼번에 $X$ 에 넣을 수 없다.","확인":"5","스킬":"P4"},{"제목":"원소의 합이 가장 큰 후보","힌트":"큰 소수 $19$, $13$ 을 먼저 넣으면 $\\{2,3,5,7\\}$ 에서는 어떤 수를 고를 때 합이 가장 큰가?","식":["$19,\\ 13$ 포함, $\\{2,3,5,7\\}$ 에서 $3,\\ 7$ 선택","$3+7+13+19=42$"],"설명":"$17$ 은 $19$ 와, $11$ 은 $13$ 과 함께 쓸 수 없다. $\\{2,3,5,7\\}$ 에서는 서로 붙어 있지 않게 고른 $3$, $7$ 의 합이 $10$ 으로 가장 크다. 그러나 합이 $42$ 로 짝수이므로 조건 (나) 에 맞지 않는다.","확인":"42","스킬":"P4"},{"제목":"합이 홀수인 최댓값","힌트":"$19$, $13$ 을 유지하면서 합을 홀수로 만들 때 $\\{2,3,5,7\\}$ 에서는 어떤 수를 골라야 하는가?","식":["$\\{2,7\\}$ 선택: $2+7+13+19=41$","$19,\\ 13$ 중 하나를 빼면 합 $\\le40$"],"설명":"$\\{2,3,5,7\\}$ 에서 합이 $10$ 다음으로 큰 것은 $\\{2,7\\}$ 의 $9$ 이다. 이때 전체 합은 $41$ 로 홀수이다. $19$ 나 $13$ 을 빼고 $17$ 이나 $11$ 로 바꾸면 합이 $40$ 이하이므로 $41$ 이 최댓값이다.","확인":"41","스킬":"N5","고비":true}]},"ns-5be5cf5324fb":{"길":"각 원소가 최대인 부분집합의 개수를 세어 합을 구하고 가우스 기호를 적용한다","단계":[{"제목":"최대 원소가 $-\\dfrac12$ 인 부분집합의 개수","힌트":"$-\\dfrac12$ 이 가장 큰 원소가 되려면 나머지 다섯 원소는 각각 넣을지 말지를 정하면 몇 가지인가?","식":["$2^5=32$"],"설명":"$-\\dfrac12$ 은 집합 $\\mathrm{A}$ 에서 가장 큰 원소이다. 이 원소를 넣고 나머지 다섯 원소는 자유롭게 넣거나 뺄 수 있으므로 $2^5$ 개이다. 같은 방식으로 $-\\dfrac23$ 이 최대이면 $2^4$ 개, 이후 $2^3$, $2^2$, $2$, $1$ 개이다.","확인":"32","스킬":"P4"},{"제목":"뽑은 최대 원소의 합을 식으로 쓰기","힌트":"각 원소에 그 원소가 최대인 부분집합의 개수를 곱해 더하면 $x$ 는 어떤 식이 되는가?","식":["$x=-\\dfrac12\\cdot32-\\dfrac23\\cdot16-\\dfrac34\\cdot8-\\dfrac45\\cdot4-\\dfrac56\\cdot2-1$"],"설명":"원소 $-\\dfrac12$, $-\\dfrac23$, $-\\dfrac34$, $-\\dfrac45$, $-\\dfrac56$, $-1$ 이 최대 원소로 뽑히는 횟수는 차례로 $32$, $16$, $8$, $4$, $2$, $1$ 이다. 각 값에 횟수를 곱해 더한다.","확인":null,"스킬":"P4"},{"제목":"$x$ 의 값","힌트":"정수 부분과 분수 부분으로 나누어 계산하면 $x$ 는 얼마인가?","식":["$x=-16-\\dfrac{32}{3}-6-\\dfrac{16}{5}-\\dfrac53-1$","$x=-38-\\dfrac13-\\dfrac15=-\\dfrac{578}{15}$"],"설명":"분모가 $3$ 인 항 $-\\dfrac{32}{3}-\\dfrac53$ 은 $-\\dfrac{37}{3}=-12-\\dfrac13$ 이고, $-\\dfrac{16}{5}=-3-\\dfrac15$ 이다. 정수끼리 더하면 $-16-12-6-3-1=-38$ 이므로 $x=-38-\\dfrac13-\\dfrac15$ 이다.","확인":"-578/15","스킬":"P4"},{"제목":"가우스 기호 $[x]$ 의 값","힌트":"$x$ 는 $-38$ 보다 큰가 작은가, 그리고 $x$ 보다 크지 않은 최대의 정수는?","식":["$-39<-38-\\dfrac13-\\dfrac15<-38$","$[x]=-39$"],"설명":"$\\dfrac13+\\dfrac15<1$ 이므로 $x$ 는 $-39$ 와 $-38$ 사이에 있다. 가우스 기호는 $x$ 보다 크지 않은 최대의 정수이므로 음수에서는 절댓값이 더 큰 쪽인 $-39$ 이다.","확인":"-39","스킬":"N7","고비":true}]},"ns-5e62feb1bbd4":{"길":"세 과목 모두의 수를 문자로 두고 각 영역의 학생 수가 0 이상이 되는 조건을 쓴다","단계":[{"제목":"한 과목만 선호하는 학생 수","힌트":"세 과목 모두를 선호하는 학생을 $t$ 명이라 하면 국어만 선호하는 학생은 $28$ 명에서 어떤 학생을 빼야 하는가?","식":["국어만 $=28-20-17+t=t-9$","영어만 $=35-20-25+t=t-10$","수학만 $=30-25-17+t=t-12$"],"설명":"국어를 선호하는 학생 $28$ 명 중 국어와 영어, 국어와 수학을 선호하는 학생을 빼면 세 과목 모두를 선호하는 학생이 두 번 빠진다. 그래서 $t$ 를 한 번 더해 준다. 영어와 수학도 같은 방식이다.","확인":null,"스킬":"C7"},{"제목":"$t$ 의 하한","힌트":"한 과목만 선호하는 학생 수는 음수가 될 수 있는가?","식":["$t-9\\ge0,\\ t-10\\ge0,\\ t-12\\ge0$","$t\\ge12$"],"설명":"각 영역의 학생 수는 $0$ 이상이어야 하므로 세 식을 모두 만족하는 $t$ 의 범위는 $t\\ge12$ 이다.","확인":null,"스킬":"P4","고비":true},{"제목":"$t=12$ 가 가능한지 확인하고 최솟값 정하기","힌트":"$t=12$ 일 때 두 과목만 선호하는 학생과 전체 인원은 조건에 맞는가?","식":["국어만 $3$, 영어만 $2$, 수학만 $0$","국영만 $8$, 영수만 $13$, 국수만 $5$, 모두 $12$","$3+2+0+8+13+5+12=43\\le50$"],"설명":"$t=12$ 이면 두 과목만 선호하는 학생은 $20-12$, $25-12$, $17-12$ 로 모두 $0$ 이상이다. 모든 영역의 합이 $43$ 명으로 전체 $50$ 명을 넘지 않는다. 따라서 $t=12$ 가 가능하고 최솟값은 $12$ 이다.","확인":"12","스킬":"C7"}]},"ns-606459361a03":{"길":"연산을 3 으로 나눈 나머지로 읽고 x 의 값마다 대입해 조건을 확인한다","단계":[{"제목":"안쪽 식이 가져야 할 값","힌트":"$\\{(x\\otimes x)\\oplus(2\\otimes x)\\}\\oplus1=1$ 에서 $\\oplus1$ 을 하기 전의 값은 $0,1,2$ 중 무엇인가?","식":["$0\\oplus1=1,\\ 1\\oplus1=2,\\ 2\\oplus1=0$","$(x\\otimes x)\\oplus(2\\otimes x)=0$"],"설명":"$\\oplus$ 는 합을 $3$ 으로 나눈 나머지이므로 결과는 $0,1,2$ 중 하나이다. $1$ 을 $\\oplus$ 해서 $1$ 이 나오는 값은 $0$ 뿐이다.","확인":"0","스킬":"C6"},{"제목":"조건을 만족하는 $x$","힌트":"$x=0,1,2,3$ 을 각각 넣어 $(x\\otimes x)\\oplus(2\\otimes x)$ 를 구하면 어느 것이 $0$ 인가?","식":["$x=0:\\ 0\\oplus0=0$","$x=1:\\ 1\\oplus2=0$","$x=2:\\ 1\\oplus1=2$","$x=3:\\ 0\\oplus0=0$","$x=0,\\ 1,\\ 3$"],"설명":"$x=2$ 이면 $2\\otimes2=4$ 를 $3$ 으로 나눈 나머지 $1$ 이고 $2\\otimes x$ 도 $1$ 이므로 합이 $2$ 가 되어 맞지 않는다. $x=3$ 이면 $3\\otimes3$ 과 $2\\otimes3$ 이 모두 $0$ 이다. 따라서 $x=0,1,3$ 이다.","확인":null,"스킬":"N3","고비":true},{"제목":"$x$ 값들의 제곱의 합","힌트":"$0$, $1$, $3$ 의 제곱을 모두 더하면?","식":["$0^2+1^2+3^2=10$"],"설명":"조건을 만족하는 $x$ 는 $0$, $1$, $3$ 이므로 제곱의 합은 $0+1+9=10$ 이다.","확인":"10","스킬":"C6"}]},"ns-63602dfb72e0":{"길":"최소 원소와 최대 원소의 쌍을 정하고 그 사이 원소의 부분집합 수를 센다","단계":[{"제목":"합이 $9$ 인 (최소 원소, 최대 원소) 쌍의 개수","힌트":"$1\\sim8$ 에서 합이 $9$ 이고 최소 원소가 최대 원소보다 작은 쌍은 모두 몇 개인가?","식":["$(1,8),\\ (2,7),\\ (3,6),\\ (4,5)$"],"설명":"$\\mathrm{S}(\\mathrm{X})=9$ 이면 최소 원소와 최대 원소의 합이 $9$ 이다. $9$ 는 홀수이므로 두 수가 같을 수 없고, 작은 수가 $1,2,3,4$ 인 네 쌍이 가능하다.","확인":"4","스킬":"P4"},{"제목":"최소 $1$, 최대 $8$ 인 집합 $\\mathrm{X}$ 의 개수","힌트":"$1$ 과 $8$ 을 반드시 넣으면 그 사이의 원소 $2,3,4,5,6,7$ 은 각각 넣을지 말지를 정하면 몇 가지인가?","식":["$2^6=64$"],"설명":"최소 원소 $1$ 과 최대 원소 $8$ 이 정해지면 $\\mathrm{X}$ 는 그 사이의 여섯 원소를 마음대로 넣거나 뺀 집합이다. 따라서 $2^6$ 개이다.","확인":"64","스킬":"P4","고비":true},{"제목":"나머지 세 쌍의 집합의 개수","힌트":"쌍 $(2,7)$, $(3,6)$, $(4,5)$ 사이에 있는 원소는 각각 몇 개이고, 세 경우의 개수의 합은?","식":["$(2,7):\\ 2^4=16$","$(3,6):\\ 2^2=4$","$(4,5):\\ 2^0=1$","$16+4+1=21$"],"설명":"사이에 있는 원소는 $(2,7)$ 이면 $3,4,5,6$ 의 네 개, $(3,6)$ 이면 $4,5$ 의 두 개, $(4,5)$ 이면 없다. 사이 원소의 개수를 지수로 하여 $2$ 의 거듭제곱으로 센다.","확인":"21","스킬":"P4"},{"제목":"조건을 만족하는 집합 $\\mathrm{X}$ 의 개수","힌트":"네 쌍의 경우의 개수를 모두 더하면?","식":["$64+21=85$"],"설명":"네 쌍은 서로 겹치지 않는 경우이므로 개수를 모두 더하면 된다.","확인":"85","스킬":"P4"}]},"ns-63b030381a8e":{"길":"A 와 B 의 차이 나는 원소가 모두 C 에 들어가야 함을 이용해 C 를 정한다","단계":[{"제목":"집합 $A$, $B$ 의 원소 나열","힌트":"$\\sqrt{x}$ 가 $5$ 보다 작은 자연수이고 $x<10$ 인 $x$ 는 무엇이며, $8$ 의 약수는 무엇인가?","식":["$A=\\{1,4,9\\}$","$B=\\{1,2,4,8\\}$"],"설명":"$\\sqrt{x}=1,2,3,4$ 중 $x$ 가 $10$ 보다 작은 것은 $x=1,4,9$ 이다. $8$ 의 약수는 $1,2,4,8$ 이다.","확인":null,"스킬":"C4"},{"제목":"$C$ 가 반드시 가져야 하는 원소의 개수","힌트":"$A\\cup C=B\\cup C$ 이려면 $A$, $B$ 중 한쪽에만 속하는 원소는 $C$ 에 있어야 하는가? 그런 원소는 몇 개인가?","식":["$2,\\ 8\\in B$ 이지만 $\\notin A$","$9\\in A$ 이지만 $\\notin B$","$\\{2,8,9\\}\\subset C$"],"설명":"$2$ 와 $8$ 은 $B$ 에만 속하므로 $A\\cup C$ 에도 들어가려면 $C$ 의 원소여야 한다. $9$ 는 $A$ 에만 속하므로 같은 이유로 $C$ 의 원소여야 한다. 둘 다에 속하는 $1$, $4$ 는 $C$ 에 있든 없든 상관없다.","확인":"3","스킬":"C4","고비":true},{"제목":"집합 $C$ 의 원소의 개수","힌트":"원소가 $n$ 개인 집합의 진부분집합이 $15$ 개이면 $n$ 은 얼마인가?","식":["$2^n-1=15$","$n(C)=4$"],"설명":"원소가 $n$ 개인 집합의 진부분집합의 개수는 $2^n-1$ 이다. $2^n=16$ 이므로 $n=4$ 이고, $C$ 는 $2,8,9$ 와 다른 원소 한 개로 이루어진다.","확인":"4","스킬":"P4"},{"제목":"가능한 모든 $k$ 의 합","힌트":"나머지 한 원소로 가능한 수는 무엇이고, 그때의 $k$ 를 모두 더하면?","식":["나머지 원소: $1,3,4,5,6,7$","$(2+8+9)\\times6+(1+3+4+5+6+7)=114+26=140$"],"설명":"전체집합 $\\{1,2,\\cdots,9\\}$ 에서 $2,8,9$ 를 뺀 $1,3,4,5,6,7$ 중 하나가 나머지 원소이므로 $C$ 는 $6$ 가지이다. 각 경우의 $k$ 는 $19$ 에 그 원소를 더한 값이므로, $19$ 가 여섯 번 더해지고 여섯 원소의 합 $26$ 이 더해진다.","확인":"140","스킬":"P4"}]},"ns-7d7e106bb5c3":{"길":"합의 조건으로 k 를 먼저 구하고 교집합 원소를 이용해 A 를 채운다","단계":[{"제목":"집합 $\\mathrm{B}$ 의 원소의 합","힌트":"$\\mathrm{A}\\cup\\mathrm{B}$ 의 합은 $\\mathrm{A}$ 의 합과 $\\mathrm{B}$ 의 합을 더하고 겹치는 부분을 한 번 빼면 어떻게 되는가?","식":["$62=50+(\\mathrm{B}\\text{의 합})-(4+7+9)$","$\\mathrm{B}\\text{의 합}=32$"],"설명":"두 집합의 합집합의 원소의 합은 각 집합의 합을 더한 값에서 교집합의 합을 뺀 것이다. 교집합 $\\{4,7,9\\}$ 의 합은 $20$ 이므로 $\\mathrm{B}$ 의 합은 $32$ 이다.","확인":"32","스킬":"C7"},{"제목":"상수 $k$ 의 값","힌트":"$\\mathrm{B}$ 의 원소는 $\\mathrm{A}$ 의 원소에서 각각 $k$ 를 뺀 것이므로 $\\mathrm{B}$ 의 합은 $k$ 로 어떻게 나타내는가?","식":["$\\mathrm{B}\\text{의 합}=50-6k=32$","$k=3$"],"설명":"$\\mathrm{A}$ 의 원소가 여섯 개이므로 각각 $k$ 를 빼면 합이 $6k$ 만큼 줄어든다. $50-6k=32$ 이므로 $k=3$ 이다.","확인":"3","스킬":"C7"},{"제목":"집합 $\\mathrm{A}$ 가 반드시 가지는 원소","힌트":"$4,7,9$ 가 $\\mathrm{B}$ 의 원소이면 $\\mathrm{A}$ 에서 어떤 수가 나와 $4,7,9$ 가 되었는가?","식":["$b=a-3$ 이므로 $a=b+3$","$7,\\ 10,\\ 12\\in\\mathrm{A}$","$4,\\ 7,\\ 9\\in\\mathrm{A}$ 와 합하면 $\\{4,7,9,10,12\\}\\subset\\mathrm{A}$"],"설명":"교집합의 원소는 $\\mathrm{A}$ 에도 $\\mathrm{B}$ 에도 속한다. $\\mathrm{B}$ 의 원소 $4,7,9$ 는 $\\mathrm{A}$ 의 원소에서 $3$ 을 뺀 것이므로 $\\mathrm{A}$ 에는 $7,10,12$ 가 있다. 이미 알고 있는 $4,7,9$ 와 합하면 $\\mathrm{A}$ 는 $4,7,9,10,12$ 를 가진다.","확인":null,"스킬":"C7","고비":true},{"제목":"집합 $\\mathrm{A}$ 의 나머지 원소","힌트":"$\\mathrm{A}$ 의 합 $50$ 에서 이미 정해진 다섯 원소의 합을 빼면?","식":["$4+7+9+10+12=42$","$50-42=8$","$\\mathrm{A}=\\{4,7,8,9,10,12\\}$"],"설명":"$\\mathrm{A}$ 의 원소는 여섯 개이고 다섯 개가 정해졌으므로 나머지 한 개는 $50$ 에서 그 합을 뺀 $8$ 이다.","확인":"8","스킬":"C7"},{"제목":"$\\mathrm{B}$ 의 원소 중 세 번째로 큰 수","힌트":"$\\mathrm{A}$ 의 각 원소에서 $3$ 을 뺀 $\\mathrm{B}$ 를 큰 수부터 나열하면 세 번째는?","식":["$\\mathrm{B}=\\{1,4,5,6,7,9\\}$","$9,\\ 7,\\ 6,\\ 5,\\ 4,\\ 1$"],"설명":"$\\mathrm{B}$ 의 원소는 $1,4,5,6,7,9$ 이고 $\\mathrm{A}\\cap\\mathrm{B}=\\{4,7,9\\}$ 가 조건과 일치한다. 큰 수부터 세면 $9,7,6$ 이므로 세 번째는 $6$ 이다.","확인":"6","스킬":"C7"}]},"ns-804bf08a009c":{"길":"C 가 A, B 와 겹치지 않으므로 C 가 (A∪B) 의 여집합 안에 있음을 이용한다","단계":[{"제목":"$C$ 가 들어 있는 집합","힌트":"$C$ 가 $A$, $B$ 와 모두 겹치지 않으면 $C$ 는 $A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}$ 와 어떤 관계인가?","식":["$C\\subset A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}$"],"설명":"$C$ 의 원소는 $A$ 에도 $B$ 에도 속하지 않으므로 모두 $A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}$ 에 속한다. 따라서 $C$ 는 $A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}$ 의 부분집합이다.","확인":null,"스킬":"C4","고비":true},{"제목":"$n(A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}\\cap C^{\\mathrm{c}})$ 를 $n(C)$ 로 나타내기","힌트":"$A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}$ 에서 $C$ 의 원소를 빼면 어떤 집합이 되는가?","식":["$A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}\\cap C^{\\mathrm{c}}=(A^{\\mathrm{c}}\\cap B^{\\mathrm{c}})-C$","$14=52-n(C)$"],"설명":"$C$ 가 $A^{\\mathrm{c}}\\cap B^{\\mathrm{c}}$ 의 부분집합이므로 $C^{\\mathrm{c}}$ 와의 교집합은 $C$ 의 원소를 뺀 나머지이다. 그 원소의 개수는 $52-n(C)$ 이다.","확인":null,"스킬":"C4"},{"제목":"$n(C)$ 의 값","힌트":"$14=52-n(C)$ 에서 $n(C)$ 는?","식":["$n(C)=52-14=38$"],"설명":"앞 단계의 식을 $n(C)$ 에 대하여 풀면 값이 정해진다.","확인":"38","스킬":"C4"}]},"ns-8ab5bf6e6166":{"길":"불참 인원의 합을 먼저 구하고 n 의 범위로 m-n 의 최대 최소를 잡는다","단계":[{"제목":"불참한 학생 수의 합 $m+n$","힌트":"전체 $251$ 명 중 참석하지 않은 학생은 몇 명이고, 이것은 $m$, $n$ 과 어떤 관계인가?","식":["$m+n=251-130=121$"],"설명":"참석하지 않은 학생은 참석 가능이라고 답했으나 불참한 $m$ 명과 모르겠다고 답했으나 불참한 $n$ 명으로 이루어진다. 전체에서 참석한 $130$ 명을 빼면 $121$ 명이다.","확인":"121","스킬":"C7"},{"제목":"$m-n$ 을 $n$ 하나로 나타내기","힌트":"$m=121-n$ 을 $m-n$ 에 대입하면 어떤 식이 되는가?","식":["$m-n=(121-n)-n=121-2n$"],"설명":"$m+n=121$ 에서 $m=121-n$ 이다. 이를 $m-n$ 에 대입하면 $n$ 이 작을수록 $m-n$ 이 커지는 식이 된다.","확인":null,"스킬":"C7"},{"제목":"$n$ 의 범위","힌트":"$n$ 은 모르겠다고 응답한 $95$ 명 중 불참한 학생 수이다. $n$ 의 가장 작은 값과 가장 큰 값은?","식":["$0\\le n\\le95$","$n=0$ 이면 $m=121\\le156$, $n=95$ 이면 $m=26\\ge0$"],"설명":"$n$ 은 $0$ 명 이상 $95$ 명 이하이다. 양 끝에서 $m=121-n$ 이 $0$ 이상 $156$ 이하인지 확인하면 $n=0$ 일 때 $m=121$, $n=95$ 일 때 $m=26$ 으로 모두 가능하다.","확인":null,"스킬":"C7","고비":true},{"제목":"$m-n$ 의 최댓값과 최솟값의 합","힌트":"$121-2n$ 은 $n=0$ 과 $n=95$ 일 때 각각 얼마이며 그 합은?","식":["최댓값: $n=0$ 일 때 $121$","최솟값: $n=95$ 일 때 $121-190=-69$","$121+(-69)=52$"],"설명":"$121-2n$ 은 $n$ 이 증가하면 줄어드는 식이므로 $n=0$ 에서 최대, $n=95$ 에서 최소이다. 두 값을 더하면 $52$ 이다.","확인":"52","스킬":"C7"}]},"ns-8f9edda26257":{"길":"B 의 최소, 최대로 A 의 양 끝 원소를 정하고 n(B)=5 로 나머지 원소를 구한다","단계":[{"제목":"집합 $\\mathrm{A}$ 의 가장 작은 원소와 가장 큰 원소","힌트":"$\\mathrm{B}$ 의 최솟값 $16$ 과 최댓값 $256$ 은 $\\mathrm{A}$ 의 어느 원소끼리의 곱인가?","식":["최솟값 $16=4^2$, 최댓값 $256=16^2$","$\\mathrm{A}=\\{4,x,16\\}\\ (4<x<16)$"],"설명":"자연수끼리의 곱에서 가장 작은 값은 가장 작은 원소끼리의 곱이고 가장 큰 값은 가장 큰 원소끼리의 곱이다. 따라서 $\\mathrm{A}$ 의 가장 작은 원소는 $4$, 가장 큰 원소는 $16$ 이다.","확인":null,"스킬":"P4"},{"제목":"집합 $\\mathrm{B}$ 의 원소를 $x$ 로 나열","힌트":"$\\mathrm{A}=\\{4,x,16\\}$ 의 두 원소의 곱을 모두 적으면 몇 개의 식이 나오는가?","식":["$4\\cdot4=16,\\ 4x,\\ 4\\cdot16=64$","$x^2,\\ 16x,\\ 16^2=256$"],"설명":"$p$, $q$ 가 각각 $4,x,16$ 중 하나이므로 서로 다른 곱은 $16,\\ 4x,\\ 64,\\ x^2,\\ 16x,\\ 256$ 의 여섯 개 식이다. $n(\\mathrm{B})=5$ 이므로 이 중 두 식만 값이 같아야 한다.","확인":null,"스킬":"P4"},{"제목":"$x$ 의 값","힌트":"$4<x<16$ 일 때 여섯 식 중 값이 같아질 수 있는 두 식은 무엇인가?","식":["$16<4x<64,\\ 64<16x<256$","$x^2=64$","$x=8$"],"설명":"$4<x<16$ 이면 $4x$ 는 $16$ 과 $64$ 사이, $16x$ 는 $64$ 와 $256$ 사이에 있어 다른 식과 같아질 수 없다. $x^2$ 이 $4x$, $16x$, $16$, $256$ 과 같아지려면 $x$ 가 $4$ 나 $16$ 이 되어야 하므로 불가능하다. 따라서 $x^2=64$ 일 때만 $n(\\mathrm{B})=5$ 가 되고 $x=8$ 이다.","확인":"8","스킬":"P4","고비":true},{"제목":"집합 $\\mathrm{A}$ 의 모든 원소의 합","힌트":"$\\mathrm{A}=\\{4,8,16\\}$ 의 합은?","식":["$4+8+16=28$"],"설명":"이때 $\\mathrm{B}=\\{16,32,64,128,256\\}$ 으로 원소가 다섯 개이고 최솟값 $16$, 최댓값 $256$ 이 조건과 맞는다.","확인":"28","스킬":"P4"}]},"ns-91452a69a28e":{"길":"수혈받을 수 없는 학생이 어느 혈액형인지 짝지어 식을 세우고 연립한다","단계":[{"제목":"조건 (가), (나), (다) 를 혈액형의 식으로","힌트":"$\\mathrm{A}$형 혈액을 받을 수 없는 혈액형은 무엇이고, $\\mathrm{B}$형 혈액은? 모든 혈액을 받을 수 있는 혈액형은?","식":["(가) $\\mathrm{O}+\\mathrm{B}=15$","(나) $\\mathrm{O}+\\mathrm{A}=18$","(다) $\\mathrm{AB}=5$"],"설명":"$\\mathrm{A}$형 혈액은 $\\mathrm{A}$형과 $\\mathrm{AB}$형만 받을 수 있으므로 못 받는 학생은 $\\mathrm{O}$형과 $\\mathrm{B}$형이다. $\\mathrm{B}$형 혈액을 못 받는 학생은 $\\mathrm{O}$형과 $\\mathrm{A}$형이다. 모든 혈액을 받을 수 있는 혈액형은 $\\mathrm{AB}$형뿐이다. 문자는 각 혈액형 학생 수이다.","확인":null,"스킬":"C7","고비":true},{"제목":"$\\mathrm{O}$형, $\\mathrm{A}$형, $\\mathrm{B}$형 학생의 합","힌트":"전체 $30$ 명에서 $\\mathrm{AB}$형을 빼면?","식":["$\\mathrm{O}+\\mathrm{A}+\\mathrm{B}=30-5=25$"],"설명":"학생의 혈액형은 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{AB}$, $\\mathrm{O}$ 넷뿐이다. $\\mathrm{AB}$형이 $5$ 명이므로 나머지 세 혈액형의 합은 $25$ 명이다.","확인":"25","스킬":"P4"},{"제목":"$\\mathrm{O}$형 학생의 수","힌트":"(가), (나) 를 더한 식에서 $\\mathrm{O}+\\mathrm{A}+\\mathrm{B}=25$ 를 빼면?","식":["$(\\mathrm{O}+\\mathrm{B})+(\\mathrm{O}+\\mathrm{A})=33$","$\\mathrm{O}+(\\mathrm{O}+\\mathrm{A}+\\mathrm{B})=33\\ \\Rightarrow\\ \\mathrm{O}=33-25=8$"],"설명":"(가), (나) 를 변끼리 더하면 $\\mathrm{O}$ 가 두 번, $\\mathrm{A}$, $\\mathrm{B}$ 가 한 번씩 나온다. 이는 $\\mathrm{O}+25$ 와 같으므로 $\\mathrm{O}=8$ 이다. 이때 $\\mathrm{A}=10$, $\\mathrm{B}=7$ 이고 합이 $25$ 로 맞는다.","확인":"8","스킬":"P4"}]},"ns-97226a1bc216":{"길":"B의 원소에서 k를 빼면 A의 원소임을 써서 A의 네 원소를 정한다","단계":[{"제목":"합집합의 원소의 합을 k, a로 나타내기","힌트":"$S(B)$ 는 $S(A)$ 와 $k$ 로, $S(A\\cup B)$ 는 겹친 원소를 한 번 빼서 쓰면?","식":["$S(B)=S(A)+4k=14+4k$","$S(A\\cup B)=S(A)+S(B)-S(A\\cap B)$","$33=14+(14+4k)-(3+a)\\ \\Rightarrow\\ a=4k-8$"],"설명":"$B$ 의 원소는 $A$ 의 네 원소에 각각 $k$ 를 더한 것이라 합이 $4k$ 만큼 커진다. 합집합의 합은 두 집합의 합을 더한 뒤 겹친 원소의 합을 한 번 빼서 구한다.","확인":null,"스킬":"C6"},{"제목":"A∩B의 원소로 A의 네 원소 정하기","고비":true,"힌트":"$3,\\ a$ 가 $B$ 의 원소이면 $A$ 의 어떤 원소에 $k$ 를 더해 만들어진 것일까?","식":["$3\\in B\\ \\Rightarrow\\ 3-k\\in A$","$a\\in B\\ \\Rightarrow\\ a-k\\in A$","$A=\\{3-k,\\ 3,\\ a-k,\\ a\\}$"],"설명":"$B$ 의 원소는 $A$ 의 원소에 $k$ 를 더한 값이므로, $B$ 에 속한 $3,\\ a$ 에서 $k$ 를 빼면 $A$ 의 원소가 된다. $0<k<a-3$ 이므로 $3-k<3<a-k<a$ 로 네 수가 모두 다르고, $n(A)=4$ 이므로 이 네 수가 $A$ 의 전부이다.","확인":null,"스킬":"C6"},{"제목":"원소의 합으로 a-k 의 값 구하기","힌트":"네 원소의 합이 $14$ 라는 식에서 $a-k$ 는 얼마일까?","식":["$(3-k)+3+(a-k)+a=14$","$2a-2k+6=14$","$a-k=4$"],"설명":"네 원소를 모두 더하면 $a$ 가 두 번, $k$ 가 두 번 빠진 꼴이 되어 $2(a-k)+6=14$ 이다. 이를 풀면 $a-k$ 가 정해진다.","확인":"4","스킬":"C7"},{"제목":"k, a 를 구하고 A 확정하기","힌트":"$a=4k-8$ 과 $a-k=4$ 에서 $a$ 를 소거하면?","식":["$4k-8=k+4$","$k=4,\\ a=8$","$A=\\{-1,\\ 3,\\ 4,\\ 8\\}$"],"설명":"$a=k+4$ 를 $a=4k-8$ 에 대입하면 $k=4$ 이다. $0<k<a-3$ 에서 $4<5$ 이므로 조건에 맞고, $B=\\{3,\\ 7,\\ 8,\\ 12\\}$ 에서 $A\\cap B=\\{3,\\ 8\\}$ 이며 $A\\cup B$ 의 원소의 합도 $33$ 이다.","확인":"8","스킬":"A10"},{"제목":"원소의 제곱의 합 구하기","힌트":"네 원소를 각각 제곱해서 더하면?","식":["$(-1)^{2}+3^{2}+4^{2}+8^{2}=1+9+16+64=90$"],"설명":"음수인 $-1$ 도 제곱하면 $1$ 이 된다. 네 제곱수를 모두 더한다.","확인":"90","스킬":"C7"}]},"ns-9f24014bfbb3":{"길":"올림 기호를 풀어 A_n 의 원소를 정수 빼기 분수 꼴로 정리한다","단계":[{"제목":"A_n 의 원소를 한 꼴로 나타내기","고비":true,"힌트":"$<x>=m$ 으로 놓으면 $x$ 는 $m$ 과 $n$ 으로 어떻게 쓸 수 있을까?","식":["$<x>=m\\ (m\\text{은 정수}),\\quad m-x=\\dfrac{1}{2n}$","$x=m-\\dfrac{1}{2n}$","$A_{n}=\\left\\{m-\\dfrac{1}{2n}\\ \\middle|\\ m\\text{은 정수}\\right\\}$"],"설명":"$x$ 이상의 최소 정수가 $m$ 이므로 $m-x$ 가 주어진 값과 같아야 한다. $0<\\frac{1}{2n}<1$ 이라서 $m-1<x<m$ 이 되어 $<x>=m$ 과 모순이 없다.","확인":null,"스킬":"N7"},{"제목":"ㄱ 의 참 거짓 판별","힌트":"$-\\frac{7}{6}$ 을 $m-\\frac{1}{6}$ 꼴로 놓으면 $m$ 은 얼마일까?","식":["$A_{3}=\\left\\{m-\\dfrac{1}{6}\\right\\}$","$-\\dfrac{7}{6}=m-\\dfrac{1}{6}$","$m=-1$"],"설명":"$m$ 이 정수 $-1$ 로 나오므로 $-\\frac{7}{6}$ 은 $A_{3}$ 의 원소이다. ㄱ 은 참이다.","확인":"-1","스킬":"N7"},{"제목":"ㄴ 의 참 거짓 판별","힌트":"$A_{2}$ 의 원소 하나를 잡아 $A_{4}$ 의 꼴에 맞는지 확인하면?","식":["$A_{2}=\\left\\{m-\\dfrac{1}{4}\\right\\}$, 여기서 $\\dfrac{3}{4}\\in A_{2}$","$A_{4}=\\left\\{m-\\dfrac{1}{8}\\right\\}$","$\\dfrac{3}{4}=m-\\dfrac{1}{8}\\ \\Rightarrow\\ m=\\dfrac{7}{8}$"],"설명":"$m=1$ 일 때 $\\frac{3}{4}$ 은 $A_{2}$ 의 원소이다. 그런데 $A_{4}$ 의 원소로 쓰려면 $m=\\frac{7}{8}$ 이 되어 정수가 아니다. 반례가 하나 있으므로 $A_{2}\\not\\subset A_{4}$ 이고 ㄴ 은 거짓이다.","확인":"7/8","스킬":"C3"},{"제목":"ㄷ 의 참 거짓 판별","힌트":"$A_{i}$ 의 원소를 정수 부분과 $0$ 과 $1$ 사이의 부분으로 나누면 뒤의 부분은 어떻게 될까?","식":["$m-\\dfrac{1}{2n}=(m-1)+\\left(1-\\dfrac{1}{2n}\\right)$","$0<1-\\dfrac{1}{2n}<1$","$i\\ne j\\ \\Rightarrow\\ 1-\\dfrac{1}{2i}\\ne 1-\\dfrac{1}{2j}$"],"설명":"정수와 $0$ 과 $1$ 사이의 수로 나뉘므로 뒤의 수가 소수 부분이다. 이 값이 $n$ 마다 다르기 때문에 $i\\ne j$ 이면 두 집합에 공통으로 속하는 수가 없다. ㄷ 은 참이다.","확인":null,"스킬":"N7"},{"제목":"참인 보기 조합 고르기","힌트":"ㄱ, ㄴ, ㄷ 중 참인 것만 모으면 어느 선지일까?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참"],"설명":"참인 보기는 ㄱ 과 ㄷ 이므로 ㄱ, ㄷ 이 답이다.","확인":null,"스킬":"C3"}]},"ns-9fe210845b48":{"길":"연산 ⊙ 를 한쪽에만 속하는 부분으로 읽고 주기를 찾아 세 물음을 푼다","단계":[{"제목":"연산 ⊙ 의 뜻과 성질 파악하기","힌트":"$\\mathrm{A}\\odot\\mathrm{B}$ 는 벤다이어그램에서 어느 부분이고, $\\mathrm{A}\\odot\\mathrm{A}$ 는 무엇일까?","식":["$\\mathrm{A}\\odot\\mathrm{B}=(\\mathrm{A}\\cup\\mathrm{B})-(\\mathrm{A}\\cap\\mathrm{B})$","$\\mathrm{A}\\odot\\mathrm{A}=\\varnothing$","$\\mathrm{A}\\odot\\varnothing=\\mathrm{A}$"],"설명":"$(\\mathrm{A}\\cup\\mathrm{B})\\cap(\\mathrm{A}\\cap\\mathrm{B})^{\\mathrm{c}}$ 는 두 집합 중 한쪽에만 속하는 부분이다. 같은 집합끼리 ⊙ 하면 공집합이 되고, 공집합과 ⊙ 하면 원래 집합이 그대로 남는다. 계산 순서를 바꾸어도 결과가 같으므로 같은 집합이 두 번 나오면 지울 수 있다.","확인":null,"스킬":"C6"},{"제목":"⑴ X_n 이 처음으로 되돌아오는 주기 찾기","고비":true,"힌트":"$\\mathrm{X}_{4},\\ \\mathrm{X}_{5},\\ \\mathrm{X}_{6}$ 에서 같은 집합을 지워 가며 쓰면 몇 번째에 $\\mathrm{X}_{1}$ 과 같아질까?","식":["$\\mathrm{X}_{4}=\\mathrm{A}\\odot\\mathrm{B}\\odot\\mathrm{C}\\odot\\mathrm{A}=\\mathrm{B}\\odot\\mathrm{C}$","$\\mathrm{X}_{5}=\\mathrm{C},\\quad \\mathrm{X}_{6}=\\mathrm{C}\\odot\\mathrm{C}=\\varnothing$","$\\mathrm{X}_{7}=\\varnothing\\odot\\mathrm{A}=\\mathrm{A}=\\mathrm{X}_{1}$"],"설명":"$\\mathrm{A},\\ \\mathrm{B},\\ \\mathrm{C}$ 가 한 바퀴 돌면 각각 두 번씩 쓰여 모두 지워지고 $\\varnothing$ 이 된다. 그 뒤로는 처음과 같은 과정이 반복되므로 $\\mathrm{X}_{n}$ 은 같은 순서로 되풀이된다.","확인":"6","스킬":"C6"},{"제목":"⑴ X_n = A 인 횟수 세기","힌트":"$n\\le 30$ 에서 $\\mathrm{X}_{n}=\\mathrm{A}$ 가 되는 $n$ 은 $6$ 으로 나눈 나머지가 얼마일 때일까?","식":["$n=6k+1\\ (k=0,\\ 1,\\ 2,\\ \\cdots)$","$n=1,\\ 7,\\ 13,\\ 19,\\ 25$"],"설명":"주기가 $6$ 이고 $\\mathrm{X}_{1}=\\mathrm{A}$ 이므로 $n$ 을 $6$ 으로 나눈 나머지가 $1$ 일 때만 $\\mathrm{A}$ 가 나온다. 다음 후보인 $31$ 은 범위를 넘으므로 $5$ 번이다.","확인":"5","스킬":"N3"},{"제목":"⑵ 벤다이어그램에서 (A⊙B) 의 여집합 구하기","힌트":"그림에서 $\\mathrm{A},\\ \\mathrm{B}$ 의 원소를 읽고 $\\mathrm{A}\\odot\\mathrm{B}$ 부터 구하면?","식":["$\\mathrm{A}=\\{1,\\ 5\\},\\ \\mathrm{B}=\\{3,\\ 5\\},\\ \\mathrm{U}=\\{1,\\ 3,\\ 5,\\ 7\\}$","$\\mathrm{A}\\odot\\mathrm{B}=\\{1,\\ 3\\}$","$(\\mathrm{A}\\odot\\mathrm{B})^{\\mathrm{c}}=\\{5,\\ 7\\}$"],"설명":"겹친 부분인 $5$ 는 빼고 한쪽에만 속한 $1,\\ 3$ 이 $\\mathrm{A}\\odot\\mathrm{B}$ 이다. 전체집합에서 이 둘을 뺀 $5,\\ 7$ 의 합이 구하는 값이다.","확인":"12","스킬":"C4"},{"제목":"⑶ ∼q → ∼p 가 거짓이 되는 원소 찾기","힌트":"$\\sim q\\rightarrow\\sim p$ 가 거짓이 되려면 $\\sim q$ 와 $\\sim p$ 가 각각 어떤 값을 가져야 할까?","식":["$\\mathrm{B}^{\\mathrm{c}}=\\{1,\\ 7\\}$","$(\\mathrm{A}\\odot\\mathrm{B})^{\\mathrm{c}}=\\{5,\\ 7\\}$","$\\mathrm{B}^{\\mathrm{c}}-(\\mathrm{A}\\odot\\mathrm{B})^{\\mathrm{c}}=\\{1\\}$"],"설명":"$\\sim q\\rightarrow\\sim p$ 가 거짓이려면 $\\sim q$ 는 참이고 $\\sim p$ 는 거짓인 원소가 있어야 한다. 곧 $\\sim q$ 의 진리집합 $\\mathrm{B}^{\\mathrm{c}}$ 에는 속하고 $\\sim p$ 의 진리집합 $(\\mathrm{A}\\odot\\mathrm{B})^{\\mathrm{c}}$ 에는 속하지 않는 원소이며, 그것은 $1$ 하나뿐이다.","확인":"1","스킬":"C4"}]},"ns-a6952faf0c97":{"길":"합이 22 이상인 경우를 여집합의 합으로 바꿔 세고 전체에서 뺀다","단계":[{"제목":"여사건으로 바꾸기","고비":true,"힌트":"$A$ 의 모든 원소의 합은 얼마이고, $S(X)\\ge 22$ 이면 $X$ 의 여집합의 합은 어떻게 될까?","식":["$S(A)=1+2+\\cdots+7=28$","$S(X)+S(X^{C})=28$","$S(X)\\ge 22\\iff S(X^{C})\\le 6$"],"설명":"$X$ 와 그 여집합 $X^{C}$ 의 원소를 합치면 $A$ 전체이므로 두 합의 합은 $28$ 이다. 따라서 $S(X)$ 가 $22$ 이상인 경우는 $S(X^{C})$ 가 $6$ 이하인 경우와 일대일로 대응한다.","확인":"28","스킬":"P2"},{"제목":"합이 6 이하인 부분집합 세기","힌트":"합이 $0,\\ 1,\\ \\cdots,\\ 6$ 인 부분집합을 합별로 나눠 빠짐없이 적으면 모두 몇 개일까?","식":["$0,\\ 1,\\ 2$ 일 때 : $\\varnothing,\\ \\{1\\},\\ \\{2\\}$","$3,\\ 4,\\ 5$ 일 때 : $\\{3\\},\\ \\{1,2\\},\\ \\{4\\},\\ \\{1,3\\},\\ \\{5\\},\\ \\{1,4\\},\\ \\{2,3\\}$","$6$ 일 때 : $\\{6\\},\\ \\{1,5\\},\\ \\{2,4\\},\\ \\{1,2,3\\}$"],"설명":"합이 작은 것부터 원소가 큰 수 하나인 경우, 작은 수 둘 이상으로 만드는 경우 순으로 적으면 빠지는 것이 없다. 공집합까지 포함하면 $3+7+4=14$ 개이다.","확인":"14","스킬":"P4"},{"제목":"전체에서 빼서 개수 구하기","힌트":"공집합이 아닌 부분집합 전체의 개수에서 합이 $22$ 이상인 것의 개수를 빼면?","식":["$2^{7}-1=127$","$127-14=113$"],"설명":"합이 $22$ 이상인 $X$ 는 $14$ 개이고 모두 공집합이 아니다. 공집합이 아닌 부분집합 $127$ 개에서 이를 빼면 $S(X)<22$ 인 집합의 개수이다.","확인":"113","스킬":"P2"}]},"ns-ae0381d83ade":{"길":"색칠한 부분이 어느 집합 안팎에 있는지 읽어 선지의 식과 맞춘다","단계":[{"제목":"색칠한 부분의 위치 읽기","고비":true,"힌트":"색칠한 부분은 $A,\\ B,\\ C$ 각각의 안과 밖 중 어디에 있을까?","식":["$A\\cap B\\cap C^{C}$","$=A\\cap(B\\cap C^{C})=A\\cap(B-C)$"],"설명":"색칠한 부분은 $A$ 와 $B$ 가 겹치는 곳 중에서 $C$ 에 속하지 않는 부분이다. $B\\cap C^{C}$ 는 $B-C$ 와 같으므로 하나의 식으로 쓸 수 있다.","확인":null,"스킬":"C4"},{"제목":"같은 식의 선지 고르기","힌트":"$A\\cap(B-C)$ 와 같은 영역을 나타내는 선지는?","식":["④ $A\\cap(B-C)$"],"설명":"④ 가 같은 식이다. ① 은 $A$ 에서 일부만 빼므로 $A\\cap C$ 를 포함하고, ② 와 ⑤ 는 $C$ 안의 부분이며, ③ 은 $C$ 밖 전체를 포함하므로 모두 색칠한 영역과 다르다.","확인":null,"스킬":"C4"}]},"ns-c152c369e68a":{"길":"빗금친 영역을 교집합으로 쓰고 드모르간 법칙으로 선지를 고친다","단계":[{"제목":"빗금친 부분을 집합으로 나타내기","힌트":"빗금친 부분은 $A,\\ B,\\ C$ 각각의 안과 밖 중 어디에 있을까?","식":["$A\\cap B\\cap C^{C}$","$=A\\cap(B\\cap C^{C})$"],"설명":"빗금친 부분은 $A$ 와 $B$ 가 겹치는 곳 중 $C$ 에 속하지 않는 부분이다. 세 조건을 모두 만족하는 영역이므로 세 집합의 교집합으로 쓴다.","확인":null,"스킬":"C4"},{"제목":"드모르간 법칙으로 선지 식 정리하기","고비":true,"힌트":"선지 ① 의 $(B^{C}\\cup C)^{C}$ 에 드모르간 법칙을 쓰면?","식":["$(B^{C}\\cup C)^{C}=(B^{C})^{C}\\cap C^{C}$","$=B\\cap C^{C}$","$A\\cap(B^{C}\\cup C)^{C}=A\\cap B\\cap C^{C}$"],"설명":"합집합의 여집합은 각 여집합의 교집합이다. $(B^{C})^{C}=B$ 이므로 ① 은 $A\\cap B\\cap C^{C}$ 가 되어 빗금친 부분과 같다.","확인":null,"스킬":"C4"},{"제목":"나머지 선지가 다름을 확인하기","힌트":"④, ③ 도 같은 방법으로 정리하면 어떤 영역이 될까?","식":["$A\\cap(B\\cup C)^{C}=A\\cap B^{C}\\cap C^{C}$","$A\\cap(B\\cup C^{C})^{C}=A\\cap B^{C}\\cap C$"],"설명":"④ 는 $A$ 에서 $B$, $C$ 를 모두 벗어난 부분이고, ③ 은 $A$ 와 $C$ 의 공통부분 중 $B$ 밖이라 빗금친 부분과 다르다. ② 와 ⑤ 는 $A$ 전체를 포함하는 합집합이라 영역이 훨씬 넓다.","확인":null,"스킬":"C4"}]},"ns-d37b21e4f92c":{"길":"색칠하지 않은 부분이 하나뿐이므로 그 여집합으로 나타낸다","단계":[{"제목":"색칠하지 않은 부분 읽기","고비":true,"힌트":"색칠하지 않은 부분은 $A,\\ B$ 각각의 안과 밖 중 어디에 있을까?","식":["$A-B=A\\cap B^{C}$"],"설명":"색칠하지 않은 곳은 $A$ 에는 속하고 $B$ 에는 속하지 않는 부분 하나뿐이다. 이 부분은 $A-B$ 이다.","확인":null,"스킬":"C4"},{"제목":"여집합으로 색칠한 부분 나타내기","힌트":"전체집합에서 색칠하지 않은 부분을 빼면 색칠한 부분은 어떻게 쓸까?","식":["$\\mathrm{U}-(A\\cap B^{C})=(A\\cap B^{C})^{C}$"],"설명":"전체집합 중 $A-B$ 만 색칠되지 않았으므로 색칠한 부분은 $A-B$ 의 여집합이다.","확인":null,"스킬":"C4"},{"제목":"선지와 대조하기","힌트":"$(A\\cap B^{C})^{C}$ 와 같은 식은 어느 선지일까?","식":["④ $(A\\cap B^{C})^{C}$"],"설명":"④ 가 같은 식이다. ① 은 색칠하지 않은 부분 자체이고, ② 는 $(A\\cap B)^{C}$ 라서 색칠한 $A\\cap B$ 가 빠진다. ③ 은 $(A\\cup B)^{C}$ 로 두 원 밖만이고, ⑤ 는 겹치지 않는 부분만이라 모두 다르다.","확인":null,"스킬":"C4"}]},"ns-d93f9f906b34":{"길":"그림에서 영역마다 원소를 읽어 선지를 하나씩 대조한다","단계":[{"제목":"벤다이어그램에서 A, B 의 원소 읽기","고비":true,"힌트":"그림에서 $A$ 의 안, $B$ 의 안, 둘의 겹친 부분에 각각 어떤 수가 있을까?","식":["$A=\\{1,\\ 2,\\ 5,\\ 7\\},\\quad B=\\{2,\\ 3,\\ 7,\\ 9\\}$","$U=\\{1,\\ 2,\\ 3,\\ 4,\\ 5,\\ 6,\\ 7,\\ 8,\\ 9\\}$"],"설명":"원 $A$ 안의 수가 $A$ 의 원소이고, 두 원이 겹친 부분의 $2,\\ 7$ 은 $A$ 와 $B$ 에 모두 속한다. 원 밖의 $4,\\ 6,\\ 8$ 은 전체집합에만 속한다.","확인":null,"스킬":"C4"},{"제목":"선지의 집합을 하나씩 구해 대조하기","힌트":"$A\\cap B^{C}$ 은 $A$ 의 원소 중 $B$ 에 속하지 않는 것이다. 어떤 수일까?","식":["$A\\cap B^{C}=\\{1,\\ 5\\}$","$A\\cup B=\\{1,\\ 2,\\ 3,\\ 5,\\ 7,\\ 9\\},\\quad A\\cap B=\\{2,\\ 7\\}$","$(B-A)^{C}=\\{3,\\ 9\\}^{C}=\\{1,\\ 2,\\ 4,\\ 5,\\ 6,\\ 7,\\ 8\\}$"],"설명":"② 만 $\\{1,\\ 5\\}$ 로 일치한다. ① 과 ⑤ 는 합집합과 교집합의 값이 서로 바뀌어 있고, ③ 은 원소의 개수 $n(A)$ 를 집합처럼 썼으며, ④ 는 $2,\\ 7$ 이 빠져 있어 옳지 않다.","확인":null,"스킬":"C4"}]},"ns-0a86d8ef5bbb":{"길":"3의 배수가 아닌 수를 3k+1, 3k+2로 나눠 제곱을 3으로 묶는다","단계":[{"제목":"3의 배수가 아닌 수의 두 번째 꼴 정하기","힌트":"$3$ 으로 나눈 나머지가 $0$ 이 아닌 자연수는 $3k+1$ 말고 어떤 꼴일까?","식":["$n=3k,\\ 3k+1,\\ 3k+2$","$f(k)=3k+2$"],"설명":"자연수를 $3$ 으로 나눈 나머지는 $0,\\ 1,\\ 2$ 뿐이다. 나머지 $0$ 은 $3$ 의 배수이므로 나머지 $1$ 인 $3k+1$ 과 나머지 $2$ 인 $3k+2$ 로 나눈다. ⅱ) 의 $n^{2}=3(3k^{2}+4k+1)+1$ 도 $(3k+2)^{2}$ 과 같다.","확인":null,"스킬":"N3"},{"제목":"제곱을 3으로 묶어 (가), (다) 구하기","고비":true,"힌트":"$(3k+1)^{2}$ 을 전개해서 $3\\times(\\ )+1$ 꼴로 묶으면 괄호 안은?","식":["$(3k+1)^{2}=9k^{2}+6k+1=3(3k^{2}+2k)+1$","$(3k+2)^{2}=9k^{2}+12k+4=3(3k^{2}+4k+1)+1$","$g(k)=3k^{2}+2k$"],"설명":"두 경우 모두 $3\\times(\\ )+1$ 꼴이 되므로 나머지는 $1$ 이고 (가) 는 $1$ 이다. ⅰ) 의 괄호 안이 (다) 이다.","확인":"1","스킬":"N3"},{"제목":"f(a)+g(a) 의 값 구하기","힌트":"$a=1$ 을 $f(k),\\ g(k)$ 에 각각 넣으면?","식":["$f(1)=3+2=5$","$g(1)=3+2=5$","$f(1)+g(1)=10$"],"설명":"(가) 가 $1$ 이므로 $a=1$ 이다. $k$ 대신 $1$ 을 대입해 두 값을 더한다.","확인":"10","스킬":"N3"}]},"ns-0c8057105186":{"길":"필요·충분 조건을 구간의 포함 관계로 바꿔 a, b 의 범위를 구한다","단계":[{"제목":"세 조건의 진리집합을 구간으로 나타내기","힌트":"$p,\\ q,\\ r$ 을 만족하는 $x$ 의 범위를 수직선 위의 구간으로 쓰면?","식":["$P=\\{x\\mid x^{2}-x\\le0\\}=\\{x\\mid 0\\le x\\le1\\}$","$Q=\\left\\{x\\mid 1-\\dfrac{1}{a}\\le x\\le1+\\dfrac{1}{a}\\right\\}$","$R=\\{x\\mid x\\ge b\\}$"],"설명":"$x^{2}-x=x(x-1)\\le0$ 에서 $0\\le x\\le1$ 이다. $|x-1|\\le\\frac{1}{a}$ 는 $x$ 가 $1$ 에서 $\\frac{1}{a}$ 이하만큼 떨어진 범위를 뜻한다.","확인":null,"스킬":"C4"},{"제목":"필요·충분 조건을 포함 관계로 바꾸기","고비":true,"힌트":"$r$ 이 $q$ 이기 위한 필요조건이면 $Q$ 와 $R$ 중 어느 쪽이 더 큰 집합일까?","식":["$q\\Rightarrow r\\ \\iff\\ Q\\subset R$","$p\\Rightarrow q\\ \\iff\\ P\\subset Q$"],"설명":"$r$ 이 $q$ 이기 위한 필요조건이면 $q\\Rightarrow r$ 이고, $p$ 가 $q$ 이기 위한 충분조건이면 $p\\Rightarrow q$ 이다. 진리집합에서는 화살표의 앞쪽 조건의 집합이 뒤쪽 조건의 집합의 부분집합이다.","확인":null,"스킬":"C4"},{"제목":"P ⊂ Q 에서 a 의 범위 구하기","힌트":"$Q$ 의 왼쪽 끝 $1-\\frac{1}{a}$ 이 $P$ 의 왼쪽 끝 $0$ 보다 작거나 같으려면 $a$ 는?","식":["$1-\\dfrac{1}{a}\\le0,\\quad 1+\\dfrac{1}{a}\\ge1$","$\\dfrac{1}{a}\\ge1$","$0<a\\le1$"],"설명":"$P=[0,\\ 1]$ 이 $Q$ 안에 들어가려면 왼쪽 끝은 $Q$ 가 더 작거나 같고 오른쪽 끝은 $Q$ 가 더 크거나 같아야 한다. $a>0$ 이면 오른쪽 끝 조건은 항상 성립하므로 왼쪽 끝 조건만 남는다.","확인":null,"스킬":"C4"},{"제목":"Q ⊂ R 에서 b 의 범위 구하기","힌트":"$Q$ 의 모든 원소가 $x\\ge b$ 를 만족하려면 $Q$ 의 왼쪽 끝과 $b$ 의 관계는?","식":["$1-\\dfrac{1}{a}\\ge b$","$b\\le1-\\dfrac{1}{a}$"],"설명":"$R$ 은 $b$ 이상의 모든 수이므로 $Q$ 의 가장 왼쪽 점이 $b$ 이상이면 $Q$ 전체가 $R$ 안에 들어간다.","확인":null,"스킬":"C4"},{"제목":"점 (a, b) 의 영역을 그래프에서 고르기","힌트":"$0<a\\le1$ 이고 $b\\le1-\\frac{1}{a}$ 인 점은 곡선 $b=1-\\frac{1}{a}$ 의 어느 쪽에 있을까?","식":["$0<a\\le1,\\quad b\\le1-\\dfrac{1}{a}$","$a=1\\ \\Rightarrow\\ b\\le0$","$a=\\dfrac{1}{2}\\ \\Rightarrow\\ b\\le-1$"],"설명":"곡선 $b=1-\\frac{1}{a}$ 은 $a$ 가 $0$ 에 가까울수록 아래로 내려가고 $a=1$ 에서 $b=0$ 이다. 영역은 이 곡선의 아래쪽이고 직선 $a=1$ 의 왼쪽이므로, 곡선과 $a=1$ 사이의 아래로 뻗은 영역인 ② 이다.","확인":null,"스킬":"C4"}]},"ns-0f6d46a6818b":{"길":"역이 참이면 q 의 진리집합이 p 의 진리집합에 들어가므로 구간 끝을 비교한다","단계":[{"제목":"p 의 진리집합을 구간으로 구하기","힌트":"절댓값 안이 $0$ 이 되는 $x=1,\\ 3$ 을 경계로 구간을 나누어 풀면?","식":["$x<1$ 일 때 : $4-2x<8\\ \\Rightarrow\\ -2<x<1$","$1\\le x\\le3$ 일 때 : $2<8$ (항상 성립)","$x>3$ 일 때 : $2x-4<8\\ \\Rightarrow\\ 3<x<6$"],"설명":"$x<1$ 에서는 $(1-x)+(3-x)$, $x>3$ 에서는 $(x-1)+(x-3)$ 이고 그 사이에서는 합이 항상 $2$ 이다. 세 구간의 결과를 합치면 $P=\\{x\\mid -2<x<6\\}$ 이다.","확인":null,"스킬":"C2"},{"제목":"역이 참일 조건을 포함 관계로 바꾸기","고비":true,"힌트":"$p\\to q$ 의 역은 무엇이고, 그것이 참이면 $P$ 와 $Q$ 의 관계는?","식":["$q\\Rightarrow p\\ \\iff\\ Q\\subset P$","$Q=\\{x\\mid 4-k<x<4+k\\}$","$4-k\\ge-2,\\quad 4+k\\le6$"],"설명":"$p\\to q$ 의 역은 $q\\to p$ 이다. 이것이 참이면 $Q\\subset P$ 이므로 $Q$ 의 양 끝이 $P$ 의 양 끝 $-2,\\ 6$ 의 안쪽이어야 한다.","확인":null,"스킬":"C4"},{"제목":"k 의 최댓값 구하기","힌트":"두 부등식에서 나온 $k$ 의 범위를 동시에 만족하는 가장 큰 값은?","식":["$k\\le6,\\quad k\\le2$","$0<k\\le2$"],"설명":"$4-k\\ge-2$ 에서 $k\\le6$, $4+k\\le6$ 에서 $k\\le2$ 이다. 둘을 모두 만족하려면 $k\\le2$ 이므로 양수 $k$ 의 최댓값은 $2$ 이다.","확인":"2","스킬":"C4"}]},"ns-103ad7904abb":{"길":"접힌 각을 따라 검은 삼각형의 넓이를 한 문자의 식으로 만든 뒤 산술·기하 평균을 쓴다","단계":[{"제목":"접은 도형에서 검은 삼각형의 변과 각 찾기","고비":true,"힌트":"접어도 변 $\\mathrm{PB}$ 의 길이와 $\\angle\\mathrm{BPD}$ 는 어떻게 될까?","식":["$\\overline{\\mathrm{PB}'}=\\overline{\\mathrm{PB}}=x,\\quad \\angle\\mathrm{PB}'\\mathrm{Q}=90^\\circ$","$\\angle\\mathrm{DPC}=\\varphi,\\quad \\tan\\varphi=\\dfrac{2}{2-x}$","$\\angle\\mathrm{DPB}'=\\angle\\mathrm{DPB}=180^\\circ-\\varphi\\ \\Rightarrow\\ \\angle\\mathrm{B}'\\mathrm{PQ}=180^\\circ-2\\varphi$"],"설명":"직선 $\\mathrm{A}'\\mathrm{B}'$ 과 직선 $\\mathrm{BC}$ 가 만나는 점을 $\\mathrm{Q}$ 라 하면 검은 삼각형은 $\\mathrm{PB}'\\mathrm{Q}$ 이다. $\\mathrm{B}'$ 에서의 각은 정사각형의 꼭짓점 각 $90^\\circ$ 이고 $\\overline{\\mathrm{PB}'}=x$ 이다. 직선 $\\mathrm{BC}$ 위에서 $\\angle\\mathrm{BPD}=180^\\circ-\\varphi$ 가 접혀 $\\angle\\mathrm{DPB}'$ 가 되므로, 여기서 $\\varphi$ 를 한 번 더 빼면 $\\angle\\mathrm{B}'\\mathrm{PQ}$ 가 나온다.","확인":null,"스킬":"S10"},{"제목":"tan 값을 x 의 식으로 나타내기","힌트":"배각 공식으로 $\\tan2\\varphi$ 를 $\\tan\\varphi$ 로 쓰고 $x$ 를 넣으면?","식":["$\\tan(180^\\circ-2\\varphi)=-\\tan2\\varphi=-\\dfrac{2\\tan\\varphi}{1-\\tan^{2}\\varphi}$","$=\\dfrac{4(2-x)}{x(4-x)}$"],"설명":"$\\tan\\varphi=\\frac{2}{2-x}$ 를 대입하면 분자는 $-\\frac{4}{2-x}$ 이고 분모는 $\\frac{x(x-4)}{(2-x)^{2}}$ 이다. 약분하면 위의 값이 된다.","확인":null,"스킬":"S6"},{"제목":"검은 삼각형의 넓이를 x 의 식으로 쓰기","힌트":"직각삼각형 $\\mathrm{PB}'\\mathrm{Q}$ 에서 $\\overline{\\mathrm{PB}'}$ 와 $\\tan$ 값으로 $\\overline{\\mathrm{B}'\\mathrm{Q}}$ 를 구하면?","식":["$\\overline{\\mathrm{B}'\\mathrm{Q}}=x\\tan(180^\\circ-2\\varphi)=\\dfrac{4(2-x)}{4-x}$","$S=\\dfrac{1}{2}\\cdot x\\cdot\\dfrac{4(2-x)}{4-x}=\\dfrac{2x(2-x)}{4-x}$"],"설명":"각 $\\mathrm{P}$ 의 $\\tan$ 값은 $\\frac{\\overline{\\mathrm{B}'\\mathrm{Q}}}{\\overline{\\mathrm{PB}'}}$ 이므로 $\\overline{\\mathrm{B}'\\mathrm{Q}}$ 는 $x$ 에 그 값을 곱한 것이다. 두 직각변의 곱의 절반이 넓이이다.","확인":null,"스킬":"S6"},{"제목":"분모를 문자로 치환해 정리하기","힌트":"분모 $4-x$ 를 $s$ 로 놓고 분자를 $s$ 의 식으로 바꾸면?","식":["$s=4-x\\ (2<s<4),\\quad x=4-s,\\ 2-x=s-2$","$S=\\dfrac{2(4-s)(s-2)}{s}=\\dfrac{2(-s^{2}+6s-8)}{s}$","$S=2\\left(6-s-\\dfrac{8}{s}\\right)$"],"설명":"점 $\\mathrm{P}$ 가 변 $\\mathrm{BC}$ 위에 있으므로 $0<x<2$ 이고 $s$ 의 범위는 $2<s<4$ 이다. 분자를 전개해 $s$ 로 나누면 $s$ 와 $\\frac{8}{s}$ 의 합이 나타난다.","확인":null,"스킬":"A1"},{"제목":"산술·기하 평균으로 최댓값 구하기","힌트":"$s+\\dfrac{8}{s}$ 의 최솟값을 산술·기하 평균으로 구하면?","식":["$s+\\dfrac{8}{s}\\ge2\\sqrt{s\\cdot\\dfrac{8}{s}}=4\\sqrt{2}$","등호 : $s=\\dfrac{8}{s}\\ \\Rightarrow\\ s=2\\sqrt{2}$","$S\\le2\\left(6-4\\sqrt{2}\\right)=12-8\\sqrt{2}$"],"설명":"$s>0$ 이므로 산술·기하 평균을 쓸 수 있다. $s+\\frac{8}{s}$ 가 최소일 때 $S$ 가 최대이고, 등호의 조건 $s=2\\sqrt{2}$ 는 $2<s<4$ 안에 있으므로 이 최댓값이 실제로 나타난다.","확인":null,"스킬":"A7"}]},"ns-11e1f8315374":{"길":"절편으로 직선을 쓰고 산술·기하 평균으로 두 절편의 곱을 누른다","단계":[{"제목":"점 P 를 지나는 직선을 절편 꼴로 쓰기","힌트":"$x$ 절편을 $a$, $y$ 절편을 $b$ 라 하면 직선의 식과 점 $\\mathrm{P}$ 의 조건은?","식":["$\\dfrac{x}{a}+\\dfrac{y}{b}=1\\quad(a>0,\\ b>0)$","$\\dfrac{3}{a}+\\dfrac{4}{b}=1$"],"설명":"기울기가 음수이고 점 $\\mathrm{P}$ 가 제1사분면에 있으므로 두 절편은 모두 양수이다. 직선이 $\\mathrm{P}(3,\\ 4)$ 를 지나므로 $x=3,\\ y=4$ 를 대입한다.","확인":null,"스킬":"G3"},{"제목":"삼각형의 넓이를 절편으로 나타내기","힌트":"$\\overline{\\mathrm{OA}}=a,\\ \\overline{\\mathrm{OB}}=b$ 인 직각삼각형의 넓이는?","식":["$S=\\dfrac{1}{2}ab$"],"설명":"넓이를 최소로 만들려면 $ab$ 를 최소로 만들면 된다. 앞 단계의 식으로 $ab$ 의 범위를 알아낸다.","확인":null,"스킬":"G10"},{"제목":"산술·기하 평균으로 ab 의 최솟값 구하기","고비":true,"힌트":"$\\dfrac{3}{a}$ 와 $\\dfrac{4}{b}$ 의 합이 $1$ 이라는 식에 산술·기하 평균을 쓰면?","식":["$1=\\dfrac{3}{a}+\\dfrac{4}{b}\\ge2\\sqrt{\\dfrac{12}{ab}}$","$\\sqrt{ab}\\ge2\\sqrt{12}\\ \\Rightarrow\\ ab\\ge48$"],"설명":"$\\frac{3}{a},\\ \\frac{4}{b}$ 는 모두 양수라서 산술·기하 평균을 쓸 수 있다. 양변이 양수이므로 제곱하면 $ab$ 의 하한이 나온다. 등호는 $\\frac{3}{a}=\\frac{4}{b}=\\frac{1}{2}$, 곧 $a=6,\\ b=8$ 일 때 성립한다.","확인":"48","스킬":"A7"},{"제목":"넓이의 최솟값 구하기","힌트":"$S=\\dfrac{1}{2}ab$ 에 $ab$ 의 최솟값을 넣으면?","식":["$S\\ge\\dfrac{1}{2}\\times48=24$"],"설명":"$a=6,\\ b=8$ 이면 직선 $\\frac{x}{6}+\\frac{y}{8}=1$ 은 점 $(3,\\ 4)$ 를 지나고 기울기가 $-\\frac{4}{3}$ 로 음수이다. 따라서 최솟값 $24$ 가 실제로 나타난다.","확인":"24","스킬":"A7"}]},"ns-1fe8daf6413e":{"길":"R 이 Q 안에 있음을 쓰고 진리집합의 식을 줄여 포함 방향을 본다","단계":[{"제목":"벤다이어그램에서 포함 관계 읽기","힌트":"그림에서 $R$ 은 $Q$ 와 어떤 위치에 있을까?","식":["$R\\subset Q$","$Q^{C}\\cap R=\\varnothing$"],"설명":"원 $R$ 은 원 $Q$ 안에 완전히 들어 있으므로 $R\\subset Q$ 이다. 따라서 $Q$ 밖에 있는 $R$ 의 원소는 없다. $P$ 는 $Q$, $R$ 과 일부만 겹친다.","확인":null,"스킬":"C4"},{"제목":"(1) s 와 ∼p 의 관계 판정하기","힌트":"$s$ 의 진리집합 $(P\\cup R)^{C}\\cap Q$ 는 $P^{C}$ 안에 들어갈까?","식":["$(P\\cup R)^{C}\\cap Q=Q-(P\\cup R)$","$Q-(P\\cup R)\\subset P^{C}$"],"설명":"$P$ 와 $R$ 을 뺀 부분이므로 $P$ 에 속하지 않고, 따라서 $P^{C}$ 의 부분집합이다. $s\\Rightarrow\\sim p$ 이므로 충분조건이다. $P^{C}$ 에는 $Q$ 밖의 원소도 있어 역은 성립하지 않는다.","확인":null,"스킬":"C4"},{"제목":"(2) ∼t 와 ∼r 의 관계 판정하기","힌트":"$R\\subset Q$ 이면 $\\left(Q^{C}\\cap R\\right)^{C}$ 는 어떤 집합이 될까?","식":["$\\left(Q^{C}\\cap R\\right)^{C}=\\varnothing^{C}=U$","$T=(P\\cup Q)\\cap U=P\\cup Q$","$(P\\cup Q)^{C}\\subset R^{C}\\ \\iff\\ R\\subset P\\cup Q$"],"설명":"$Q^{C}\\cap R$ 이 공집합이라 그 여집합은 전체집합이고, $t$ 의 진리집합은 $P\\cup Q$ 가 된다. $R\\subset Q\\subset P\\cup Q$ 이므로 $\\sim t\\Rightarrow\\sim r$ 이 성립해 충분조건이다. 역은 $(P\\cup Q)^{C}$ 가 $R^{C}$ 보다 작아 성립하지 않는다.","확인":null,"스킬":"C4"},{"제목":"(3) u 와 r 의 관계 판정하기","고비":true,"힌트":"$Q-P^{C}$ 를 교집합으로 바꾸면 $u$ 의 진리집합은 어떻게 줄어들까?","식":["$Q-P^{C}=Q\\cap P,\\quad P-(Q\\cap P)^{C}=P\\cap Q$","$(P\\cap Q)\\cup(Q-P)=Q$","$R\\subset Q\\ \\Rightarrow\\ r\\Rightarrow u$"],"설명":"$Q-P^{C}=Q\\cap(P^{C})^{C}=Q\\cap P$ 이다. 이를 대입하면 $P\\cap Q$ 와 $Q-P$ 를 합쳐 $Q$ 전체가 된다. $r\\Rightarrow u$ 이므로 $u$ 는 $r$ 이기 위한 필요조건이고, $Q\\subset R$ 이 아니어서 충분조건은 아니다.","확인":null,"스킬":"C4"},{"제목":"(가), (나), (다) 를 모아 선지 고르기","힌트":"세 판정 결과를 순서대로 모으면 어느 선지일까?","식":["(가) 충분, (나) 충분, (다) 필요"],"설명":"(가) 충분, (나) 충분, (다) 필요이므로 ① 이 답이다.","확인":null,"스킬":"C4"}]},"ns-230d0b27b02b":{"길":"닮음비로 두 높이를 구해 넓이의 합을 x 의 식으로 쓰고 산술·기하 평균을 쓴다","단계":[{"제목":"닮음비로 두 삼각형의 높이 구하기","고비":true,"힌트":"$\\overline{\\mathrm{AP}}\\,/\\!/\\,\\overline{\\mathrm{DC}}$ 이면 두 삼각형의 닮음비와 두 높이의 합은?","식":["$\\triangle\\mathrm{QAP}\\backsim\\triangle\\mathrm{QCD}$, 닮음비 $x:2$","$h_{1}+h_{2}=\\overline{\\mathrm{AD}}=1,\\quad h_{1}:h_{2}=x:2$","$h_{1}=\\dfrac{x}{x+2},\\quad h_{2}=\\dfrac{2}{x+2}$"],"설명":"$\\overline{\\mathrm{AB}}\\,/\\!/\\,\\overline{\\mathrm{DC}}$ 이므로 엇각이 같아 두 삼각형은 닮음이고 밑변의 비가 $x:2$ 이다. $\\mathrm{Q}$ 에서 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{DC}}$ 까지의 거리 $h_{1},\\ h_{2}$ 의 합은 두 변 사이의 거리 $1$ 이고, 그 비도 닮음비와 같다.","확인":null,"스킬":"S1"},{"제목":"넓이의 합 S 를 x 의 식으로 쓰기","힌트":"두 삼각형의 넓이를 밑변과 높이로 각각 쓰고 더하면?","식":["$S=\\dfrac{1}{2}\\cdot x\\cdot\\dfrac{x}{x+2}+\\dfrac{1}{2}\\cdot2\\cdot\\dfrac{2}{x+2}$","$S=\\dfrac{x^{2}+4}{2(x+2)}$"],"설명":"$\\triangle\\mathrm{QAP}$ 의 밑변은 $x$, $\\triangle\\mathrm{QCD}$ 의 밑변은 $2$ 이다. 높이를 넣고 분모를 같게 하여 합친다.","확인":null,"스킬":"S8"},{"제목":"x+2 를 덩어리로 보고 식 정리하기","힌트":"분자 $x^{2}+4$ 를 $(x+2)$ 의 식으로 바꾸면?","식":["$x^{2}+4=(x+2)^{2}-4(x+2)+8$","$S=\\dfrac{1}{2}\\left\\{(x+2)+\\dfrac{8}{x+2}\\right\\}-2$"],"설명":"$(x+2)^{2}$ 을 전개하면 $x^{2}+4x+4$ 이므로 $x^{2}+4$ 에서 $4(x+2)$ 를 빼고 $8$ 을 더하면 같은 식이 된다. 분모의 $x+2$ 로 나누면 곱이 상수인 두 항이 나타난다.","확인":null,"스킬":"A1"},{"제목":"산술·기하 평균으로 S 의 최솟값과 x 구하기","힌트":"$(x+2)+\\dfrac{8}{x+2}$ 의 최솟값과 등호가 성립하는 $x$ 는?","식":["$(x+2)+\\dfrac{8}{x+2}\\ge2\\sqrt{8}=4\\sqrt{2}$","등호 : $x+2=2\\sqrt{2}\\ \\Rightarrow\\ x=2\\sqrt{2}-2$","$S\\ge\\dfrac{1}{2}\\cdot4\\sqrt{2}-2=2\\sqrt{2}-2$"],"설명":"$x+2>0$ 이므로 산술·기하 평균을 쓴다. 등호 조건의 $x=2\\sqrt{2}-2$ 는 $0<x<2$ 안에 있으므로 최솟값이 실제로 나타난다.","확인":null,"스킬":"A7"},{"제목":"최솟값과 그때의 x 의 합 구하기","힌트":"구한 두 값 $S$ 의 최솟값과 $x$ 를 더하면?","식":["$(2\\sqrt{2}-2)+(2\\sqrt{2}-2)=4\\sqrt{2}-4=4(\\sqrt{2}-1)$"],"설명":"최솟값과 그때의 $x$ 가 우연히 같은 값 $2\\sqrt{2}-2$ 이므로 두 배 하면 된다.","확인":null,"스킬":"A7"}]},"ns-2581e5835489":{"길":"넓이를 점 P 의 좌표로 쓰고 직선의 식을 곱해 산술·기하 평균을 쓴다","단계":[{"제목":"두 삼각형의 넓이를 a, b 로 나타내기","힌트":"밑변을 $x$ 축 위의 $\\overline{\\mathrm{AB}}$, $y$ 축 위의 $\\overline{\\mathrm{CD}}$ 로 보면 높이는 각각 무엇일까?","식":["$S_{1}=\\dfrac{1}{2}\\cdot\\overline{\\mathrm{AB}}\\cdot b=b$","$S_{2}=\\dfrac{1}{2}\\cdot\\overline{\\mathrm{CD}}\\cdot a=a$","$b=-2a+4\\ \\Rightarrow\\ 2a+b=4\\quad(a>0,\\ b>0)$"],"설명":"$\\overline{\\mathrm{AB}}=2$ 이고 점 $\\mathrm{P}$ 에서 $x$ 축까지의 거리는 $b$ 이다. $\\overline{\\mathrm{CD}}=2$ 이고 $y$ 축까지의 거리는 $a$ 이다. 점 $\\mathrm{P}$ 가 직선 위에 있으므로 $a,\\ b$ 사이에 $2a+b=4$ 가 성립한다.","확인":null,"스킬":"G10"},{"제목":"구하는 식에 2a+b=4 를 이용해 곱 꼴 만들기","고비":true,"힌트":"$\\dfrac{2}{b}+\\dfrac{1}{a}$ 에 $\\dfrac{2a+b}{4}=1$ 을 곱해 전개하면?","식":["$\\dfrac{2}{S_{1}}+\\dfrac{1}{S_{2}}=\\dfrac{2}{b}+\\dfrac{1}{a}$","$=\\dfrac{1}{4}\\left(\\dfrac{2}{b}+\\dfrac{1}{a}\\right)(2a+b)=\\dfrac{1}{4}\\left(4+\\dfrac{4a}{b}+\\dfrac{b}{a}\\right)$"],"설명":"$2a+b=4$ 이므로 $\\frac{2a+b}{4}=1$ 이고, 이를 곱해도 값은 변하지 않는다. 전개하면 곱이 상수가 되는 두 항 $\\frac{4a}{b},\\ \\frac{b}{a}$ 가 생긴다.","확인":null,"스킬":"A7"},{"제목":"산술·기하 평균으로 괄호 안의 최솟값 구하기","힌트":"$\\dfrac{4a}{b}$ 와 $\\dfrac{b}{a}$ 의 합의 최솟값은?","식":["$\\dfrac{4a}{b}+\\dfrac{b}{a}\\ge2\\sqrt{\\dfrac{4a}{b}\\cdot\\dfrac{b}{a}}=4$","$4+\\dfrac{4a}{b}+\\dfrac{b}{a}\\ge8$"],"설명":"$a,\\ b$ 가 양수이므로 두 항도 양수라서 산술·기하 평균을 쓸 수 있다. 곱이 $4$ 로 상수가 되어 합의 하한이 정해진다.","확인":"8","스킬":"A7"},{"제목":"최솟값과 등호 조건 확인하기","힌트":"앞의 $\\dfrac{1}{4}$ 을 곱하고, 등호가 성립하는 $a,\\ b$ 가 직선 위에 있는지 확인하면?","식":["$\\dfrac{1}{4}\\times8=2$","등호 : $\\dfrac{4a}{b}=\\dfrac{b}{a}\\ \\Rightarrow\\ b=2a\\ \\Rightarrow\\ a=1,\\ b=2$"],"설명":"$b=2a$ 를 $2a+b=4$ 에 넣으면 $a=1,\\ b=2$ 이다. 점 $(1,\\ 2)$ 는 직선 $y=-2x+4$ 위에 있어 최솟값 $2$ 가 실제로 나타난다.","확인":"2","스킬":"A7"}]},"ns-2f82735a7db1":{"길":"넓이를 4q/p 와 9p/q 의 합으로 쓰고 산술·기하 평균의 등호 조건을 쓴다","단계":[{"제목":"두 점의 좌표 놓기","힌트":"두 점이 각각 곡선 위에 있고 제1사분면, 제4사분면에 있으면 좌표를 $p,\\ q$ 로 어떻게 쓸까?","식":["$\\mathrm{P}\\left(p,\\ \\dfrac{4}{p}\\right),\\quad \\mathrm{Q}\\left(q,\\ -\\dfrac{9}{q}\\right)$","$p>0,\\ q>0$"],"설명":"점 $\\mathrm{P}$ 는 $y=\\frac{4}{x}$ 위에 있고 $x$ 좌표가 $p$ 이므로 $y$ 좌표는 $\\frac{4}{p}$ 이다. 점 $\\mathrm{Q}$ 는 제4사분면에 있으므로 $x$ 좌표 $q$ 는 양수이고 $y$ 좌표는 $-\\frac{9}{q}$ 이다.","확인":null,"스킬":"G10"},{"제목":"삼각형 OPQ 의 넓이를 p, q 의 식으로 쓰기","고비":true,"힌트":"원점과 두 점 $\\mathrm{P},\\ \\mathrm{Q}$ 로 이루어진 삼각형의 넓이를 좌표로 구하면?","식":["$S=\\dfrac{1}{2}\\left|p\\cdot\\left(-\\dfrac{9}{q}\\right)-q\\cdot\\dfrac{4}{p}\\right|$","$S=\\dfrac{1}{2}\\left(\\dfrac{9p}{q}+\\dfrac{4q}{p}\\right)$"],"설명":"원점과 $(x_{1},\\ y_{1}),\\ (x_{2},\\ y_{2})$ 로 이루어진 삼각형의 넓이는 $\\frac{1}{2}|x_{1}y_{2}-x_{2}y_{1}|$ 이다. 절댓값 안의 값이 음수이므로 부호를 바꾸면 두 양수의 합이 된다.","확인":null,"스킬":"G10"},{"제목":"산술·기하 평균으로 최솟값과 등호 조건 구하기","힌트":"$\\dfrac{9p}{q}$ 와 $\\dfrac{4q}{p}$ 의 합의 최솟값과 등호가 성립할 조건은?","식":["$S\\ge\\dfrac{1}{2}\\cdot2\\sqrt{\\dfrac{9p}{q}\\cdot\\dfrac{4q}{p}}=6$","등호 : $\\dfrac{9p}{q}=\\dfrac{4q}{p}\\ \\Rightarrow\\ 9p^{2}=4q^{2}\\ \\Rightarrow\\ 3p=2q$"],"설명":"두 항이 양수이고 곱이 $36$ 으로 상수이므로 산술·기하 평균을 쓸 수 있다. 넓이가 최소가 되는 때는 등호가 성립하는 때이다.","확인":"6","스킬":"A7"},{"제목":"10q/p 의 값 구하기","힌트":"$3p=2q$ 에서 $\\dfrac{q}{p}$ 의 값은?","식":["$\\dfrac{q}{p}=\\dfrac{3}{2}$","$\\dfrac{10q}{p}=10\\times\\dfrac{3}{2}=15$"],"설명":"$p,\\ q$ 가 양수이므로 $3p=2q$ 의 양변을 $2p$ 로 나누면 $\\frac{q}{p}=\\frac{3}{2}$ 이다.","확인":"15","스킬":"A8"}]},"ns-2ff803072364":{"길":"코시-슈바르츠 부등식으로 최댓값을 구하고 등호 조건으로 x, y, z 의 값을 정한다","단계":[{"제목":"코시-슈바르츠 부등식으로 최댓값 구하기","고비":true,"힌트":"계수 $1,\\ 2,\\ 1$ 의 제곱의 합과 $x^{2}+y^{2}+z^{2}$ 의 곱을 $(x+2y+z)^{2}$ 과 비교하면?","식":["$(1^{2}+2^{2}+1^{2})(x^{2}+y^{2}+z^{2})\\ge(x+2y+z)^{2}$","$(x+2y+z)^{2}\\le6\\times3=18$","$x+2y+z\\le3\\sqrt{2}\\ \\Rightarrow\\ \\alpha=3\\sqrt{2}$"],"설명":"코시-슈바르츠 부등식에 계수 $(1,\\ 2,\\ 1)$ 과 $(x,\\ y,\\ z)$ 를 넣는다. $x^{2}+y^{2}+z^{2}=3$ 이므로 우변이 상수가 되어 $x+2y+z$ 의 상한이 정해진다.","확인":null,"스킬":"A7"},{"제목":"등호 조건으로 x, y, z 의 값 정하기","힌트":"등호가 성립하려면 $(x,\\ y,\\ z)$ 와 $(1,\\ 2,\\ 1)$ 은 어떤 관계여야 할까?","식":["$x:y:z=1:2:1\\ \\Rightarrow\\ x=z=t,\\ y=2t$","$6t^{2}=3\\ \\Rightarrow\\ t=\\dfrac{\\sqrt{2}}{2}$"],"설명":"등호는 두 쌍의 비가 같을 때 성립하므로 $x:y:z=1:2:1$ 이다. 최댓값이므로 $x+2y+z=6t$ 가 양수여야 하고 $t=\\frac{\\sqrt{2}}{2}$ 이다.","확인":null,"스킬":"A8"},{"제목":"xyz 의 값 β 구하기","힌트":"$x=z=t,\\ y=2t$ 를 $xyz$ 에 넣으면?","식":["$\\beta=xyz=t\\cdot2t\\cdot t=2t^{3}$","$\\beta=2\\left(\\dfrac{\\sqrt{2}}{2}\\right)^{3}=\\dfrac{\\sqrt{2}}{2}$"],"설명":"$\\left(\\frac{\\sqrt{2}}{2}\\right)^{3}=\\frac{2\\sqrt{2}}{8}=\\frac{\\sqrt{2}}{4}$ 이므로 두 배 하면 $\\frac{\\sqrt{2}}{2}$ 이다.","확인":null,"스킬":"A8"},{"제목":"α-β 의 값 구하기","힌트":"$\\alpha=3\\sqrt{2},\\ \\beta=\\dfrac{\\sqrt{2}}{2}$ 의 차는?","식":["$\\alpha-\\beta=3\\sqrt{2}-\\dfrac{\\sqrt{2}}{2}=\\dfrac{5\\sqrt{2}}{2}$"],"설명":"$\\sqrt{2}$ 를 공통으로 묶어 $3-\\frac{1}{2}=\\frac{5}{2}$ 를 곱한다.","확인":null,"스킬":"A8"}]},"ns-37383d0dc9a7":{"길":"대우로 p → q 를 만들고 정사각형이 원 안에 들어갈 조건을 꼭짓점으로 바꿔 넓이를 구한다","단계":[{"제목":"대우로 바꿔 포함 관계 만들기","힌트":"$\\sim q\\to\\sim p$ 와 같은 값을 갖는 명제와, 그때 진리집합의 관계는?","식":["$\\sim q\\to\\sim p\\ \\iff\\ p\\to q$","$P\\subset Q$"],"설명":"어떤 명제와 그 대우는 참과 거짓이 같다. $\\sim q\\to\\sim p$ 의 대우는 $p\\to q$ 이므로 $p$ 를 만족하는 점이 모두 $q$ 를 만족해야 한다. $P$ 는 한 변이 $2$ 인 정사각형 영역이고 $Q$ 는 중심이 $(a,\\ b)$ 이고 반지름이 $2$ 인 원판이다.","확인":null,"스킬":"C4"},{"제목":"정사각형이 원판 안에 들어갈 조건을 꼭짓점으로 바꾸기","힌트":"정사각형 $|x|\\le1,\\ |y|\\le1$ 이 원판 안에 들어가려면 어느 점들이 원판 안에 있으면 될까?","식":["꼭짓점 : $(1,\\ 1),\\ (1,\\ -1),\\ (-1,\\ 1),\\ (-1,\\ -1)$","$(a\\mp1)^{2}+(b\\mp1)^{2}\\le4$ (네 식 모두)"],"설명":"원판은 볼록하므로 정사각형의 네 꼭짓점이 모두 원판 안에 있으면 정사각형 전체가 들어간다. 네 꼭짓점에서 $(a,\\ b)$ 까지의 거리가 모두 $2$ 이하이어야 한다.","확인":null,"스킬":"S5"},{"제목":"점 (a, b) 의 영역을 네 원판의 공통부분으로 보기","고비":true,"힌트":"$a\\ge0,\\ b\\ge0$ 일 때 네 꼭짓점 중 $(a,\\ b)$ 에서 가장 먼 꼭짓점은 어느 것일까?","식":["$a\\ge0,\\ b\\ge0\\ \\Rightarrow$ 가장 먼 꼭짓점은 $(-1,\\ -1)$","$(a+1)^{2}+(b+1)^{2}\\le4$"],"설명":"$a\\ge0,\\ b\\ge0$ 이면 $(-1,\\ -1)$ 에서 가장 멀고, 나머지 세 꼭짓점의 조건은 이 조건에 포함된다. 영역은 $x$ 축, $y$ 축에 대칭이므로 제1사분면 부분의 넓이를 구해 $4$ 배 하면 된다.","확인":null,"스킬":"G1"},{"제목":"제1사분면 부분의 경계와 교점 구하기","힌트":"원 $(a+1)^{2}+(b+1)^{2}=4$ 가 $b$ 축과 만나는 점의 좌표는?","식":["$a=0$ 일 때 : $(b+1)^{2}=3\\ \\Rightarrow\\ b=\\sqrt{3}-1$","교점 : $(0,\\ \\sqrt{3}-1),\\ (\\sqrt{3}-1,\\ 0)$"],"설명":"제1사분면 부분은 두 축과 이 원의 호로 둘러싸인 영역이다. 원이 $a=0$ 인 직선과 만나는 점에서 $b$ 좌표가 $\\sqrt{3}-1$ 이고, $b=0$ 일 때도 같은 값이 나온다.","확인":null,"스킬":"S13"},{"제목":"제1사분면 부분의 넓이 구하기","힌트":"원의 중심 $(-1,\\ -1)$ 에서 두 교점으로 이은 부채꼴에서 사각형을 빼면?","식":["부채꼴의 중심각 : $60^\\circ-30^\\circ=30^\\circ$, 넓이 $\\dfrac{1}{2}\\cdot2^{2}\\cdot\\dfrac{\\pi}{6}=\\dfrac{\\pi}{3}$","사각형 : 중심, 두 교점, 원점 → 넓이 $\\sqrt{3}-1$","$\\dfrac{\\pi}{3}-(\\sqrt{3}-1)=\\dfrac{\\pi}{3}-\\sqrt{3}+1$"],"설명":"중심에서 두 교점까지의 가로, 세로 거리는 각각 $(1,\\ \\sqrt{3}),\\ (\\sqrt{3},\\ 1)$ 이므로 두 반지름은 가로축과 $60^\\circ,\\ 30^\\circ$ 를 이룬다. 부채꼴에서 중심, 두 교점, 원점을 꼭짓점으로 하는 사각형을 빼면 원점 쪽의 영역이 남는다.","확인":null,"스킬":"S12"},{"제목":"네 사분면을 합쳐 전체 넓이 구하기","힌트":"제1사분면 부분의 넓이에 몇을 곱할까?","식":["$4\\left(\\dfrac{\\pi}{3}-\\sqrt{3}+1\\right)$"],"설명":"영역이 $x$ 축, $y$ 축에 대칭이므로 네 사분면 부분의 넓이가 모두 같다. 따라서 전체 넓이는 한 부분의 $4$ 배이고 ④ 와 같다.","확인":null,"스킬":"S12"}]},"ns-37b885b7ae6d":{"길":"합집합이 공집합이면 둘 다 공집합이라는 것에서 포함 관계를 읽는다","단계":[{"제목":"합집합이 공집합일 조건 읽기","힌트":"합집합이 공집합이면 $\\mathrm{P}-\\mathrm{Q}$ 와 $\\mathrm{Q}-\\mathrm{R}^{\\mathrm{c}}$ 은 각각 어떤 집합일까?","식":["$\\mathrm{P}-\\mathrm{Q}=\\varnothing,\\quad \\mathrm{Q}-\\mathrm{R}^{\\mathrm{c}}=\\varnothing$","$\\mathrm{P}\\subset\\mathrm{Q},\\quad \\mathrm{Q}\\subset\\mathrm{R}^{\\mathrm{c}}$"],"설명":"두 집합의 합집합이 공집합이면 두 집합이 모두 공집합이다. $\\mathrm{A}-\\mathrm{B}=\\varnothing$ 이면 $\\mathrm{A}$ 의 원소가 모두 $\\mathrm{B}$ 에 속하므로 $\\mathrm{A}\\subset\\mathrm{B}$ 이다.","확인":null,"스킬":"C4"},{"제목":"포함 관계를 조건의 화살표로 바꾸기","힌트":"$\\mathrm{P}\\subset\\mathrm{Q}\\subset\\mathrm{R}^{\\mathrm{c}}$ 을 $p,\\ q,\\ \\sim r$ 사이의 관계로 쓰면?","식":["$\\mathrm{P}\\subset\\mathrm{Q}\\subset\\mathrm{R}^{\\mathrm{c}}$","$p\\Rightarrow q\\Rightarrow\\sim r$"],"설명":"$\\mathrm{R}^{\\mathrm{c}}$ 은 $\\sim r$ 의 진리집합이다. 진리집합이 부분집합 관계이면 앞쪽 조건이 뒤쪽 조건을 이끈다.","확인":null,"스킬":"C4"},{"제목":"선지의 방향을 하나씩 판정하기","고비":true,"힌트":"각 선지가 말하는 화살표가 $p\\Rightarrow q\\Rightarrow\\sim r$ 에서 항상 나오는지 따지면?","식":["① $p\\Rightarrow r$ : $\\mathrm{P}\\subset\\mathrm{R}^{\\mathrm{c}}$ 이고 $\\mathrm{P}\\ne\\varnothing$ 이라 성립하지 않음","② $\\sim r\\Rightarrow p$, ③ $q\\Rightarrow p$, ④ $\\sim p\\Rightarrow r$ : 항상 나오지 않음","⑤ $q\\Rightarrow\\sim r$ : 항상 성립"],"설명":"충분조건은 $\\Rightarrow$ 의 앞쪽, 필요조건은 뒤쪽이다. ① 은 $\\mathrm{P}$ 와 $\\mathrm{R}$ 이 겹치지 않아 거짓이다. ②, ③, ④ 는 $\\mathrm{P}=\\mathrm{R}^{\\mathrm{c}}$ 나 $\\mathrm{P}=\\mathrm{Q}$ 처럼 집합이 같아지는 특별한 경우에만 성립한다. ⑤ 는 $q\\Rightarrow\\sim r$ 이므로 $\\sim r$ 이 $q$ 이기 위한 필요조건이다.","확인":null,"스킬":"C4"}]},"ns-401b2ef0e528":{"길":"보기마다 두 조건을 풀어 q 가 p 를 이끌되 p 는 q 를 이끌지 않는 것을 찾는다","단계":[{"제목":"찾는 관계를 화살표로 나타내기","힌트":"$p$ 가 $q$ 이기 위한 필요조건이지만 충분조건은 아니라는 말을 화살표로 쓰면?","식":["$q\\Rightarrow p$ 이고 $p\\not\\Rightarrow q$"],"설명":"$p$ 가 $q$ 이기 위한 필요조건이면 $q\\Rightarrow p$ 이다. 충분조건이 아니므로 $p\\Rightarrow q$ 는 성립하지 않는다. 곧 $q$ 의 진리집합이 $p$ 의 진리집합의 진부분집합이다.","확인":null,"스킬":"C4"},{"제목":"ㄱ 의 관계 판별","힌트":"$|x|+|y|=|x+y|$ 를 제곱해서 $x,\\ y$ 의 조건으로 바꾸면?","식":["$|x|+|y|=|x+y|\\ \\iff\\ |xy|=xy\\ \\iff\\ xy\\ge0$","$q\\Rightarrow p$ (참), $p\\not\\Rightarrow q$ : $x=y=1$"],"설명":"양변을 제곱하면 $x^{2}+2|xy|+y^{2}=x^{2}+2xy+y^{2}$ 이므로 $xy\\ge0$ 이다. $x=y=0$ 이면 $xy\\ge0$ 이 성립하지만, $xy\\ge0$ 이어도 $x=y=1$ 처럼 $0$ 이 아닐 수 있다. ㄱ 은 필요조건이지만 충분조건은 아니다.","확인":null,"스킬":"C4"},{"제목":"ㄴ 의 관계 판별","힌트":"$x^{2}-xy+y^{2}$ 을 완전제곱식 하나와 다른 제곱항의 합으로 쓰면?","식":["$x^{2}-xy+y^{2}=\\left(x-\\dfrac{y}{2}\\right)^{2}+\\dfrac{3}{4}y^{2}$","$=0\\ \\iff\\ x=\\dfrac{y}{2},\\ y=0\\ \\iff\\ x=y=0$"],"설명":"실수의 제곱은 $0$ 이상이므로 두 제곱항의 합이 $0$ 이려면 둘 다 $0$ 이어야 한다. $p$ 와 $q$ 가 같은 조건이므로 필요충분조건이고, ㄴ 은 해당하지 않는다.","확인":null,"스킬":"A6"},{"제목":"ㄷ 의 관계 판별","고비":true,"힌트":"$xy+1\\ge x+y$ 를 한쪽으로 옮겨 인수분해하면?","식":["$xy+1-x-y=(x-1)(y-1)\\ge0$","$x,\\ y$ 가 모두 $1$ 이상이거나 모두 $1$ 이하, 그리고 $x+y\\ge2$","$\\Rightarrow\\ x\\ge1,\\ y\\ge1$"],"설명":"두 인수가 같은 부호이므로 둘 다 $1$ 이상이거나 둘 다 $1$ 이하이다. 둘 다 $1$ 이하이면 $x+y\\le2$ 이므로 $x+y\\ge2$ 와 함께 $x=y=1$ 뿐이고, 이는 첫째 경우에 포함된다. $p$ 와 $q$ 가 같은 조건이라 필요충분조건이고 ㄷ 은 해당하지 않는다.","확인":null,"스킬":"A6"},{"제목":"해당하는 보기 고르기","힌트":"필요조건이지만 충분조건은 아닌 보기는?","식":["ㄱ 만 해당"],"설명":"ㄴ 과 ㄷ 은 필요충분조건이고 ㄱ 만 필요조건이지만 충분조건은 아니다.","확인":null,"스킬":"C3"}]},"ns-44910973ff7a":{"길":"절대부등식의 뜻을 보기마다 적용해 판별식과 삼각부등식으로 확인한다","단계":[{"제목":"절대부등식의 뜻으로 ㄴ 판별하기","힌트":"문자에 어떤 실수를 넣어도 항상 성립하는 부등식이면 $x^{2}+ax+b>0$ 의 해는 어떤 범위일까?","식":["절대부등식 : 어떤 실수를 대입해도 성립","$x^{2}+ax+b>0$ 이 절대부등식 $\\Rightarrow$ 해는 모든 실수"],"설명":"절대부등식은 문자에 어떤 실수를 넣어도 성립하는 부등식이므로 해가 모든 실수이다. ㄴ 은 뜻을 그대로 쓴 문장이라 참이다.","확인":null,"스킬":"C1"},{"제목":"ㄱ 판별하기","힌트":"$|a|$ 를 $|a-b|$ 와 $|b|$ 로 나타내는 부등식은?","식":["$|a|=|(a-b)+b|\\le|a-b|+|b|$","$|a|-|b|\\le|a-b|$"],"설명":"삼각부등식 $|u+v|\\le|u|+|v|$ 에 $u=a-b,\\ v=b$ 를 넣고 $|b|$ 를 이항한다. 모든 실수 $a,\\ b$ 에서 성립하므로 절대부등식이고 ㄱ 은 참이다.","확인":null,"스킬":"C1"},{"제목":"ㄷ 판별하기","고비":true,"힌트":"모든 실수 $x$ 에서 $x^{2}+ax+b>0$ 이려면 이차함수의 그래프와 판별식은 어떤 조건이어야 할까?","식":["$x^{2}+ax+b>0$ 이 모든 실수 $x$ 에서 성립 $\\Rightarrow$ 그래프가 $x$ 축 위","$D=a^{2}-4b<0$","$x^{2}+ax+b=0$ 은 서로 다른 두 허근"],"설명":"아래로 볼록한 포물선이 항상 $x$ 축 위에 있으려면 $x$ 축과 만나지 않아야 하므로 판별식이 음수이다. 판별식이 음수이면 방정식은 서로 다른 두 허근을 가지므로 ㄷ 은 참이다.","확인":null,"스킬":"C1"},{"제목":"옳은 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 의 참 거짓을 모으면?","식":["ㄱ 참, ㄴ 참, ㄷ 참"],"설명":"세 보기가 모두 참이므로 ㄱ, ㄴ, ㄷ 이 답이다.","확인":null,"스킬":"C3"}]},"ns-46593ef4dec8":{"길":"마주 앉으면 왼쪽과 오른쪽이 뒤바뀌는 것을 써서 자리부터 확정한다","단계":[{"제목":"변호사와 B 의 자리 정하기","힌트":"변호사가 창가이고 B 의 왼쪽이면 B 는 같은 줄의 어느 자리일까?","식":["창가 : 변호사, 통로 : $\\mathrm{B}$ (같은 줄)","마주 앉은 줄에서는 왼쪽과 오른쪽이 반대"],"설명":"변호사는 창가이고 $\\mathrm{B}$ 의 왼쪽에 앉으므로, $\\mathrm{B}$ 는 변호사의 오른쪽인 같은 줄 통로 쪽에 앉는다. 마주 앉은 줄의 사람은 반대 방향을 보므로 왼쪽과 오른쪽이 뒤바뀐다.","확인":null,"스킬":"P4"},{"제목":"교사와 하얀 옷의 자리 정하기","힌트":"교사가 $\\mathrm{B}$ 의 줄에 앉을 수 있을까, 없다면 마주 보는 줄에서 교사의 오른쪽은 창가일까 통로일까?","식":["교사 : 마주 보는 줄의 통로","하얀 옷 : 마주 보는 줄의 창가"],"설명":"$\\mathrm{B}$ 의 줄에는 변호사와 $\\mathrm{B}$ 가 앉아 있고, $\\mathrm{B}$ 는 오른쪽에 자리가 없어 교사가 될 수 없다. 교사는 마주 보는 줄에 앉고, 그 줄에서는 오른쪽이 창가이므로 교사는 통로, 하얀 옷은 창가에 앉는다.","확인":null,"스킬":"P4"},{"제목":"마술사와 D 의 자리 정하기","고비":true,"힌트":"마주 보는 짝은 (변호사, 하얀 옷), ($\\mathrm{B}$, 교사) 이다. 마술사가 앉을 수 있는 자리는?","식":["마술사가 $\\mathrm{B}$ 이면 하얀 옷은 아나운서 → 노란 옷과 모순","하얀 옷 = 마술사, $\\mathrm{D}$ 는 맞은편의 변호사"],"설명":"마술사는 변호사와 교사가 아니므로 $\\mathrm{B}$ 이거나 하얀 옷 사람이다. $\\mathrm{B}$ 가 마술사이면 하얀 옷 사람은 아나운서인데 아나운서는 노란 옷이라 모순이다. 따라서 하얀 옷 사람이 마술사이고, 그 맞은편 변호사가 $\\mathrm{D}$ 이다.","확인":null,"스킬":"C2"},{"제목":"나머지 사람의 직업과 옷 색 정하기","힌트":"남은 직업은 아나운서이고 $\\mathrm{A}$ 는 파란 옷이다. $\\mathrm{A},\\ \\mathrm{B},\\ \\mathrm{C}$ 는 각각 누구일까?","식":["$\\mathrm{B}$ : 아나운서, 노란 옷","$\\mathrm{A}$ : 교사, 파란 옷","$\\mathrm{C}$ : 마술사, 하얀 옷 → $\\mathrm{D}$ : 변호사, 빨간 옷"],"설명":"$\\mathrm{B}$ 는 남은 직업인 아나운서이므로 노란 옷이다. $\\mathrm{A}$ 는 변호사 $\\mathrm{D}$ 도 아니고 하얀 옷 마술사도 아니므로 교사이고 파란 옷이다. 남은 빨간 옷은 변호사 $\\mathrm{D}$ 의 것이다.","확인":null,"스킬":"P4"},{"제목":"회장과 부회장의 직업 고르기","힌트":"빨간 옷과 파란 옷을 입은 사람의 직업은?","식":["회장 : 빨간 옷 = 변호사","부회장 : 파란 옷 = 교사"],"설명":"회장은 빨간 옷을 입은 $\\mathrm{D}$ 로 변호사이고, 부회장은 파란 옷을 입은 $\\mathrm{A}$ 로 교사이다.","확인":null,"스킬":"P4"}]},"ns-47ac8dcf18cf":{"길":"보기마다 우변과 좌변의 차를 완전제곱으로 묶거나 반례를 찾는다","단계":[{"제목":"ㄱ 의 우변과 좌변의 차 정리하기","고비":true,"힌트":"$(ax-by)^{2}-(a^{2}-b^{2})(x^{2}-y^{2})$ 을 전개해 정리하면?","식":["$(ax-by)^{2}-(a^{2}-b^{2})(x^{2}-y^{2})$","$=a^{2}y^{2}-2abxy+b^{2}x^{2}=(ay-bx)^{2}\\ge0$"],"설명":"전개하면 $a^{2}x^{2}$ 과 $b^{2}y^{2}$ 이 서로 지워지고 $a^{2}y^{2},\\ b^{2}x^{2},\\ -2abxy$ 가 남는다. 이는 $(ay-bx)^{2}$ 이므로 항상 $0$ 이상이고 ㄱ 은 참이다.","확인":null,"스킬":"A6"},{"제목":"ㄴ 의 좌변을 제곱의 합으로 나타내기","힌트":"$(a+b)^{2},\\ (b+c)^{2},\\ (c+a)^{2}$ 을 모두 더하면 좌변과 어떤 관계일까?","식":["$(a+b)^{2}+(b+c)^{2}+(c+a)^{2}=2(a^{2}+b^{2}+c^{2}+ab+bc+ca)$","$a^{2}+b^{2}+c^{2}+ab+bc+ca=\\dfrac{1}{2}\\left\\{(a+b)^{2}+(b+c)^{2}+(c+a)^{2}\\right\\}\\ge0$"],"설명":"세 제곱식을 전개해 더하면 각 제곱항이 두 번, 각 곱항이 두 번 나온다. 따라서 좌변은 세 제곱의 합의 절반이라 항상 $0$ 이상이고 ㄴ 은 참이다.","확인":null,"스킬":"A6"},{"제목":"ㄷ 의 반례 찾기","힌트":"$a,\\ b$ 에 간단한 값을 넣어 부등식이 깨지는 경우를 찾으면?","식":["$a=b=0$ 일 때 : $a+b=0,\\quad \\sqrt{a^{2}+b^{2}}=0$","$0>0$ 은 거짓"],"설명":"$a=b=0$ 이면 양변이 같아 부등호 $>$ 가 성립하지 않는다. 반례가 하나 있으므로 항상 성립하지 않아 ㄷ 은 거짓이다.","확인":null,"스킬":"C3"},{"제목":"항상 성립하는 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 의 참 거짓을 모으면?","식":["ㄱ 참, ㄴ 참, ㄷ 거짓"],"설명":"항상 성립하는 것은 ㄱ 과 ㄴ 이다.","확인":null,"스킬":"C3"}]},"ns-481d8eae489e":{"길":"지름의 원주각이 직각임을 써서 두 변의 제곱의 합을 정하고 산술·기하 평균을 쓴다","단계":[{"제목":"두 변의 제곱의 합 구하기","힌트":"지름 위에 밑변이 놓인 삼각형에서 점 $\\mathrm{P}$ 의 각은 얼마이고, 그때 두 변 사이에 어떤 관계가 생길까?","식":["$\\angle\\mathrm{APB}=90^{\\circ}$","$\\overline{\\mathrm{PA}}=m,\\ \\overline{\\mathrm{PB}}=n\\ \\Rightarrow\\ m^{2}+n^{2}=10^{2}=100$"],"설명":"지름에 대한 원주각은 $90^{\\circ}$ 이므로 삼각형은 빗변이 지름 $10$ 인 직각삼각형이다. 피타고라스 정리로 두 변의 제곱의 합이 정해진다.","확인":"100","스킬":"S3"},{"제목":"산술·기하 평균으로 넓이의 최댓값 구하기","고비":true,"힌트":"$m^{2}+n^{2}=100$ 에서 $mn$ 의 최댓값과 등호 조건은?","식":["$m^{2}+n^{2}\\ge2mn\\ \\Rightarrow\\ mn\\le50$","$\\mathrm{M}=\\dfrac{1}{2}mn\\le25$","등호 : $m=n=5\\sqrt{2}$"],"설명":"두 제곱수의 합이 일정하면 두 수가 같을 때 곱이 최대이다. $m=n$ 이면 $2m^{2}=100$ 이므로 $m=n=5\\sqrt{2}$ 이다.","확인":"25","스킬":"A7"},{"제목":"그때의 둘레와 M+a+b 구하기","힌트":"세 변의 길이를 모두 더해 $a+b\\sqrt{2}$ 꼴로 쓰면?","식":["$10+m+n=10+10\\sqrt{2}\\ \\Rightarrow\\ a=10,\\ b=10$","$\\mathrm{M}+a+b=25+10+10=45$"],"설명":"빗변이 $10$ 이고 두 변이 각각 $5\\sqrt{2}$ 이므로 둘레는 $10+10\\sqrt{2}$ 이다. $a,\\ b$ 가 유리수라서 $a=10,\\ b=10$ 으로 정해진다.","확인":"45","스킬":"A7"}]},"ns-4c772737a1ee":{"길":"보기마다 차를 정리해 부호를 보거나 반례 하나로 판가름한다","단계":[{"제목":"ㄱ 을 절댓값의 크기로 나누어 확인하기","고비":true,"힌트":"$|x|$ 와 $|y|$ 의 크기에 따라 나누어 $|x-y|$ 와 $|x|-|y|$ 를 비교하면?","식":["$|x|\\ge|y|$ 일 때 : $|x-y|^{2}-(|x|-|y|)^{2}=2(|xy|-xy)\\ge0$","$|x|<|y|$ 일 때 : $|x-y|>0>|x|-|y|$"],"설명":"$|x|\\ge|y|$ 이면 양변이 모두 $0$ 이상이라 제곱의 차가 $0$ 이상임을 보이면 된다. $|x|<|y|$ 이면 $x\\ne y$ 라서 $|x-y|$ 는 양수이고 $|x|-|y|$ 는 음수이다. 두 경우 모두 부등식이 성립하므로 ㄱ 은 참이다.","확인":null,"스킬":"C1"},{"제목":"ㄴ 의 좌변과 우변의 차 정리하기","힌트":"$(y-x)\\sqrt{x}-x(\\sqrt{y}-\\sqrt{x})$ 를 전개하면?","식":["$(y-x)\\sqrt{x}-x(\\sqrt{y}-\\sqrt{x})=y\\sqrt{x}-x\\sqrt{y}$","$=\\sqrt{xy}\\left(\\sqrt{y}-\\sqrt{x}\\right)>0$"],"설명":"$-x\\sqrt{x}$ 와 $+x\\sqrt{x}$ 가 지워져 $y\\sqrt{x}-x\\sqrt{y}$ 가 된다. $y=\\sqrt{y}\\sqrt{y}$, $x=\\sqrt{x}\\sqrt{x}$ 로 보고 $\\sqrt{xy}$ 로 묶는다. $0<x<y$ 이므로 $\\sqrt{y}>\\sqrt{x}$ 이고 차는 양수라서 ㄴ 은 참이다.","확인":null,"스킬":"C1"},{"제목":"ㄷ 의 반례 찾기","힌트":"$x=1,\\ y=2$ 를 양변에 넣어 크기를 비교하면?","식":["$(1+2)\\sqrt{1\\cdot2}=3\\sqrt{2}=\\sqrt{18}$","$1\\cdot2\\sqrt{1+2}=2\\sqrt{3}=\\sqrt{12}$","$\\sqrt{18}>\\sqrt{12}$"],"설명":"좌변이 우변보다 크므로 부등호 $<$ 가 성립하지 않는다. 반례가 하나 있으므로 항상 성립하지 않아 ㄷ 은 거짓이다.","확인":null,"스킬":"C3"},{"제목":"항상 성립하는 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 의 참 거짓을 모으면?","식":["ㄱ 참, ㄴ 참, ㄷ 거짓"],"설명":"항상 성립하는 것은 ㄱ 과 ㄴ 이다.","확인":null,"스킬":"C3"}]},"ns-572f25fb0adb":{"길":"선지를 조건에 하나씩 대어 어긋나는 것부터 지운다","단계":[{"제목":"ㄷ으로 양말·청바지 동시 구매 제외","힌트":"ㄷ에 어긋나는 선지를 지우면 몇 개가 남는가?","식":["양말과 청바지를 둘 다 산 ①, ④, ⑤ 탈락","남는 선지: ②, ③"],"설명":"ㄷ은 양말과 청바지를 함께 살 수 없다는 조건이다. 둘을 모두 산 ①, ④, ⑤는 어긋나므로 지운다.","확인":"2","스킬":"C4","고비":true},{"제목":"ㄴ으로 모자·셔츠 없는 선지 제외","힌트":"남은 ②, ③ 중 모자와 셔츠를 하나도 사지 않은 것은?","식":["③은 모자도 셔츠도 없음 → 탈락","남는 선지: ②"],"설명":"ㄴ은 모자와 셔츠 중 적어도 한 가지를 사야 한다는 조건이다. ③은 둘 다 사지 않아 어긋나므로 ②만 남는다.","확인":null,"스킬":"C4"},{"제목":"남은 선지가 모든 조건을 만족하는지 검증","힌트":"청바지와 모자만 산 경우 ㄱ, ㄹ, ㅁ은 각각 어떻게 되는가?","식":["ㄱ·ㅁ: 신발·셔츠를 사지 않아 조건이 걸리지 않음","ㄹ: 청바지와 모자를 둘 다 샀으므로 만족"],"설명":"신발과 셔츠를 사지 않았으므로 ㄱ, ㅁ은 문제가 없고, ㄹ은 둘 다 샀으니 만족한다. 따라서 산 물건은 청바지, 모자이다.","확인":null,"스킬":"C4"}]},"ns-696ce31c1b88":{"길":"보기마다 p→q, q→p를 따로 따져 분류한 뒤 개수로 식을 계산한다","단계":[{"제목":"㉠·㉡의 부호 조건으로 양방향 확인","힌트":"ab의 부호를 이용해 부등식을 정리하면 p와 q는 서로 어떤 관계인가?","식":["$ab>0$일 때 $\\frac{1}{ab}<1 \\iff ab>1$","$ab<0$일 때 $\\frac{1}{a}<\\frac{1}{b} \\iff \\frac{b-a}{ab}<0 \\iff a<b$"],"설명":"㉠은 $ab>0$이므로 $\\frac{1}{ab}<1$의 양변에 $ab$를 곱해도 부등호 방향이 같아 $ab>1$과 동치이다. ㉡은 $ab<0$이므로 $\\frac{1}{a}-\\frac{1}{b}=\\frac{b-a}{ab}<0$에서 $b-a>0$이 되어 $a<b$와 동치이다. 둘 다 필요충분조건이다.","확인":null,"스킬":"C4"},{"제목":"㉢의 양방향 증명: 부호 조건 정리","힌트":"$\\frac{a-c}{b-d}$와 $\\frac{a}{b}$, $\\frac{c}{d}$의 차를 구하면 부호는 무엇에 달려 있는가?","식":["$\\frac{a}{b}<\\frac{c}{d} \\iff ad>bc$ ($bd<0$일 때)","$\\frac{a-c}{b-d}-\\frac{a}{b}=\\frac{ad-bc}{b(b-d)}$","$\\frac{c}{d}-\\frac{a-c}{b-d}=\\frac{bc-ad}{d(b-d)}$"],"설명":"$bd<0$이므로 $p$의 양변에 $bd$를 곱하면 $ad>bc$이다. 이때 $b(b-d)>0$, $d(b-d)<0$이어서 두 차가 모두 양수가 되어 $q$가 성립한다. 거꾸로 $q$에서 $ad>bc$를 얻고 $bd<0$으로 나누면 $p$이므로 필요충분조건이다.","확인":null,"스킬":"C4","고비":true},{"제목":"㉣을 제곱의 합으로 바꾸기","힌트":"$a^2+b^2+c^2=ab+bc+ca$의 양변을 2배해 한쪽으로 모으면 어떤 꼴이 되는가?","식":["$(a-b)^2+(b-c)^2+(c-a)^2=0$","$a=b=c$"],"설명":"양변에 $2$를 곱해 이항하면 세 제곱의 합이 $0$이 된다. 실수의 제곱은 $0$ 이상이므로 세 항이 모두 $0$이어서 $a=b=c$이다. 역으로 $a=b=c$이면 등식이 성립하므로 필요충분조건이다.","확인":null,"스킬":"A6"},{"제목":"㉤의 한쪽 방향 확인과 반례","힌트":"$a+b>0$이면 $a^2+b^2>0$이 항상 성립하는가? 거꾸로는 어떤가?","식":["$a+b>0 \\Rightarrow a^2+b^2>0$ (참)","$a=-2,\\ b=-1$이면 $a^2+b^2>0$이지만 $a+b<0$"],"설명":"$a+b>0$이면 $a,\\ b$가 모두 $0$일 수 없으므로 $a^2+b^2>0$이다. 그러나 $a=-2,\\ b=-1$은 $q$를 만족하지만 $p$를 만족하지 않는다. 따라서 $p$는 $q$이기 위한 충분조건이지만 필요조건은 아니다.","확인":null,"스킬":"C3"},{"제목":"조건 개수 세기와 식 계산","힌트":"필요충분조건은 몇 개이고, 충분조건만 성립하는 것은 몇 개인가?","식":["$x=0,\\ y=1,\\ z=4$","$2x-y+z=2\\cdot0-1+4=3$"],"설명":"㉠~㉣은 필요충분조건이므로 $z=4$이고, ㉤은 충분조건이지만 필요조건이 아니므로 $y=1$이다. 필요조건이지만 충분조건이 아닌 것은 없으므로 $x=0$이다. 따라서 $2x-y+z=3$이다.","확인":"3","스킬":"C4"}]},"ns-6ac78bba3a6a":{"길":"철사 길이를 식으로 쓰고 산술·기하평균으로 넓이를 최대로 만든다","단계":[{"제목":"철사 길이를 가로·세로 식으로 나타내기","힌트":"큰 직사각형의 가로를 $W$, 세로를 $H$라 할 때 철사는 가로 방향 몇 줄, 세로 방향 몇 줄인가?","식":["$2W+4H=24$","$W+2H=12$"],"설명":"철사는 가로 방향 $2$줄과 세로 방향 $4$줄(바깥 $2$줄, 칸막이 $2$줄)로 이루어져 있다. 따라서 $2W+4H=24$이고 양변을 $2$로 나누면 $W+2H=12$이다.","확인":null,"스킬":"C7","고비":true},{"제목":"산술·기하평균으로 넓이의 최댓값 구하기","힌트":"합이 일정한 $W$와 $2H$에 산술·기하평균 부등식을 쓰면 넓이의 최댓값은 얼마인가?","식":["$W+2H\\ge2\\sqrt{2WH}$","$12\\ge2\\sqrt{2WH} \\Rightarrow WH\\le18$","등호는 $W=2H$일 때이므로 $W=6,\\ H=3$"],"설명":"$W>0,\\ 2H>0$이므로 산술·기하평균 부등식 $W+2H\\ge2\\sqrt{2WH}$가 성립한다. $W+2H=12$를 대입하면 $WH\\le18$이므로 $M=18$이다. 등호는 $W=2H$일 때 성립하고, $W+2H=12$와 연립하면 $W=6,\\ H=3$이다.","확인":"18","스킬":"A7"},{"제목":"최대일 때의 둘레와 합 구하기","힌트":"둘레 $l$을 구한 뒤 $M$과 더하면 얼마인가?","식":["$l=2(6+3)=18$","$M+l=18+18=36$"],"설명":"넓이가 최대일 때 가로는 $6\\,\\mathrm{m}$, 세로는 $3\\,\\mathrm{m}$이므로 $l=2(6+3)=18$이다. 따라서 $M+l=18+18=36$이다.","확인":"36","스킬":"C7"}]},"ns-8334bd5eec98":{"길":"보기마다 p→q, q→p를 따로 따져 옳은 것을 센다","단계":[{"제목":"ㄱ·ㄴ의 필요·충분 방향 판정","힌트":"ㄱ, ㄴ 중 서술이 옳은 것은 몇 개인가?","식":["ㄱ: $x=1,\\ y=8$이면 $xy=8$이지만 $x=2$가 아님 (거짓)","ㄴ: $\\angle \\mathrm{A}=90^{\\circ} \\Rightarrow$ 직각삼각형 (참)"],"설명":"ㄱ은 $x=1,\\ y=8$이 반례이므로 $p\\Rightarrow q$가 거짓이어서 충분조건이 아니다. ㄴ은 $\\angle\\mathrm{A}=90^{\\circ}$이면 직각삼각형이므로 $q\\Rightarrow p$가 참이고, 직각삼각형인 것은 필요조건이다.","확인":"1","스킬":"C3"},{"제목":"집합 관계·인수정리를 쓴 필요충분 판정","힌트":"ㄷ, ㅂ, ㅇ 중 서술이 옳은 것은 몇 개인가?","식":["$\\mathrm{A}-(\\mathrm{A}\\cap\\mathrm{B})=\\mathrm{A}-\\mathrm{B}=\\varnothing \\iff \\mathrm{A}\\subset\\mathrm{B}$ (ㄷ 참)","$\\mathrm{A}\\cup\\mathrm{B}=\\mathrm{B} \\iff \\mathrm{A}\\subset\\mathrm{B}$ (ㅂ 참)","$\\mathrm{P}(\\alpha)=0 \\iff \\mathrm{P}(x)$가 $x-\\alpha$로 나누어떨어짐 (ㅇ 거짓)"],"설명":"$\\mathrm{A}-\\mathrm{B}=\\varnothing$은 $\\mathrm{A}$의 원소가 모두 $\\mathrm{B}$에 속한다는 뜻이므로 ㄷ은 필요충분조건이다. $\\mathrm{A}\\cup\\mathrm{B}=\\mathrm{B}$도 $\\mathrm{A}\\subset\\mathrm{B}$와 동치이므로 ㅂ은 옳다. ㅇ은 인수정리에 의해 필요충분조건이므로 '충분조건은 아니다'가 틀리다.","확인":"2","스킬":"C4"},{"제목":"ㄹ·ㅁ·ㅅ의 반례와 대우 확인","힌트":"ㄹ, ㅁ, ㅅ 중 서술이 옳은 것은 몇 개인가?","식":["ㄹ: $x=\\sqrt{2}$이면 $x^2=2$는 유리수이지만 $x$는 무리수 (거짓)","ㅁ: $x,\\ y$가 모두 유리수이면 $x+y$도 유리수 (대우, 참)","ㅅ: $m=\\frac{1}{2},\\ n=\\frac{1}{2}$이면 $m+n=1$ (필요조건 아님, 거짓)"],"설명":"ㄹ은 $x=\\sqrt{2}$가 반례여서 필요조건이 아니므로 필요충분조건이 아니다. ㅁ은 대우 '$x,\\ y$가 모두 유리수이면 $x+y$는 유리수이다'가 참이므로 충분조건이 맞다. ㅅ은 $m,\\ n$이 정수이면 $m+n$이 정수이므로 충분조건이고, $\\frac{1}{2}+\\frac{1}{2}=1$이 반례여서 필요조건은 아니다.","확인":"1","스킬":"C3","고비":true},{"제목":"옳은 보기의 개수 합산","힌트":"앞의 세 묶음에서 옳은 보기를 합하면 몇 개인가?","식":["옳은 것: ㄴ, ㄷ, ㅁ, ㅂ","$1+2+1=4$"],"설명":"첫 묶음에서 ㄴ, 둘째 묶음에서 ㄷ·ㅂ, 셋째 묶음에서 ㅁ이 옳아 모두 $4$개이다.","확인":"4","스킬":"C3"}]},"ns-84c653e0b978":{"길":"밑면 비용은 고정이므로 나머지 면 비용에 산술·기하평균을 쓴다","단계":[{"제목":"밑면 비용 구하기","힌트":"밑면의 넓이와 단가로 밑면 비용은 얼마인가?","식":["$400\\times20=8000$"],"설명":"밑면은 $1\\,\\mathrm{cm}^2$당 $20$원이고 넓이가 $400\\,\\mathrm{cm}^2$이므로 비용은 $8000$원으로 일정하다.","확인":"8000","스킬":"C7"},{"제목":"나머지 면의 비용을 가로·세로 식으로 쓰기","힌트":"밑면의 가로를 $x$, 세로를 $y$라 하면 뒷면과 옆면·칸막이 $4$장의 넓이는 각각 얼마인가?","식":["$xy=400$","뒷면 $20x$, 옆면·칸막이 $4\\times20y=80y$","나머지 비용 $10(20x+80y)=200x+800y$"],"설명":"그림에서 뒷면은 가로 $x$, 높이 $20$인 직사각형이고, 옆면 $2$개와 칸막이 $2$개는 세로 $y$, 높이 $20$인 합동 직사각형 $4$장이다. 이들은 $1\\,\\mathrm{cm}^2$당 $10$원이므로 비용은 $10(20x+80y)=200x+800y$이다.","확인":null,"스킬":"C7"},{"제목":"산술·기하평균으로 나머지 비용의 최솟값","힌트":"$200x$와 $800y$의 곱이 일정함을 이용하면 합의 최솟값은 얼마인가?","식":["$200x+800y\\ge2\\sqrt{200x\\cdot800y}$","$=2\\sqrt{160000\\cdot400}=16000$","등호는 $200x=800y$, 즉 $x=40,\\ y=10$"],"설명":"$xy=400$이므로 $200x\\cdot800y=160000\\cdot400$으로 일정해서 산술·기하평균 부등식을 쓸 수 있다. 그러면 $200x+800y\\ge16000$이고, 등호는 $x=4y$일 때이므로 $x=40,\\ y=10$에서 성립한다.","확인":"16000","스킬":"A7","고비":true},{"제목":"전체 비용의 최솟값 계산","힌트":"밑면 비용과 나머지 비용의 최솟값을 더하면 얼마인가?","식":["$8000+16000=24000$"],"설명":"전체 비용은 $8000+200x+800y$이므로 최솟값은 $8000+16000=24000$(원)이다.","확인":"24000","스킬":"C7"}]},"ns-89328f0917b6":{"길":"p, q를 각각 동치인 조건으로 바꿔 포함 방향을 비교한다","단계":[{"제목":"①·②에서 q⇒p가 거짓인 반례 찾기","힌트":"q가 참인데 p가 거짓이 되는 값이나 집합을 ①, ②에서 찾을 수 있는가?","식":["① $x=-3,\\ y=1$: $q$ 참, $p$ 거짓","② $A=\\{1\\},\\ B=\\{2\\}$: $n(A)=n(B)$이지만 $n(A-B)=1$"],"설명":"필요조건이려면 $q\\Rightarrow p$가 참이어야 한다. ①은 $x=-3,\\ y=1$일 때 $q$가 참이지만 $p$는 거짓이므로 필요조건이 아니다. ②도 $A=\\{1\\},\\ B=\\{2\\}$에서 $n(A)=n(B)$이지만 $n(A-B)\\ne0$이므로 필요조건이 아니다.","확인":null,"스킬":"C4"},{"제목":"③·④가 필요충분조건임을 확인","힌트":"③, ④에서 p와 q가 서로 동치인지 따져 보면 어떤가?","식":["③ $xyz\\ne0 \\iff x\\ne0,\\ y\\ne0,\\ z\\ne0$","④ $x^2+xy+y^2=\\left(x+\\frac{y}{2}\\right)^2+\\frac{3}{4}y^2=0 \\iff x=y=0$"],"설명":"③은 세 수의 곱이 $0$이 아닌 것과 세 수가 모두 $0$이 아닌 것이 같은 말이어서 필요충분조건이다. ④는 완전제곱식으로 고치면 $x,\\ y$가 실수일 때 두 제곱항이 모두 $0$이어야 하므로 $x=y=0$과 동치이다. 따라서 ③, ④도 답이 아니다.","확인":null,"스킬":"A6"},{"제목":"⑤를 제곱의 합으로 바꿔 포함 관계 비교","힌트":"⑤의 p를 $(x-y)^2$ 꼴의 합으로 고치면 어떤 조건과 같은가?","식":["$p:\\ \\frac{1}{2}\\{(x-y)^2+(y-z)^2+(z-x)^2\\}=0 \\iff x=y=z$","$q:\\ x^2+y^2+z^2=0 \\iff x=y=z=0$","$q\\Rightarrow p$ 참, $p\\Rightarrow q$ 거짓 ($x=y=z=1$)"],"설명":"$p$는 세 제곱의 합이 $0$인 꼴이어서 $x=y=z$와 같고, $q$는 $x=y=z=0$과 같다. $x=y=z=0$이면 $x=y=z$이므로 $q\\Rightarrow p$는 참이다. $x=y=z=1$은 $p$를 만족하지만 $q$를 만족하지 않으므로 $p\\Rightarrow q$는 거짓이고, ⑤가 답이다.","확인":null,"스킬":"C4","고비":true}]},"ns-91fb500d9621":{"길":"나머지 네 수의 합·제곱합을 a로 쓰고 부등식으로 a의 범위를 잡는다","단계":[{"제목":"나머지 네 수의 합·제곱합을 a로 표현","힌트":"$a$를 제외한 네 수의 합과 제곱합은 $a$로 어떻게 나타내는가?","식":["$b+c+d+e=10-a$","$b^2+c^2+d^2+e^2=25-a^2$"],"설명":"주어진 두 식에서 $a$와 $a^2$을 각각 이항하면 나머지 네 수에 대한 합과 제곱합을 $a$로 쓸 수 있다.","확인":null,"스킬":"A2"},{"제목":"코시-슈바르츠로 a에 대한 부등식 세우기","힌트":"네 실수의 합의 제곱과 제곱합 사이에는 어떤 부등식이 성립하는가?","식":["$(1^2+1^2+1^2+1^2)(b^2+c^2+d^2+e^2)\\ge(b+c+d+e)^2$","$4(25-a^2)\\ge(10-a)^2$"],"설명":"실수 $b,\\ c,\\ d,\\ e$에 대해 코시-슈바르츠 부등식이 성립한다. 앞 단계의 합과 제곱합을 대입하면 $a$만 남는 부등식이 된다.","확인":null,"스킬":"A7","고비":true},{"제목":"이차부등식을 풀어 a의 최댓값 정하기","힌트":"부등식을 전개해 정리하면 $a$에 대한 어떤 이차부등식이 되는가?","식":["$100-4a^2\\ge100-20a+a^2$","$a^2-4a\\le0 \\Rightarrow 0\\le a\\le4$"],"설명":"양변을 전개해 정리하면 $5a^2-20a\\le0$이고 $a(a-4)\\le0$에서 $0\\le a\\le4$이다. $a=4$일 때 $b=c=d=e=\\frac{3}{2}$로 두 조건이 모두 성립하므로 최댓값은 $4$이다.","확인":"4","스킬":"A6"}]},"ns-99ff9b70fca6":{"길":"네 조건을 P, Q, R의 관계로 정리한 뒤 선지를 포함 관계로 따진다","단계":[{"제목":"(라)와 (나)로 P와 R 정리","힌트":"$\\mathrm{P}^c=\\varnothing$이면 $\\mathrm{P}$는 어떤 집합인가?","식":["$\\mathrm{P}^c=\\varnothing \\Rightarrow \\mathrm{P}=\\mathrm{U}$","$\\mathrm{P}\\cap\\mathrm{R}=\\mathrm{R}\\ne\\varnothing$"],"설명":"여집합이 공집합인 집합은 전체집합이므로 $\\mathrm{P}=\\mathrm{U}$이다. 그러면 (나)는 $\\mathrm{R}\\ne\\varnothing$이 된다.","확인":null,"스킬":"C4"},{"제목":"(다)에서 Q와 R의 관계 구하기","힌트":"(다)의 좌변에 드모르간 법칙을 쓰고, (가)로 $\\mathrm{P}\\cap\\mathrm{Q}$를 바꾸면?","식":["$(\\mathrm{R}\\cup(\\mathrm{P}\\cap\\mathrm{Q})^c)^c=\\mathrm{R}^c\\cap(\\mathrm{P}\\cap\\mathrm{Q})=\\mathrm{R}^c\\cap\\mathrm{Q}$","$\\mathrm{R}^c\\cap\\mathrm{Q}=\\mathrm{Q} \\Rightarrow \\mathrm{Q}\\subset\\mathrm{R}^c$, 즉 $\\mathrm{Q}\\cap\\mathrm{R}=\\varnothing$"],"설명":"드모르간 법칙으로 좌변은 $\\mathrm{R}^c\\cap(\\mathrm{P}\\cap\\mathrm{Q})$이고, (가)에서 $\\mathrm{P}\\cap\\mathrm{Q}=\\mathrm{Q}$이므로 $\\mathrm{R}^c\\cap\\mathrm{Q}$이다. 이것이 $\\mathrm{Q}$와 같으려면 $\\mathrm{Q}\\subset\\mathrm{R}^c$이어야 한다.","확인":null,"스킬":"C4","고비":true},{"제목":"선지를 진리집합의 포함 관계로 바꾸기","힌트":"각 선지 '$a\\rightarrow b$'를 진리집합으로 쓰면 어느 집합이 어느 집합에 포함되는 꼴인가?","식":["① $\\mathrm{R}^c\\subset\\mathrm{P}$, ② $\\mathrm{P}\\subset\\mathrm{Q}$, ③ $\\mathrm{R}^c\\subset\\mathrm{Q}^c$","④ $\\mathrm{Q}\\subset\\mathrm{P}^c$, ⑤ $\\mathrm{P}\\subset\\mathrm{R}^c$"],"설명":"명제 $p\\rightarrow q$가 참인 것은 $\\mathrm{P}\\subset\\mathrm{Q}$인 것과 같다. $\\sim r$의 진리집합은 $\\mathrm{R}^c$이다. ①은 $\\mathrm{P}=\\mathrm{U}$이므로 $\\mathrm{R}^c\\subset\\mathrm{U}=\\mathrm{P}$가 항상 성립한다.","확인":null,"스킬":"C4"},{"제목":"반례로 나머지 선지 제외","힌트":"네 조건을 모두 만족하면서 ②~⑤를 거짓으로 만드는 작은 집합 예를 찾을 수 있는가?","식":["$\\mathrm{U}=\\{1,2,3\\},\\ \\mathrm{P}=\\mathrm{U},\\ \\mathrm{Q}=\\{2\\},\\ \\mathrm{R}=\\{1\\}$","②~⑤는 모두 거짓, ①만 참"],"설명":"이 예는 (가)~(라)를 모두 만족한다. 이때 $\\mathrm{P}\\not\\subset\\mathrm{Q}$, $\\mathrm{R}^c\\not\\subset\\mathrm{Q}^c$, $\\mathrm{Q}\\not\\subset\\mathrm{P}^c$, $\\mathrm{P}\\not\\subset\\mathrm{R}^c$이므로 ②~⑤는 항상 참이 아니다. 따라서 항상 참인 명제는 ①이다.","확인":null,"스킬":"C3"}]},"ns-9a34d26db010":{"길":"참인 명제를 먼저 가려 두고 전구 조건에 맞게 줄줄이 이어 붙인다","단계":[{"제목":"진리집합 포함 관계와 참인 명제 정리","힌트":"$p,\\ q,\\ r$ 사이의 포함 관계를 따지면 $3\\times3$가지 명제 중 참인 것은 몇 개인가?","식":["$\\mathrm{P}=\\{1,2,3,6\\},\\ \\mathrm{Q}=\\{1,2,4,8\\}$이므로 $\\mathrm{P}\\subset\\mathrm{R},\\ \\mathrm{Q}\\subset\\mathrm{R}$","참: $p\\rightarrow p,\\ q\\rightarrow q,\\ r\\rightarrow r,\\ p\\rightarrow r,\\ q\\rightarrow r$"],"설명":"$6$과 $8$의 약수는 모두 $24$의 약수이므로 $\\mathrm{P}$, $\\mathrm{Q}$는 $\\mathrm{R}$의 부분집합이다. $\\mathrm{P}$와 $\\mathrm{Q}$는 서로 포함하지 않으므로 같은 조건끼리의 $3$가지와 $p\\rightarrow r,\\ q\\rightarrow r$만 참이다. 나머지 $p\\rightarrow q,\\ q\\rightarrow p,\\ r\\rightarrow p,\\ r\\rightarrow q$는 거짓이다.","확인":"5","스킬":"C4"},{"제목":"전구 조건을 세 줄의 참·거짓으로 나타내기","힌트":"카드를 순서대로 $c_1,\\ c_2,\\ c_3,\\ c_4$라 할 때 제일 앞 전구만 켜지려면 각 줄은 참인가 거짓인가?","식":["$c_1\\rightarrow c_2$ 참","$c_2\\rightarrow c_3$ 거짓, $c_3\\rightarrow c_4$ 거짓","거짓인 $(c_2,\\ c_3)$: $(p,q),\\ (q,p),\\ (r,p),\\ (r,q)$"],"설명":"첫째 줄은 참이고 둘째, 셋째 줄은 거짓이어야 한다. 앞 단계의 거짓 명제 $4$가지가 곧 $(c_2,\\ c_3)$가 될 수 있는 경우이다.","확인":null,"스킬":"P4"},{"제목":"거짓인 두 줄을 이어 붙이기","힌트":"$(c_2,\\ c_3)$마다 $c_3\\rightarrow c_4$가 거짓이 되는 $c_4$는 무엇인가? 가능한 $(c_2,\\ c_3,\\ c_4)$는 몇 가지인가?","식":["$(p,q,p),\\ (q,p,q)$","$(r,p,q),\\ (r,q,p)$"],"설명":"$q\\rightarrow p$, $p\\rightarrow q$가 거짓이므로 $c_3=q$이면 $c_4=p$, $c_3=p$이면 $c_4=q$이다. $r\\rightarrow p$, $r\\rightarrow q$도 거짓이므로 $c_2=r$이면 $(c_3,\\ c_4)$는 $(p,q)$ 또는 $(q,p)$이다. 가능한 경우는 모두 $4$가지이다.","확인":"4","스킬":"P4"},{"제목":"첫 카드 붙이기와 카드 장수 제한","힌트":"각 조건 카드는 $2$장씩이다. $c_2$로 참이 되는 $c_1$을 붙인 뒤 어느 것이 불가능한가?","식":["$c_2=p$이면 $c_1=p$: $(p,p,q,p)$, $c_2=q$이면 $c_1=q$: $(q,q,p,q)$ → 카드 $3$장 필요, 불가","$c_2=r$이면 $c_1=p,\\ q,\\ r$ 모두 가능: $3\\times2=6$"],"설명":"$c_1\\rightarrow p$가 참인 $c_1$은 $p$뿐이고 $c_1\\rightarrow q$가 참인 $c_1$은 $q$뿐이어서 $p$ 또는 $q$ 카드가 $3$장 필요하므로 불가능하다. $c_2=r$이면 $c_1$은 $p,\\ q,\\ r$ 모두 가능하고 카드는 $2$장을 넘지 않는다. $c_2=r$인 두 경우에 각각 $3$가지씩이므로 $6$가지이다.","확인":"6","스킬":"P4","고비":true}]},"ns-9dc4f80f6507":{"길":"보기마다 q⇒p는 참, p⇒q는 거짓인지 반례로 확인한다","단계":[{"제목":"ㄱ의 부호 경우 나누기","힌트":"$x>y>z$이면 곱의 부호는? 곱이 음수인데 $x>y>z$가 아닌 순서가 있는가?","식":["$x>y>z \\Rightarrow (x-y)(y-z)(z-x)<0$ (참)","$x=1,\\ y=3,\\ z=2$: $p$ 참, $q$ 거짓"],"설명":"$x>y>z$이면 $x-y>0$, $y-z>0$, $z-x<0$이어서 곱이 음수이므로 $q\\Rightarrow p$는 참이다. $x=1,\\ y=3,\\ z=2$는 곱이 $-2$로 $p$를 만족하지만 $q$는 만족하지 않으므로 $p\\Rightarrow q$는 거짓이다. ㄱ은 필요조건이지만 충분조건은 아니다.","확인":null,"스킬":"C3","고비":true},{"제목":"ㄴ의 방향 판정","힌트":"$x+y>4$이면 $x>2$ 또는 $y>2$인가? 거꾸로는 성립하는가?","식":["$x\\le2,\\ y\\le2 \\Rightarrow x+y\\le4$ (대우, 참)","$x=3,\\ y=0$: $q$ 참, $p$ 거짓"],"설명":"대우가 참이므로 $p\\Rightarrow q$는 참이다. $x=3,\\ y=0$은 $q$를 만족하지만 $x+y=3$이어서 $p$를 만족하지 않으므로 $q\\Rightarrow p$는 거짓이다. ㄴ은 충분조건이지만 필요조건은 아니어서 답이 아니다.","확인":null,"스킬":"C3"},{"제목":"ㄷ을 동치인 식으로 바꿔 판정","힌트":"$a^2+b^2=2ab$를 한쪽으로 모으면 $p$는 어떤 조건과 같은가?","식":["$p:\\ (a-b)^2=0 \\iff a=b$","$q:\\ |a|+|b|=0 \\iff a=b=0$"],"설명":"$p$는 $a=b$와 같고 $q$는 $a=b=0$과 같다. $a=b=0$이면 $a=b$이므로 $q\\Rightarrow p$는 참이고, $a=b=1$이면 $p$만 성립하므로 $p\\Rightarrow q$는 거짓이다. ㄷ은 필요조건이지만 충분조건은 아니다.","확인":null,"스킬":"A6"},{"제목":"ㄹ을 동치인 식으로 바꿔 판정하고 선지 고르기","힌트":"$|a+b|=|a-b|$의 양변을 제곱하면 $q$는 어떤 조건과 같은가?","식":["$q:\\ (a+b)^2=(a-b)^2 \\iff ab=0$","$ab=0 \\Rightarrow ab<1$ (참), $ab=\\frac{1}{2}$이면 $q$ 거짓","필요조건이지만 충분조건이 아닌 것: ㄱ, ㄷ, ㄹ"],"설명":"$q$는 $ab=0$과 같으므로 $q\\Rightarrow p$는 참이다. $a=1,\\ b=\\frac{1}{2}$은 $ab<1$이지만 $ab\\ne0$이므로 $p\\Rightarrow q$는 거짓이다. 따라서 ㄱ, ㄷ, ㄹ이 해당한다.","확인":null,"스킬":"C4"}]},"ns-ccc9fbd369f0":{"길":"겉넓이 조건을 쓰고 제곱합의 하한을 제곱의 합으로 잡는다","단계":[{"제목":"겉넓이와 대각선 길이를 식으로 나타내기","힌트":"직육면체의 겉넓이와 대각선의 길이를 $x,\\ y,\\ z$로 쓰면?","식":["$2(xy+yz+zx)=1$","대각선 $=\\sqrt{x^2+y^2+z^2}$"],"설명":"직육면체의 겉넓이는 $2(xy+yz+zx)$이므로 이 값이 $1$이다. 대각선의 길이는 $\\sqrt{x^2+y^2+z^2}$이므로 $x^2+y^2+z^2$의 최솟값을 구하면 된다.","확인":null,"스킬":"A2"},{"제목":"제곱합과 곱의 합의 크기 비교","힌트":"$x^2+y^2+z^2$에서 $xy+yz+zx$를 빼면 어떤 제곱의 합으로 쓸 수 있는가?","식":["$x^2+y^2+z^2-(xy+yz+zx)=\\frac{1}{2}\\{(x-y)^2+(y-z)^2+(z-x)^2\\}\\ge0$","$x^2+y^2+z^2\\ge xy+yz+zx=\\frac{1}{2}$"],"설명":"실수의 제곱은 $0$ 이상이므로 위 식이 $0$ 이상이다. 따라서 $x^2+y^2+z^2$은 $xy+yz+zx$ 이상이고, 겉넓이 조건에서 $xy+yz+zx=\\frac{1}{2}$이다.","확인":"1/2","스킬":"A6","고비":true},{"제목":"등호 조건과 대각선 길이의 최솟값","힌트":"제곱합이 하한과 같아질 수 있는 때는 언제이고, 그때 대각선은 얼마인가?","식":["등호: $x=y=z=\\frac{\\sqrt{6}}{6}$","대각선 $\\ge\\sqrt{\\frac{1}{2}}=\\frac{\\sqrt{2}}{2}$"],"설명":"등호는 $x=y=z$일 때 성립하고, $6x^2=1$에서 $x=\\frac{\\sqrt{6}}{6}$이므로 등호가 실제로 가능하다. 따라서 대각선의 길이의 최솟값은 $\\frac{\\sqrt{2}}{2}$이다.","확인":null,"스킬":"A2"}]},"ns-00d8c8b2532b":{"길":"f의 여섯 번 합성값 2에서 거꾸로 올라가며 가능한 갈래만 남긴다","단계":[{"제목":"f의 5제곱 합성값 구하기","힌트":"$2$는 $3x+1$꼴(나머지가 $1$인 수)인가? 아니라면 어느 쪽 식으로 나온 값인가?","식":["$2$는 $3$으로 나눈 나머지가 $2$이므로 $3x+1$꼴이 아니다","$f^{5}(x)=2^2=4$"],"설명":"$3x+1$은 $3$으로 나눈 나머지가 $1$인 수이다. $2$는 나머지가 $2$이므로 제곱근 쪽으로만 나오고, $f^{5}(x)=2^2=4$이다.","확인":"4","스킬":"C5"},{"제목":"f의 4제곱 합성값 구하기","힌트":"$4$를 만드는 값은 제곱근 쪽과 $3x+1$ 쪽에서 각각 무엇이며, 둘 다 가능한가?","식":["$f(y)=4$: $y=4^2=16$ 또는 $y=1$ ($3\\cdot1+1=4$)","$f(1)=\\sqrt{1}=1\\ne4$이므로 $f^{4}(x)=16$"],"설명":"$4=3\\cdot1+1$이므로 $3x+1$ 쪽 후보는 $1$이다. 그러나 $\\sqrt{1}$이 자연수이므로 $f(1)=1$이어서 $4$가 되지 않는다. 따라서 $f^{4}(x)=16$이다.","확인":"16","스킬":"C5"},{"제목":"f의 3제곱·2제곱 합성값의 후보 정리","힌트":"$16$, $5$, $256$을 만드는 값을 같은 방법으로 거꾸로 구하면 각각 무엇인가?","식":["$f^{3}(x)=5$ 또는 $16^2=256$","$f^{2}(x)=25$ ($5$에서), $85$ 또는 $256^2$ ($256$에서)"],"설명":"$16=3\\cdot5+1$이고 $\\sqrt{5}$는 무리수이므로 $f^{3}(x)=5$가 가능하고, 제곱 쪽으로 $256$도 가능하다. $5$는 $3$으로 나눈 나머지가 $2$이므로 제곱 쪽 $25$만 나온다. $256=3\\cdot85+1$이므로 $85$와 $256^2$이 가능하다.","확인":null,"스킬":"N3"},{"제목":"f(x)와 x의 후보 거꾸로 올라가기","힌트":"$25$, $85$에서 한 번 더 거꾸로 올라가 $x$의 후보를 구하되, 제곱근이 자연수인 값은 어떻게 처리하는가?","식":["$f^{2}(x)=25$: $f(x)=8$ 또는 $625$ → $x=64$ 또는 $x=208$","$f^{2}(x)=85$: $f(x)=28$ → $x=784$ ($x=9$는 $f(9)=3$이므로 제외)"],"설명":"$f(x)=8$이면 $x=8^2=64$이고, $f(x)=625$이면 $625=3\\cdot208+1$에서 $x=208$이다. $f(x)=28$이면 $x=28^2=784$이고, $3x+1=28$의 해 $x=9$는 $\\sqrt{9}=3$이 자연수라 $f(9)=3$이므로 쓸 수 없다. $85^2$ 갈래와 $256^2$ 갈래는 값이 훨씬 커서 작은 세 수에 들지 않는다.","확인":null,"스킬":"C5","고비":true},{"제목":"세 수를 정해 n3−n2−n1 계산","힌트":"후보 중 가장 작은 세 수를 차례로 놓고 식에 넣으면 얼마인가?","식":["$n_1=64,\\ n_2=208,\\ n_3=784$","$n_3-n_2-n_1=784-208-64=512$"],"설명":"후보 중 작은 순서대로 $64,\\ 208,\\ 784$이므로 이것이 $n_1,\\ n_2,\\ n_3$이다. 따라서 $n_3-n_2-n_1=784-208-64=512$이다.","확인":"512","스킬":"C5"}]},"ns-01d51ae0cea2":{"길":"f의 값이 어느 구간에 드는지로 나눠 합성함수를 구간별로 쓰고 직선과 만난다","단계":[{"제목":"그래프에서 f와 g의 식 읽기","힌트":"정의역이 $0\\le x\\le2$이므로 격자 한 칸을 $\\frac{1}{2}$로 보면 꺾이는 점의 좌표는?","식":["$f(x)=2x\\ (0\\le x\\le1),\\ \\ f(x)=4-2x\\ (1\\le x\\le2)$","$g(x)=1-x\\ (0\\le x\\le1),\\ \\ g(x)=2x-2\\ (1\\le x\\le2)$"],"설명":"정의역이 $0\\le x\\le2$이므로 격자 한 칸은 $\\frac{1}{2}$이다. $f$는 $(0,0),\\ (1,2),\\ (2,0)$을 잇는 꺾은선이고, $g$는 $(0,1),\\ (1,0),\\ (2,2)$를 잇는 꺾은선이다.","확인":null,"스킬":"G9"},{"제목":"f의 값의 크기로 g∘f를 구간별로 쓰기","힌트":"$f(x)$가 $1$ 이하인 구간과 $1$ 이상인 구간으로 나누어 $g$의 식을 고르면?","식":["$f(x)\\le1$이면 $g=1-f(x)$, $f(x)\\ge1$이면 $g=2f(x)-2$","$0\\le x\\le\\frac{1}{2}$: $1-2x$, $\\frac{1}{2}\\le x\\le1$: $4x-2$","$1\\le x\\le\\frac{3}{2}$: $6-4x$, $\\frac{3}{2}\\le x\\le2$: $2x-3$"],"설명":"$g$는 입력이 $1$ 이하일 때 $1-u$, $1$ 이상일 때 $2u-2$이므로 $f(x)$와 $1$의 대소로 구간을 나눈다. $f(x)=1$인 점은 $x=\\frac{1}{2},\\ \\frac{3}{2}$이다. 각 구간에 $f$의 식을 넣으면 위의 네 식이 나온다.","확인":null,"스킬":"T6","고비":true},{"제목":"직선과 구간별로 교점 구하기","힌트":"직선 $y=\\frac{1}{2}x-\\frac{1}{4}$와 각 구간의 식을 연립하면 구간 안에 들어오는 해는?","식":["$1-2x=\\frac{1}{2}x-\\frac{1}{4}$, $4x-2=\\frac{1}{2}x-\\frac{1}{4} \\Rightarrow x=\\frac{1}{2}$","$6-4x=\\frac{1}{2}x-\\frac{1}{4} \\Rightarrow x=\\frac{25}{18}$","$2x-3=\\frac{1}{2}x-\\frac{1}{4} \\Rightarrow x=\\frac{11}{6}$"],"설명":"첫 두 구간의 식은 모두 $x=\\frac{1}{2}$에서 직선과 만난다. $x=\\frac{25}{18}$은 $1\\le x\\le\\frac{3}{2}$에, $x=\\frac{11}{6}$은 $\\frac{3}{2}\\le x\\le2$에 속하므로 적합하다.","확인":null,"스킬":"G1"},{"제목":"겹치는 교점을 빼고 개수 세기","힌트":"$x=\\frac{1}{2}$는 두 구간의 경계에서 같은 점인데, 서로 다른 교점은 모두 몇 개인가?","식":["교점의 $x$좌표: $\\frac{1}{2},\\ \\frac{25}{18},\\ \\frac{11}{6}$","서로 다른 교점은 $3$개"],"설명":"$x=\\frac{1}{2}$는 첫 두 구간이 만나는 꼭짓점 $\\left(\\frac{1}{2},\\ 0\\right)$이므로 한 점으로 센다. 따라서 교점은 $3$개이다.","확인":"3","스킬":"G1"}]},"ns-0387dde143c0":{"길":"일대일 조건으로 a의 범위를 잡고 a+b를 a의 이차식으로 쓴다","단계":[{"제목":"일대일 조건으로 a의 범위 정하기","힌트":"이차함수가 일대일이 되도록 하는 $a$의 최솟값은? (축의 위치를 생각한다)","식":["$f(x)=(x-2)^2+k-4$, 축 $x=2$","정의역 $x\\ge a$에서 일대일 $\\Rightarrow a\\ge2$"],"설명":"$a<2$이면 축 $x=2$를 사이에 둔 서로 다른 두 값이 같은 함숫값을 가지므로 (가)를 어긴다. 따라서 $a\\ge2$이다.","확인":"2","스킬":"T3"},{"제목":"b를 a와 k로 나타내고 a+b 식 세우기","힌트":"$a\\ge2$에서 $f$는 증가하므로 치역의 최솟값 $b$는 어느 점의 함숫값인가?","식":["$b=f(a)=a^2-4a+k$","$a+b=a^2-3a+k$"],"설명":"$a\\ge2$이면 $x\\ge a$에서 $f$가 증가하므로 치역은 $y\\ge f(a)$이고 $b=f(a)$이다. 따라서 $a+b=a+a^2-4a+k=a^2-3a+k$이다.","확인":null,"스킬":"G7"},{"제목":"a+b의 최솟값으로 k 구하기","힌트":"$a\\ge2$에서 $a^2-3a+k$는 어느 $a$에서 최소가 되는가? 그 값이 $7$이 되게 하는 $k$는?","식":["$a+b=\\left(a-\\frac{3}{2}\\right)^2+k-\\frac{9}{4}$","$a\\ge2$에서 증가하므로 $a=2$일 때 최솟값 $k-2$","$k-2=7 \\Rightarrow k=9$"],"설명":"$a^2-3a+k$의 꼭짓점의 $a$좌표는 $\\frac{3}{2}$로 구간 $a\\ge2$의 왼쪽에 있으므로 이 구간에서는 증가한다. 최솟값은 $a=2$에서 $k-2$이고, (나)에서 이 값이 $7$이므로 $k=9$이다.","확인":"9","스킬":"G7","고비":true}]},"ns-05c49cb81300":{"길":"항등함수 조건을 방정식으로 바꾸고 절댓값을 구간별로 푼다","단계":[{"제목":"항등함수 조건을 방정식으로 바꾸기","힌트":"$h$가 항등함수이면 $a$, $b$에서 $h$의 값은 각각 무엇인가?","식":["$h(a)=a,\\ h(b)=b$","$h(x)=x \\iff |x+1|+|2x-1|=2x+2$"],"설명":"항등함수는 정의역의 모든 원소를 자기 자신으로 보내므로 $a,\\ b$는 $h(x)=x$의 서로 다른 해이다. $2h(x)=f(x)+g(x)$를 대입하면 $|x+1|+|2x-1|-2=2x$, 즉 $|x+1|+|2x-1|=2x+2$이다.","확인":null,"스킬":"C7"},{"제목":"절댓값 안의 부호로 구간 나누어 풀기","힌트":"$x+1$과 $2x-1$이 $0$이 되는 값을 기준으로 세 구간에서 각각 풀면?","식":["$x<-1$: $-3x=2x+2 \\Rightarrow x=-\\frac{2}{5}$ (구간 밖)","$-1\\le x<\\frac{1}{2}$: $2-x=2x+2 \\Rightarrow x=0$","$x\\ge\\frac{1}{2}$: $3x=2x+2 \\Rightarrow x=2$"],"설명":"$x=-1,\\ x=\\frac{1}{2}$를 기준으로 절댓값을 풀어 구간별로 방정식을 세운다. 첫 구간의 해 $-\\frac{2}{5}$는 구간에 속하지 않아 버리고, 나머지 두 구간에서 $x=0,\\ x=2$를 얻는다.","확인":null,"스킬":"G5","고비":true},{"제목":"두 해로 |a−b| 구하기","힌트":"해가 둘뿐이므로 $\\{a,\\ b\\}$는 무엇이고 $|a-b|$는 얼마인가?","식":["$\\{a,\\ b\\}=\\{0,\\ 2\\}$","$|a-b|=|0-2|=2$"],"설명":"방정식의 해가 $0$, $2$뿐이므로 서로 다른 두 상수 $a,\\ b$는 $0$과 $2$이다. 따라서 $|a-b|=2$이다.","확인":"2","스킬":"C2"}]},"ns-067d17d89ab2":{"길":"합성을 몇 번 해 보면서 1로 돌아오는 주기를 찾는다","단계":[{"제목":"합성을 반복해 주기 찾기","힌트":"그림에서 $f(1)$부터 차례로 구하면 $f^{3}(1)$은 얼마인가?","식":["$f(1)=3,\\ f^{2}(1)=f(3)=4,\\ f^{3}(1)=f(4)=1$"],"설명":"그림에서 $1\\to3$, $3\\to4$, $4\\to1$이므로 세 번 합성하면 다시 $1$이 된다. 따라서 $f^{n}(1)$은 $3$을 주기로 같은 값이 반복된다.","확인":"1","스킬":"P7"},{"제목":"지수를 주기로 나눈 나머지 구하기","힌트":"$2018$과 $2019$를 $3$으로 나눈 나머지로 $f^{2018}(1)$은 어느 값과 같은가?","식":["$2018=3\\times672+2,\\ \\ 2019=3\\times673$","$f^{2018}(1)=f^{2}(1)=4,\\ \\ f^{2019}(1)=f^{3}(1)=1$"],"설명":"$2018$을 $3$으로 나눈 나머지가 $2$이므로 $f^{2018}(1)=f^{2}(1)=4$이다. $2019$는 $3$의 배수이므로 $f^{2019}(1)=f^{3}(1)=1$이다.","확인":"4","스킬":"P7","고비":true},{"제목":"두 값의 차 계산","힌트":"$f^{2018}(1)-f^{2019}(1)$의 값은?","식":["$f^{2018}(1)-f^{2019}(1)=4-1=3$"],"설명":"앞 단계의 두 값을 빼면 $4-1=3$이다.","확인":"3","스킬":"P7"}]},"ns-0753bff56339":{"길":"f(x)를 t로 두고 바깥 f부터 풀어 t의 값을 정한 뒤 x를 구한다","단계":[{"제목":"그래프에서 f의 식 읽기","힌트":"그래프가 지나는 세 점의 좌표를 읽고 두 구간의 식을 구하면?","식":["$f(x)=3-3x\\ (0\\le x\\le1)$","$f(x)=\\frac{x-1}{2}\\ (1\\le x\\le3)$"],"설명":"그래프는 $(0,3),\\ (1,0),\\ (3,1)$을 차례로 잇는다. 첫 구간의 기울기는 $-3$, 둘째 구간의 기울기는 $\\frac{1}{2}$이다. 치역은 $0\\le y\\le3$이다.","확인":null,"스킬":"G9"},{"제목":"f(x)를 t로 두고 f(t)=2−t 풀기","힌트":"$t=f(x)$로 치환하면 방정식은 어떤 꼴이 되고, $t$는 어느 범위에서 구하는가?","식":["$f(t)=2-t\\ (0\\le t\\le3)$","$0\\le t\\le1$: $3-3t=2-t \\Rightarrow t=\\frac{1}{2}$","$1\\le t\\le3$: $\\frac{t-1}{2}=2-t \\Rightarrow t=\\frac{5}{3}$"],"설명":"$t=f(x)$는 치역 $0\\le t\\le3$ 안의 값이고 방정식은 $f(t)=2-t$가 된다. 구간별로 풀면 두 해가 모두 해당 구간 안에 있으므로 $t=\\frac{1}{2}$ 또는 $t=\\frac{5}{3}$이다.","확인":null,"스킬":"T6","고비":true},{"제목":"f(x)=1/2의 근 구하기","힌트":"두 구간에서 각각 $f(x)=\\frac{1}{2}$인 $x$는 구간 안에 있는가? 근은 몇 개인가?","식":["$3-3x=\\frac{1}{2} \\Rightarrow x=\\frac{5}{6}$","$\\frac{x-1}{2}=\\frac{1}{2} \\Rightarrow x=2$"],"설명":"$x=\\frac{5}{6}$은 $0\\le x\\le1$에, $x=2$는 $1\\le x\\le3$에 속하므로 모두 적합하다. 따라서 근은 $2$개이다.","확인":"2","스킬":"G1"},{"제목":"f(x)=5/3의 근과 전체 개수","힌트":"$f(x)=\\frac{5}{3}$은 두 구간에서 각각 근이 구간 안에 있는가? 서로 다른 근은 모두 몇 개인가?","식":["$3-3x=\\frac{5}{3} \\Rightarrow x=\\frac{4}{9}$","$\\frac{x-1}{2}=\\frac{5}{3} \\Rightarrow x=\\frac{13}{3}>3$ (구간 밖)","근: $\\frac{4}{9},\\ \\frac{5}{6},\\ 2$"],"설명":"둘째 구간에서 $f$의 값은 $1$ 이하이므로 $\\frac{5}{3}$은 첫 구간에서만 나오고 $x=\\frac{4}{9}$이다. 앞의 두 근과 겹치지 않으므로 서로 다른 실근은 $3$개이다.","확인":"3","스킬":"G1"}]},"ns-076ba1a2df5d":{"길":"f=g가 되는 X를 방정식의 해 집합의 부분집합으로 보고 해의 개수를 정한다","단계":[{"제목":"f=g를 방정식으로 바꾸고 X의 의미 파악","힌트":"$f=g$가 성립하려면 $X$의 모든 원소 $x$가 어떤 식을 만족해야 하는가?","식":["$x^2-2x-2=3x-k \\iff x^2-5x+k-2=0$","$X\\subset\\{x\\mid x^2-5x+k-2=0\\}$, $X\\ne\\varnothing$"],"설명":"두 함수가 같으려면 정의역의 모든 $x$에서 $f(x)=g(x)$이어야 한다. 따라서 $X$는 방정식 $x^2-5x+k-2=0$의 실근으로 이루어진 집합의 공집합이 아닌 부분집합이다.","확인":null,"스킬":"G1"},{"제목":"X가 3개가 되는 해의 개수 정하기","힌트":"해의 집합의 원소가 $n$개일 때 공집합이 아닌 부분집합은 몇 개이고, 그것이 $3$이 되는 $n$은?","식":["해가 $n$개이면 $X$의 개수는 $2^n-1$","$2^n-1=3 \\Rightarrow n=2$"],"설명":"해가 $n$개이면 공집합이 아닌 부분집합은 $2^n-1$개이다. $2^n-1=3$에서 $n=2$이므로 방정식은 서로 다른 두 실근을 가져야 한다.","확인":"2","스킬":"C4","고비":true},{"제목":"판별식으로 k의 범위 구하기","힌트":"서로 다른 두 실근을 가지려면 판별식은 어떤 부호이어야 하는가?","식":["$D=(-5)^2-4(k-2)=33-4k>0$","$k<\\frac{33}{4}$"],"설명":"서로 다른 두 실근을 가질 조건은 $D>0$이다. 계산하면 $k<\\frac{33}{4}$이다.","확인":"33/4","스킬":"G2"},{"제목":"조건을 만족하는 자연수 k 세기","힌트":"$k<\\frac{33}{4}=8.25$인 자연수는 몇 개인가?","식":["$k=1,\\ 2,\\ \\cdots,\\ 8$"],"설명":"$\\frac{33}{4}=8.25$이므로 조건을 만족하는 자연수 $k$는 $1$부터 $8$까지이다.","확인":"8","스킬":"G2"}]},"ns-09e81f7698a3":{"길":"f의 세제곱이 항등이면 원소가 자기 자신 또는 세 원소 고리로 짝지어진다","단계":[{"제목":"f³=항등이 되는 순환 구조 분류","힌트":"각 원소가 $f$를 거듭 적용해 제자리로 돌아오는 최소 횟수는 어떤 수의 약수이어야 하는가? 가능한 구조는 몇 가지인가?","식":["돌아오는 최소 횟수는 $1$ 또는 $3$","자기 자신 $6$개 / $3$순환 $1$개와 자기 자신 $3$개 / $3$순환 $2$개"],"설명":"$f$는 일대일대응이므로 원소들이 순환 고리로 나뉘고, $f^3$이 항등이면 고리의 길이는 $3$의 약수인 $1$ 또는 $3$이다. $6$개를 길이 $1$, $3$의 고리로 나누는 방법은 모두 $3$가지이다.","확인":"3","스킬":"C2"},{"제목":"3순환 한 개와 고정점 세 개인 경우","힌트":"순환에 들어갈 $3$개를 고른 뒤, 그 $3$개를 순환시키는 방법은 몇 가지인가?","식":["${}_{6}\\mathrm{C}_{3}\\times2=20\\times2=40$"],"설명":"순환에 넣을 $3$개를 고르는 방법은 ${}_{6}\\mathrm{C}_{3}=20$가지이다. 고른 $a,\\ b,\\ c$는 $a\\to b\\to c\\to a$ 또는 $a\\to c\\to b\\to a$의 $2$가지로 순환시킬 수 있다. 나머지 $3$개는 자기 자신에 대응한다.","확인":"40","스킬":"P4"},{"제목":"3개씩 두 조로 나누는 방법","힌트":"$6$개를 $3$개씩 두 조로 나누되 조의 순서를 구별하지 않으면 몇 가지인가?","식":["$\\frac{{}_{6}\\mathrm{C}_{3}\\times{}_{3}\\mathrm{C}_{3}}{2}=\\frac{20}{2}=10$"],"설명":"$3$개를 먼저 고르면 나머지 $3$개가 자동으로 한 조가 되어 $20$가지이다. 그런데 두 조의 순서는 구별하지 않으므로 같은 나눔이 $2$번씩 세어져 $2$로 나눈다.","확인":"10","스킬":"P3","고비":true},{"제목":"순환 방향을 곱해 모든 경우 더하기","힌트":"각 조를 순환시키는 방법은 $2$가지씩이다. 두 순환의 경우의 수와 전체 합은?","식":["두 개의 $3$순환: $10\\times2\\times2=40$","$1+40+40=81$"],"설명":"각 조의 순환 방향이 $2$가지씩이므로 두 조가 순환하는 경우는 $10\\times2\\times2=40$가지이다. 모두 자기 자신에 대응하는 경우가 $1$가지이므로 전체는 $1+40+40=81$가지이다.","확인":"81","스킬":"P4"}]},"ns-0ad408c5e8a9":{"길":"감소함수의 성질로 값의 순서를 정해 보기를 하나씩 따진다","단계":[{"제목":"감소 조건으로 f(a), f(b), 1의 순서 정하기","힌트":"$f$가 감소하고 $f(1)=1$일 때 $a<b<1$이면 $f(a)$, $f(b)$는 $1$과 어떤 관계인가?","식":["$a<b<1 \\Rightarrow f(a)>f(b)>f(1)=1$"],"설명":"$x_1<x_2$이면 $f(x_1)>f(x_2)$이므로 $f$는 감소한다. $0<a<b<1$이므로 $f(a)>f(b)>f(1)=1$이다.","확인":null,"스킬":"C3"},{"제목":"ㄱ의 f∘f 값을 1과 비교","힌트":"$f(a)>1$을 다시 $f$에 넣으면 $f(f(a))$와 $1$의 대소는?","식":["$f(a)>1 \\Rightarrow f(f(a))<f(1)=1$","$(f\\circ f)(a)<1<f(b)$이므로 ㄱ은 거짓"],"설명":"$f$가 감소하므로 $f(a)>1$이면 $f(f(a))<f(1)=1$이다. 한편 $f(b)>1$이므로 $f(b)<(f\\circ f)(a)$는 성립하지 않는다.","확인":null,"스킬":"C3"},{"제목":"ㄴ의 분수 크기 비교","힌트":"분자 $f(a)$와 $f(b)$, 분모 $a$와 $b$의 크기 관계를 따로 보면?","식":["$f(a)>f(b)>0,\\ \\ \\frac{1}{a}>\\frac{1}{b}>0$","$\\frac{f(a)}{a}>\\frac{f(b)}{b}$ (ㄴ 참)"],"설명":"$f$의 치역이 양수이므로 $f(a)>f(b)>0$이다. 또 $0<a<b$이면 $\\frac{1}{a}>\\frac{1}{b}>0$이다. 양수끼리 큰 쪽끼리 곱하면 $\\frac{f(a)}{a}>\\frac{f(b)}{b}$이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ의 역함수 합성의 증가·감소","힌트":"감소함수의 역함수는 증가하는가 감소하는가? 같은 함수를 두 번 합성하면?","식":["$f$ 감소 $\\Rightarrow f^{-1}$도 감소","$f^{-1}\\circ f^{-1}$은 증가 $\\Rightarrow (f^{-1}\\circ f^{-1})(a)<(f^{-1}\\circ f^{-1})(b)$ (ㄷ 참)","옳은 것: ㄴ, ㄷ"],"설명":"역함수가 존재한다고 보고 따진다. 감소함수의 역함수도 감소하고, 감소함수를 두 번 합성하면 증가함수가 되므로 $a<b$이면 $(f^{-1}\\circ f^{-1})(a)<(f^{-1}\\circ f^{-1})(b)$이다. 따라서 옳은 것은 ㄴ, ㄷ이다.","확인":null,"스킬":"T1","고비":true}]},"ns-0c07093ee9b2":{"길":"역함수가 있으려면 일대일대응이므로 시작점이 y=x 위에 놓인다","단계":[{"제목":"일대일 조건으로 k의 범위 정하기","힌트":"$f(x)=x^2-5x$의 축의 $x$좌표는 얼마인가?","식":["$f(x)=\\left(x-\\frac{5}{2}\\right)^2-\\frac{25}{4}$, 축 $x=\\frac{5}{2}$","$x\\ge k$에서 일대일 $\\Rightarrow k\\ge\\frac{5}{2}$"],"설명":"역함수가 존재하려면 $f:X\\to X$가 일대일대응이어야 한다. 일대일이려면 정의역이 축의 한쪽에만 있어야 하므로 $k\\ge\\frac{5}{2}$이다.","확인":"5/2","스킬":"T1"},{"제목":"공역과 치역이 같을 조건 세우기","힌트":"$k\\ge\\frac{5}{2}$에서 $f$는 증가한다. 치역이 $\\{y\\mid y\\ge k\\}$와 같으려면 어느 점의 함숫값이 $k$이어야 하는가?","식":["$k\\ge\\frac{5}{2}$에서 증가: 치역 $\\{y\\mid y\\ge f(k)\\}$","치역=공역 $\\Rightarrow f(k)=k$"],"설명":"정의역이 $x\\ge k$이고 $f$가 증가하므로 치역은 $y\\ge f(k)$이다. 공역이 $\\{y\\mid y\\ge k\\}$이므로 둘이 같으려면 $f(k)=k$이어야 한다. 즉 그래프의 시작점이 직선 $y=x$ 위에 놓인다.","확인":null,"스킬":"T1","고비":true},{"제목":"f(k)=k를 풀고 조건에 맞는 k 고르기","힌트":"$k^2-5k=k$의 해 중 $k\\ge\\frac{5}{2}$를 만족하는 것은?","식":["$k^2-5k=k \\Rightarrow k(k-6)=0$","$k=0$ 또는 $k=6$, $k\\ge\\frac{5}{2}$이므로 $k=6$"],"설명":"$k^2-6k=0$에서 $k=0$ 또는 $k=6$이다. $k\\ge\\frac{5}{2}$이므로 $k=0$은 제외되어 $k=6$이다.","확인":"6","스킬":"G1"}]},"ns-0c6362dd46ff":{"길":"f∘f가 항등이면 자기 자신 또는 두 원소 맞바꿈으로만 짝지어진다","단계":[{"제목":"f∘f=항등이 되는 구조 분류","힌트":"$f(a)=b$이면 $f(b)$는 무엇이어야 하는가? 자기 자신에 대응되는 원소의 개수로 나누면 가능한 경우는 몇 가지인가?","식":["$f(a)=b \\Rightarrow f(b)=a$","자기 자신에 대응하는 원소의 개수: $5,\\ 3,\\ 1$"],"설명":"$(f\\circ f)(a)=a$이므로 $f(a)=b$이면 $f(b)=a$이다. 그래서 원소는 자기 자신에 대응하거나 두 원소가 서로 맞바꿔진다. 맞바꿈이 $0$쌍, $1$쌍, $2$쌍이면 자기 자신에 대응하는 원소는 각각 $5$개, $3$개, $1$개이다.","확인":"3","스킬":"P4"},{"제목":"자기 자신에 대응하는 원소가 1개인 경우 세기","힌트":"그런 원소를 하나 고른 뒤, 나머지 $4$개를 $2$개씩 두 쌍으로 나누는 방법은 몇 가지인가?","식":["${}_{5}\\mathrm{C}_{1}=5$","$\\frac{{}_{4}\\mathrm{C}_{2}\\times{}_{2}\\mathrm{C}_{2}}{2}=3$","$5\\times3=15$"],"설명":"자기 자신에 대응할 원소를 고르는 방법은 $5$가지이다. 나머지 $4$개를 두 쌍으로 나누는 방법은 쌍의 순서를 구별하지 않으므로 $\\frac{6\\times1}{2}=3$가지이다. 각 쌍은 서로 맞바꾸는 방법이 하나뿐이다.","확인":"15","스킬":"P4","고비":true},{"제목":"자기 자신에 대응하는 원소가 3개인 경우 세기","힌트":"그런 원소 $3$개를 고르면 나머지 $2$개는 어떻게 되는가?","식":["${}_{5}\\mathrm{C}_{3}=10$"],"설명":"자기 자신에 대응할 $3$개를 고르면 나머지 $2$개는 서로 맞바꿔야 하므로 $1$가지로 정해진다. 따라서 ${}_{5}\\mathrm{C}_{3}=10$가지이다.","확인":"10","스킬":"P4"},{"제목":"5개 모두 자기 자신인 경우와 전체 합","힌트":"모든 원소가 자기 자신에 대응하는 경우까지 더하면 전체는?","식":["모두 자기 자신: $1$가지","$15+10+1=26$"],"설명":"모든 원소가 자기 자신에 대응하는 경우는 항등함수 $1$가지이다. 따라서 전체는 $15+10+1=26$이다.","확인":"26","스킬":"P4"}]},"ns-0c830ffb40b9":{"길":"두 칸 옮길 때마다 높이가 절반이므로 최댓값이 충분히 큰 구간까지만 본다","단계":[{"제목":"(나)로 각 구간에서 f의 식 구하기","힌트":"(나)를 반복해 쓰면 $2k\\le x<2k+2$에서 $f(x)$와 $f(x-2k)$는 어떤 관계인가?","식":["$f(x)=\\left(\\frac{1}{2}\\right)^{k}f(x-2k)$","$2k\\le x<2k+2$: $f(x)=\\frac{8(x-2k)(2k+2-x)}{2^k}$"],"설명":"(나)에서 $x$가 $2$ 늘어날 때마다 함숫값이 $\\frac{1}{2}$배가 된다. $2k\\le x<2k+2$에서는 $0\\le x-2k<2$이므로 (가)를 이용해 위의 식을 얻는다.","확인":null,"스킬":"T2"},{"제목":"f(x)=1이 가능한 구간의 범위 정하기","힌트":"각 구간 $[2k,\\ 2k+2)$에서 $f$의 최댓값은 얼마이고, 그것이 $1$ 이상이 되는 $k$의 최댓값은?","식":["$[2k,\\ 2k+2)$에서 최댓값 $\\frac{8}{2^k}$ (꼭짓점 $x=2k+1$)","$\\frac{8}{2^k}\\ge1 \\Rightarrow k\\le3$"],"설명":"(가)의 최댓값은 $x=1$에서 $8$이므로 $k$번째 구간의 최댓값은 $\\frac{8}{2^k}$이다. 이것이 $1$ 이상이어야 $f(x)=1$인 점이 있으므로 $k=0,\\ 1,\\ 2,\\ 3$만 살핀다.","확인":"3","스킬":"T2"},{"제목":"k=0, 1, 2 구간에서 근의 합 구하기","힌트":"$t=x-2k$로 두면 $f(x)=1$은 $8t(2-t)=2^k$ 꼴이다. 두 근의 합은 $x$로는 얼마인가?","식":["$8t^2-16t+2^k=0$, 근의 합 $t_1+t_2=2$","$x_1+x_2=2+4k$","$k=0,\\ 1,\\ 2$: $2+6+10=18$"],"설명":"$2^k<8$이므로 이차방정식은 대칭축 $t=1$ 양쪽에 $0\\le t<2$인 서로 다른 두 근을 가지고, 근의 합은 $2$이다. $x=t+2k$이므로 구간마다 근의 합은 $2+4k$이다. 따라서 $k=0,\\ 1,\\ 2$에서 합은 $2,\\ 6,\\ 10$이다.","확인":"18","스킬":"G1","고비":true},{"제목":"k=3 구간의 근과 전체 합","힌트":"$k=3$에서 $f$의 최댓값이 $1$이므로 $f(x)=1$인 점은 몇 개이고 어디인가?","식":["$8t(2-t)=8 \\Rightarrow (t-1)^2=0 \\Rightarrow t=1,\\ x=7$","$18+7=25$"],"설명":"$k=3$에서는 최댓값이 $1$이므로 꼭짓점에서만 $f(x)=1$이고 $x=2\\cdot3+1=7$이다. $k\\ge4$에서는 최댓값이 $1$보다 작아 해가 없다. 따라서 $P$의 원소의 합은 $18+7=25$이다.","확인":"25","스킬":"T2"}]},"ns-0f6882c0e118":{"길":"g의 값 전체가 f가 0 이상인 구간에 들어가도록 a의 조건을 세운다","단계":[{"제목":"f가 0 이상이 되는 범위","힌트":"$f(t)$를 인수분해하면 어떤 두 일차식의 곱인가?","식":["$f(t)=(t-3)(t+2)\\ge 0$","$t\\le -2$ 또는 $t\\ge 3$"],"설명":"$(f\\circ g)(x)\\ge 0$이 되려면 $g(x)$의 값이 이 범위 안에 있어야 한다.","확인":null,"스킬":"T6"},{"제목":"g의 값이 놓일 구간 고르기","힌트":"$g(x)$는 $x$가 커지면 값이 어떻게 되는가?","식":["$g(x)\\ge 3$"],"설명":"$g(x)$는 아래로 볼록한 포물선이라 값이 끝없이 커진다. 따라서 $g(x)\\le -2$인 쪽에는 모든 값이 들어갈 수 없고, 모든 $x$에서 $g(x)\\ge 3$이어야 한다.","확인":null,"스킬":"T3","고비":true},{"제목":"항상 성립하는 이차부등식 만들기","힌트":"$x^{2}-ax+4\\ge 3$을 한쪽으로 정리하면 판별식 조건은?","식":["$x^{2}-ax+1\\ge 0$","$D=a^{2}-4\\le 0$"],"설명":"모든 실수 $x$에서 아래로 볼록한 이차식이 $0$ 이상이려면 판별식이 $0$ 이하여야 한다.","확인":null,"스킬":"C1"},{"제목":"a의 범위와 p, q 정하기","힌트":"$(a-2)(a+2)\\le 0$의 해는?","식":["$-2\\le a\\le 2$","$p=-2,\\ q=2$"],"설명":"$a^{2}\\le 4$이므로 $a$의 범위는 $-2$ 이상 $2$ 이하이다. $p$는 범위의 왼쪽 끝, $q$는 오른쪽 끝이다.","확인":"-2","스킬":"G6"},{"제목":"제곱의 합 계산","힌트":"$p^{2}+q^{2}$에 $p,\\ q$를 넣으면?","식":["$p^{2}+q^{2}=(-2)^{2}+2^{2}=8$"],"설명":"$p=-2$이므로 $p^{2}=4$이고 $q^{2}=4$이다.","확인":"8","스킬":"C1"}]},"ns-1217e5526c28":{"길":"점 좌표를 역함수 g로 이어 쓰고 사다리꼴 넓이에 대입한다","단계":[{"제목":"점의 좌표를 f의 식으로 쓰기","힌트":"$\\mathrm{B}_1$과 $\\mathrm{A}_2$는 높이가 같다. 그 높이를 $f$로 쓰면?","식":["$f(b)=a,\\ f(c)=b,\\ f(d)=c$"],"설명":"$\\mathrm{B}_1$이 직선 $y=x$ 위에 있으므로 $\\mathrm{B}_1(a,\\ a)$이고, $x$축에 평행하게 그어 만나는 $\\mathrm{A}_2$의 $y$좌표도 $a$이다. $\\mathrm{A}_2$는 $y=f(x)$ 위의 점이므로 $f(b)=a$이다. 같은 과정이 $\\mathrm{A}_3,\\ \\mathrm{A}_4$에서도 반복된다.","확인":null,"스킬":"T1"},{"제목":"역함수 g로 바꿔 쓰기","힌트":"$f(b)=a$를 $b$에 대해 풀면 $g$로 어떻게 쓰는가?","식":["$b=g(a),\\ c=g(b),\\ d=g(c)$"],"설명":"$g$는 $f$의 역함수이므로 $f(b)=a$는 $b=g(a)$와 같다.","확인":null,"스킬":"T1"},{"제목":"c, d를 a, b로 나타내기","힌트":"$c=g(b)$의 $b$ 자리에 $g(a)$를 넣으면?","식":["$c=g(g(a))=(g\\circ g)(a)$","$d=g(c)=g(g(b))=(g\\circ g)(b)$"],"설명":"넓이를 $a,\\ b$로만 나타내야 하므로 $c,\\ d$를 $g$의 합성으로 바꾼다.","확인":null,"스킬":"T6","고비":true},{"제목":"사다리꼴의 넓이식 세우기","힌트":"$x=c$와 $x=d$에서 $y$축에 평행한 두 변의 길이는 각각 얼마인가?","식":["$f(c)=b,\\ f(d)=c$","$S=\\frac{1}{2}(b+c)(d-c)$"],"설명":"네 점이 이루는 사각형은 $y$축에 평행한 두 변 $f(c),\\ f(d)$를 가진 사다리꼴이고, 높이는 $d-c$이다.","확인":null,"스킬":"S12"},{"제목":"a, b로 나타낸 넓이식 완성","힌트":"$b,\\ c,\\ d$를 앞에서 구한 식으로 바꾸면?","식":["$S=\\frac{1}{2}\\{g(a)+g(b)\\}\\{(g\\circ g)(b)-(g\\circ g)(a)\\}$"],"설명":"$b=g(a),\\ c=(g\\circ g)(a),\\ d=(g\\circ g)(b)$를 대입하면 선지 ①과 같다.","확인":null,"스킬":"T6"}]},"ns-1326e6f76239":{"길":"f(x)를 한 문자로 두고 얻은 방정식을 푼 뒤 x의 값을 모은다","단계":[{"제목":"합성함수식 세우기","힌트":"$(f\\circ f)(x)=f(f(x))$에서 바깥 $f$에 $f(x)$를 넣으면?","식":["$(f\\circ f)(x)=|f(x)-a|$","$|f(x)-a|=f(x)$"],"설명":"바깥 함수 $f$의 $x$ 자리에 $f(x)$를 넣는다.","확인":null,"스킬":"T6"},{"제목":"f(x)의 값 정하기","힌트":"$f(x)=t$로 두면 $t\\ge 0$이다. $|t-a|$의 절댓값을 벗기려면 어디서 나누는가?","식":["$t\\ge a$: $t-a=t$ → 해 없음","$0\\le t<a$: $a-t=t$ → $t=\\frac{a}{2}$"],"설명":"$t=|x-a|\\ge 0$이다. $t\\ge a$이면 $t-a=t$에서 $a=0$이 되어 $a>0$에 모순이므로 해가 없다. $t<a$일 때만 $t=\\frac{a}{2}$이다.","확인":null,"스킬":"C2","고비":true},{"제목":"x의 값 구하기","힌트":"$|x-a|=\\frac{a}{2}$를 만족하는 $x$는 두 개이다. 각각은?","식":["$x-a=\\pm\\frac{a}{2}$","$x=\\frac{a}{2},\\ \\frac{3a}{2}$"],"설명":"$f(x)=\\frac{a}{2}$이므로 $x-a$는 $\\frac{a}{2}$ 또는 $-\\frac{a}{2}$이다.","확인":null,"스킬":"C2"},{"제목":"합 k와 최종값 계산","힌트":"$k=\\frac{a}{2}+\\frac{3a}{2}$일 때 $16\\times\\frac{k}{a}$는?","식":["$k=2a$","$16\\times\\frac{k}{a}=32$"],"설명":"$k$를 $a$로 나누면 $a$가 약분되어 $2$가 된다.","확인":"32","스킬":"A2"}]},"ns-17554b78a069":{"길":"보기마다 안쪽 함수값이 떨어지는 구간부터 나누어 참거짓을 가린다","단계":[{"제목":"ㄱ의 참거짓 판별","힌트":"$f(10)$을 먼저 구하면?","식":["$f(10)=5,\\ g(5)=4$"],"설명":"$10>2$이므로 $f(10)=10-5=5$이고, $5>4$이므로 $g(5)=4$이다. 따라서 ㄱ은 참이다.","확인":"5","스킬":"T6"},{"제목":"ㄴ에서 안쪽 함수값 구하기","힌트":"$f(t)=1$이 되는 $t$는 어느 구간에서 얼마인가?","식":["$t>2$: $t-5=1$ → $t=6$","$-1\\le t\\le 2$: $-2t+1=1$ → $t=0$","$t<-1$: $f(t)=3$ → 해 없음"],"설명":"$f(x)=t$로 두면 $(f\\circ f)(x)=1$은 $f(t)=1$이다. 구간마다 식이 달라 따로 푼다.","확인":null,"스킬":"C2"},{"제목":"ㄴ의 실근의 합 구하기","힌트":"$f(x)=6$과 $f(x)=0$의 해를 모두 구하면?","식":["$f(x)=6$: $x=11$ ($-\\frac{5}{2}$는 범위 밖)","$f(x)=0$: $x=5,\\ \\frac{1}{2}$","$11+5+\\frac{1}{2}=\\frac{33}{2}$"],"설명":"$f(x)=6$은 $x>2$에서만 해 $11$을 갖고, $f(x)=0$은 $x>2$에서 $5$, $-1\\le x\\le 2$에서 $\\frac{1}{2}$을 갖는다. 합이 $1$이 아니므로 ㄴ은 거짓이다.","확인":"33/2","스킬":"C3"},{"제목":"ㄷ의 구간 나누기","힌트":"$f$는 $x=-1,\\ 2$에서, $g$는 $x=-4,\\ 4$에서 식이 바뀐다. 해가 없는 구간은 어디인가?","식":["$x<-4$: $g(f(x))=3,\\ -g(x)=4$ → 해 없음","$x>4$: $g(f(x))=g(x-5)>-1,\\ -g(x)=-4$ → 해 없음"],"설명":"경계를 모두 모아 $x<-4$, $-4\\le x<-1$, $-1\\le x\\le 2$, $2<x\\le 4$, $x>4$로 나눈다. 양 끝 구간은 두 값이 같을 수 없다.","확인":null,"스킬":"C2","고비":true},{"제목":"ㄷ의 해와 합 구하기","힌트":"남은 세 구간에서 $g(f(x))=-g(x)$를 각각 풀면?","식":["$-4\\le x<-1$: $3=-x$ → $x=-3$","$-1\\le x\\le 2$: $-2x+1=-x$ → $x=1$,  $2<x\\le 4$: $x-5=-x$ → $x=\\frac{5}{2}$","$-3+1+\\frac{5}{2}=\\frac{1}{2}$"],"설명":"구간마다 $f(x)$의 식을 안쪽에 넣고, $g$는 $|t|\\le 4$일 때 $g(t)=t$로 쓴다. 구한 세 값은 모두 해당 구간 안에 있고 합이 $\\frac{1}{2}$이므로 ㄷ은 참이다.","확인":"1/2","스킬":"T6"},{"제목":"참인 보기 모아 선지 고르기","힌트":"ㄱ, ㄴ, ㄷ의 참거짓을 모으면 어떤 선지인가?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참 → ④"],"설명":"옳은 것은 ㄱ과 ㄷ이다.","확인":null,"스킬":"C3"}]},"ns-17b0919c2e52":{"길":"0과 6을 경계로 구간을 나눠 g를 구간마다 일차식으로 쓴다","단계":[{"제목":"구간의 경계 찾기","힌트":"$f(x)$와 $f(x-6)$은 각각 어느 $x$에서 식이 바뀌는가?","식":["$x<0,\\ \\ 0\\le x<6,\\ \\ x\\ge 6$"],"설명":"$f(x)$는 $x=0$에서, $f(x-6)$은 $x-6=0$인 $x=6$에서 식이 바뀐다. 따라서 세 구간으로 나눈다.","확인":null,"스킬":"C2"},{"제목":"구간별 g(x) 구하기","힌트":"각 구간에서 $f(x-6)$과 $f(x)$를 어느 식으로 쓰는가?","식":["$x<0$: $g(x)=(6-x)-(-x)=6$","$0\\le x<6$: $g(x)=(6-x)-\\frac{1}{2}x=6-\\frac{3}{2}x$","$x\\ge 6$: $g(x)=\\frac{x-6}{2}-\\frac{x}{2}=-3$"],"설명":"$x<0$이면 $x-6<0$이다. $0\\le x<6$이면 $x-6<0$이고 $x\\ge 0$이다. $x\\ge 6$이면 둘 다 $0$ 이상이다.","확인":null,"스킬":"C2","고비":true},{"제목":"M, m 읽고 합 구하기","힌트":"가운데 구간에서 $g$는 증가하는가 감소하는가?","식":["$\\mathrm{M}=6,\\ m=-3$","$\\mathrm{M}+m=3$"],"설명":"$0\\le x<6$에서 $g$는 $6$에서 $-3$까지 감소하므로 값의 범위는 $-3$ 이상 $6$ 이하이다.","확인":"3","스킬":"C2"}]},"ns-19de211e3e18":{"길":"g의 값이 f의 꺾이는 점을 지나는 x를 찾아 구간별로 합성한다","단계":[{"제목":"그래프에서 f, g의 식 읽기","힌트":"$f$는 $x=\\frac{2}{3}$에서, $g$는 $x=1$에서 꺾인다. 각 구간의 직선의 식은?","식":["$g(x)=2x\\ (0\\le x\\le 1),\\ \\ \\frac{1}{2}x+\\frac{3}{2}\\ (1\\le x\\le 3)$","$f(x)=\\frac{9}{2}x\\ (0\\le x\\le\\frac{2}{3}),\\ \\ -\\frac{9}{7}x+\\frac{27}{7}\\ (\\frac{2}{3}\\le x\\le 3)$"],"설명":"$g$는 $(0,\\ 0),\\ (1,\\ 2),\\ (3,\\ 3)$을, $f$는 $(0,\\ 0),\\ (\\frac{2}{3},\\ 3),\\ (3,\\ 0)$을 지나는 꺾은선이다.","확인":null,"스킬":"G9"},{"제목":"합성함수가 꺾이는 곳 찾기","힌트":"$g(x)=\\frac{2}{3}$이 되는 $x$는?","식":["$g(x)=\\frac{2}{3}$ → $2x=\\frac{2}{3}$","$x=\\frac{1}{3}$"],"설명":"$f$의 식은 입력이 $\\frac{2}{3}$일 때 바뀌므로 $g(x)=\\frac{2}{3}$인 $x$에서 $f\\circ g$의 식이 바뀐다. $g$ 자체도 $x=1$에서 꺾이므로 경계는 $x=\\frac{1}{3},\\ 1$이다.","확인":"1/3","스킬":"T6","고비":true},{"제목":"구간별로 f(g(x)) 구하기","힌트":"각 구간에서 $g(x)$의 값이 $f$의 어느 식에 들어가는가?","식":["$0\\le x\\le\\frac{1}{3}$: $f(2x)=9x$","$\\frac{1}{3}\\le x\\le 1$: $f(2x)=-\\frac{18}{7}x+\\frac{27}{7}$","$1\\le x\\le 3$: $f\\left(\\frac{x}{2}+\\frac{3}{2}\\right)=-\\frac{9}{14}x+\\frac{27}{14}$"],"설명":"첫 구간에서 $g(x)\\le\\frac{2}{3}$이므로 $f$의 첫째 식을, 나머지 두 구간에서는 $g(x)\\ge\\frac{2}{3}$이므로 둘째 식을 쓴다.","확인":null,"스킬":"T6"},{"제목":"개형 비교하기","힌트":"기울기가 $9,\\ -\\frac{18}{7},\\ -\\frac{9}{14}$ 순이다. 이 순서에 맞는 그래프는?","식":["$(0,\\ 0)\\to\\left(\\frac{1}{3},\\ 3\\right)\\to\\left(1,\\ \\frac{9}{7}\\right)\\to(3,\\ 0)$"],"설명":"처음에 가장 가파르게 올라 $x=\\frac{1}{3}$에서 최대 $3$이 되고, 이후 기울기가 두 번 완만해지며 내려가 $(3,\\ 0)$에 닿는다. 이 모양은 ③이다.","확인":null,"스킬":"T6"}]},"ns-1e9ab35335ce":{"길":"f(x)를 t로 놓고 f(t)=3-t의 t를 구한 뒤 각 t에 대한 x의 개수를 센다","단계":[{"제목":"f(x)를 t로 놓고 식 바꾸기","힌트":"$f(x)=t$로 두면 $f(f(x))$는 어떻게 쓰는가?","식":["$f(t)=3-t$"],"설명":"$f(f(x))=f(t)$이고 $3-f(x)=3-t$이므로 방정식은 $f(t)=3-t$가 된다. 이 방정식의 $t$를 먼저 구한다.","확인":null,"스킬":"T6"},{"제목":"그래프와 직선의 교점 찾기","힌트":"직선 $y=3-t$는 $(0,\\ 3),\\ (3,\\ 0)$을 지난다. 꺾은선과 어느 두 구간에서 만나는가?","식":["$1\\le t\\le 2$: $6-3t=3-t$ → $t=\\frac{3}{2}$","$2\\le t\\le 3$: $4t-8=3-t$ → $t=\\frac{11}{5}$"],"설명":"$f(t)$는 $[1,\\ 2]$에서 $6-3t$, $[2,\\ 3]$에서 $4t-8$이다. $0\\le t\\le 1$에서는 $f(t)\\ge 3$이라 직선보다 위에 있고, $t\\ge 3$에서는 직선의 값이 $0$ 이하라 $f(t)$가 항상 위에 있으므로 더 만나지 않는다.","확인":null,"스킬":"G1","고비":true},{"제목":"t마다 x의 개수 세기","힌트":"수평선 $y=\\frac{3}{2}$와 $y=\\frac{11}{5}$는 꺾은선과 각각 몇 번 만나는가?","식":["$f(x)=\\frac{3}{2}$: $[1,\\ 2],\\ [2,\\ 3],\\ [4,\\ 5]$에서 각 1개 → 3개","$f(x)=\\frac{11}{5}$: 같은 세 구간에서 각 1개 → 3개"],"설명":"두 값 모두 $0$보다 크고 $3$보다 작다. $[1,\\ 2]$에서 내려오며 한 번, $[2,\\ 3]$에서 올라가며 한 번, $[4,\\ 5]$에서 내려오며 한 번 만난다. $[0,\\ 1]$과 $[3,\\ 4]$에서는 $f$의 값이 $3$ 이상이다.","확인":"3","스킬":"G1"},{"제목":"서로 다른 실근의 개수 합하기","힌트":"$t$가 두 값이므로 $x$의 개수를 합하면?","식":["$3+3=6$"],"설명":"$f(x)=\\frac{3}{2}$와 $f(x)=\\frac{11}{5}$는 값이 달라 두 해의 집합이 겹치지 않는다.","확인":"6","스킬":"T6"}]},"ns-2163414cb82f":{"길":"바깥 함수부터 거꾸로 풀며 안쪽 값은 0 이상인 것만 남긴다","단계":[{"제목":"가장 바깥 값 s 구하기","힌트":"$f(f(f(k)))=\\frac{1}{2}$에서 $s=f(f(k))$로 두면 $f(s)=\\frac{1}{2}$의 해는?","식":["$f(s)=\\frac{1}{2}$ → $s=1\\pm\\frac{1}{2}$","$s=\\frac{3}{2},\\ \\frac{1}{2}$"],"설명":"$|s-1|=\\frac{1}{2}$이므로 $s-1=\\pm\\frac{1}{2}$이다.","확인":null,"스킬":"G5"},{"제목":"가운데 값 t 구하기","힌트":"$t=f(k)$는 절댓값이므로 부호가 어떠해야 하는가?","식":["$s=\\frac{1}{2}$: $t=1\\pm\\frac{1}{2}=\\frac{3}{2},\\ \\frac{1}{2}$","$s=\\frac{3}{2}$: $t=1\\pm\\frac{3}{2}=\\frac{5}{2},\\ -\\frac{1}{2}$ (음수는 제외)"],"설명":"$t=f(k)=|k-1|\\ge 0$이어야 하므로 $t=-\\frac{1}{2}$인 경우는 $k$가 존재하지 않는다.","확인":null,"스킬":"C2","고비":true},{"제목":"k의 값 모두 구하기","힌트":"$f(k)=t$는 $k=1\\pm t$이다. 남은 세 $t$에 대해 구하면?","식":["$t=\\frac{1}{2}$: $k=\\frac{1}{2},\\ \\frac{3}{2}$","$t=\\frac{3}{2}$: $k=-\\frac{1}{2},\\ \\frac{5}{2}$","$t=\\frac{5}{2}$: $k=-\\frac{3}{2},\\ \\frac{7}{2}$"],"설명":"각 $t$마다 $k$가 두 개씩 나오고, $t$가 서로 다르므로 $k$도 모두 다르다.","확인":null,"스킬":"G5"},{"제목":"개수 m과 합 n 구하기","힌트":"구한 $k$ 여섯 개의 합은?","식":["$m=6$","$n=\\frac{1}{2}+\\frac{3}{2}-\\frac{1}{2}+\\frac{5}{2}-\\frac{3}{2}+\\frac{7}{2}=6$"],"설명":"$k$는 모두 $6$개이고, 이들의 합도 $6$이다.","확인":"6","스킬":"C1"},{"제목":"m+n의 값","힌트":"$m+n$은?","식":["$m+n=6+6=12$"],"설명":"$m=6,\\ n=6$을 더한다.","확인":"12","스킬":"C1"}]},"ns-234812004dff":{"길":"f(1)을 구하고 g는 차수를 정한 뒤 계수를 비교해 합성값을 구한다","단계":[{"제목":"f(1)의 값 구하기","힌트":"$f(4)$를 $f(1)$의 거듭제곱으로 나타내면?","식":["$f(4)=f(2)^{2}=f(1)^{4}=256$","$f(1)=4$"],"설명":"$f(x+y)=f(x)f(y)$에서 $f(2)=f(1)^{2}$, $f(4)=f(2)^{2}$이다. $f(x)>0$이므로 $f(1)^{4}=256$에서 $f(1)=4$이다.","확인":"4","스킬":"A3"},{"제목":"g의 차수 정하기","힌트":"$g(x)$가 $n$차이면 $g(x)^{2}$은 몇 차인가?","식":["$g(x)^{2}$은 $2n$차, 우변은 $2$차","$2n=2$ → $n=1$"],"설명":"$g(x+1)$은 $n$차이므로 $n\\ge 1$이면 최고차항은 $g(x)^{2}$에서 나온다. 좌변과 우변의 차수가 같아야 한다.","확인":"1","스킬":"A11"},{"제목":"계수 비교 식 세우기","힌트":"$g(x)=ax+b$를 넣고 $x$에 대해 정리하면?","식":["$a(x+1)+b+(ax+b)^{2}=4x^{2}+6x+4$","$a^{2}=4,\\ \\ a+2ab=6,\\ \\ a+b+b^{2}=4$"],"설명":"양변에 $2$를 곱한 뒤 $x^{2},\\ x$의 계수와 상수항을 각각 비교한다.","확인":null,"스킬":"A3","고비":true},{"제목":"a, b의 값 정하기","힌트":"$a^{2}=4$이므로 $a=2$와 $a=-2$를 나머지 두 식에 넣으면?","식":["$a=2$: $2+4b=6$ → $b=1$ (셋째 식도 성립)","$a=-2$: $b=-2$이지만 셋째 식이 성립하지 않음","$g(x)=2x+1$"],"설명":"$a=-2$이면 $-2-4b=6$에서 $b=-2$이고, $a+b+b^{2}=-2-2+4=0\\ne 4$이므로 맞지 않는다.","확인":"2","스킬":"A3"},{"제목":"합성함수의 값 구하기","힌트":"$(g\\circ f)(1)=g(f(1))$에서 $f(1)$ 자리에 구한 값을 넣으면?","식":["$(g\\circ f)(1)=g(4)=2\\times 4+1=9$"],"설명":"$f(1)=4$이므로 $g(4)$를 구한다.","확인":"9","스킬":"T6"}]},"ns-27909b17a77e":{"길":"좌변이 0 이상의 정수임을 이용해 우변이 될 수 있는 값을 좁힌다","단계":[{"제목":"좌변의 정체 파악하기","힌트":"$(h\\circ g\\circ f)(x)$를 $x$로 쓰면?","식":["$(h\\circ g\\circ f)(x)=[\\,|x^{2}-1|\\,]$"],"설명":"$f$, $g$, $h$를 차례로 적용한다. 가우스 기호의 값은 정수이고, 절댓값 안쪽을 거치므로 $0$ 이상이다.","확인":null,"스킬":"N7"},{"제목":"우변이 될 수 있는 값 좁히기","힌트":"$-x^{2}+1$이 $0$ 이상의 정수이려면 어떤 값만 가능한가?","식":["$0\\le -x^{2}+1\\le 1$","$-x^{2}+1=0$ 또는 $1$"],"설명":"$x^{2}\\ge 0$이므로 $-x^{2}+1\\le 1$이다. 좌변이 $0$ 이상의 정수이므로 우변도 $0$ 이상의 정수여야 하고 가능한 값은 $0,\\ 1$뿐이다.","확인":null,"스킬":"N7","고비":true},{"제목":"후보를 넣어 확인하기","힌트":"$-x^{2}+1=0$과 $-x^{2}+1=1$의 해를 좌변에 넣어 보면?","식":["$x=\\pm 1$: 좌변 $[0]=0$, 우변 $0$","$x=0$: 좌변 $[1]=1$, 우변 $1$"],"설명":"세 값 모두 좌변과 우변이 같으므로 실근이다.","확인":null,"스킬":"T6"},{"제목":"실근의 개수 세기","힌트":"실근 $-1,\\ 0,\\ 1$은 모두 몇 개인가?","식":["$-1,\\ 0,\\ 1$ → $3$개"],"설명":"세 값은 서로 다르므로 서로 다른 실근은 $3$개이다.","확인":"3","스킬":"N7"}]},"ns-327711e0bbde":{"길":"f(t)=s의 해 t=1±s를 바깥부터 거꾸로 풀며 음수는 버린다","단계":[{"제목":"한 단계 거꾸로 푸는 규칙","힌트":"$f(t)=s$에서 $t$는 $s$로 어떻게 쓰는가? 안쪽 값이 음수이면 어떻게 되는가?","식":["$f(t)=s\\ \\Leftrightarrow\\ t=1\\pm s$","$t=f_{k}(x)\\ge 0$이므로 $1-s<0$인 값은 제외"],"설명":"$f_{5}(x)=f\\left(f_{4}(x)\\right)$이므로 $f_{4}(x)$는 $f(t)=\\frac{1}{2}$의 해 $t$ 중 $0$ 이상인 값이어야 한다. 이 과정을 안쪽으로 되풀이한다.","확인":null,"스킬":"G5","고비":true},{"제목":"f4, f3이 가질 수 있는 값","힌트":"$f_{5}(x)=\\frac{1}{2}$이면 $f_{4}(x)$, 그 안쪽 $f_{3}(x)$의 값은?","식":["$f_{4}(x)\\in\\left\\{\\frac{1}{2},\\ \\frac{3}{2}\\right\\}$","$f_{3}(x)\\in\\left\\{\\frac{1}{2},\\ \\frac{3}{2},\\ \\frac{5}{2}\\right\\}$"],"설명":"$f_{3}(x)=t$에서 $f(t)=\\frac{1}{2}$이면 $t=\\frac{1}{2},\\frac{3}{2}$이고 $f(t)=\\frac{3}{2}$이면 $t=\\frac{5}{2}$이다. $t=-\\frac{1}{2}$는 음수라 버린다.","확인":null,"스킬":"G5"},{"제목":"f2, f1이 가질 수 있는 값","힌트":"같은 방법으로 $f_{2}(x)$, $f_{1}(x)=f(x)$의 값을 구하면? $f(x)$가 가질 수 있는 값은 모두 몇 개인가?","식":["$f_{2}(x)\\in\\left\\{\\frac{1}{2},\\ \\frac{3}{2},\\ \\frac{5}{2},\\ \\frac{7}{2}\\right\\}$","$f(x)\\in\\left\\{\\frac{1}{2},\\ \\frac{3}{2},\\ \\frac{5}{2},\\ \\frac{7}{2},\\ \\frac{9}{2}\\right\\}$"],"설명":"한 단계 안쪽으로 갈 때마다 가능한 값이 하나씩 늘어난다. $f(x)$가 가질 수 있는 값은 $5$개이다.","확인":"5","스킬":"P1"},{"제목":"x의 값 구하기","힌트":"$f(x)=y$는 $x=1\\pm y$이다. $0\\le x\\le 10$인 값은 모두 몇 개인가?","식":["$x=1+y$: $\\frac{3}{2},\\ \\frac{5}{2},\\ \\frac{7}{2},\\ \\frac{9}{2},\\ \\frac{11}{2}$","$x=1-y$: $\\frac{1}{2}$ ($y\\le 1$일 때만 $x\\ge 0$)"],"설명":"$x=1-y$는 $y=\\frac{1}{2}$일 때만 $0$ 이상이고, $x=1+y$는 모두 $10$ 이하이다. 따라서 실근은 $\\frac{1}{2},\\frac{3}{2},\\cdots,\\frac{11}{2}$의 $6$개이다.","확인":"6","스킬":"G5"},{"제목":"모든 실근의 합","힌트":"$\\frac{1}{2},\\ \\frac{3}{2},\\ \\cdots,\\ \\frac{11}{2}$를 모두 더하면?","식":["$\\frac{1+3+5+7+9+11}{2}=18$"],"설명":"분자는 처음 여섯 개의 홀수의 합 $36$이다.","확인":"18","스킬":"P6"}]},"ns-3e3638b48435":{"길":"정의역의 원소를 구간에 맞는 식에 하나씩 넣어 함숫값을 모은다","단계":[{"제목":"원소마다 맞는 식으로 함숫값 구하기","힌트":"$x=2$는 어느 구간의 식에 넣어야 하는가?","식":["$f(-1)=|-2+1|=1,\\ \\ f(0)=|1|=1$","$f(1)=|3|=3,\\ \\ f(2)=2^{2}-1=3$"],"설명":"$x\\le 1$인 $-1,\\ 0,\\ 1$은 $|2x+1|$에, $x>1$인 $2$는 $x^{2}-1$에 넣는다.","확인":null,"스킬":"C2","고비":true},{"제목":"치역의 원소 모아 합 구하기","힌트":"같은 값은 한 번만 세어 더하면?","식":["치역 $=\\{1,\\ 3\\}$","$1+3=4$"],"설명":"치역은 함숫값의 집합이므로 중복되는 값은 한 번만 쓴다.","확인":"4","스킬":"C2"}]},"ns-4249b23a4e62":{"길":"f(-x)=-f(x)를 이용해 보기마다 값이 결정되는 곳을 찾는다","단계":[{"제목":"㉠ 참거짓 판별","힌트":"조건 (나)에 $x=0$을 넣으면?","식":["$f(0)=-f(0)$","$2f(0)=0$"],"설명":"$-0=0$이므로 $f(-0)=-f(0)$은 $f(0)=-f(0)$이 된다. 따라서 $f(0)=0$이고 ㉠은 참이다.","확인":null,"스킬":"T2"},{"제목":"㉡ 참거짓 판별","힌트":"$f(-2)$를 $f(2)$로 바꿔 쓰면?","식":["$f(-2)=-f(2)=f(1)$","$f(2)=-f(1)=f(-1)$"],"설명":"$f(-2)=-f(2)$이고 이것이 $f(1)$과 같으면 $f(2)=-f(1)$이다. 또 $f(-1)=-f(1)$이므로 $f(2)=f(-1)$이다. 따라서 ㉡은 참이다.","확인":null,"스킬":"T2"},{"제목":"㉢에서 자유롭게 정할 값 찾기","힌트":"$f(0),\\ f(1),\\ f(2),\\ f(-1),\\ f(-2)$ 중 처음에 마음대로 정할 수 있는 값은 어느 것인가? 그 값은 몇 가지인가?","식":["$f(0)=0$, $f(-1)=-f(1)$, $f(-2)=-f(2)$","$f(1),\\ f(2)$는 각각 $\\mathrm{A}$의 원소 $5$가지"],"설명":"$f(1),\\ f(2)$를 정하면 나머지 세 값이 정해진다. $-f(1),\\ -f(2)$도 $\\mathrm{A}$의 원소이므로 어떤 값을 골라도 (가)가 성립한다.","확인":"5","스킬":"P4","고비":true},{"제목":"함수의 개수와 선지 고르기","힌트":"$f(1),\\ f(2)$를 정하는 경우의 수를 곱하면? ㉠, ㉡, ㉢의 참거짓을 모으면?","식":["$5\\times 5=25$ → ㉢ 참","㉠, ㉡, ㉢ 모두 참 → ⑤"],"설명":"$f(1)$과 $f(2)$는 서로 영향을 주지 않으므로 곱의 법칙을 쓴다.","확인":null,"스킬":"C3"}]},"ns-42f18788ec04":{"길":"그림에서 대응을 읽고 보기마다 값을 직접 넣어 참거짓을 가린다","단계":[{"제목":"ㄱ의 참거짓 판별","힌트":"그림에서 $f$의 대응을 읽으면 서로 다른 원소가 같은 값으로 가는 경우가 있는가?","식":["$f(1)=2,\\ f(2)=1,\\ f(3)=3,\\ f(4)=4$"],"설명":"네 함숫값이 모두 다르다. 따라서 $f(x_{1})=f(x_{2})$이면 $x_{1}=x_{2}$이고 ㄱ은 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄴ의 참거짓 판별","힌트":"$h(1)$과 $h(3)$을 각각 구하면?","식":["$h(1)=g(f(1))=g(2)=2$","$h(3)=g(f(3))=g(3)=3$"],"설명":"$h(1)\\ne h(3)$이므로 모든 $x_{1},\\ x_{2}$에서 $h(x_{1})=h(x_{2})$는 성립하지 않는다. ㄴ은 거짓이다.","확인":null,"스킬":"T6"},{"제목":"g의 값이 같은 원소 묶기","힌트":"그림에서 $g$의 값이 $2$인 원소와 $3$인 원소를 각각 찾으면?","식":["$g(y)=2$인 $y$: $1,\\ 2$","$g(y)=3$인 $y$: $3,\\ 4$"],"설명":"$g$는 $1,\\ 2$를 $2$로, $3,\\ 4$를 $3$으로 보낸다. $g\\circ\\sigma$가 상수함수이려면 $\\sigma$의 값이 모두 같은 묶음에 있어야 한다.","확인":null,"스킬":"P4","고비":true},{"제목":"ㄷ의 σ 개수 세기","힌트":"상수값이 $2$일 때 $\\sigma(1),\\ \\sigma(2),\\ \\sigma(3),\\ \\sigma(4)$는 각각 몇 가지씩 고를 수 있는가?","식":["상수 $2$: $\\sigma(x)\\in\\{1,\\ 2\\}$ → $2^{4}=16$","상수 $3$: $\\sigma(x)\\in\\{3,\\ 4\\}$ → $2^{4}=16$","$16+16=32$ → ㄷ 참"],"설명":"$X$의 원소 $4$개 각각에 대해 같은 묶음의 두 값 중 하나를 고른다. 상수값이 $2$인 경우와 $3$인 경우는 겹치지 않으므로 더한다.","확인":"16","스킬":"P3"},{"제목":"참인 보기 모아 선지 고르기","힌트":"ㄱ, ㄴ, ㄷ의 참거짓을 모으면 어떤 선지인가?","식":["ㄱ 참, ㄴ 거짓, ㄷ 참 → ③"],"설명":"옳은 것은 ㄱ과 ㄷ이다.","확인":null,"스킬":"C3"}]},"ns-46787afca3e4":{"길":"(f∘f)(x)를 한 문자로 두어 안쪽과 바깥쪽 방정식으로 나누어 푼다","단계":[{"제목":"치환으로 식 단순하게 만들기","힌트":"$u=(f\\circ f)(x)$로 두면 $(f\\circ f\\circ f)(x)$는 $u$로 어떻게 쓰는가?","식":["$(f\\circ f\\circ f)(x)=f(u)$","$u=f(u)=|u-2|$"],"설명":"$(f\\circ f\\circ f)(x)=f\\left((f\\circ f)(x)\\right)=f(u)$이므로 주어진 식은 $u=f(u)$이다.","확인":null,"스킬":"A1"},{"제목":"u의 값 구하기","힌트":"$|u-2|$의 절댓값을 벗기려면 $u$를 어디서 나누는가?","식":["$u\\ge 2$: $u-2=u$ → 해 없음","$u<2$: $2-u=u$ → $u=1$"],"설명":"$u\\ge 2$에서는 $-2=0$이 되어 불가능하다. $u<2$에서 $u=1$이고 이는 구간 안에 있다.","확인":"1","스킬":"C2","고비":true},{"제목":"|x-2|의 값 구하기","힌트":"$u=(f\\circ f)(x)=\\left||x-2|-2\\right|=1$에서 $|x-2|$는?","식":["$|x-2|-2=\\pm 1$","$|x-2|=3$ 또는 $1$"],"설명":"$f(x)=|x-2|$이므로 $(f\\circ f)(x)=\\left|f(x)-2\\right|$이다. $|x-2|$는 $0$ 이상이므로 두 값 모두 가능하다.","확인":null,"스킬":"G5"},{"제목":"x의 값 모두 구하기","힌트":"$|x-2|=3$과 $|x-2|=1$의 해는 모두 몇 개인가?","식":["$|x-2|=3$: $x=5,\\ -1$","$|x-2|=1$: $x=3,\\ 1$"],"설명":"네 값은 서로 다르므로 $x$의 개수는 $4$이다.","확인":"4","스킬":"G5"},{"제목":"α+β의 값","힌트":"네 값의 합 $\\alpha$와 개수 $\\beta$를 더하면?","식":["$\\alpha=5-1+3+1=8,\\ \\ \\beta=4$","$\\alpha+\\beta=12$"],"설명":"$\\alpha=8$, $\\beta=4$이므로 합은 $12$이다.","확인":"12","스킬":"C1"}]},"ns-481b32af3c0a":{"길":"a가 양수이면 증가함수라 양 끝점이 서로 대응해야 한다","단계":[{"제목":"일대일 대응 조건 읽기","힌트":"$a>0$이면 $f$는 증가인가 감소인가? 정의역의 양 끝은 공역의 어느 끝으로 가야 하는가?","식":["$f(1)=-1,\\ f(3)=5$"],"설명":"일대일 대응이려면 치역이 공역 $[-1,\\ 5]$ 전체여야 한다. $a>0$이면 증가함수이므로 가장 작은 $x=1$이 가장 작은 값에, $x=3$이 가장 큰 값에 대응한다.","확인":null,"스킬":"T3","고비":true},{"제목":"a와 b의 값 구하기","힌트":"$a+b=-1,\\ 3a+b=5$를 연립하면?","식":["$a+b=-1,\\ \\ 3a+b=5$","$a=3,\\ b=-4$"],"설명":"두 식을 빼면 $2a=6$이므로 $a=3$이고, $b=-1-3=-4$이다.","확인":"3","스킬":"A10"},{"제목":"ab의 값","힌트":"$a,\\ b$의 곱은?","식":["$ab=3\\times(-4)=-12$"],"설명":"$a=3,\\ b=-4$를 곱한다.","확인":"-12","스킬":"A10"}]},"ns-4cf48b25573f":{"길":"x²이 정수임을 이용해 x를 √n으로 두고 n마다 p의 범위를 확인한다","단계":[{"제목":"x가 될 수 있는 값의 꼴 정하기","힌트":"$x^{2}=[px]$에서 우변은 어떤 수인가? $x<0$이면 $[px]$의 부호는?","식":["$x^{2}=[px]$는 정수이므로 $x^{2}=n\\ (n\\ge 0$인 정수$)$","$x<0$이면 $[px]<0\\le x^{2}$ → 불가능","$x=\\sqrt{n}$"],"설명":"$p>0$이므로 $x<0$이면 $px<0$이고 $[px]<0$이다. 그러나 $x^{2}\\ge 0$이므로 두 함수가 같을 수 없다.","확인":null,"스킬":"N7"},{"제목":"n이 가능할 조건 세우기","힌트":"$x=\\sqrt{n}$일 때 $[p\\sqrt{n}]=n$을 부등식으로 쓰면?","식":["$n\\le p\\sqrt{n}<n+1$","$\\sqrt{n}\\le p<\\frac{n+1}{\\sqrt{n}}\\ (n\\ge 1)$"],"설명":"가우스 기호 $[A]=n$은 $n\\le A<n+1$과 같다. $n\\ge 1$이면 $\\sqrt{n}$으로 나누어 $p$의 범위로 바꾼다.","확인":null,"스킬":"N7"},{"제목":"가능한 n 골라내기","힌트":"$p<\\sqrt{3}$이므로 $\\sqrt{n}\\le p$를 만족할 수 있는 $n$은? 남은 $n$에서 위쪽 조건은 항상 성립하는가?","식":["$\\sqrt{n}\\le p<\\sqrt{3}$ → $n\\le 2$","$n=1$: $1\\le p<2$, $n=2$: $\\sqrt{2}\\le p<\\frac{3}{\\sqrt{2}}$는 모든 $p$에서 성립","$n=0$: $x=0$은 항상 성립"],"설명":"$n\\ge 3$이면 $\\sqrt{n}\\ge\\sqrt{3}>p$라 $\\sqrt{n}\\le p$가 깨진다. $n=1,\\ 2$는 $\\sqrt{2}\\le p<\\sqrt{3}$이면 위쪽 부등식도 성립한다.","확인":null,"스킬":"C2","고비":true},{"제목":"n(X)의 최댓값 구하기","힌트":"가능한 $x$를 모두 모으면 원소는 몇 개인가?","식":["$X\\subset\\{0,\\ 1,\\ \\sqrt{2}\\}$","$n(X)$의 최댓값은 $3$"],"설명":"$X$가 세 값을 모두 포함할 때 원소의 개수가 가장 많다.","확인":"3","스킬":"N7"}]},"ns-4cfeb429bdf4":{"길":"f(x)가 f의 꺾이는 점을 지나는 x에서 구간을 끊어 f(f(x))를 쓴다","단계":[{"제목":"구간 나누는 경계 찾기","힌트":"$f(f(x))$의 식은 $f(x)$의 값이 $1$ 또는 $2$가 되는 $x$와 $x=1,\\ 2$에서 바뀐다. 경계를 모두 모으면 구간은 몇 개인가?","식":["$f(x)=1$: $x=1,\\ \\frac{8}{3}$","$f(x)=2$: $x=\\frac{1}{2},\\ \\frac{3}{2},\\ \\frac{7}{3}$"],"설명":"$f$는 $x=1,\\ 2$에서 꺾이므로 경계는 $\\frac{1}{2},\\ 1,\\ \\frac{3}{2},\\ 2,\\ \\frac{7}{3},\\ \\frac{8}{3}$이고 구간은 $7$개이다.","확인":"7","스킬":"T6"},{"제목":"구간별 f(f(x)) 구하기","힌트":"각 구간에서 $f(x)$가 $f$의 어느 식에 들어가는지 보고 합성하면?","식":["$0\\le x<\\frac{1}{2}$: $6x$,  $\\frac{1}{2}\\le x<1$: $-4x+5$,  $1\\le x<\\frac{3}{2}$: $4x-3$","$\\frac{3}{2}\\le x<2$: $-6x+12$,  $2\\le x<\\frac{7}{3}$: $9x-18$","$\\frac{7}{3}\\le x<\\frac{8}{3}$: $-6x+17$,  $\\frac{8}{3}\\le x\\le 3$: $6x-15$"],"설명":"예를 들어 $0\\le x<\\frac{1}{2}$이면 $f(x)=-2x+3\\in(2,\\ 3]$이므로 $f(f(x))=-3(-2x+3)+9=6x$이다. 다른 구간도 같은 방법으로 합성한다.","확인":null,"스킬":"T6","고비":true},{"제목":"구간마다 |2x-3|과 같게 놓기","힌트":"$x<\\frac{3}{2}$에서는 $|2x-3|=3-2x$, $x\\ge\\frac{3}{2}$에서는 $2x-3$이다. 각 구간에서 풀고 구간 안의 값만 남기면?","식":["$x<\\frac{3}{2}$: $6x=3-2x$ → $x=\\frac{3}{8}$, $-4x+5=3-2x$ → $x=1$(구간 밖), $4x-3=3-2x$ → $x=1$","$x\\ge\\frac{3}{2}$: $-6x+12=2x-3$ → $x=\\frac{15}{8}$, $9x-18=2x-3$ → $x=\\frac{15}{7}$","$-6x+17=2x-3$ → $x=\\frac{5}{2}$, $6x-15=2x-3$ → $x=3$"],"설명":"$-4x+5=3-2x$의 해 $x=1$은 구간 $\\frac{1}{2}\\le x<1$ 밖이지만, 같은 값이 다음 구간 $1\\le x<\\frac{3}{2}$에서는 해가 된다. 일곱 구간의 해가 모두 해당 구간 안에 있는지 확인한다.","확인":null,"스킬":"G1"},{"제목":"서로 다른 실근의 개수 세기","힌트":"구한 해를 중복 없이 세면?","식":["$\\frac{3}{8},\\ 1,\\ \\frac{15}{8},\\ \\frac{15}{7},\\ \\frac{5}{2},\\ 3$ → $6$개"],"설명":"여섯 값은 모두 서로 다르다.","확인":"6","스킬":"G1"}]},"ns-4d0a02bf59a1":{"길":"조건 (가)에서 f(x+1)과 f(x)의 관계를 끌어내 f(4)부터 구한다","단계":[{"제목":"조건 (가) 풀어 쓰기","힌트":"$f\\circ f=I$이면 $f$의 역함수는 무엇인가? $(g\\circ f)^{2}=I$를 풀어 쓰면?","식":["$f^{-1}=f$","$g\\circ f\\circ g\\circ f=I\\ \\Rightarrow\\ g\\circ f\\circ g=f$"],"설명":"$f^{2}=I$이므로 $f$는 자기 자신이 역함수이다. $g\\circ f\\circ g\\circ f=I$의 오른쪽에 $f$를 합성하면 $g\\circ f\\circ g\\circ f\\circ f=f$이고, $f\\circ f=I$이므로 $g\\circ f\\circ g=f$이다.","확인":null,"스킬":"C6"},{"제목":"f(x+1)과 f(x)의 관계 찾기","힌트":"$g\\circ f\\circ g=f$의 양변 왼쪽에 $g^{-1}$을 합성하면 $f(g(x))$는?","식":["$f(g(x))=g^{-1}(f(x))$","$f(x+1)=f(x)-1$ (값이 $1$이면 $10$으로 돌아감)"],"설명":"$g(x)=x+1$이고 $g^{-1}(y)=y-1$이다. $10$ 다음은 $1$로 돌아가므로 $f$의 값도 $1$ 줄이면 $10$이 되는 순환으로 센다.","확인":null,"스킬":"T6","고비":true},{"제목":"f(1)부터 f(4)까지 이어 쓰기","힌트":"$f(1)=3$에서 $x$가 $1$씩 늘 때마다 값을 $1$씩 줄이면 $f(4)$는?","식":["$f(1)=3,\\ f(2)=2,\\ f(3)=1$","$f(4)=10$"],"설명":"$f(3)=1$에서 $1$을 더 줄이면 순환하여 $10$이 된다.","확인":"10","스킬":"T6"},{"제목":"f(10)의 값 구하기","힌트":"$f(4)=10$이고 $f\\circ f=I$이면 $f(10)$은?","식":["$f(10)=f(f(4))=4$"],"설명":"$f^{2}=I$이므로 $f(f(4))=4$이다. 따라서 $f(10)=4$이다.","확인":"4","스킬":"T6"}]},"ns-53220e905862":{"길":"g의 값이 끝없이 커지는 점을 이용해 g의 최솟값 조건으로 바꾼다","단계":[{"제목":"f가 0 이상이 되는 범위","힌트":"$f(t)$를 인수분해하면?","식":["$f(t)=(t-4)(t+3)\\ge 0$","$t\\le -3$ 또는 $t\\ge 4$"],"설명":"$(f\\circ g)(x)\\ge 0$이 되려면 $g(x)$의 값이 이 범위 안에 있어야 한다.","확인":null,"스킬":"T6"},{"제목":"g의 값이 놓일 구간 고르기","힌트":"$g(x)$는 $x$가 커지면 값이 어떻게 되는가?","식":["$g(x)\\ge 4$"],"설명":"$g(x)$는 아래로 볼록한 포물선이라 값이 끝없이 커지고 이어져 있다. 따라서 $g(x)\\le -3$ 쪽에 머물 수 없고 모든 $x$에서 $g(x)\\ge 4$이어야 한다.","확인":null,"스킬":"T3","고비":true},{"제목":"항상 성립하는 이차부등식 만들기","힌트":"$x^{2}-ax+5\\ge 4$를 정리하고 판별식 조건을 쓰면?","식":["$x^{2}-ax+1\\ge 0$","$D=a^{2}-4\\le 0$"],"설명":"모든 실수 $x$에서 아래로 볼록한 이차식이 $0$ 이상이려면 판별식이 $0$ 이하여야 한다.","확인":null,"스킬":"C1"},{"제목":"a의 범위와 β/α 구하기","힌트":"$a^{2}\\le 4$의 해에서 $\\alpha,\\ \\beta$는 각각 왼쪽 끝, 오른쪽 끝이다. $\\frac{\\beta}{\\alpha}$는?","식":["$-2\\le a\\le 2$ → $\\alpha=-2,\\ \\beta=2$","$\\frac{\\beta}{\\alpha}=\\frac{2}{-2}=-1$"],"설명":"범위의 왼쪽 끝이 $\\alpha$, 오른쪽 끝이 $\\beta$이다.","확인":"-1","스킬":"G6"}]},"ns-5c8a80b2fd58":{"길":"f와 g를 6으로 나눈 나머지의 이동으로 보고 한 번의 효과를 먼저 구한다","단계":[{"제목":"f와 g를 이동으로 나타내기","힌트":"꼭짓점 번호는 시계 반대 방향으로 늘어난다. $f$는 몇 칸, $g$(반대편)는 몇 칸 이동인가?","식":["$f(n)\\equiv n+1\\pmod 6$","$g(n)\\equiv n+3\\pmod 6$"],"설명":"$f$는 시계 반대 방향으로 한 칸 이동이고 $6$ 다음은 $1$이다. $g$는 $O$에 대칭인 꼭짓점이므로 반 바퀴, 즉 $3$칸 이동이다.","확인":null,"스킬":"N3"},{"제목":"f²∘g 한 번의 효과 구하기","힌트":"$g$로 $3$칸, 이어서 $f$를 두 번 적용하면 모두 몇 칸 이동인가? 한 번 적용하면 $6$은 어디로 가는가?","식":["$(f^{2}\\circ g)(n)\\equiv n+3+2=n+5\\equiv n-1\\pmod 6$","$(f^{2}\\circ g)(6)=5$"],"설명":"$f^{2}$는 $2$칸 이동이다. $5$칸 앞으로 가는 것은 $6$으로 나눈 나머지로는 한 칸 뒤로 가는 것과 같다.","확인":"5","스킬":"C6","고비":true},{"제목":"2014번 반복의 효과 구하기","힌트":"한 칸 뒤로 가는 이동을 $2014$번 하면 몇 칸 뒤인가? $2014$를 $6$으로 나눈 나머지는?","식":["$2014=6\\times 335+4$","$(f^{2}\\circ g)^{2014}(n)\\equiv n-4\\pmod 6$"],"설명":"$6$칸 이동은 제자리로 돌아오므로 $2014$칸 뒤는 나머지 $4$칸 뒤와 같다.","확인":"4","스킬":"N3"},{"제목":"6에서 네 칸 뒤 구하기","힌트":"$6$에서 $4$칸 뒤로 가면?","식":["$6-4=2$"],"설명":"$(f^{2}\\circ g)^{2014}(6)\\equiv 6-4=2$이다.","확인":"2","스킬":"N3"}]},"ns-5fb030d1847c":{"길":"함숫값 후보를 구하고 치역 두 값을 고른 뒤 둘 다 쓰이는 함수만 센다","단계":[{"제목":"함숫값 후보 구하기","힌트":"$t^{3}-t=0$을 인수분해하면?","식":["$t(t-1)(t+1)=0$","$f(x)\\in\\{-1,\\ 0,\\ 1\\}$"],"설명":"조건 (가)는 모든 $x$에서 $f(x)$가 $t^{3}-t=0$의 해라는 뜻이다.","확인":null,"스킬":"P4"},{"제목":"치역의 두 원소 고르기","힌트":"$n(Y)=2$이므로 후보 세 개에서 서로 다른 두 개를 고르는 방법은?","식":["$\\{-1,\\ 0\\},\\ \\{-1,\\ 1\\},\\ \\{0,\\ 1\\}$"],"설명":"치역이 후보 중 어느 두 원소의 집합인지에 따라 경우를 나눈다.","확인":"3","스킬":"P4"},{"제목":"두 값을 모두 쓰는 함수 세기","힌트":"정의역 $5$개의 원소에 두 값을 배정하는 방법 중 한 값만 쓰는 경우는 몇 개인가?","식":["$2^{5}=32$","$32-2=30$"],"설명":"각 원소에 두 값 중 하나를 배정하면 $2^{5}$가지이다. 치역이 두 원소가 되려면 두 값이 모두 쓰여야 하므로 한 값만 쓰는 $2$가지를 뺀다.","확인":"30","스킬":"P2","고비":true},{"제목":"함수의 개수 구하기","힌트":"치역을 고르는 경우의 수와 함수의 개수를 곱하면?","식":["$3\\times 30=90$"],"설명":"치역이 정해지면 그 치역을 갖는 함수가 $30$개씩 있으므로 곱의 법칙을 쓴다.","확인":"90","스킬":"P4"}]},"ns-640ed8a93e9c":{"길":"g의 증가 조건과 이어 붙이는 조건, 산술·기하 평균으로 a, b를 정한다","단계":[{"제목":"x<2에서 g가 가질 조건","힌트":"일대일 대응이 되려면 $x<2$에서 $g$는 증가해야 하는가 감소해야 하는가? 그러려면 꼭짓점의 위치는?","식":["$a\\ge 2$","$x<2$에서 $g$의 치역: $y<4-(a-2)^{2}$"],"설명":"위로 볼록한 포물선이 $x<2$에서 증가하려면 꼭짓점의 $x$좌표 $a$가 $2$ 이상이어야 한다. 그러면 $x<2$에서 값은 $g(2)=4-(a-2)^{2}$ 아래로 모두 나온다.","확인":null,"스킬":"G7"},{"제목":"두 부분을 이어 붙이는 조건","힌트":"$f$의 기울기를 $c$라 하면 $f(2)$는? $x\\ge 2$의 치역과 $x<2$의 치역이 겹치지 않고 이어지려면?","식":["$f(2)=2c=4-(a-2)^{2}$","$2c\\le 4$, 즉 $c\\le 2$"],"설명":"$a,\\ b>0$이므로 $c>0$이고 $x\\ge 2$에서 $f$의 치역은 $[2c,\\ \\infty)$이다. 두 치역이 빈틈없이 이어지려면 $2c=g(2)$이고, $g(2)\\le 4$이다.","확인":null,"스킬":"T3"},{"제목":"산술·기하 평균으로 c의 하한 구하기","힌트":"$a+b+1=\\frac{1}{2}\\{(2a+1)+(2b+1)\\}$로 쓰고 두 괄호에 각각 산술·기하 평균을 쓰면?","식":["$c=\\frac{1}{2}\\{(2a+1)+(2b+1)\\}\\left(\\frac{1}{2a+1}+\\frac{1}{2b+1}\\right)$","$c\\ge\\frac{1}{2}\\cdot 2\\sqrt{(2a+1)(2b+1)}\\cdot\\frac{2}{\\sqrt{(2a+1)(2b+1)}}=2$"],"설명":"$2a+1,\\ 2b+1$은 양수이므로 합과 역수의 합에 각각 산술·기하 평균을 쓸 수 있다. 앞 단계의 $c\\le 2$와 합치면 $c=2$이다.","확인":null,"스킬":"A7","고비":true},{"제목":"a와 b의 값 정하기","힌트":"$c=2$이면 $4-(a-2)^{2}$는? 산술·기하 평균에서 등호는 언제 성립하는가?","식":["$4-(a-2)^{2}=2c=4$ → $a=2$","$2a+1=2b+1$ → $b=2$"],"설명":"$c=2$이므로 $(a-2)^{2}=0$이다. 또 $c=2$는 산술·기하 평균의 등호 조건 $2a+1=2b+1$일 때만 가능하므로 $b=a$이다.","확인":null,"스킬":"A7"},{"제목":"ab의 값","힌트":"$a=b=2$일 때 $ab$는?","식":["$ab=2\\times 2=4$"],"설명":"구한 두 값을 곱한다.","확인":"4","스킬":"A7"}]},"ns-68e5a5f5acec":{"길":"바깥에서 안쪽으로 f(t)=s의 해 1±s를 따라가며 음수는 버린다","단계":[{"제목":"한 단계 거꾸로 푸는 규칙","힌트":"$f(t)=s$에서 $t$는 $s$로 어떻게 쓰는가? 안쪽 값이 음수이면 어떻게 되는가?","식":["$f(t)=s\\ \\Leftrightarrow\\ t=1\\pm s$","$t=f^{k}(x)\\ge 0$이므로 음수인 값은 제외"],"설명":"$f^{10}(x)=f\\left(f^{9}(x)\\right)=\\frac{1}{2}$이므로 $f^{9}(x)$는 $f(t)=\\frac{1}{2}$의 해 중 $0$ 이상인 값이어야 한다. 이 과정을 안쪽으로 되풀이한다.","확인":null,"스킬":"G5","고비":true},{"제목":"f⁹, f⁸이 가질 수 있는 값","힌트":"$f^{10}(x)=\\frac{1}{2}$이면 $f^{9}(x)$, 그 안쪽 $f^{8}(x)$의 값은?","식":["$f^{9}(x)\\in\\left\\{\\frac{1}{2},\\ \\frac{3}{2}\\right\\}$","$f^{8}(x)\\in\\left\\{\\frac{1}{2},\\ \\frac{3}{2},\\ \\frac{5}{2}\\right\\}$","$f^{k}(x)$가 가질 수 있는 값은 $11-k$개"],"설명":"$f(t)=\\frac{3}{2}$이면 $t=\\frac{5}{2}$ 또는 $-\\frac{1}{2}$인데 음수는 버린다. 한 단계 안쪽으로 갈 때마다 가능한 값이 하나씩 늘어난다.","확인":null,"스킬":"G5"},{"제목":"f(x)가 가질 수 있는 값의 개수","힌트":"$k=1$일 때 $f^{1}(x)=f(x)$가 가질 수 있는 값은 몇 개인가?","식":["$f(x)\\in\\left\\{\\frac{1}{2},\\ \\frac{3}{2},\\ \\cdots,\\ \\frac{19}{2}\\right\\}$"],"설명":"$11-1=10$개이고, 가장 큰 값은 $\\frac{19}{2}$이다.","확인":"10","스킬":"P1"},{"제목":"x의 값 모두 나타내기","힌트":"$f(x)=c$이면 $x$는 $c$로 어떻게 쓰는가? 해는 모두 몇 개인가?","식":["$x=1+c$ 또는 $x=1-c$","$c$가 $10$개이므로 해는 $20$개"],"설명":"$c>0$이므로 $1+c$와 $1-c$는 서로 다른 값이고, $x$의 범위에 제한이 없으므로 음수인 해도 모두 포함한다.","확인":null,"스킬":"G5"},{"제목":"해의 합 구하기","힌트":"$1+c$와 $1-c$를 짝지어 더하면?","식":["$(1+c)+(1-c)=2$","$2\\times 10=20$"],"설명":"$c$ 하나마다 해 두 개의 합이 $2$이고, $c$가 $10$개이다.","확인":"20","스킬":"G5"}]},"ns-68fa8d9deb83":{"길":"일대일대응을 거듭 합성하면 제자리로 오는 주기를 조건 (나)로 정한다","단계":[{"제목":"주기가 1, 2인 경우 배제하기","힌트":"$f^{2}=I$이면 $f^{2014}(3)$은 얼마인가? 그러면 (나)에서 $f^{2013}(1)$은?","식":["$f^{2}=I$이면 $f^{2014}(3)=3$","$3+f^{2013}(1)=3$ → $f^{2013}(1)=0$ (불가능)"],"설명":"$f^{2013}(1)$은 $\\mathrm{X}$의 원소이므로 $1$ 이상이다. 항등함수나 두 원소만 바꾸는 함수는 $f^{2}=I$라 조건 (나)를 만족하지 못한다.","확인":null,"스킬":"P7"},{"제목":"주기 3으로 거듭제곱 줄이기","힌트":"남은 경우는 세 원소를 돌리는 함수이다. $f^{3}=I$이면 $2014$를 $3$으로 나눈 나머지는?","식":["$f^{3}=I$","$2014=3\\times 671+1,\\ \\ 2013=3\\times 671$","$f^{2014}=f,\\ \\ f^{2013}=I$"],"설명":"$f^{3}=I$이므로 지수에서 $3$의 배수를 뺄 수 있다. $f^{2013}=I$이므로 $f^{2013}(1)=1$이다.","확인":"1","스킬":"P7","고비":true},{"제목":"f(1), f(2), f(3) 정하기","힌트":"(나)는 $f(3)+1=3$으로 바뀐다. $f(3)$을 구하고 $f^{3}=I$가 되도록 나머지를 채우면?","식":["$f(3)+1=3$ → $f(3)=2$","$f(2)=1,\\ f(1)=3$"],"설명":"$f(3)=2$이고 $f(2)=3$이면 $f^{2}(3)=3$이 되어 주기가 $2$가 되므로 안 된다. 따라서 $f(2)=1$이고, 일대일대응이므로 $f(1)=3$이다.","확인":"2","스킬":"T6"},{"제목":"구하는 값 계산하기","힌트":"$2015$를 $3$으로 나눈 나머지로 $f^{2015}(3)$을, $f^{2014}=f$로 $f^{2014}(1)$을 구하면?","식":["$f^{2015}(3)=f^{2}(3)=f(2)=1$","$f^{2014}(1)=f(1)=3$","$1-3=-2$"],"설명":"$2015=3\\times 671+2$이므로 $f^{2015}=f^{2}$이다.","확인":"-2","스킬":"P7"}]},"ns-69011c31dda8":{"길":"역함수 조건으로 a, b의 관계를 세우고 (a-3)²+b²를 거리의 제곱으로 본다","단계":[{"제목":"역함수가 존재할 조건 읽기","힌트":"$x\\le 3$에서 $f$의 치역은? $x>3$ 쪽은 증가해야 하는가 감소해야 하는가, 어느 값에서 이어져야 하는가?","식":["$x\\le 3$: $f(x)=2x+1$의 치역은 $(-\\infty,\\ 7]$","$x>3$: $f$가 증가하고 $x=3$에서 값이 이어짐 → $9-3a+4b=7$","꼭짓점 $x=\\frac{a}{2}\\le 3$ → $a\\le 6$"],"설명":"역함수가 있으려면 일대일대응이어야 한다. $x\\le 3$에서 치역이 $(-\\infty,\\ 7]$이므로 $x>3$ 쪽은 증가하며 $7$보다 큰 값을 모두 채워야 한다.","확인":null,"스킬":"T3","고비":true},{"제목":"a의 범위 정하기","힌트":"$9-3a+4b=7$에서 $b$를 $a$로 나타내고 $b\\ge 0$을 쓰면?","식":["$3a-4b=2$ → $b=\\frac{3a-2}{4}$","$b\\ge 0$ → $a\\ge\\frac{2}{3}$","$\\frac{2}{3}\\le a\\le 6$"],"설명":"점 $(a,\\ b)$는 직선 $3a-4b=2$ 위의 선분 위를 움직인다.","확인":null,"스킬":"G7"},{"제목":"최댓값 M 구하기","힌트":"$(a-3)^{2}+b^{2}$은 점 $(a,\\ b)$에서 점 $(3,\\ 0)$까지 거리의 제곱이다. 선분의 양 끝에서 값은?","식":["$a=6$: $b=4$, $3^{2}+4^{2}=25$","$a=\\frac{2}{3}$: $b=0$, $\\left(\\frac{7}{3}\\right)^{2}=\\frac{49}{9}$"],"설명":"고정점에서 선분 위의 점까지 거리의 제곱은 양 끝점에서 가장 크다. 두 끝점의 값 중 큰 것이 $M$이다.","확인":"25","스킬":"G10"},{"제목":"최솟값 m 구하기","힌트":"점 $(3,\\ 0)$에서 직선 $3a-4b-2=0$까지 거리를 구하면?","식":["$\\frac{|3\\cdot 3-4\\cdot 0-2|}{\\sqrt{3^{2}+4^{2}}}=\\frac{7}{5}$","$m=\\left(\\frac{7}{5}\\right)^{2}=\\frac{49}{25}$"],"설명":"수선의 발이 $a=\\frac{54}{25}$로 $\\frac{2}{3}\\le a\\le 6$ 안에 있으므로 최솟값은 점과 직선 사이 거리의 제곱이다.","확인":"49/25","스킬":"G10"},{"제목":"Mm의 값 구하기","힌트":"$M$과 $m$을 곱하면?","식":["$Mm=25\\times\\frac{49}{25}=49$"],"설명":"$25$와 분모 $25$가 약분된다.","확인":"49","스킬":"G10"}]},"ns-6d7e35c3bebf":{"길":"f∘g와 f의 그래프에서 g를 하나씩 거꾸로 찾고 역함수 값을 읽는다","단계":[{"제목":"g를 구하는 방법 세우기","힌트":"$(f\\circ g)(x)$와 $f$의 대응표를 알면 $g(x)$는 $f$의 무엇으로 구하는가?","식":["$f$: $1\\to3,\\ 2\\to5,\\ 3\\to2,\\ 4\\to4,\\ 5\\to1$","$f\\circ g$: $1\\to5,\\ 2\\to2,\\ 3\\to3,\\ 4\\to1,\\ 5\\to4$"],"설명":"그림에서 두 함수의 점을 읽는다. $f(g(x))$의 값을 알고 $f$가 일대일대응이므로 $g(x)=f^{-1}\\left(f(g(x))\\right)$로 구한다.","확인":null,"스킬":"T6"},{"제목":"g의 값 표 만들기","힌트":"$f(g(3))=3$이면 $f(1)=3$이므로 $g(3)$은? 나머지도 같은 방법으로 구하면?","식":["$g(1)=2,\\ g(2)=3,\\ g(3)=1$","$g(4)=5,\\ g(5)=4$"],"설명":"$f(g(1))=5$에서 $f(2)=5$이므로 $g(1)=2$이다. 같은 방법으로 $f(g(2))=2$에서 $g(2)=3$, $f(g(4))=1$에서 $g(4)=5$, $f(g(5))=4$에서 $g(5)=4$이다.","확인":"1","스킬":"T6"},{"제목":"(g∘f)⁻¹(4) 구하기","힌트":"$(g\\circ f)^{-1}=f^{-1}\\circ g^{-1}$이다. $g^{-1}(4)$를 먼저 구하면?","식":["$g^{-1}(4)=5$","$(g\\circ f)^{-1}(4)=f^{-1}(5)=2$"],"설명":"$g(5)=4$이므로 $g^{-1}(4)=5$이고, $f(2)=5$이므로 $f^{-1}(5)=2$이다.","확인":"2","스킬":"T1","고비":true},{"제목":"구하는 값 더하기","힌트":"$g(3)$과 $(g\\circ f)^{-1}(4)$를 더하면?","식":["$g(3)+(g\\circ f)^{-1}(4)=1+2=3$"],"설명":"앞에서 구한 두 값을 더한다.","확인":"3","스킬":"T6"}]},"ns-7f0914e5b24b":{"길":"정수에 f를 거듭하면 0에 닿은 뒤 1과 0이 번갈아 나오는 규칙을 쓴다","단계":[{"제목":"f를 거듭했을 때의 규칙 찾기","힌트":"$m$에 $f$를 한 번 적용할 때마다 값은 어떻게 변하는가? $0$에 닿으면 그 뒤는?","식":["$n\\le m$이면 $f^{n}(m)=m-n$","$f^{m}(m)=0,\\ f^{m+1}(m)=1,\\ f^{m+2}(m)=0,\\ \\cdots$"],"설명":"$f(m)=m-1$이므로 $m$번 적용하면 $0$이 된다. 그 뒤로는 $f(0)=1,\\ f(1)=0$이라 $1$과 $0$이 번갈아 나온다. 따라서 $n\\ge m$일 때 $n-m$이 홀수이면 $1$, 짝수이면 $0$이다.","확인":null,"스킬":"P7","고비":true},{"제목":"네 항의 값 각각 구하기","힌트":"각 항에서 $n-m$이 홀수인지 짝수인지 살피면?","식":["$f^{2016}(2016)=0$ ($n=m$),  $f^{2015}(2013)=0$ ($n-m=2$)","$f^{2012}(2007)=1$ ($n-m=5$, 홀수)","$f^{2006}(2002)=0$ ($n-m=4$, 짝수)"],"설명":"네 항 모두 $n\\ge m$이므로 규칙을 쓸 수 있다.","확인":null,"스킬":"P7"},{"제목":"네 항의 합 구하기","힌트":"$0+0+1+0$을 계산하면?","식":["$0+0+1+0=1$"],"설명":"$1$이 되는 항은 $n-m$이 홀수인 하나뿐이다.","확인":"1","스킬":"P7"}]},"ns-8308481c77ca":{"길":"f(x)가 f의 꺾이는 점을 지나는 x에서 구간을 끊어 f(f(x))와 x/2를 비교한다","단계":[{"제목":"구간 나누는 경계 찾기","힌트":"$f(f(x))$의 식은 $f(x)$의 값이 $1$ 또는 $2$가 되는 $x$와 $x=1,\\ 2$에서 바뀐다. 경계를 모두 모으면 구간은 몇 개인가?","식":["$f(x)=1$: $x=1,\\ \\frac{8}{3}$","$f(x)=2$: $x=\\frac{1}{2},\\ \\frac{3}{2},\\ \\frac{7}{3}$"],"설명":"$f$는 $x=1,\\ 2$에서 꺾이므로 경계는 $\\frac{1}{2},\\ 1,\\ \\frac{3}{2},\\ 2,\\ \\frac{7}{3},\\ \\frac{8}{3}$이고 구간은 $7$개이다.","확인":"7","스킬":"T6"},{"제목":"구간별 f(f(x)) 구하기","힌트":"각 구간에서 $f(x)$가 $f$의 어느 식에 들어가는지 보고 합성하면?","식":["$0\\le x<\\frac{1}{2}$: $6x$,  $\\frac{1}{2}\\le x<1$: $-4x+5$,  $1\\le x<\\frac{3}{2}$: $4x-3$","$\\frac{3}{2}\\le x<2$: $-6x+12$,  $2\\le x<\\frac{7}{3}$: $9x-18$","$\\frac{7}{3}\\le x<\\frac{8}{3}$: $-6x+17$,  $\\frac{8}{3}\\le x\\le 3$: $6x-15$"],"설명":"예를 들어 $0\\le x<\\frac{1}{2}$이면 $f(x)=-2x+3\\in(2,\\ 3]$이므로 $f(f(x))=-3(-2x+3)+9=6x$이다. 다른 구간도 같은 방법으로 합성한다.","확인":null,"스킬":"T6","고비":true},{"제목":"구간마다 x/2와 같게 놓기","힌트":"일곱 구간에서 각각 방정식을 풀고 구간 안에 있는 해만 남기면?","식":["$0\\le x<\\frac{1}{2}$: $6x=\\frac{x}{2}$ → $x=0$,  $\\frac{1}{2}\\le x<1$: $-4x+5=\\frac{x}{2}$ → $x=\\frac{10}{9}$ (구간 밖)","$1\\le x<\\frac{3}{2}$: $4x-3=\\frac{x}{2}$ → $x=\\frac{6}{7}$ (구간 밖),  $\\frac{3}{2}\\le x<2$: $-6x+12=\\frac{x}{2}$ → $x=\\frac{24}{13}$","$2\\le x<\\frac{7}{3}$: $x=\\frac{36}{17}$,  $\\frac{7}{3}\\le x<\\frac{8}{3}$: $x=\\frac{34}{13}$,  $\\frac{8}{3}\\le x\\le 3$: $x=\\frac{30}{11}$"],"설명":"구한 값이 해당 구간 안에 있어야 실근이다. 두 구간에서는 구한 값이 구간 밖이라 버린다.","확인":null,"스킬":"G1"},{"제목":"서로 다른 실근의 개수 세기","힌트":"남은 해를 중복 없이 세면?","식":["$0,\\ \\frac{24}{13},\\ \\frac{36}{17},\\ \\frac{34}{13},\\ \\frac{30}{11}$ → $5$개"],"설명":"다섯 값은 서로 다른 구간에서 나왔으므로 모두 다르다.","확인":"5","스킬":"G1"}]},"ns-8652b43dfd8a":{"길":"제1사분면 부분을 네 방향으로 옮겨 곡선을 그리고 직선·포물선과 만나는 점을 센다","단계":[{"제목":"그래프에서 f의 식 읽기","힌트":"그래프는 꼭짓점이 $(2,\\ -1)$인 꺾은선이고 $(0,\\ 1),\\ (1,\\ 0),\\ (3,\\ 0)$을 지난다. 식은?","식":["$f(x)=|x-2|-1$"],"설명":"꼭짓점 $(2,\\ -1)$에서 양쪽 기울기가 $\\pm 1$이다.","확인":null,"스킬":"G4"},{"제목":"|y|=f(|x|)의 그래프 파악하기","힌트":"$|y|\\ge 0$이므로 $f(|x|)$가 $0$ 이상인 곳만 그려진다. 그 $x$의 범위와 모양은?","식":["$|x|\\le 1$: $|x|+|y|=1$ (마름모)","$|x|\\ge 3$: $|y|=|x|-3$"],"설명":"$x\\ge 0$에서 $f(x)\\ge 0$인 부분은 $0\\le x\\le 1$의 $y=1-x$와 $x\\ge 3$의 $y=x-3$이다. $|x|$와 $|y|$를 쓰면 이 부분을 $x$축, $y$축, 원점에 대칭이동한 곡선이 된다.","확인":null,"스킬":"G5","고비":true},{"제목":"직선 y=-1과의 교점 세기","힌트":"$(x^{2}-y-10)(y+1)=0$은 $y=x^{2}-10$ 또는 $y=-1$이다. $y=-1$일 때 마름모와 바깥 곡선에서 각각 몇 개 만나는가?","식":["마름모: $|y|=1$ → $|x|=0$, 점 $(0,\\ -1)$","바깥 곡선: $|x|-3=1$ → $x=\\pm 4$, 점 $(4,\\ -1),\\ (-4,\\ -1)$"],"설명":"마름모의 아래쪽 꼭짓점에서 $1$개, 바깥 곡선에서 $2$개 만나므로 모두 $3$개이다.","확인":"3","스킬":"G1"},{"제목":"포물선 y=x²-10과의 교점 세기","힌트":"마름모는 $|x|\\le 1$이라 $|y|\\le 1$이다. 포물선이 거기에 닿는가? 바깥 곡선의 $x\\ge 3$ 부분과는?","식":["마름모와는 만나지 않음 ($y=x^{2}-10$이 $|y|\\le 1$이려면 $|x|\\ge 3$)","$x\\ge 3$: $y=x-3$일 때 $x^{2}-x-7=0$, $y=3-x$일 때 $x^{2}+x-13=0$ → 각각 $3$ 이상인 해 $1$개","$y$축 대칭으로 $x\\le -3$에서도 각 $1$개"],"설명":"$x^{2}-x-7=0$의 해 $\\frac{1+\\sqrt{29}}{2}$와 $x^{2}+x-13=0$의 해 $\\frac{-1+\\sqrt{53}}{2}$는 모두 $3$보다 크다. 다른 해는 음수라 이 가지 위에 없다. 따라서 포물선과의 교점은 $4$개이다.","확인":"4","스킬":"G1"},{"제목":"교점의 총 개수","힌트":"두 경우의 교점을 더하면?","식":["$3+4=7$"],"설명":"$y=-1$ 위의 점과 포물선 위의 점은 서로 다르다. $y=-1$에서 포물선과 만나는 $x=\\pm 3$은 곡선 위에 없기 때문이다.","확인":"7","스킬":"G1"}]},"ns-941f58bef156":{"길":"x<3, x≥3과 x²이 6 이상인지로 구간을 나눠 두 합성함수를 쓴다","단계":[{"제목":"두 합성함수의 식 쓰기","힌트":"$(g\\circ f)(x)=f(x)^{2}-3$과 $(f\\circ g)(x)=f(x^{2}-3)$을 $f$의 구간에 맞게 쓰면?","식":["$(g\\circ f)(x)$: $x<3$이면 $6$, $x\\ge 3$이면 $4x^{2}-12x+6$","$(f\\circ g)(x)$: $x^{2}<6$이면 $3$, $x^{2}\\ge 6$이면 $-2x^{2}+9$"],"설명":"$f(x)=3$ ($x<3$)이면 $g(3)=6$이다. $x^{2}-3\\ge 3$일 때만 $f$의 둘째 식 $-2t+3$을 쓰므로 $x^{2}\\ge 6$이 기준이다.","확인":null,"스킬":"T6","고비":true},{"제목":"x<3인 경우 풀기","힌트":"$x<3$이면서 $x^{2}<6$일 때와 $x^{2}\\ge 6$일 때 차를 각각 구하면?","식":["$x^{2}<6$: $6-3=3\\ne 15$ → 해 없음","$x^{2}\\ge 6$: $6-(-2x^{2}+9)=15$ → $x^{2}=9$","$x<3$이므로 $x=-3$"],"설명":"$x^{2}=9$에서 $x=\\pm 3$인데 $x<3$이므로 $-3$만 남는다. $-3$은 $x^{2}\\ge 6$도 만족한다.","확인":"-3","스킬":"C2"},{"제목":"x≥3인 경우 풀기","힌트":"$x\\ge 3$이면 $x^{2}\\ge 9\\ge 6$이다. 차를 정리해 $15$와 같게 놓으면?","식":["$(4x^{2}-12x+6)-(-2x^{2}+9)=15$","$x^{2}-2x-3=0$ → $x=3$ 또는 $-1$","$x\\ge 3$이므로 $x=3$"],"설명":"정리하면 $6x^{2}-12x-18=0$이다. $x=-1$은 $x\\ge 3$을 만족하지 않는다.","확인":null,"스킬":"C2"},{"제목":"a−b의 값","힌트":"해는 $-3,\\ 3$이다. 최대와 최소를 정해 차를 구하면?","식":["$a=3,\\ b=-3$","$a-b=6$"],"설명":"구한 해 중 큰 것이 $a$, 작은 것이 $b$이다.","확인":"6","스킬":"C2"}]},"ns-979e07badaba":{"길":"f³=I로 f를 완성하고 g=f의 역함수도 세 번에 제자리로 옴을 이용한다","단계":[{"제목":"f 완성하기","힌트":"$f(0)=2$이고 $f^{3}(0)=0$이 되려면 $f(2)$는 $0$인가 $1$인가?","식":["$f(0)=2,\\ f(2)=1,\\ f(1)=0$"],"설명":"$f(2)=0$이면 $f^{2}(0)=0$이 되어 $f^{3}(0)=2$로 $f^{3}=\\mathrm{I}$에 모순이다. 따라서 $f(2)=1$이고, 일대일 대응이므로 $f(1)=0$이다.","확인":"1","스킬":"P7"},{"제목":"g=f의 역함수 구하기","힌트":"$f(a)=b$이면 $g(b)=a$이다. $g(2),\\ g(1),\\ g(0)$은?","식":["$g(2)=0,\\ g(1)=2,\\ g(0)=1$"],"설명":"$f$의 대응을 거꾸로 읽는다.","확인":"2","스킬":"T1"},{"제목":"g의 거듭제곱 줄이기","힌트":"$f^{3}=\\mathrm{I}$이면 $g^{3}$은? $2013$과 $2014$를 $3$으로 나누면?","식":["$g^{3}=(f^{3})^{-1}=\\mathrm{I}$","$2013=3\\times 671,\\ \\ 2014=3\\times 671+1$","$g^{2013}=\\mathrm{I},\\ \\ g^{2014}=g$"],"설명":"$g$도 세 번 적용하면 제자리로 오므로 지수에서 $3$의 배수를 뺄 수 있다.","확인":null,"스킬":"P7","고비":true},{"제목":"구하는 값 계산하기","힌트":"$g^{2013}(2)$와 $g^{2014}(1)$을 각각 구하면?","식":["$g^{2013}(2)=2$","$g^{2014}(1)=g(1)=2$","$2+2=4$"],"설명":"$g^{2013}=\\mathrm{I}$이므로 $g^{2013}(2)=2$이고, $g^{2014}(1)=g(1)=2$이다.","확인":"4","스킬":"P7"}]},"ns-9ff3da451733":{"길":"일의 자리 숫자를 구해 f, g의 대응표를 만들고 역함수는 거꾸로 읽는다","단계":[{"제목":"f와 g의 대응표 만들기","힌트":"$3^{n}$과 $7^{n}$의 일의 자리 숫자를 $n=1,\\ 2,\\ 3,\\ 4$에서 구하면?","식":["$f$: $1\\to3,\\ 2\\to9,\\ 3\\to7,\\ 4\\to1$","$g$: $1\\to7,\\ 2\\to9,\\ 3\\to3,\\ 4\\to1$"],"설명":"$3^{3}=27$, $3^{4}=81$, $7^{2}=49$, $7^{3}=343$, $7^{4}=2401$에서 일의 자리를 읽는다.","확인":null,"스킬":"N3"},{"제목":"역함수로 두 항 구하기","힌트":"$g^{-1}(9)$와 $f^{-1}(3)$은 표를 거꾸로 읽어 구한다. 그 값을 각각 $f,\\ g$에 넣으면?","식":["$g^{-1}(9)=2$ → $(f\\circ g^{-1})(9)=f(2)=9$","$f^{-1}(3)=1$ → $(g\\circ f^{-1})(3)=g(1)=7$"],"설명":"$g(2)=9$이므로 $g^{-1}(9)=2$이고, $f(1)=3$이므로 $f^{-1}(3)=1$이다.","확인":null,"스킬":"T1","고비":true},{"제목":"두 항의 합 구하기","힌트":"앞에서 구한 $9$와 $7$을 더하면?","식":["$9+7=16$"],"설명":"구한 두 값을 더한다.","확인":"16","스킬":"T1"}]},"ns-b04ff04629a3":{"길":"f(x)가 f의 꺾이는 점 1/2보다 큰 구간과 작은 구간을 나눠 f에 넣는다","단계":[{"제목":"그래프에서 f의 식 읽기","힌트":"$f$는 $x=\\frac{1}{2}$를 경계로 두 선분이다. 각 선분의 식은?","식":["$0\\le x<\\frac{1}{2}$: $f(x)=1-2x$","$\\frac{1}{2}\\le x\\le 1$: $f(x)=2-2x$"],"설명":"첫 선분은 $(0,\\ 1)$에서 $\\left(\\frac{1}{2},\\ 0\\right)$으로, 둘째 선분은 $\\left(\\frac{1}{2},\\ 1\\right)$에서 $(1,\\ 0)$으로 내려간다.","확인":null,"스킬":"G9"},{"제목":"구간 나누는 경계 찾기","힌트":"$f$의 식은 입력이 $\\frac{1}{2}$를 기준으로 바뀐다. $f(x)=\\frac{1}{2}$인 $x$를 모두 구하면 구간은 몇 개인가?","식":["$1-2x=\\frac{1}{2}$ → $x=\\frac{1}{4}$","$2-2x=\\frac{1}{2}$ → $x=\\frac{3}{4}$"],"설명":"$f(x)$가 $\\frac{1}{2}$ 이상인지 미만인지에 따라 $f$의 어느 식을 쓰는지 달라진다. $x=\\frac{1}{4},\\ \\frac{1}{2},\\ \\frac{3}{4}$에서 경계가 생겨 구간은 $4$개이다.","확인":"4","스킬":"C2","고비":true},{"제목":"구간별 f(f(x)) 구하기","힌트":"각 구간에서 $f(x)$가 $\\frac{1}{2}$ 이상이면 $f$의 둘째 식을, 미만이면 첫째 식을 쓰면?","식":["$0\\le x\\le\\frac{1}{4}$: $2-2(1-2x)=4x$,  $\\frac{1}{4}<x<\\frac{1}{2}$: $1-2(1-2x)=4x-1$","$\\frac{1}{2}\\le x\\le\\frac{3}{4}$: $2-2(2-2x)=4x-2$,  $\\frac{3}{4}<x\\le 1$: $1-2(2-2x)=4x-3$"],"설명":"네 구간 모두 기울기가 $4$이고, 각 구간에서 값이 $0$에서 $1$까지 늘어난다.","확인":null,"스킬":"T6"},{"제목":"개형 고르기","힌트":"기울기 $4$로 오르는 선분이 몇 개 이어지는 그래프인가?","식":["기울기 $4$로 $0$에서 $1$까지 오르는 선분 $4$개 → ③"],"설명":"각 구간의 시작점에서는 $0$, 끝점에서는 $1$이므로 오르는 선분이 네 번 반복되는 그래프이다. 이 모양은 ③이다.","확인":null,"스킬":"T6"}]},"ns-b21c37254d69":{"길":"점선을 따라 f(a), f(b), f(c)를 읽고 합성과 역함수를 차례로 푼다","단계":[{"제목":"그래프에서 함숫값 읽기","힌트":"$x=a$ 에서 점선을 따라가면 $f(a)$ 는 무엇인가?","식":["$f(a)=b,\\ f(b)=c,\\ f(c)=d$"],"설명":"$x=a$ 에서 위로 올라 곡선에 닿은 높이가 $b$ 이므로 $f(a)=b$ 이다. 이 높이를 $y=x$ 로 옮겨 $x$ 축으로 내리면 $x=b$ 이고, 같은 방법으로 $f(b)=c$, $f(c)=d$ 이다.","확인":null,"스킬":"G1"},{"제목":"합성함수의 값 구하기","힌트":"$(f\\circ f)(a)=f(f(a))$ 에서 안쪽 $f(a)$ 를 먼저 넣으면?","식":["$(f\\circ f)(a)=f(f(a))=f(b)=c$"],"설명":"안쪽 $f(a)=b$ 를 넣고, 바깥쪽 $f(b)=c$ 를 적용한다.","확인":null,"스킬":"T6"},{"제목":"합성함수의 역함수 값 구하기","고비":true,"힌트":"$(f\\circ f)^{-1}=f^{-1}\\circ f^{-1}$ 이므로 $f^{-1}(d)$ 는 무엇인가?","식":["$(f\\circ f)^{-1}(d)=f^{-1}(f^{-1}(d))$","$f^{-1}(d)=c,\\ f^{-1}(c)=b$"],"설명":"$f(c)=d$ 이므로 $f^{-1}(d)=c$ 이고, $f(b)=c$ 이므로 $f^{-1}(c)=b$ 이다. 따라서 $(f\\circ f)^{-1}(d)=b$ 이다.","확인":null,"스킬":"T6"},{"제목":"두 값의 차 구하기","힌트":"앞에서 구한 두 값 $c$, $b$ 의 차는?","식":["$(f\\circ f)(a)-(f\\circ f)^{-1}(d)=c-b$"],"설명":"$(f\\circ f)(a)=c$, $(f\\circ f)^{-1}(d)=b$ 이므로 차는 $c-b$ 이다.","확인":null,"스킬":"T6"}]},"ns-bfbf563d21e6":{"길":"f(t)=0, f(t)>0 의 해를 먼저 구하고 t=f(x)로 두어 보기를 하나씩 따진다","단계":[{"제목":"f(t)의 부호와 최솟값 정리하기","힌트":"$f(t)>0$ 이 되는 $t$ 의 범위와 $f$ 의 최솟값은?","식":["$f(t)=0$ 의 해는 $t=-3,\\ a$","$f(t)>0$ 의 해는 $t<-3$ 또는 $t>a$, 최솟값은 $-3$"],"설명":"최고차항의 계수가 양수이고 $x$ 절편이 $-3$, $a$ 이므로 $f(t)>0$ 은 두 근의 바깥쪽이다. 꼭짓점의 $y$ 좌표가 $-3$ 이므로 최솟값은 $-3$ 이다.","확인":null,"스킬":"G6"},{"제목":"ㄱ 의 참거짓 판정","힌트":"$f(0)$ 이 최솟값 $-3$ 과 같아지려면 꼭짓점의 $x$ 좌표가 얼마여야 하는가?","식":["$f(f(-3))=f(0)$","꼭짓점의 $x$ 좌표 $\\frac{a-3}{2}>0$","$f(0)>-3$"],"설명":"꼭짓점의 $x$ 좌표는 두 근 $-3$, $a$ 의 중점 $\\frac{a-3}{2}$ 이고 $a>3$ 이므로 $0$ 이 아니다. 따라서 $f(0)$ 은 최솟값 $-3$ 이 아니어서 $f(0)>-3$ 이고 ㄱ 은 옳다.","확인":null,"스킬":"G7"},{"제목":"ㄴ 의 실근 개수 세기","힌트":"$f(f(x))=0$ 이면 $f(x)$ 는 어떤 값이어야 하는가?","식":["$f(f(x))=0 \\iff f(x)=-3$ 또는 $f(x)=a$","$f(x)=-3$ 은 $1$개, $f(x)=a$ 는 $2$개"],"설명":"$f(t)=0$ 의 해가 $t=-3,\\ a$ 이므로 $f(x)=-3$ 또는 $f(x)=a$ 이다. 직선 $y=-3$ 은 꼭짓점에서 접하므로 실근이 $1$개이고, 직선 $y=a$ 는 $a>-3$ 이므로 두 점에서 만나 $2$개이다. 서로 다른 실근은 $3$개이므로 ㄴ 은 거짓이다.","확인":"3","스킬":"T6"},{"제목":"ㄷ 의 집합 포함 판정과 정답 고르기","고비":true,"힌트":"$f(f(x))>0$ 이 되려면 $f(x)$ 는 어느 범위여야 하고, $f(x)<-3$ 은 가능한가?","식":["$f(f(x))>0 \\iff f(x)<-3$ 또는 $f(x)>a$","$f(x)\\ge-3$ 이므로 $f(x)<-3$ 은 불가능","$\\{x\\mid f(f(x))>0\\}=\\{x\\mid f(x)>a\\}$"],"설명":"$f(t)>0$ 의 해에서 $t=f(x)$ 로 놓으면 $f(x)<-3$ 또는 $f(x)>a$ 이다. $f(x)$ 의 최솟값이 $-3$ 이어서 앞의 경우는 일어나지 않으므로 두 집합은 같고, 부분집합 관계가 성립하여 ㄷ 은 옳다. 따라서 옳은 것은 ㄱ, ㄷ 이다.","확인":null,"스킬":"T6"}]},"ns-c2b3aeca3ed6":{"길":"f 의 역함수 값을 정리하고 x=2, x=1 을 조건에 넣어 g(1), g(3)을 차례로 구한다","단계":[{"제목":"그림에서 역함수 값 정리하기","힌트":"화살표를 거꾸로 읽으면 $f^{-1}(2)$ 는 얼마인가?","식":["$f(1)=2,\\ f(2)=3,\\ f(3)=1,\\ f(4)=4$","$f^{-1}(1)=3,\\ f^{-1}(2)=1,\\ f^{-1}(3)=2$"],"설명":"$f$ 는 $1\\to2$, $2\\to3$, $3\\to1$, $4\\to4$ 로 대응한다. 화살표 방향을 거꾸로 읽으면 $f^{-1}(1)=3$, $f^{-1}(2)=1$, $f^{-1}(3)=2$ 이다.","확인":"1","스킬":"T1"},{"제목":"x=2 를 넣어 g(1) 구하기","고비":true,"힌트":"$f^{-1}\\circ g=g\\circ f^{-1}$ 의 양변에 $x=2$ 를 넣으면 $g(1)$ 은?","식":["$f^{-1}(g(2))=f^{-1}(1)=3$","$g(f^{-1}(2))=g(1)$","$g(1)=3$"],"설명":"좌변은 $g(2)=1$ 이므로 $f^{-1}(1)=3$ 이다. 우변은 $f^{-1}(2)=1$ 이므로 $g(1)$ 이다. 두 변이 같으므로 $g(1)=3$ 이다.","확인":"3","스킬":"T6"},{"제목":"x=1 을 넣어 g(3) 구하기","힌트":"같은 식에 $x=1$ 을 넣으면 $g(3)$ 은?","식":["$f^{-1}(g(1))=f^{-1}(3)=2$","$g(f^{-1}(1))=g(3)$","$g(3)=2$"],"설명":"앞에서 $g(1)=3$ 이므로 좌변은 $f^{-1}(3)=2$ 이다. 우변은 $f^{-1}(1)=3$ 이므로 $g(3)$ 이다. 따라서 $g(3)=2$ 이다.","확인":"2","스킬":"T6"},{"제목":"비의 값 구하기","힌트":"$g(3)$ 을 $g(1)$ 로 나누면?","식":["$\\frac{g(3)}{g(1)}=\\frac{2}{3}$"],"설명":"$g(3)=2$, $g(1)=3$ 이므로 비의 값은 $\\frac{2}{3}$ 이다.","확인":"2/3","스킬":"T6"}]},"ns-d9e884595096":{"길":"f(f(x))의 그래프를 그리고 (0,1)을 지나는 직선을 돌려 교점 수를 센다","단계":[{"제목":"f(x)의 구간별 식 세우기","힌트":"$x\\ge2$ 와 $x<2$ 에서 직선의 기울기와 지나는 점은?","식":["$f(x)=x-3\\ (x\\ge2)$","$f(x)=-x+1\\ (x<2)$"],"설명":"$x\\ge2$ 에서는 $(2,-1)$, $(3,0)$ 을 지나는 기울기 $1$ 의 직선이고, $x<2$ 에서는 $(0,1)$, $(1,0)$ 을 지나는 기울기 $-1$ 의 직선이다.","확인":null,"스킬":"G9"},{"제목":"f(f(x))의 구간별 식 구하기","고비":true,"힌트":"안쪽 $f(x)$ 가 $2$ 이상인지 미만인지에 따라 바깥 $f$ 의 어떤 식을 쓰는가?","식":["$x\\ge5:\\ x-6,\\quad 2\\le x<5:\\ -x+4$","$-1<x<2:\\ x,\\quad x\\le-1:\\ -x-2$"],"설명":"안쪽 값 $f(x)$ 가 $2$ 이상이면 $f(f(x))=f(x)-3$, $2$ 미만이면 $-f(x)+1$ 이다. $f(x)\\ge2$ 인 경우는 $x\\ge5$ 또는 $x\\le-1$ 이다. 각 구간에서 $f(x)$ 의 식을 넣어 정리한다.","확인":null,"스킬":"T6"},{"제목":"꺾인 점 A 를 지나는 직선의 기울기","힌트":"직선이 $\\mathrm{C}(0,1)$ 과 꺾인 점 $\\mathrm{A}(2,2)$ 를 지날 때 기울기는?","식":["$\\mathrm{A}(2,\\,2)$","$a=\\frac{2-1}{2-0}=\\frac{1}{2}$"],"설명":"$y=ax+1$ 은 $a$ 에 관계없이 $\\mathrm{C}(0,1)$ 을 지난다. 점 $\\mathrm{A}$ 를 지날 때 $a=\\frac{1}{2}$ 이고, 교점은 $x=-2$, $x=2$, $x=14$ 로 $3$개이다. 기울기가 이보다 커지면 교점은 $2$개로 줄어든다.","확인":"1/2","스킬":"G3"},{"제목":"꺾인 점 B 를 지나는 직선의 기울기","힌트":"직선이 $\\mathrm{C}(0,1)$ 과 꺾인 점 $\\mathrm{B}(5,-1)$ 을 지날 때 기울기는?","식":["$\\mathrm{B}(5,\\,-1)$","$a=\\frac{-1-1}{5-0}=-\\frac{2}{5}$"],"설명":"점 $\\mathrm{B}$ 를 지날 때 $a=-\\frac{2}{5}$ 이고, 교점은 $x=-5$, $x=\\frac{5}{7}$, $x=5$ 로 $3$개이다. 기울기가 이보다 작아지면 교점은 $2$개로 줄어든다.","확인":"-2/5","스킬":"G3"},{"제목":"교점이 3개 이상인 범위 정하기","힌트":"기울기가 두 경계값 사이일 때 교점은 몇 개인가?","식":["$-\\frac{2}{5}\\le a\\le\\frac{1}{2}$"],"설명":"$-\\frac{2}{5}<a<\\frac{1}{2}$ 이면 직선이 $\\mathrm{A}$ 의 아래쪽, $\\mathrm{B}$ 의 위쪽을 지나 교점이 $4$개이고, 두 경계에서는 $3$개이다. 이 범위 밖에서는 교점이 $2$개 이하이므로 구하는 범위는 $-\\frac{2}{5}\\le a\\le\\frac{1}{2}$ 이다.","확인":null,"스킬":"G3"}]},"ns-e1b224853a9e":{"길":"f, g 의 식으로 g(f(x))의 W자 그래프를 그리고 사분원과 구간마다 교점을 센다","단계":[{"제목":"f, g 의 식 세우기","힌트":"$x=\\frac{1}{2}$ 을 경계로 $f$ 와 $g$ 의 식은 각각 어떻게 나뉘는가?","식":["$f(x)=2x\\ \\left(0\\le x\\le\\frac{1}{2}\\right),\\quad f(x)=2-2x\\ \\left(\\frac{1}{2}\\le x\\le1\\right)$","$g(t)=|2t-1|\\ (0\\le t\\le1)$"],"설명":"$f$ 는 $(0,0)$, $\\left(\\frac{1}{2},1\\right)$, $(1,0)$ 을 잇는 꺾은선이다. $g$ 는 $(0,1)$, $\\left(\\frac{1}{2},0\\right)$, $(1,1)$ 을 잇는 꺾은선이므로 $t=\\frac{1}{2}$ 를 기준으로 $1-2t$, $2t-1$ 이고 절댓값 하나로 쓸 수 있다.","확인":null,"스킬":"G5"},{"제목":"g∘f 의 꺾인 점 구하기","힌트":"$x=\\frac{1}{4}$ 에서 $g(f(x))$ 의 값은?","식":["$g(f(x))=|2f(x)-1|$","$x=0,\\frac{1}{4},\\frac{1}{2},\\frac{3}{4},1$ 에서 $1,\\ 0,\\ 1,\\ 0,\\ 1$"],"설명":"$f(x)=\\frac{1}{2}$ 인 $x=\\frac{1}{4},\\frac{3}{4}$ 에서 $g(f(x))=0$ 이고, $f(x)=0$ 또는 $1$ 인 $x=0,\\frac{1}{2},1$ 에서 $1$ 이다. 따라서 그래프는 기울기 $\\pm4$ 인 선분 네 개가 이어진 W 모양이다.","확인":"0","스킬":"T6"},{"제목":"구간마다 교점 세기","고비":true,"힌트":"$x=0$ 이외의 교점은 모두 몇 개인가?","식":["$x=0$ 에서 $g(f(0))=1=\\sqrt{1-0^2}$ — 교점","$\\left[0,\\frac{1}{4}\\right]$ 에서는 $x=0$ 뿐, 나머지 세 구간에서는 각 $1$개"],"설명":"사분원은 $1$ 에서 $0$ 으로 완만하게 줄어든다. 첫 구간에서는 W 자가 기울기 $-4$ 로 급히 내려가 사분원보다 아래에 머물러 $x=0$ 외에 만나지 않는다. $\\frac{1}{4}\\le x\\le\\frac{1}{2}$ 에서는 W 자가 $0$ 에서 $1$ 로 올라 사분원 값($0.97$ 에서 $0.87$)을 한 번 넘고, $\\frac{1}{2}\\le x\\le\\frac{3}{4}$ 에서는 $1$ 에서 $0$ 으로 내려가며 사분원 값($0.87$ 에서 $0.66$)을 한 번 지나친다. $\\frac{3}{4}\\le x\\le1$ 에서는 $0$ 에서 $1$ 로 올라 사분원 값($0.66$ 에서 $0$)을 한 번 넘는다.","확인":"3","스킬":"G1"},{"제목":"교점의 개수 합하기","힌트":"$x=0$ 의 교점과 나머지 교점을 합하면?","식":["$1+3=4$"],"설명":"정의역이 $0\\le x\\le1$ 이므로 $x=0$ 의 교점도 포함하여 교점은 모두 $4$개이다.","확인":"4","스킬":"G1"}]},"ns-f00c09b70eea":{"길":"f 를 세 번 합성한 톱니 그래프를 구간별로 쓰고 직선 y=3x/2 와 비교해 교점을 센다","단계":[{"제목":"f 의 구간별 식 세우기","힌트":"$x=\\frac{1}{2}$ 을 경계로 $f(x)$ 의 식은 어떻게 나뉘는가?","식":["$f(x)=2x\\ \\left(0\\le x\\le\\frac{1}{2}\\right)$","$f(x)=2-2x\\ \\left(\\frac{1}{2}\\le x\\le1\\right)$"],"설명":"그래프는 $(0,0)$, $\\left(\\frac{1}{2},1\\right)$, $(1,0)$ 을 잇는 꺾은선이다. 기울기는 각각 $2$, $-2$ 이다.","확인":null,"스킬":"G9"},{"제목":"f∘f∘f 의 구간별 식 구하기","고비":true,"힌트":"$0\\le x<\\frac{1}{8}$ 에서 $f(f(f(x)))$ 는 어떤 식이 되는가?","식":["$0\\le x<\\frac{1}{8}:\\ 8x,\\quad \\frac{1}{8}\\le x<\\frac{1}{4}:\\ -8x+2,\\quad \\frac{1}{4}\\le x<\\frac{3}{8}:\\ 8x-2$","$\\frac{3}{8}\\le x<\\frac{1}{2}:\\ -8x+4,\\quad \\frac{1}{2}\\le x<\\frac{5}{8}:\\ 8x-4,\\quad \\frac{5}{8}\\le x<\\frac{3}{4}:\\ -8x+6$","$\\frac{3}{4}\\le x<\\frac{7}{8}:\\ 8x-6,\\quad \\frac{7}{8}\\le x\\le1:\\ -8x+8$"],"설명":"$0\\le x<\\frac{1}{8}$ 에서는 $f(x)=2x$, $f(f(x))=4x$, $f(f(f(x)))=8x$ 이다. 합성할 때마다 산의 개수와 기울기의 크기가 두 배가 되어 $[0,1]$ 이 $8$등분되고, 각 구간에서 값이 $0$ 과 $1$ 사이를 오가는 기울기 $\\pm8$ 의 선분이 된다. 꺾이는 점 $x=\\frac{k}{8}$ 에서 값은 $0,1,0,1,\\ldots$ 이다.","확인":null,"스킬":"T6"},{"제목":"직선이 1 을 넘는 구간 제외하기","힌트":"직선 $y=\\frac{3}{2}x$ 의 값이 $1$ 이 되는 $x$ 는?","식":["$\\frac{3}{2}x=1 \\Rightarrow x=\\frac{2}{3}$"],"설명":"$f(f(f(x)))$ 의 값은 $0$ 이상 $1$ 이하이다. $x>\\frac{2}{3}$ 에서는 직선의 값이 $1$ 보다 커서 만나지 않는다. 특히 $\\frac{3}{4}\\le x\\le1$ 에서는 직선의 값이 $\\frac{9}{8}$ 이상이므로 이 구간은 볼 필요가 없다.","확인":"2/3","스킬":"G1"},{"제목":"구간마다 교점 세기","힌트":"$\\frac{1}{8}\\le x\\le\\frac{3}{4}$ 의 각 구간에서 톱니와 직선은 몇 번 만나는가?","식":["$0<x\\le\\frac{1}{8}:\\ 8x>\\frac{3}{2}x$ 이므로 교점 없음","$\\frac{1}{8}\\le x\\le\\frac{3}{4}$ 의 $5$개 구간에서 각 $1$개"],"설명":"$0<x\\le\\frac{1}{8}$ 에서는 $8x>\\frac{3}{2}x$ 라 만나지 않고, $x=0$ 은 구간 $0<x<1$ 에 포함되지 않는다. $\\left[\\frac{1}{8},\\frac{1}{4}\\right]$ 에서 톱니는 $1$ 에서 $0$ 으로 내려가고 직선은 $\\frac{3}{16}$ 에서 $\\frac{3}{8}$ 로 올라 한 번 만난다. $\\left[\\frac{1}{4},\\frac{3}{8}\\right]$, $\\left[\\frac{3}{8},\\frac{1}{2}\\right]$, $\\left[\\frac{1}{2},\\frac{5}{8}\\right]$, $\\left[\\frac{5}{8},\\frac{3}{4}\\right]$ 에서도 톱니가 직선의 위와 아래를 한 번씩 오가므로 각각 한 번 만난다. 따라서 교점은 $5$개이다.","확인":"5","스킬":"G1"}]},"ns-01b69e9bb524":{"길":"(가)에서 m 을 구하고 (나)를 이차식의 최댓값으로 바꿔 k 를 찾는다","단계":[{"제목":"g(x)의 식 세우기","힌트":"$x$ 축 방향으로 $m$ 만큼 평행이동하면 $x$ 대신 무엇을 넣는가?","식":["$g(x)=\\frac{k}{x-m}+3$"],"설명":"$x$ 축의 방향으로 $m$ 만큼 평행이동하면 $x$ 를 $x-m$ 으로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"(가)로 m 의 값 구하기","고비":true,"힌트":"$g(a)=b$, $g(b)=a$ 에서 $k$ 를 각각 $a$, $b$, $m$ 으로 나타내 같다고 놓으면?","식":["$(a-m)(b-3)=k,\\quad (b-m)(a-3)=k$","$(3-m)(b-a)=0$"],"설명":"$g(a)=b$ 에서 $\\frac{k}{a-m}=b-3$ 이므로 $(a-m)(b-3)=k$ 이다. 같은 방법으로 $g(b)=a$ 에서 $(b-m)(a-3)=k$ 이다. 두 식의 좌변이 같으므로 전개하여 정리하면 $(3-m)(b-a)=0$ 이다. $a\\ne b$ 이므로 $m=3$ 이다.","확인":"3","스킬":"A10"},{"제목":"(나)의 식을 이차식으로 바꾸기","힌트":"$f(x)-g(x)$ 를 통분하면 분자는?","식":["$f(x)-g(x)=\\frac{k}{x}-\\frac{k}{x-3}=\\frac{-3k}{x(x-3)}$","$\\frac{1}{f(x)-g(x)}=-\\frac{1}{3k}x(x-3)$"],"설명":"통분하면 분자는 $k(x-3)-kx=-3k$ 이다. 역수를 취하면 $x$ 에 대한 이차식이 된다.","확인":null,"스킬":"C7"},{"제목":"최댓값으로 k 의 값 구하기","힌트":"$-\\frac{1}{3k}x(x-3)$ 은 $0<x<3$ 에서 $x$ 가 얼마일 때 최대인가?","식":["$x=\\frac{3}{2}$ 일 때 최대, 최댓값 $\\frac{9}{12k}$","$\\frac{9}{12k}=\\frac{1}{12} \\Rightarrow k=9$"],"설명":"$x(x-3)$ 은 $x=\\frac{3}{2}$ 에서 최솟값 $-\\frac{9}{4}$ 를 갖고, 앞의 계수 $-\\frac{1}{3k}$ 는 음수이므로 이때 최대이다. 최댓값은 $\\frac{9}{12k}$ 이고 이것이 $\\frac{1}{12}$ 이므로 $k=9$ 이다.","확인":"9","스킬":"A6"},{"제목":"g(4)의 값 구하기","힌트":"$g(x)=\\frac{9}{x-3}+3$ 에 $x=4$ 를 넣으면?","식":["$g(4)=\\frac{9}{4-3}+3=12$"],"설명":"$m=3$, $k=9$ 이므로 $g(x)=\\frac{9}{x-3}+3$ 이다. $x=4$ 를 대입하면 $9+3=12$ 이다.","확인":"12","스킬":"G4"}]},"ns-11c49616a6be":{"길":"점근선과 대칭, 상수함수 조건을 보기마다 확인해 틀린 설명을 찾는다","단계":[{"제목":"윤도의 설명 점검하기","힌트":"$y=\\frac{1}{x+3}+3$ 의 수직 점근선은 $x=$ 얼마인가?","식":["$y=\\frac{1}{x-(-3)}+3$","점근선: $x=-3,\\ y=3$"],"설명":"$y=\\frac{k}{x-p}+q$ 의 점근선은 $x=p$, $y=q$ 이다. $x+3=x-(-3)$ 이므로 $p=-3$ 이고 점근선은 $x=-3$, $y=3$ 이다. 윤도는 $x=3$ 이라 했으므로 옳지 않다.","확인":"-3","스킬":"T4"},{"제목":"지은의 설명 점검하기","고비":true,"힌트":"점근선이 없는 유리함수의 예는 무엇인가?","식":["$y=x$ 는 유리함수이지만 점근선이 없다"],"설명":"다항함수 $y=x$ 도 유리함수이고 그래프는 직선이라 점근선이 없다. 점근선이 항상 $2$개라는 설명은 성립하지 않으므로 지은은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"나머지 설명 확인과 결론","힌트":"유진, 수지, 상윤의 설명은 각각 옳은가?","식":["$ad-bc=0$ 이면 $\\frac{ax+b}{cx+d}=\\frac{a}{c}$"],"설명":"$y=f(x)$ 와 $y=-f(x)$ 는 $y$ 좌표의 부호만 바뀌므로 $x$ 축에 대하여 대칭이다. $ad-bc=0$, $c\\ne0$ 이면 분자가 분모의 상수배라 약분되어 $y=\\frac{a}{c}$ (단, $x\\ne-\\frac{d}{c}$) 상수함수가 된다. 점근선의 정의도 상윤의 말과 같다. 따라서 옳지 않은 설명을 한 학생은 윤도와 지은이다.","확인":null,"스킬":"C3"}]},"ns-21d65fe4a1fe":{"길":"점근선의 교점 Q 를 중심으로 한 대칭축 위의 점 P 를 구해 PQ 를 k 로 나타낸다","단계":[{"제목":"점 Q 와 대칭축 찾기","힌트":"두 점근선 $x=a$, $y=b$ 의 교점 $\\mathrm{Q}$ 를 지나는 대칭축은?","식":["$\\mathrm{Q}(a,\\,b)$","$y-b=\\frac{k}{x-a}$ 는 직선 $y-b=x-a$ 에 대하여 대칭"],"설명":"$X=x-a$, $Y=y-b$ 로 놓으면 곡선은 $Y=\\frac{k}{X}$ 이고 이는 $Y=X$ 에 대하여 대칭이다. 즉 $\\mathrm{Q}$ 를 지나는 기울기 $1$ 의 직선 $y=x-a+b$ 가 대칭축이다.","확인":null,"스킬":"T4"},{"제목":"대칭축 위의 점 P 구하기","고비":true,"힌트":"$x-a+b=\\frac{k}{x-a}+b$ 에서 $x-a$ 는 얼마인가? (단 $x>a$)","식":["$(x-a)^2=k$","$\\mathrm{P}(a+\\sqrt{k},\\ b+\\sqrt{k})$"],"설명":"곡선과 대칭축의 교점은 $x-a=\\frac{k}{x-a}$ 에서 $(x-a)^2=k$ 이다. $x>a$ 이므로 $x=a+\\sqrt{k}$ 이고, 대칭축 위의 점이므로 $y=b+\\sqrt{k}$ 이다.","확인":null,"스킬":"G1"},{"제목":"선분 PQ 의 길이 나타내기","힌트":"$\\mathrm{P}$ 와 $\\mathrm{Q}$ 의 $x$ 좌표 차와 $y$ 좌표 차는 각각 얼마인가?","식":["$\\overline{\\mathrm{PQ}}=\\sqrt{(\\sqrt{k})^2+(\\sqrt{k})^2}=\\sqrt{2k}$"],"설명":"두 좌표의 차가 모두 $\\sqrt{k}$ 이므로 $\\overline{\\mathrm{PQ}}=\\sqrt{2k}$ 이다. 곡선 위의 점 중 대칭축 위의 점이 $\\mathrm{Q}$ 에 가장 가깝다. $x-a=t$ 로 놓으면 $\\overline{\\mathrm{PQ}}^2=t^2+\\frac{k^2}{t^2}\\ge2k$ 이므로 산술·기하평균으로도 최솟값이 $\\sqrt{2k}$ 임을 알 수 있다.","확인":null,"스킬":"A7"},{"제목":"k 의 값 구하기","힌트":"$\\sqrt{2k}=6$ 에서 $k$ 는 얼마인가?","식":["$\\sqrt{2k}=6 \\Rightarrow 2k=36$","$k=18$"],"설명":"최솟값이 $6$ 이므로 $\\sqrt{2k}=6$ 이다. 양변을 제곱하면 $2k=36$ 이므로 $k=18$ 이다.","확인":"18","스킬":"A7"}]},"ns-3fb3b4243f59":{"길":"A, D 가 y=x 에 대칭임을 이용해 좌표를 구하고 B, C 를 찾아 직사각형의 넓이를 구한다","단계":[{"제목":"A, D 의 좌표 구하기","힌트":"$\\mathrm{A}\\left(p,\\frac{2}{p}\\right)$ 라 할 때 그림에 맞는 $p$ 는 얼마인가?","식":["$\\mathrm{A}\\left(p,\\frac{2}{p}\\right),\\ \\mathrm{D}\\left(\\frac{2}{p},p\\right)$","$\\overline{\\mathrm{AD}}=\\sqrt{2}\\left|p-\\frac{2}{p}\\right|=\\sqrt{2}$"],"설명":"$y=\\frac{2}{x}$ 는 $y=x$ 에 대하여 대칭이고, 기울기가 $-1$ 인 직선 $\\mathrm{AD}$ 는 $y=x$ 에 수직이다. 따라서 $\\mathrm{A}\\left(p,\\frac{2}{p}\\right)$ 이면 $\\mathrm{D}\\left(\\frac{2}{p},p\\right)$ 이다. $\\left|p-\\frac{2}{p}\\right|=1$ 이고 그림에서 $\\mathrm{A}$ 는 제$1$사분면에서 $\\mathrm{D}$ 의 왼쪽 위에 있으므로 $p=1$ 이다. 즉 $\\mathrm{A}(1,2)$, $\\mathrm{D}(2,1)$ 이다.","확인":"1","스킬":"T2"},{"제목":"직선 l₁, l₂ 의 식과 B, C 구하기","고비":true,"힌트":"$l_1$ 이 곡선과 다시 만나는 점 $\\mathrm{B}$ 의 $x$ 좌표는?","식":["$l_1:\\ y=x+1,\\quad x+1=\\frac{2}{x} \\Rightarrow x=1,\\ -2$","$l_2:\\ y=x-1,\\quad x-1=\\frac{2}{x} \\Rightarrow x=2,\\ -1$","$\\mathrm{B}(-2,\\,-1),\\ \\mathrm{C}(-1,\\,-2)$"],"설명":"$l_1$ 은 $\\mathrm{A}(1,2)$ 를 지나는 기울기 $1$ 의 직선이므로 $y=x+1$ 이고, $x^2+x-2=0$ 에서 $x=1$ 또는 $x=-2$ 이다. 그림에서 $\\mathrm{B}$ 는 제$3$사분면에 있으므로 $\\mathrm{B}(-2,-1)$ 이다. $l_2$ 는 $\\mathrm{D}(2,1)$ 을 지나 $y=x-1$ 이고 $x^2-x-2=0$ 에서 $x=2$ 또는 $x=-1$ 이므로 $\\mathrm{C}(-1,-2)$ 이다.","확인":"-2","스킬":"G1"},{"제목":"사각형의 두 변의 길이 구하기","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 의 좌표 차로 $\\overline{\\mathrm{AB}}$ 의 길이를 구하면?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(1+2)^2+(2+1)^2}=3\\sqrt{2}$","$\\overline{\\mathrm{AD}}=\\sqrt{2}$"],"설명":"$\\mathrm{AB}$ 의 기울기는 $1$, $\\mathrm{AD}$ 의 기울기는 $-1$ 로 서로 수직이다. $\\mathrm{AB}\\parallel\\mathrm{DC}$, $\\mathrm{AD}\\parallel\\mathrm{BC}$ 이므로 사각형 $\\mathrm{ABCD}$ 는 직사각형이다. 두 변의 길이는 $3\\sqrt{2}$, $\\sqrt{2}$ 이다.","확인":null,"스킬":"S4"},{"제목":"직사각형의 넓이 구하기","힌트":"가로와 세로의 곱은?","식":["$3\\sqrt{2}\\times\\sqrt{2}=6$"],"설명":"직사각형의 넓이는 두 변의 길이의 곱이므로 $3\\sqrt{2}\\times\\sqrt{2}=6$ 이다.","확인":"6","스킬":"S4"}]},"ns-41eb961f7170":{"길":"B, R, P 가 한 직선 위임을 써서 P 를 구하고 사각형 OBPQ 에서 삼각형 OAB 를 뺀다","단계":[{"제목":"점 A, B 와 점근선의 교점 구하기","힌트":"그래프가 $x$ 축, $y$ 축과 만나는 점의 좌표를 $k$ 로 나타내면?","식":["$\\mathrm{A}\\left(\\frac{2-k}{2},\\,0\\right),\\ \\mathrm{B}(0,\\,2-k)$","두 점근선의 교점 $\\mathrm{R}(1,\\,2)$"],"설명":"$y=0$ 이면 $\\frac{k}{x-1}=-2$ 에서 $x=1-\\frac{k}{2}=\\frac{2-k}{2}$ 이다. $x=0$ 이면 $y=-k+2$ 이다. 점근선은 $x=1$, $y=2$ 이므로 교점은 $(1,2)$ 이다.","확인":null,"스킬":"T4"},{"제목":"점 P 의 좌표 구하기","고비":true,"힌트":"$\\mathrm{B}$, $\\mathrm{R}$, $\\mathrm{P}$ 가 한 직선 위에 있으므로 $\\mathrm{P}$ 의 $x$ 좌표 $a$ 는 얼마인가?","식":["$\\mathrm{P}\\left(a,\\frac{k}{a-1}+2\\right)$ 라 하면 $k=\\frac{k}{(a-1)^2}$","$(a-1)^2=1,\\ a=2$"],"설명":"$\\mathrm{BR}$ 의 기울기는 $\\frac{2-(2-k)}{1-0}=k$ 이고, $\\mathrm{RP}$ 의 기울기는 $\\frac{k}{a-1}\\div(a-1)=\\frac{k}{(a-1)^2}$ 이다. 두 기울기가 같으므로 $(a-1)^2=1$ 이고, $\\mathrm{P}$ 가 $x>1$ 쪽에 있으므로 $a=2$ 이다.","확인":"2","스킬":"G3"},{"제목":"사각형 OBPQ 의 넓이 구하기","힌트":"$\\mathrm{OB}$ 와 $\\mathrm{QP}$ 를 평행한 두 변으로 보면 넓이는?","식":["$\\mathrm{P}(2,\\,k+2),\\ \\mathrm{Q}(2,\\,0)$","$\\square\\mathrm{OBPQ}=\\frac{1}{2}\\times2\\times\\{(2-k)+(k+2)\\}=4$"],"설명":"$\\mathrm{OB}=2-k$, $\\mathrm{QP}=k+2$ 는 모두 $y$ 축에 평행하고 둘 사이의 거리는 $2$ 이므로 사다리꼴이다. 넓이는 $k$ 가 사라져 $4$ 로 일정하다.","확인":"4","스킬":"G10"},{"제목":"삼각형 OAB 를 빼서 식 세우기","힌트":"사각형 $\\mathrm{PBAQ}$ 는 $\\square\\mathrm{OBPQ}$ 에서 어느 삼각형을 뺀 것인가?","식":["$\\triangle\\mathrm{OAB}=\\frac{1}{2}\\times\\frac{2-k}{2}\\times(2-k)=\\frac{(2-k)^2}{4}$","$4-\\frac{(2-k)^2}{4}=\\frac{13}{4}$"],"설명":"$\\square\\mathrm{PBAQ}=\\square\\mathrm{OBPQ}-\\triangle\\mathrm{OAB}$ 이다. $\\triangle\\mathrm{OAB}$ 는 밑변 $\\mathrm{OA}=\\frac{2-k}{2}$, 높이 $\\mathrm{OB}=2-k$ 이므로 넓이가 $\\frac{(2-k)^2}{4}$ 이다.","확인":null,"스킬":"G10"},{"제목":"k 의 값 구하기","힌트":"$(2-k)^2$ 의 값은? ($0<k<2$ 임에 주의)","식":["$(2-k)^2=3$","$2-k=\\sqrt{3},\\ k=2-\\sqrt{3}$"],"설명":"$4-\\frac{(2-k)^2}{4}=\\frac{13}{4}$ 에서 $(2-k)^2=3$ 이다. $0<k<2$ 이므로 $2-k>0$ 이어서 $2-k=\\sqrt{3}$, 즉 $k=2-\\sqrt{3}$ 이다.","확인":null,"스킬":"A6"}]},"ns-45c26c38e604":{"길":"점근선으로 a, b 를 정하고 그래프가 지나는 점 (1,0)을 넣어 k 를 구한다","단계":[{"제목":"점근선으로 a, b 정하기","고비":true,"힌트":"$y=\\frac{k}{x+a}+b$ 의 점근선 $x=-a$, $y=b$ 를 그림의 $x=3$, $y=2$ 와 비교하면 $a$ 는?","식":["$-a=3,\\ b=2$","$a=-3,\\ b=2$"],"설명":"$y=\\frac{k}{x+a}+b$ 의 점근선은 $x=-a$, $y=b$ 이다. 그림의 점근선이 $x=3$, $y=2$ 이므로 $-a=3$, $b=2$ 이다.","확인":"-3","스킬":"T4"},{"제목":"지나는 점으로 k 구하기","힌트":"$(1,0)$ 을 $y=\\frac{k}{x-3}+2$ 에 대입하면 $k$ 는?","식":["$0=\\frac{k}{1-3}+2$","$k=4$"],"설명":"그래프가 $x$ 절편 $(1,0)$ 을 지나므로 $0=\\frac{k}{-2}+2$ 이고, 이로부터 $k=4$ 이다.","확인":"4","스킬":"G1"},{"제목":"a+b+k 구하기","힌트":"$a=-3$, $b=2$, $k=4$ 를 더하면?","식":["$a+b+k=-3+2+4=3$"],"설명":"세 상수를 모두 더하면 $3$ 이다.","확인":"3","스킬":"T4"}]},"ns-57d06f73e35d":{"길":"f(f(x))를 구해 (f∘f)(k)=k 를 k 의 이차방정식으로 정리하고 중근 조건을 쓴다","단계":[{"제목":"합성함수 구하기","힌트":"$f(f(x))=\\frac{2f(x)-1}{f(x)+a}$ 에 $f(x)$ 를 넣고 분자·분모에 $x+a$ 를 곱하면 분자는?","식":["$(f\\circ f)(x)=\\frac{2(2x-1)-(x+a)}{(2x-1)+a(x+a)}=\\frac{3x-2-a}{(a+2)x+a^2-1}$"],"설명":"분자는 $2(2x-1)-(x+a)=3x-2-a$ 이고, 분모는 $(2x-1)+a(x+a)=(a+2)x+a^2-1$ 이다.","확인":null,"스킬":"T6"},{"제목":"방정식을 k 에 대한 이차식으로 정리하기","고비":true,"힌트":"$(f\\circ f)(k)=k$ 의 양변에 분모를 곱해 정리하면?","식":["$(a+2)k^2+(a^2-4)k+(a+2)=0$","$k^2+(a-2)k+1=0$"],"설명":"$3k-2-a=k\\{(a+2)k+a^2-1\\}$ 을 정리하면 $(a+2)k^2+(a^2-4)k+(a+2)=0$ 이다. $a>0$ 이므로 $a+2\\ne0$ 이고, 양변을 $a+2$ 로 나누면 $k^2+(a-2)k+1=0$ 이다. 이 식은 $f(k)=k$ 를 정리한 식과 같다.","확인":null,"스킬":"C7"},{"제목":"실근이 하나일 조건 세우기","힌트":"이차방정식이 서로 다른 실근을 오직 하나만 가지려면 판별식은?","식":["$D=(a-2)^2-4=0$","$a=0$ 또는 $a=4$"],"설명":"실근이 오직 하나이므로 중근이어야 하고 $D=0$ 이다. $(a-2)^2=4$ 에서 $a-2=\\pm2$ 이므로 $a=4$ 또는 $a=0$ 이다.","확인":null,"스킬":"G2"},{"제목":"조건 확인하고 a 정하기","힌트":"$a>0$ 이면 $a$ 는? 그때의 중근은 정의역에 속하는가?","식":["$a=4$","$k=-1,\\ f(-1)=-1$"],"설명":"$a>0$ 이므로 $a=4$ 이다. 이때 중근은 $k=-1$ 이고 $f(-1)=-1$ 이며 $x=-a=-4$ 가 아니므로 $f(f(k))$ 가 정의된다.","확인":"4","스킬":"G2"}]},"ns-7a8cebe94ce1":{"길":"f(x)=k-2/(x+1) 로 고쳐 점근선과 증가 구간을 잡고 보기를 하나씩 따진다","단계":[{"제목":"식을 변형해 점근선 찾기","힌트":"분자 $kx-2+k$ 를 $k(x+1)-2$ 로 쓰면 $f(x)$ 는?","식":["$f(x)=k-\\frac{2}{x+1}$","점근선 $x=-1,\\ y=k$"],"설명":"$kx-2+k=k(x+1)-2$ 이므로 $f(x)=k-\\frac{2}{x+1}$ 이다. 점근선은 $x=-1$, $y=k$ 이고 $-\\frac{2}{x+1}$ 은 각 구간에서 증가하므로 $f$ 도 각 구간에서 증가한다.","확인":null,"스킬":"T4"},{"제목":"ㄱ 의 참거짓 판정","힌트":"$k=1$ 일 때 $x\\ge0$ 에서 $f(x)$ 가 한없이 가까워지는 값에 실제로 도달하는가?","식":["$f(x)=1-\\frac{2}{x+1}\\ (x\\ge0)$","$x$ 가 커지면 $f(x)$ 는 증가하며 점근선 $y=1$ 에 가까워지지만 $1$ 이 되지는 않는다"],"설명":"$x\\ge0$ 에서 $f$ 는 증가하고 $f(0)=-1$ 에서 출발해 $y=1$ 에 한없이 가까워질 뿐이다. 가장 큰 값이 없으므로 최댓값이 존재하지 않아 ㄱ 은 거짓이다.","확인":null,"스킬":"T3"},{"제목":"ㄴ 의 참거짓 판정","힌트":"$x=-1$ 의 왼쪽과 오른쪽에서 $x\\to-1$ 일 때 $f(x)$ 는 각각 어디로 가는가?","식":["$x\\to-1^-$ 이면 $f(x)\\to+\\infty$","$x\\to-1^+$ 이면 $f(x)\\to-\\infty$"],"설명":"$x<-1$ 에서 $x\\to-1$ 이면 $-\\frac{2}{x+1}\\to+\\infty$ 이므로 $x<0$, $y>0$ 인 부분이 있어 제$2$사분면을 지난다. $-1<x<0$ 에서 $x\\to-1$ 이면 $-\\frac{2}{x+1}\\to-\\infty$ 이므로 $x<0$, $y<0$ 인 부분이 있어 제$3$사분면을 지난다. 이는 $k$ 의 값과 관계없으므로 ㄴ 은 참이다.","확인":null,"스킬":"T4"},{"제목":"ㄷ 의 범위 구하고 정답 고르기","고비":true,"힌트":"$x>0$ 에서 $f(x)$ 가 음수와 양수를 모두 가지려면 $f(0)$ 과 $k$ 의 부호는?","식":["$x>0$ 에서 $k-2<f(x)<k$","$k-2<0<k \\Rightarrow 0<k<2$"],"설명":"$x>0$ 에서 $f$ 는 증가하며 $f(0)=k-2$ 에서 출발해 $k$ 에 한없이 가까워진다. 제$4$사분면을 지나려면 $k-2<0$, 제$1$사분면을 지나려면 $k>0$ 이어야 한다. 제$2$, $3$사분면은 항상 지나므로 네 사분면을 모두 지날 조건은 $0<k<2$ 이고 ㄷ 은 참이다. 따라서 옳은 것은 ㄴ, ㄷ 이다.","확인":null,"스킬":"T3"}]},"ns-7b6d089d127d":{"길":"P, Q 가 y=x 에 대칭임을 이용해 밑변 PQ 를 구하고 좌표로 k 를 찾는다","단계":[{"제목":"밑변 PQ 의 길이 구하기","힌트":"$\\overline{\\mathrm{PQ}}$ 를 밑변으로 보면 높이는 원점에서 직선까지의 거리이다. 그 값은?","식":["$h=\\frac{|0+0-8|}{\\sqrt{1^2+1^2}}=4\\sqrt{2}$","$\\frac{1}{2}\\times4\\sqrt{2}\\times\\overline{\\mathrm{PQ}}=20 \\Rightarrow \\overline{\\mathrm{PQ}}=5\\sqrt{2}$"],"설명":"$\\mathrm{P}$, $\\mathrm{Q}$ 는 직선 $x+y-8=0$ 위의 점이므로 삼각형 $\\mathrm{OPQ}$ 의 높이는 원점과 이 직선 사이의 거리 $4\\sqrt{2}$ 이다. 넓이가 $20$ 이므로 $\\overline{\\mathrm{PQ}}=5\\sqrt{2}$ 이다.","확인":null,"스킬":"G10"},{"제목":"P, Q 의 좌표 관계 세우기","힌트":"$\\mathrm{P}$, $\\mathrm{Q}$ 는 $y=x$ 에 대하여 어떤 관계이고, 직선 위에 있다는 조건을 쓰면?","식":["$\\mathrm{P}\\left(a,\\frac{k}{a}\\right),\\ \\mathrm{Q}\\left(\\frac{k}{a},a\\right)$","$a+\\frac{k}{a}=8$"],"설명":"$y=\\frac{k}{x}$ 는 $y=x$ 에 대하여 대칭이고 직선 $y=-x+8$ 은 $y=x$ 에 수직이므로 두 교점 $\\mathrm{P}$, $\\mathrm{Q}$ 도 $y=x$ 에 대하여 대칭이다. $\\mathrm{P}$ 가 직선 위의 점이므로 $\\frac{k}{a}=-a+8$, 즉 $a+\\frac{k}{a}=8$ 이다.","확인":null,"스킬":"T2"},{"제목":"P 의 x 좌표 a 구하기","고비":true,"힌트":"$\\overline{\\mathrm{PQ}}=\\sqrt{2}\\left(a-\\frac{k}{a}\\right)$ 에 $\\frac{k}{a}=8-a$ 를 넣으면?","식":["$\\overline{\\mathrm{PQ}}=\\sqrt{2}\\,(2a-8)=5\\sqrt{2}$","$a=\\frac{13}{2}$"],"설명":"그림에서 $\\mathrm{P}$ 는 $\\mathrm{Q}$ 의 오른쪽 아래에 있으므로 $a>\\frac{k}{a}$ 이다. $\\overline{\\mathrm{PQ}}=\\sqrt{2}\\left(a-\\frac{k}{a}\\right)=\\sqrt{2}\\{a-(8-a)\\}=\\sqrt{2}(2a-8)$ 이다. $\\sqrt{2}(2a-8)=5\\sqrt{2}$ 에서 $2a-8=5$ 이므로 $a=\\frac{13}{2}$ 이다.","확인":"13/2","스킬":"T2"},{"제목":"k 의 값 구하기","힌트":"$\\frac{k}{a}=8-a$ 에 $a=\\frac{13}{2}$ 를 넣으면 $k$ 는?","식":["$\\frac{k}{a}=8-\\frac{13}{2}=\\frac{3}{2}$","$k=\\frac{13}{2}\\times\\frac{3}{2}=\\frac{39}{4}$"],"설명":"$\\frac{k}{a}=8-a=\\frac{3}{2}$ 이므로 $k=a\\times\\frac{3}{2}=\\frac{13}{2}\\times\\frac{3}{2}=\\frac{39}{4}$ 이다.","확인":"39/4","스킬":"G1"}]},"ns-83345e0c5dba":{"길":"점근선 교점과 원의 중심을 평행이동으로 맞춰 ㄱ, ㄴ 을 계산하고 ㄷ 은 교점 수를 따진다","단계":[{"제목":"ㄱ 의 참거짓 판정","힌트":"$f(x)=\\frac{4}{x-t}+2t+3$ 의 두 점근선의 교점의 좌표는?","식":["점근선 $x=t,\\ y=2t+3$","교점 $(t,\\ 2t+3)$ 은 $y=2x+3$ 위의 점"],"설명":"점근선은 $x=t$, $y=2t+3$ 이므로 교점은 $(t,\\,2t+3)$ 이다. 이 점의 $y$ 좌표가 $x$ 좌표의 $2$ 배에 $3$ 을 더한 값이므로 $y=2x+3$ 위에 있다. ㄱ 은 참이다.","확인":null,"스킬":"T4"},{"제목":"ㄴ 의 참거짓 판정","힌트":"$t=-3$ 일 때 $\\frac{4}{x+3}-3=x$ 를 풀면 두 점의 $x$ 좌표는?","식":["$\\frac{4}{x+3}-3=x \\Rightarrow (x+3)^2=4$","$(-1,-1),\\ (-5,-5)$, 거리 $4\\sqrt{2}$"],"설명":"$t=-3$ 이면 $f(x)=\\frac{4}{x+3}-3$ 이다. $x+3=\\frac{4}{x+3}$ 에서 $(x+3)^2=4$ 이므로 $x=-1$ 또는 $x=-5$ 이다. 두 점 $(-1,-1)$, $(-5,-5)$ 사이의 거리는 $\\sqrt{16+16}=4\\sqrt{2}$ 이므로 $2\\sqrt{2}$ 가 아니다. ㄴ 은 거짓이다.","확인":null,"스킬":"G1"},{"제목":"평행이동으로 원의 중심을 원점에 두기","힌트":"$u=x-t$, $v=y-t^2$ 으로 놓으면 곡선은 $v=\\frac{4}{u}+s$ 꼴이다. $s$ 의 최댓값은?","식":["$v=\\frac{4}{u}+s,\\quad s=2t+3-t^2=-(t-1)^2+4$","원 $u^2+v^2=8$"],"설명":"$y-t^2=\\frac{4}{x-t}+2t+3-t^2$ 이므로 $v=\\frac{4}{u}+s$ 이고 $s=-(t-1)^2+4$ 이다. 원은 $u^2+v^2=8$ 로 고정되고 쌍곡선만 $v$ 방향으로 $s$ 만큼 움직인다. $s$ 의 최댓값은 $t=1$ 일 때 $4$ 이다.","확인":"4","스킬":"G4"},{"제목":"교점이 놓이는 가지 정하기","힌트":"$u^2+v^2=8$ 과 $uv=4+su$ 로 $(u-v)^2$ 을 구하면?","식":["$(u-v)^2=8-2(4+su)=-2su$","$su\\le0$"],"설명":"$v=\\frac{4}{u}+s$ 에서 $uv=4+su$ 이다. 원의 식과 합치면 $(u-v)^2=-2su\\ge0$ 이므로 $su\\le0$ 이다. 따라서 $s>0$ 이면 $u<0$ 인 가지에서, $s<0$ 이면 $u>0$ 인 가지에서만 교점이 생긴다. $s=0$ 이면 $u=v$ 이고 $uv=4$ 이므로 $(2,2)$, $(-2,-2)$ 두 점이다.","확인":null,"스킬":"C2"},{"제목":"한쪽 가지의 교점 수 세고 정답 고르기","고비":true,"힌트":"$s<0$ 일 때 $u>0$ 가지는 원 밖에서 출발해 원 안을 지나는가?","식":["$u\\to0+$ 이면 $v\\to+\\infty$, $u\\to\\infty$ 이면 $v\\to s$ — 모두 원 밖","원 안의 점: $-4<s<0$ 이면 $(2,\\,2+s)$, $s\\le-4$ 이면 $\\left(\\frac{4}{|s|},\\,0\\right)$"],"설명":"$s<0$ 이면 $u>0$ 가지는 $u\\to0+$ 에서 원의 위쪽 밖에서 출발하고 $u\\to\\infty$ 에서는 원의 오른쪽 밖으로 간다. $-4<s<0$ 이면 점 $(2,\\,2+s)$ 가, $s\\le-4$ 이면 점 $\\left(\\frac{4}{|s|},\\,0\\right)$ 가 곡선 위에 있으면서 원 안에 있으므로 곡선은 원 안으로 들어갔다 나오며 교점이 $2$개이다. 연립한 식 $u^4+(s^2-8)u^2+8su+16=0$ 의 양의 실근은 부호 변화가 $2$번이라 $2$개를 넘지 않는다. $s>0$ 이면 원점 대칭인 같은 상황이므로 $2$개이고, 모든 $t$ 에서 $n(A\\cap B)=2$ 이다. 따라서 ㄷ 도 참이고, 옳은 것은 ㄱ, ㄷ 이다.","확인":null,"스킬":"C10"}]},"ns-8a93180cb837":{"길":"g 가 일대일대응이 되도록 x<k 조각의 치역을 정해 점근선으로 a, b 를 구한다","단계":[{"제목":"역함수와 k 구하기","힌트":"$x\\ge2$ 에서 $f$ 의 치역은 $y\\ge$ 얼마인가?","식":["$f(x)=(x-2)^2+3\\ (x\\ge2)$, 치역 $y\\ge3$","$f^{-1}(x)=2+\\sqrt{x-3}\\ (x\\ge3)$"],"설명":"$x\\ge2$ 에서 $f$ 는 증가하고 $f(2)=3$ 이므로 치역은 $y\\ge3$ 이고, 이것이 $f^{-1}$ 의 정의역 $x\\ge k$ 이다. $y=(x-2)^2+3$ 에서 $x=2+\\sqrt{y-3}$ 이므로 $f^{-1}(x)=2+\\sqrt{x-3}$ 이고 $k=3$ 이다.","확인":"3","스킬":"T1"},{"제목":"x≥k 조각의 치역 구하기","힌트":"$x\\ge3$ 에서 $g(x)=f^{-1}(x)+2$ 의 최솟값은?","식":["$g(x)=4+\\sqrt{x-3}\\ (x\\ge3)$","치역 $y\\ge4$"],"설명":"$g(x)=2+\\sqrt{x-3}+2=4+\\sqrt{x-3}$ 이고 $x=3$ 에서 최솟값을 갖고 한없이 커진다. 따라서 이 조각의 치역은 $y\\ge4$ 이다.","확인":"4","스킬":"T3"},{"제목":"x<k 조각의 치역을 정하고 a 구하기","고비":true,"힌트":"$x<3$ 조각이 아래로 한없이 내려가려면 $x=3$ 에서 분모 $ax+2$ 는 어떤 값이어야 하는가?","식":["$x<3$ 조각의 치역은 $y<4$ 전체","$3a+2=0,\\ a=-\\frac{2}{3}$"],"설명":"$g$ 가 일대일대응이면 $x<3$ 조각은 나머지 값 $y<4$ 전체를 한 번씩 가져야 한다. 이 조각은 $x\\to-\\infty$ 에서 $\\frac{b}{a}$ 로 수렴할 뿐이므로, 아래로 한없이 내려가려면 $x\\to3^-$ 에서 분모가 $0$ 이어야 한다. 즉 $x=3$ 이 세로 점근선이므로 $3a+2=0$ 이다.","확인":"-2/3","스킬":"T4"},{"제목":"가로 점근선으로 b 구하기","힌트":"$x\\to-\\infty$ 일 때 $\\frac{bx+3}{ax+2}$ 가 가까워지는 값 $\\frac{b}{a}$ 는 얼마여야 하는가?","식":["$\\frac{b}{a}=4$","$b=4a=-\\frac{8}{3}$"],"설명":"$x<3$ 조각의 치역이 $y<4$ 이므로 가로 점근선은 $y=\\frac{b}{a}=4$ 이다. 따라서 $b=4a=-\\frac{8}{3}$ 이고, $2b-3a=-\\frac{10}{3}\\ne0$ 이어서 조건에 맞는다.","확인":"-8/3","스킬":"T4"},{"제목":"g 의 식과 k+a+b 구하기","힌트":"$a$, $b$ 를 넣어 $\\frac{bx+3}{ax+2}$ 를 정리하면?","식":["$g(x)=\\frac{-8x+9}{-2x+6}=4+\\frac{15}{2x-6}\\ (x<3)$","$k+a+b=3-\\frac{2}{3}-\\frac{8}{3}=-\\frac{1}{3}$"],"설명":"분자·분모에 $3$ 을 곱하면 $\\frac{-8x+9}{-2x+6}=\\frac{8x-9}{2x-6}=4+\\frac{15}{2x-6}$ 이다. $x<3$ 에서 $2x-6<0$ 이므로 $g(x)<4$ 이고, $x\\to3^-$ 에서 $-\\infty$ 로 가므로 $y<4$ 전체를 한 번씩 갖는다. 세 상수의 합은 $-\\frac{1}{3}$ 이다.","확인":"-1/3","스킬":"T4"},{"제목":"역함수의 값 구하기","힌트":"$-1<4$ 이므로 $g^{-1}(-1)$ 은 어느 조각에서 구하는가? 그 값은?","식":["$g^{-1}(5):\\ 4+\\sqrt{x-3}=5 \\Rightarrow x=4$","$g^{-1}(-1):\\ 4+\\frac{15}{2x-6}=-1 \\Rightarrow x=\\frac{3}{2}$"],"설명":"$5\\ge4$ 이므로 $x\\ge3$ 조각에서 $\\sqrt{x-3}=1$, $x=4$ 이다. $-1<4$ 이므로 $x<3$ 조각에서 $\\frac{15}{2x-6}=-5$, $2x-6=-3$ 이고 $x=\\frac{3}{2}$ 이며 $\\frac{3}{2}<3$ 을 만족한다.","확인":"3/2","스킬":"T1"},{"제목":"합을 구해 p+q 구하기","힌트":"$-\\frac{1}{3}+4+\\frac{3}{2}$ 를 기약분수 $\\frac{q}{p}$ 로 나타내면 $p+q$ 는?","식":["$-\\frac{1}{3}+4+\\frac{3}{2}=\\frac{31}{6}$","$p+q=6+31=37$"],"설명":"통분하면 $\\frac{-2+24+9}{6}=\\frac{31}{6}$ 이고 $31$ 과 $6$ 은 서로소이다. 따라서 $p=6$, $q=31$ 이고 $p+q=37$ 이다.","확인":"37","스킬":"T1"}]},"ns-ac99b40cc74d":{"길":"두 넓이가 같다는 식으로 f(x)를 구하고 증가함수의 양 끝값으로 최대·최소를 찾는다","단계":[{"제목":"두 도형의 넓이 식 세우기","힌트":"삼각형 $\\mathrm{BCE}$ 는 밑변이 $\\overline{\\mathrm{BC}}=x$ 일 때 높이는?","식":["$\\square\\mathrm{ABCD}=\\frac{1}{2}(2+x)f(x)$","$\\triangle\\mathrm{BCE}=\\frac{1}{2}\\times x\\times2=x$"],"설명":"사다리꼴의 넓이는 (윗변+아랫변)×높이÷$2$ 이다. 삼각형 $\\mathrm{BCE}$ 는 밑변이 $x$, 높이가 $2$ 이다.","확인":null,"스킬":"S8"},{"제목":"f(x)를 구하고 꼴 바꾸기","고비":true,"힌트":"두 넓이가 같다는 식에서 $f(x)$ 를 구하면?","식":["$\\frac{1}{2}(2+x)f(x)=x \\Rightarrow f(x)=\\frac{2x}{x+2}$","$f(x)=2-\\frac{4}{x+2}$"],"설명":"양변에 $2$ 를 곱하면 $(x+2)f(x)=2x$ 이다. $\\frac{2x}{x+2}=\\frac{2(x+2)-4}{x+2}=2-\\frac{4}{x+2}$ 이므로 $x>-2$ 에서 $f$ 는 증가한다.","확인":null,"스킬":"T4"},{"제목":"구간의 양 끝값 구하기","힌트":"$x=1$ 과 $x=4$ 의 함숫값 중 작은 값 $m$ 은?","식":["$f(1)=\\frac{2}{3},\\ f(4)=\\frac{8}{6}=\\frac{4}{3}$","$m=\\frac{2}{3},\\ M=\\frac{4}{3}$"],"설명":"$f$ 는 증가하므로 $1\\le x\\le4$ 에서 $x=1$ 일 때 최솟값, $x=4$ 일 때 최댓값을 갖는다.","확인":"2/3","스킬":"T3"},{"제목":"M+m 구하기","힌트":"$M=\\frac{4}{3}$, $m=\\frac{2}{3}$ 일 때 $M+m$ 은?","식":["$M+m=\\frac{4}{3}+\\frac{2}{3}=2$"],"설명":"두 값을 더하면 $2$ 이다.","확인":"2","스킬":"T3"}]},"ns-ade92c86cd68":{"길":"PQ 를 t 로 나타내 t-1/2 를 한 덩어리로 두고 산술·기하평균을 쓴다","단계":[{"제목":"선분 PQ 의 길이 식 세우기","힌트":"$\\mathrm{P}$ 와 $\\mathrm{Q}$ 는 $x$ 좌표가 같다. $y$ 좌표의 차는?","식":["$\\mathrm{P}\\left(t,\\frac{2}{2t-1}\\right),\\ \\mathrm{Q}(t,-t)$","$\\overline{\\mathrm{PQ}}=\\frac{2}{2t-1}-(-t)=\\frac{2}{2t-1}+t$"],"설명":"두 점의 $x$ 좌표가 $t$ 로 같으므로 길이는 $y$ 좌표의 차이다. $\\mathrm{P}$ 는 $x$ 축 위쪽, $\\mathrm{Q}$ 는 아래쪽에 있으므로 $\\mathrm{P}$ 의 $y$ 좌표에서 $\\mathrm{Q}$ 의 $y$ 좌표를 뺀다.","확인":null,"스킬":"C7"},{"제목":"t-1/2 를 한 덩어리로 묶기","고비":true,"힌트":"분모 $2t-1$ 을 $2\\left(t-\\frac{1}{2}\\right)$ 로 쓰고 $u=t-\\frac{1}{2}$ 로 놓으면?","식":["$\\frac{2}{2t-1}=\\frac{1}{t-\\frac{1}{2}}$","$\\overline{\\mathrm{PQ}}=u+\\frac{1}{u}+\\frac{1}{2}\\ (u>0)$"],"설명":"$t=u+\\frac{1}{2}$ 이므로 $\\overline{\\mathrm{PQ}}=\\frac{1}{u}+u+\\frac{1}{2}$ 이다. $t>\\frac{1}{2}$ 이므로 $u>0$ 이다.","확인":null,"스킬":"A1"},{"제목":"산술·기하평균 적용하기","힌트":"$u>0$ 일 때 $u+\\frac{1}{u}$ 의 최솟값은?","식":["$u+\\frac{1}{u}\\ge2\\sqrt{u\\times\\frac{1}{u}}=2$","등호는 $u=1$ 일 때"],"설명":"산술평균과 기하평균의 관계로 $u+\\frac{1}{u}\\ge2$ 이고, 등호는 $u=\\frac{1}{u}$, 즉 $u=1$ 일 때 성립한다.","확인":"2","스킬":"A7"},{"제목":"최솟값 구하기","힌트":"$u=1$ ($t=\\frac{3}{2}$) 일 때 $\\overline{\\mathrm{PQ}}$ 는?","식":["$\\overline{\\mathrm{PQ}}\\ge2+\\frac{1}{2}=\\frac{5}{2}$"],"설명":"$\\overline{\\mathrm{PQ}}=u+\\frac{1}{u}+\\frac{1}{2}\\ge2+\\frac{1}{2}$ 이고 등호가 성립하는 $t=\\frac{3}{2}$ 가 $t>\\frac{1}{2}$ 를 만족하므로 최솟값은 $\\frac{5}{2}$ 이다.","확인":"5/2","스킬":"A7"}]},"ns-affe01743c3b":{"길":"P 의 좌표로 두 수선의 길이를 나타내고 곱이 일정함을 이용해 산술·기하평균을 쓴다","단계":[{"제목":"두 수선의 길이 나타내기","힌트":"$\\mathrm{P}\\left(t,\\frac{8}{t-1}\\right)$ 에서 점근선 $x=1$ 까지의 거리와 $x$ 축까지의 거리는?","식":["$\\mathrm{P}\\left(t,\\frac{8}{t-1}\\right)\\ (t>1)$","$\\overline{\\mathrm{PR}}=t-1,\\ \\overline{\\mathrm{PQ}}=\\frac{8}{t-1}$"],"설명":"점근선은 $x=1$ 과 $y=0$ 이다. $\\mathrm{R}$ 은 $x=1$ 위, $\\mathrm{Q}$ 는 $x$ 축 위에 있으므로 $\\overline{\\mathrm{PR}}$ 은 $x$ 좌표의 차 $t-1$, $\\overline{\\mathrm{PQ}}$ 는 $y$ 좌표 $\\frac{8}{t-1}$ 이다.","확인":null,"스킬":"T4"},{"제목":"합의 식 세우기","고비":true,"힌트":"$\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{PR}}$ 에서 두 항의 곱은 $t$ 에 따라 변하는가?","식":["$\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{PR}}=(t-1)+\\frac{8}{t-1}$","곱 $(t-1)\\times\\frac{8}{t-1}$ 은 $t$ 에 관계없이 일정"],"설명":"두 항 $t-1$ 과 $\\frac{8}{t-1}$ 은 모두 양수이고 곱이 일정하다. 이런 꼴의 합에는 산술·기하평균을 쓴다.","확인":null,"스킬":"A7"},{"제목":"산술·기하평균으로 최솟값 구하기","힌트":"두 양수의 합은 곱의 제곱근의 몇 배 이상인가?","식":["$(t-1)+\\frac{8}{t-1}\\ge2\\sqrt{8}=4\\sqrt{2}$","등호는 $(t-1)^2=8$ 일 때"],"설명":"$t-1>0$ 이므로 산술·기하평균에 의해 $(t-1)+\\frac{8}{t-1}\\ge2\\sqrt{8}=4\\sqrt{2}$ 이다. 등호는 $t-1=\\frac{8}{t-1}$, 즉 $t=1+2\\sqrt{2}$ 일 때 성립하므로 최솟값은 $4\\sqrt{2}$ 이다.","확인":null,"스킬":"A7"}]},"ns-c72458a33c7f":{"길":"시작점과 지나는 점으로 a, b, c 를 읽고 점근선과 두 절편으로 지나는 사분면을 센다","단계":[{"제목":"시작점으로 식 세우기","힌트":"시작점이 $(-2,-1)$ 이면 $ax+b$ 는 $x=-2$ 에서 $0$ 이다. 이때 $b$ 는 $a$ 로 어떻게 나타나는가?","식":["$ax+b=a(x+2)$","$y=\\sqrt{a(x+2)}-1,\\ b=2a,\\ c=-1$"],"설명":"근호 안이 $0$ 이 되는 $x=-2$ 가 시작점의 $x$ 좌표이므로 $ax+b=a(x+2)$ 이다. 시작점의 $y$ 좌표가 $c$ 이므로 $c=-1$ 이다.","확인":null,"스킬":"G4"},{"제목":"지나는 점으로 a, b 구하기","고비":true,"힌트":"$(0,1)$ 을 대입하면 $a$ 는? 그때 $b$ 의 값은?","식":["$1=\\sqrt{2a}-1 \\Rightarrow \\sqrt{2a}=2 \\Rightarrow a=2$","$b=2a=4$"],"설명":"그래프가 $(0,1)$ 을 지나므로 $1=\\sqrt{2a}-1$ 이다. $\\sqrt{2a}=2$ 에서 $a=2$ 이고, $b=2a=4$ 이다.","확인":"4","스킬":"G1"},{"제목":"유리함수의 식과 점근선 구하기","힌트":"$y=\\frac{b}{x+a}+c$ 에 $a=2$, $b=4$, $c=-1$ 을 넣으면 점근선은?","식":["$y=\\frac{4}{x+2}-1$","점근선 $x=-2,\\ y=-1$"],"설명":"$y=\\frac{b}{x+a}+c$ 의 점근선은 $x=-a$, $y=c$ 이므로 $x=-2$, $y=-1$ 이다.","확인":null,"스킬":"T4"},{"제목":"지나는 사분면 판정하기","힌트":"$y$ 절편과 $x$ 절편은 각각 얼마인가?","식":["$x=0$ 에서 $y=1$, $y=0$ 에서 $x=2$","$x>-2$ 쪽은 제$1$, $2$, $4$사분면, $x<-2$ 쪽은 제$3$사분면"],"설명":"$-2<x<0$ 에서 $\\frac{4}{x+2}>2$ 이므로 $y>1$ 이어서 제$2$사분면이다. $0<x<2$ 에서 $y>0$ 이므로 제$1$사분면, $x>2$ 에서 $y<0$ 이므로 제$4$사분면이다. $x<-2$ 에서는 $\\frac{4}{x+2}<0$ 이므로 $y<-1$ 이어서 제$3$사분면이다. 따라서 네 사분면을 모두 지난다.","확인":null,"스킬":"T4"}]},"ns-cbc45f9b01e7":{"길":"R 이 Q 의 원점 대칭점임을 쓰고 근과 계수의 관계와 넓이 조건으로 기울기를 구한다","단계":[{"제목":"점 Q, P, R 의 좌표 놓기","힌트":"곡선이 원점에 대하여 대칭이면 $\\mathrm{Q}\\left(\\alpha,\\frac{2}{\\alpha}\\right)$ 와 직선 $\\mathrm{QO}$ 위의 다른 교점 $\\mathrm{R}$ 의 좌표는?","식":["$\\mathrm{Q}\\left(\\alpha,\\frac{2}{\\alpha}\\right),\\ \\mathrm{P}\\left(\\beta,\\frac{2}{\\beta}\\right),\\ \\mathrm{R}\\left(-\\alpha,-\\frac{2}{\\alpha}\\right)$","$\\alpha<0<\\beta$"],"설명":"$y=\\frac{2}{x}$ 의 그래프는 원점에 대하여 대칭이므로 원점을 지나는 직선이 곡선과 만나는 두 점은 원점에 대하여 대칭이다. 따라서 $\\mathrm{R}$ 은 $\\mathrm{Q}$ 의 원점 대칭점이다. 그림에서 $\\mathrm{Q}$ 는 제$3$사분면, $\\mathrm{P}$ 는 제$1$사분면에 있으므로 $\\alpha<0<\\beta$ 이다.","확인":null,"스킬":"T2"},{"제목":"직선 l 과 곡선의 교점 조건 세우기","힌트":"$y=m(x-4)$ 와 $y=\\frac{2}{x}$ 를 연립한 이차방정식의 두 근의 합과 곱은?","식":["$\\frac{2}{x}=m(x-4) \\Rightarrow mx^2-4mx-2=0$","$\\alpha+\\beta=4,\\ \\alpha\\beta=-\\frac{2}{m}$"],"설명":"직선 $l$ 은 $(4,0)$ 을 지나므로 $y=m(x-4)$ 이다. 연립하여 정리한 이차방정식의 두 근이 $\\alpha$, $\\beta$ 이므로 근과 계수의 관계에서 $\\alpha+\\beta=4$, $\\alpha\\beta=-\\frac{2}{m}$ 이다.","확인":null,"스킬":"G1"},{"제목":"넓이 조건을 식으로 정리하기","고비":true,"힌트":"삼각형 $\\mathrm{PQR}$ 의 넓이를 $\\alpha$, $\\beta$ 로 나타내고 $\\alpha+\\beta=4$ 를 쓰면 $\\alpha-\\beta$ 와 $\\alpha\\beta$ 의 관계는?","식":["$\\triangle\\mathrm{PQR}=\\frac{2(\\alpha^2-\\beta^2)}{\\alpha\\beta}=\\frac{8(\\alpha-\\beta)}{\\alpha\\beta}=8$","$\\alpha-\\beta=\\alpha\\beta$"],"설명":"세 점 $\\mathrm{P}$, $\\mathrm{Q}$, $\\mathrm{R}$ 의 좌표로 넓이를 구하면 $\\frac{1}{2}\\left|\\frac{4\\alpha}{\\beta}-\\frac{4\\beta}{\\alpha}\\right|$ 이고, $\\alpha<0<\\beta$ 이므로 $\\frac{2(\\alpha^2-\\beta^2)}{\\alpha\\beta}$ 이다. $\\alpha+\\beta=4$ 를 넣으면 $\\frac{8(\\alpha-\\beta)}{\\alpha\\beta}=8$ 이므로 $\\alpha-\\beta=\\alpha\\beta$ 이다.","확인":null,"스킬":"G10"},{"제목":"αβ 의 값 구하기","힌트":"$(\\alpha-\\beta)^2+4\\alpha\\beta=(\\alpha+\\beta)^2$ 에 $\\alpha-\\beta=\\alpha\\beta$ 를 넣으면 $\\alpha\\beta$ 가 만족하는 식은?","식":["$(\\alpha\\beta)^2+4\\alpha\\beta=16$","$\\alpha\\beta=-2-2\\sqrt{5}$"],"설명":"$(\\alpha\\beta)^2+4\\alpha\\beta-16=0$ 에서 $\\alpha\\beta=-2\\pm2\\sqrt{5}$ 이다. $\\alpha<0<\\beta$ 에서 $\\alpha\\beta<0$ 이므로 $\\alpha\\beta=-2-2\\sqrt{5}$ 이다.","확인":null,"스킬":"A2"},{"제목":"직선 l 의 기울기 구하기","힌트":"$m=-\\frac{2}{\\alpha\\beta}$ 에 $\\alpha\\beta$ 를 넣고 분모를 유리화하면?","식":["$m=-\\frac{2}{-2-2\\sqrt{5}}=\\frac{1}{1+\\sqrt{5}}=\\frac{-1+\\sqrt{5}}{4}$"],"설명":"$m=-\\frac{2}{\\alpha\\beta}=\\frac{1}{1+\\sqrt{5}}$ 이고, 분모와 분자에 $\\sqrt{5}-1$ 을 곱하면 $\\frac{\\sqrt{5}-1}{4}$ 이다.","확인":null,"스킬":"G3"}]},"ns-d662391feff8":{"길":"점근선 교점으로 식을 세우고 y절편을 넣어 통분하면 a, b, c 가 보인다","단계":[{"제목":"점근선으로 식 세우기","힌트":"점근선이 $x=-1$, $y=3$ 인 유리함수는 어떤 꼴인가?","식":["$y=\\frac{k}{x+1}+3$"],"설명":"점근선이 $x=-1$, $y=3$ 이므로 $y=\\frac{k}{x-(-1)}+3=\\frac{k}{x+1}+3$ 꼴이다.","확인":null,"스킬":"T4"},{"제목":"y 절편으로 k 를 구해 a, b, c 읽기","고비":true,"힌트":"통분하여 $\\frac{ax+b}{x+c}$ 꼴로 만들면 $c$ 는?","식":["$2=\\frac{k}{0+1}+3 \\Rightarrow k=-1$","$y=\\frac{-1}{x+1}+3=\\frac{3x+2}{x+1}$","$a=3,\\ b=2,\\ c=1$"],"설명":"$y$ 절편이 $2$ 이므로 $x=0$, $y=2$ 를 넣으면 $2=k+3$ 에서 $k=-1$ 이다. 통분하면 $\\frac{-1}{x+1}+3=\\frac{3(x+1)-1}{x+1}=\\frac{3x+2}{x+1}$ 이므로 $a=3$, $b=2$, $c=1$ 이다.","확인":"1","스킬":"A3"},{"제목":"ab-c 구하기","힌트":"$a=3$, $b=2$, $c=1$ 일 때 $ab-c$ 는?","식":["$ab-c=3\\times2-1=5$"],"설명":"$ab=6$ 에서 $c=1$ 을 빼면 $5$ 이다.","확인":"5","스킬":"T4"}]},"ns-da8c121afd36":{"길":"A 를 (t, 2/t)로 두고 B, C 의 좌표로 직각삼각형의 넓이를 구하면 t 가 약분된다","단계":[{"제목":"점 B, C 의 좌표 구하기","힌트":"점 $\\mathrm{A}\\left(t,\\frac{2}{t}\\right)$ 와 $y$ 좌표가 같은 $y=\\frac{k}{x}$ 위의 점 $\\mathrm{B}$ 의 $x$ 좌표는?","식":["$\\mathrm{A}\\left(t,\\frac{2}{t}\\right)$","$\\mathrm{B}\\left(\\frac{kt}{2},\\frac{2}{t}\\right),\\ \\mathrm{C}\\left(t,\\frac{k}{t}\\right)$"],"설명":"$\\mathrm{B}$ 는 $x$ 축에 평행한 직선 $y=\\frac{2}{t}$ 위에 있으므로 $\\frac{2}{t}=\\frac{k}{x}$ 에서 $x=\\frac{kt}{2}$ 이다. $\\mathrm{C}$ 는 $y$ 축에 평행한 직선 $x=t$ 위에 있으므로 $y=\\frac{k}{t}$ 이다.","확인":null,"스킬":"G1"},{"제목":"직각을 낀 두 변의 길이 구하기","힌트":"$\\overline{\\mathrm{AB}}$ 와 $\\overline{\\mathrm{AC}}$ 를 좌표의 차로 나타내면?","식":["$\\overline{\\mathrm{AB}}=\\frac{kt}{2}-t=\\frac{t(k-2)}{2}$","$\\overline{\\mathrm{AC}}=\\frac{k}{t}-\\frac{2}{t}=\\frac{k-2}{t}$"],"설명":"$\\mathrm{AB}$ 는 $x$ 축에, $\\mathrm{AC}$ 는 $y$ 축에 평행하므로 삼각형 $\\mathrm{ABC}$ 는 $\\mathrm{A}$ 에서 직각이다. $k>2$ 이므로 두 길이는 모두 양수이다.","확인":null,"스킬":"S4"},{"제목":"넓이 식에서 t 약분하기","고비":true,"힌트":"$\\frac{1}{2}\\times\\overline{\\mathrm{AB}}\\times\\overline{\\mathrm{AC}}=16$ 에서 $t$ 가 약분되면 $(k-2)^2$ 의 값은?","식":["$\\frac{1}{2}\\times\\frac{t(k-2)}{2}\\times\\frac{k-2}{t}=\\frac{(k-2)^2}{4}=16$","$(k-2)^2=64$"],"설명":"두 길이를 곱하면 $t$ 가 약분되어 $\\frac{(k-2)^2}{4}$ 만 남는다. 이것이 $16$ 이므로 $(k-2)^2=64$ 이다.","확인":"64","스킬":"G10"},{"제목":"k 의 값 구하기","힌트":"$k>2$ 일 때 $k-2$ 는?","식":["$k-2=8$","$k=10$"],"설명":"$k>2$ 이므로 $k-2=8$ 이고 $k=10$ 이다.","확인":"10","스킬":"G10"}]},"ns-ed5cbbacd023":{"길":"그림의 점근선으로 a, b 를 정하고 원점을 지난다는 조건으로 k 를 구한다","단계":[{"제목":"점근선으로 a, b 읽기","고비":true,"힌트":"그림의 점근선 $x=2$, $y=1$ 을 $y=\\frac{k}{x-a}+b$ 의 점근선 $x=a$, $y=b$ 와 비교하면?","식":["$a=2,\\ b=1$"],"설명":"$y=\\frac{k}{x-a}+b$ 의 점근선은 $x=a$, $y=b$ 이다. 그림의 점근선이 $x=2$, $y=1$ 이므로 $a=2$, $b=1$ 이다.","확인":null,"스킬":"T4"},{"제목":"원점을 지나는 조건으로 k 구하기","힌트":"$(0,0)$ 을 $y=\\frac{k}{x-2}+1$ 에 대입하면 $k$ 는?","식":["$0=\\frac{k}{0-2}+1$","$k=2$"],"설명":"그래프가 원점을 지나므로 $0=\\frac{k}{-2}+1$ 이고, 이로부터 $k=2$ 이다.","확인":"2","스킬":"G1"},{"제목":"ab/k 의 값 구하기","힌트":"$a=2$, $b=1$, $k=2$ 일 때 $\\frac{ab}{k}$ 는?","식":["$\\frac{ab}{k}=\\frac{2\\times1}{2}=1$"],"설명":"$ab=2$ 를 $k=2$ 로 나누면 $1$ 이다.","확인":"1","스킬":"T4"}]},"ns-05a0a6a92f30":{"길":"g 와 역함수의 식을 세우고 역함수가 A 에서 A 로 가는 일대일대응이 될 끝점 조건을 쓴다","단계":[{"제목":"g(x)의 식 세우기","힌트":"끝점 $(5,2)$ 에서 왼쪽으로 뻗는 $y=p\\sqrt{5-x}+2$ 가 $(4,0)$ 을 지나면 $p$ 는?","식":["$g(x)=p\\sqrt{5-x}+2$","$0=p\\sqrt{5-4}+2 \\Rightarrow p=-2$"],"설명":"그래프의 끝점이 $(5,2)$ 이고 왼쪽으로 뻗으므로 $g(x)=p\\sqrt{5-x}+2$ 꼴이다. $(4,0)$ 을 지나므로 $p=-2$ 이고, $x$ 가 커질수록 $y$ 가 증가하는 그림과도 맞다.","확인":"-2","스킬":"G4"},{"제목":"역함수 구하기","힌트":"$y=-2\\sqrt{5-x}+2$ 에서 $x$ 를 $y$ 로 나타내면?","식":["$\\sqrt{5-x}=\\frac{2-y}{2},\\ 5-x=\\frac{(y-2)^2}{4}$","$g^{-1}(x)=-\\frac{1}{4}(x-2)^2+5\\ (x\\le2)$"],"설명":"$g$ 의 치역이 $y\\le2$ 이므로 $g^{-1}$ 의 정의역은 $x\\le2$ 이다. $x=5-\\frac{(y-2)^2}{4}$ 에서 $x$ 와 $y$ 를 서로 바꾼다.","확인":null,"스킬":"T1"},{"제목":"A 에서 A 로의 일대일대응 조건 세우기","고비":true,"힌트":"$g^{-1}$ 은 $x\\le2$ 에서 증가한다. $x\\le a$ 를 $y\\le a$ 로 보내려면 끝점 $x=a$ 의 함숫값은?","식":["$g^{-1}(a)=a,\\quad a\\le2$"],"설명":"$g^{-1}$ 은 증가하고 $x\\to-\\infty$ 에서 $-\\infty$ 로 가므로, $x\\le a$ 의 치역이 $y\\le a$ 가 되려면 끝점에서 $g^{-1}(a)=a$ 이어야 한다. 또 $A$ 가 $g^{-1}$ 의 정의역에 들어가려면 $a\\le2$ 이다.","확인":null,"스킬":"T7"},{"제목":"방정식을 풀어 a 구하기","힌트":"$-\\frac{1}{4}(a-2)^2+5=a$ 를 정리하면 $a^2$ 은?","식":["$-\\frac{1}{4}(a-2)^2+5=a \\Rightarrow a^2=16$","$a\\le2$ 이므로 $a=-4$"],"설명":"양변에 $4$ 를 곱하면 $-(a-2)^2+20=4a$ 이고, 정리하면 $-a^2+4a-4+20=4a$ 에서 $a^2=16$ 이다. $a\\le2$ 이므로 $a=-4$ 이다.","확인":"-4","스킬":"T7"}]},"ns-06dc7acd74c5":{"길":"정의역을 구해 f(x)를 제곱하고 근호 안 이차식의 범위로 최대·최소를 찾는다","단계":[{"제목":"정의역과 제곱식 구하기","고비":true,"힌트":"$f(x)$ 를 제곱하면 근호가 몇 개 남는가?","식":["$2\\le x\\le8$","$f(x)^2=6+2\\sqrt{(8-x)(x-2)}$"],"설명":"$8-x\\ge0$, $x-2\\ge0$ 에서 $2\\le x\\le8$ 이다. 제곱하면 $(8-x)+(x-2)=6$ 과 $2\\sqrt{(8-x)(x-2)}$ 가 남아 근호가 하나가 된다.","확인":null,"스킬":"A2"},{"제목":"근호 안 이차식의 범위 구하기","힌트":"$(8-x)(x-2)$ 의 최댓값은?","식":["$(8-x)(x-2)=-(x-5)^2+9$","$0\\le(8-x)(x-2)\\le9$"],"설명":"$-x^2+10x-16=-(x-5)^2+9$ 이므로 $x=5$ 에서 최댓값 $9$ 를 갖고, $x=2$, $8$ 에서 최솟값 $0$ 을 갖는다.","확인":"9","스킬":"A6"},{"제목":"최댓값 M 과 최솟값 m 구하기","힌트":"$f(x)^2$ 의 최댓값은?","식":["$6\\le f(x)^2\\le6+2\\times3=12$","$M=2\\sqrt{3},\\ m=\\sqrt{6}$"],"설명":"$f(x)^2=6+2\\sqrt{(8-x)(x-2)}$ 는 근호 안이 $0$ 일 때 최소 $6$, $9$ 일 때 최대 $6+2\\times3=12$ 이다. $f(x)>0$ 이므로 $M=\\sqrt{12}=2\\sqrt{3}$, $m=\\sqrt{6}$ 이다.","확인":"12","스킬":"T3"},{"제목":"m²/M 의 값 구하기","힌트":"$m^2=6$ 이고 $M=2\\sqrt{3}$ 일 때 $\\frac{m^2}{M}$ 은?","식":["$\\frac{m^2}{M}=\\frac{6}{2\\sqrt{3}}=\\sqrt{3}$"],"설명":"$\\frac{6}{2\\sqrt{3}}=\\frac{3}{\\sqrt{3}}=\\sqrt{3}$ 이다.","확인":null,"스킬":"A6"}]},"ns-0bddbd0785ba":{"길":"부등식을 직선과 무리함수 그래프의 위치 관계로 바꿔 b 는 끝점에서, a 는 접점에서 정한다","단계":[{"제목":"부등식을 그래프의 위치 관계로 바꾸기","힌트":"$bx\\le\\sqrt{x-2}$ 와 $\\sqrt{x-2}\\le ax$ 에서 직선은 곡선의 위와 아래 중 각각 어디에 있는가?","식":["$bx\\le\\sqrt{x-2}$: 직선 $y=bx$ 가 곡선 아래","$\\sqrt{x-2}\\le ax$: 직선 $y=ax$ 가 곡선 위"],"설명":"$x\\ge2$ 에서 $y=\\sqrt{x-2}$ 의 그래프는 점 $(2,0)$ 에서 시작해 오른쪽 위로 뻗는다. 원점을 지나는 직선 $y=bx$ 는 이 곡선보다 계속 아래에, $y=ax$ 는 계속 위에 있어야 한다.","확인":null,"스킬":"G6"},{"제목":"b 의 최댓값 M 구하기","힌트":"$x=2$ 에서 곡선의 값은 $0$ 이다. 직선 $y=bx$ 가 그 아래에 있으려면 $b$ 의 범위는?","식":["$x=2$ 에서 $2b\\le0 \\Rightarrow b\\le0$","$b=0$ 이면 $0\\le\\sqrt{x-2}$ 가 성립하므로 $M=0$"],"설명":"$b>0$ 이면 $x=2$ 에서 $bx=2b>0=\\sqrt{x-2}$ 이므로 성립하지 않는다. $b=0$ 이면 모든 $x\\ge2$ 에서 $0\\le\\sqrt{x-2}$ 이므로 $b$ 의 최댓값은 $0$ 이다.","확인":"0","스킬":"G6"},{"제목":"접할 때의 기울기로 a 의 최솟값 m 구하기","고비":true,"힌트":"$ax=\\sqrt{x-2}$ 의 양변을 제곱해 정리한 이차방정식이 중근을 가지려면 판별식은?","식":["$a^2x^2=x-2 \\Rightarrow a^2x^2-x+2=0$","$D=1-8a^2=0 \\Rightarrow a=\\frac{\\sqrt{2}}{4}$"],"설명":"기울기가 클수록 직선이 위로 올라가므로, 곡선이 직선 아래에 있게 되는 가장 작은 기울기는 접할 때이다. 양변을 제곱하면 $a^2x^2-x+2=0$ 이고 중근을 가질 조건 $D=1-8a^2=0$ 에서 $a=\\frac{\\sqrt{2}}{4}$ ($a>0$) 이다. 접점은 $x=4$ 로 $x\\ge2$ 에 속한다.","확인":null,"스킬":"G2"},{"제목":"(M-m)² 구하기","힌트":"$M=0$, $m=\\frac{\\sqrt{2}}{4}$ 일 때 $(M-m)^2$ 은?","식":["$(M-m)^2=\\left(0-\\frac{\\sqrt{2}}{4}\\right)^2=\\frac{1}{8}$"],"설명":"$\\left(\\frac{\\sqrt{2}}{4}\\right)^2=\\frac{2}{16}=\\frac{1}{8}$ 이다.","확인":"1/8","스킬":"G2"}]},"ns-228b82a908cd":{"길":"점선을 따라 같은 y, 같은 x 를 함수식에 차례로 넣어 A, B, C, D, Q 를 구한다","단계":[{"제목":"점 A, B 의 좌표 구하기","힌트":"점 $\\mathrm{A}$ 의 $y$ 좌표를 구한 뒤, 같은 높이에서 $y=\\sqrt{-2x}$ 위에 있는 점 $\\mathrm{B}$ 의 $x$ 좌표는?","식":["$\\mathrm{A}(2,\\ \\sqrt{2})$","$\\sqrt{-2x}=\\sqrt{2} \\Rightarrow x=-1,\\ \\mathrm{B}(-1,\\ \\sqrt{2})$"],"설명":"$\\mathrm{A}$ 는 $\\mathrm{P}(2,0)$ 에서 $y$ 축에 평행한 직선과 $y=\\sqrt{x}$ 의 교점이므로 $\\mathrm{A}(2,\\sqrt{2})$ 이다. $\\mathrm{B}$ 는 $\\mathrm{A}$ 에서 $x$ 축에 평행한 직선과 $y=\\sqrt{-2x}$ 의 교점이므로 $-2x=2$ 에서 $x=-1$ 이다.","확인":"-1","스킬":"C11"},{"제목":"점 C, D 의 좌표 구하기","고비":true,"힌트":"점 $\\mathrm{C}$ 의 $y$ 좌표를 구한 뒤, 같은 높이에서 $y=-\\sqrt{4x}$ 위에 있는 점 $\\mathrm{D}$ 의 $x$ 좌표는?","식":["$\\mathrm{C}(-1,\\ -\\sqrt{3})$","$-\\sqrt{4x}=-\\sqrt{3} \\Rightarrow x=\\frac{3}{4},\\ \\mathrm{D}\\left(\\frac{3}{4},\\ -\\sqrt{3}\\right)$"],"설명":"$\\mathrm{C}$ 는 $\\mathrm{B}$ 에서 $y$ 축에 평행한 직선과 $y=-\\sqrt{-3x}$ 의 교점이므로 $y=-\\sqrt{3}$ 이다. $\\mathrm{D}$ 는 $\\mathrm{C}$ 에서 $x$ 축에 평행한 직선과 $y=-\\sqrt{4x}$ 의 교점이므로 $4x=3$ 에서 $x=\\frac{3}{4}$ 이다.","확인":"3/4","스킬":"C11"},{"제목":"선분 PQ 의 길이 구하기","힌트":"$\\mathrm{Q}$ 는 $\\mathrm{D}$ 에서 $y$ 축에 평행한 직선이 $x$ 축과 만나는 점이다. $\\overline{\\mathrm{PQ}}$ 는?","식":["$\\mathrm{Q}\\left(\\frac{3}{4},\\ 0\\right)$","$\\overline{\\mathrm{PQ}}=2-\\frac{3}{4}=\\frac{5}{4}$"],"설명":"$\\mathrm{Q}$ 의 $x$ 좌표는 $\\mathrm{D}$ 와 같은 $\\frac{3}{4}$ 이고 $\\mathrm{P}$ 의 $x$ 좌표는 $2$ 이므로 $\\overline{\\mathrm{PQ}}=2-\\frac{3}{4}=\\frac{5}{4}$ 이다.","확인":"5/4","스킬":"C11"}]},"ns-2a51ba4f5969":{"길":"곡선을 오른쪽 위로 밀면서 사각형에 처음 닿는 순간과 마지막으로 닿는 순간을 찾는다","단계":[{"제목":"곡선의 움직임 파악하기","힌트":"$k$ 가 커지면 곡선 $y=\\sqrt{-\\frac{3}{2}x+k}$ 는 어느 방향으로 움직이는가?","식":["시작점 $\\left(\\frac{2k}{3},\\,0\\right)$, $x$ 가 커질수록 $y$ 는 감소","$k$ 가 커지면 곡선은 오른쪽 위로 이동"],"설명":"$-\\frac{3}{2}x+k\\ge0$ 에서 $x\\le\\frac{2k}{3}$ 이므로 곡선은 점 $\\left(\\frac{2k}{3},0\\right)$ 에서 왼쪽 위로 뻗는 감소 곡선이다. $k$ 가 커지면 전체가 오른쪽 위로 움직이므로 사각형과 처음 만나는 순간과 마지막으로 만나는 순간이 경계가 된다.","확인":null,"스킬":"G12"},{"제목":"직선 AB 의 식 구하기","힌트":"$\\mathrm{A}(1,2)$, $\\mathrm{B}(3,1)$ 을 지나는 직선의 기울기는?","식":["기울기 $\\frac{1-2}{3-1}=-\\frac{1}{2}$","$y=-\\frac{1}{2}x+\\frac{5}{2}$"],"설명":"$\\mathrm{A}$ 를 지나는 기울기 $-\\frac{1}{2}$ 의 직선은 $y=-\\frac{1}{2}(x-1)+2=-\\frac{1}{2}x+\\frac{5}{2}$ 이다. 곡선은 사각형의 왼쪽 아래 변 $\\mathrm{AB}$ 에 가장 먼저 닿는다.","확인":null,"스킬":"G9"},{"제목":"선분 AB 에 접할 때의 k 구하기","고비":true,"힌트":"$\\sqrt{-\\frac{3}{2}x+k}=-\\frac{1}{2}x+\\frac{5}{2}$ 의 양변을 제곱해 정리한 이차방정식의 판별식은?","식":["$x^2-4x+25-4k=0$","$\\frac{D}{4}=4-(25-4k)=0 \\Rightarrow k=\\frac{21}{4}$"],"설명":"양변을 제곱하면 $-\\frac{3}{2}x+k=\\frac{1}{4}(x^2-10x+25)$ 이고 정리하면 $x^2-4x+25-4k=0$ 이다. 접하므로 중근을 가져 $\\frac{D}{4}=4-(25-4k)=0$ 에서 $k=\\frac{21}{4}$ 이다. 이때 접점은 $x=2$ 로 선분 $\\mathrm{AB}$ ($1\\le x\\le3$) 위에 있다.","확인":"21/4","스킬":"G2"},{"제목":"점 C 를 지날 때의 k 구하기","힌트":"곡선이 $\\mathrm{C}(4,3)$ 을 지나면 $k$ 는?","식":["$\\sqrt{-\\frac{3}{2}\\times4+k}=3 \\Rightarrow k-6=9$","$k=15$"],"설명":"$\\mathrm{C}(4,3)$ 을 대입하면 $\\sqrt{k-6}=3$ 에서 $k=15$ 이다. $k>15$ 이면 $x\\le4$ 에서 곡선이 $y>3$ 이라 사각형의 위쪽을 지나 만나지 않는다.","확인":"15","스킬":"G12"},{"제목":"k 의 범위 정하기","힌트":"처음 만나는 $k$ 와 마지막으로 만나는 $k$ 사이에서는 곡선이 사각형과 만나는가?","식":["$\\frac{21}{4}\\le k\\le15$"],"설명":"$k$ 를 $\\frac{21}{4}$ 에서 $15$ 까지 연속으로 키우면 곡선이 사각형을 지나가므로 이 범위 전체에서 만난다. 그 밖에서는 만나지 않는다.","확인":null,"스킬":"G12"}]},"ns-3598d2b0a57a":{"길":"원과 그래프의 위치를 잡고 아래 반원에 위쪽 두 조각을 대칭으로 합쳐 넓이를 구한다","단계":[{"제목":"원과 그래프의 위치 파악하기","힌트":"$f(1)$, $f(-1)$, $f(0)$ 은 각각 얼마이고 그래프는 원 안과 밖 중 어디에 있는가?","식":["$f(-1)=f(1)=-1,\\ f(0)=0$","원: 중심 $(0,-1)$, 반지름 $1$ — 그래프는 $-1\\le x\\le1$ 에서 원 안쪽"],"설명":"그래프는 $(-1,-1)$, $(0,0)$, $(1,-1)$ 을 지나고 $-1\\le x\\le1$ 에서 원 안쪽에 있다. $0\\le x\\le1$ 에서는 $x^2+(1-\\sqrt{x})^2\\le1$, $-1\\le x<0$ 에서는 $x^2+(1-x^2)^2=1-x^2+x^4\\le1$ 로 확인된다. 영역 $A$ 는 그래프의 아래쪽이다.","확인":null,"스킬":"C10"},{"제목":"아래 반원의 넓이 구하기","힌트":"$y\\le-1$ 인 부분은 원의 어느 부분이고 넓이는?","식":["$y\\le-1$ 인 반원의 넓이 $\\frac{1}{2}\\pi\\times1^2=\\frac{\\pi}{2}$"],"설명":"$-1\\le x\\le1$ 에서 그래프는 $y\\ge-1$ 이므로 원의 아래 반원($y\\le-1$)은 모두 그래프의 아래쪽에 있다. 그 넓이는 $\\frac{\\pi}{2}$ 이다.","확인":null,"스킬":"C10"},{"제목":"y≥-1 부분의 넓이 구하기","고비":true,"힌트":"$x<0$ 쪽 조각을 $y$ 축에 대칭시키면 $0\\le x\\le1$ 에서 어떤 모양이 되는가?","식":["$x<0$ 쪽 조각을 $y$ 축 대칭으로 옮기면 $0\\le x\\le1$ 에서 $y=-x^2$ 과 $y=-1$ 사이의 조각","$x\\ge0$ 쪽 조각을 직선 $y=-x$ 에 대칭시키면 같은 정사각형 안에서 $y=-x^2$ 의 위쪽 조각","두 조각이 정사각형 $0\\le x\\le1,\\ -1\\le y\\le0$ 을 채우므로 넓이의 합은 $1$"],"설명":"$y\\ge-1$ 인 부분의 영역은 $y=-1$ 과 그래프 사이이다. 왼쪽($x<0$) 조각을 $y$ 축에 대칭시키면 정사각형 $0\\le x\\le1,\\ -1\\le y\\le0$ 안에서 $y=-x^2$ 의 아래쪽 조각이 된다. 오른쪽($x\\ge0$) 조각은 $y=-\\sqrt{x}$ 의 아래쪽인데, $y=-\\sqrt{x}$ 는 $y=-x^2$ ($x\\ge0$) 을 직선 $y=-x$ 에 대칭시킨 곡선이어서 이 조각을 옮기면 $y=-x^2$ 의 위쪽 조각이 된다. 두 조각이 정사각형을 채우므로 넓이의 합은 $1$ 이다.","확인":null,"스킬":"S12"},{"제목":"두 넓이의 합 구하기","힌트":"아래 반원의 넓이와 위쪽 조각의 넓이를 더하면?","식":["$\\frac{\\pi}{2}+1$"],"설명":"아래 반원의 넓이 $\\frac{\\pi}{2}$ 와 위쪽 조각의 넓이 $1$ 을 더한 $\\frac{\\pi}{2}+1$ 이 $A\\cap B$ 의 넓이이다.","확인":null,"스킬":"S12"}]},"ns-417090c19c6e":{"길":"시작점 (-2,-1)로 식을 먼저 쓰고 (0,1)을 넣어 a, b, c 를 정한다","단계":[{"제목":"시작점으로 식 세우기","힌트":"시작점 $(-2,-1)$ 에서 근호 안이 $0$ 이 되므로 $ax+b$ 는 어떻게 쓸 수 있는가?","식":["$ax+b=a(x+2),\\ c=-1$","$y=\\sqrt{a(x+2)}-1$"],"설명":"시작점의 $x$ 좌표 $-2$ 에서 근호 안이 $0$ 이므로 $ax+b=a(x+2)$ 이고, 시작점의 $y$ 좌표가 $c$ 이므로 $c=-1$ 이다.","확인":null,"스킬":"G4"},{"제목":"지나는 점으로 a, b 구하기","고비":true,"힌트":"$(0,1)$ 을 대입하면 $a$ 는? 그때 $b$ 는?","식":["$1=\\sqrt{2a}-1 \\Rightarrow a=2$","$b=2a=4$"],"설명":"$(0,1)$ 을 넣으면 $1=\\sqrt{2a}-1$ 이므로 $\\sqrt{2a}=2$, $a=2$ 이다. 따라서 $b=2a=4$ 이다.","확인":"4","스킬":"G1"},{"제목":"a+b+c 구하기","힌트":"$a=2$, $b=4$, $c=-1$ 일 때 $a+b+c$ 는?","식":["$a+b+c=2+4+(-1)=5$"],"설명":"세 상수를 더하면 $5$ 이다.","확인":"5","스킬":"G4"}]},"ns-41727c3d4440":{"길":"두 조각의 치역이 겹치지 않고 빈틈없이 이어지도록 a 를 정한 뒤 f(k)=8 이 속한 조각에서 k 를 푼다","단계":[{"제목":"x>3 조각의 치역 구하기","힌트":"$\\frac{2x+3}{x-2}$ 를 $\\frac{7}{x-2}+2$ 로 고치면 $x>3$ 에서 값은 $2$ 초과 몇 미만인가?","식":["$f(x)=\\frac{7}{x-2}+2\\ (x>3)$","$2<f(x)<9$"],"설명":"$2x+3=2(x-2)+7$ 이므로 $f(x)=\\frac{7}{x-2}+2$ 이다. $x>3$ 에서 $x-2>1$ 이므로 $0<\\frac{7}{x-2}<7$ 이고, $2<f(x)<9$ 이다.","확인":null,"스킬":"T4"},{"제목":"x≤3 조각의 치역으로 a 정하기","고비":true,"힌트":"(가), (나) 를 모두 만족하려면 $x\\le3$ 조각의 치역 $[a,\\infty)$ 은 $(2,9)$ 와 어떻게 이어져야 하는가?","식":["$x\\le3$ 에서 $f(x)=\\sqrt{3-x}+a\\ge a$","$(2,9)\\cup[a,\\infty)=(2,\\infty)$ 이고 겹치지 않으려면 $a=9$"],"설명":"$x\\le3$ 조각의 치역은 $[a,\\infty)$ 이다. (가) 에서 전체 치역이 $y>2$ 이므로 $a>9$ 이면 $[9,a)$ 가 비어 안 되고, $a\\le2$ 이면 $2$ 이하의 값이 나와 안 된다. (나) 에서 일대일이므로 $2<a<9$ 이면 두 조각의 치역이 겹쳐 안 된다. 따라서 $a=9$ 이다.","확인":"9","스킬":"T7"},{"제목":"f(2) 와 f(k) 구하기","힌트":"$f(2)=\\sqrt{3-2}+9$ 이므로 $f(2)f(k)=80$ 에서 $f(k)$ 는?","식":["$f(2)=\\sqrt{1}+9=10$","$f(k)=\\frac{80}{10}=8$"],"설명":"$2\\le3$ 이므로 $x\\le3$ 의 식으로 $f(2)=10$ 이다. $10f(k)=80$ 에서 $f(k)=8$ 이다.","확인":"8","스킬":"T6"},{"제목":"k 의 값 구하기","힌트":"$f(k)=8$ 은 어느 조각의 치역에 속하는가? 그 식으로 $k$ 를 구하면?","식":["$2<8<9$ 이므로 $x>3$ 조각","$\\frac{2k+3}{k-2}=8 \\Rightarrow 2k+3=8k-16,\\ k=\\frac{19}{6}$"],"설명":"$x>3$ 조각의 치역은 $(2,9)$ 이고 $x\\le3$ 조각의 치역은 $[9,\\infty)$ 이므로 $f(k)=8$ 이면 $k>3$ 이다. $\\frac{2k+3}{k-2}=8$ 에서 $2k+3=8k-16$ 이므로 $k=\\frac{19}{6}$ 이고, $\\frac{19}{6}>3$ 을 만족한다.","확인":"19/6","스킬":"T6"}]},"ns-4b1c3a075a4a":{"길":"점근선과 y절편으로 a, b, c 를 읽고 새 그래프의 위치를 따진다","단계":[{"제목":"그림에서 a, b, c 읽기","고비":true,"힌트":"점근선 $x=-c$, $y=a$ 와 $y$절편 $\\frac{b}{c}$ 를 그림에서 읽으면?","식":["$x=-c=1$ 에서 $c=-1$","$y=a=2$","$\\frac{b}{c}=3$ 에서 $b=-3$"],"설명":"$f(x)=\\frac{ax+b}{x+c}$ 의 점근선은 $x=-c$, $y=a$ 이고 $y$절편은 $f(0)=\\frac{b}{c}$ 이다. 그림의 점근선은 $x=1$, $y=2$ 이고 $y$절편은 $3$ 이다.","확인":"-3","스킬":"T4"},{"제목":"시작점과 그래프의 모양","힌트":"$y=\\sqrt{ax-b}+c$ 에 값을 넣고 $\\sqrt{\\ }$ 안을 $x$ 의 계수로 묶으면?","식":["$y=\\sqrt{2x+3}-1=\\sqrt{2\\left(x+\\frac{3}{2}\\right)}-1$","시작점 $\\left(-\\frac{3}{2},\\ -1\\right)$"],"설명":"$y=\\sqrt{2x}$ 를 $x$축 방향으로 $-\\frac{3}{2}$, $y$축 방향으로 $-1$ 만큼 평행이동한 꼴이다. 시작점에서 오른쪽 위로 증가하는 그래프이다.","확인":"-3/2","스킬":"G4"},{"제목":"축과 만나는 점 구하기","힌트":"$y=0$ 일 때의 $x$ 와 $x=0$ 일 때의 $y$ 는?","식":["$y=0$: $\\sqrt{2x+3}=1$ 에서 $x=-1$","$x=0$: $y=\\sqrt{3}-1>0$"],"설명":"$x$절편은 $(-1,\\ 0)$ 이고 $y$절편은 $\\sqrt{3}-1$ 로 양수이다. 시작점에서 $x$절편까지는 $y<0$, 그 뒤로는 $y>0$ 이다.","확인":"-1","스킬":"T4"},{"제목":"지나는 사분면 판정","힌트":"$x<-1$, $-1<x<0$, $x>0$ 일 때 $y$ 의 부호는 각각?","식":["$-\\frac{3}{2}\\le x<-1$: $x<0,\\ y<0$ → 제$3$사분면","$-1<x<0$: $x<0,\\ y>0$ → 제$2$사분면","$x>0$: $x>0,\\ y>0$ → 제$1$사분면"],"설명":"구간마다 $x$, $y$ 의 부호를 따진다. 그래프는 증가하므로 $x>0$ 에서는 $y>\\sqrt{3}-1>0$ 이고, $x>0$ 이면서 $y<0$ 인 부분이 없어 제$4$사분면은 지나지 않는다.","확인":null,"스킬":"G4"}]},"ns-56f1555495bf":{"길":"시작점으로 c 와 -b/a 를 읽고 지나는 점으로 b 를 정한다","단계":[{"제목":"시작점으로 식 읽기","고비":true,"힌트":"$f(x)=-\\sqrt{ax+b}+c$ 를 $x$ 의 계수로 묶으면 시작점의 좌표는?","식":["$f(x)=-\\sqrt{a\\left(x+\\frac{b}{a}\\right)}+c$","시작점 $\\left(-\\frac{b}{a},\\ c\\right)=(-3,\\ 2)$","$-\\frac{b}{a}=-3,\\ c=2$"],"설명":"근호 안을 $a\\left(x+\\frac{b}{a}\\right)$ 꼴로 묶으면 시작점이 $\\left(-\\frac{b}{a},\\ c\\right)$ 임이 보인다. 그림의 시작점은 $(-3,\\ 2)$ 이다.","확인":null,"스킬":"G4"},{"제목":"지나는 점으로 b 구하기","힌트":"그래프가 지나는 점 $(0,\\ -1)$ 을 대입하면 $b$ 는?","식":["$-1=-\\sqrt{b}+2$","$\\sqrt{b}=3$","$b=9$"],"설명":"$y$절편이 $-1$ 이므로 $f(0)=-\\sqrt{b}+2=-1$ 이다. $\\sqrt{b}=3$ 의 양변을 제곱한다.","확인":"9","스킬":"G4"},{"제목":"a 구하기","힌트":"$-\\frac{b}{a}=-3$ 에 $b$ 의 값을 넣으면?","식":["$\\frac{9}{a}=3$","$a=3$"],"설명":"$-\\frac{b}{a}=-3$ 에서 $\\frac{b}{a}=3$ 이고 $b=9$ 이므로 $a=3$ 이다. 따라서 $f(x)=-\\sqrt{3x+9}+2$ 이다.","확인":"3","스킬":"A3"},{"제목":"f(9) 계산","힌트":"$f(x)=-\\sqrt{3x+9}+2$ 에 $x=9$ 를 넣으면?","식":["$f(9)=-\\sqrt{27+9}+2$","$=-6+2=-4$"],"설명":"근호 안이 $36$ 이므로 $\\sqrt{36}=6$ 이다.","확인":"-4","스킬":"G4"}]},"ns-64049806d4d9":{"길":"곡선의 대칭으로 곡선 부분을 상쇄해 다각형 넓이의 차로 바꾼다","단계":[{"제목":"보조점 C, A', B' 잡기","힌트":"직선 $x+2y-15=0$ 이 $y$축과 만나는 점 $\\mathrm{C}$ 의 $y$좌표는?","식":["$x=0$ 을 넣으면 $2y=15$","$\\mathrm{C}\\left(0,\\ \\frac{15}{2}\\right)$","$\\mathrm{A}'(0,\\ 9),\\ \\mathrm{B}'(9,\\ 0)$"],"설명":"$\\mathrm{A}'$ 은 $\\mathrm{A}$ 에서 $y$축에 내린 수선의 발이고 $\\mathrm{B}'$ 은 $\\mathrm{B}$ 에서 $x$축에 내린 수선의 발이다. $\\mathrm{C}$ 는 직선의 $y$절편이다.","확인":"15/2","스킬":"G10"},{"제목":"색칠 영역을 다각형으로 바꾸기","고비":true,"힌트":"$y=\\sqrt{x}$ 와 $y=x^{2}$ 은 어떤 직선에 대해 대칭일까?","식":["$S=$ 사다리꼴 $\\mathrm{OCBB}'$ $-$ 삼각형 $\\mathrm{AA}'\\mathrm{C}$"],"설명":"$y=\\sqrt{x}$ 와 $y=x^{2}\\ (x\\ge0)$ 은 $y=x$ 에 대해 대칭이고 $y=x^{2}$ 은 $y$축에 대해서도 대칭이다. 그래서 $y=\\sqrt{x}$ 아래의 넓이가 $x<0$ 에서 $y=x^{2}$ 위쪽의 넓이와 같아져 곡선 부분이 서로 메워지고 다각형의 넓이만 남는다.","확인":null,"스킬":"T1"},{"제목":"사다리꼴 OCBB' 의 넓이","힌트":"평행한 두 변 $\\overline{\\mathrm{OC}}$, $\\overline{\\mathrm{BB}'}$ 의 길이와 높이는?","식":["$\\overline{\\mathrm{OC}}=\\frac{15}{2},\\ \\overline{\\mathrm{BB}'}=3,\\ \\overline{\\mathrm{OB}'}=9$","$\\frac{1}{2}\\left(\\frac{15}{2}+3\\right)\\times9=\\frac{189}{4}$"],"설명":"두 밑변은 $y$축 위의 $\\overline{\\mathrm{OC}}$ 와 $x=9$ 위의 $\\overline{\\mathrm{BB}'}$ 이고 높이는 $\\overline{\\mathrm{OB}'}=9$ 이다.","확인":"189/4","스킬":"G10"},{"제목":"삼각형 AA'C 의 넓이","힌트":"밑변 $\\overline{\\mathrm{AA}'}$ 의 길이와 높이 $\\overline{\\mathrm{A}'\\mathrm{C}}$ 는?","식":["$\\overline{\\mathrm{AA}'}=3,\\ \\overline{\\mathrm{A}'\\mathrm{C}}=9-\\frac{15}{2}=\\frac{3}{2}$","$\\frac{1}{2}\\times3\\times\\frac{3}{2}=\\frac{9}{4}$"],"설명":"$\\mathrm{A}(-3,\\ 9)$ 이므로 $\\overline{\\mathrm{AA}'}=3$ 이고, $\\overline{\\mathrm{A}'\\mathrm{C}}$ 는 두 점의 $y$좌표의 차이다.","확인":"9/4","스킬":"G10"},{"제목":"색칠 영역의 넓이","힌트":"사다리꼴의 넓이에서 삼각형의 넓이를 빼면?","식":["$S=\\frac{189}{4}-\\frac{9}{4}=45$"],"설명":"앞에서 구한 두 넓이를 빼면 색칠 영역의 넓이이다.","확인":"45","스킬":"G10"}]},"ns-665088310d14":{"길":"a 를 x 로 나타내 두 근호 안을 완전제곱으로 만들어 벗긴다","단계":[{"제목":"a 를 x 로 나타내기","힌트":"$\\sqrt{a}=\\frac{1+x}{2}$ 의 양변을 제곱하면?","식":["$a=\\frac{(1+x)^{2}}{4}$"],"설명":"$-1\\le x\\le1$ 에서 $\\frac{1+x}{2}\\ge0$ 이므로 양변을 제곱해도 된다. 이제 근호 안이 모두 $x$ 만의 식이 된다.","확인":null,"스킬":"A6"},{"제목":"√(a-x) 의 근호 벗기기","고비":true,"힌트":"$a-x$ 를 통분해 하나의 완전제곱식으로 쓰면?","식":["$a-x=\\frac{(1+x)^{2}-4x}{4}=\\frac{(x-1)^{2}}{4}$","$\\sqrt{a-x}=\\frac{|x-1|}{2}=\\frac{1-x}{2}$"],"설명":"$\\sqrt{A^{2}}=|A|$ 이다. $-1\\le x\\le1$ 에서 $x-1\\le0$ 이므로 $|x-1|=1-x$ 이다.","확인":null,"스킬":"A6"},{"제목":"√(a+x+2) 의 근호 벗기기","힌트":"$a+x+2$ 도 통분해 완전제곱식으로 쓰면?","식":["$a+x+2=\\frac{(1+x)^{2}+4x+8}{4}=\\frac{(x+3)^{2}}{4}$","$\\sqrt{a+x+2}=\\frac{x+3}{2}$"],"설명":"$x\\ge-1$ 이므로 $x+3>0$ 이고 절댓값 없이 $\\frac{x+3}{2}$ 이다.","확인":null,"스킬":"T3"},{"제목":"주어진 식을 x 로 정리","힌트":"두 결과를 빼면 $x$ 의 일차식이 되는데 어떤 꼴일까?","식":["$\\frac{1-x}{2}-\\frac{x+3}{2}=\\frac{-2x-2}{2}=-x-1$"],"설명":"분모가 같으므로 분자끼리 뺀다.","확인":null,"스킬":"A6"},{"제목":"범위에서 최댓값 찾기","힌트":"$-x-1$ 은 $x$ 가 커질 때 커질까 작아질까?","식":["$-x-1$ 은 $x$ 가 작을수록 크다","$x=-1$ 일 때 $-(-1)-1=0$"],"설명":"기울기가 $-1$ 인 일차식이므로 $-1\\le x\\le1$ 에서 $x=-1$ 일 때 최대이다.","확인":"0","스킬":"T3"}]},"ns-706742f76034":{"길":"역함수의 성질로 식을 줄여 g 의 역함수 값 하나만 구한다","단계":[{"제목":"합성식 간단히 하기","고비":true,"힌트":"$(g\\circ f)^{-1}$ 을 $f^{-1}$, $g^{-1}$ 로 풀어 쓰면?","식":["$(g\\circ f)^{-1}=f^{-1}\\circ g^{-1}$","$f\\circ f^{-1}\\circ g^{-1}\\circ f=g^{-1}\\circ f$"],"설명":"합성함수의 역함수는 순서가 바뀐 역함수들의 합성이다. $f\\circ f^{-1}$ 은 항등함수이므로 $g^{-1}\\circ f$ 만 남는다.","확인":null,"스킬":"T6"},{"제목":"f(2) 계산","힌트":"$f(x)=\\frac{x+2}{x-1}$ 에 $x=2$ 를 넣으면?","식":["$f(2)=\\frac{2+2}{2-1}=4$"],"설명":"구하는 값은 $g^{-1}(f(2))$ 이므로 먼저 $f(2)$ 를 구한다.","확인":"4","스킬":"T6"},{"제목":"g 의 역함수 값 구하기","힌트":"$g^{-1}(4)=t$ 이면 $g(t)$ 는 얼마일까?","식":["$g(t)=4$ 에서 $\\sqrt{2t-2}+1=4,\\ \\sqrt{2t-2}=3$","$2t-2=9$","$t=\\frac{11}{2}$"],"설명":"$g^{-1}(4)=t$ 는 $g(t)=4$ 와 같다. 정의역 $t>1$ 을 만족하는지 확인하면 $\\frac{11}{2}>1$ 이다.","확인":"11/2","스킬":"T1"}]},"ns-79e4fc3251c9":{"길":"양변을 반원과 정점을 지나는 직선으로 보고 교점이 하나인 경계를 찾는다","단계":[{"제목":"양변을 그래프로 바꾸기","힌트":"$y=1-\\sqrt{1-x^{2}}$ 을 정리하면 어떤 도형의 일부일까?","식":["$y=1-\\sqrt{1-x^{2}}\\iff x^{2}+(y-1)^{2}=1,\\ y\\le1$","$y=k(x+2)$ 는 $k$ 에 관계없이 점 $(-2,\\ 0)$ 을 지난다"],"설명":"$y-1=-\\sqrt{1-x^{2}}\\le0$ 이므로 중심 $(0,\\ 1)$, 반지름 $1$ 인 원의 아래쪽 반원이다. 끝점은 $(-1,\\ 1)$, $(1,\\ 1)$ 이다. 직선은 정점 $(-2,\\ 0)$ 을 중심으로 기울기 $k$ 만큼 돌아간다.","확인":null,"스킬":"G1"},{"제목":"오른쪽 끝점을 지나는 직선","고비":true,"힌트":"직선이 반원의 오른쪽 끝점 $(1,\\ 1)$ 을 지날 때 $k$ 는?","식":["$1=k(1+2)$","$k=\\frac{1}{3}$"],"설명":"$k=\\frac{1}{3}$ 일 때 직선은 반원 위의 두 점 $\\left(-\\frac{4}{5},\\ \\frac{2}{5}\\right)$, $(1,\\ 1)$ 에서 만나 교점이 $2$ 개이다. $0<k\\le\\frac{1}{3}$ 에서는 교점이 $2$ 개이다.","확인":"1/3","스킬":"G2"},{"제목":"왼쪽 끝점을 지나는 직선","힌트":"직선이 반원의 왼쪽 끝점 $(-1,\\ 1)$ 을 지날 때 $k$ 는?","식":["$1=k(-1+2)$","$k=1$"],"설명":"$k$ 가 $\\frac{1}{3}$ 보다 커지면 오른쪽 끝점이 직선 아래로 밀려나 교점이 하나만 남는다. 이 상태가 $(-1,\\ 1)$ 을 지날 때까지 이어지고, 그보다 크면 만나지 않는다.","확인":null,"스킬":"G1"},{"제목":"교점이 하나인 범위와 최댓값","힌트":"교점이 정확히 하나인 $k$ 의 범위에서 가장 큰 값은?","식":["$k=0$ (꼭짓점 $(0,\\ 0)$ 에서 접함) 또는 $\\frac{1}{3}<k\\le1$","최댓값 $1$"],"설명":"$k=0$ 이면 직선 $y=0$ 이 반원의 꼭짓점에서 접해 교점이 하나이다. $\\frac{1}{3}<k\\le1$ 에서도 교점이 하나이므로 가능한 $k$ 중 가장 큰 값은 $1$ 이다.","확인":"1","스킬":"G2"}]},"ns-94e47cc7e0d3":{"길":"A 는 C 를 왼쪽·위로 옮긴 점이라 그래프도 같은 만큼 평행이동한다","단계":[{"제목":"A 와 C 의 좌표 관계","고비":true,"힌트":"그림에서 $\\mathrm{A}$ 는 $\\mathrm{C}$ 에서 어느 방향으로 얼마만큼 떨어져 있을까?","식":["$\\mathrm{C}(t,\\ \\sqrt{t})$","$\\mathrm{A}(t-1,\\ \\sqrt{t}+1)$"],"설명":"한 변의 길이가 $1$ 이고 $\\overline{\\mathrm{BC}}$ 가 가로, $\\overline{\\mathrm{AB}}$ 가 세로이므로 $\\mathrm{A}$ 는 $\\mathrm{C}$ 에서 왼쪽으로 $1$, 위로 $1$ 만큼 떨어진 점이다.","확인":null,"스킬":"G4"},{"제목":"A 가 그리는 도형의 방정식","힌트":"$x=t-1$, $y=\\sqrt{t}+1$ 에서 $t$ 를 없애면?","식":["$t=x+1$","$y=\\sqrt{x+1}+1$"],"설명":"$x$ 좌표에서 $t=x+1$ 이므로 $y$ 좌표에 대입한다. $y=\\sqrt{x}$ 를 $x$축 방향으로 $-1$, $y$축 방향으로 $1$ 만큼 평행이동한 그래프이다.","확인":null,"스킬":"G4"},{"제목":"a+b+c 계산","힌트":"$y=\\sqrt{ax+b}+c$ 와 비교해 $a$, $b$, $c$ 를 읽으면?","식":["$a=1,\\ b=1,\\ c=1$","$a+b+c=3$"],"설명":"$\\sqrt{x+1}+1$ 과 $\\sqrt{ax+b}+c$ 의 대응하는 계수를 비교한다.","확인":"3","스킬":"A3"}]},"ns-98f314a78cab":{"길":"절댓값 식을 구간별로 벗겨 수평선과 반직선으로 놓고 교점 수를 센다","단계":[{"제목":"절댓값 벗겨 그래프 파악","힌트":"$|x-k|$ 를 $x<k$, $x\\ge k$ 로 나눠 벗기면?","식":["$x<k$: $y=x+(k-x)=k$","$x\\ge k$: $y=x+(x-k)=2x-k$"],"설명":"$y=x+|x-k|$ 는 $x<k$ 에서 수평선 $y=k$ 이고, $x\\ge k$ 에서는 시작점이 $(k,\\ k)$ 이고 기울기가 $2$ 인 반직선이다.","확인":null,"스킬":"G5"},{"제목":"오른쪽 경계 b 구하기","힌트":"반직선의 시작점 $(k,\\ k)$ 가 곡선 위에 놓이는 $k$ 는?","식":["$k=\\sqrt{\\frac{4k+4}{3}}$","$3k^{2}-4k-4=0,\\ (3k+2)(k-2)=0$","$k\\ge0$ 이므로 $k=2$"],"설명":"$0\\le k<2$ 이면 수평선 $y=k$ 가 곡선과 한 번 만나고, 시작점이 곡선 아래에 있어 반직선도 한 번 만나므로 교점이 $2$ 개이다. $k=2$ 부터는 수평선과 만나지 않아 교점이 줄어든다.","확인":"2","스킬":"G1"},{"제목":"왼쪽 경계 a 구하기: 접하는 경우","고비":true,"힌트":"$k<0$ 이면 곡선과 만나는 것은 반직선뿐이다. 접하려면 판별식은?","식":["$(2x-k)^{2}=\\frac{4x+4}{3},\\ 12x^{2}-(12k+4)x+3k^{2}-4=0$","$D=(12k+4)^{2}-48(3k^{2}-4)=96k+208=0$","$k=-\\frac{13}{6}$"],"설명":"$k<0$ 이면 수평선 $y=k$ 는 $y\\ge0$ 인 곡선과 만나지 않는다. 반직선이 시작점 $(-1,\\ 0)$ 을 지날 때가 $k=-2$ 이고, $k$ 가 $-2$ 에서 작아지면 교점이 $2$ 개가 되다가 접할 때 $1$ 개가 된다. 접점은 $x=-\\frac{11}{12}$ 로 조건에 맞는다.","확인":"-13/6","스킬":"G2"},{"제목":"a+b 계산","힌트":"$-\\frac{13}{6}<k\\le-2$ 또는 $0\\le k<2$ 에서 $a$, $b$ 는?","식":["$a=-\\frac{13}{6},\\ b=2$","$a+b=-\\frac{13}{6}+2=-\\frac{1}{6}$"],"설명":"교점이 $2$ 개인 범위의 양 끝에서 $a$ 와 $b$ 가 정해진다.","확인":"-1/6","스킬":"G1"}]},"ns-998f4e02ac73":{"길":"역함수 그래프의 점을 뒤집어 f 의 시작점과 지나는 점으로 쓴다","단계":[{"제목":"역함수 그래프의 점을 f 의 점으로","고비":true,"힌트":"점 $(p,\\ q)$ 가 $y=f^{-1}(x)$ 위에 있으면 $y=f(x)$ 위에 있는 점은?","식":["$f^{-1}$ 의 시작점 $(4,\\ 6)$ → $f$ 의 시작점 $(6,\\ 4)$","$f^{-1}(5)=0$ → $f(0)=5$"],"설명":"역함수의 그래프는 $y=x$ 에 대칭이므로 $x$ 좌표와 $y$ 좌표를 바꾼다. 그림에서 $y=f^{-1}(x)$ 는 $x=5$ 에서 $x$축과 만난다.","확인":null,"스킬":"T1"},{"제목":"a 구하기","힌트":"$f(x)=\\sqrt{a(x-6)}+4$ 에 $f(0)=5$ 를 넣으면?","식":["$\\sqrt{-6a}+4=5$","$-6a=1$","$a=-\\frac{1}{6}$"],"설명":"시작점이 $(6,\\ 4)$ 이므로 $f(x)=\\sqrt{a(x-6)}+4$ 로 놓는다. $f(0)=5$ 를 넣고 양변을 제곱한다.","확인":"-1/6","스킬":"G4"},{"제목":"6a+b+c 계산","힌트":"$f(x)=\\sqrt{ax-6a}+4$ 와 $\\sqrt{ax+b}+c$ 를 비교하면 $b$, $c$ 는?","식":["$b=-6a=1,\\ c=4$","$6a+b+c=-1+1+4=4$"],"설명":"$a(x-6)=ax-6a$ 이므로 $b=-6a$ 이다.","확인":"4","스킬":"A3"}]},"ns-b83ca141c6f9":{"길":"교점이 y=x 위임을 이용하고 시작점이 y=x 위일 때 길이가 최대임을 쓴다","단계":[{"제목":"교점이 놓이는 직선 찾기","힌트":"증가함수 $f$ 와 그 역함수의 교점은 어떤 직선 위에 있을까?","식":["$f(x)=f^{-1}(x)\\iff f(x)=x$"],"설명":"$f$ 가 증가함수이면 $f$ 와 $f^{-1}$ 의 교점은 모두 $y=x$ 위에 있다. 따라서 $y=f(x)$ 와 $y=x$ 의 교점을 구하면 된다.","확인":null,"스킬":"T1"},{"제목":"선분 AB 가 가장 길 때의 위치","고비":true,"힌트":"교점 두 개를 유지하면서 $\\mathrm{AB}$ 가 가장 길려면 시작점 $(3,\\ k)$ 는 어디에 있어야 할까?","식":["시작점 $(3,\\ k)$ 가 $y=x$ 위에 있을 때","$k=3$"],"설명":"시작점이 $y=x$ 아래에 있어야 교점이 $2$ 개이고, $k$ 가 클수록 $\\mathrm{A}$ 가 시작점 쪽으로 이동해 $\\overline{\\mathrm{AB}}$ 가 길어진다. 시작점이 $y=x$ 위에 놓일 때가 한계이므로 $\\mathrm{A}$ 가 시작점과 일치하는 $k=3$ 에서 최대이다.","확인":"3","스킬":"G1"},{"제목":"다른 교점 구하기","힌트":"$\\sqrt{2x-6}+3=x$ 를 제곱해 풀면?","식":["$2x-6=(x-3)^{2}$","$x^{2}-8x+15=0,\\ (x-3)(x-5)=0$","$x=3$ 또는 $x=5$"],"설명":"$x=3$ 은 시작점이고 다른 교점은 $x=5$ 이다. $y=x$ 위이므로 $(5,\\ 5)$ 이다.","확인":"5","스킬":"G1"},{"제목":"선분 AB 의 길이","힌트":"$\\mathrm{A}(3,\\ 3)$, $\\mathrm{B}(5,\\ 5)$ 사이의 거리는?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(5-3)^{2}+(5-3)^{2}}=\\sqrt{8}=2\\sqrt{2}$"],"설명":"두 점 모두 $y=x$ 위에 있으므로 $x$ 좌표의 차 $2$ 에 $\\sqrt{2}$ 를 곱한 값과 같다.","확인":null,"스킬":"S3"}]},"ns-c6b0e02eaa99":{"길":"그림의 시작점과 뻗는 방향으로 a, b, c 의 부호를 읽어 새 그래프를 그린다","단계":[{"제목":"그림에서 a, b, c 의 부호 읽기","힌트":"시작점 $(-b,\\ c)$ 가 그림의 $(1,\\ 1)$ 이고 그래프가 왼쪽으로 뻗으면 $b$, $c$, $a$ 는?","식":["시작점 $(-b,\\ c)=(1,\\ 1)$ 에서 $b=-1,\\ c=1$","시작점에서 왼쪽으로 뻗으므로 $a<0$"],"설명":"$y=\\sqrt{a(x+b)}+c$ 의 시작점은 $(-b,\\ c)$ 이다. $a>0$ 이면 오른쪽으로, $a<0$ 이면 왼쪽으로 뻗는다.","확인":"-1","스킬":"G4"},{"제목":"새 그래프의 시작점과 방향","고비":true,"힌트":"$y=\\sqrt{c(x+b)}+a$ 의 시작점의 좌표와 뻗는 방향은?","식":["시작점 $(-b,\\ a)$: $-b>0,\\ a<0$ 이므로 제$4$사분면","$c>0$ 이므로 오른쪽 위로 뻗는다"],"설명":"시작점의 좌표가 $(-b,\\ a)$ 이므로 앞에서 읽은 부호를 넣는다. 근호 안 $x$ 의 계수가 $c>0$ 이므로 오른쪽으로 증가하는 그래프이다.","확인":null,"스킬":"N5"},{"제목":"지나는 사분면 판정","힌트":"정의역이 $x\\ge-b$ 이고 $-b>0$ 이면 어느 사분면에는 갈 수 없을까?","식":["$x\\ge-b>0$ 이므로 제$2$, $3$사분면은 지나지 않는다","제$4$사분면에서 시작해 $x$축을 지나 제$1$사분면으로 간다"],"설명":"정의역의 모든 $x$ 가 양수이므로 $x<0$ 인 사분면은 지날 수 없다. 시작점의 $y$ 좌표가 음수이고 그래프가 증가하므로 $x$축을 지나 $y>0$ 인 부분으로 이어진다.","확인":null,"스킬":"G4"}]},"ns-c6e661884ecf":{"길":"B 의 대칭점으로 C 를 잡고 A 가 y=x 위임을 이용해 좌표를 구한다","단계":[{"제목":"C 의 좌표와 BC 의 길이","힌트":"$\\mathrm{B}$ 가 $y=f(x)$ 위이면 $y=f^{-1}(x)$ 위에서 $\\mathrm{B}$ 와 짝이 되는 점은?","식":["$\\mathrm{B}(-1,\\ 7)$ 의 $y=x$ 대칭점 $\\mathrm{C}(7,\\ -1)$","$\\overline{\\mathrm{BC}}=\\sqrt{8^{2}+8^{2}}=8\\sqrt{2}$"],"설명":"$y=f(x)$ 위의 점 $(p,\\ q)$ 에 대응하는 $y=f^{-1}(x)$ 위의 점은 $(q,\\ p)$ 이므로 $\\mathrm{C}$ 는 $\\mathrm{B}$ 의 $y=x$ 대칭점이다.","확인":null,"스킬":"T1"},{"제목":"BC 를 밑변으로 한 높이","힌트":"넓이가 $64$ 이고 밑변이 $\\overline{\\mathrm{BC}}$ 일 때 높이 $h$ 는?","식":["$\\frac{1}{2}\\times8\\sqrt{2}\\times h=64$","$h=8\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$ 이므로 $\\mathrm{A}$ 는 $\\overline{\\mathrm{BC}}$ 의 수직이등분선인 $y=x$ 위에 있고, $\\mathrm{A}$ 에서 $\\overline{\\mathrm{BC}}$ 까지의 거리가 높이 $h$ 이다.","확인":null,"스킬":"S8"},{"제목":"A 의 좌표 구하기","고비":true,"힌트":"$\\mathrm{A}(k,\\ k)$ 로 놓고 $\\overline{\\mathrm{AB}}^{2}$ 를 두 가지로 나타내면?","식":["$\\overline{\\mathrm{AB}}^{2}=(k+1)^{2}+(k-7)^{2}=2k^{2}-12k+50$","$\\overline{\\mathrm{AB}}^{2}=h^{2}+\\left(4\\sqrt{2}\\right)^{2}=160$","$k^{2}-6k-55=0,\\ (k+5)(k-11)=0$ 에서 $k=11$"],"설명":"$\\overline{\\mathrm{BC}}$ 의 중점과 $\\mathrm{A}$ 를 이은 선분이 높이이므로 피타고라스 정리로 $\\overline{\\mathrm{AB}}^{2}$ 를 구한다. $\\mathrm{A}$ 의 $x$ 좌표가 $\\mathrm{C}$ 의 $x$ 좌표 $7$ 보다 크므로 $k=11$ 이다.","확인":"11","스킬":"S3"},{"제목":"연립해 a, b 구하기","힌트":"$f(x)=a\\sqrt{x+5}+b$ 가 $(-1,\\ 7)$ 과 $(11,\\ 11)$ 을 지난다는 조건을 식으로 쓰면?","식":["$2a+b=7$","$4a+b=11$","$a=2,\\ b=3$"],"설명":"$f(-1)=a\\sqrt{4}+b$, $f(11)=a\\sqrt{16}+b$ 이다. 두 식을 빼면 $2a=4$ 이다.","확인":"2","스킬":"A10"},{"제목":"ab 계산","힌트":"구한 $a$, $b$ 를 곱하면?","식":["$ab=2\\times3=6$"],"설명":"앞에서 구한 값을 곱한다.","확인":"6","스킬":"A10"}]},"ns-c8c2a8ba4eea":{"길":"(1,3) 에서 만나면 f(1)=3 이고 역함수 관계로 f(3)=1 도 성립한다","단계":[{"제목":"교점 조건을 f 의 식으로","고비":true,"힌트":"$g(1)=3$ 이면 $f$ 에 대해 어떤 등식이 성립할까?","식":["$f(1)=3$","$g(1)=3\\iff f(3)=1$"],"설명":"점 $(1,\\ 3)$ 이 $y=f(x)$ 위에 있으므로 $f(1)=3$ 이다. $y=g(x)$ 위에도 있으면 $g(1)=3$ 이고, $g$ 가 $f$ 의 역함수이므로 $f(3)=1$ 이다.","확인":null,"스킬":"T1"},{"제목":"a, b 구하기","힌트":"$f(1)=3$, $f(3)=1$ 을 $\\sqrt{ax+b}+1$ 에 넣으면?","식":["$\\sqrt{a+b}=2,\\ \\sqrt{3a+b}=0$","$a+b=4,\\ 3a+b=0$","$a=-2,\\ b=6$"],"설명":"두 식을 제곱해 연립한다. 변끼리 빼면 $2a=-4$ 이다.","확인":"-2","스킬":"A10"},{"제목":"g(5) 구하기","힌트":"$g(5)=k$ 라 하면 $f(k)$ 는 얼마일까?","식":["$f(k)=5$ 에서 $\\sqrt{-2k+6}+1=5$","$-2k+6=16$","$k=-5$"],"설명":"$g(5)=k$ 는 $f(k)=5$ 와 같다. $\\sqrt{-2k+6}=4$ 의 양변을 제곱한다.","확인":"-5","스킬":"T1"}]},"ns-d5c5d5b4ca21":{"길":"조건식을 원으로 바꾸고 치역 조건이 만드는 호 위에서 p+q 의 범위를 따진다","단계":[{"제목":"그림에서 a, b, c 구하기","힌트":"끝점 $\\left(\\frac{b}{a},\\ c\\right)$ 와 $y$절편 $\\sqrt{b}+c$ 를 그림에서 읽으면?","식":["끝점 $\\left(\\frac{b}{a},\\ c\\right)=(2,\\ 1)$ 에서 $c=1,\\ \\frac{b}{a}=2$","$y$절편: $\\sqrt{b}+1=3$ 에서 $b=4$","$a=2$"],"설명":"$y=\\sqrt{-a\\left(x-\\frac{b}{a}\\right)}+c$ 이므로 끝점이 $\\left(\\frac{b}{a},\\ c\\right)$ 이다. $x=0$ 일 때 $y=\\sqrt{b}+c$ 가 $3$ 이다.","확인":"4","스킬":"G4"},{"제목":"조건식을 원의 방정식으로 정리","힌트":"$2ac$ 와 $b$ 의 값을 넣으면 $\\frac{p^{2}}{2ac}+\\frac{q^{2}}{b}=1$ 은 어떤 식이 될까?","식":["$2ac=4,\\ b=4$","$\\frac{p^{2}}{4}+\\frac{q^{2}}{4}=1,\\ p^{2}+q^{2}=4$","$X=(-\\infty,\\ 2],\\ Y=[1,\\ \\infty)$ 이므로 $q\\ge1$"],"설명":"$(p,\\ q)$ 는 원점이 중심이고 반지름이 $2$ 인 원 위의 점이다. 함수의 치역이 $y\\ge1$ 이므로 $q\\ge1$ 이다. $p\\le2$ 는 원 위의 점이면 항상 성립한다.","확인":null,"스킬":"T3"},{"제목":"점 (p, q) 가 움직이는 호의 범위","고비":true,"힌트":"$p^{2}+q^{2}=4$ 에서 $q\\ge1$ 이면 $p$ 의 범위는?","식":["$q=1$ 일 때 $p^{2}=3$","끝점 $\\left(-\\sqrt{3},\\ 1\\right)$, $\\left(\\sqrt{3},\\ 1\\right)$","$-\\sqrt{3}\\le p\\le\\sqrt{3}$"],"설명":"원 전체가 아니라 $q\\ge1$ 인 윗부분의 호만 가능하다. 호의 양 끝은 $q=1$ 일 때의 두 점이다.","확인":null,"스킬":"G2"},{"제목":"최댓값 M 구하기","힌트":"직선 $p+q=k$ 가 호에 접할 때의 $k$ 는? 원점과 직선 사이의 거리는 얼마일까?","식":["$\\frac{|k|}{\\sqrt{2}}=2$ 에서 $k=2\\sqrt{2}$","접점 $\\left(\\sqrt{2},\\ \\sqrt{2}\\right)$ 는 $q\\ge1$ 이므로 호 위의 점","$M^{2}=8$"],"설명":"직선 $p+q=k$ 가 원에 접할 때 $k$ 가 가장 크다. 접점의 $q$ 좌표 $\\sqrt{2}$ 가 $1$ 이상이므로 호 위에 있어 $M=2\\sqrt{2}$ 가 가능하다.","확인":"8","스킬":"G2"},{"제목":"최솟값 m 구하기","힌트":"$p+q$ 는 접점에서 양쪽으로 갈수록 작아진다. 호의 두 끝점에서의 값은?","식":["왼쪽 끝점 $\\left(-\\sqrt{3},\\ 1\\right)$: $p+q=1-\\sqrt{3}$","오른쪽 끝점 $\\left(\\sqrt{3},\\ 1\\right)$: $p+q=1+\\sqrt{3}$","$m=1-\\sqrt{3}$"],"설명":"$p+q$ 는 접점에서 최대이고 양쪽으로 갈수록 작아지므로 최솟값은 호의 끝점에서 나온다. 두 끝점 중 작은 값이 $m$ 이다.","확인":null,"스킬":"T3"},{"제목":"M²+m² 계산","힌트":"$m^{2}=\\left(1-\\sqrt{3}\\right)^{2}$ 을 전개하고 $M^{2}$ 과 더하면?","식":["$m^{2}=1-2\\sqrt{3}+3=4-2\\sqrt{3}$","$M^{2}+m^{2}=8+4-2\\sqrt{3}=12-2\\sqrt{3}$"],"설명":"$M^{2}=8$ 이고 $m^{2}=4-2\\sqrt{3}$ 이므로 더한다.","확인":null,"스킬":"T3"}]},"ns-da8948134779":{"길":"f 와 g 가 역함수임을 이용해 A, C 를 y=x 로 짠 뒤 거리로 넓이를 구한다","단계":[{"제목":"점 A 구하기","힌트":"$g$ 가 $f$ 의 역함수라면 교점 $\\mathrm{A}$ 는 어떤 직선 위에 있을까?","식":["$y=\\sqrt{3x+4}$ 에서 $x=\\frac{y^{2}-4}{3}$ 이므로 $g$ 는 $f$ 의 역함수","$\\sqrt{3x+4}=x,\\ x^{2}-3x-4=0$","$x=4,\\ \\mathrm{A}(4,\\ 4)$"],"설명":"$f$ 는 증가함수이므로 $f$ 와 그 역함수 $g$ 의 교점은 $y=x$ 위에 있다. 제곱해 푼 근 가운데 $x\\ge0$ 인 것을 택한다.","확인":"4","스킬":"T1"},{"제목":"밑변 BC 의 길이","고비":true,"힌트":"기울기가 $-1$ 인 직선과 $y=x$ 는 어떤 관계이고, $\\mathrm{C}$ 는 $\\mathrm{B}$ 의 어느 점일까?","식":["$l$ 의 기울기 $-1$ 은 $y=x$ 에 수직","$\\mathrm{B}$ 와 $y=x$ 사이 거리 $\\frac{\\left|\\frac{5}{3}-3\\right|}{\\sqrt{2}}=\\frac{4}{3\\sqrt{2}}$","$\\overline{\\mathrm{BC}}=2\\times\\frac{4}{3\\sqrt{2}}=\\frac{8}{3\\sqrt{2}}$"],"설명":"$f$ 와 $g$ 의 그래프는 $y=x$ 에 대칭이므로 $\\mathrm{B}$ 의 대칭점은 $g$ 위에 있다. $l$ 이 $y=x$ 에 수직이라 이 대칭점이 $l$ 위에도 있으므로 $\\mathrm{C}$ 이고, $\\overline{\\mathrm{BC}}$ 는 $\\mathrm{B}$ 에서 $y=x$ 까지 거리의 $2$ 배이다.","확인":null,"스킬":"S4"},{"제목":"높이: A 에서 직선 l 까지의 거리","힌트":"$l$ 의 방정식을 구하고 점과 직선 사이의 거리 공식을 쓰면?","식":["$l$: $y-3=-\\left(x-\\frac{5}{3}\\right)$, 즉 $x+y-\\frac{14}{3}=0$","$\\frac{\\left|4+4-\\frac{14}{3}\\right|}{\\sqrt{2}}=\\frac{10}{3\\sqrt{2}}$"],"설명":"점 $\\mathrm{B}\\left(\\frac{5}{3},\\ 3\\right)$ 을 지나는 기울기 $-1$ 인 직선이다. $\\mathrm{A}(4,\\ 4)$ 를 대입해 거리를 구한다.","확인":null,"스킬":"S4"},{"제목":"삼각형 ABC 의 넓이","힌트":"밑변 $\\overline{\\mathrm{BC}}$ 와 높이로 넓이를 구하면?","식":["$\\frac{1}{2}\\times\\frac{10}{3\\sqrt{2}}\\times\\frac{8}{3\\sqrt{2}}=\\frac{20}{9}$"],"설명":"분모의 $\\sqrt{2}\\times\\sqrt{2}=2$ 이므로 $\\frac{1}{2}\\times\\frac{80}{18}=\\frac{20}{9}$ 이다.","확인":"20/9","스킬":"S8"}]},"ns-f2d0a0d6a638":{"길":"PQ+PR 을 y 하나의 이차식으로 쓰고 꼭짓점이 범위 안일 때의 최댓값을 쓴다","단계":[{"제목":"PQ+PR 를 한 문자로 나타내기","힌트":"$\\mathrm{P}(x,\\ y)$ 라 할 때 $\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{PR}}$ 을 좌표로 쓰고 $x$ 를 $y$ 로 바꾸면?","식":["$\\overline{\\mathrm{PQ}}=y,\\ \\overline{\\mathrm{PR}}=x$","$y=\\sqrt{16-ax}$ 에서 $x=\\frac{16-y^{2}}{a}$","$\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{PR}}=y+\\frac{16-y^{2}}{a}\\ (0<y<4)$"],"설명":"제$1$사분면의 점이므로 $x>0$ 이고 이는 $y<4$ 와 같다. 따라서 $0<y<4$ 이다.","확인":null,"스킬":"A6"},{"제목":"이차식의 꼭짓점과 최댓값","고비":true,"힌트":"$y+\\frac{16-y^{2}}{a}$ 를 $\\left(y-\\square\\right)^{2}$ 꼴로 고치면?","식":["$-\\frac{1}{a}\\left(y-\\frac{a}{2}\\right)^{2}+\\frac{a}{4}+\\frac{16}{a}$","꼭짓점 $y=\\frac{a}{2}$ 가 $0<y<4$ 안이려면 $0<a<8$","최댓값 $\\frac{a}{4}+\\frac{16}{a}$"],"설명":"$y^{2}$ 의 계수가 음수이므로 위로 볼록한 이차식이다. 꼭짓점이 범위 안에 있어야 꼭짓점에서 최댓값을 갖는다.","확인":null,"스킬":"A6"},{"제목":"최댓값 5 로 a 구하기","힌트":"$\\frac{a}{4}+\\frac{16}{a}=5$ 의 양변에 $4a$ 를 곱하면?","식":["$a^{2}+64=20a,\\ a^{2}-20a+64=0$","$(a-4)(a-16)=0$","$0<a<8$ 이므로 $a=4$"],"설명":"$a=16$ 은 $a<8$ 을 만족하지 않아 버린다.","확인":"4","스킬":"A6"}]},"ns-fea0857f9a61":{"길":"선회각과 g 가 같아 V 의 비는 반경비의 제곱근이 된다","단계":[{"제목":"속도의 비를 반경의 비로 바꾸기","고비":true,"힌트":"$V_{1}$, $V_{2}$ 의 식에서 같은 값은 무엇이고 비를 만들면 어떻게 될까?","식":["$\\frac{V_{1}}{V_{2}}=\\frac{\\sqrt{R_{1}g\\tan30^{\\circ}}}{\\sqrt{R_{2}g\\tan30^{\\circ}}}$","$=\\sqrt{\\frac{R_{1}}{R_{2}}}$"],"설명":"두 경우 모두 선회각이 $30^{\\circ}$ 이고 $g$ 도 같으므로 $g\\tan30^{\\circ}$ 가 약분된다.","확인":null,"스킬":"C7"},{"제목":"반경비를 대입해 계산","힌트":"$R_{1}:R_{2}=9:16$ 이면 $\\frac{R_{1}}{R_{2}}$ 는?","식":["$\\frac{R_{1}}{R_{2}}=\\frac{9}{16}$","$\\frac{V_{1}}{V_{2}}=\\sqrt{\\frac{9}{16}}=\\frac{3}{4}$"],"설명":"$9$ 와 $16$ 은 각각 $3^{2}$, $4^{2}$ 이므로 제곱근이 바로 나온다.","확인":"3/4","스킬":"C7"}]}});
